export const GEO_IND_001_NATIVE_HI_PA_V1: IndianGeoNativeRecordsV1 = {"GEO-IND-001-CP001-Q001":{"h":"143d93b2","hi":["विनिर्माण क्या है?",["बिना प्रसंस्करण के खनिजों का निष्कर्षण","कच्चे माल को संसाधित करके अधिक मूल्यवान वस्तुओं का उत्पादन","केवल तैयार माल का परिवहन","केवल आयातित उत्पादों की खुदरा बिक्री"],"विनिर्माण कच्चे माल को अधिक उपयोगिता और मूल्य वाली वस्तुओं में बदलता है। इसलिए यह साधारण निष्कर्षण या व्यापार नहीं, बल्कि एक द्वितीयक आर्थिक क्रिया है।"],"pa":["ਨਿਰਮਾਣ ਕੀ ਹੈ?",["ਬਿਨਾਂ ਪ੍ਰੋਸੈਸਿੰਗ ਦੇ ਖਣਿਜ ਕੱਢਣਾ","ਕੱਚੇ ਮਾਲ ਨੂੰ ਪ੍ਰੋਸੈਸ ਕਰਕੇ ਵਧੇਰੇ ਕੀਮਤੀ ਵਸਤਾਂ ਦਾ ਉਤਪਾਦਨ","ਸਿਰਫ਼ ਤਿਆਰ ਮਾਲ ਦੀ ਢੋਆ-ਢੁਆਈ","ਸਿਰਫ਼ ਆਯਾਤ ਕੀਤੇ ਉਤਪਾਦਾਂ ਦੀ ਪਰਚੂਨ ਵਿਕਰੀ"],"ਨਿਰਮਾਣ ਕੱਚੇ ਮਾਲ ਨੂੰ ਵਧੇਰੇ ਉਪਯੋਗਤਾ ਅਤੇ ਕੀਮਤ ਵਾਲੀਆਂ ਵਸਤਾਂ ਵਿੱਚ ਬਦਲਦਾ ਹੈ। ਇਸ ਲਈ ਇਹ ਸਾਧਾਰਨ ਨਿਕਾਸੀ ਜਾਂ ਵਪਾਰ ਨਹੀਂ, ਸਗੋਂ ਇੱਕ ਦੂਜੈਲੀ ਆਰਥਿਕ ਕਿਰਿਆ ਹੈ।"]},
"GEO-IND-001-CP001-Q002":{"h":"3cac6277","hi":["कौन-सा उदाहरण विनिर्माण द्वारा मूल्यवर्धन दर्शाता है?",["खेत से कपास की तुड़ाई","लौह अयस्क का खनन","कपास के रेशे से कपड़ा बनाना","कोयले को रेलवे साइडिंग तक ले जाना"],"कपास के रेशे से कपड़ा बनाने पर कच्चे माल का रूप और उपयोगिता बदल जाती है। यह प्रसंस्करण मूल्य बढ़ाता है और स्पष्ट रूप से विनिर्माण क्रिया है।"],"pa":["ਕਿਹੜੀ ਉਦਾਹਰਨ ਨਿਰਮਾਣ ਰਾਹੀਂ ਮੁੱਲ-ਵਾਧਾ ਦਰਸਾਉਂਦੀ ਹੈ?",["ਖੇਤ ਵਿੱਚੋਂ ਕਪਾਹ ਦੀ ਚੁਗਾਈ","ਕੱਚੇ ਲੋਹੇ ਦੀ ਖੁਦਾਈ","ਕਪਾਹ ਦੇ ਰੇਸ਼ੇ ਤੋਂ ਕੱਪੜਾ ਬਣਾਉਣਾ","ਕੋਲੇ ਨੂੰ ਰੇਲਵੇ ਸਾਈਡਿੰਗ ਤੱਕ ਲਿਜਾਣਾ"],"ਕਪਾਹ ਦੇ ਰੇਸ਼ੇ ਤੋਂ ਕੱਪੜਾ ਬਣਾਉਣ ਨਾਲ ਕੱਚੇ ਮਾਲ ਦਾ ਰੂਪ ਅਤੇ ਉਪਯੋਗਤਾ ਬਦਲ ਜਾਂਦੀ ਹੈ। ਇਹ ਪ੍ਰੋਸੈਸਿੰਗ ਕੀਮਤ ਵਧਾਉਂਦੀ ਹੈ ਅਤੇ ਸਪਸ਼ਟ ਤੌਰ 'ਤੇ ਨਿਰਮਾਣ ਕਿਰਿਆ ਹੈ।"]},
"GEO-IND-001-CP001-Q003":{"h":"a79b2ef2","hi":["कौन-सी क्रिया निष्कर्षण नहीं, बल्कि विनिर्माण है?",["लौह अयस्क का खनन","वन में लकड़ी काटना","समुद्र से मछली पकड़ना","लौह अयस्क से इस्पात बनाना"],"इस्पात उत्पादन में खनन से प्राप्त कच्चे माल को एक नए औद्योगिक उत्पाद में बदला जाता है। खनन, लकड़ी कटाई और मत्स्यन प्राथमिक क्रियाएँ हैं, क्योंकि इनमें प्राकृतिक संसाधन निकाले जाते हैं।"],"pa":["ਕਿਹੜੀ ਕਿਰਿਆ ਨਿਕਾਸੀ ਨਹੀਂ, ਸਗੋਂ ਨਿਰਮਾਣ ਹੈ?",["ਕੱਚੇ ਲੋਹੇ ਦੀ ਖੁਦਾਈ","ਜੰਗਲ ਵਿੱਚ ਲੱਕੜ ਕੱਟਣੀ","ਸਮੁੰਦਰ ਵਿੱਚੋਂ ਮੱਛੀ ਫੜਨੀ","ਕੱਚੇ ਲੋਹੇ ਤੋਂ ਸਟੀਲ ਬਣਾਉਣਾ"],"ਸਟੀਲ ਉਤਪਾਦਨ ਵਿੱਚ ਖੁਦਾਈ ਨਾਲ ਮਿਲੇ ਕੱਚੇ ਮਾਲ ਨੂੰ ਨਵੇਂ ਉਦਯੋਗਿਕ ਉਤਪਾਦ ਵਿੱਚ ਬਦਲਿਆ ਜਾਂਦਾ ਹੈ। ਖੁਦਾਈ, ਲੱਕੜ ਕਟਾਈ ਅਤੇ ਮੱਛੀ ਫੜਨਾ ਮੁਢਲੀਆਂ ਕਿਰਿਆਵਾਂ ਹਨ, ਕਿਉਂਕਿ ਇਨ੍ਹਾਂ ਵਿੱਚ ਕੁਦਰਤੀ ਸਾਧਨ ਕੱਢੇ ਜਾਂਦੇ ਹਨ।"]},
"GEO-IND-001-CP001-Q004":{"h":"f7681a38","hi":["कथनों पर विचार कीजिए: I. विनिर्माण कच्चे माल का रूप बदलता है। II. विनिर्माण किसी उत्पाद का आर्थिक मूल्य बढ़ा सकता है। कौन-सा/से कथन सही है/हैं?",["I और II दोनों सही हैं","केवल I सही है","केवल II सही है","न तो I और न ही II सही है"],"विनिर्माण सामग्री का रूप बदलता है और सामान्यतः उसकी उपयोगिता तथा बाज़ार मूल्य बढ़ाता है। अतः दोनों कथन विनिर्माण की भूमिका सही बताते हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਨਿਰਮਾਣ ਕੱਚੇ ਮਾਲ ਦਾ ਰੂਪ ਬਦਲਦਾ ਹੈ। II. ਨਿਰਮਾਣ ਕਿਸੇ ਉਤਪਾਦ ਦੀ ਆਰਥਿਕ ਕੀਮਤ ਵਧਾ ਸਕਦਾ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਨਿਰਮਾਣ ਸਮੱਗਰੀ ਦਾ ਰੂਪ ਬਦਲਦਾ ਹੈ ਅਤੇ ਆਮ ਤੌਰ 'ਤੇ ਉਸ ਦੀ ਉਪਯੋਗਤਾ ਅਤੇ ਬਾਜ਼ਾਰੀ ਕੀਮਤ ਵਧਾਉਂਦਾ ਹੈ। ਇਸ ਲਈ ਦੋਵੇਂ ਕਥਨ ਨਿਰਮਾਣ ਦੀ ਭੂਮਿਕਾ ਸਹੀ ਦੱਸਦੇ ਹਨ।"]},
"GEO-IND-001-CP001-Q005":{"h":"ac8a9582","hi":["कौन-सी शृंखला विनिर्माण को सबसे स्पष्ट रूप से दर्शाती है?",["कोयला परत → खनित कोयला","गन्ना → चीनी","वन → कटी हुई लकड़ी","समुद्र → पकड़ी गई मछली"],"चीनी उत्पादन में गन्ने को संसाधित करके एक अलग उत्पाद बनाया जाता है। अन्य उदाहरण मुख्यतः प्राकृतिक संसाधनों के निष्कर्षण के हैं।"],"pa":["ਕਿਹੜੀ ਲੜੀ ਨਿਰਮਾਣ ਨੂੰ ਸਭ ਤੋਂ ਸਪਸ਼ਟ ਦਰਸਾਉਂਦੀ ਹੈ?",["ਕੋਲੇ ਦੀ ਪਰਤ → ਖੁਦਾਈ ਕੀਤਾ ਕੋਲਾ","ਗੰਨਾ → ਖੰਡ","ਜੰਗਲ → ਕੱਟੀ ਹੋਈ ਲੱਕੜ","ਸਮੁੰਦਰ → ਫੜੀ ਗਈ ਮੱਛੀ"],"ਖੰਡ ਉਤਪਾਦਨ ਵਿੱਚ ਗੰਨੇ ਨੂੰ ਪ੍ਰੋਸੈਸ ਕਰਕੇ ਇੱਕ ਵੱਖਰਾ ਉਤਪਾਦ ਬਣਾਇਆ ਜਾਂਦਾ ਹੈ। ਬਾਕੀ ਉਦਾਹਰਨਾਂ ਮੁੱਖ ਤੌਰ 'ਤੇ ਕੁਦਰਤੀ ਸਾਧਨਾਂ ਦੀ ਨਿਕਾਸੀ ਦੀਆਂ ਹਨ।"]},
"GEO-IND-001-CP001-Q006":{"h":"cccd88e4","hi":["आर्थिक भूगोल में विनिर्माण क्यों महत्वपूर्ण है?",["इसका स्थान से कोई संबंध नहीं है","यह केवल जलवायु पर निर्भर करता है","यह विशेष स्थानों पर कच्चे माल, श्रम, ऊर्जा, परिवहन और बाज़ार को जोड़ता है","यह केवल वहीं होता है जहाँ खनिजों का खनन होता है"],"औद्योगिक भूगोल यह अध्ययन करता है कि विनिर्माण संसाधनों, लोगों, अवसंरचना और बाज़ारों को कैसे जोड़ता है। इन्हीं कारकों से समझ आता है कि उद्योग कुछ विशेष क्षेत्रों में क्यों केंद्रित होते हैं।"],"pa":["ਆਰਥਿਕ ਭੂਗੋਲ ਵਿੱਚ ਨਿਰਮਾਣ ਮਹੱਤਵਪੂਰਨ ਕਿਉਂ ਹੈ?",["ਇਸ ਦਾ ਸਥਾਨ ਨਾਲ ਕੋਈ ਸੰਬੰਧ ਨਹੀਂ","ਇਹ ਸਿਰਫ਼ ਜਲਵਾਯੂ 'ਤੇ ਨਿਰਭਰ ਕਰਦਾ ਹੈ","ਇਹ ਖ਼ਾਸ ਥਾਵਾਂ 'ਤੇ ਕੱਚੇ ਮਾਲ, ਕਿਰਤ, ਊਰਜਾ, ਆਵਾਜਾਈ ਅਤੇ ਬਾਜ਼ਾਰਾਂ ਨੂੰ ਜੋੜਦਾ ਹੈ","ਇਹ ਸਿਰਫ਼ ਉੱਥੇ ਹੁੰਦਾ ਹੈ ਜਿੱਥੇ ਖਣਿਜਾਂ ਦੀ ਖੁਦਾਈ ਹੁੰਦੀ ਹੈ"],"ਉਦਯੋਗਿਕ ਭੂਗੋਲ ਇਹ ਅਧਿਐਨ ਕਰਦਾ ਹੈ ਕਿ ਨਿਰਮਾਣ ਸਾਧਨਾਂ, ਲੋਕਾਂ, ਬੁਨਿਆਦੀ ਢਾਂਚੇ ਅਤੇ ਬਾਜ਼ਾਰਾਂ ਨੂੰ ਕਿਵੇਂ ਜੋੜਦਾ ਹੈ। ਇਨ੍ਹਾਂ ਕਾਰਕਾਂ ਤੋਂ ਪਤਾ ਲੱਗਦਾ ਹੈ ਕਿ ਉਦਯੋਗ ਕੁਝ ਖ਼ਾਸ ਖੇਤਰਾਂ ਵਿੱਚ ਕਿਉਂ ਇਕੱਠੇ ਹੁੰਦੇ ਹਨ।"]},
"GEO-IND-001-CP001-Q007":{"h":"4f1d55a9","hi":["विनिर्माण आर्थिक क्रिया के किस क्षेत्रक से संबंधित है?",["द्वितीयक क्षेत्रक","प्राथमिक क्षेत्रक","केवल तृतीयक क्षेत्रक","केवल चतुर्थक क्षेत्रक"],"द्वितीयक क्षेत्रक प्राथमिक क्रियाओं से प्राप्त कच्चे माल को विनिर्मित वस्तुओं में बदलता है। इसलिए विनिर्माण एक मूल द्वितीयक क्रिया है।"],"pa":["ਨਿਰਮਾਣ ਆਰਥਿਕ ਕਿਰਿਆ ਦੇ ਕਿਸ ਖੇਤਰ ਨਾਲ ਸੰਬੰਧਿਤ ਹੈ?",["ਦੂਜੈਲਾ ਖੇਤਰ","ਮੁਢਲਾ ਖੇਤਰ","ਸਿਰਫ਼ ਤੀਜੈਲਾ ਖੇਤਰ","ਸਿਰਫ਼ ਚੌਥਾ ਖੇਤਰ"],"ਦੂਜੈਲਾ ਖੇਤਰ ਮੁਢਲੀਆਂ ਕਿਰਿਆਵਾਂ ਤੋਂ ਮਿਲੇ ਕੱਚੇ ਮਾਲ ਨੂੰ ਨਿਰਮਿਤ ਵਸਤਾਂ ਵਿੱਚ ਬਦਲਦਾ ਹੈ। ਇਸ ਲਈ ਨਿਰਮਾਣ ਇੱਕ ਮੂਲ ਦੂਜੈਲੀ ਕਿਰਿਆ ਹੈ।"]},
"GEO-IND-001-CP001-Q008":{"h":"1da28a85","hi":["कौन-सा क्रम प्राथमिक से द्वितीयक आर्थिक शृंखला को सही दर्शाता है?",["इस्पात विनिर्माण → लौह अयस्क खनन","लौह अयस्क खनन → इस्पात विनिर्माण","बैंकिंग → गेहूँ की खेती","खुदरा व्यापार → कोयले का निर्माण"],"खनन कच्चा माल निकालता है और प्राथमिक क्षेत्रक में आता है, जबकि इस्पात उत्पादन उसे संसाधित करता है और द्वितीयक क्षेत्रक में आता है।"],"pa":["ਕਿਹੜਾ ਕ੍ਰਮ ਮੁਢਲੀ ਤੋਂ ਦੂਜੈਲੀ ਆਰਥਿਕ ਲੜੀ ਨੂੰ ਸਹੀ ਦਰਸਾਉਂਦਾ ਹੈ?",["ਸਟੀਲ ਨਿਰਮਾਣ → ਕੱਚੇ ਲੋਹੇ ਦੀ ਖੁਦਾਈ","ਕੱਚੇ ਲੋਹੇ ਦੀ ਖੁਦਾਈ → ਸਟੀਲ ਨਿਰਮਾਣ","ਬੈਂਕਿੰਗ → ਕਣਕ ਦੀ ਖੇਤੀ","ਪਰਚੂਨ ਵਪਾਰ → ਕੋਲੇ ਦਾ ਬਣਨਾ"],"ਖੁਦਾਈ ਕੱਚਾ ਮਾਲ ਕੱਢਦੀ ਹੈ ਅਤੇ ਮੁਢਲੇ ਖੇਤਰ ਵਿੱਚ ਆਉਂਦੀ ਹੈ, ਜਦਕਿ ਸਟੀਲ ਉਤਪਾਦਨ ਉਸ ਨੂੰ ਪ੍ਰੋਸੈਸ ਕਰਦਾ ਹੈ ਅਤੇ ਦੂਜੈਲੇ ਖੇਤਰ ਵਿੱਚ ਆਉਂਦਾ ਹੈ।"]},
"GEO-IND-001-CP001-Q009":{"h":"04f9da74","hi":["कथनों पर विचार कीजिए: I. खनन एक प्राथमिक क्रिया है। II. इस्पात का विनिर्माण एक द्वितीयक क्रिया है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","I और II दोनों सही हैं","न तो I और न ही II सही है"],"खनन प्राकृतिक संसाधन निकालता है, जबकि इस्पात विनिर्माण निकाले गए अयस्क को संसाधित करता है। ये दोनों क्रियाएँ उत्पादन शृंखला के अलग-अलग चरणों में आती हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਖੁਦਾਈ ਇੱਕ ਮੁਢਲੀ ਕਿਰਿਆ ਹੈ। II. ਸਟੀਲ ਦਾ ਨਿਰਮਾਣ ਇੱਕ ਦੂਜੈਲੀ ਕਿਰਿਆ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਖੁਦਾਈ ਕੁਦਰਤੀ ਸਾਧਨ ਕੱਢਦੀ ਹੈ, ਜਦਕਿ ਸਟੀਲ ਨਿਰਮਾਣ ਕੱਢੇ ਗਏ ਕੱਚੇ ਧਾਤ ਨੂੰ ਪ੍ਰੋਸੈਸ ਕਰਦਾ ਹੈ। ਇਹ ਦੋਵੇਂ ਕਿਰਿਆਵਾਂ ਉਤਪਾਦਨ ਲੜੀ ਦੇ ਵੱਖ-ਵੱਖ ਪੜਾਵਾਂ ਵਿੱਚ ਆਉਂਦੀਆਂ ਹਨ।"]},
"GEO-IND-001-CP001-Q010":{"h":"7e1a9ff7","hi":["कौन-सी क्रिया द्वितीयक है?",["चूना पत्थर का खनन","गेहूँ की खेती","समुद्री मत्स्यन","सीमेंट विनिर्माण"],"सीमेंट विनिर्माण खनिज कच्चे माल को विनिर्मित उत्पाद में बदलता है। खनन, कृषि और मत्स्यन प्राथमिक क्रियाएँ हैं।"],"pa":["ਕਿਹੜੀ ਕਿਰਿਆ ਦੂਜੈਲੀ ਹੈ?",["ਚੂਨਾ ਪੱਥਰ ਦੀ ਖੁਦਾਈ","ਕਣਕ ਦੀ ਖੇਤੀ","ਸਮੁੰਦਰੀ ਮੱਛੀ ਪਾਲਣ","ਸੀਮਿੰਟ ਨਿਰਮਾਣ"],"ਸੀਮਿੰਟ ਨਿਰਮਾਣ ਖਣਿਜ ਕੱਚੇ ਮਾਲ ਨੂੰ ਨਿਰਮਿਤ ਉਤਪਾਦ ਵਿੱਚ ਬਦਲਦਾ ਹੈ। ਖੁਦਾਈ, ਖੇਤੀ ਅਤੇ ਮੱਛੀ ਫੜਨਾ ਮੁਢਲੀਆਂ ਕਿਰਿਆਵਾਂ ਹਨ।"]},
"GEO-IND-001-CP001-Q011":{"h":"01ccae4b","hi":["विनिर्माण उद्योगों को द्वितीयक क्रियाएँ क्यों कहा जाता है?",["वे प्राथमिक क्रियाओं से मिली सामग्री को संसाधित करते हैं","वे केवल खुदरा व्यापार के बाद होते हैं","वे किसी कच्चे माल का उपयोग नहीं करते","वे प्राथमिक क्रियाओं से कम महत्वपूर्ण हैं"],"द्वितीयक क्रियाएँ कृषि, वानिकी, मत्स्यन या खनन से प्राप्त सामग्री को रूपांतरित करती हैं। उत्पादन शृंखला में इनका स्थान ही इस नाम का कारण है।"],"pa":["ਨਿਰਮਾਣ ਉਦਯੋਗਾਂ ਨੂੰ ਦੂਜੈਲੀਆਂ ਕਿਰਿਆਵਾਂ ਕਿਉਂ ਕਿਹਾ ਜਾਂਦਾ ਹੈ?",["ਉਹ ਮੁਢਲੀਆਂ ਕਿਰਿਆਵਾਂ ਤੋਂ ਮਿਲੀ ਸਮੱਗਰੀ ਨੂੰ ਪ੍ਰੋਸੈਸ ਕਰਦੇ ਹਨ","ਉਹ ਸਿਰਫ਼ ਪਰਚੂਨ ਵਪਾਰ ਤੋਂ ਬਾਅਦ ਹੁੰਦੇ ਹਨ","ਉਹ ਕੋਈ ਕੱਚਾ ਮਾਲ ਨਹੀਂ ਵਰਤਦੇ","ਉਹ ਮੁਢਲੀਆਂ ਕਿਰਿਆਵਾਂ ਨਾਲੋਂ ਘੱਟ ਮਹੱਤਵਪੂਰਨ ਹਨ"],"ਦੂਜੈਲੀਆਂ ਕਿਰਿਆਵਾਂ ਖੇਤੀ, ਜੰਗਲਾਤ, ਮੱਛੀ ਫੜਨ ਜਾਂ ਖੁਦਾਈ ਤੋਂ ਮਿਲੀ ਸਮੱਗਰੀ ਦਾ ਰੂਪ ਬਦਲਦੀਆਂ ਹਨ। ਉਤਪਾਦਨ ਲੜੀ ਵਿੱਚ ਇਨ੍ਹਾਂ ਦੀ ਥਾਂ ਹੀ ਇਸ ਨਾਂ ਦਾ ਕਾਰਨ ਹੈ।"]},
"GEO-IND-001-CP001-Q012":{"h":"aa7940a5","hi":["कौन-सी शृंखला क्षेत्रकों को सही ढंग से जोड़ती है?",["खुदरा व्यापार → कृषि → खनन","कृषि → वस्त्र विनिर्माण → खुदरा व्यापार","विनिर्माण → खनिज निर्माण → मत्स्यन","बैंकिंग → कोयला खनन → वर्षा"],"कृषि कच्चा माल देती है, विनिर्माण उसे संसाधित करता है और व्यापार तैयार उत्पाद को उपभोक्ताओं तक पहुँचाता है। यह शृंखला प्राथमिक से द्वितीयक और फिर तृतीयक क्रिया की ओर बढ़ती है।"],"pa":["ਕਿਹੜੀ ਲੜੀ ਖੇਤਰਾਂ ਨੂੰ ਸਹੀ ਤਰ੍ਹਾਂ ਜੋੜਦੀ ਹੈ?",["ਪਰਚੂਨ ਵਪਾਰ → ਖੇਤੀ → ਖੁਦਾਈ","ਖੇਤੀ → ਕੱਪੜਾ ਨਿਰਮਾਣ → ਪਰਚੂਨ ਵਪਾਰ","ਨਿਰਮਾਣ → ਖਣਿਜ ਬਣਨਾ → ਮੱਛੀ ਫੜਨਾ","ਬੈਂਕਿੰਗ → ਕੋਲਾ ਖੁਦਾਈ → ਵਰਖਾ"],"ਖੇਤੀ ਕੱਚਾ ਮਾਲ ਦਿੰਦੀ ਹੈ, ਨਿਰਮਾਣ ਉਸ ਨੂੰ ਪ੍ਰੋਸੈਸ ਕਰਦਾ ਹੈ ਅਤੇ ਵਪਾਰ ਤਿਆਰ ਉਤਪਾਦ ਨੂੰ ਖਪਤਕਾਰਾਂ ਤੱਕ ਪਹੁੰਚਾਉਂਦਾ ਹੈ। ਇਹ ਲੜੀ ਮੁਢਲੀ ਤੋਂ ਦੂਜੈਲੀ ਅਤੇ ਫਿਰ ਤੀਜੈਲੀ ਕਿਰਿਆ ਵੱਲ ਜਾਂਦੀ ਹੈ।"]},
"GEO-IND-001-CP001-Q013":{"h":"ecd15510","hi":["कौन-सा उद्योग कृषि-आधारित है?",["लौह-इस्पात उद्योग","एल्युमिनियम प्रगलन","सीमेंट उद्योग","सूती वस्त्र उद्योग"],"सूती वस्त्र उद्योग का मुख्य कच्चा माल कृषि में उगाई गई कपास है। लौह-इस्पात, एल्युमिनियम और सीमेंट मुख्यतः खनिज कच्चे माल पर निर्भर हैं।"],"pa":["ਕਿਹੜਾ ਉਦਯੋਗ ਖੇਤੀ-ਅਧਾਰਿਤ ਹੈ?",["ਲੋਹਾ-ਸਟੀਲ ਉਦਯੋਗ","ਐਲੂਮੀਨੀਅਮ ਪਿਘਲਾਈ","ਸੀਮਿੰਟ ਉਦਯੋਗ","ਸੂਤੀ ਕੱਪੜਾ ਉਦਯੋਗ"],"ਸੂਤੀ ਕੱਪੜਾ ਉਦਯੋਗ ਦਾ ਮੁੱਖ ਕੱਚਾ ਮਾਲ ਖੇਤੀ ਵਿੱਚ ਉਗਾਈ ਕਪਾਹ ਹੈ। ਲੋਹਾ-ਸਟੀਲ, ਐਲੂਮੀਨੀਅਮ ਅਤੇ ਸੀਮਿੰਟ ਮੁੱਖ ਤੌਰ 'ਤੇ ਖਣਿਜ ਕੱਚੇ ਮਾਲ 'ਤੇ ਨਿਰਭਰ ਹਨ।"]},
"GEO-IND-001-CP001-Q014":{"h":"6c64d448","hi":["कौन-सा उद्योग खनिज-आधारित है?",["लौह-इस्पात उद्योग","चीनी उद्योग","जूट वस्त्र उद्योग","खाद्य प्रसंस्करण उद्योग"],"लौह-इस्पात उत्पादन लौह अयस्क, कोयला और चूना पत्थर जैसे खनिजों पर निर्भर है। चीनी, जूट और अधिकांश खाद्य प्रसंस्करण उद्योग कृषि कच्चे माल का उपयोग करते हैं।"],"pa":["ਕਿਹੜਾ ਉਦਯੋਗ ਖਣਿਜ-ਅਧਾਰਿਤ ਹੈ?",["ਲੋਹਾ-ਸਟੀਲ ਉਦਯੋਗ","ਖੰਡ ਉਦਯੋਗ","ਪਟਸਨ ਕੱਪੜਾ ਉਦਯੋਗ","ਖ਼ੁਰਾਕ ਪ੍ਰੋਸੈਸਿੰਗ ਉਦਯੋਗ"],"ਲੋਹਾ-ਸਟੀਲ ਉਤਪਾਦਨ ਕੱਚਾ ਲੋਹਾ, ਕੋਲਾ ਅਤੇ ਚੂਨਾ ਪੱਥਰ ਵਰਗੇ ਖਣਿਜਾਂ 'ਤੇ ਨਿਰਭਰ ਹੈ। ਖੰਡ, ਪਟਸਨ ਅਤੇ ਬਹੁਤੇ ਖ਼ੁਰਾਕ ਪ੍ਰੋਸੈਸਿੰਗ ਉਦਯੋਗ ਖੇਤੀ ਵਾਲਾ ਕੱਚਾ ਮਾਲ ਵਰਤਦੇ ਹਨ।"]},
"GEO-IND-001-CP001-Q015":{"h":"1a474a22","hi":["कथनों पर विचार कीजिए: I. चीनी एक कृषि-आधारित उद्योग है। II. सीमेंट एक खनिज-आधारित उद्योग है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","I और II दोनों सही हैं","केवल II सही है","न तो I और न ही II सही है"],"चीनी विनिर्माण गन्ने पर निर्भर है, जबकि सीमेंट मुख्यतः चूना पत्थर जैसे खनिजों पर। दोनों वर्गीकरण सही हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਖੰਡ ਇੱਕ ਖੇਤੀ-ਅਧਾਰਿਤ ਉਦਯੋਗ ਹੈ। II. ਸੀਮਿੰਟ ਇੱਕ ਖਣਿਜ-ਅਧਾਰਿਤ ਉਦਯੋਗ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਖੰਡ ਨਿਰਮਾਣ ਗੰਨੇ 'ਤੇ ਨਿਰਭਰ ਹੈ, ਜਦਕਿ ਸੀਮਿੰਟ ਮੁੱਖ ਤੌਰ 'ਤੇ ਚੂਨਾ ਪੱਥਰ ਵਰਗੇ ਖਣਿਜਾਂ 'ਤੇ। ਦੋਵੇਂ ਵਰਗੀਕਰਨ ਸਹੀ ਹਨ।"]},
"GEO-IND-001-CP001-Q016":{"h":"17665416","hi":["कौन-सा युग्म सही वर्गीकृत है?",["इस्पात — कृषि-आधारित","चीनी — खनिज-आधारित","जूट वस्त्र — कृषि-आधारित","एल्युमिनियम — कृषि-आधारित"],"जूट वस्त्र एक कृषि रेशे का उपयोग करते हैं, इसलिए वे कृषि-आधारित हैं। इस्पात और एल्युमिनियम खनिज-आधारित हैं, जबकि चीनी भी कृषि-आधारित है।"],"pa":["ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਵਰਗੀਕ੍ਰਿਤ ਹੈ?",["ਸਟੀਲ — ਖੇਤੀ-ਅਧਾਰਿਤ","ਖੰਡ — ਖਣਿਜ-ਅਧਾਰਿਤ","ਪਟਸਨ ਕੱਪੜਾ — ਖੇਤੀ-ਅਧਾਰਿਤ","ਐਲੂਮੀਨੀਅਮ — ਖੇਤੀ-ਅਧਾਰਿਤ"],"ਪਟਸਨ ਕੱਪੜਾ ਇੱਕ ਖੇਤੀ ਰੇਸ਼ਾ ਵਰਤਦਾ ਹੈ, ਇਸ ਲਈ ਇਹ ਖੇਤੀ-ਅਧਾਰਿਤ ਹੈ। ਸਟੀਲ ਅਤੇ ਐਲੂਮੀਨੀਅਮ ਖਣਿਜ-ਅਧਾਰਿਤ ਹਨ, ਜਦਕਿ ਖੰਡ ਵੀ ਖੇਤੀ-ਅਧਾਰਿਤ ਹੈ।"]},
"GEO-IND-001-CP001-Q017":{"h":"2bbeecff","hi":["कौन-सा कच्चा माल एल्युमिनियम प्रगलन को सीधे खनिज-आधारित उद्योग बनाता है?",["कपास","गन्ना","जूट","बॉक्साइट"],"बॉक्साइट एल्युमिनियम बनाने में प्रयुक्त मुख्य खनिज अयस्क है। अन्य सामग्रियाँ कृषि कच्चा माल हैं।"],"pa":["ਕਿਹੜਾ ਕੱਚਾ ਮਾਲ ਐਲੂਮੀਨੀਅਮ ਪਿਘਲਾਈ ਨੂੰ ਸਿੱਧੇ ਤੌਰ 'ਤੇ ਖਣਿਜ-ਅਧਾਰਿਤ ਉਦਯੋਗ ਬਣਾਉਂਦਾ ਹੈ?",["ਕਪਾਹ","ਗੰਨਾ","ਪਟਸਨ","ਬਾਕਸਾਈਟ"],"ਬਾਕਸਾਈਟ ਐਲੂਮੀਨੀਅਮ ਬਣਾਉਣ ਲਈ ਵਰਤੀ ਜਾਂਦੀ ਮੁੱਖ ਖਣਿਜ ਕੱਚੀ ਧਾਤ ਹੈ। ਬਾਕੀ ਸਮੱਗਰੀਆਂ ਖੇਤੀ ਵਾਲਾ ਕੱਚਾ ਮਾਲ ਹਨ।"]},
"GEO-IND-001-CP001-Q018":{"h":"5b39b942","hi":["उद्योगों के वर्गीकरण के लिए कौन-सी तुलना सही है?",["सूती वस्त्र कृषि-आधारित है, जबकि इस्पात खनिज-आधारित है","दोनों खनिज-आधारित हैं","दोनों कृषि-आधारित हैं","इस्पात कृषि-आधारित है और सूती वस्त्र खनिज-आधारित"],"वर्गीकरण मुख्य कच्चे माल के स्रोत पर आधारित होता है। कपास कृषि से मिलती है, जबकि इस्पात खनिज अयस्कों और ईंधनों पर निर्भर है।"],"pa":["ਉਦਯੋਗਾਂ ਦੇ ਵਰਗੀਕਰਨ ਲਈ ਕਿਹੜੀ ਤੁਲਨਾ ਸਹੀ ਹੈ?",["ਸੂਤੀ ਕੱਪੜਾ ਖੇਤੀ-ਅਧਾਰਿਤ ਹੈ, ਜਦਕਿ ਸਟੀਲ ਖਣਿਜ-ਅਧਾਰਿਤ ਹੈ","ਦੋਵੇਂ ਖਣਿਜ-ਅਧਾਰਿਤ ਹਨ","ਦੋਵੇਂ ਖੇਤੀ-ਅਧਾਰਿਤ ਹਨ","ਸਟੀਲ ਖੇਤੀ-ਅਧਾਰਿਤ ਹੈ ਅਤੇ ਸੂਤੀ ਕੱਪੜਾ ਖਣਿਜ-ਅਧਾਰਿਤ"],"ਵਰਗੀਕਰਨ ਮੁੱਖ ਕੱਚੇ ਮਾਲ ਦੇ ਸਰੋਤ 'ਤੇ ਅਧਾਰਿਤ ਹੁੰਦਾ ਹੈ। ਕਪਾਹ ਖੇਤੀ ਤੋਂ ਮਿਲਦੀ ਹੈ, ਜਦਕਿ ਸਟੀਲ ਖਣਿਜ ਕੱਚੀਆਂ ਧਾਤਾਂ ਅਤੇ ਬਾਲਣ 'ਤੇ ਨਿਰਭਰ ਹੈ।"]},
"GEO-IND-001-CP001-Q019":{"h":"77d940c4","hi":["सरकार के स्वामित्व और संचालन वाला उद्योग किस क्षेत्रक में आता है?",["निजी क्षेत्रक","सार्वजनिक क्षेत्रक","सहकारी क्षेत्रक","केवल घरेलू क्षेत्रक"],"सार्वजनिक क्षेत्रक के उद्यमों का स्वामित्व या नियंत्रण सरकार के पास होता है। यह औद्योगिक वर्गीकरण स्वामित्व पर आधारित है।"],"pa":["ਸਰਕਾਰ ਦੀ ਮਲਕੀਅਤ ਅਤੇ ਸੰਚਾਲਨ ਵਾਲਾ ਉਦਯੋਗ ਕਿਸ ਖੇਤਰ ਵਿੱਚ ਆਉਂਦਾ ਹੈ?",["ਨਿੱਜੀ ਖੇਤਰ","ਜਨਤਕ ਖੇਤਰ","ਸਹਿਕਾਰੀ ਖੇਤਰ","ਸਿਰਫ਼ ਘਰੇਲੂ ਖੇਤਰ"],"ਜਨਤਕ ਖੇਤਰ ਦੇ ਉੱਦਮਾਂ ਦੀ ਮਲਕੀਅਤ ਜਾਂ ਕੰਟਰੋਲ ਸਰਕਾਰ ਕੋਲ ਹੁੰਦਾ ਹੈ। ਇਹ ਉਦਯੋਗਿਕ ਵਰਗੀਕਰਨ ਮਲਕੀਅਤ 'ਤੇ ਅਧਾਰਿਤ ਹੈ।"]},
"GEO-IND-001-CP001-Q020":{"h":"f2ef908e","hi":["व्यक्तियों या कंपनियों के स्वामित्व वाला औद्योगिक उद्यम किस क्षेत्रक में आता है?",["सार्वजनिक क्षेत्रक","सहकारी क्षेत्रक","निजी क्षेत्रक","केवल राज्य एकाधिकार"],"निजी क्षेत्रक के उद्यमों का स्वामित्व सरकार के बजाय निजी व्यक्तियों, समूहों या कंपनियों के पास होता है।"],"pa":["ਵਿਅਕਤੀਆਂ ਜਾਂ ਕੰਪਨੀਆਂ ਦੀ ਮਲਕੀਅਤ ਵਾਲਾ ਉਦਯੋਗਿਕ ਉੱਦਮ ਕਿਸ ਖੇਤਰ ਵਿੱਚ ਆਉਂਦਾ ਹੈ?",["ਜਨਤਕ ਖੇਤਰ","ਸਹਿਕਾਰੀ ਖੇਤਰ","ਨਿੱਜੀ ਖੇਤਰ","ਸਿਰਫ਼ ਰਾਜ ਦੀ ਅਜਾਰੇਦਾਰੀ"],"ਨਿੱਜੀ ਖੇਤਰ ਦੇ ਉੱਦਮਾਂ ਦੀ ਮਲਕੀਅਤ ਸਰਕਾਰ ਦੀ ਬਜਾਏ ਨਿੱਜੀ ਵਿਅਕਤੀਆਂ, ਸਮੂਹਾਂ ਜਾਂ ਕੰਪਨੀਆਂ ਕੋਲ ਹੁੰਦੀ ਹੈ।"]},
"GEO-IND-001-CP001-Q021":{"h":"56f19091","hi":["संयुक्त क्षेत्रक के उद्योग की विशेषता क्या है?",["इसका स्वामित्व केवल किसानों के पास होता है","इसका स्वामित्व केवल केंद्र सरकार के पास होता है","इसके कोई पहचाने जाने योग्य स्वामी नहीं होते","इसका स्वामित्व सरकार और निजी पक्षों में साझा होता है"],"संयुक्त क्षेत्रक के उद्यमों में सार्वजनिक और निजी दोनों का स्वामित्व होता है। यही उन्हें केवल सार्वजनिक, निजी या सहकारी संगठनों से अलग करता है।"],"pa":["ਸਾਂਝੇ ਖੇਤਰ ਦੇ ਉਦਯੋਗ ਦੀ ਵਿਸ਼ੇਸ਼ਤਾ ਕੀ ਹੈ?",["ਇਸ ਦੀ ਮਲਕੀਅਤ ਸਿਰਫ਼ ਕਿਸਾਨਾਂ ਕੋਲ ਹੁੰਦੀ ਹੈ","ਇਸ ਦੀ ਮਲਕੀਅਤ ਸਿਰਫ਼ ਕੇਂਦਰ ਸਰਕਾਰ ਕੋਲ ਹੁੰਦੀ ਹੈ","ਇਸ ਦੇ ਕੋਈ ਪਛਾਣਨਯੋਗ ਮਾਲਕ ਨਹੀਂ ਹੁੰਦੇ","ਇਸ ਦੀ ਮਲਕੀਅਤ ਸਰਕਾਰ ਅਤੇ ਨਿੱਜੀ ਧਿਰਾਂ ਵਿੱਚ ਸਾਂਝੀ ਹੁੰਦੀ ਹੈ"],"ਸਾਂਝੇ ਖੇਤਰ ਦੇ ਉੱਦਮਾਂ ਵਿੱਚ ਜਨਤਕ ਅਤੇ ਨਿੱਜੀ ਦੋਵਾਂ ਦੀ ਮਲਕੀਅਤ ਹੁੰਦੀ ਹੈ। ਇਹੀ ਉਨ੍ਹਾਂ ਨੂੰ ਸਿਰਫ਼ ਜਨਤਕ, ਨਿੱਜੀ ਜਾਂ ਸਹਿਕਾਰੀ ਸੰਗਠਨਾਂ ਤੋਂ ਵੱਖ ਕਰਦਾ ਹੈ।"]},
"GEO-IND-001-CP001-Q022":{"h":"de54c5a7","hi":["सहकारी क्षेत्रक के उद्योग की निर्णायक विशेषता क्या है?",["इसका स्वामित्व सदस्यों के पास सामूहिक रूप से होता है, जो संसाधन जुटाते हैं और लाभ बाँटते हैं","इसका स्वामित्व हमेशा किसी बहुराष्ट्रीय कंपनी के पास होता है","इसका स्वामित्व केवल संसद के पास होता है","इसका उत्पादकों से कोई संबंध नहीं होता"],"सहकारी उद्योगों का स्वामित्व और प्रबंधन उत्पादक या श्रमिक जैसे सदस्य करते हैं, जो अपने संसाधन मिलाते हैं। चीनी सहकारी मिलें इसका परिचित भारतीय उदाहरण हैं।"],"pa":["ਸਹਿਕਾਰੀ ਖੇਤਰ ਦੇ ਉਦਯੋਗ ਦੀ ਨਿਰਣਾਇਕ ਵਿਸ਼ੇਸ਼ਤਾ ਕੀ ਹੈ?",["ਇਸ ਦੀ ਮਲਕੀਅਤ ਮੈਂਬਰਾਂ ਕੋਲ ਸਾਂਝੇ ਤੌਰ 'ਤੇ ਹੁੰਦੀ ਹੈ, ਜੋ ਸਾਧਨ ਇਕੱਠੇ ਕਰਦੇ ਹਨ ਅਤੇ ਲਾਭ ਵੰਡਦੇ ਹਨ","ਇਸ ਦੀ ਮਲਕੀਅਤ ਹਮੇਸ਼ਾ ਕਿਸੇ ਬਹੁਕੌਮੀ ਕੰਪਨੀ ਕੋਲ ਹੁੰਦੀ ਹੈ","ਇਸ ਦੀ ਮਲਕੀਅਤ ਸਿਰਫ਼ ਸੰਸਦ ਕੋਲ ਹੁੰਦੀ ਹੈ","ਇਸ ਦਾ ਉਤਪਾਦਕਾਂ ਨਾਲ ਕੋਈ ਸੰਬੰਧ ਨਹੀਂ ਹੁੰਦਾ"],"ਸਹਿਕਾਰੀ ਉਦਯੋਗਾਂ ਦੀ ਮਲਕੀਅਤ ਅਤੇ ਪ੍ਰਬੰਧ ਉਤਪਾਦਕ ਜਾਂ ਕਾਮੇ ਵਰਗੇ ਮੈਂਬਰ ਕਰਦੇ ਹਨ, ਜੋ ਆਪਣੇ ਸਾਧਨ ਇਕੱਠੇ ਕਰਦੇ ਹਨ। ਸਹਿਕਾਰੀ ਖੰਡ ਮਿੱਲਾਂ ਇਸ ਦੀ ਜਾਣੀ-ਪਛਾਣੀ ਭਾਰਤੀ ਉਦਾਹਰਨ ਹਨ।"]},
"GEO-IND-001-CP001-Q023":{"h":"4b3f08da","hi":["कथनों पर विचार कीजिए: I. सार्वजनिक/निजी वर्गीकरण स्वामित्व पर आधारित है। II. सहकारी उद्योगों का स्वामित्व सदस्यों के पास होता है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","I और II दोनों सही हैं","केवल II सही है","न तो I और न ही II सही है"],"स्वामित्व के आधार पर ही सार्वजनिक, निजी, संयुक्त और सहकारी वर्गीकरण होता है। सहकारी उद्योगों का स्वामित्व भाग लेने वाले सदस्यों के पास सामूहिक रूप से होता है।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਜਨਤਕ/ਨਿੱਜੀ ਵਰਗੀਕਰਨ ਮਲਕੀਅਤ 'ਤੇ ਅਧਾਰਿਤ ਹੈ। II. ਸਹਿਕਾਰੀ ਉਦਯੋਗਾਂ ਦੀ ਮਲਕੀਅਤ ਮੈਂਬਰਾਂ ਕੋਲ ਹੁੰਦੀ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਮਲਕੀਅਤ ਦੇ ਅਧਾਰ 'ਤੇ ਹੀ ਜਨਤਕ, ਨਿੱਜੀ, ਸਾਂਝਾ ਅਤੇ ਸਹਿਕਾਰੀ ਵਰਗੀਕਰਨ ਹੁੰਦਾ ਹੈ। ਸਹਿਕਾਰੀ ਉਦਯੋਗਾਂ ਦੀ ਮਲਕੀਅਤ ਹਿੱਸਾ ਲੈਣ ਵਾਲੇ ਮੈਂਬਰਾਂ ਕੋਲ ਸਾਂਝੇ ਤੌਰ 'ਤੇ ਹੁੰਦੀ ਹੈ।"]},
"GEO-IND-001-CP001-Q024":{"h":"a8cce3cd","hi":["कौन-सा उदाहरण सहकारी औद्योगिक संगठन पर सबसे स्वाभाविक रूप से लागू होता है?",["मंत्रालय के स्वामित्व वाला इस्पात संयंत्र","निजी स्वामित्व वाली ऑटोमोबाइल कंपनी","सदस्य गन्ना उत्पादकों के स्वामित्व वाली चीनी मिल","एक सरकारी विभाग"],"उत्पादकों के स्वामित्व वाली चीनी मिल सहकारी स्वामित्व को दर्शाती है, क्योंकि उत्पादक संसाधन जुटाते हैं और स्वामित्व तथा लाभ में भागीदार होते हैं।"],"pa":["ਕਿਹੜੀ ਉਦਾਹਰਨ ਸਹਿਕਾਰੀ ਉਦਯੋਗਿਕ ਸੰਗਠਨ 'ਤੇ ਸਭ ਤੋਂ ਕੁਦਰਤੀ ਤੌਰ 'ਤੇ ਢੁਕਦੀ ਹੈ?",["ਮੰਤਰਾਲੇ ਦੀ ਮਲਕੀਅਤ ਵਾਲਾ ਸਟੀਲ ਪਲਾਂਟ","ਨਿੱਜੀ ਮਲਕੀਅਤ ਵਾਲੀ ਆਟੋਮੋਬਾਈਲ ਕੰਪਨੀ","ਮੈਂਬਰ ਗੰਨਾ ਉਤਪਾਦਕਾਂ ਦੀ ਮਲਕੀਅਤ ਵਾਲੀ ਖੰਡ ਮਿੱਲ","ਇੱਕ ਸਰਕਾਰੀ ਵਿਭਾਗ"],"ਉਤਪਾਦਕਾਂ ਦੀ ਮਲਕੀਅਤ ਵਾਲੀ ਖੰਡ ਮਿੱਲ ਸਹਿਕਾਰੀ ਮਲਕੀਅਤ ਨੂੰ ਦਰਸਾਉਂਦੀ ਹੈ, ਕਿਉਂਕਿ ਉਤਪਾਦਕ ਸਾਧਨ ਇਕੱਠੇ ਕਰਦੇ ਹਨ ਅਤੇ ਮਲਕੀਅਤ ਤੇ ਲਾਭ ਵਿੱਚ ਹਿੱਸੇਦਾਰ ਹੁੰਦੇ ਹਨ।"]},
"GEO-IND-001-CP001-Q025":{"h":"cedbd7fb","hi":["जो उद्योग भारी कच्चा माल उपयोग करता है और प्रसंस्करण में उसका भार घटता है, उसके लिए कौन-सा अवस्थिति कारक विशेष रूप से महत्वपूर्ण है?",["सभी परिवहन मार्गों से दूरी","कच्चे माल के स्रोत से निकटता","श्रम का अभाव","केवल भूमि की ऊँची कीमत"],"जब कच्चा माल भारी हो या प्रसंस्करण में उसका भार काफ़ी घट जाए, तब स्रोत के पास उद्योग लगाने से परिवहन लागत कम होती है। यह औद्योगिक अवस्थिति का एक प्रमुख सिद्धांत है।"],"pa":["ਜੋ ਉਦਯੋਗ ਭਾਰੀ ਕੱਚਾ ਮਾਲ ਵਰਤਦਾ ਹੈ ਅਤੇ ਪ੍ਰੋਸੈਸਿੰਗ ਦੌਰਾਨ ਉਸ ਦਾ ਭਾਰ ਘਟਦਾ ਹੈ, ਉਸ ਲਈ ਕਿਹੜਾ ਸਥਾਨਕ ਕਾਰਕ ਖ਼ਾਸ ਤੌਰ 'ਤੇ ਮਹੱਤਵਪੂਰਨ ਹੈ?",["ਸਾਰੇ ਆਵਾਜਾਈ ਮਾਰਗਾਂ ਤੋਂ ਦੂਰੀ","ਕੱਚੇ ਮਾਲ ਦੇ ਸਰੋਤ ਦੀ ਨੇੜਤਾ","ਕਿਰਤ ਦੀ ਘਾਟ","ਸਿਰਫ਼ ਜ਼ਮੀਨ ਦੀ ਉੱਚੀ ਕੀਮਤ"],"ਜਦੋਂ ਕੱਚਾ ਮਾਲ ਭਾਰੀ ਹੋਵੇ ਜਾਂ ਪ੍ਰੋਸੈਸਿੰਗ ਵਿੱਚ ਉਸ ਦਾ ਭਾਰ ਕਾਫ਼ੀ ਘਟ ਜਾਵੇ, ਤਾਂ ਸਰੋਤ ਦੇ ਨੇੜੇ ਉਦਯੋਗ ਲਾਉਣ ਨਾਲ ਢੋਆ-ਢੁਆਈ ਦੀ ਲਾਗਤ ਘਟਦੀ ਹੈ। ਇਹ ਉਦਯੋਗਿਕ ਸਥਾਨੀਕਰਨ ਦਾ ਇੱਕ ਪ੍ਰਮੁੱਖ ਸਿਧਾਂਤ ਹੈ।"]},
"GEO-IND-001-CP001-Q026":{"h":"8fcb97d9","hi":["अनेक आरंभिक लौह-इस्पात संयंत्र कोयला और लौह अयस्क क्षेत्रों के पास क्यों विकसित हुए?",["इस्पात उत्पादन के लिए समुद्र तट आवश्यक थे","इस उद्योग में परिवहन का उपयोग नहीं होता था","इनका प्रमुख कच्चा माल भारी था और उसका परिवहन महँगा था","बाज़ार का कोई महत्व नहीं था"],"इस्पात संयंत्रों को बड़ी मात्रा में अयस्क, कोयला और चूना पत्थर चाहिए। इन कच्चे मालों की निकटता से परिवहन लागत घटी और उद्योग खनिज पट्टियों में केंद्रित हुआ।"],"pa":["ਬਹੁਤੇ ਸ਼ੁਰੂਆਤੀ ਲੋਹਾ-ਸਟੀਲ ਪਲਾਂਟ ਕੋਲੇ ਅਤੇ ਕੱਚੇ ਲੋਹੇ ਵਾਲੇ ਖੇਤਰਾਂ ਦੇ ਨੇੜੇ ਕਿਉਂ ਵਿਕਸਿਤ ਹੋਏ?",["ਸਟੀਲ ਉਤਪਾਦਨ ਲਈ ਸਮੁੰਦਰੀ ਕੰਢੇ ਲੋੜੀਂਦੇ ਸਨ","ਇਸ ਉਦਯੋਗ ਵਿੱਚ ਆਵਾਜਾਈ ਦੀ ਵਰਤੋਂ ਨਹੀਂ ਹੁੰਦੀ ਸੀ","ਇਨ੍ਹਾਂ ਦਾ ਮੁੱਖ ਕੱਚਾ ਮਾਲ ਭਾਰੀ ਸੀ ਅਤੇ ਉਸ ਦੀ ਢੋਆ-ਢੁਆਈ ਮਹਿੰਗੀ ਸੀ","ਬਾਜ਼ਾਰਾਂ ਦੀ ਕੋਈ ਮਹੱਤਤਾ ਨਹੀਂ ਸੀ"],"ਸਟੀਲ ਪਲਾਂਟਾਂ ਨੂੰ ਵੱਡੀ ਮਾਤਰਾ ਵਿੱਚ ਕੱਚੀ ਧਾਤ, ਕੋਲਾ ਅਤੇ ਚੂਨਾ ਪੱਥਰ ਚਾਹੀਦਾ ਹੈ। ਇਨ੍ਹਾਂ ਦੀ ਨੇੜਤਾ ਨਾਲ ਢੋਆ-ਢੁਆਈ ਦੀ ਲਾਗਤ ਘਟੀ ਅਤੇ ਉਦਯੋਗ ਖਣਿਜ ਪੱਟੀਆਂ ਵਿੱਚ ਕੇਂਦਰਿਤ ਹੋਇਆ।"]},
"GEO-IND-001-CP001-Q027":{"h":"149e605a","hi":["कथनों पर विचार कीजिए: I. कच्चे माल की अवस्थिति उद्योग की अवस्थिति को प्रभावित कर सकती है। II. भार घटाने वाले उद्योग कच्चे माल के पास के स्थान पसंद कर सकते हैं। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","न तो I और न ही II सही है","I और II दोनों सही हैं"],"कच्चा माल अवस्थिति का एक प्रमुख कारक है, विशेषकर तब जब परिवहन लागत अधिक हो या प्रसंस्करण से कच्चे माल का भार घट जाए।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਕੱਚੇ ਮਾਲ ਦਾ ਸਥਾਨ ਉਦਯੋਗ ਦੇ ਸਥਾਨ ਨੂੰ ਪ੍ਰਭਾਵਿਤ ਕਰ ਸਕਦਾ ਹੈ। II. ਭਾਰ ਘਟਾਉਣ ਵਾਲੇ ਉਦਯੋਗ ਕੱਚੇ ਮਾਲ ਦੇ ਨੇੜੇ ਦੀਆਂ ਥਾਵਾਂ ਪਸੰਦ ਕਰ ਸਕਦੇ ਹਨ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ"],"ਕੱਚਾ ਮਾਲ ਸਥਾਨੀਕਰਨ ਦਾ ਇੱਕ ਮੁੱਖ ਕਾਰਕ ਹੈ, ਖ਼ਾਸ ਕਰਕੇ ਜਦੋਂ ਢੋਆ-ਢੁਆਈ ਦੀ ਲਾਗਤ ਵੱਧ ਹੋਵੇ ਜਾਂ ਪ੍ਰੋਸੈਸਿੰਗ ਨਾਲ ਕੱਚੇ ਮਾਲ ਦਾ ਭਾਰ ਘਟ ਜਾਵੇ।"]},
"GEO-IND-001-CP001-Q028":{"h":"1b885f6d","hi":["कौन-सा उद्योग शीघ्र खराब होने वाले कच्चे माल की निकटता से अधिक प्रभावित होता है?",["चीनी उद्योग","सॉफ़्टवेयर सेवाएँ","घड़ी संयोजन","ऑनलाइन बैंकिंग"],"गन्ना भारी होता है और कटाई के बाद उसमें सुक्रोज़ घटने लगता है, इसलिए चीनी मिलों को गन्ना उत्पादक क्षेत्रों के पास होने से लाभ होता है।"],"pa":["ਕਿਹੜਾ ਉਦਯੋਗ ਜਲਦੀ ਖ਼ਰਾਬ ਹੋਣ ਵਾਲੇ ਕੱਚੇ ਮਾਲ ਦੀ ਨੇੜਤਾ ਤੋਂ ਵਧੇਰੇ ਪ੍ਰਭਾਵਿਤ ਹੁੰਦਾ ਹੈ?",["ਖੰਡ ਉਦਯੋਗ","ਸਾਫ਼ਟਵੇਅਰ ਸੇਵਾਵਾਂ","ਘੜੀਆਂ ਜੋੜਨਾ","ਆਨਲਾਈਨ ਬੈਂਕਿੰਗ"],"ਗੰਨਾ ਭਾਰੀ ਹੁੰਦਾ ਹੈ ਅਤੇ ਕਟਾਈ ਤੋਂ ਬਾਅਦ ਉਸ ਵਿੱਚ ਸੁਕਰੋਜ਼ ਘਟਣ ਲੱਗਦਾ ਹੈ, ਇਸ ਲਈ ਖੰਡ ਮਿੱਲਾਂ ਨੂੰ ਗੰਨਾ ਉਗਾਉਣ ਵਾਲੇ ਖੇਤਰਾਂ ਦੇ ਨੇੜੇ ਹੋਣ ਦਾ ਲਾਭ ਹੁੰਦਾ ਹੈ।"]},
"GEO-IND-001-CP001-Q029":{"h":"7311332a","hi":["कौन-सी शृंखला कच्चा माल-उन्मुख अवस्थिति को सबसे स्पष्ट दर्शाती है?",["हवाई अड्डा → गेहूँ का खेत","चूना पत्थर पट्टी → सीमेंट संयंत्र","बैंकिंग क्षेत्र → लौह खदान","सॉफ़्टवेयर पार्क → गन्ने का खेत"],"सीमेंट संयंत्रों को बड़ी मात्रा में चूना पत्थर चाहिए, इसलिए चूना पत्थर के भंडारों के पास होना अवस्थिति का एक महत्वपूर्ण लाभ है।"],"pa":["ਕਿਹੜੀ ਲੜੀ ਕੱਚਾ ਮਾਲ-ਮੁਖੀ ਸਥਾਨੀਕਰਨ ਨੂੰ ਸਭ ਤੋਂ ਸਪਸ਼ਟ ਦਰਸਾਉਂਦੀ ਹੈ?",["ਹਵਾਈ ਅੱਡਾ → ਕਣਕ ਦਾ ਖੇਤ","ਚੂਨਾ ਪੱਥਰ ਪੱਟੀ → ਸੀਮਿੰਟ ਪਲਾਂਟ","ਬੈਂਕਿੰਗ ਇਲਾਕਾ → ਲੋਹੇ ਦੀ ਖਾਣ","ਸਾਫ਼ਟਵੇਅਰ ਪਾਰਕ → ਗੰਨੇ ਦਾ ਖੇਤ"],"ਸੀਮਿੰਟ ਪਲਾਂਟਾਂ ਨੂੰ ਵੱਡੀ ਮਾਤਰਾ ਵਿੱਚ ਚੂਨਾ ਪੱਥਰ ਚਾਹੀਦਾ ਹੈ, ਇਸ ਲਈ ਚੂਨਾ ਪੱਥਰ ਦੇ ਭੰਡਾਰਾਂ ਦੇ ਨੇੜੇ ਹੋਣਾ ਸਥਾਨੀਕਰਨ ਦਾ ਇੱਕ ਮਹੱਤਵਪੂਰਨ ਲਾਭ ਹੈ।"]},
"GEO-IND-001-CP001-Q030":{"h":"b4ef9ff7","hi":["कच्चे माल की निकटता कब कम निर्णायक हो जाती है?",["जब कच्चा माल और भारी हो जाए","जब परिवहन असंभव हो जाए","जब कच्चा माल हल्का हो, आसानी से ढोया जा सके या कुल लागत का छोटा हिस्सा हो","जब उद्योग में कोई प्रौद्योगिकी न लगे"],"बेहतर परिवहन और हल्के या अधिक मूल्य वाले कच्चे माल से कच्चे माल की निकटता का महत्व घट जाता है। इसी से अधिक अवस्थिति-मुक्त औद्योगिक प्रतिरूप समझ में आते हैं।"],"pa":["ਕੱਚੇ ਮਾਲ ਦੀ ਨੇੜਤਾ ਕਦੋਂ ਘੱਟ ਫ਼ੈਸਲਾਕੁੰਨ ਹੋ ਜਾਂਦੀ ਹੈ?",["ਜਦੋਂ ਕੱਚਾ ਮਾਲ ਹੋਰ ਭਾਰੀ ਹੋ ਜਾਵੇ","ਜਦੋਂ ਆਵਾਜਾਈ ਅਸੰਭਵ ਹੋ ਜਾਵੇ","ਜਦੋਂ ਕੱਚਾ ਮਾਲ ਹਲਕਾ ਹੋਵੇ, ਸੌਖਿਆਂ ਢੋਇਆ ਜਾ ਸਕੇ ਜਾਂ ਕੁੱਲ ਲਾਗਤ ਦਾ ਛੋਟਾ ਹਿੱਸਾ ਹੋਵੇ","ਜਦੋਂ ਉਦਯੋਗ ਵਿੱਚ ਕੋਈ ਤਕਨਾਲੋਜੀ ਨਾ ਵਰਤੀ ਜਾਵੇ"],"ਬਿਹਤਰ ਆਵਾਜਾਈ ਅਤੇ ਹਲਕੇ ਜਾਂ ਵੱਧ ਕੀਮਤ ਵਾਲੇ ਕੱਚੇ ਮਾਲ ਨਾਲ ਕੱਚੇ ਮਾਲ ਦੀ ਨੇੜਤਾ ਦੀ ਮਹੱਤਤਾ ਘਟਦੀ ਹੈ। ਇਸ ਨਾਲ ਵਧੇਰੇ ਸਥਾਨ-ਮੁਕਤ ਉਦਯੋਗਿਕ ਨਮੂਨੇ ਸਮਝ ਆਉਂਦੇ ਹਨ।"]},
"GEO-IND-001-CP001-Q031":{"h":"6fd16389","hi":["कौन-सा उद्योग विशेष रूप से अधिक बिजली खपत वाला है?",["एल्युमिनियम प्रगलन","हथकरघा बुनाई","पुस्तकों की खुदरा बिक्री","चाय की नीलामी"],"एल्युमिनियम प्रगलन में बहुत अधिक बिजली लगती है, इसलिए भरोसेमंद और अपेक्षाकृत सस्ती बिजली उसकी अवस्थिति का प्रमुख कारक है।"],"pa":["ਕਿਹੜਾ ਉਦਯੋਗ ਖ਼ਾਸ ਤੌਰ 'ਤੇ ਬਹੁਤ ਬਿਜਲੀ ਖਪਤ ਕਰਨ ਵਾਲਾ ਹੈ?",["ਐਲੂਮੀਨੀਅਮ ਪਿਘਲਾਈ","ਹੱਥ-ਖੱਡੀ ਬੁਣਾਈ","ਕਿਤਾਬਾਂ ਦੀ ਪਰਚੂਨ ਵਿਕਰੀ","ਚਾਹ ਦੀ ਨਿਲਾਮੀ"],"ਐਲੂਮੀਨੀਅਮ ਪਿਘਲਾਈ ਵਿੱਚ ਬਹੁਤ ਵੱਧ ਬਿਜਲੀ ਲੱਗਦੀ ਹੈ, ਇਸ ਲਈ ਭਰੋਸੇਯੋਗ ਅਤੇ ਤੁਲਨਾਤਮਕ ਤੌਰ 'ਤੇ ਸਸਤੀ ਬਿਜਲੀ ਇਸ ਦੇ ਸਥਾਨੀਕਰਨ ਦਾ ਮੁੱਖ ਕਾਰਕ ਹੈ।"]},
"GEO-IND-001-CP001-Q032":{"h":"92bba1a9","hi":["विनिर्माण के लिए बिजली आपूर्ति क्यों महत्वपूर्ण है?",["उद्योग बिना ऊर्जा के चलते हैं","मशीनों, भट्टियों और उत्पादन प्रणालियों को भरोसेमंद ऊर्जा चाहिए","बिजली केवल कृषि को प्रभावित करती है","बिजली केवल कार्यालय की रोशनी के लिए प्रयुक्त होती है"],"आधुनिक कारखाने मशीनों, तापन, शीतलन और प्रक्रिया नियंत्रण के लिए बिजली पर निर्भर हैं। इसलिए ऊर्जा की उपलब्धता अवस्थिति और संचालन लागत दोनों को प्रभावित करती है।"],"pa":["ਨਿਰਮਾਣ ਲਈ ਬਿਜਲੀ ਸਪਲਾਈ ਮਹੱਤਵਪੂਰਨ ਕਿਉਂ ਹੈ?",["ਉਦਯੋਗ ਬਿਨਾਂ ਊਰਜਾ ਦੇ ਚੱਲਦੇ ਹਨ","ਮਸ਼ੀਨਾਂ, ਭੱਠੀਆਂ ਅਤੇ ਉਤਪਾਦਨ ਪ੍ਰਣਾਲੀਆਂ ਨੂੰ ਭਰੋਸੇਯੋਗ ਊਰਜਾ ਚਾਹੀਦੀ ਹੈ","ਬਿਜਲੀ ਸਿਰਫ਼ ਖੇਤੀ ਨੂੰ ਪ੍ਰਭਾਵਿਤ ਕਰਦੀ ਹੈ","ਬਿਜਲੀ ਸਿਰਫ਼ ਦਫ਼ਤਰ ਦੀ ਰੋਸ਼ਨੀ ਲਈ ਵਰਤੀ ਜਾਂਦੀ ਹੈ"],"ਆਧੁਨਿਕ ਕਾਰਖ਼ਾਨੇ ਮਸ਼ੀਨਾਂ, ਗਰਮ ਕਰਨ, ਠੰਢਾ ਕਰਨ ਅਤੇ ਪ੍ਰਕਿਰਿਆ ਕੰਟਰੋਲ ਲਈ ਬਿਜਲੀ 'ਤੇ ਨਿਰਭਰ ਹਨ। ਇਸ ਲਈ ਊਰਜਾ ਦੀ ਉਪਲਬਧਤਾ ਸਥਾਨ ਅਤੇ ਸੰਚਾਲਨ ਲਾਗਤ ਦੋਵਾਂ ਨੂੰ ਪ੍ਰਭਾਵਿਤ ਕਰਦੀ ਹੈ।"]},
"GEO-IND-001-CP001-Q033":{"h":"0676ccf2","hi":["कथनों पर विचार कीजिए: I. एल्युमिनियम प्रगलन में बहुत अधिक बिजली लगती है। II. भरोसेमंद बिजली औद्योगिक अवस्थिति को प्रभावित कर सकती है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","I और II दोनों सही हैं","न तो I और न ही II सही है"],"एल्युमिनियम अधिक बिजली खपत वाले उद्योग का उत्कृष्ट उदाहरण है, और भरोसेमंद ऊर्जा आपूर्ति औद्योगिक अवस्थिति का एक प्रमुख कारक है।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਐਲੂਮੀਨੀਅਮ ਪਿਘਲਾਈ ਵਿੱਚ ਬਹੁਤ ਬਿਜਲੀ ਲੱਗਦੀ ਹੈ। II. ਭਰੋਸੇਯੋਗ ਬਿਜਲੀ ਉਦਯੋਗਿਕ ਸਥਾਨੀਕਰਨ ਨੂੰ ਪ੍ਰਭਾਵਿਤ ਕਰ ਸਕਦੀ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਐਲੂਮੀਨੀਅਮ ਬਹੁਤ ਬਿਜਲੀ ਖਪਤ ਕਰਨ ਵਾਲੇ ਉਦਯੋਗ ਦੀ ਉੱਤਮ ਉਦਾਹਰਨ ਹੈ, ਅਤੇ ਭਰੋਸੇਯੋਗ ਊਰਜਾ ਸਪਲਾਈ ਉਦਯੋਗਿਕ ਸਥਾਨੀਕਰਨ ਦਾ ਇੱਕ ਮੁੱਖ ਕਾਰਕ ਹੈ।"]},
"GEO-IND-001-CP001-Q034":{"h":"ed5ee00a","hi":["अत्यधिक बिजली खपत वाले उद्योग के लिए कौन-सा स्थान सबसे उपयुक्त होगा?",["बार-बार लंबी बिजली कटौती वाला क्षेत्र","बिना ग्रिड कनेक्शन वाला स्थल","केवल प्राकृतिक सुंदरता के आधार पर चुना गया स्थान","बड़े पैमाने पर भरोसेमंद बिजली आपूर्ति वाला क्षेत्र"],"अधिक बिजली खपत वाले उद्योगों को प्रतिस्पर्धी लागत पर भरोसेमंद ऊर्जा चाहिए। इसलिए विश्वसनीय बिजली एक मज़बूत अवस्थितिक लाभ बन जाती है।"],"pa":["ਬਹੁਤ ਜ਼ਿਆਦਾ ਬਿਜਲੀ ਖਪਤ ਵਾਲੇ ਉਦਯੋਗ ਲਈ ਕਿਹੜੀ ਥਾਂ ਸਭ ਤੋਂ ਢੁਕਵੀਂ ਹੋਵੇਗੀ?",["ਵਾਰ-ਵਾਰ ਲੰਮੇ ਬਿਜਲੀ ਕੱਟਾਂ ਵਾਲਾ ਖੇਤਰ","ਬਿਨਾਂ ਗਰਿੱਡ ਕੁਨੈਕਸ਼ਨ ਵਾਲੀ ਥਾਂ","ਸਿਰਫ਼ ਕੁਦਰਤੀ ਸੁੰਦਰਤਾ ਲਈ ਚੁਣੀ ਗਈ ਥਾਂ","ਵੱਡੇ ਪੱਧਰ 'ਤੇ ਭਰੋਸੇਯੋਗ ਬਿਜਲੀ ਸਪਲਾਈ ਵਾਲਾ ਖੇਤਰ"],"ਬਹੁਤ ਬਿਜਲੀ ਖਪਤ ਵਾਲੇ ਉਦਯੋਗਾਂ ਨੂੰ ਮੁਕਾਬਲੇਬਾਜ਼ ਲਾਗਤ 'ਤੇ ਭਰੋਸੇਯੋਗ ਊਰਜਾ ਚਾਹੀਦੀ ਹੈ। ਇਸ ਲਈ ਭਰੋਸੇਯੋਗ ਬਿਜਲੀ ਇੱਕ ਮਜ਼ਬੂਤ ਸਥਾਨਕ ਲਾਭ ਬਣ ਜਾਂਦੀ ਹੈ।"]},
"GEO-IND-001-CP001-Q035":{"h":"0b192e84","hi":["कौन-सा संसाधन संबंध एल्युमिनियम उत्पादन को आकर्षित कर सकता है?",["सस्ती और प्रचुर बिजली","केवल प्रचुर जूट","बिजली के बिना भारी वर्षा","सभी पारेषण लाइनों से दूरी"],"बॉक्साइट अयस्क कच्चा माल है, पर एल्युमिनियम प्रगलन में भारी मात्रा में बिजली लगती है। इसलिए ऊर्जा लागत संयंत्र की अवस्थिति को बहुत प्रभावित करती है।"],"pa":["ਕਿਹੜਾ ਸਾਧਨ-ਸੰਬੰਧ ਐਲੂਮੀਨੀਅਮ ਉਤਪਾਦਨ ਨੂੰ ਖਿੱਚ ਸਕਦਾ ਹੈ?",["ਸਸਤੀ ਅਤੇ ਭਰਪੂਰ ਬਿਜਲੀ","ਸਿਰਫ਼ ਭਰਪੂਰ ਪਟਸਨ","ਬਿਜਲੀ ਤੋਂ ਬਿਨਾਂ ਭਾਰੀ ਵਰਖਾ","ਸਾਰੀਆਂ ਟਰਾਂਸਮਿਸ਼ਨ ਲਾਈਨਾਂ ਤੋਂ ਦੂਰੀ"],"ਬਾਕਸਾਈਟ ਕੱਚੀ ਧਾਤ ਕੱਚਾ ਮਾਲ ਹੈ, ਪਰ ਐਲੂਮੀਨੀਅਮ ਪਿਘਲਾਈ ਵਿੱਚ ਬੇਹੱਦ ਬਿਜਲੀ ਲੱਗਦੀ ਹੈ। ਇਸ ਲਈ ਊਰਜਾ ਦੀ ਲਾਗਤ ਪਲਾਂਟ ਦੇ ਸਥਾਨ ਨੂੰ ਬਹੁਤ ਪ੍ਰਭਾਵਿਤ ਕਰਦੀ ਹੈ।"]},
"GEO-IND-001-CP001-Q036":{"h":"94a47dc4","hi":["जलविद्युत-संपन्न क्षेत्र कुछ अधिक बिजली खपत वाले उद्योगों को क्यों आकर्षित कर सकते हैं?",["जलविद्युत लौह अयस्क देती है","वे बड़ी मात्रा में बिजली उपलब्ध करा सकते हैं","जलविद्युत परिवहन की आवश्यकता समाप्त कर देती है","जलविद्युत कपास पैदा करती है"],"अधिक बिजली खपत वाले उद्योगों को बड़ी और अपेक्षाकृत किफ़ायती बिजली आपूर्ति से लाभ होता है। ऐतिहासिक रूप से जलविद्युत की उपलब्धता ने कुछ औद्योगिक अवस्थितियों को प्रभावित किया है।"],"pa":["ਪਣ-ਬਿਜਲੀ ਨਾਲ ਭਰਪੂਰ ਖੇਤਰ ਕੁਝ ਬਹੁਤ ਬਿਜਲੀ ਖਪਤ ਵਾਲੇ ਉਦਯੋਗਾਂ ਨੂੰ ਕਿਉਂ ਖਿੱਚ ਸਕਦੇ ਹਨ?",["ਪਣ-ਬਿਜਲੀ ਕੱਚਾ ਲੋਹਾ ਦਿੰਦੀ ਹੈ","ਉਹ ਵੱਡੀ ਮਾਤਰਾ ਵਿੱਚ ਬਿਜਲੀ ਮੁਹੱਈਆ ਕਰ ਸਕਦੇ ਹਨ","ਪਣ-ਬਿਜਲੀ ਆਵਾਜਾਈ ਦੀ ਲੋੜ ਖ਼ਤਮ ਕਰ ਦਿੰਦੀ ਹੈ","ਪਣ-ਬਿਜਲੀ ਕਪਾਹ ਪੈਦਾ ਕਰਦੀ ਹੈ"],"ਬਹੁਤ ਬਿਜਲੀ ਖਪਤ ਵਾਲੇ ਉਦਯੋਗਾਂ ਨੂੰ ਵੱਡੀ ਅਤੇ ਤੁਲਨਾਤਮਕ ਤੌਰ 'ਤੇ ਕਿਫ਼ਾਇਤੀ ਬਿਜਲੀ ਸਪਲਾਈ ਤੋਂ ਲਾਭ ਹੁੰਦਾ ਹੈ। ਇਤਿਹਾਸਕ ਤੌਰ 'ਤੇ ਪਣ-ਬਿਜਲੀ ਦੀ ਉਪਲਬਧਤਾ ਨੇ ਕੁਝ ਉਦਯੋਗਿਕ ਸਥਾਨਾਂ ਨੂੰ ਪ੍ਰਭਾਵਿਤ ਕੀਤਾ ਹੈ।"]},
"GEO-IND-001-CP001-Q037":{"h":"f7d89863","hi":["उपयुक्त कौशल वाले श्रमिकों की उपलब्धता किस औद्योगिक अवस्थिति कारक को दर्शाती है?",["केवल उच्चावच","श्रम","केवल वर्षा","खनिज निर्माण"],"उद्योगों को उपयुक्त कौशल और उत्पादकता वाले श्रमिक चाहिए। इसलिए श्रम की उपलब्धता यह तय कर सकती है कि कुछ विनिर्माण क्रियाएँ कहाँ केंद्रित हों।"],"pa":["ਢੁਕਵੇਂ ਹੁਨਰ ਵਾਲੇ ਕਾਮਿਆਂ ਦੀ ਉਪਲਬਧਤਾ ਕਿਸ ਉਦਯੋਗਿਕ ਸਥਾਨੀਕਰਨ ਕਾਰਕ ਨੂੰ ਦਰਸਾਉਂਦੀ ਹੈ?",["ਸਿਰਫ਼ ਧਰਾਤਲ","ਕਿਰਤ","ਸਿਰਫ਼ ਵਰਖਾ","ਖਣਿਜਾਂ ਦਾ ਬਣਨਾ"],"ਉਦਯੋਗਾਂ ਨੂੰ ਢੁਕਵੇਂ ਹੁਨਰ ਅਤੇ ਉਤਪਾਦਕਤਾ ਵਾਲੇ ਕਾਮੇ ਚਾਹੀਦੇ ਹਨ। ਇਸ ਲਈ ਕਿਰਤ ਦੀ ਉਪਲਬਧਤਾ ਇਹ ਤੈਅ ਕਰ ਸਕਦੀ ਹੈ ਕਿ ਕੁਝ ਨਿਰਮਾਣ ਕਿਰਿਆਵਾਂ ਕਿੱਥੇ ਕੇਂਦਰਿਤ ਹੋਣ।"]},
"GEO-IND-001-CP001-Q038":{"h":"10d895e5","hi":["औद्योगिक अवस्थिति और विकास के लिए पूँजी क्यों महत्वपूर्ण है?",["पूँजी मानसून वर्षा तय करती है","उद्योगों को किसी निवेश की आवश्यकता नहीं होती","कारखानों को भूमि, मशीनरी, प्रौद्योगिकी और दैनिक संचालन में निवेश चाहिए","पूँजी सभी कच्चे माल की जगह ले लेती है"],"औद्योगिक विकास के लिए स्थायी परिसंपत्तियों और निरंतर संचालन हेतु वित्त चाहिए। इसलिए पूँजी तक पहुँच अच्छी तरह जुड़े व्यावसायिक केंद्रों में उद्योगों के केंद्रीकरण को बढ़ावा देती है।"],"pa":["ਉਦਯੋਗਿਕ ਸਥਾਨੀਕਰਨ ਅਤੇ ਵਿਕਾਸ ਲਈ ਪੂੰਜੀ ਮਹੱਤਵਪੂਰਨ ਕਿਉਂ ਹੈ?",["ਪੂੰਜੀ ਮਾਨਸੂਨੀ ਵਰਖਾ ਤੈਅ ਕਰਦੀ ਹੈ","ਉਦਯੋਗਾਂ ਨੂੰ ਕਿਸੇ ਨਿਵੇਸ਼ ਦੀ ਲੋੜ ਨਹੀਂ ਹੁੰਦੀ","ਕਾਰਖ਼ਾਨਿਆਂ ਨੂੰ ਜ਼ਮੀਨ, ਮਸ਼ੀਨਰੀ, ਤਕਨਾਲੋਜੀ ਅਤੇ ਰੋਜ਼ਾਨਾ ਸੰਚਾਲਨ ਵਿੱਚ ਨਿਵੇਸ਼ ਚਾਹੀਦਾ ਹੈ","ਪੂੰਜੀ ਸਾਰੇ ਕੱਚੇ ਮਾਲ ਦੀ ਥਾਂ ਲੈ ਲੈਂਦੀ ਹੈ"],"ਉਦਯੋਗਿਕ ਵਿਕਾਸ ਲਈ ਸਥਾਈ ਸੰਪਤੀਆਂ ਅਤੇ ਲਗਾਤਾਰ ਸੰਚਾਲਨ ਵਾਸਤੇ ਵਿੱਤ ਚਾਹੀਦਾ ਹੈ। ਇਸ ਲਈ ਪੂੰਜੀ ਤੱਕ ਪਹੁੰਚ ਚੰਗੀ ਤਰ੍ਹਾਂ ਜੁੜੇ ਕਾਰੋਬਾਰੀ ਕੇਂਦਰਾਂ ਵਿੱਚ ਉਦਯੋਗਾਂ ਦੇ ਇਕੱਠੇ ਹੋਣ ਨੂੰ ਉਤਸ਼ਾਹਿਤ ਕਰਦੀ ਹੈ।"]},
"GEO-IND-001-CP001-Q039":{"h":"0859a3fd","hi":["प्रौद्योगिकी औद्योगिक अवस्थिति के प्रतिरूप को कैसे बदल सकती है?",["यह कच्चे माल को हमेशा भारी बना देती है","यह बाज़ारों को पूरी तरह समाप्त कर देती है","यह परिवहन विकास को रोकती है","यह कुछ पारंपरिक अवस्थिति कारकों पर निर्भरता घटा सकती है"],"बेहतर प्रौद्योगिकी, परिवहन और संचार से उद्योगों को सीधे कच्चे माल या श्रम के पास लगाने की आवश्यकता घटती है। इससे कुछ उद्योग अवस्थिति के मामले में अधिक लचीले बन जाते हैं।"],"pa":["ਤਕਨਾਲੋਜੀ ਉਦਯੋਗਿਕ ਸਥਾਨੀਕਰਨ ਦੇ ਨਮੂਨੇ ਨੂੰ ਕਿਵੇਂ ਬਦਲ ਸਕਦੀ ਹੈ?",["ਇਹ ਕੱਚੇ ਮਾਲ ਨੂੰ ਹਮੇਸ਼ਾ ਭਾਰੀ ਬਣਾ ਦਿੰਦੀ ਹੈ","ਇਹ ਬਾਜ਼ਾਰਾਂ ਨੂੰ ਪੂਰੀ ਤਰ੍ਹਾਂ ਖ਼ਤਮ ਕਰ ਦਿੰਦੀ ਹੈ","ਇਹ ਆਵਾਜਾਈ ਦੇ ਵਿਕਾਸ ਨੂੰ ਰੋਕਦੀ ਹੈ","ਇਹ ਕੁਝ ਰਵਾਇਤੀ ਸਥਾਨੀਕਰਨ ਕਾਰਕਾਂ 'ਤੇ ਨਿਰਭਰਤਾ ਘਟਾ ਸਕਦੀ ਹੈ"],"ਬਿਹਤਰ ਤਕਨਾਲੋਜੀ, ਆਵਾਜਾਈ ਅਤੇ ਸੰਚਾਰ ਨਾਲ ਉਦਯੋਗਾਂ ਨੂੰ ਸਿੱਧੇ ਕੱਚੇ ਮਾਲ ਜਾਂ ਕਿਰਤ ਦੇ ਨੇੜੇ ਲਾਉਣ ਦੀ ਲੋੜ ਘਟਦੀ ਹੈ। ਇਸ ਨਾਲ ਕੁਝ ਉਦਯੋਗ ਸਥਾਨ ਪੱਖੋਂ ਵਧੇਰੇ ਲਚਕਦਾਰ ਬਣ ਜਾਂਦੇ ਹਨ।"]},
"GEO-IND-001-CP001-Q040":{"h":"b9af064d","hi":["कथनों पर विचार कीजिए: I. कुशल श्रम विशिष्ट उद्योगों को आकर्षित कर सकता है। II. पूँजी की उपलब्धता औद्योगिक विकास में सहायक हो सकती है। कौन-सा/से कथन सही है/हैं?",["I और II दोनों सही हैं","केवल I सही है","केवल II सही है","न तो I और न ही II सही है"],"विशिष्ट उद्योगों को कुशल श्रमिक चाहिए, जबकि संयंत्र, उपकरण और संचालन के लिए निवेश आवश्यक है। दोनों कारक औद्योगिक विकास को प्रभावित करते हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਹੁਨਰਮੰਦ ਕਿਰਤ ਖ਼ਾਸ ਉਦਯੋਗਾਂ ਨੂੰ ਖਿੱਚ ਸਕਦੀ ਹੈ। II. ਪੂੰਜੀ ਦੀ ਉਪਲਬਧਤਾ ਉਦਯੋਗਿਕ ਵਿਕਾਸ ਵਿੱਚ ਮਦਦ ਕਰ ਸਕਦੀ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਖ਼ਾਸ ਉਦਯੋਗਾਂ ਨੂੰ ਹੁਨਰਮੰਦ ਕਾਮੇ ਚਾਹੀਦੇ ਹਨ, ਜਦਕਿ ਪਲਾਂਟ, ਸਾਜ਼ੋ-ਸਾਮਾਨ ਅਤੇ ਸੰਚਾਲਨ ਲਈ ਨਿਵੇਸ਼ ਲੋੜੀਂਦਾ ਹੈ। ਦੋਵੇਂ ਕਾਰਕ ਉਦਯੋਗਿਕ ਵਿਕਾਸ ਨੂੰ ਪ੍ਰਭਾਵਿਤ ਕਰਦੇ ਹਨ।"]},
"GEO-IND-001-CP001-Q041":{"h":"9bc4a818","hi":["कौन-सा उद्योग अत्यधिक कुशल तकनीकी श्रम की उपलब्धता के प्रति विशेष रूप से संवेदनशील है?",["केवल पत्थर उत्खनन","उन्नत अभियांत्रिकी और इलेक्ट्रॉनिक्स","केवल नमक वाष्पन","पारंपरिक पशुचारण"],"उन्नत अभियांत्रिकी और इलेक्ट्रॉनिक्स कई बुनियादी निष्कर्षण क्रियाओं की तुलना में विशिष्ट तकनीकी कौशल, डिज़ाइन क्षमता और ज्ञान-आधारित श्रम पर अधिक निर्भर हैं।"],"pa":["ਕਿਹੜਾ ਉਦਯੋਗ ਬਹੁਤ ਹੁਨਰਮੰਦ ਤਕਨੀਕੀ ਕਿਰਤ ਦੀ ਉਪਲਬਧਤਾ ਪ੍ਰਤੀ ਖ਼ਾਸ ਤੌਰ 'ਤੇ ਸੰਵੇਦਨਸ਼ੀਲ ਹੈ?",["ਸਿਰਫ਼ ਪੱਥਰ ਕੱਢਣਾ","ਉੱਨਤ ਇੰਜੀਨੀਅਰਿੰਗ ਅਤੇ ਇਲੈਕਟ੍ਰਾਨਿਕਸ","ਸਿਰਫ਼ ਲੂਣ ਵਾਸ਼ਪੀਕਰਨ","ਰਵਾਇਤੀ ਪਸ਼ੂ-ਚਰਾਈ"],"ਉੱਨਤ ਇੰਜੀਨੀਅਰਿੰਗ ਅਤੇ ਇਲੈਕਟ੍ਰਾਨਿਕਸ ਕਈ ਬੁਨਿਆਦੀ ਨਿਕਾਸੀ ਕਿਰਿਆਵਾਂ ਨਾਲੋਂ ਖ਼ਾਸ ਤਕਨੀਕੀ ਹੁਨਰ, ਡਿਜ਼ਾਈਨ ਸਮਰੱਥਾ ਅਤੇ ਗਿਆਨ-ਅਧਾਰਿਤ ਕਿਰਤ 'ਤੇ ਵਧੇਰੇ ਨਿਰਭਰ ਹਨ।"]},
"GEO-IND-001-CP001-Q042":{"h":"7c8acb95","hi":["कच्चा माल दूर होने पर भी बड़े शहर आधुनिक उद्योगों को क्यों आकर्षित कर सकते हैं?",["शहर खनिज अयस्क बनाते हैं","शहर बाज़ार की आवश्यकता समाप्त कर देते हैं","वहाँ कुशल श्रम, वित्त, सेवाएँ और अवसंरचना एक साथ उपलब्ध होते हैं","शहरी क्षेत्रों में कोई परिवहन लागत नहीं होती"],"बड़े शहरी केंद्र कुशल श्रमिक, बैंकिंग, व्यावसायिक सेवाएँ, परिवहन और बड़े बाज़ार जैसे अनेक औद्योगिक लाभ देते हैं।"],"pa":["ਕੱਚਾ ਮਾਲ ਦੂਰ ਹੋਣ ਦੇ ਬਾਵਜੂਦ ਵੱਡੇ ਸ਼ਹਿਰ ਆਧੁਨਿਕ ਉਦਯੋਗਾਂ ਨੂੰ ਕਿਉਂ ਖਿੱਚ ਸਕਦੇ ਹਨ?",["ਸ਼ਹਿਰ ਖਣਿਜ ਕੱਚੀਆਂ ਧਾਤਾਂ ਬਣਾਉਂਦੇ ਹਨ","ਸ਼ਹਿਰ ਬਾਜ਼ਾਰਾਂ ਦੀ ਲੋੜ ਖ਼ਤਮ ਕਰ ਦਿੰਦੇ ਹਨ","ਉੱਥੇ ਹੁਨਰਮੰਦ ਕਿਰਤ, ਵਿੱਤ, ਸੇਵਾਵਾਂ ਅਤੇ ਬੁਨਿਆਦੀ ਢਾਂਚਾ ਇਕੱਠੇ ਮਿਲਦੇ ਹਨ","ਸ਼ਹਿਰੀ ਖੇਤਰਾਂ ਵਿੱਚ ਕੋਈ ਢੋਆ-ਢੁਆਈ ਲਾਗਤ ਨਹੀਂ ਹੁੰਦੀ"],"ਵੱਡੇ ਸ਼ਹਿਰੀ ਕੇਂਦਰ ਹੁਨਰਮੰਦ ਕਾਮੇ, ਬੈਂਕਿੰਗ, ਕਾਰੋਬਾਰੀ ਸੇਵਾਵਾਂ, ਆਵਾਜਾਈ ਅਤੇ ਵੱਡੇ ਬਾਜ਼ਾਰ ਵਰਗੇ ਕਈ ਉਦਯੋਗਿਕ ਲਾਭ ਦਿੰਦੇ ਹਨ।"]},
"GEO-IND-001-CP001-Q043":{"h":"f62edf78","hi":["औद्योगिक अवस्थिति के लिए परिवहन क्यों महत्वपूर्ण है?",["यह खनिजों का रसायन तय करता है","यह कच्चा माल कारखानों तक और तैयार माल बाज़ारों तक पहुँचाता है","यह श्रम की पूरी तरह जगह ले लेता है","यह उत्पादन लागत समाप्त कर देता है"],"उद्योग आने वाले कच्चे माल और बाहर जाने वाले उत्पाद, दोनों के लिए परिवहन पर निर्भर हैं। अच्छी कनेक्टिविटी से लॉजिस्टिक्स लागत काफ़ी कम हो सकती है।"],"pa":["ਉਦਯੋਗਿਕ ਸਥਾਨੀਕਰਨ ਲਈ ਆਵਾਜਾਈ ਮਹੱਤਵਪੂਰਨ ਕਿਉਂ ਹੈ?",["ਇਹ ਖਣਿਜਾਂ ਦੀ ਰਸਾਇਣਕ ਬਣਤਰ ਤੈਅ ਕਰਦੀ ਹੈ","ਇਹ ਕੱਚਾ ਮਾਲ ਕਾਰਖ਼ਾਨਿਆਂ ਤੱਕ ਅਤੇ ਤਿਆਰ ਮਾਲ ਬਾਜ਼ਾਰਾਂ ਤੱਕ ਪਹੁੰਚਾਉਂਦੀ ਹੈ","ਇਹ ਕਿਰਤ ਦੀ ਪੂਰੀ ਥਾਂ ਲੈ ਲੈਂਦੀ ਹੈ","ਇਹ ਉਤਪਾਦਨ ਲਾਗਤ ਖ਼ਤਮ ਕਰ ਦਿੰਦੀ ਹੈ"],"ਉਦਯੋਗ ਆਉਣ ਵਾਲੇ ਕੱਚੇ ਮਾਲ ਅਤੇ ਬਾਹਰ ਜਾਣ ਵਾਲੇ ਉਤਪਾਦ ਦੋਵਾਂ ਲਈ ਆਵਾਜਾਈ 'ਤੇ ਨਿਰਭਰ ਹਨ। ਚੰਗੀ ਕਨੈਕਟੀਵਿਟੀ ਨਾਲ ਲੌਜਿਸਟਿਕਸ ਲਾਗਤ ਕਾਫ਼ੀ ਘਟ ਸਕਦੀ ਹੈ।"]},
"GEO-IND-001-CP001-Q044":{"h":"b1402a0c","hi":["किस उद्योग को बड़े उपभोक्ता बाज़ार के पास स्थापित होने से सबसे अधिक लाभ होगा?",["अयस्क निकालने वाली दूरस्थ खदान","अपतटीय वेधन प्लेटफ़ॉर्म","भारी या शीघ्र खराब होने वाली उपभोक्ता वस्तुएँ बनाने वाला उद्योग","वन बागान"],"जब तैयार उत्पाद भारी हों, उन्हें ढोना महँगा हो या वे समय-संवेदनशील हों, तब बाज़ार-उन्मुख उद्योगों को उपभोक्ताओं के पास होने से लाभ होता है।"],"pa":["ਕਿਹੜੇ ਉਦਯੋਗ ਨੂੰ ਵੱਡੇ ਖਪਤਕਾਰ ਬਾਜ਼ਾਰ ਦੇ ਨੇੜੇ ਲੱਗਣ ਨਾਲ ਸਭ ਤੋਂ ਵੱਧ ਲਾਭ ਹੋਵੇਗਾ?",["ਕੱਚੀ ਧਾਤ ਕੱਢਣ ਵਾਲੀ ਦੂਰ-ਦੁਰਾਡੀ ਖਾਣ","ਸਮੁੰਦਰ ਅੰਦਰਲਾ ਡ੍ਰਿਲਿੰਗ ਪਲੇਟਫ਼ਾਰਮ","ਭਾਰੀ ਜਾਂ ਜਲਦੀ ਖ਼ਰਾਬ ਹੋਣ ਵਾਲੀਆਂ ਖਪਤਕਾਰੀ ਵਸਤਾਂ ਬਣਾਉਣ ਵਾਲਾ ਉਦਯੋਗ","ਜੰਗਲੀ ਬਾਗ਼ਾਨ"],"ਜਦੋਂ ਤਿਆਰ ਉਤਪਾਦ ਭਾਰੀ ਹੋਣ, ਉਨ੍ਹਾਂ ਨੂੰ ਢੋਣਾ ਮਹਿੰਗਾ ਹੋਵੇ ਜਾਂ ਉਹ ਸਮੇਂ-ਸੰਵੇਦਨਸ਼ੀਲ ਹੋਣ, ਤਾਂ ਬਾਜ਼ਾਰ-ਮੁਖੀ ਉਦਯੋਗਾਂ ਨੂੰ ਖਪਤਕਾਰਾਂ ਦੇ ਨੇੜੇ ਹੋਣ ਦਾ ਲਾਭ ਹੁੰਦਾ ਹੈ।"]},
"GEO-IND-001-CP001-Q045":{"h":"00ef4bdf","hi":["कथनों पर विचार कीजिए: I. अच्छा परिवहन किसी उद्योग का बाज़ार बढ़ा सकता है। II. बड़े शहरी बाज़ार उपभोक्ता वस्तु उद्योगों को आकर्षित कर सकते हैं। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","न तो I और न ही II सही है","I और II दोनों सही हैं"],"परिवहन ग्राहकों तक पहुँच बढ़ाता है, जबकि बड़े शहर केंद्रित माँग उपलब्ध कराते हैं। दोनों कारक औद्योगिक अवस्थिति को बहुत प्रभावित कर सकते हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਚੰਗੀ ਆਵਾਜਾਈ ਕਿਸੇ ਉਦਯੋਗ ਦਾ ਬਾਜ਼ਾਰ ਵਧਾ ਸਕਦੀ ਹੈ। II. ਵੱਡੇ ਸ਼ਹਿਰੀ ਬਾਜ਼ਾਰ ਖਪਤਕਾਰੀ ਵਸਤਾਂ ਦੇ ਉਦਯੋਗਾਂ ਨੂੰ ਖਿੱਚ ਸਕਦੇ ਹਨ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ"],"ਆਵਾਜਾਈ ਗਾਹਕਾਂ ਤੱਕ ਪਹੁੰਚ ਵਧਾਉਂਦੀ ਹੈ, ਜਦਕਿ ਵੱਡੇ ਸ਼ਹਿਰ ਕੇਂਦਰਿਤ ਮੰਗ ਦਿੰਦੇ ਹਨ। ਦੋਵੇਂ ਕਾਰਕ ਉਦਯੋਗਿਕ ਸਥਾਨੀਕਰਨ ਨੂੰ ਬਹੁਤ ਪ੍ਰਭਾਵਿਤ ਕਰ ਸਕਦੇ ਹਨ।"]},
"GEO-IND-001-CP001-Q046":{"h":"e2dc89a3","hi":["किसी बड़े कारखाने के लिए किस स्थल पर परिवहन का सबसे अधिक लाभ है?",["सड़क, रेल और प्रमुख माल-ढुलाई मार्गों से जुड़ा स्थान","सभी परिवहन से कटा हुआ स्थल","केवल पैदल पहुँचने योग्य स्थान","बाज़ार तक पहुँच के बिना चुना गया स्थान"],"परिवहन के अनेक साधन विश्वसनीयता बढ़ाते हैं और लॉजिस्टिक्स की बाधाएँ घटाते हैं। ऐसी कनेक्टिविटी बड़े पैमाने के विनिर्माण के लिए एक बड़ा लाभ है।"],"pa":["ਕਿਸੇ ਵੱਡੇ ਕਾਰਖ਼ਾਨੇ ਲਈ ਕਿਸ ਥਾਂ 'ਤੇ ਆਵਾਜਾਈ ਦਾ ਸਭ ਤੋਂ ਵੱਧ ਲਾਭ ਹੈ?",["ਸੜਕ, ਰੇਲ ਅਤੇ ਮੁੱਖ ਮਾਲ-ਢੁਆਈ ਮਾਰਗਾਂ ਨਾਲ ਜੁੜੀ ਥਾਂ","ਹਰ ਤਰ੍ਹਾਂ ਦੀ ਆਵਾਜਾਈ ਤੋਂ ਕੱਟੀ ਥਾਂ","ਸਿਰਫ਼ ਪੈਦਲ ਪਹੁੰਚਣਯੋਗ ਥਾਂ","ਬਾਜ਼ਾਰ ਤੱਕ ਪਹੁੰਚ ਤੋਂ ਬਿਨਾਂ ਚੁਣੀ ਥਾਂ"],"ਆਵਾਜਾਈ ਦੇ ਕਈ ਸਾਧਨ ਭਰੋਸੇਯੋਗਤਾ ਵਧਾਉਂਦੇ ਹਨ ਅਤੇ ਲੌਜਿਸਟਿਕਸ ਦੀਆਂ ਰੁਕਾਵਟਾਂ ਘਟਾਉਂਦੇ ਹਨ। ਅਜਿਹੀ ਕਨੈਕਟੀਵਿਟੀ ਵੱਡੇ ਪੱਧਰ ਦੇ ਨਿਰਮਾਣ ਲਈ ਵੱਡਾ ਲਾਭ ਹੈ।"]},
"GEO-IND-001-CP001-Q047":{"h":"3fbb38fd","hi":["आयातित कच्चे माल का उपयोग करने वाले उद्योगों को पत्तन नगर क्यों आकर्षित कर सकते हैं?",["पत्तन सारा कच्चा माल स्थानीय रूप से पैदा करते हैं","पत्तन भारी आयातों के लिए आवश्यक आंतरिक परिवहन घटाते हैं","जहाज़ बाज़ार की आवश्यकता समाप्त कर देते हैं","पत्तन उद्योगों में श्रम नहीं लगता"],"आयातित भारी सामग्री पर निर्भर उद्योग पत्तनों के पास स्थापित होकर परिवहन लागत घटा सकते हैं। पत्तन तक पहुँच से तैयार माल का निर्यात भी आसान होता है।"],"pa":["ਆਯਾਤ ਕੀਤੇ ਕੱਚੇ ਮਾਲ ਦੀ ਵਰਤੋਂ ਕਰਨ ਵਾਲੇ ਉਦਯੋਗਾਂ ਨੂੰ ਬੰਦਰਗਾਹੀ ਸ਼ਹਿਰ ਕਿਉਂ ਖਿੱਚ ਸਕਦੇ ਹਨ?",["ਬੰਦਰਗਾਹਾਂ ਸਾਰਾ ਕੱਚਾ ਮਾਲ ਸਥਾਨਕ ਤੌਰ 'ਤੇ ਪੈਦਾ ਕਰਦੀਆਂ ਹਨ","ਬੰਦਰਗਾਹਾਂ ਭਾਰੀ ਆਯਾਤ ਲਈ ਲੋੜੀਂਦੀ ਅੰਦਰੂਨੀ ਢੋਆ-ਢੁਆਈ ਘਟਾਉਂਦੀਆਂ ਹਨ","ਜਹਾਜ਼ ਬਾਜ਼ਾਰਾਂ ਦੀ ਲੋੜ ਖ਼ਤਮ ਕਰ ਦਿੰਦੇ ਹਨ","ਬੰਦਰਗਾਹੀ ਉਦਯੋਗਾਂ ਵਿੱਚ ਕਿਰਤ ਨਹੀਂ ਲੱਗਦੀ"],"ਆਯਾਤ ਕੀਤੀ ਭਾਰੀ ਸਮੱਗਰੀ 'ਤੇ ਨਿਰਭਰ ਉਦਯੋਗ ਬੰਦਰਗਾਹਾਂ ਦੇ ਨੇੜੇ ਲੱਗ ਕੇ ਢੋਆ-ਢੁਆਈ ਲਾਗਤ ਘਟਾ ਸਕਦੇ ਹਨ। ਬੰਦਰਗਾਹ ਤੱਕ ਪਹੁੰਚ ਨਾਲ ਤਿਆਰ ਮਾਲ ਦਾ ਨਿਰਯਾਤ ਵੀ ਸੌਖਾ ਹੁੰਦਾ ਹੈ।"]},
"GEO-IND-001-CP001-Q048":{"h":"9135f508","hi":["किसी उपभोक्ता वस्तु कारखाने को महानगर के पास लगाने का कारण कौन-सा कारक है?",["लौह अयस्क की उपस्थिति","कोयला परत की उपस्थिति","बड़ा बाज़ार","ऊँचा पर्वतीय उच्चावच"],"महानगरों में उपभोक्ता और क्रय शक्ति केंद्रित होती है, जिससे अनेक उपभोक्ता-उन्मुख उद्योगों को बाज़ार का मज़बूत लाभ मिलता है।"],"pa":["ਕਿਸੇ ਖਪਤਕਾਰੀ ਵਸਤਾਂ ਦੇ ਕਾਰਖ਼ਾਨੇ ਨੂੰ ਮਹਾਂਨਗਰ ਦੇ ਨੇੜੇ ਲਾਉਣ ਦਾ ਕਾਰਨ ਕਿਹੜਾ ਕਾਰਕ ਹੈ?",["ਕੱਚੇ ਲੋਹੇ ਦੀ ਮੌਜੂਦਗੀ","ਕੋਲੇ ਦੀ ਪਰਤ ਦੀ ਮੌਜੂਦਗੀ","ਵੱਡਾ ਬਾਜ਼ਾਰ","ਉੱਚਾ ਪਹਾੜੀ ਧਰਾਤਲ"],"ਮਹਾਂਨਗਰਾਂ ਵਿੱਚ ਖਪਤਕਾਰ ਅਤੇ ਖ਼ਰੀਦ ਸ਼ਕਤੀ ਕੇਂਦਰਿਤ ਹੁੰਦੀ ਹੈ, ਜਿਸ ਨਾਲ ਕਈ ਖਪਤਕਾਰ-ਮੁਖੀ ਉਦਯੋਗਾਂ ਨੂੰ ਬਾਜ਼ਾਰ ਦਾ ਮਜ਼ਬੂਤ ਲਾਭ ਮਿਲਦਾ ਹੈ।"]},
"GEO-IND-001-CP001-Q049":{"h":"40072948","hi":["औद्योगिक समूहन क्या है?",["साझा लाभ पाने के लिए एक ही क्षेत्र में उद्योगों का केंद्रीकरण","सभी कारखानों का पूर्ण बिखराव","किसी क्षेत्र के सभी उद्योगों का बंद होना","कारखानों पर केवल सरकारी स्वामित्व"],"समूहन तब होता है जब उद्योग एक जगह केंद्रित होकर साझा श्रम, आपूर्तिकर्ताओं, परिवहन, सेवाओं और बाज़ारों का लाभ उठाते हैं।"],"pa":["ਉਦਯੋਗਿਕ ਸਮੂਹੀਕਰਨ ਕੀ ਹੈ?",["ਸਾਂਝੇ ਲਾਭ ਲੈਣ ਲਈ ਇੱਕੋ ਖੇਤਰ ਵਿੱਚ ਉਦਯੋਗਾਂ ਦਾ ਇਕੱਠਾ ਹੋਣਾ","ਸਾਰੇ ਕਾਰਖ਼ਾਨਿਆਂ ਦਾ ਪੂਰੀ ਤਰ੍ਹਾਂ ਖਿੰਡ ਜਾਣਾ","ਕਿਸੇ ਖੇਤਰ ਦੇ ਸਾਰੇ ਉਦਯੋਗਾਂ ਦਾ ਬੰਦ ਹੋਣਾ","ਕਾਰਖ਼ਾਨਿਆਂ 'ਤੇ ਸਿਰਫ਼ ਸਰਕਾਰੀ ਮਲਕੀਅਤ"],"ਸਮੂਹੀਕਰਨ ਉਦੋਂ ਹੁੰਦਾ ਹੈ ਜਦੋਂ ਉਦਯੋਗ ਇੱਕ ਥਾਂ ਇਕੱਠੇ ਹੋ ਕੇ ਸਾਂਝੀ ਕਿਰਤ, ਸਪਲਾਇਰਾਂ, ਆਵਾਜਾਈ, ਸੇਵਾਵਾਂ ਅਤੇ ਬਾਜ਼ਾਰਾਂ ਦਾ ਲਾਭ ਲੈਂਦੇ ਹਨ।"]},
"GEO-IND-001-CP001-Q050":{"h":"7c06777c","hi":["कोई नया कारखाना पहले से स्थापित औद्योगिक क्षेत्र को क्यों चुन सकता है?",["स्थापित क्षेत्रों में कोई अवसंरचना नहीं होती","वह पहले से मौजूद आपूर्तिकर्ताओं, श्रम, परिवहन और सेवाओं का उपयोग कर सकता है","समूहन हर लागत को हमेशा बढ़ाता है","उद्योगों के लिए एक जगह एकत्र होना कानूनी रूप से अनिवार्य है"],"स्थापित औद्योगिक क्षेत्र विशिष्ट आपूर्तिकर्ता, प्रशिक्षित श्रमिक और तैयार अवसंरचना जैसी बाह्य मितव्ययिताएँ देते हैं। ये लाभ और फ़र्मों को आकर्षित करते हैं।"],"pa":["ਕੋਈ ਨਵਾਂ ਕਾਰਖ਼ਾਨਾ ਪਹਿਲਾਂ ਤੋਂ ਸਥਾਪਿਤ ਉਦਯੋਗਿਕ ਖੇਤਰ ਨੂੰ ਕਿਉਂ ਚੁਣ ਸਕਦਾ ਹੈ?",["ਸਥਾਪਿਤ ਖੇਤਰਾਂ ਵਿੱਚ ਕੋਈ ਬੁਨਿਆਦੀ ਢਾਂਚਾ ਨਹੀਂ ਹੁੰਦਾ","ਉਹ ਪਹਿਲਾਂ ਤੋਂ ਮੌਜੂਦ ਸਪਲਾਇਰਾਂ, ਕਿਰਤ, ਆਵਾਜਾਈ ਅਤੇ ਸੇਵਾਵਾਂ ਦੀ ਵਰਤੋਂ ਕਰ ਸਕਦਾ ਹੈ","ਸਮੂਹੀਕਰਨ ਹਰ ਲਾਗਤ ਨੂੰ ਹਮੇਸ਼ਾ ਵਧਾਉਂਦਾ ਹੈ","ਉਦਯੋਗਾਂ ਲਈ ਇਕੱਠੇ ਹੋਣਾ ਕਾਨੂੰਨੀ ਤੌਰ 'ਤੇ ਲਾਜ਼ਮੀ ਹੈ"],"ਸਥਾਪਿਤ ਉਦਯੋਗਿਕ ਖੇਤਰ ਖ਼ਾਸ ਸਪਲਾਇਰ, ਸਿਖਲਾਈ-ਪ੍ਰਾਪਤ ਕਾਮੇ ਅਤੇ ਤਿਆਰ ਬੁਨਿਆਦੀ ਢਾਂਚੇ ਵਰਗੀਆਂ ਬਾਹਰੀ ਬੱਚਤਾਂ ਦਿੰਦੇ ਹਨ। ਇਹ ਲਾਭ ਹੋਰ ਫ਼ਰਮਾਂ ਨੂੰ ਖਿੱਚਦੇ ਹਨ।"]},
"GEO-IND-001-CP001-Q051":{"h":"2c5ff7ee","hi":["कथनों पर विचार कीजिए: I. औद्योगिक समूहन साझा अवसंरचना का लाभ दे सकता है। II. आपूर्तिकर्ता नेटवर्क समूहन को मज़बूत कर सकते हैं। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","I और II दोनों सही हैं","न तो I और न ही II सही है"],"साझा सेवाएँ और आपूर्तिकर्ता नेटवर्क समूह की फ़र्मों की लागत घटाते हैं और दक्षता बढ़ाते हैं। दोनों समूहन के महत्वपूर्ण लाभ हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਉਦਯੋਗਿਕ ਸਮੂਹੀਕਰਨ ਸਾਂਝੇ ਬੁਨਿਆਦੀ ਢਾਂਚੇ ਦਾ ਲਾਭ ਦੇ ਸਕਦਾ ਹੈ। II. ਸਪਲਾਇਰ ਨੈੱਟਵਰਕ ਸਮੂਹੀਕਰਨ ਨੂੰ ਮਜ਼ਬੂਤ ਕਰ ਸਕਦੇ ਹਨ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਸਾਂਝੀਆਂ ਸੇਵਾਵਾਂ ਅਤੇ ਸਪਲਾਇਰ ਨੈੱਟਵਰਕ ਸਮੂਹ ਦੀਆਂ ਫ਼ਰਮਾਂ ਦੀ ਲਾਗਤ ਘਟਾਉਂਦੇ ਹਨ ਅਤੇ ਕੁਸ਼ਲਤਾ ਵਧਾਉਂਦੇ ਹਨ। ਦੋਵੇਂ ਸਮੂਹੀਕਰਨ ਦੇ ਮਹੱਤਵਪੂਰਨ ਲਾਭ ਹਨ।"]},
"GEO-IND-001-CP001-Q052":{"h":"3dd1d650","hi":["किसी औद्योगिक समूह की सबसे विशिष्ट विशेषता कौन-सी है?",["एक अलग-थलग खेत","बिना परिवहन वाला क्षेत्र","केवल एक खनिज भंडार","पास-पास स्थित अनेक जुड़ी हुई फ़र्में और सेवाएँ"],"औद्योगिक समूहों में परस्पर जुड़ी फ़र्में, आपूर्तिकर्ता, श्रमिक और सहायक सेवाएँ होती हैं। इनकी निकटता आर्थिक लाभ पैदा करती है।"],"pa":["ਕਿਸੇ ਉਦਯੋਗਿਕ ਸਮੂਹ ਦੀ ਸਭ ਤੋਂ ਆਮ ਵਿਸ਼ੇਸ਼ਤਾ ਕਿਹੜੀ ਹੈ?",["ਇੱਕ ਵੱਖਰਾ-ਥਲੱਗ ਖੇਤ","ਬਿਨਾਂ ਆਵਾਜਾਈ ਵਾਲਾ ਖੇਤਰ","ਸਿਰਫ਼ ਇੱਕ ਖਣਿਜ ਭੰਡਾਰ","ਨੇੜੇ-ਨੇੜੇ ਸਥਿਤ ਕਈ ਜੁੜੀਆਂ ਫ਼ਰਮਾਂ ਅਤੇ ਸੇਵਾਵਾਂ"],"ਉਦਯੋਗਿਕ ਸਮੂਹਾਂ ਵਿੱਚ ਆਪਸ ਵਿੱਚ ਜੁੜੀਆਂ ਫ਼ਰਮਾਂ, ਸਪਲਾਇਰ, ਕਾਮੇ ਅਤੇ ਸਹਾਇਕ ਸੇਵਾਵਾਂ ਹੁੰਦੀਆਂ ਹਨ। ਇਨ੍ਹਾਂ ਦੀ ਨੇੜਤਾ ਆਰਥਿਕ ਲਾਭ ਪੈਦਾ ਕਰਦੀ ਹੈ।"]},
"GEO-IND-001-CP001-Q053":{"h":"28ac8920","hi":["औद्योगिक क्षेत्रों में विशिष्ट श्रम-समूह क्यों विकसित हो सकते हैं?",["समान उद्योगों के लगातार केंद्रीकरण से संबंधित कौशलों की स्थायी माँग बनती है","श्रम कौशल का उद्योग से कोई संबंध नहीं होता","समूहन रोज़गार समाप्त कर देता है","श्रमिक फ़र्मों के बीच नहीं जा सकते"],"जब संबंधित उद्योग एक जगह केंद्रित रहते हैं, तो श्रमिक विशिष्ट कौशल सीखते और फ़र्मों के बीच साझा करते हैं। इससे वह क्षेत्र समान फ़र्मों के लिए और आकर्षक बनता है।"],"pa":["ਉਦਯੋਗਿਕ ਖੇਤਰਾਂ ਵਿੱਚ ਖ਼ਾਸ ਕਿਰਤ-ਸਮੂਹ ਕਿਉਂ ਵਿਕਸਿਤ ਹੋ ਸਕਦੇ ਹਨ?",["ਇੱਕੋ ਜਿਹੇ ਉਦਯੋਗਾਂ ਦੇ ਲਗਾਤਾਰ ਇਕੱਠੇ ਹੋਣ ਨਾਲ ਸੰਬੰਧਿਤ ਹੁਨਰਾਂ ਦੀ ਸਥਾਈ ਮੰਗ ਬਣਦੀ ਹੈ","ਕਿਰਤ ਹੁਨਰਾਂ ਦਾ ਉਦਯੋਗ ਨਾਲ ਕੋਈ ਸੰਬੰਧ ਨਹੀਂ ਹੁੰਦਾ","ਸਮੂਹੀਕਰਨ ਰੁਜ਼ਗਾਰ ਖ਼ਤਮ ਕਰ ਦਿੰਦਾ ਹੈ","ਕਾਮੇ ਫ਼ਰਮਾਂ ਵਿਚਕਾਰ ਨਹੀਂ ਜਾ ਸਕਦੇ"],"ਜਦੋਂ ਸੰਬੰਧਿਤ ਉਦਯੋਗ ਇੱਕ ਥਾਂ ਕੇਂਦਰਿਤ ਰਹਿੰਦੇ ਹਨ, ਤਾਂ ਕਾਮੇ ਖ਼ਾਸ ਹੁਨਰ ਸਿੱਖਦੇ ਹਨ ਅਤੇ ਫ਼ਰਮਾਂ ਵਿੱਚ ਸਾਂਝੇ ਕਰਦੇ ਹਨ। ਇਸ ਨਾਲ ਉਹ ਖੇਤਰ ਇੱਕੋ ਜਿਹੀਆਂ ਫ਼ਰਮਾਂ ਲਈ ਹੋਰ ਆਕਰਸ਼ਕ ਬਣਦਾ ਹੈ।"]},
"GEO-IND-001-CP001-Q054":{"h":"10d2e711","hi":["कौन-सी प्रक्रिया किसी औद्योगिक क्षेत्र को समय के साथ स्व-सुदृढ़ बना सकती है?",["सभी परिवहन संपर्कों का समाप्त होना","समूहन मितव्ययिताएँ","बाज़ारों का हट जाना","आपूर्तिकर्ताओं का समाप्त होना"],"एक बार औद्योगिक समूह बन जाने पर साझा अवसंरचना, आपूर्तिकर्ता, कौशल और बाज़ार और फ़र्मों को आकर्षित करते हैं। यह संचयी प्रक्रिया क्षेत्र के औद्योगिक महत्व को मज़बूत करती है।"],"pa":["ਕਿਹੜੀ ਪ੍ਰਕਿਰਿਆ ਕਿਸੇ ਉਦਯੋਗਿਕ ਖੇਤਰ ਨੂੰ ਸਮੇਂ ਨਾਲ ਆਪਣੇ-ਆਪ ਮਜ਼ਬੂਤ ਹੋਣ ਵਾਲਾ ਬਣਾ ਸਕਦੀ ਹੈ?",["ਸਾਰੇ ਆਵਾਜਾਈ ਸੰਪਰਕਾਂ ਦਾ ਟੁੱਟ ਜਾਣਾ","ਸਮੂਹੀਕਰਨ ਦੀਆਂ ਬੱਚਤਾਂ","ਬਾਜ਼ਾਰਾਂ ਦਾ ਹਟ ਜਾਣਾ","ਸਪਲਾਇਰਾਂ ਦਾ ਖ਼ਤਮ ਹੋ ਜਾਣਾ"],"ਇੱਕ ਵਾਰ ਉਦਯੋਗਿਕ ਸਮੂਹ ਬਣ ਜਾਣ 'ਤੇ ਸਾਂਝਾ ਬੁਨਿਆਦੀ ਢਾਂਚਾ, ਸਪਲਾਇਰ, ਹੁਨਰ ਅਤੇ ਬਾਜ਼ਾਰ ਹੋਰ ਫ਼ਰਮਾਂ ਨੂੰ ਖਿੱਚਦੇ ਹਨ। ਇਹ ਸੰਚਿਤ ਪ੍ਰਕਿਰਿਆ ਖੇਤਰ ਦੀ ਉਦਯੋਗਿਕ ਮਹੱਤਤਾ ਨੂੰ ਮਜ਼ਬੂਤ ਕਰਦੀ ਹੈ।"]},
"GEO-IND-001-CP001-Q055":{"h":"91bc23da","hi":["अवस्थिति-मुक्त (फ़ुटलूज़) उद्योग क्या है?",["ऐसा उद्योग जो केवल खदान पर चल सकता है","ऐसा उद्योग जिसके लिए नदी बाँध आवश्यक है","ऐसा उद्योग जिसका स्वामित्व केवल सरकार के पास है","ऐसा उद्योग जो किसी विशेष कच्चे माल के स्रोत या बाज़ार से मज़बूती से बँधा न हो"],"अवस्थिति-मुक्त उद्योगों की अवस्थिति अपेक्षाकृत लचीली होती है, क्योंकि उनका कच्चा माल हल्का, मूल्यवान या आसानी से ढोने योग्य होता है और उनकी प्रक्रियाएँ विशेष प्राकृतिक संसाधनों से कम बँधी होती हैं।"],"pa":["ਸਥਾਨ-ਮੁਕਤ (ਫੁਟਲੂਜ਼) ਉਦਯੋਗ ਕੀ ਹੈ?",["ਅਜਿਹਾ ਉਦਯੋਗ ਜੋ ਸਿਰਫ਼ ਖਾਣ 'ਤੇ ਚੱਲ ਸਕਦਾ ਹੈ","ਅਜਿਹਾ ਉਦਯੋਗ ਜਿਸ ਲਈ ਦਰਿਆਈ ਡੈਮ ਜ਼ਰੂਰੀ ਹੈ","ਅਜਿਹਾ ਉਦਯੋਗ ਜਿਸ ਦੀ ਮਲਕੀਅਤ ਸਿਰਫ਼ ਸਰਕਾਰ ਕੋਲ ਹੈ","ਅਜਿਹਾ ਉਦਯੋਗ ਜੋ ਕਿਸੇ ਖ਼ਾਸ ਕੱਚੇ ਮਾਲ ਦੇ ਸਰੋਤ ਜਾਂ ਬਾਜ਼ਾਰ ਨਾਲ ਮਜ਼ਬੂਤੀ ਨਾਲ ਬੱਝਾ ਨਾ ਹੋਵੇ"],"ਸਥਾਨ-ਮੁਕਤ ਉਦਯੋਗਾਂ ਦੀ ਥਾਂ ਤੁਲਨਾਤਮਕ ਤੌਰ 'ਤੇ ਲਚਕਦਾਰ ਹੁੰਦੀ ਹੈ, ਕਿਉਂਕਿ ਉਨ੍ਹਾਂ ਦਾ ਕੱਚਾ ਮਾਲ ਹਲਕਾ, ਕੀਮਤੀ ਜਾਂ ਸੌਖਿਆਂ ਢੋਣਯੋਗ ਹੁੰਦਾ ਹੈ ਅਤੇ ਉਨ੍ਹਾਂ ਦੀਆਂ ਪ੍ਰਕਿਰਿਆਵਾਂ ਖ਼ਾਸ ਕੁਦਰਤੀ ਸਾਧਨਾਂ ਨਾਲ ਘੱਟ ਬੱਝੀਆਂ ਹੁੰਦੀਆਂ ਹਨ।"]},
"GEO-IND-001-CP001-Q056":{"h":"fb63e46c","hi":["कौन-सी विशेषता अवस्थिति-मुक्त औद्योगिक प्रतिरूप के अनुकूल है?",["हल्का, अधिक मूल्य वाला और आसानी से ढोने योग्य कच्चा माल","बहुत भारी और कम मूल्य वाला कच्चा माल","केवल शीघ्र खराब होने वाला गन्ना","एक ही कोयला परत पर निर्भरता"],"जब परिवहन लागत उत्पाद के मूल्य का छोटा हिस्सा हो, तब फ़र्में श्रम, अवसंरचना या व्यावसायिक वातावरण के आधार पर स्थान चुनने के लिए अधिक स्वतंत्र होती हैं।"],"pa":["ਕਿਹੜੀ ਵਿਸ਼ੇਸ਼ਤਾ ਸਥਾਨ-ਮੁਕਤ ਉਦਯੋਗਿਕ ਨਮੂਨੇ ਦੇ ਅਨੁਕੂਲ ਹੈ?",["ਹਲਕਾ, ਵੱਧ ਕੀਮਤ ਵਾਲਾ ਅਤੇ ਸੌਖਿਆਂ ਢੋਣਯੋਗ ਕੱਚਾ ਮਾਲ","ਬਹੁਤ ਭਾਰੀ ਅਤੇ ਘੱਟ ਕੀਮਤ ਵਾਲਾ ਕੱਚਾ ਮਾਲ","ਸਿਰਫ਼ ਜਲਦੀ ਖ਼ਰਾਬ ਹੋਣ ਵਾਲਾ ਗੰਨਾ","ਇੱਕੋ ਕੋਲੇ ਦੀ ਪਰਤ 'ਤੇ ਨਿਰਭਰਤਾ"],"ਜਦੋਂ ਢੋਆ-ਢੁਆਈ ਦੀ ਲਾਗਤ ਉਤਪਾਦ ਦੀ ਕੀਮਤ ਦਾ ਛੋਟਾ ਹਿੱਸਾ ਹੋਵੇ, ਤਾਂ ਫ਼ਰਮਾਂ ਕਿਰਤ, ਬੁਨਿਆਦੀ ਢਾਂਚੇ ਜਾਂ ਕਾਰੋਬਾਰੀ ਮਾਹੌਲ ਦੇ ਅਧਾਰ 'ਤੇ ਥਾਂ ਚੁਣਨ ਲਈ ਵਧੇਰੇ ਆਜ਼ਾਦ ਹੁੰਦੀਆਂ ਹਨ।"]},
"GEO-IND-001-CP001-Q057":{"h":"347dec55","hi":["कथनों पर विचार कीजिए: I. अवस्थिति-मुक्त उद्योगों की अवस्थिति अपेक्षाकृत लचीली होती है। II. वे भारी स्थानीय कच्चे माल पर कम निर्भर होते हैं। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","I और II दोनों सही हैं","केवल II सही है","न तो I और न ही II सही है"],"अवस्थिति-मुक्त उद्योग कई स्थानों पर लग सकते हैं, क्योंकि वे भारी संसाधनों से अधिक बँधे नहीं होते। दोनों कथन इस अवधारणा को सही बताते हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਸਥਾਨ-ਮੁਕਤ ਉਦਯੋਗਾਂ ਦੀ ਥਾਂ ਤੁਲਨਾਤਮਕ ਤੌਰ 'ਤੇ ਲਚਕਦਾਰ ਹੁੰਦੀ ਹੈ। II. ਉਹ ਭਾਰੀ ਸਥਾਨਕ ਕੱਚੇ ਮਾਲ 'ਤੇ ਘੱਟ ਨਿਰਭਰ ਹੁੰਦੇ ਹਨ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਸਥਾਨ-ਮੁਕਤ ਉਦਯੋਗ ਕਈ ਥਾਵਾਂ 'ਤੇ ਲੱਗ ਸਕਦੇ ਹਨ, ਕਿਉਂਕਿ ਉਹ ਭਾਰੀ ਸਾਧਨਾਂ ਨਾਲ ਬਹੁਤੇ ਬੱਝੇ ਨਹੀਂ ਹੁੰਦੇ। ਦੋਵੇਂ ਕਥਨ ਇਸ ਸੰਕਲਪ ਨੂੰ ਸਹੀ ਦੱਸਦੇ ਹਨ।"]},
"GEO-IND-001-CP001-Q058":{"h":"69c05326","hi":["एकीकृत इस्पात संयंत्र की तुलना में कौन-सा उद्योग अधिक अवस्थिति-मुक्त होने की संभावना रखता है?",["लौह-इस्पात","चीनी मिल","इलेक्ट्रॉनिक्स संयोजन","चूना पत्थर के पास सीमेंट विनिर्माण"],"इलेक्ट्रॉनिक्स संयोजन में अपेक्षाकृत हल्के और अधिक मूल्य वाले पुर्ज़े लगते हैं, इसलिए उसकी अवस्थिति अधिक लचीली हो सकती है। इस्पात, चीनी और सीमेंट पर कच्चे माल या भारी परिवहन की बाधाएँ अधिक होती हैं।"],"pa":["ਏਕੀਕ੍ਰਿਤ ਸਟੀਲ ਪਲਾਂਟ ਦੇ ਮੁਕਾਬਲੇ ਕਿਹੜਾ ਉਦਯੋਗ ਵਧੇਰੇ ਸਥਾਨ-ਮੁਕਤ ਹੋਣ ਦੀ ਸੰਭਾਵਨਾ ਰੱਖਦਾ ਹੈ?",["ਲੋਹਾ-ਸਟੀਲ","ਖੰਡ ਮਿੱਲ","ਇਲੈਕਟ੍ਰਾਨਿਕਸ ਅਸੈਂਬਲੀ","ਚੂਨਾ ਪੱਥਰ ਦੇ ਨੇੜੇ ਸੀਮਿੰਟ ਨਿਰਮਾਣ"],"ਇਲੈਕਟ੍ਰਾਨਿਕਸ ਅਸੈਂਬਲੀ ਵਿੱਚ ਤੁਲਨਾਤਮਕ ਤੌਰ 'ਤੇ ਹਲਕੇ ਅਤੇ ਵੱਧ ਕੀਮਤ ਵਾਲੇ ਪੁਰਜ਼ੇ ਲੱਗਦੇ ਹਨ, ਇਸ ਲਈ ਇਸ ਦੀ ਥਾਂ ਵਧੇਰੇ ਲਚਕਦਾਰ ਹੋ ਸਕਦੀ ਹੈ। ਸਟੀਲ, ਖੰਡ ਅਤੇ ਸੀਮਿੰਟ 'ਤੇ ਕੱਚੇ ਮਾਲ ਜਾਂ ਭਾਰੀ ਢੋਆ-ਢੁਆਈ ਦੀਆਂ ਪਾਬੰਦੀਆਂ ਵੱਧ ਹੁੰਦੀਆਂ ਹਨ।"]},
"GEO-IND-001-CP001-Q059":{"h":"f7426ccc","hi":["अवस्थिति-मुक्त उद्योग के लिए कच्चे माल की निकटता से अधिक कौन-सा कारक महत्वपूर्ण हो सकता है?",["लौह अयस्क खदान की उपस्थिति","केवल चूना पत्थर खदान की उपस्थिति","गन्ने का खेत","कुशल श्रम और कनेक्टिविटी"],"अवस्थिति-मुक्त उद्योग संसाधनों से कम बँधे होते हैं, इसलिए कुशल श्रमिक, संचार, लॉजिस्टिक्स और व्यावसायिक सेवाओं तक पहुँच उनके स्थान-निर्णय में प्रमुख हो सकती है।"],"pa":["ਸਥਾਨ-ਮੁਕਤ ਉਦਯੋਗ ਲਈ ਕੱਚੇ ਮਾਲ ਦੀ ਨੇੜਤਾ ਨਾਲੋਂ ਕਿਹੜਾ ਕਾਰਕ ਵਧੇਰੇ ਮਹੱਤਵਪੂਰਨ ਹੋ ਸਕਦਾ ਹੈ?",["ਕੱਚੇ ਲੋਹੇ ਦੀ ਖਾਣ ਦੀ ਮੌਜੂਦਗੀ","ਸਿਰਫ਼ ਚੂਨਾ ਪੱਥਰ ਦੀ ਖਾਣ ਦੀ ਮੌਜੂਦਗੀ","ਗੰਨੇ ਦਾ ਖੇਤ","ਹੁਨਰਮੰਦ ਕਿਰਤ ਅਤੇ ਕਨੈਕਟੀਵਿਟੀ"],"ਸਥਾਨ-ਮੁਕਤ ਉਦਯੋਗ ਸਾਧਨਾਂ ਨਾਲ ਘੱਟ ਬੱਝੇ ਹੁੰਦੇ ਹਨ, ਇਸ ਲਈ ਹੁਨਰਮੰਦ ਕਾਮਿਆਂ, ਸੰਚਾਰ, ਲੌਜਿਸਟਿਕਸ ਅਤੇ ਕਾਰੋਬਾਰੀ ਸੇਵਾਵਾਂ ਤੱਕ ਪਹੁੰਚ ਉਨ੍ਹਾਂ ਦੇ ਥਾਂ ਸੰਬੰਧੀ ਫ਼ੈਸਲਿਆਂ ਵਿੱਚ ਪ੍ਰਮੁੱਖ ਹੋ ਸਕਦੀ ਹੈ।"]},
"GEO-IND-001-CP001-Q060":{"h":"ff000846","hi":["औद्योगिक अवस्थिति के लिए कौन-सी तुलना सही है?",["इस्पात मुख्यतः संसाधन-उन्मुख है, जबकि इलेक्ट्रॉनिक्स संयोजन अधिक अवस्थिति-मुक्त हो सकता है","दोनों के लिए लौह अयस्क खदान आवश्यक है","इलेक्ट्रॉनिक्स, इस्पात से अधिक संसाधन-बद्ध है","किसी भी उद्योग पर अवस्थिति कारकों का प्रभाव नहीं पड़ता"],"एकीकृत इस्पात को भारी खनिज कच्चा माल चाहिए, जबकि इलेक्ट्रॉनिक्स संयोजन हल्के पुर्ज़ों और आधुनिक परिवहन का उपयोग कर सकता है। इसलिए दोनों की अवस्थिति का लचीलापन बहुत अलग है।"],"pa":["ਉਦਯੋਗਿਕ ਸਥਾਨੀਕਰਨ ਲਈ ਕਿਹੜੀ ਤੁਲਨਾ ਸਹੀ ਹੈ?",["ਸਟੀਲ ਮੁੱਖ ਤੌਰ 'ਤੇ ਸਾਧਨ-ਮੁਖੀ ਹੈ, ਜਦਕਿ ਇਲੈਕਟ੍ਰਾਨਿਕਸ ਅਸੈਂਬਲੀ ਵਧੇਰੇ ਸਥਾਨ-ਮੁਕਤ ਹੋ ਸਕਦੀ ਹੈ","ਦੋਵਾਂ ਲਈ ਕੱਚੇ ਲੋਹੇ ਦੀ ਖਾਣ ਜ਼ਰੂਰੀ ਹੈ","ਇਲੈਕਟ੍ਰਾਨਿਕਸ ਸਟੀਲ ਨਾਲੋਂ ਵੱਧ ਸਾਧਨ-ਬੱਧ ਹੈ","ਕਿਸੇ ਵੀ ਉਦਯੋਗ 'ਤੇ ਸਥਾਨੀਕਰਨ ਕਾਰਕਾਂ ਦਾ ਅਸਰ ਨਹੀਂ ਪੈਂਦਾ"],"ਏਕੀਕ੍ਰਿਤ ਸਟੀਲ ਨੂੰ ਭਾਰੀ ਖਣਿਜ ਕੱਚਾ ਮਾਲ ਚਾਹੀਦਾ ਹੈ, ਜਦਕਿ ਇਲੈਕਟ੍ਰਾਨਿਕਸ ਅਸੈਂਬਲੀ ਹਲਕੇ ਪੁਰਜ਼ੇ ਅਤੇ ਆਧੁਨਿਕ ਆਵਾਜਾਈ ਵਰਤ ਸਕਦੀ ਹੈ। ਇਸ ਲਈ ਦੋਵਾਂ ਦੀ ਥਾਂ ਸੰਬੰਧੀ ਲਚਕ ਬਹੁਤ ਵੱਖਰੀ ਹੈ।"]},
"GEO-IND-001-CP002-Q001":{"h":"3a0cb32e","hi":["लौह-इस्पात उद्योग के लिए लोहे का मुख्य स्रोत कौन-सा कच्चा माल है?",["बॉक्साइट","अभ्रक","लौह अयस्क","जिप्सम"],"लौह अयस्क से ही कच्चा लोहा और इस्पात बनाने के लिए लोहा मिलता है। कोकिंग कोयला, चूना पत्थर और मैंगनीज़ इस प्रक्रिया में सहायक हैं, पर धातु के मुख्य स्रोत के रूप में लौह अयस्क की जगह नहीं लेते।"],"pa":["ਲੋਹਾ-ਸਟੀਲ ਉਦਯੋਗ ਲਈ ਲੋਹੇ ਦਾ ਮੁੱਖ ਸਰੋਤ ਕਿਹੜਾ ਕੱਚਾ ਮਾਲ ਹੈ?",["ਬਾਕਸਾਈਟ","ਅਬਰਕ","ਕੱਚਾ ਲੋਹਾ","ਜਿਪਸਮ"],"ਕੱਚੇ ਲੋਹੇ ਤੋਂ ਹੀ ਪਿਗ ਆਇਰਨ ਅਤੇ ਸਟੀਲ ਬਣਾਉਣ ਲਈ ਲੋਹਾ ਮਿਲਦਾ ਹੈ। ਕੋਕਿੰਗ ਕੋਲਾ, ਚੂਨਾ ਪੱਥਰ ਅਤੇ ਮੈਂਗਨੀਜ਼ ਇਸ ਪ੍ਰਕਿਰਿਆ ਵਿੱਚ ਸਹਾਇਕ ਹਨ, ਪਰ ਧਾਤ ਦੇ ਮੁੱਖ ਸਰੋਤ ਵਜੋਂ ਕੱਚੇ ਲੋਹੇ ਦੀ ਥਾਂ ਨਹੀਂ ਲੈਂਦੇ।"]},
"GEO-IND-001-CP002-Q002":{"h":"2dc29a5a","hi":["अनेक एकीकृत इस्पात संयंत्र खनिज पट्टियों के पास क्यों स्थित हैं?",["उन्हें केवल पर्यटन बाज़ार चाहिए","वे परिवहन का उपयोग नहीं करते","वे केवल वर्षा पर निर्भर हैं","उन्हें बड़ी मात्रा में भारी कच्चा माल चाहिए"],"एकीकृत इस्पात संयंत्र बड़ी मात्रा में लौह अयस्क, कोयला, चूना पत्थर और अन्य सामग्री खपत करते हैं। इन कच्चे मालों के पास स्थापित होने से माल-भाड़ा घटता है।"],"pa":["ਬਹੁਤੇ ਏਕੀਕ੍ਰਿਤ ਸਟੀਲ ਪਲਾਂਟ ਖਣਿਜ ਪੱਟੀਆਂ ਦੇ ਨੇੜੇ ਕਿਉਂ ਸਥਿਤ ਹਨ?",["ਉਨ੍ਹਾਂ ਨੂੰ ਸਿਰਫ਼ ਸੈਰ-ਸਪਾਟਾ ਬਾਜ਼ਾਰ ਚਾਹੀਦੇ ਹਨ","ਉਹ ਆਵਾਜਾਈ ਦੀ ਵਰਤੋਂ ਨਹੀਂ ਕਰਦੇ","ਉਹ ਸਿਰਫ਼ ਵਰਖਾ 'ਤੇ ਨਿਰਭਰ ਹਨ","ਉਨ੍ਹਾਂ ਨੂੰ ਵੱਡੀ ਮਾਤਰਾ ਵਿੱਚ ਭਾਰੀ ਕੱਚਾ ਮਾਲ ਚਾਹੀਦਾ ਹੈ"],"ਏਕੀਕ੍ਰਿਤ ਸਟੀਲ ਪਲਾਂਟ ਵੱਡੀ ਮਾਤਰਾ ਵਿੱਚ ਕੱਚਾ ਲੋਹਾ, ਕੋਲਾ, ਚੂਨਾ ਪੱਥਰ ਅਤੇ ਹੋਰ ਸਮੱਗਰੀ ਵਰਤਦੇ ਹਨ। ਇਨ੍ਹਾਂ ਦੇ ਨੇੜੇ ਲੱਗਣ ਨਾਲ ਮਾਲ-ਭਾੜਾ ਘਟਦਾ ਹੈ।"]},
"GEO-IND-001-CP002-Q003":{"h":"213a2cb8","hi":["वात्या भट्टी में इस्पात बनाने में गालक (फ़्लक्स) के रूप में किस पदार्थ का उपयोग होता है?",["चूना पत्थर","अभ्रक","सेंधा नमक","बेराइट"],"चूना पत्थर अशुद्धियों से मिलकर उन्हें धातुमल के रूप में अलग करने में मदद करता है। इसलिए लौह-इस्पात उत्पादन में यह एक महत्वपूर्ण गालक है।"],"pa":["ਬਲਾਸਟ ਫਰਨੇਸ ਵਿੱਚ ਸਟੀਲ ਬਣਾਉਣ ਸਮੇਂ ਫਲਕਸ ਵਜੋਂ ਕਿਹੜਾ ਪਦਾਰਥ ਵਰਤਿਆ ਜਾਂਦਾ ਹੈ?",["ਚੂਨਾ ਪੱਥਰ","ਅਬਰਕ","ਸੇਂਧਾ ਲੂਣ","ਬੇਰਾਈਟ"],"ਚੂਨਾ ਪੱਥਰ ਅਸ਼ੁੱਧੀਆਂ ਨਾਲ ਮਿਲ ਕੇ ਉਨ੍ਹਾਂ ਨੂੰ ਸਲੈਗ ਵਜੋਂ ਵੱਖ ਕਰਨ ਵਿੱਚ ਮਦਦ ਕਰਦਾ ਹੈ। ਇਸ ਲਈ ਲੋਹਾ-ਸਟੀਲ ਉਤਪਾਦਨ ਵਿੱਚ ਇਹ ਇੱਕ ਮਹੱਤਵਪੂਰਨ ਫਲਕਸ ਹੈ।"]},
"GEO-IND-001-CP002-Q004":{"h":"632a2448","hi":["मिश्रधातु बनाने और ऑक्सीजन हटाने वाले पदार्थ के रूप में इस्पात निर्माण में कौन-सा खनिज महत्वपूर्ण है?",["जिप्सम","मैंगनीज़","अभ्रक","रॉक फ़ॉस्फ़ेट"],"मैंगनीज़ इस्पात के गुण सुधारता है और अवांछित ऑक्सीजन व गंधक हटाने में मदद करता है। यह लौह-मिश्रधातु का एक प्रमुख कच्चा माल है।"],"pa":["ਮਿਸ਼ਰਤ ਧਾਤ ਬਣਾਉਣ ਅਤੇ ਆਕਸੀਜਨ ਹਟਾਉਣ ਵਾਲੇ ਪਦਾਰਥ ਵਜੋਂ ਸਟੀਲ ਬਣਾਉਣ ਵਿੱਚ ਕਿਹੜਾ ਖਣਿਜ ਮਹੱਤਵਪੂਰਨ ਹੈ?",["ਜਿਪਸਮ","ਮੈਂਗਨੀਜ਼","ਅਬਰਕ","ਰੌਕ ਫਾਸਫੇਟ"],"ਮੈਂਗਨੀਜ਼ ਸਟੀਲ ਦੇ ਗੁਣ ਸੁਧਾਰਦਾ ਹੈ ਅਤੇ ਅਣਚਾਹੀ ਆਕਸੀਜਨ ਤੇ ਗੰਧਕ ਹਟਾਉਣ ਵਿੱਚ ਮਦਦ ਕਰਦਾ ਹੈ। ਇਹ ਫੈਰੋ-ਮਿਸ਼ਰਤ ਧਾਤ ਦਾ ਮੁੱਖ ਕੱਚਾ ਮਾਲ ਹੈ।"]},
"GEO-IND-001-CP002-Q005":{"h":"cc49da41","hi":["कथनों पर विचार कीजिए: I. लौह अयस्क इस्पात का एक प्रमुख कच्चा माल है। II. पारंपरिक वात्या भट्टी से इस्पात बनाने में कोकिंग कोयला महत्वपूर्ण है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","I और II दोनों सही हैं","न तो I और न ही II सही है"],"एकीकृत इस्पात उत्पादन परंपरागत रूप से चूना पत्थर और अन्य सामग्री के साथ-साथ लौह अयस्क और कोकिंग कोयले पर बहुत निर्भर रहा है।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਕੱਚਾ ਲੋਹਾ ਸਟੀਲ ਦਾ ਇੱਕ ਮੁੱਖ ਕੱਚਾ ਮਾਲ ਹੈ। II. ਰਵਾਇਤੀ ਬਲਾਸਟ ਫਰਨੇਸ ਨਾਲ ਸਟੀਲ ਬਣਾਉਣ ਵਿੱਚ ਕੋਕਿੰਗ ਕੋਲਾ ਮਹੱਤਵਪੂਰਨ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਏਕੀਕ੍ਰਿਤ ਸਟੀਲ ਉਤਪਾਦਨ ਰਵਾਇਤੀ ਤੌਰ 'ਤੇ ਚੂਨਾ ਪੱਥਰ ਅਤੇ ਹੋਰ ਸਮੱਗਰੀ ਦੇ ਨਾਲ-ਨਾਲ ਕੱਚੇ ਲੋਹੇ ਅਤੇ ਕੋਕਿੰਗ ਕੋਲੇ 'ਤੇ ਬਹੁਤ ਨਿਰਭਰ ਰਿਹਾ ਹੈ।"]},
"GEO-IND-001-CP002-Q006":{"h":"6e45d9e6","hi":["कौन-सा संयोजन एकीकृत इस्पात संयंत्र की अवस्थिति के अनुकूल है?",["चाय बागान, मत्स्य क्षेत्र और पर्यटन","केवल उपजाऊ मिट्टी","केवल भारी वर्षा","लौह अयस्क, कोकिंग कोयला, जल, बिजली और परिवहन"],"इस्पात संयंत्रों को भारी खनिज कच्चा माल, जल, बिजली, श्रम और कुशल परिवहन चाहिए। इसलिए उनकी अवस्थिति कई औद्योगिक कारकों के मेल को दर्शाती है।"],"pa":["ਕਿਹੜਾ ਸੁਮੇਲ ਏਕੀਕ੍ਰਿਤ ਸਟੀਲ ਪਲਾਂਟ ਦੇ ਸਥਾਨ ਦੇ ਅਨੁਕੂਲ ਹੈ?",["ਚਾਹ ਦੇ ਬਾਗ਼, ਮੱਛੀ ਖੇਤਰ ਅਤੇ ਸੈਰ-ਸਪਾਟਾ","ਸਿਰਫ਼ ਉਪਜਾਊ ਮਿੱਟੀ","ਸਿਰਫ਼ ਭਾਰੀ ਵਰਖਾ","ਕੱਚਾ ਲੋਹਾ, ਕੋਕਿੰਗ ਕੋਲਾ, ਪਾਣੀ, ਬਿਜਲੀ ਅਤੇ ਆਵਾਜਾਈ"],"ਸਟੀਲ ਪਲਾਂਟਾਂ ਨੂੰ ਭਾਰੀ ਖਣਿਜ ਕੱਚਾ ਮਾਲ, ਪਾਣੀ, ਬਿਜਲੀ, ਕਿਰਤ ਅਤੇ ਕੁਸ਼ਲ ਆਵਾਜਾਈ ਚਾਹੀਦੀ ਹੈ। ਇਸ ਲਈ ਉਨ੍ਹਾਂ ਦਾ ਸਥਾਨ ਕਈ ਉਦਯੋਗਿਕ ਕਾਰਕਾਂ ਦੇ ਮੇਲ ਨੂੰ ਦਰਸਾਉਂਦਾ ਹੈ।"]},
"GEO-IND-001-CP002-Q007":{"h":"6525ca0e","hi":["प्रमुख लौह-इस्पात केंद्र जमशेदपुर किस राज्य में स्थित है?",["झारखंड","ओडिशा","छत्तीसगढ़","पश्चिम बंगाल"],"जमशेदपुर झारखंड में है और पूर्वी खनिज पट्टी में एक प्रमुख एकीकृत इस्पात केंद्र के रूप में विकसित हुआ।"],"pa":["ਪ੍ਰਮੁੱਖ ਲੋਹਾ-ਸਟੀਲ ਕੇਂਦਰ ਜਮਸ਼ੇਦਪੁਰ ਕਿਸ ਰਾਜ ਵਿੱਚ ਸਥਿਤ ਹੈ?",["ਝਾਰਖੰਡ","ਓਡੀਸ਼ਾ","ਛੱਤੀਸਗੜ੍ਹ","ਪੱਛਮੀ ਬੰਗਾਲ"],"ਜਮਸ਼ੇਦਪੁਰ ਝਾਰਖੰਡ ਵਿੱਚ ਹੈ ਅਤੇ ਪੂਰਬੀ ਖਣਿਜ ਪੱਟੀ ਵਿੱਚ ਇੱਕ ਪ੍ਰਮੁੱਖ ਏਕੀਕ੍ਰਿਤ ਸਟੀਲ ਕੇਂਦਰ ਵਜੋਂ ਵਿਕਸਿਤ ਹੋਇਆ।"]},
"GEO-IND-001-CP002-Q008":{"h":"78509754","hi":["जमशेदपुर इस्पात संयंत्र ऐतिहासिक रूप से किस कंपनी से जुड़ा है?",["सेल (SAIL)","टाटा स्टील","आरआईएनएल (RINL)","नाल्को (NALCO)"],"जमशेदपुर टाटा स्टील (पूर्व में TISCO) का ऐतिहासिक केंद्र है। यह भारत के निजी क्षेत्र के प्रमुख एकीकृत इस्पात केंद्रों में से एक है।"],"pa":["ਜਮਸ਼ੇਦਪੁਰ ਸਟੀਲ ਪਲਾਂਟ ਇਤਿਹਾਸਕ ਤੌਰ 'ਤੇ ਕਿਸ ਕੰਪਨੀ ਨਾਲ ਜੁੜਿਆ ਹੈ?",["ਸੇਲ (SAIL)","ਟਾਟਾ ਸਟੀਲ","ਆਰਆਈਐਨਐਲ (RINL)","ਨਾਲਕੋ (NALCO)"],"ਜਮਸ਼ੇਦਪੁਰ ਟਾਟਾ ਸਟੀਲ (ਪਹਿਲਾਂ TISCO) ਦਾ ਇਤਿਹਾਸਕ ਕੇਂਦਰ ਹੈ। ਇਹ ਭਾਰਤ ਦੇ ਨਿੱਜੀ ਖੇਤਰ ਦੇ ਪ੍ਰਮੁੱਖ ਏਕੀਕ੍ਰਿਤ ਸਟੀਲ ਕੇਂਦਰਾਂ ਵਿੱਚੋਂ ਇੱਕ ਹੈ।"]},
"GEO-IND-001-CP002-Q009":{"h":"2835fa03","hi":["किस निकटवर्ती खनिज क्षेत्र ने जमशेदपुर को इस्पात केंद्र के रूप में विकसित होने में मदद की?",["सांभर नमक पट्टी","नेवेली लिग्नाइट क्षेत्र","सिंहभूम लौह अयस्क पट्टी","पन्ना हीरा क्षेत्र"],"जमशेदपुर को सिंहभूम लौह अयस्क क्षेत्र और पास के कोयला क्षेत्रों की निकटता का लाभ मिलता है, जिससे यह एकीकृत इस्पात उत्पादन के लिए उपयुक्त है।"],"pa":["ਕਿਸ ਨੇੜਲੇ ਖਣਿਜ ਖੇਤਰ ਨੇ ਜਮਸ਼ੇਦਪੁਰ ਨੂੰ ਸਟੀਲ ਕੇਂਦਰ ਵਜੋਂ ਵਿਕਸਿਤ ਹੋਣ ਵਿੱਚ ਮਦਦ ਕੀਤੀ?",["ਸਾਂਭਰ ਲੂਣ ਪੱਟੀ","ਨੇਵੇਲੀ ਲਿਗਨਾਈਟ ਖੇਤਰ","ਸਿੰਘਭੂਮ ਕੱਚੇ ਲੋਹੇ ਦੀ ਪੱਟੀ","ਪੰਨਾ ਹੀਰਾ ਖੇਤਰ"],"ਜਮਸ਼ੇਦਪੁਰ ਨੂੰ ਸਿੰਘਭੂਮ ਕੱਚੇ ਲੋਹੇ ਦੇ ਖੇਤਰ ਅਤੇ ਨੇੜਲੇ ਕੋਲਾ ਖੇਤਰਾਂ ਦੀ ਨੇੜਤਾ ਦਾ ਲਾਭ ਮਿਲਦਾ ਹੈ, ਜਿਸ ਨਾਲ ਇਹ ਏਕੀਕ੍ਰਿਤ ਸਟੀਲ ਉਤਪਾਦਨ ਲਈ ਢੁਕਵਾਂ ਹੈ।"]},
"GEO-IND-001-CP002-Q010":{"h":"b4466eea","hi":["कथनों पर विचार कीजिए: I. जमशेदपुर झारखंड में है। II. यह पूर्वी खनिज-औद्योगिक क्षेत्र में स्थित है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","न तो I और न ही II सही है","I और II दोनों सही हैं"],"जमशेदपुर झारखंड में स्थित है और खनिज-संपन्न छोटानागपुर औद्योगिक पट्टी का भाग है।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਜਮਸ਼ੇਦਪੁਰ ਝਾਰਖੰਡ ਵਿੱਚ ਹੈ। II. ਇਹ ਪੂਰਬੀ ਖਣਿਜ-ਉਦਯੋਗਿਕ ਖੇਤਰ ਵਿੱਚ ਸਥਿਤ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ"],"ਜਮਸ਼ੇਦਪੁਰ ਝਾਰਖੰਡ ਵਿੱਚ ਸਥਿਤ ਹੈ ਅਤੇ ਖਣਿਜਾਂ ਨਾਲ ਭਰਪੂਰ ਛੋਟਾਨਾਗਪੁਰ ਉਦਯੋਗਿਕ ਪੱਟੀ ਦਾ ਹਿੱਸਾ ਹੈ।"]},
"GEO-IND-001-CP002-Q011":{"h":"1b272863","hi":["जमशेदपुर के इस्पात भूगोल में कौन-सा युग्म सही सुमेलित है?",["जमशेदपुर — टाटा स्टील","जमशेदपुर — नेवेली लिग्नाइट","जमशेदपुर — राउरकेला इस्पात संयंत्र","जमशेदपुर — सेलम इस्पात संयंत्र"],"जमशेदपुर ऐतिहासिक रूप से टाटा स्टील से जुड़ा है। अन्य संयंत्र दूसरे राज्यों में स्थित हैं।"],"pa":["ਜਮਸ਼ੇਦਪੁਰ ਦੇ ਸਟੀਲ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਜਮਸ਼ੇਦਪੁਰ — ਟਾਟਾ ਸਟੀਲ","ਜਮਸ਼ੇਦਪੁਰ — ਨੇਵੇਲੀ ਲਿਗਨਾਈਟ","ਜਮਸ਼ੇਦਪੁਰ — ਰਾਉਰਕੇਲਾ ਸਟੀਲ ਪਲਾਂਟ","ਜਮਸ਼ੇਦਪੁਰ — ਸੇਲਮ ਸਟੀਲ ਪਲਾਂਟ"],"ਜਮਸ਼ੇਦਪੁਰ ਇਤਿਹਾਸਕ ਤੌਰ 'ਤੇ ਟਾਟਾ ਸਟੀਲ ਨਾਲ ਜੁੜਿਆ ਹੈ। ਬਾਕੀ ਪਲਾਂਟ ਹੋਰ ਰਾਜਾਂ ਵਿੱਚ ਸਥਿਤ ਹਨ।"]},
"GEO-IND-001-CP002-Q012":{"h":"1f7bb210","hi":["जमशेदपुर संसाधन-उन्मुख औद्योगिक अवस्थिति का उत्कृष्ट उदाहरण क्यों है?",["यह केवल तटीय पर्यटन पर निर्भर है","यह लौह अयस्क, कोयला, जल और परिवहन मार्गों के पास स्थित है","इसका कोई खनिज पृष्ठप्रदेश नहीं है","इसकी अवस्थिति केवल जलवायु के कारण है"],"यह शहर प्रमुख खनिज और परिवहन संसाधनों के पास विकसित हुआ, जो दिखाता है कि भारी उद्योग में कई अवस्थिति कारक एक साथ कैसे काम करते हैं।"],"pa":["ਜਮਸ਼ੇਦਪੁਰ ਸਾਧਨ-ਮੁਖੀ ਉਦਯੋਗਿਕ ਸਥਾਨੀਕਰਨ ਦੀ ਉੱਤਮ ਉਦਾਹਰਨ ਕਿਉਂ ਹੈ?",["ਇਹ ਸਿਰਫ਼ ਤਟੀ ਸੈਰ-ਸਪਾਟੇ 'ਤੇ ਨਿਰਭਰ ਹੈ","ਇਹ ਕੱਚੇ ਲੋਹੇ, ਕੋਲੇ, ਪਾਣੀ ਅਤੇ ਆਵਾਜਾਈ ਮਾਰਗਾਂ ਦੇ ਨੇੜੇ ਸਥਿਤ ਹੈ","ਇਸ ਦਾ ਕੋਈ ਖਣਿਜ ਪਿਛਵਾੜਾ ਖੇਤਰ ਨਹੀਂ","ਇਸ ਦਾ ਸਥਾਨ ਸਿਰਫ਼ ਜਲਵਾਯੂ ਕਾਰਨ ਹੈ"],"ਇਹ ਸ਼ਹਿਰ ਪ੍ਰਮੁੱਖ ਖਣਿਜ ਅਤੇ ਆਵਾਜਾਈ ਸਾਧਨਾਂ ਦੇ ਨੇੜੇ ਵਿਕਸਿਤ ਹੋਇਆ, ਜੋ ਦਿਖਾਉਂਦਾ ਹੈ ਕਿ ਭਾਰੀ ਉਦਯੋਗ ਵਿੱਚ ਕਈ ਸਥਾਨਕ ਕਾਰਕ ਇਕੱਠੇ ਕਿਵੇਂ ਕੰਮ ਕਰਦੇ ਹਨ।"]},
"GEO-IND-001-CP002-Q013":{"h":"db863f95","hi":["भिलाई इस्पात संयंत्र किस राज्य में स्थित है?",["झारखंड","छत्तीसगढ़","ओडिशा","पश्चिम बंगाल"],"भिलाई इस्पात संयंत्र छत्तीसगढ़ में है और भारत के प्रमुख सार्वजनिक क्षेत्र के एकीकृत इस्पात संयंत्रों में से एक है।"],"pa":["ਭਿਲਾਈ ਸਟੀਲ ਪਲਾਂਟ ਕਿਸ ਰਾਜ ਵਿੱਚ ਸਥਿਤ ਹੈ?",["ਝਾਰਖੰਡ","ਛੱਤੀਸਗੜ੍ਹ","ਓਡੀਸ਼ਾ","ਪੱਛਮੀ ਬੰਗਾਲ"],"ਭਿਲਾਈ ਸਟੀਲ ਪਲਾਂਟ ਛੱਤੀਸਗੜ੍ਹ ਵਿੱਚ ਹੈ ਅਤੇ ਭਾਰਤ ਦੇ ਪ੍ਰਮੁੱਖ ਜਨਤਕ ਖੇਤਰ ਦੇ ਏਕੀਕ੍ਰਿਤ ਸਟੀਲ ਪਲਾਂਟਾਂ ਵਿੱਚੋਂ ਇੱਕ ਹੈ।"]},
"GEO-IND-001-CP002-Q014":{"h":"165ef3be","hi":["भिलाई इस्पात संयंत्र का संचालन किस सार्वजनिक क्षेत्र की कंपनी करती है?",["टाटा स्टील","आरआईएनएल (RINL)","सेल (SAIL)","नाल्को (NALCO)"],"भिलाई, स्टील अथॉरिटी ऑफ़ इंडिया लिमिटेड (SAIL) द्वारा संचालित एकीकृत इस्पात संयंत्रों में से एक है।"],"pa":["ਭਿਲਾਈ ਸਟੀਲ ਪਲਾਂਟ ਦਾ ਸੰਚਾਲਨ ਕਿਹੜੀ ਜਨਤਕ ਖੇਤਰ ਦੀ ਕੰਪਨੀ ਕਰਦੀ ਹੈ?",["ਟਾਟਾ ਸਟੀਲ","ਆਰਆਈਐਨਐਲ (RINL)","ਸੇਲ (SAIL)","ਨਾਲਕੋ (NALCO)"],"ਭਿਲਾਈ, ਸਟੀਲ ਅਥਾਰਟੀ ਆਫ਼ ਇੰਡੀਆ ਲਿਮਟਿਡ (SAIL) ਵੱਲੋਂ ਚਲਾਏ ਜਾਂਦੇ ਏਕੀਕ੍ਰਿਤ ਸਟੀਲ ਪਲਾਂਟਾਂ ਵਿੱਚੋਂ ਇੱਕ ਹੈ।"]},
"GEO-IND-001-CP002-Q015":{"h":"e13e5056","hi":["कौन-सा लौह अयस्क क्षेत्र भिलाई इस्पात संयंत्र से निकट रूप से जुड़ा है?",["कोडरमा","सांभर","पन्ना","दल्ली-राजहरा"],"छत्तीसगढ़ का दल्ली-राजहरा लंबे समय से भिलाई को लौह अयस्क देता रहा है। यह भारतीय औद्योगिक भूगोल में कच्चे माल के संबंध का उत्कृष्ट उदाहरण है।"],"pa":["ਕਿਹੜਾ ਕੱਚੇ ਲੋਹੇ ਦਾ ਖੇਤਰ ਭਿਲਾਈ ਸਟੀਲ ਪਲਾਂਟ ਨਾਲ ਨੇੜਿਓਂ ਜੁੜਿਆ ਹੈ?",["ਕੋਡਰਮਾ","ਸਾਂਭਰ","ਪੰਨਾ","ਦੱਲੀ-ਰਾਜਹਰਾ"],"ਛੱਤੀਸਗੜ੍ਹ ਦਾ ਦੱਲੀ-ਰਾਜਹਰਾ ਲੰਮੇ ਸਮੇਂ ਤੋਂ ਭਿਲਾਈ ਨੂੰ ਕੱਚਾ ਲੋਹਾ ਦਿੰਦਾ ਆ ਰਿਹਾ ਹੈ। ਇਹ ਭਾਰਤੀ ਉਦਯੋਗਿਕ ਭੂਗੋਲ ਵਿੱਚ ਕੱਚੇ ਮਾਲ ਦੇ ਸੰਬੰਧ ਦੀ ਉੱਤਮ ਉਦਾਹਰਨ ਹੈ।"]},
"GEO-IND-001-CP002-Q016":{"h":"bd8fe9eb","hi":["कथनों पर विचार कीजिए: I. भिलाई छत्तीसगढ़ में है। II. यह सेल (SAIL) का एकीकृत इस्पात संयंत्र है। कौन-सा/से कथन सही है/हैं?",["I और II दोनों सही हैं","केवल I सही है","केवल II सही है","न तो I और न ही II सही है"],"भिलाई की अवस्थिति और उसका सेल (SAIL) से संबंध, दोनों तथ्य सही हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਭਿਲਾਈ ਛੱਤੀਸਗੜ੍ਹ ਵਿੱਚ ਹੈ। II. ਇਹ ਸੇਲ (SAIL) ਦਾ ਏਕੀਕ੍ਰਿਤ ਸਟੀਲ ਪਲਾਂਟ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਭਿਲਾਈ ਦਾ ਸਥਾਨ ਅਤੇ ਸੇਲ (SAIL) ਨਾਲ ਇਸ ਦਾ ਸੰਬੰਧ, ਦੋਵੇਂ ਤੱਥ ਸਹੀ ਹਨ।"]},
"GEO-IND-001-CP002-Q017":{"h":"b5254e01","hi":["भिलाई के इस्पात भूगोल में कौन-सा युग्म सही सुमेलित है?",["भिलाई — ओडिशा","भिलाई — छत्तीसगढ़","भिलाई — तमिलनाडु","भिलाई — आंध्र प्रदेश"],"भिलाई छत्तीसगढ़ में स्थित है। राउरकेला ओडिशा में, सेलम तमिलनाडु में और विशाखापत्तनम आंध्र प्रदेश में है।"],"pa":["ਭਿਲਾਈ ਦੇ ਸਟੀਲ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਭਿਲਾਈ — ਓਡੀਸ਼ਾ","ਭਿਲਾਈ — ਛੱਤੀਸਗੜ੍ਹ","ਭਿਲਾਈ — ਤਾਮਿਲਨਾਡੂ","ਭਿਲਾਈ — ਆਂਧਰਾ ਪ੍ਰਦੇਸ਼"],"ਭਿਲਾਈ ਛੱਤੀਸਗੜ੍ਹ ਵਿੱਚ ਸਥਿਤ ਹੈ। ਰਾਉਰਕੇਲਾ ਓਡੀਸ਼ਾ ਵਿੱਚ, ਸੇਲਮ ਤਾਮਿਲਨਾਡੂ ਵਿੱਚ ਅਤੇ ਵਿਸ਼ਾਖਾਪਟਨਮ ਆਂਧਰਾ ਪ੍ਰਦੇਸ਼ ਵਿੱਚ ਹੈ।"]},
"GEO-IND-001-CP002-Q018":{"h":"863897b6","hi":["भिलाई और दल्ली-राजहरा किस उद्योग-संसाधन संबंध को दर्शाते हैं?",["चाय बागानों से जुड़ी चीनी मिल","जूट से जुड़ा सीमेंट संयंत्र","पास के लौह अयस्क से जुड़ा इस्पात संयंत्र","यूरेनियम से जुड़ी कपड़ा मिल"],"भिलाई और दल्ली-राजहरा का संबंध दर्शाता है कि एकीकृत इस्पात संयंत्र के लिए पास में लौह अयस्क की आपूर्ति कितनी महत्वपूर्ण है।"],"pa":["ਭਿਲਾਈ ਅਤੇ ਦੱਲੀ-ਰਾਜਹਰਾ ਕਿਹੜੇ ਉਦਯੋਗ-ਸਾਧਨ ਸੰਬੰਧ ਨੂੰ ਦਰਸਾਉਂਦੇ ਹਨ?",["ਚਾਹ ਦੇ ਬਾਗ਼ਾਂ ਨਾਲ ਜੁੜੀ ਖੰਡ ਮਿੱਲ","ਪਟਸਨ ਨਾਲ ਜੁੜਿਆ ਸੀਮਿੰਟ ਪਲਾਂਟ","ਨੇੜਲੇ ਕੱਚੇ ਲੋਹੇ ਨਾਲ ਜੁੜਿਆ ਸਟੀਲ ਪਲਾਂਟ","ਯੂਰੇਨੀਅਮ ਨਾਲ ਜੁੜੀ ਕੱਪੜਾ ਮਿੱਲ"],"ਭਿਲਾਈ ਅਤੇ ਦੱਲੀ-ਰਾਜਹਰਾ ਦਾ ਸੰਬੰਧ ਦਰਸਾਉਂਦਾ ਹੈ ਕਿ ਏਕੀਕ੍ਰਿਤ ਸਟੀਲ ਪਲਾਂਟ ਲਈ ਨੇੜੇ ਕੱਚੇ ਲੋਹੇ ਦੀ ਸਪਲਾਈ ਕਿੰਨੀ ਮਹੱਤਵਪੂਰਨ ਹੈ।"]},
"GEO-IND-001-CP002-Q019":{"h":"7dcf67ef","hi":["राउरकेला इस्पात संयंत्र किस राज्य में स्थित है?",["झारखंड","ओडिशा","छत्तीसगढ़","पश्चिम बंगाल"],"राउरकेला इस्पात संयंत्र ओडिशा में है और खनिज-संपन्न पूर्वी औद्योगिक क्षेत्र का भाग है।"],"pa":["ਰਾਉਰਕੇਲਾ ਸਟੀਲ ਪਲਾਂਟ ਕਿਸ ਰਾਜ ਵਿੱਚ ਸਥਿਤ ਹੈ?",["ਝਾਰਖੰਡ","ਓਡੀਸ਼ਾ","ਛੱਤੀਸਗੜ੍ਹ","ਪੱਛਮੀ ਬੰਗਾਲ"],"ਰਾਉਰਕੇਲਾ ਸਟੀਲ ਪਲਾਂਟ ਓਡੀਸ਼ਾ ਵਿੱਚ ਹੈ ਅਤੇ ਖਣਿਜਾਂ ਨਾਲ ਭਰਪੂਰ ਪੂਰਬੀ ਉਦਯੋਗਿਕ ਖੇਤਰ ਦਾ ਹਿੱਸਾ ਹੈ।"]},
"GEO-IND-001-CP002-Q020":{"h":"d6607ef7","hi":["राउरकेला इस्पात संयंत्र का संचालन कौन-सी कंपनी करती है?",["टाटा स्टील","आरआईएनएल (RINL)","सेल (SAIL)","केवल जेएसडब्ल्यू (JSW)"],"राउरकेला, स्टील अथॉरिटी ऑफ़ इंडिया लिमिटेड के अधीन एकीकृत इस्पात संयंत्रों में से एक है।"],"pa":["ਰਾਉਰਕੇਲਾ ਸਟੀਲ ਪਲਾਂਟ ਦਾ ਸੰਚਾਲਨ ਕਿਹੜੀ ਕੰਪਨੀ ਕਰਦੀ ਹੈ?",["ਟਾਟਾ ਸਟੀਲ","ਆਰਆਈਐਨਐਲ (RINL)","ਸੇਲ (SAIL)","ਸਿਰਫ਼ ਜੇਐਸਡਬਲਿਊ (JSW)"],"ਰਾਉਰਕੇਲਾ, ਸਟੀਲ ਅਥਾਰਟੀ ਆਫ਼ ਇੰਡੀਆ ਲਿਮਟਿਡ ਅਧੀਨ ਏਕੀਕ੍ਰਿਤ ਸਟੀਲ ਪਲਾਂਟਾਂ ਵਿੱਚੋਂ ਇੱਕ ਹੈ।"]},
"GEO-IND-001-CP002-Q021":{"h":"0c71d0c6","hi":["राउरकेला के आसपास इस्पात उत्पादन को कौन-सा खनिज संसाधन मज़बूती से सहारा देता है?",["केवल कोडरमा का अभ्रक","सांभर का नमक","डिगबोई का पेट्रोलियम","ओडिशा की खनिज पट्टी का लौह अयस्क"],"राउरकेला को कोयला, चूना पत्थर और परिवहन संपर्कों के साथ-साथ ओडिशा के समृद्ध लौह अयस्क संसाधनों का लाभ मिलता है।"],"pa":["ਰਾਉਰਕੇਲਾ ਦੇ ਆਲੇ-ਦੁਆਲੇ ਸਟੀਲ ਉਤਪਾਦਨ ਨੂੰ ਕਿਹੜਾ ਖਣਿਜ ਸਾਧਨ ਮਜ਼ਬੂਤ ਸਹਾਰਾ ਦਿੰਦਾ ਹੈ?",["ਸਿਰਫ਼ ਕੋਡਰਮਾ ਦਾ ਅਬਰਕ","ਸਾਂਭਰ ਦਾ ਲੂਣ","ਡਿਗਬੋਈ ਦਾ ਪੈਟਰੋਲੀਅਮ","ਓਡੀਸ਼ਾ ਦੀ ਖਣਿਜ ਪੱਟੀ ਦਾ ਕੱਚਾ ਲੋਹਾ"],"ਰਾਉਰਕੇਲਾ ਨੂੰ ਕੋਲੇ, ਚੂਨਾ ਪੱਥਰ ਅਤੇ ਆਵਾਜਾਈ ਸੰਪਰਕਾਂ ਦੇ ਨਾਲ-ਨਾਲ ਓਡੀਸ਼ਾ ਦੇ ਭਰਪੂਰ ਕੱਚੇ ਲੋਹੇ ਦੇ ਸਾਧਨਾਂ ਦਾ ਲਾਭ ਮਿਲਦਾ ਹੈ।"]},
"GEO-IND-001-CP002-Q022":{"h":"8e293444","hi":["कथनों पर विचार कीजिए: I. राउरकेला ओडिशा में है। II. यह पूर्वी इस्पात पट्टी का भाग है। कौन-सा/से कथन सही है/हैं?",["I और II दोनों सही हैं","केवल I सही है","केवल II सही है","न तो I और न ही II सही है"],"राउरकेला ओडिशा में है और पूर्वी भारत की खनिज-आधारित औद्योगिक पट्टी का भाग है।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਰਾਉਰਕੇਲਾ ਓਡੀਸ਼ਾ ਵਿੱਚ ਹੈ। II. ਇਹ ਪੂਰਬੀ ਸਟੀਲ ਪੱਟੀ ਦਾ ਹਿੱਸਾ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਰਾਉਰਕੇਲਾ ਓਡੀਸ਼ਾ ਵਿੱਚ ਹੈ ਅਤੇ ਪੂਰਬੀ ਭਾਰਤ ਦੀ ਖਣਿਜ-ਅਧਾਰਿਤ ਉਦਯੋਗਿਕ ਪੱਟੀ ਦਾ ਹਿੱਸਾ ਹੈ।"]},
"GEO-IND-001-CP002-Q023":{"h":"6b62470b","hi":["राउरकेला के इस्पात भूगोल में कौन-सा युग्म सही सुमेलित है?",["राउरकेला — झारखंड","राउरकेला — ओडिशा","राउरकेला — कर्नाटक","राउरकेला — तमिलनाडु"],"राउरकेला ओडिशा का इस्पात केंद्र है। अन्य राज्य युग्म गलत हैं।"],"pa":["ਰਾਉਰਕੇਲਾ ਦੇ ਸਟੀਲ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਰਾਉਰਕੇਲਾ — ਝਾਰਖੰਡ","ਰਾਉਰਕੇਲਾ — ਓਡੀਸ਼ਾ","ਰਾਉਰਕੇਲਾ — ਕਰਨਾਟਕ","ਰਾਉਰਕੇਲਾ — ਤਾਮਿਲਨਾਡੂ"],"ਰਾਉਰਕੇਲਾ ਓਡੀਸ਼ਾ ਦਾ ਸਟੀਲ ਕੇਂਦਰ ਹੈ। ਬਾਕੀ ਰਾਜਾਂ ਵਾਲੇ ਜੋੜੇ ਗਲਤ ਹਨ।"]},
"GEO-IND-001-CP002-Q024":{"h":"a37e8e0d","hi":["राउरकेला खनिज-आधारित औद्योगिक अवस्थिति का महत्वपूर्ण उदाहरण क्यों है?",["यह केवल तटीय मत्स्यन पर निर्भर है","इसकी खनिजों तक कोई पहुँच नहीं है","यह प्रमुख लौह अयस्क और कोयला क्षेत्रों के पास स्थित है","इसकी अवस्थिति केवल पर्यटन से तय होती है"],"इसकी अवस्थिति खनिज कच्चे माल, बिजली, जल और परिवहन तक पहुँच को दर्शाती है, जो भारी उद्योग के लिए मुख्य हैं।"],"pa":["ਰਾਉਰਕੇਲਾ ਖਣਿਜ-ਅਧਾਰਿਤ ਉਦਯੋਗਿਕ ਸਥਾਨੀਕਰਨ ਦੀ ਮਹੱਤਵਪੂਰਨ ਉਦਾਹਰਨ ਕਿਉਂ ਹੈ?",["ਇਹ ਸਿਰਫ਼ ਤਟੀ ਮੱਛੀ ਫੜਨ 'ਤੇ ਨਿਰਭਰ ਹੈ","ਇਸ ਦੀ ਖਣਿਜਾਂ ਤੱਕ ਕੋਈ ਪਹੁੰਚ ਨਹੀਂ","ਇਹ ਪ੍ਰਮੁੱਖ ਕੱਚੇ ਲੋਹੇ ਅਤੇ ਕੋਲੇ ਵਾਲੇ ਖੇਤਰਾਂ ਦੇ ਨੇੜੇ ਸਥਿਤ ਹੈ","ਇਸ ਦਾ ਸਥਾਨ ਸਿਰਫ਼ ਸੈਰ-ਸਪਾਟੇ ਨਾਲ ਤੈਅ ਹੁੰਦਾ ਹੈ"],"ਇਸ ਦਾ ਸਥਾਨ ਖਣਿਜ ਕੱਚੇ ਮਾਲ, ਬਿਜਲੀ, ਪਾਣੀ ਅਤੇ ਆਵਾਜਾਈ ਤੱਕ ਪਹੁੰਚ ਨੂੰ ਦਰਸਾਉਂਦਾ ਹੈ, ਜੋ ਭਾਰੀ ਉਦਯੋਗ ਲਈ ਮੁੱਖ ਹਨ।"]},
"GEO-IND-001-CP002-Q025":{"h":"ed4631a0","hi":["दुर्गापुर इस्पात संयंत्र किस राज्य में स्थित है?",["पश्चिम बंगाल","झारखंड","ओडिशा","छत्तीसगढ़"],"दुर्गापुर इस्पात संयंत्र पश्चिम बंगाल में दामोदर औद्योगिक क्षेत्र में स्थित है।"],"pa":["ਦੁਰਗਾਪੁਰ ਸਟੀਲ ਪਲਾਂਟ ਕਿਸ ਰਾਜ ਵਿੱਚ ਸਥਿਤ ਹੈ?",["ਪੱਛਮੀ ਬੰਗਾਲ","ਝਾਰਖੰਡ","ਓਡੀਸ਼ਾ","ਛੱਤੀਸਗੜ੍ਹ"],"ਦੁਰਗਾਪੁਰ ਸਟੀਲ ਪਲਾਂਟ ਪੱਛਮੀ ਬੰਗਾਲ ਵਿੱਚ ਦਾਮੋਦਰ ਉਦਯੋਗਿਕ ਖੇਤਰ ਵਿੱਚ ਸਥਿਤ ਹੈ।"]},
"GEO-IND-001-CP002-Q026":{"h":"b0e41e92","hi":["बर्नपुर किस उद्योग के लिए प्रसिद्ध है?",["केवल जूट","लौह-इस्पात","केवल पेट्रोलियम शोधन","केवल एल्युमिनियम प्रगलन"],"पश्चिम बंगाल का बर्नपुर एक प्रमुख लौह-इस्पात केंद्र है, जहाँ इस्को (IISCO) इस्पात संयंत्र स्थित है।"],"pa":["ਬਰਨਪੁਰ ਕਿਸ ਉਦਯੋਗ ਲਈ ਮਸ਼ਹੂਰ ਹੈ?",["ਸਿਰਫ਼ ਪਟਸਨ","ਲੋਹਾ-ਸਟੀਲ","ਸਿਰਫ਼ ਪੈਟਰੋਲੀਅਮ ਸੋਧ","ਸਿਰਫ਼ ਐਲੂਮੀਨੀਅਮ ਪਿਘਲਾਈ"],"ਪੱਛਮੀ ਬੰਗਾਲ ਦਾ ਬਰਨਪੁਰ ਇੱਕ ਪ੍ਰਮੁੱਖ ਲੋਹਾ-ਸਟੀਲ ਕੇਂਦਰ ਹੈ, ਜਿੱਥੇ ਇਸਕੋ (IISCO) ਸਟੀਲ ਪਲਾਂਟ ਸਥਿਤ ਹੈ।"]},
"GEO-IND-001-CP002-Q027":{"h":"1d060e0f","hi":["दुर्गापुर-आसनसोल-बर्नपुर औद्योगिक पट्टी के निकट कौन-सा कोयला क्षेत्र स्थित है?",["नेवेली","माकुम","रानीगंज","केवल सिंगरौली"],"रानीगंज कोयला क्षेत्र आसनसोल-दुर्गापुर-बर्नपुर पट्टी के पास है और इसने वहाँ भारी उद्योगों के विकास में मदद की।"],"pa":["ਦੁਰਗਾਪੁਰ-ਆਸਨਸੋਲ-ਬਰਨਪੁਰ ਉਦਯੋਗਿਕ ਪੱਟੀ ਦੇ ਨੇੜੇ ਕਿਹੜਾ ਕੋਲਾ ਖੇਤਰ ਸਥਿਤ ਹੈ?",["ਨੇਵੇਲੀ","ਮਾਕੁਮ","ਰਾਣੀਗੰਜ","ਸਿਰਫ਼ ਸਿੰਗਰੌਲੀ"],"ਰਾਣੀਗੰਜ ਕੋਲਾ ਖੇਤਰ ਆਸਨਸੋਲ-ਦੁਰਗਾਪੁਰ-ਬਰਨਪੁਰ ਪੱਟੀ ਦੇ ਨੇੜੇ ਹੈ ਅਤੇ ਇਸ ਨੇ ਉੱਥੇ ਭਾਰੀ ਉਦਯੋਗਾਂ ਦੇ ਵਿਕਾਸ ਵਿੱਚ ਮਦਦ ਕੀਤੀ।"]},
"GEO-IND-001-CP002-Q028":{"h":"f26cf110","hi":["कथनों पर विचार कीजिए: I. दुर्गापुर और बर्नपुर पश्चिम बंगाल में हैं। II. दोनों दामोदर औद्योगिक क्षेत्र से संबंधित हैं। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","न तो I और न ही II सही है","I और II दोनों सही हैं"],"दोनों केंद्र पश्चिम बंगाल में हैं और कोयला-आधारित दामोदर औद्योगिक पट्टी का भाग हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਦੁਰਗਾਪੁਰ ਅਤੇ ਬਰਨਪੁਰ ਪੱਛਮੀ ਬੰਗਾਲ ਵਿੱਚ ਹਨ। II. ਦੋਵੇਂ ਦਾਮੋਦਰ ਉਦਯੋਗਿਕ ਖੇਤਰ ਨਾਲ ਸੰਬੰਧਿਤ ਹਨ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ"],"ਦੋਵੇਂ ਕੇਂਦਰ ਪੱਛਮੀ ਬੰਗਾਲ ਵਿੱਚ ਹਨ ਅਤੇ ਕੋਲਾ-ਅਧਾਰਿਤ ਦਾਮੋਦਰ ਉਦਯੋਗਿਕ ਪੱਟੀ ਦਾ ਹਿੱਸਾ ਹਨ।"]},
"GEO-IND-001-CP002-Q029":{"h":"7c78ea5c","hi":["पश्चिम बंगाल के इस्पात भूगोल में कौन-सा युग्म सही सुमेलित है?",["बर्नपुर — इस्को (IISCO) इस्पात संयंत्र","बर्नपुर — भिलाई इस्पात संयंत्र","दुर्गापुर — राउरकेला इस्पात संयंत्र","आसनसोल — सेलम इस्पात संयंत्र"],"बर्नपुर में इस्को (IISCO) इस्पात संयंत्र है, जबकि दुर्गापुर में सेल (SAIL) का अपना इस्पात संयंत्र है।"],"pa":["ਪੱਛਮੀ ਬੰਗਾਲ ਦੇ ਸਟੀਲ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਬਰਨਪੁਰ — ਇਸਕੋ (IISCO) ਸਟੀਲ ਪਲਾਂਟ","ਬਰਨਪੁਰ — ਭਿਲਾਈ ਸਟੀਲ ਪਲਾਂਟ","ਦੁਰਗਾਪੁਰ — ਰਾਉਰਕੇਲਾ ਸਟੀਲ ਪਲਾਂਟ","ਆਸਨਸੋਲ — ਸੇਲਮ ਸਟੀਲ ਪਲਾਂਟ"],"ਬਰਨਪੁਰ ਵਿੱਚ ਇਸਕੋ (IISCO) ਸਟੀਲ ਪਲਾਂਟ ਹੈ, ਜਦਕਿ ਦੁਰਗਾਪੁਰ ਵਿੱਚ ਸੇਲ (SAIL) ਦਾ ਆਪਣਾ ਸਟੀਲ ਪਲਾਂਟ ਹੈ।"]},
"GEO-IND-001-CP002-Q030":{"h":"9a52fc6d","hi":["दुर्गापुर-आसनसोल-बर्नपुर पट्टी भारी उद्योग क्षेत्र के रूप में क्यों विकसित हुई?",["केवल उपजाऊ मिट्टी महत्वपूर्ण थी","वहाँ कोयला, परिवहन, श्रम और पास के खनिज संसाधन उपलब्ध थे","वहाँ परिवहन संपर्क नहीं थे","यह केवल पर्यटन पर निर्भर थी"],"दामोदर पट्टी में कोयला, रेलमार्ग, श्रम और खनिज कच्चे माल तक पहुँच एक साथ उपलब्ध थी, जो इस्पात और अभियांत्रिकी उद्योगों के अनुकूल थी।"],"pa":["ਦੁਰਗਾਪੁਰ-ਆਸਨਸੋਲ-ਬਰਨਪੁਰ ਪੱਟੀ ਭਾਰੀ ਉਦਯੋਗ ਖੇਤਰ ਵਜੋਂ ਕਿਉਂ ਵਿਕਸਿਤ ਹੋਈ?",["ਸਿਰਫ਼ ਉਪਜਾਊ ਮਿੱਟੀ ਮਹੱਤਵਪੂਰਨ ਸੀ","ਉੱਥੇ ਕੋਲਾ, ਆਵਾਜਾਈ, ਕਿਰਤ ਅਤੇ ਨੇੜਲੇ ਖਣਿਜ ਸਾਧਨ ਉਪਲਬਧ ਸਨ","ਉੱਥੇ ਆਵਾਜਾਈ ਸੰਪਰਕ ਨਹੀਂ ਸਨ","ਇਹ ਸਿਰਫ਼ ਸੈਰ-ਸਪਾਟੇ 'ਤੇ ਨਿਰਭਰ ਸੀ"],"ਦਾਮੋਦਰ ਪੱਟੀ ਵਿੱਚ ਕੋਲਾ, ਰੇਲਮਾਰਗ, ਕਿਰਤ ਅਤੇ ਖਣਿਜ ਕੱਚੇ ਮਾਲ ਤੱਕ ਪਹੁੰਚ ਇਕੱਠੀ ਉਪਲਬਧ ਸੀ, ਜੋ ਸਟੀਲ ਅਤੇ ਇੰਜੀਨੀਅਰਿੰਗ ਉਦਯੋਗਾਂ ਦੇ ਅਨੁਕੂਲ ਸੀ।"]},
"GEO-IND-001-CP002-Q031":{"h":"9f584d48","hi":["बोकारो इस्पात संयंत्र किस राज्य में स्थित है?",["झारखंड","ओडिशा","पश्चिम बंगाल","छत्तीसगढ़"],"बोकारो इस्पात संयंत्र झारखंड में है और छोटानागपुर-दामोदर औद्योगिक क्षेत्र का भाग है।"],"pa":["ਬੋਕਾਰੋ ਸਟੀਲ ਪਲਾਂਟ ਕਿਸ ਰਾਜ ਵਿੱਚ ਸਥਿਤ ਹੈ?",["ਝਾਰਖੰਡ","ਓਡੀਸ਼ਾ","ਪੱਛਮੀ ਬੰਗਾਲ","ਛੱਤੀਸਗੜ੍ਹ"],"ਬੋਕਾਰੋ ਸਟੀਲ ਪਲਾਂਟ ਝਾਰਖੰਡ ਵਿੱਚ ਹੈ ਅਤੇ ਛੋਟਾਨਾਗਪੁਰ-ਦਾਮੋਦਰ ਉਦਯੋਗਿਕ ਖੇਤਰ ਦਾ ਹਿੱਸਾ ਹੈ।"]},
"GEO-IND-001-CP002-Q032":{"h":"852cdf09","hi":["बोकारो इस्पात संयंत्र का संचालन किस सार्वजनिक क्षेत्र की कंपनी करती है?",["टाटा स्टील","सेल (SAIL)","आरआईएनएल (RINL)","नाल्को (NALCO)"],"बोकारो, स्टील अथॉरिटी ऑफ़ इंडिया लिमिटेड के अधीन एकीकृत इस्पात संयंत्रों में से एक है।"],"pa":["ਬੋਕਾਰੋ ਸਟੀਲ ਪਲਾਂਟ ਦਾ ਸੰਚਾਲਨ ਕਿਹੜੀ ਜਨਤਕ ਖੇਤਰ ਦੀ ਕੰਪਨੀ ਕਰਦੀ ਹੈ?",["ਟਾਟਾ ਸਟੀਲ","ਸੇਲ (SAIL)","ਆਰਆਈਐਨਐਲ (RINL)","ਨਾਲਕੋ (NALCO)"],"ਬੋਕਾਰੋ, ਸਟੀਲ ਅਥਾਰਟੀ ਆਫ਼ ਇੰਡੀਆ ਲਿਮਟਿਡ ਅਧੀਨ ਏਕੀਕ੍ਰਿਤ ਸਟੀਲ ਪਲਾਂਟਾਂ ਵਿੱਚੋਂ ਇੱਕ ਹੈ।"]},
"GEO-IND-001-CP002-Q033":{"h":"90877264","hi":["बोकारो की औद्योगिक अवस्थिति से कौन-सा कोयला क्षेत्र निकट रूप से जुड़ा है?",["नेवेली लिग्नाइट क्षेत्र","असम के तेल क्षेत्र","दामोदर घाटी के कोयला क्षेत्र","राजस्थान की नमक पट्टी"],"बोकारो दामोदर कोयला क्षेत्र में स्थित है, जिससे इसे प्रमुख कोयला संसाधनों और परिवहन अवसंरचना तक पहुँच मिलती है।"],"pa":["ਬੋਕਾਰੋ ਦੇ ਉਦਯੋਗਿਕ ਸਥਾਨ ਨਾਲ ਕਿਹੜਾ ਕੋਲਾ ਖੇਤਰ ਨੇੜਿਓਂ ਜੁੜਿਆ ਹੈ?",["ਨੇਵੇਲੀ ਲਿਗਨਾਈਟ ਖੇਤਰ","ਅਸਾਮ ਦੇ ਤੇਲ ਖੇਤਰ","ਦਾਮੋਦਰ ਘਾਟੀ ਦੇ ਕੋਲਾ ਖੇਤਰ","ਰਾਜਸਥਾਨ ਦੀ ਲੂਣ ਪੱਟੀ"],"ਬੋਕਾਰੋ ਦਾਮੋਦਰ ਕੋਲਾ ਖੇਤਰ ਵਿੱਚ ਸਥਿਤ ਹੈ, ਜਿਸ ਨਾਲ ਇਸ ਨੂੰ ਪ੍ਰਮੁੱਖ ਕੋਲਾ ਸਾਧਨਾਂ ਅਤੇ ਆਵਾਜਾਈ ਦੇ ਬੁਨਿਆਦੀ ਢਾਂਚੇ ਤੱਕ ਪਹੁੰਚ ਮਿਲਦੀ ਹੈ।"]},
"GEO-IND-001-CP002-Q034":{"h":"4ba37579","hi":["कथनों पर विचार कीजिए: I. बोकारो झारखंड में है। II. यह एक प्रमुख एकीकृत इस्पात केंद्र है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","न तो I और न ही II सही है","I और II दोनों सही हैं"],"बोकारो झारखंड का एक प्रमुख इस्पात केंद्र है और सेल (SAIL) के एकीकृत संयंत्रों में से एक है।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਬੋਕਾਰੋ ਝਾਰਖੰਡ ਵਿੱਚ ਹੈ। II. ਇਹ ਇੱਕ ਪ੍ਰਮੁੱਖ ਏਕੀਕ੍ਰਿਤ ਸਟੀਲ ਕੇਂਦਰ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ"],"ਬੋਕਾਰੋ ਝਾਰਖੰਡ ਦਾ ਇੱਕ ਪ੍ਰਮੁੱਖ ਸਟੀਲ ਕੇਂਦਰ ਹੈ ਅਤੇ ਸੇਲ (SAIL) ਦੇ ਏਕੀਕ੍ਰਿਤ ਪਲਾਂਟਾਂ ਵਿੱਚੋਂ ਇੱਕ ਹੈ।"]},
"GEO-IND-001-CP002-Q035":{"h":"9055004d","hi":["बोकारो के इस्पात भूगोल में कौन-सा युग्म सही सुमेलित है?",["बोकारो — झारखंड","बोकारो — ओडिशा","बोकारो — तमिलनाडु","बोकारो — आंध्र प्रदेश"],"बोकारो झारखंड में है। अन्य राज्य गलत हैं।"],"pa":["ਬੋਕਾਰੋ ਦੇ ਸਟੀਲ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਬੋਕਾਰੋ — ਝਾਰਖੰਡ","ਬੋਕਾਰੋ — ਓਡੀਸ਼ਾ","ਬੋਕਾਰੋ — ਤਾਮਿਲਨਾਡੂ","ਬੋਕਾਰੋ — ਆਂਧਰਾ ਪ੍ਰਦੇਸ਼"],"ਬੋਕਾਰੋ ਝਾਰਖੰਡ ਵਿੱਚ ਹੈ। ਬਾਕੀ ਰਾਜ ਗਲਤ ਹਨ।"]},
"GEO-IND-001-CP002-Q036":{"h":"d160f482","hi":["बोकारो औद्योगिक अवस्थिति के बारे में क्या दर्शाता है?",["इस्पात संयंत्रों को कच्चे माल की आवश्यकता नहीं होती","भारी उद्योग वहाँ केंद्रित हो सकते हैं जहाँ कोयला, अयस्क, जल और परिवहन सुलभ हों","केवल बाज़ार का आकार महत्वपूर्ण है","इस्पात भूगोल में कोयले की कोई भूमिका नहीं है"],"बोकारो की अवस्थिति भारी उद्योग में खनिज कच्चे माल, ऊर्जा, जल और परिवहन के संयुक्त महत्व को दर्शाती है।"],"pa":["ਬੋਕਾਰੋ ਉਦਯੋਗਿਕ ਸਥਾਨੀਕਰਨ ਬਾਰੇ ਕੀ ਦਰਸਾਉਂਦਾ ਹੈ?",["ਸਟੀਲ ਪਲਾਂਟਾਂ ਨੂੰ ਕੱਚੇ ਮਾਲ ਦੀ ਲੋੜ ਨਹੀਂ ਹੁੰਦੀ","ਭਾਰੀ ਉਦਯੋਗ ਉੱਥੇ ਇਕੱਠੇ ਹੋ ਸਕਦੇ ਹਨ ਜਿੱਥੇ ਕੋਲਾ, ਕੱਚੀ ਧਾਤ, ਪਾਣੀ ਅਤੇ ਆਵਾਜਾਈ ਸੌਖੇ ਮਿਲਣ","ਸਿਰਫ਼ ਬਾਜ਼ਾਰ ਦਾ ਆਕਾਰ ਮਹੱਤਵਪੂਰਨ ਹੈ","ਸਟੀਲ ਭੂਗੋਲ ਵਿੱਚ ਕੋਲੇ ਦੀ ਕੋਈ ਭੂਮਿਕਾ ਨਹੀਂ"],"ਬੋਕਾਰੋ ਦਾ ਸਥਾਨ ਭਾਰੀ ਉਦਯੋਗ ਵਿੱਚ ਖਣਿਜ ਕੱਚੇ ਮਾਲ, ਊਰਜਾ, ਪਾਣੀ ਅਤੇ ਆਵਾਜਾਈ ਦੀ ਸਾਂਝੀ ਮਹੱਤਤਾ ਨੂੰ ਦਰਸਾਉਂਦਾ ਹੈ।"]},
"GEO-IND-001-CP002-Q037":{"h":"6b6aafa3","hi":["विशाखापत्तनम इस्पात संयंत्र किस राज्य में स्थित है?",["ओडिशा","तमिलनाडु","आंध्र प्रदेश","कर्नाटक"],"विशाखापत्तनम इस्पात संयंत्र आंध्र प्रदेश के तट पर स्थित है और एक प्रमुख एकीकृत इस्पात केंद्र है।"],"pa":["ਵਿਸ਼ਾਖਾਪਟਨਮ ਸਟੀਲ ਪਲਾਂਟ ਕਿਸ ਰਾਜ ਵਿੱਚ ਸਥਿਤ ਹੈ?",["ਓਡੀਸ਼ਾ","ਤਾਮਿਲਨਾਡੂ","ਆਂਧਰਾ ਪ੍ਰਦੇਸ਼","ਕਰਨਾਟਕ"],"ਵਿਸ਼ਾਖਾਪਟਨਮ ਸਟੀਲ ਪਲਾਂਟ ਆਂਧਰਾ ਪ੍ਰਦੇਸ਼ ਦੇ ਤਟ 'ਤੇ ਸਥਿਤ ਹੈ ਅਤੇ ਇੱਕ ਪ੍ਰਮੁੱਖ ਏਕੀਕ੍ਰਿਤ ਸਟੀਲ ਕੇਂਦਰ ਹੈ।"]},
"GEO-IND-001-CP002-Q038":{"h":"16c3a9e0","hi":["विशाखापत्तनम इस्पात संयंत्र ऐतिहासिक रूप से किस कंपनी से जुड़ा है?",["सेल (SAIL)","टाटा स्टील","नाल्को (NALCO)","आरआईएनएल (RINL)"],"राष्ट्रीय इस्पात निगम लिमिटेड (RINL) सार्वजनिक क्षेत्र की वह कंपनी है जो ऐतिहासिक रूप से विशाखापत्तनम इस्पात संयंत्र से जुड़ी है।"],"pa":["ਵਿਸ਼ਾਖਾਪਟਨਮ ਸਟੀਲ ਪਲਾਂਟ ਇਤਿਹਾਸਕ ਤੌਰ 'ਤੇ ਕਿਸ ਕੰਪਨੀ ਨਾਲ ਜੁੜਿਆ ਹੈ?",["ਸੇਲ (SAIL)","ਟਾਟਾ ਸਟੀਲ","ਨਾਲਕੋ (NALCO)","ਆਰਆਈਐਨਐਲ (RINL)"],"ਰਾਸ਼ਟਰੀ ਇਸਪਾਤ ਨਿਗਮ ਲਿਮਟਿਡ (RINL) ਜਨਤਕ ਖੇਤਰ ਦੀ ਉਹ ਕੰਪਨੀ ਹੈ ਜੋ ਇਤਿਹਾਸਕ ਤੌਰ 'ਤੇ ਵਿਸ਼ਾਖਾਪਟਨਮ ਸਟੀਲ ਪਲਾਂਟ ਨਾਲ ਜੁੜੀ ਹੈ।"]},
"GEO-IND-001-CP002-Q039":{"h":"c7536126","hi":["कौन-सा अवस्थितिक लाभ विशाखापत्तनम इस्पात संयंत्र को कई आंतरिक इस्पात संयंत्रों से अलग करता है?",["प्रमुख पत्तन तक पहुँच","कोयला खदान के भीतर अवस्थिति","मरुस्थलीय नमक बेसिन में अवस्थिति","केवल स्थानीय कपास पर निर्भरता"],"इसकी तटीय अवस्थिति भारी कच्चे माल और इस्पात उत्पादों की आवाजाही के लिए पत्तन तक पहुँच देती है।"],"pa":["ਕਿਹੜਾ ਸਥਾਨਕ ਲਾਭ ਵਿਸ਼ਾਖਾਪਟਨਮ ਸਟੀਲ ਪਲਾਂਟ ਨੂੰ ਕਈ ਅੰਦਰੂਨੀ ਸਟੀਲ ਪਲਾਂਟਾਂ ਤੋਂ ਵੱਖ ਕਰਦਾ ਹੈ?",["ਪ੍ਰਮੁੱਖ ਬੰਦਰਗਾਹ ਤੱਕ ਪਹੁੰਚ","ਕੋਲਾ ਖਾਣ ਦੇ ਅੰਦਰ ਸਥਾਨ","ਮਾਰੂਥਲੀ ਲੂਣ ਬੇਸਿਨ ਵਿੱਚ ਸਥਾਨ","ਸਿਰਫ਼ ਸਥਾਨਕ ਕਪਾਹ 'ਤੇ ਨਿਰਭਰਤਾ"],"ਇਸ ਦਾ ਤਟੀ ਸਥਾਨ ਭਾਰੀ ਕੱਚੇ ਮਾਲ ਅਤੇ ਸਟੀਲ ਉਤਪਾਦਾਂ ਦੀ ਆਵਾਜਾਈ ਲਈ ਬੰਦਰਗਾਹ ਤੱਕ ਪਹੁੰਚ ਦਿੰਦਾ ਹੈ।"]},
"GEO-IND-001-CP002-Q040":{"h":"66f73057","hi":["कथनों पर विचार कीजिए: I. विशाखापत्तनम इस्पात संयंत्र तटीय है। II. पत्तन तक पहुँच एक महत्वपूर्ण अवस्थितिक लाभ है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","I और II दोनों सही हैं","केवल II सही है","न तो I और न ही II सही है"],"संयंत्र की तटीय अवस्थिति और पत्तन तक पहुँच उसे खनिज पट्टियों के पारंपरिक आंतरिक इस्पात केंद्रों से अलग करती है।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਵਿਸ਼ਾਖਾਪਟਨਮ ਸਟੀਲ ਪਲਾਂਟ ਤਟੀ ਹੈ। II. ਬੰਦਰਗਾਹ ਤੱਕ ਪਹੁੰਚ ਇੱਕ ਮਹੱਤਵਪੂਰਨ ਸਥਾਨਕ ਲਾਭ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਪਲਾਂਟ ਦਾ ਤਟੀ ਸਥਾਨ ਅਤੇ ਬੰਦਰਗਾਹ ਤੱਕ ਪਹੁੰਚ ਇਸ ਨੂੰ ਖਣਿਜ ਪੱਟੀਆਂ ਦੇ ਰਵਾਇਤੀ ਅੰਦਰੂਨੀ ਸਟੀਲ ਕੇਂਦਰਾਂ ਤੋਂ ਵੱਖ ਕਰਦੀ ਹੈ।"]},
"GEO-IND-001-CP002-Q041":{"h":"79d477ef","hi":["विशाखापत्तनम के इस्पात भूगोल में कौन-सा युग्म सही सुमेलित है?",["विशाखापत्तनम — ओडिशा","विशाखापत्तनम — गुजरात","विशाखापत्तनम — आंध्र प्रदेश","विशाखापत्तनम — पश्चिम बंगाल"],"विशाखापत्तनम भारत के पूर्वी तट पर आंध्र प्रदेश में स्थित है।"],"pa":["ਵਿਸ਼ਾਖਾਪਟਨਮ ਦੇ ਸਟੀਲ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਵਿਸ਼ਾਖਾਪਟਨਮ — ਓਡੀਸ਼ਾ","ਵਿਸ਼ਾਖਾਪਟਨਮ — ਗੁਜਰਾਤ","ਵਿਸ਼ਾਖਾਪਟਨਮ — ਆਂਧਰਾ ਪ੍ਰਦੇਸ਼","ਵਿਸ਼ਾਖਾਪਟਨਮ — ਪੱਛਮੀ ਬੰਗਾਲ"],"ਵਿਸ਼ਾਖਾਪਟਨਮ ਭਾਰਤ ਦੇ ਪੂਰਬੀ ਤਟ 'ਤੇ ਆਂਧਰਾ ਪ੍ਰਦੇਸ਼ ਵਿੱਚ ਸਥਿਤ ਹੈ।"]},
"GEO-IND-001-CP002-Q042":{"h":"e9c5637f","hi":["इस्पात संयंत्रों की अवस्थिति के लिए कौन-सी तुलना सही है?",["दोनों अपतटीय संयंत्र हैं","बोकारो एक पत्तन नगर है","विशाखापत्तनम झारखंड में है","विशाखापत्तनम को तटीय पत्तन का लाभ है, जबकि बोकारो आंतरिक खनिज पट्टी का संयंत्र है"],"विशाखापत्तनम को तटीय पत्तन का लाभ मिलता है, जबकि बोकारो आंतरिक छोटानागपुर-दामोदर खनिज-औद्योगिक पट्टी में स्थित है।"],"pa":["ਸਟੀਲ ਪਲਾਂਟਾਂ ਦੇ ਸਥਾਨ ਲਈ ਕਿਹੜੀ ਤੁਲਨਾ ਸਹੀ ਹੈ?",["ਦੋਵੇਂ ਸਮੁੰਦਰ ਅੰਦਰਲੇ ਪਲਾਂਟ ਹਨ","ਬੋਕਾਰੋ ਇੱਕ ਬੰਦਰਗਾਹੀ ਸ਼ਹਿਰ ਹੈ","ਵਿਸ਼ਾਖਾਪਟਨਮ ਝਾਰਖੰਡ ਵਿੱਚ ਹੈ","ਵਿਸ਼ਾਖਾਪਟਨਮ ਨੂੰ ਤਟੀ ਬੰਦਰਗਾਹ ਦਾ ਲਾਭ ਹੈ, ਜਦਕਿ ਬੋਕਾਰੋ ਅੰਦਰੂਨੀ ਖਣਿਜ ਪੱਟੀ ਦਾ ਪਲਾਂਟ ਹੈ"],"ਵਿਸ਼ਾਖਾਪਟਨਮ ਨੂੰ ਤਟੀ ਬੰਦਰਗਾਹ ਦਾ ਲਾਭ ਮਿਲਦਾ ਹੈ, ਜਦਕਿ ਬੋਕਾਰੋ ਅੰਦਰੂਨੀ ਛੋਟਾਨਾਗਪੁਰ-ਦਾਮੋਦਰ ਖਣਿਜ-ਉਦਯੋਗਿਕ ਪੱਟੀ ਵਿੱਚ ਸਥਿਤ ਹੈ।"]},
"GEO-IND-001-CP002-Q043":{"h":"1fe0f443","hi":["सेलम इस्पात संयंत्र किस राज्य में स्थित है?",["कर्नाटक","आंध्र प्रदेश","ओडिशा","तमिलनाडु"],"सेलम इस्पात संयंत्र तमिलनाडु में है और विशेष तथा स्टेनलेस इस्पात उत्पादों के लिए जाना जाता है।"],"pa":["ਸੇਲਮ ਸਟੀਲ ਪਲਾਂਟ ਕਿਸ ਰਾਜ ਵਿੱਚ ਸਥਿਤ ਹੈ?",["ਕਰਨਾਟਕ","ਆਂਧਰਾ ਪ੍ਰਦੇਸ਼","ਓਡੀਸ਼ਾ","ਤਾਮਿਲਨਾਡੂ"],"ਸੇਲਮ ਸਟੀਲ ਪਲਾਂਟ ਤਾਮਿਲਨਾਡੂ ਵਿੱਚ ਹੈ ਅਤੇ ਵਿਸ਼ੇਸ਼ ਤੇ ਸਟੇਨਲੈਸ ਸਟੀਲ ਉਤਪਾਦਾਂ ਲਈ ਜਾਣਿਆ ਜਾਂਦਾ ਹੈ।"]},
"GEO-IND-001-CP002-Q044":{"h":"53142e45","hi":["महत्वपूर्ण लौह-इस्पात केंद्र भद्रावती किस राज्य में स्थित है?",["कर्नाटक","तमिलनाडु","झारखंड","पश्चिम बंगाल"],"कर्नाटक का भद्रावती ऐतिहासिक रूप से विश्वेश्वरैया लौह-इस्पात संयंत्र से जुड़ा है।"],"pa":["ਮਹੱਤਵਪੂਰਨ ਲੋਹਾ-ਸਟੀਲ ਕੇਂਦਰ ਭਦ੍ਰਾਵਤੀ ਕਿਸ ਰਾਜ ਵਿੱਚ ਸਥਿਤ ਹੈ?",["ਕਰਨਾਟਕ","ਤਾਮਿਲਨਾਡੂ","ਝਾਰਖੰਡ","ਪੱਛਮੀ ਬੰਗਾਲ"],"ਕਰਨਾਟਕ ਦਾ ਭਦ੍ਰਾਵਤੀ ਇਤਿਹਾਸਕ ਤੌਰ 'ਤੇ ਵਿਸ਼ਵੇਸ਼ਵਰੱਈਆ ਲੋਹਾ-ਸਟੀਲ ਪਲਾਂਟ ਨਾਲ ਜੁੜਿਆ ਹੈ।"]},
"GEO-IND-001-CP002-Q045":{"h":"8603ca25","hi":["कौन-सा संयंत्र सेल (SAIL) के अंतर्गत विशेष इस्पात संयंत्र है?",["जमशेदपुर इस्पात संयंत्र","सेलम इस्पात संयंत्र","विशाखापत्तनम इस्पात संयंत्र","विजयनगर इस्पात संयंत्र"],"सेल (SAIL) सेलम इस्पात संयंत्र को विशेष इस्पात संयंत्र के रूप में सूचीबद्ध करता है; अन्य केंद्र इस श्रेणी में नहीं हैं।"],"pa":["ਕਿਹੜਾ ਪਲਾਂਟ ਸੇਲ (SAIL) ਅਧੀਨ ਵਿਸ਼ੇਸ਼ ਸਟੀਲ ਪਲਾਂਟ ਹੈ?",["ਜਮਸ਼ੇਦਪੁਰ ਸਟੀਲ ਪਲਾਂਟ","ਸੇਲਮ ਸਟੀਲ ਪਲਾਂਟ","ਵਿਸ਼ਾਖਾਪਟਨਮ ਸਟੀਲ ਪਲਾਂਟ","ਵਿਜੈਨਗਰ ਸਟੀਲ ਪਲਾਂਟ"],"ਸੇਲ (SAIL) ਸੇਲਮ ਸਟੀਲ ਪਲਾਂਟ ਨੂੰ ਵਿਸ਼ੇਸ਼ ਸਟੀਲ ਪਲਾਂਟ ਵਜੋਂ ਸੂਚੀਬੱਧ ਕਰਦਾ ਹੈ; ਬਾਕੀ ਕੇਂਦਰ ਇਸ ਸ਼੍ਰੇਣੀ ਵਿੱਚ ਨਹੀਂ ਆਉਂਦੇ।"]},
"GEO-IND-001-CP002-Q046":{"h":"557e3072","hi":["कथनों पर विचार कीजिए: I. सेलम तमिलनाडु में है। II. भद्रावती कर्नाटक में है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","I और II दोनों सही हैं","न तो I और न ही II सही है"],"सेलम और भद्रावती क्रमशः तमिलनाडु और कर्नाटक के महत्वपूर्ण दक्षिणी इस्पात केंद्र हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਸੇਲਮ ਤਾਮਿਲਨਾਡੂ ਵਿੱਚ ਹੈ। II. ਭਦ੍ਰਾਵਤੀ ਕਰਨਾਟਕ ਵਿੱਚ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਸੇਲਮ ਅਤੇ ਭਦ੍ਰਾਵਤੀ ਕ੍ਰਮਵਾਰ ਤਾਮਿਲਨਾਡੂ ਅਤੇ ਕਰਨਾਟਕ ਦੇ ਮਹੱਤਵਪੂਰਨ ਦੱਖਣੀ ਸਟੀਲ ਕੇਂਦਰ ਹਨ।"]},
"GEO-IND-001-CP002-Q047":{"h":"62e9c67b","hi":["दक्षिणी इस्पात भूगोल में कौन-सा युग्म सही सुमेलित है?",["भद्रावती — ओडिशा","सेलम — झारखंड","सेलम — पश्चिम बंगाल","भद्रावती — कर्नाटक"],"भद्रावती कर्नाटक में और सेलम तमिलनाडु में है।"],"pa":["ਦੱਖਣੀ ਸਟੀਲ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਭਦ੍ਰਾਵਤੀ — ਓਡੀਸ਼ਾ","ਸੇਲਮ — ਝਾਰਖੰਡ","ਸੇਲਮ — ਪੱਛਮੀ ਬੰਗਾਲ","ਭਦ੍ਰਾਵਤੀ — ਕਰਨਾਟਕ"],"ਭਦ੍ਰਾਵਤੀ ਕਰਨਾਟਕ ਵਿੱਚ ਅਤੇ ਸੇਲਮ ਤਾਮਿਲਨਾਡੂ ਵਿੱਚ ਹੈ।"]},
"GEO-IND-001-CP002-Q048":{"h":"4fbfd255","hi":["दक्षिणी इस्पात केंद्रों के लिए कौन-सी तुलना सही है?",["सेलम तमिलनाडु में है, जबकि भद्रावती कर्नाटक में है","दोनों ओडिशा में हैं","दोनों झारखंड में हैं","सेलम कर्नाटक में और भद्रावती तमिलनाडु में है"],"ये दोनों केंद्र अलग-अलग दक्षिणी राज्यों में हैं और मानचित्र-आधारित अवस्थिति के मानक तथ्य हैं।"],"pa":["ਦੱਖਣੀ ਸਟੀਲ ਕੇਂਦਰਾਂ ਲਈ ਕਿਹੜੀ ਤੁਲਨਾ ਸਹੀ ਹੈ?",["ਸੇਲਮ ਤਾਮਿਲਨਾਡੂ ਵਿੱਚ ਹੈ, ਜਦਕਿ ਭਦ੍ਰਾਵਤੀ ਕਰਨਾਟਕ ਵਿੱਚ ਹੈ","ਦੋਵੇਂ ਓਡੀਸ਼ਾ ਵਿੱਚ ਹਨ","ਦੋਵੇਂ ਝਾਰਖੰਡ ਵਿੱਚ ਹਨ","ਸੇਲਮ ਕਰਨਾਟਕ ਵਿੱਚ ਅਤੇ ਭਦ੍ਰਾਵਤੀ ਤਾਮਿਲਨਾਡੂ ਵਿੱਚ ਹੈ"],"ਇਹ ਦੋਵੇਂ ਕੇਂਦਰ ਵੱਖ-ਵੱਖ ਦੱਖਣੀ ਰਾਜਾਂ ਵਿੱਚ ਹਨ ਅਤੇ ਨਕਸ਼ੇ 'ਤੇ ਸਥਾਨ ਦੇ ਮਿਆਰੀ ਤੱਥ ਹਨ।"]},
"GEO-IND-001-CP002-Q049":{"h":"d1e6e818","hi":["विजयनगर इस्पात केंद्र किस राज्य में स्थित है?",["कर्नाटक","तमिलनाडु","झारखंड","ओडिशा"],"विजयनगर कर्नाटक का एक प्रमुख इस्पात केंद्र है, जो बल्लारी-होसपेट लौह अयस्क क्षेत्र के पास स्थित है।"],"pa":["ਵਿਜੈਨਗਰ ਸਟੀਲ ਕੇਂਦਰ ਕਿਸ ਰਾਜ ਵਿੱਚ ਸਥਿਤ ਹੈ?",["ਕਰਨਾਟਕ","ਤਾਮਿਲਨਾਡੂ","ਝਾਰਖੰਡ","ਓਡੀਸ਼ਾ"],"ਵਿਜੈਨਗਰ ਕਰਨਾਟਕ ਦਾ ਇੱਕ ਪ੍ਰਮੁੱਖ ਸਟੀਲ ਕੇਂਦਰ ਹੈ, ਜੋ ਬੱਲਾਰੀ-ਹੋਸਪੇਟ ਕੱਚੇ ਲੋਹੇ ਦੇ ਖੇਤਰ ਦੇ ਨੇੜੇ ਸਥਿਤ ਹੈ।"]},
"GEO-IND-001-CP002-Q050":{"h":"9db9fdad","hi":["कौन-सी खनिज पट्टी विजयनगर को कच्चे माल का महत्वपूर्ण लाभ देती है?",["कोडरमा अभ्रक पट्टी","बल्लारी-होसपेट लौह अयस्क पट्टी","सांभर नमक पट्टी","पन्ना हीरा क्षेत्र"],"विजयनगर बल्लारी-होसपेट लौह अयस्क क्षेत्र के पास है, जिससे इसे इस्पात के एक प्रमुख कच्चे माल तक मज़बूत पहुँच मिलती है।"],"pa":["ਕਿਹੜੀ ਖਣਿਜ ਪੱਟੀ ਵਿਜੈਨਗਰ ਨੂੰ ਕੱਚੇ ਮਾਲ ਦਾ ਮਹੱਤਵਪੂਰਨ ਲਾਭ ਦਿੰਦੀ ਹੈ?",["ਕੋਡਰਮਾ ਅਬਰਕ ਪੱਟੀ","ਬੱਲਾਰੀ-ਹੋਸਪੇਟ ਕੱਚੇ ਲੋਹੇ ਦੀ ਪੱਟੀ","ਸਾਂਭਰ ਲੂਣ ਪੱਟੀ","ਪੰਨਾ ਹੀਰਾ ਖੇਤਰ"],"ਵਿਜੈਨਗਰ ਬੱਲਾਰੀ-ਹੋਸਪੇਟ ਕੱਚੇ ਲੋਹੇ ਦੇ ਖੇਤਰ ਦੇ ਨੇੜੇ ਹੈ, ਜਿਸ ਨਾਲ ਇਸ ਨੂੰ ਸਟੀਲ ਦੇ ਇੱਕ ਮੁੱਖ ਕੱਚੇ ਮਾਲ ਤੱਕ ਮਜ਼ਬੂਤ ਪਹੁੰਚ ਮਿਲਦੀ ਹੈ।"]},
"GEO-IND-001-CP002-Q051":{"h":"ec9c5331","hi":["कथनों पर विचार कीजिए: I. विजयनगर कर्नाटक में है। II. यह बल्लारी-होसपेट खनिज क्षेत्र से जुड़ा है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","I और II दोनों सही हैं","न तो I और न ही II सही है"],"दोनों कथन विजयनगर की अवस्थिति और उसके कच्चे माल के परिवेश का सही वर्णन करते हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਵਿਜੈਨਗਰ ਕਰਨਾਟਕ ਵਿੱਚ ਹੈ। II. ਇਹ ਬੱਲਾਰੀ-ਹੋਸਪੇਟ ਖਣਿਜ ਖੇਤਰ ਨਾਲ ਜੁੜਿਆ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਦੋਵੇਂ ਕਥਨ ਵਿਜੈਨਗਰ ਦੇ ਸਥਾਨ ਅਤੇ ਉਸ ਦੇ ਕੱਚੇ ਮਾਲ ਦੇ ਮਾਹੌਲ ਦਾ ਸਹੀ ਵਰਣਨ ਕਰਦੇ ਹਨ।"]},
"GEO-IND-001-CP002-Q052":{"h":"6fe6572c","hi":["विजयनगर के इस्पात भूगोल में कौन-सा युग्म सही सुमेलित है?",["विजयनगर — पश्चिम बंगाल","विजयनगर — छत्तीसगढ़","विजयनगर — असम","विजयनगर — कर्नाटक"],"विजयनगर कर्नाटक में स्थित है।"],"pa":["ਵਿਜੈਨਗਰ ਦੇ ਸਟੀਲ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਵਿਜੈਨਗਰ — ਪੱਛਮੀ ਬੰਗਾਲ","ਵਿਜੈਨਗਰ — ਛੱਤੀਸਗੜ੍ਹ","ਵਿਜੈਨਗਰ — ਅਸਾਮ","ਵਿਜੈਨਗਰ — ਕਰਨਾਟਕ"],"ਵਿਜੈਨਗਰ ਕਰਨਾਟਕ ਵਿੱਚ ਸਥਿਤ ਹੈ।"]},
"GEO-IND-001-CP002-Q053":{"h":"910c00a9","hi":["विजयनगर कच्चा माल-उन्मुख इस्पात अवस्थिति का सशक्त उदाहरण क्यों है?",["यह एक प्रमुख लौह अयस्क पट्टी के पास स्थित है","यह केवल पर्यटन के लिए स्थित है","इसकी खनिजों तक कोई पहुँच नहीं है","यह केवल आयातित कपास पर निर्भर है"],"बल्लारी-होसपेट लौह अयस्क पट्टी की निकटता एक प्रमुख भारी कच्चे माल के परिवहन का बोझ घटाती है।"],"pa":["ਵਿਜੈਨਗਰ ਕੱਚਾ ਮਾਲ-ਮੁਖੀ ਸਟੀਲ ਸਥਾਨੀਕਰਨ ਦੀ ਮਜ਼ਬੂਤ ਉਦਾਹਰਨ ਕਿਉਂ ਹੈ?",["ਇਹ ਇੱਕ ਪ੍ਰਮੁੱਖ ਕੱਚੇ ਲੋਹੇ ਦੀ ਪੱਟੀ ਦੇ ਨੇੜੇ ਸਥਿਤ ਹੈ","ਇਹ ਸਿਰਫ਼ ਸੈਰ-ਸਪਾਟੇ ਲਈ ਸਥਿਤ ਹੈ","ਇਸ ਦੀ ਖਣਿਜਾਂ ਤੱਕ ਕੋਈ ਪਹੁੰਚ ਨਹੀਂ","ਇਹ ਸਿਰਫ਼ ਆਯਾਤ ਕੀਤੀ ਕਪਾਹ 'ਤੇ ਨਿਰਭਰ ਹੈ"],"ਬੱਲਾਰੀ-ਹੋਸਪੇਟ ਕੱਚੇ ਲੋਹੇ ਦੀ ਪੱਟੀ ਦੀ ਨੇੜਤਾ ਇੱਕ ਮੁੱਖ ਭਾਰੀ ਕੱਚੇ ਮਾਲ ਦੀ ਢੋਆ-ਢੁਆਈ ਦਾ ਬੋਝ ਘਟਾਉਂਦੀ ਹੈ।"]},
"GEO-IND-001-CP002-Q054":{"h":"9e1918c8","hi":["कर्नाटक के इस्पात भूगोल के लिए कौन-सी तुलना सही है?",["दोनों तमिलनाडु में हैं","भद्रावती और विजयनगर दोनों कर्नाटक में हैं","विजयनगर ओडिशा में है","भद्रावती पश्चिम बंगाल में है"],"भद्रावती और विजयनगर कर्नाटक के दो महत्वपूर्ण इस्पात केंद्र हैं।"],"pa":["ਕਰਨਾਟਕ ਦੇ ਸਟੀਲ ਭੂਗੋਲ ਲਈ ਕਿਹੜੀ ਤੁਲਨਾ ਸਹੀ ਹੈ?",["ਦੋਵੇਂ ਤਾਮਿਲਨਾਡੂ ਵਿੱਚ ਹਨ","ਭਦ੍ਰਾਵਤੀ ਅਤੇ ਵਿਜੈਨਗਰ ਦੋਵੇਂ ਕਰਨਾਟਕ ਵਿੱਚ ਹਨ","ਵਿਜੈਨਗਰ ਓਡੀਸ਼ਾ ਵਿੱਚ ਹੈ","ਭਦ੍ਰਾਵਤੀ ਪੱਛਮੀ ਬੰਗਾਲ ਵਿੱਚ ਹੈ"],"ਭਦ੍ਰਾਵਤੀ ਅਤੇ ਵਿਜੈਨਗਰ ਕਰਨਾਟਕ ਦੇ ਦੋ ਮਹੱਤਵਪੂਰਨ ਸਟੀਲ ਕੇਂਦਰ ਹਨ।"]},
"GEO-IND-001-CP002-Q055":{"h":"679415bd","hi":["किस समूह में केवल पूर्वी भारत के प्रमुख इस्पात केंद्र हैं?",["सेलम, विजयनगर, भद्रावती और नेवेली","जमशेदपुर, बोकारो, राउरकेला और दुर्गापुर","डिगबोई, बाड़मेर, अंकलेश्वर और मुंबई हाई","खेतड़ी, पन्ना, सांभर और हट्टी"],"जमशेदपुर, बोकारो, राउरकेला और दुर्गापुर सभी पूर्वी भारत की खनिज-औद्योगिक पट्टी में आते हैं।"],"pa":["ਕਿਸ ਸਮੂਹ ਵਿੱਚ ਸਿਰਫ਼ ਪੂਰਬੀ ਭਾਰਤ ਦੇ ਪ੍ਰਮੁੱਖ ਸਟੀਲ ਕੇਂਦਰ ਹਨ?",["ਸੇਲਮ, ਵਿਜੈਨਗਰ, ਭਦ੍ਰਾਵਤੀ ਅਤੇ ਨੇਵੇਲੀ","ਜਮਸ਼ੇਦਪੁਰ, ਬੋਕਾਰੋ, ਰਾਉਰਕੇਲਾ ਅਤੇ ਦੁਰਗਾਪੁਰ","ਡਿਗਬੋਈ, ਬਾੜਮੇਰ, ਅੰਕਲੇਸ਼ਵਰ ਅਤੇ ਮੁੰਬਈ ਹਾਈ","ਖੇਤੜੀ, ਪੰਨਾ, ਸਾਂਭਰ ਅਤੇ ਹੱਟੀ"],"ਜਮਸ਼ੇਦਪੁਰ, ਬੋਕਾਰੋ, ਰਾਉਰਕੇਲਾ ਅਤੇ ਦੁਰਗਾਪੁਰ ਸਾਰੇ ਪੂਰਬੀ ਭਾਰਤ ਦੀ ਖਣਿਜ-ਉਦਯੋਗਿਕ ਪੱਟੀ ਵਿੱਚ ਆਉਂਦੇ ਹਨ।"]},
"GEO-IND-001-CP002-Q056":{"h":"e42e84e5","hi":["पूर्वी भारत एक प्रमुख लौह-इस्पात क्षेत्र क्यों है?",["यहाँ खनिज संसाधनों का अभाव है","यह केवल कपास पर निर्भर है","यहाँ लौह अयस्क, कोयला, चूना पत्थर, जल और परिवहन अपेक्षाकृत पास-पास उपलब्ध हैं","यहाँ रेल नेटवर्क नहीं है"],"छोटानागपुर-दामोदर-ओडिशा पट्टी में प्रमुख खनिज कच्चे माल के साथ जल, श्रम और परिवहन अवसंरचना भी उपलब्ध है।"],"pa":["ਪੂਰਬੀ ਭਾਰਤ ਇੱਕ ਪ੍ਰਮੁੱਖ ਲੋਹਾ-ਸਟੀਲ ਖੇਤਰ ਕਿਉਂ ਹੈ?",["ਇੱਥੇ ਖਣਿਜ ਸਾਧਨਾਂ ਦੀ ਘਾਟ ਹੈ","ਇਹ ਸਿਰਫ਼ ਕਪਾਹ 'ਤੇ ਨਿਰਭਰ ਹੈ","ਇੱਥੇ ਕੱਚਾ ਲੋਹਾ, ਕੋਲਾ, ਚੂਨਾ ਪੱਥਰ, ਪਾਣੀ ਅਤੇ ਆਵਾਜਾਈ ਤੁਲਨਾਤਮਕ ਤੌਰ 'ਤੇ ਨੇੜੇ-ਨੇੜੇ ਮਿਲਦੇ ਹਨ","ਇੱਥੇ ਰੇਲ ਨੈੱਟਵਰਕ ਨਹੀਂ ਹੈ"],"ਛੋਟਾਨਾਗਪੁਰ-ਦਾਮੋਦਰ-ਓਡੀਸ਼ਾ ਪੱਟੀ ਵਿੱਚ ਪ੍ਰਮੁੱਖ ਖਣਿਜ ਕੱਚੇ ਮਾਲ ਦੇ ਨਾਲ ਪਾਣੀ, ਕਿਰਤ ਅਤੇ ਆਵਾਜਾਈ ਦਾ ਬੁਨਿਆਦੀ ਢਾਂਚਾ ਵੀ ਉਪਲਬਧ ਹੈ।"]},
"GEO-IND-001-CP002-Q057":{"h":"eef60a38","hi":["कथनों पर विचार कीजिए: I. जमशेदपुर और बोकारो झारखंड में हैं। II. राउरकेला ओडिशा में है। III. दुर्गापुर पश्चिम बंगाल में है। कौन-सा/से कथन सही है/हैं?",["केवल I और II","केवल II और III","केवल I और III","I, II और III"],"तीनों राज्य-अवस्थिति संबंध सही हैं और पूर्वी इस्पात भूगोल का मूल भाग हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਜਮਸ਼ੇਦਪੁਰ ਅਤੇ ਬੋਕਾਰੋ ਝਾਰਖੰਡ ਵਿੱਚ ਹਨ। II. ਰਾਉਰਕੇਲਾ ਓਡੀਸ਼ਾ ਵਿੱਚ ਹੈ। III. ਦੁਰਗਾਪੁਰ ਪੱਛਮੀ ਬੰਗਾਲ ਵਿੱਚ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਅਤੇ II","ਸਿਰਫ਼ II ਅਤੇ III","ਸਿਰਫ਼ I ਅਤੇ III","I, II ਅਤੇ III"],"ਤਿੰਨੋਂ ਰਾਜ-ਸਥਾਨ ਸੰਬੰਧ ਸਹੀ ਹਨ ਅਤੇ ਪੂਰਬੀ ਸਟੀਲ ਭੂਗੋਲ ਦਾ ਮੂਲ ਹਿੱਸਾ ਹਨ।"]},
"GEO-IND-001-CP002-Q058":{"h":"8b79d334","hi":["पूर्वी इस्पात पट्टी के लिए कौन-सा क्रम सही सुमेलित है?",["जमशेदपुर—झारखंड; राउरकेला—ओडिशा; दुर्गापुर—पश्चिम बंगाल","जमशेदपुर—ओडिशा; राउरकेला—झारखंड; दुर्गापुर—छत्तीसगढ़","तीनों—तमिलनाडु","जमशेदपुर—गुजरात; राउरकेला—राजस्थान; दुर्गापुर—असम"],"यह क्रम तीनों प्रमुख इस्पात केंद्रों को सही ढंग से झारखंड, ओडिशा और पश्चिम बंगाल में रखता है।"],"pa":["ਪੂਰਬੀ ਸਟੀਲ ਪੱਟੀ ਲਈ ਕਿਹੜਾ ਕ੍ਰਮ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਜਮਸ਼ੇਦਪੁਰ—ਝਾਰਖੰਡ; ਰਾਉਰਕੇਲਾ—ਓਡੀਸ਼ਾ; ਦੁਰਗਾਪੁਰ—ਪੱਛਮੀ ਬੰਗਾਲ","ਜਮਸ਼ੇਦਪੁਰ—ਓਡੀਸ਼ਾ; ਰਾਉਰਕੇਲਾ—ਝਾਰਖੰਡ; ਦੁਰਗਾਪੁਰ—ਛੱਤੀਸਗੜ੍ਹ","ਤਿੰਨੋਂ—ਤਾਮਿਲਨਾਡੂ","ਜਮਸ਼ੇਦਪੁਰ—ਗੁਜਰਾਤ; ਰਾਉਰਕੇਲਾ—ਰਾਜਸਥਾਨ; ਦੁਰਗਾਪੁਰ—ਅਸਾਮ"],"ਇਹ ਕ੍ਰਮ ਤਿੰਨੋਂ ਪ੍ਰਮੁੱਖ ਸਟੀਲ ਕੇਂਦਰਾਂ ਨੂੰ ਸਹੀ ਤਰ੍ਹਾਂ ਝਾਰਖੰਡ, ਓਡੀਸ਼ਾ ਅਤੇ ਪੱਛਮੀ ਬੰਗਾਲ ਵਿੱਚ ਰੱਖਦਾ ਹੈ।"]},
"GEO-IND-001-CP002-Q059":{"h":"8145f840","hi":["पूर्वी इस्पात पट्टी के लिए कौन-सा कोयला क्षेत्र विशेष रूप से महत्वपूर्ण है?",["केवल नेवेली लिग्नाइट","दामोदर घाटी के कोयला क्षेत्र","असम के तेल क्षेत्र","राजस्थान का पोटाश बेसिन"],"दामोदर क्षेत्र के झरिया, रानीगंज और बोकारो कोयला क्षेत्र लंबे समय से पूर्वी भारत के इस्पात और भारी उद्योगों को सहारा देते रहे हैं।"],"pa":["ਪੂਰਬੀ ਸਟੀਲ ਪੱਟੀ ਲਈ ਕਿਹੜਾ ਕੋਲਾ ਖੇਤਰ ਖ਼ਾਸ ਤੌਰ 'ਤੇ ਮਹੱਤਵਪੂਰਨ ਹੈ?",["ਸਿਰਫ਼ ਨੇਵੇਲੀ ਲਿਗਨਾਈਟ","ਦਾਮੋਦਰ ਘਾਟੀ ਦੇ ਕੋਲਾ ਖੇਤਰ","ਅਸਾਮ ਦੇ ਤੇਲ ਖੇਤਰ","ਰਾਜਸਥਾਨ ਦਾ ਪੋਟਾਸ਼ ਬੇਸਿਨ"],"ਦਾਮੋਦਰ ਖੇਤਰ ਦੇ ਝਰੀਆ, ਰਾਣੀਗੰਜ ਅਤੇ ਬੋਕਾਰੋ ਕੋਲਾ ਖੇਤਰ ਲੰਮੇ ਸਮੇਂ ਤੋਂ ਪੂਰਬੀ ਭਾਰਤ ਦੇ ਸਟੀਲ ਅਤੇ ਭਾਰੀ ਉਦਯੋਗਾਂ ਨੂੰ ਸਹਾਰਾ ਦਿੰਦੇ ਆ ਰਹੇ ਹਨ।"]},
"GEO-IND-001-CP002-Q060":{"h":"640e104f","hi":["किन राज्यों का समूह कई प्रमुख इस्पात केंद्रों वाला भारत का पूर्वी-मध्य खनिज-औद्योगिक क्षेत्र बनाता है?",["केरल की तटीय बागान पट्टी","पंजाब-हरियाणा गेहूँ पट्टी","झारखंड–ओडिशा–पश्चिम बंगाल–छत्तीसगढ़ खनिज-औद्योगिक क्षेत्र","पश्चिमी राजस्थान की मरुस्थलीय पर्यटन पट्टी"],"पूर्वी-मध्य खनिज पट्टी में आसपास के राज्यों में फैले लौह अयस्क, कोयला और प्रमुख एकीकृत इस्पात केंद्र एक साथ हैं।"],"pa":["ਕਿਹੜੇ ਰਾਜਾਂ ਦਾ ਸਮੂਹ ਕਈ ਪ੍ਰਮੁੱਖ ਸਟੀਲ ਕੇਂਦਰਾਂ ਵਾਲਾ ਭਾਰਤ ਦਾ ਪੂਰਬੀ-ਕੇਂਦਰੀ ਖਣਿਜ-ਉਦਯੋਗਿਕ ਖੇਤਰ ਬਣਾਉਂਦਾ ਹੈ?",["ਕੇਰਲ ਦੀ ਤਟੀ ਬਾਗ਼ਾਨ ਪੱਟੀ","ਪੰਜਾਬ-ਹਰਿਆਣਾ ਕਣਕ ਪੱਟੀ","ਝਾਰਖੰਡ–ਓਡੀਸ਼ਾ–ਪੱਛਮੀ ਬੰਗਾਲ–ਛੱਤੀਸਗੜ੍ਹ ਖਣਿਜ-ਉਦਯੋਗਿਕ ਖੇਤਰ","ਪੱਛਮੀ ਰਾਜਸਥਾਨ ਦੀ ਮਾਰੂਥਲੀ ਸੈਰ-ਸਪਾਟਾ ਪੱਟੀ"],"ਪੂਰਬੀ-ਕੇਂਦਰੀ ਖਣਿਜ ਪੱਟੀ ਵਿੱਚ ਨਾਲ ਲੱਗਦੇ ਰਾਜਾਂ ਵਿੱਚ ਫੈਲੇ ਕੱਚਾ ਲੋਹਾ, ਕੋਲਾ ਅਤੇ ਪ੍ਰਮੁੱਖ ਏਕੀਕ੍ਰਿਤ ਸਟੀਲ ਕੇਂਦਰ ਇਕੱਠੇ ਹਨ।"]},
"GEO-IND-001-CP003-Q001":{"h":"20a5bc70","hi":["सूती वस्त्र उद्योग किस कृषि कच्चे माल का उपयोग करता है?",["जूट","गन्ना","कपास","चाय की पत्तियाँ"],"सूती धागे की कताई और कपड़े की बुनाई में कपास का रेशा मूल कच्चा माल है। इसलिए सूती वस्त्र उद्योग कृषि आधारित उद्योग है।"],"pa":["ਸੂਤੀ ਕੱਪੜਾ ਉਦਯੋਗ ਖੇਤੀ ਤੋਂ ਮਿਲੇ ਕਿਹੜੇ ਕੱਚੇ ਮਾਲ ਦੀ ਵਰਤੋਂ ਕਰਦਾ ਹੈ?",["ਜੂਟ","ਗੰਨਾ","ਕਪਾਹ","ਚਾਹ ਦੀਆਂ ਪੱਤੀਆਂ"],"ਸੂਤੀ ਧਾਗਾ ਕੱਤਣ ਅਤੇ ਕੱਪੜਾ ਬੁਣਨ ਲਈ ਕਪਾਹ ਦਾ ਰੇਸ਼ਾ ਮੁੱਖ ਕੱਚਾ ਮਾਲ ਹੈ। ਇਸ ਕਰਕੇ ਸੂਤੀ ਕੱਪੜਾ ਉਦਯੋਗ ਖੇਤੀ-ਆਧਾਰਿਤ ਹੈ।"]},
"GEO-IND-001-CP003-Q002":{"h":"6df56ad7","hi":["पश्चिमी भारत में सूती वस्त्र मिलों का शुरुआती विकास तेज़ी से क्यों हुआ?",["लौह अयस्क मुख्य कच्चा माल था","क्षेत्र में बाज़ार नहीं थे","केवल जलविद्युत का महत्व था","कपास की आपूर्ति, पत्तन, पूँजी और आर्द्र तटीय दशाएँ अनुकूल थीं"],"मुंबई और गुजरात में वस्त्र उद्योग के शुरुआती विकास में कपास उत्पादक पृष्ठप्रदेश, पत्तनों तक पहुँच, पूँजी, श्रम और उपयुक्त आर्द्रता का संयुक्त योगदान था।"],"pa":["ਪੱਛਮੀ ਭਾਰਤ ਵਿੱਚ ਸੂਤੀ ਕੱਪੜਾ ਮਿੱਲਾਂ ਦਾ ਮੁੱਢਲਾ ਵਿਕਾਸ ਤੇਜ਼ੀ ਨਾਲ ਕਿਉਂ ਹੋਇਆ?",["ਕੱਚਾ ਲੋਹਾ ਮੁੱਖ ਕੱਚਾ ਮਾਲ ਸੀ","ਇਲਾਕੇ ਵਿੱਚ ਬਾਜ਼ਾਰ ਨਹੀਂ ਸਨ","ਸਿਰਫ਼ ਪਣ-ਬਿਜਲੀ ਦਾ ਮਹੱਤਵ ਸੀ","ਕਪਾਹ ਦੀ ਸਪਲਾਈ, ਬੰਦਰਗਾਹਾਂ, ਪੂੰਜੀ ਅਤੇ ਨਮੀ ਵਾਲੇ ਤੱਟੀ ਹਾਲਾਤ ਅਨੁਕੂਲ ਸਨ"],"ਮੁੰਬਈ ਅਤੇ ਗੁਜਰਾਤ ਵਿੱਚ ਕੱਪੜਾ ਉਦਯੋਗ ਦੇ ਮੁੱਢਲੇ ਵਿਕਾਸ ਵਿੱਚ ਕਪਾਹ ਉਗਾਉਣ ਵਾਲੇ ਪਿਛਲੇ ਇਲਾਕਿਆਂ, ਬੰਦਰਗਾਹਾਂ ਤੱਕ ਪਹੁੰਚ, ਪੂੰਜੀ, ਕਿਰਤ ਅਤੇ ਢੁੱਕਵੀਂ ਨਮੀ ਦਾ ਸਾਂਝਾ ਯੋਗਦਾਨ ਸੀ।"]},
"GEO-IND-001-CP003-Q003":{"h":"e2763559","hi":["कथनों पर विचार कीजिए: I. सूती वस्त्र उद्योग कृषि आधारित है। II. कपास उत्पादक क्षेत्रों में कच्चे माल की उपलब्धता का लाभ मिल सकता है। कौन-सा/से कथन सही है/हैं?",["I और II दोनों सही हैं","केवल I सही है","केवल II सही है","न तो I और न ही II सही है"],"कपास एक कृषि रेशा है। इसलिए यह उद्योग कृषि आधारित है और इसे कपास उत्पादक क्षेत्रों की निकटता का लाभ मिल सकता है।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਸੂਤੀ ਕੱਪੜਾ ਉਦਯੋਗ ਖੇਤੀ-ਆਧਾਰਿਤ ਹੈ। II. ਕਪਾਹ ਉਗਾਉਣ ਵਾਲੇ ਇਲਾਕਿਆਂ ਵਿੱਚ ਕੱਚੇ ਮਾਲ ਦੀ ਉਪਲਬਧਤਾ ਦਾ ਲਾਭ ਹੋ ਸਕਦਾ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਕਪਾਹ ਖੇਤੀ ਤੋਂ ਮਿਲਦਾ ਰੇਸ਼ਾ ਹੈ। ਇਸ ਲਈ ਇਹ ਉਦਯੋਗ ਖੇਤੀ-ਆਧਾਰਿਤ ਹੈ ਅਤੇ ਇਸ ਨੂੰ ਕਪਾਹ ਉਗਾਉਣ ਵਾਲੇ ਇਲਾਕਿਆਂ ਦੇ ਨੇੜੇ ਹੋਣ ਦਾ ਲਾਭ ਮਿਲ ਸਕਦਾ ਹੈ।"]},
"GEO-IND-001-CP003-Q004":{"h":"2f2d17f2","hi":["सूती धागे की कताई के दौरान धागा कम टूटे, इसमें कौन-सा कारक सहायक है?",["केवल अत्यंत शुष्क मरुस्थलीय वायु","आर्द्र वायु","कोयले की परतें","ज्वारीय परास"],"आर्द्रता से कपास के रेशे अधिक लचीले रहते हैं और कताई के दौरान कम टूटते हैं। इस कारण ऐतिहासिक रूप से आर्द्र तटीय स्थान अनुकूल रहे हैं।"],"pa":["ਸੂਤੀ ਧਾਗਾ ਕੱਤਣ ਵੇਲੇ ਧਾਗਾ ਘੱਟ ਟੁੱਟੇ, ਇਸ ਵਿੱਚ ਕਿਹੜਾ ਕਾਰਕ ਮਦਦ ਕਰਦਾ ਹੈ?",["ਸਿਰਫ਼ ਬਹੁਤ ਖੁਸ਼ਕ ਮਾਰੂਥਲੀ ਹਵਾ","ਨਮੀ ਵਾਲੀ ਹਵਾ","ਕੋਲੇ ਦੀਆਂ ਪਰਤਾਂ","ਜਵਾਰ-ਭਾਟਾ ਅੰਤਰ"],"ਨਮੀ ਨਾਲ ਕਪਾਹ ਦੇ ਰੇਸ਼ੇ ਵਧੇਰੇ ਲਚਕੀਲੇ ਰਹਿੰਦੇ ਹਨ ਅਤੇ ਕਤਾਈ ਵੇਲੇ ਘੱਟ ਟੁੱਟਦੇ ਹਨ। ਇਸ ਕਰਕੇ ਪਹਿਲਾਂ ਨਮੀ ਵਾਲੇ ਤੱਟੀ ਇਲਾਕੇ ਇਸ ਕੰਮ ਲਈ ਅਨੁਕੂਲ ਰਹੇ ਹਨ।"]},
"GEO-IND-001-CP003-Q005":{"h":"96226ca0","hi":["सूती वस्त्र उद्योग के भूगोल में कौन-सा युग्म सही सुमेलित है?",["कपास — खनिज आधारित उद्योग","कपास — परमाणु ईंधन","कपास — कृषि आधारित वस्त्र उद्योग","कपास — केवल पेट्रोरसायन का कच्चा माल"],"कपास एक कृषि रेशा है और उस पर कृषि आधारित वस्त्र उद्योग टिका है।"],"pa":["ਸੂਤੀ ਕੱਪੜਾ ਉਦਯੋਗ ਦੇ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਕਪਾਹ — ਖਣਿਜ-ਆਧਾਰਿਤ ਉਦਯੋਗ","ਕਪਾਹ — ਪਰਮਾਣੂ ਬਾਲਣ","ਕਪਾਹ — ਖੇਤੀ-ਆਧਾਰਿਤ ਕੱਪੜਾ ਉਦਯੋਗ","ਕਪਾਹ — ਸਿਰਫ਼ ਪੈਟਰੋ-ਰਸਾਇਣਾਂ ਦਾ ਕੱਚਾ ਮਾਲ"],"ਕਪਾਹ ਖੇਤੀ ਤੋਂ ਮਿਲਦਾ ਰੇਸ਼ਾ ਹੈ ਅਤੇ ਇਸ 'ਤੇ ਖੇਤੀ-ਆਧਾਰਿਤ ਕੱਪੜਾ ਉਦਯੋਗ ਟਿਕਿਆ ਹੈ।"]},
"GEO-IND-001-CP003-Q006":{"h":"4062c7d4","hi":["एक मिल में कच्ची कपास, कताई की मशीनों और बुनाई इकाइयों का उपयोग होता है। यह किस उद्योग का वर्णन है?",["जूट उद्योग","लौह-इस्पात उद्योग","चीनी उद्योग","सूती वस्त्र उद्योग"],"कपास के रेशे से धागा कातना और उस धागे से कपड़ा बुनना सूती वस्त्र विनिर्माण की मुख्य प्रक्रियाएँ हैं।"],"pa":["ਇੱਕ ਮਿੱਲ ਵਿੱਚ ਕੱਚੀ ਕਪਾਹ, ਕਤਾਈ ਦੀਆਂ ਮਸ਼ੀਨਾਂ ਅਤੇ ਬੁਣਾਈ ਇਕਾਈਆਂ ਵਰਤੀਆਂ ਜਾਂਦੀਆਂ ਹਨ। ਇਹ ਕਿਹੜੇ ਉਦਯੋਗ ਦਾ ਵਰਣਨ ਹੈ?",["ਜੂਟ ਉਦਯੋਗ","ਲੋਹਾ-ਸਟੀਲ ਉਦਯੋਗ","ਖੰਡ ਉਦਯੋਗ","ਸੂਤੀ ਕੱਪੜਾ ਉਦਯੋਗ"],"ਕਪਾਹ ਦੇ ਰੇਸ਼ੇ ਤੋਂ ਧਾਗਾ ਕੱਤਣਾ ਅਤੇ ਉਸ ਤੋਂ ਕੱਪੜਾ ਬੁਣਨਾ ਸੂਤੀ ਕੱਪੜਾ ਬਣਾਉਣ ਦੀਆਂ ਮੁੱਖ ਪ੍ਰਕਿਰਿਆਵਾਂ ਹਨ।"]},
"GEO-IND-001-CP003-Q007":{"h":"4cd63ae9","hi":["मुंबई किस प्रमुख उद्योग के शुरुआती केंद्रों में से एक बना?",["जूट वस्त्र","सूती वस्त्र","लौह अयस्क खनन","केवल चीनी मिलें"],"पत्तन तक पहुँच, पूँजी, श्रम और कपास उत्पादक क्षेत्रों से संपर्क के कारण मुंबई सूती वस्त्र उद्योग का महत्वपूर्ण केंद्र बना।"],"pa":["ਮੁੰਬਈ ਕਿਹੜੇ ਪ੍ਰਮੁੱਖ ਉਦਯੋਗ ਦੇ ਮੁੱਢਲੇ ਕੇਂਦਰਾਂ ਵਿੱਚੋਂ ਇੱਕ ਬਣਿਆ?",["ਜੂਟ ਦਾ ਕੱਪੜਾ","ਸੂਤੀ ਕੱਪੜਾ","ਕੱਚੇ ਲੋਹੇ ਦੀ ਖੁਦਾਈ","ਸਿਰਫ਼ ਖੰਡ ਮਿੱਲਾਂ"],"ਬੰਦਰਗਾਹ ਤੱਕ ਪਹੁੰਚ, ਪੂੰਜੀ, ਕਿਰਤ ਅਤੇ ਕਪਾਹ ਉਗਾਉਣ ਵਾਲੇ ਇਲਾਕਿਆਂ ਨਾਲ ਸੰਪਰਕ ਸਦਕਾ ਮੁੰਬਈ ਸੂਤੀ ਕੱਪੜੇ ਦਾ ਮਹੱਤਵਪੂਰਨ ਕੇਂਦਰ ਬਣਿਆ।"]},
"GEO-IND-001-CP003-Q008":{"h":"a219db72","hi":["अहमदाबाद ऐतिहासिक रूप से किस उद्योग के लिए प्रसिद्ध है?",["जूट उद्योग","चाय प्रसंस्करण","सूती वस्त्र उद्योग","केवल जहाज़ निर्माण"],"गुजरात का अहमदाबाद भारत के पारंपरिक सूती वस्त्र केंद्रों में से एक के रूप में विकसित हुआ।"],"pa":["ਅਹਿਮਦਾਬਾਦ ਇਤਿਹਾਸਕ ਤੌਰ 'ਤੇ ਕਿਹੜੇ ਉਦਯੋਗ ਲਈ ਮਸ਼ਹੂਰ ਹੈ?",["ਜੂਟ ਉਦਯੋਗ","ਚਾਹ ਦੀ ਪ੍ਰੋਸੈਸਿੰਗ","ਸੂਤੀ ਕੱਪੜਾ ਉਦਯੋਗ","ਸਿਰਫ਼ ਸਮੁੰਦਰੀ ਜਹਾਜ਼ ਬਣਾਉਣਾ"],"ਗੁਜਰਾਤ ਦਾ ਅਹਿਮਦਾਬਾਦ ਭਾਰਤ ਦੇ ਰਵਾਇਤੀ ਸੂਤੀ ਕੱਪੜਾ ਕੇਂਦਰਾਂ ਵਿੱਚੋਂ ਇੱਕ ਵਜੋਂ ਵਿਕਸਿਤ ਹੋਇਆ।"]},
"GEO-IND-001-CP003-Q009":{"h":"401f9dec","hi":["पश्चिमी भारत के वस्त्र उद्योग के भूगोल में कौन-सा युग्म सही सुमेलित है?",["मुंबई और अहमदाबाद — केवल जूट","मुंबई और अहमदाबाद — कोयला खनन","मुंबई और अहमदाबाद — केवल चीनी","मुंबई और अहमदाबाद — सूती वस्त्र"],"दोनों शहर पश्चिमी भारत के पारंपरिक सूती वस्त्र केंद्र हैं।"],"pa":["ਪੱਛਮੀ ਭਾਰਤ ਦੇ ਕੱਪੜਾ ਉਦਯੋਗ ਦੇ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਮੁੰਬਈ ਅਤੇ ਅਹਿਮਦਾਬਾਦ — ਸਿਰਫ਼ ਜੂਟ","ਮੁੰਬਈ ਅਤੇ ਅਹਿਮਦਾਬਾਦ — ਕੋਲੇ ਦੀ ਖੁਦਾਈ","ਮੁੰਬਈ ਅਤੇ ਅਹਿਮਦਾਬਾਦ — ਸਿਰਫ਼ ਖੰਡ","ਮੁੰਬਈ ਅਤੇ ਅਹਿਮਦਾਬਾਦ — ਸੂਤੀ ਕੱਪੜਾ"],"ਦੋਵੇਂ ਸ਼ਹਿਰ ਪੱਛਮੀ ਭਾਰਤ ਵਿੱਚ ਸੂਤੀ ਕੱਪੜੇ ਦੇ ਰਵਾਇਤੀ ਕੇਂਦਰ ਹਨ।"]},
"GEO-IND-001-CP003-Q010":{"h":"0a8fef98","hi":["कथनों पर विचार कीजिए: I. मुंबई को पत्तन की सुविधा प्राप्त है। II. अहमदाबाद गुजरात के कपास उत्पादक क्षेत्रों के निकट है। कौन-सा/से कथन सही है/हैं?",["I और II दोनों सही हैं","केवल I सही है","केवल II सही है","न तो I और न ही II सही है"],"मुंबई को अपने पत्तन का लाभ मिला, जबकि अहमदाबाद को कपास उत्पादक पृष्ठप्रदेश और बाज़ारों से संपर्क का विशेष लाभ मिला।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਮੁੰਬਈ ਨੂੰ ਬੰਦਰਗਾਹ ਦੀ ਸਹੂਲਤ ਹੈ। II. ਅਹਿਮਦਾਬਾਦ ਗੁਜਰਾਤ ਦੇ ਕਪਾਹ ਉਗਾਉਣ ਵਾਲੇ ਇਲਾਕਿਆਂ ਦੇ ਨੇੜੇ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਮੁੰਬਈ ਨੂੰ ਆਪਣੀ ਬੰਦਰਗਾਹ ਦਾ ਲਾਭ ਮਿਲਿਆ, ਜਦਕਿ ਅਹਿਮਦਾਬਾਦ ਨੂੰ ਕਪਾਹ ਉਗਾਉਣ ਵਾਲੇ ਪਿਛਲੇ ਇਲਾਕਿਆਂ ਅਤੇ ਬਾਜ਼ਾਰਾਂ ਨਾਲ ਸੰਪਰਕ ਦਾ ਖ਼ਾਸ ਲਾਭ ਮਿਲਿਆ।"]},
"GEO-IND-001-CP003-Q011":{"h":"4ffe8507","hi":["सूती वस्त्र उद्योग का प्रमुख केंद्र अहमदाबाद किस राज्य में है?",["महाराष्ट्र","गुजरात","पश्चिम बंगाल","तमिलनाडु"],"अहमदाबाद गुजरात में है और लंबे समय से सूती वस्त्र उद्योग का प्रमुख केंद्र रहा है।"],"pa":["ਸੂਤੀ ਕੱਪੜਾ ਉਦਯੋਗ ਦਾ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰ ਅਹਿਮਦਾਬਾਦ ਕਿਹੜੇ ਰਾਜ ਵਿੱਚ ਹੈ?",["ਮਹਾਰਾਸ਼ਟਰ","ਗੁਜਰਾਤ","ਪੱਛਮੀ ਬੰਗਾਲ","ਤਾਮਿਲਨਾਡੂ"],"ਅਹਿਮਦਾਬਾਦ ਗੁਜਰਾਤ ਵਿੱਚ ਹੈ ਅਤੇ ਲੰਮੇ ਸਮੇਂ ਤੋਂ ਸੂਤੀ ਕੱਪੜਾ ਉਦਯੋਗ ਦਾ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰ ਰਿਹਾ ਹੈ।"]},
"GEO-IND-001-CP003-Q012":{"h":"ca970c93","hi":["पश्चिमी भारत के सूती वस्त्र केंद्रों की कौन-सी तुलना सही है?",["दोनों पश्चिम बंगाल में हैं","मुंबई गुजरात में है और अहमदाबाद महाराष्ट्र में है","मुंबई महाराष्ट्र में है, जबकि अहमदाबाद गुजरात में है","दोनों तमिलनाडु में हैं"],"मुंबई और अहमदाबाद पश्चिमी भारत के दो पड़ोसी राज्यों के महत्वपूर्ण वस्त्र उद्योग केंद्र हैं।"],"pa":["ਪੱਛਮੀ ਭਾਰਤ ਦੇ ਸੂਤੀ ਕੱਪੜਾ ਕੇਂਦਰਾਂ ਦੀ ਕਿਹੜੀ ਤੁਲਨਾ ਸਹੀ ਹੈ?",["ਦੋਵੇਂ ਪੱਛਮੀ ਬੰਗਾਲ ਵਿੱਚ ਹਨ","ਮੁੰਬਈ ਗੁਜਰਾਤ ਵਿੱਚ ਹੈ ਅਤੇ ਅਹਿਮਦਾਬਾਦ ਮਹਾਰਾਸ਼ਟਰ ਵਿੱਚ ਹੈ","ਮੁੰਬਈ ਮਹਾਰਾਸ਼ਟਰ ਵਿੱਚ ਹੈ, ਜਦਕਿ ਅਹਿਮਦਾਬਾਦ ਗੁਜਰਾਤ ਵਿੱਚ ਹੈ","ਦੋਵੇਂ ਤਾਮਿਲਨਾਡੂ ਵਿੱਚ ਹਨ"],"ਮੁੰਬਈ ਅਤੇ ਅਹਿਮਦਾਬਾਦ ਪੱਛਮੀ ਭਾਰਤ ਦੇ ਗੁਆਂਢੀ ਰਾਜਾਂ ਵਿੱਚ ਕੱਪੜਾ ਉਦਯੋਗ ਦੇ ਮਹੱਤਵਪੂਰਨ ਕੇਂਦਰ ਹਨ।"]},
"GEO-IND-001-CP003-Q013":{"h":"1fa21253","hi":["दक्षिण भारत का कौन-सा राज्य सूती वस्त्र विनिर्माण का प्रमुख क्षेत्र है?",["पंजाब","असम","ओडिशा","तमिलनाडु"],"तमिलनाडु में सूती वस्त्र उद्योग का एक प्रमुख संकुल है। कताई, बुनाई और परिधान निर्माण की गतिविधियाँ कई शहरों में केंद्रित हैं।"],"pa":["ਦੱਖਣੀ ਭਾਰਤ ਦਾ ਕਿਹੜਾ ਰਾਜ ਸੂਤੀ ਕੱਪੜਾ ਬਣਾਉਣ ਵਾਲਾ ਪ੍ਰਮੁੱਖ ਖੇਤਰ ਹੈ?",["ਪੰਜਾਬ","ਅਸਾਮ","ਓਡੀਸ਼ਾ","ਤਾਮਿਲਨਾਡੂ"],"ਤਾਮਿਲਨਾਡੂ ਵਿੱਚ ਸੂਤੀ ਕੱਪੜਾ ਉਦਯੋਗ ਦੀਆਂ ਕਈ ਇਕਾਈਆਂ ਇੱਕੋ ਖੇਤਰ ਵਿੱਚ ਕੇਂਦਰਿਤ ਹਨ। ਕਤਾਈ, ਬੁਣਾਈ ਅਤੇ ਪਹਿਰਾਵੇ ਬਣਾਉਣ ਦਾ ਕੰਮ ਕਈ ਸ਼ਹਿਰਾਂ ਵਿੱਚ ਕੇਂਦਰਿਤ ਹੈ।"]},
"GEO-IND-001-CP003-Q014":{"h":"5161b8ee","hi":["कोयंबटूर विशेष रूप से किस उद्योग के लिए प्रसिद्ध है?",["सूती वस्त्र और कताई","जूट मिलें","केवल पेट्रोलियम शोधन","लौह अयस्क खनन"],"कोयंबटूर दक्षिण भारत में सूती वस्त्र और कताई के सबसे प्रसिद्ध केंद्रों में से एक है।"],"pa":["ਕੋਇੰਬਟੂਰ ਖ਼ਾਸ ਤੌਰ 'ਤੇ ਕਿਹੜੇ ਉਦਯੋਗ ਲਈ ਮਸ਼ਹੂਰ ਹੈ?",["ਸੂਤੀ ਕੱਪੜਾ ਅਤੇ ਕਤਾਈ","ਜੂਟ ਮਿੱਲਾਂ","ਸਿਰਫ਼ ਪੈਟਰੋਲੀਅਮ ਦੀ ਸੁਧਾਈ","ਕੱਚੇ ਲੋਹੇ ਦੀ ਖੁਦਾਈ"],"ਕੋਇੰਬਟੂਰ ਦੱਖਣੀ ਭਾਰਤ ਵਿੱਚ ਸੂਤੀ ਕੱਪੜੇ ਅਤੇ ਕਤਾਈ ਦੇ ਸਭ ਤੋਂ ਮਸ਼ਹੂਰ ਕੇਂਦਰਾਂ ਵਿੱਚੋਂ ਇੱਕ ਹੈ।"]},
"GEO-IND-001-CP003-Q015":{"h":"be0c6d74","hi":["कौन-सा शहर तमिलनाडु की प्रमुख वस्त्र उद्योग पट्टी में आता है?",["धनबाद","कोयंबटूर","डिगबोई","राउरकेला"],"कोयंबटूर तमिलनाडु के प्रमुख सूती वस्त्र और परिधान उद्योग क्षेत्र में आता है।"],"pa":["ਕਿਹੜਾ ਸ਼ਹਿਰ ਤਾਮਿਲਨਾਡੂ ਦੀ ਪ੍ਰਮੁੱਖ ਕੱਪੜਾ ਉਦਯੋਗ ਪੱਟੀ ਦਾ ਹਿੱਸਾ ਹੈ?",["ਧਨਬਾਦ","ਕੋਇੰਬਟੂਰ","ਡਿਗਬੋਈ","ਰਾਉਰਕੇਲਾ"],"ਕੋਇੰਬਟੂਰ ਤਾਮਿਲਨਾਡੂ ਦੇ ਪ੍ਰਮੁੱਖ ਸੂਤੀ ਕੱਪੜਾ ਅਤੇ ਪਹਿਰਾਵਾ ਉਦਯੋਗ ਖੇਤਰ ਵਿੱਚ ਪੈਂਦਾ ਹੈ।"]},
"GEO-IND-001-CP003-Q016":{"h":"c7016cbe","hi":["कथनों पर विचार कीजिए: I. कोयंबटूर तमिलनाडु में है। II. तमिलनाडु कताई और वस्त्र उत्पादन में प्रमुख राज्य है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","I और II दोनों सही हैं","न तो I और न ही II सही है"],"दोनों कथन तमिलनाडु की वस्त्र उद्योग पट्टी की अवस्थिति और औद्योगिक महत्व का सही वर्णन करते हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਕੋਇੰਬਟੂਰ ਤਾਮਿਲਨਾਡੂ ਵਿੱਚ ਹੈ। II. ਤਾਮਿਲਨਾਡੂ ਕਤਾਈ ਅਤੇ ਕੱਪੜਾ ਉਤਪਾਦਨ ਵਿੱਚ ਪ੍ਰਮੁੱਖ ਰਾਜ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਦੋਵੇਂ ਕਥਨ ਤਾਮਿਲਨਾਡੂ ਦੀ ਕੱਪੜਾ ਉਦਯੋਗ ਪੱਟੀ ਦੀ ਸਥਿਤੀ ਅਤੇ ਉਦਯੋਗਿਕ ਮਹੱਤਤਾ ਦਾ ਸਹੀ ਵਰਣਨ ਕਰਦੇ ਹਨ।"]},
"GEO-IND-001-CP003-Q017":{"h":"1b7588a1","hi":["दक्षिण भारत के वस्त्र उद्योग के भूगोल में कौन-सा युग्म सही सुमेलित है?",["कोयंबटूर — केवल जूट","कोयंबटूर — कोयला क्षेत्र","कोयंबटूर — पेट्रोलियम क्षेत्र","कोयंबटूर — सूती वस्त्र"],"कोयंबटूर का सूती वस्त्र उद्योग और कताई से गहरा संबंध है।"],"pa":["ਦੱਖਣੀ ਭਾਰਤ ਦੇ ਕੱਪੜਾ ਉਦਯੋਗ ਦੇ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਕੋਇੰਬਟੂਰ — ਸਿਰਫ਼ ਜੂਟ","ਕੋਇੰਬਟੂਰ — ਕੋਲਾ ਖੇਤਰ","ਕੋਇੰਬਟੂਰ — ਪੈਟਰੋਲੀਅਮ ਖੇਤਰ","ਕੋਇੰਬਟੂਰ — ਸੂਤੀ ਕੱਪੜਾ"],"ਕੋਇੰਬਟੂਰ ਦਾ ਸੂਤੀ ਕੱਪੜਾ ਉਦਯੋਗ ਅਤੇ ਕਤਾਈ ਨਾਲ ਡੂੰਘਾ ਸਬੰਧ ਹੈ।"]},
"GEO-IND-001-CP003-Q018":{"h":"15049390","hi":["एक स्थापित वस्त्र उद्योग संकुल नई कंपनियों को लगातार क्यों आकर्षित कर सकता है?",["कुशल श्रम, आपूर्तिकर्ता और प्रसंस्करण तंत्र पहले से मौजूद हैं","श्रमिकों की कमी है","परिवहन की सुविधा नहीं है","केवल खनिजों पर निर्भरता है"],"एक जगह केंद्रित होने से वस्त्र उद्योगों को विशिष्ट कौशल वाले श्रमिकों, मशीनरी संबंधी सेवाओं, धागा आपूर्तिकर्ताओं और बाज़ार संपर्क का लाभ मिलता है।"],"pa":["ਕੱਪੜਾ ਉਦਯੋਗ ਦਾ ਸਥਾਪਤ ਗੁੱਛ ਨਵੀਆਂ ਕੰਪਨੀਆਂ ਨੂੰ ਲਗਾਤਾਰ ਕਿਉਂ ਖਿੱਚ ਸਕਦਾ ਹੈ?",["ਹੁਨਰਮੰਦ ਕਾਮੇ, ਸਪਲਾਇਰ ਅਤੇ ਪ੍ਰੋਸੈਸਿੰਗ ਦੇ ਤੰਤਰ ਪਹਿਲਾਂ ਹੀ ਮੌਜੂਦ ਹਨ","ਕਾਮਿਆਂ ਦੀ ਘਾਟ ਹੈ","ਆਵਾਜਾਈ ਦੀ ਸਹੂਲਤ ਨਹੀਂ ਹੈ","ਸਿਰਫ਼ ਖਣਿਜਾਂ 'ਤੇ ਨਿਰਭਰਤਾ ਹੈ"],"ਇੱਕੋ ਥਾਂ ਇਕੱਠੇ ਹੋਣ ਨਾਲ ਕੱਪੜਾ ਉਦਯੋਗਾਂ ਨੂੰ ਖ਼ਾਸ ਹੁਨਰ ਵਾਲੇ ਕਾਮਿਆਂ, ਮਸ਼ੀਨਰੀ ਦੀਆਂ ਸੇਵਾਵਾਂ, ਧਾਗੇ ਦੇ ਸਪਲਾਇਰਾਂ ਅਤੇ ਬਾਜ਼ਾਰਾਂ ਨਾਲ ਸੰਪਰਕ ਦਾ ਲਾਭ ਮਿਲਦਾ ਹੈ।"]},
"GEO-IND-001-CP003-Q019":{"h":"4ae4688f","hi":["किस नदी की घाटी भारत के जूट उद्योग का पारंपरिक केंद्र है?",["नर्मदा घाटी","गोदावरी घाटी","सतलुज घाटी","हुगली घाटी"],"अधिकांश पारंपरिक जूट मिलें कोलकाता और उसके आसपास हुगली नदी के किनारे स्थापित हुईं।"],"pa":["ਕਿਸ ਦਰਿਆ ਦੀ ਘਾਟੀ ਭਾਰਤ ਦੇ ਜੂਟ ਉਦਯੋਗ ਦਾ ਰਵਾਇਤੀ ਕੇਂਦਰ ਹੈ?",["ਨਰਮਦਾ ਘਾਟੀ","ਗੋਦਾਵਰੀ ਘਾਟੀ","ਸਤਲੁਜ ਘਾਟੀ","ਹੁਗਲੀ ਘਾਟੀ"],"ਜ਼ਿਆਦਾਤਰ ਰਵਾਇਤੀ ਜੂਟ ਮਿੱਲਾਂ ਕੋਲਕਾਤਾ ਅਤੇ ਇਸ ਦੇ ਆਲੇ-ਦੁਆਲੇ ਹੁਗਲੀ ਦਰਿਆ ਦੇ ਕੰਢੇ ਵਿਕਸਿਤ ਹੋਈਆਂ।"]},
"GEO-IND-001-CP003-Q020":{"h":"b9579a87","hi":["जूट मिलें कोलकाता और हुगली नदी के पास क्यों केंद्रित हुईं?",["कच्चा जूट, नदी का पानी, पत्तन तक पहुँच, श्रम और परिवहन उपलब्ध थे","लौह अयस्क मुख्य कच्चा माल था","क्षेत्र में कोई पत्तन नहीं था","केवल जलविद्युत का महत्व था"],"हुगली पट्टी में जूट उत्पादक डेल्टा तक पहुँच, प्रचुर जल, कोलकाता पत्तन, श्रम और परिवहन की सुविधाएँ एक साथ उपलब्ध थीं।"],"pa":["ਜੂਟ ਮਿੱਲਾਂ ਕੋਲਕਾਤਾ ਅਤੇ ਹੁਗਲੀ ਦਰਿਆ ਦੇ ਨੇੜੇ ਕਿਉਂ ਕੇਂਦਰਿਤ ਹੋਈਆਂ?",["ਕੱਚਾ ਜੂਟ, ਦਰਿਆ ਦਾ ਪਾਣੀ, ਬੰਦਰਗਾਹ ਤੱਕ ਪਹੁੰਚ, ਕਾਮੇ ਅਤੇ ਆਵਾਜਾਈ ਉਪਲਬਧ ਸਨ","ਕੱਚਾ ਲੋਹਾ ਮੁੱਖ ਕੱਚਾ ਮਾਲ ਸੀ","ਇਲਾਕੇ ਵਿੱਚ ਕੋਈ ਬੰਦਰਗਾਹ ਨਹੀਂ ਸੀ","ਸਿਰਫ਼ ਪਣ-ਬਿਜਲੀ ਦਾ ਮਹੱਤਵ ਸੀ"],"ਹੁਗਲੀ ਪੱਟੀ ਵਿੱਚ ਜੂਟ ਉਗਾਉਣ ਵਾਲੇ ਡੈਲਟੇ ਤੱਕ ਪਹੁੰਚ, ਪਾਣੀ ਦੀ ਬਹੁਤਾਤ, ਕੋਲਕਾਤਾ ਦੀ ਬੰਦਰਗਾਹ, ਕਾਮੇ ਅਤੇ ਆਵਾਜਾਈ ਦੀਆਂ ਸਹੂਲਤਾਂ ਇਕੱਠੀਆਂ ਮਿਲਦੀਆਂ ਸਨ।"]},
"GEO-IND-001-CP003-Q021":{"h":"feeba505","hi":["हुगली की पारंपरिक जूट मिल पट्टी किस राज्य में है?",["गुजरात","पश्चिम बंगाल","तमिलनाडु","राजस्थान"],"हुगली औद्योगिक पट्टी पश्चिम बंगाल में है। भारत की जूट मिलों का पारंपरिक जमाव इसी पट्टी में है।"],"pa":["ਹੁਗਲੀ ਦੀ ਰਵਾਇਤੀ ਜੂਟ ਮਿੱਲ ਪੱਟੀ ਕਿਹੜੇ ਰਾਜ ਵਿੱਚ ਹੈ?",["ਗੁਜਰਾਤ","ਪੱਛਮੀ ਬੰਗਾਲ","ਤਾਮਿਲਨਾਡੂ","ਰਾਜਸਥਾਨ"],"ਹੁਗਲੀ ਦੀ ਉਦਯੋਗਿਕ ਪੱਟੀ ਪੱਛਮੀ ਬੰਗਾਲ ਵਿੱਚ ਹੈ। ਭਾਰਤ ਦੀਆਂ ਜੂਟ ਮਿੱਲਾਂ ਰਵਾਇਤੀ ਤੌਰ 'ਤੇ ਇਸ ਪੱਟੀ ਵਿੱਚ ਕੇਂਦਰਿਤ ਰਹੀਆਂ ਹਨ।"]},
"GEO-IND-001-CP003-Q022":{"h":"d2d45ec9","hi":["कथनों पर विचार कीजिए: I. जूट कृषि आधारित कच्चा माल है। II. हुगली पट्टी जूट उत्पादक क्षेत्रों के निकट है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","I और II दोनों सही हैं","न तो I और न ही II सही है"],"जूट एक पादप रेशा है। मिलें जूट उत्पादक गंगा-ब्रह्मपुत्र डेल्टा क्षेत्र के निकट विकसित हुईं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਜੂਟ ਖੇਤੀ ਤੋਂ ਮਿਲਦਾ ਕੱਚਾ ਮਾਲ ਹੈ। II. ਹੁਗਲੀ ਪੱਟੀ ਜੂਟ ਉਗਾਉਣ ਵਾਲੇ ਇਲਾਕਿਆਂ ਦੇ ਨੇੜੇ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਜੂਟ ਪੌਦਿਆਂ ਤੋਂ ਮਿਲਦਾ ਰੇਸ਼ਾ ਹੈ। ਮਿੱਲਾਂ ਗੰਗਾ-ਬ੍ਰਹਮਪੁੱਤਰ ਦੇ ਜੂਟ ਉਗਾਉਣ ਵਾਲੇ ਡੈਲਟਾ ਖੇਤਰ ਦੇ ਨੇੜੇ ਵਿਕਸਿਤ ਹੋਈਆਂ।"]},
"GEO-IND-001-CP003-Q023":{"h":"89544222","hi":["जूट उद्योग के भूगोल में कौन-सा युग्म सही सुमेलित है?",["हुगली पट्टी — राजस्थान","हुगली पट्टी — कर्नाटक","हुगली पट्टी — पंजाब","हुगली पट्टी — पश्चिम बंगाल"],"हुगली की जूट मिल पट्टी पश्चिम बंगाल में स्थित है।"],"pa":["ਜੂਟ ਉਦਯੋਗ ਦੇ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਹੁਗਲੀ ਪੱਟੀ — ਰਾਜਸਥਾਨ","ਹੁਗਲੀ ਪੱਟੀ — ਕਰਨਾਟਕ","ਹੁਗਲੀ ਪੱਟੀ — ਪੰਜਾਬ","ਹੁਗਲੀ ਪੱਟੀ — ਪੱਛਮੀ ਬੰਗਾਲ"],"ਹੁਗਲੀ ਦੀ ਜੂਟ ਮਿੱਲ ਪੱਟੀ ਪੱਛਮੀ ਬੰਗਾਲ ਵਿੱਚ ਹੈ।"]},
"GEO-IND-001-CP003-Q024":{"h":"d9017ee0","hi":["एक कारखाना कच्चे जूट से बोरे और पैकिंग सामग्री बनाता है। वह किस उद्योग का हिस्सा है?",["जूट वस्त्र उद्योग","सूती वस्त्र उद्योग","इस्पात उद्योग","सीमेंट उद्योग"],"जूट वस्त्र उद्योग में जूट के रेशे का प्रसंस्करण करके बोरे, टाट और पैकिंग के अन्य उत्पाद बनाए जाते हैं।"],"pa":["ਇੱਕ ਕਾਰਖ਼ਾਨਾ ਕੱਚੇ ਜੂਟ ਤੋਂ ਬੋਰੀਆਂ ਅਤੇ ਪੈਕਿੰਗ ਦਾ ਸਾਮਾਨ ਬਣਾਉਂਦਾ ਹੈ। ਇਹ ਕਿਹੜਾ ਉਦਯੋਗ ਹੈ?",["ਜੂਟ ਕੱਪੜਾ ਉਦਯੋਗ","ਸੂਤੀ ਕੱਪੜਾ ਉਦਯੋਗ","ਸਟੀਲ ਉਦਯੋਗ","ਸੀਮਿੰਟ ਉਦਯੋਗ"],"ਜੂਟ ਕੱਪੜਾ ਉਦਯੋਗ ਵਿੱਚ ਜੂਟ ਦੇ ਰੇਸ਼ੇ ਤੋਂ ਬੋਰੀਆਂ, ਟਾਟ ਅਤੇ ਪੈਕਿੰਗ ਦੇ ਹੋਰ ਉਤਪਾਦ ਬਣਾਏ ਜਾਂਦੇ ਹਨ।"]},
"GEO-IND-001-CP003-Q025":{"h":"3fe7dd62","hi":["कौन-सा रेशा मानव निर्मित है और सीधे किसी फसल से प्राप्त नहीं होता?",["पॉलिएस्टर","कपास","जूट","ऊन"],"पॉलिएस्टर रासायनिक प्रसंस्करण से बनाया जाने वाला संश्लेषित रेशा है। कपास, जूट और ऊन प्राकृतिक रेशे हैं।"],"pa":["ਕਿਹੜਾ ਰੇਸ਼ਾ ਮਨੁੱਖ ਦੁਆਰਾ ਬਣਾਇਆ ਜਾਂਦਾ ਹੈ ਅਤੇ ਸਿੱਧਾ ਕਿਸੇ ਫ਼ਸਲ ਤੋਂ ਨਹੀਂ ਮਿਲਦਾ?",["ਪਾਲੀਐਸਟਰ","ਕਪਾਹ","ਜੂਟ","ਉੱਨ"],"ਪਾਲੀਐਸਟਰ ਰਸਾਇਣਕ ਪ੍ਰਕਿਰਿਆ ਨਾਲ ਬਣਾਇਆ ਜਾਣ ਵਾਲਾ ਬਣਾਵਟੀ ਰੇਸ਼ਾ ਹੈ। ਕਪਾਹ, ਜੂਟ ਅਤੇ ਉੱਨ ਕੁਦਰਤੀ ਰੇਸ਼ੇ ਹਨ।"]},
"GEO-IND-001-CP003-Q026":{"h":"b62fd0da","hi":["संश्लेषित रेशों के लिए महत्वपूर्ण कच्चा माल किस उद्योग से मिलता है?",["लौह अयस्क खनन","पेट्रोरसायन उद्योग","चीनी उद्योग","जूट की खेती"],"पॉलिएस्टर और नायलॉन जैसे कई संश्लेषित रेशे पेट्रोरसायन से प्राप्त कच्चे माल से बनाए जाते हैं।"],"pa":["ਬਣਾਵਟੀ ਰੇਸ਼ਿਆਂ ਲਈ ਅਹਿਮ ਕੱਚਾ ਮਾਲ ਕਿਹੜਾ ਉਦਯੋਗ ਦਿੰਦਾ ਹੈ?",["ਕੱਚੇ ਲੋਹੇ ਦੀ ਖੁਦਾਈ","ਪੈਟਰੋ-ਰਸਾਇਣ ਉਦਯੋਗ","ਖੰਡ ਉਦਯੋਗ","ਜੂਟ ਦੀ ਖੇਤੀ"],"ਪਾਲੀਐਸਟਰ ਅਤੇ ਨਾਈਲੋਨ ਵਰਗੇ ਕਈ ਬਣਾਵਟੀ ਰੇਸ਼ੇ ਪੈਟਰੋ-ਰਸਾਇਣਾਂ ਤੋਂ ਮਿਲਦੇ ਕੱਚੇ ਮਾਲ ਨਾਲ ਬਣਾਏ ਜਾਂਦੇ ਹਨ।"]},
"GEO-IND-001-CP003-Q027":{"h":"d42c8f69","hi":["कथनों पर विचार कीजिए: I. पॉलिएस्टर संश्लेषित रेशा है। II. कपास प्राकृतिक रेशा है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","I और II दोनों सही हैं","न तो I और न ही II सही है"],"पॉलिएस्टर रासायनिक प्रक्रिया से बनाया जाता है, जबकि कपास एक प्राकृतिक पादप रेशा है।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਪਾਲੀਐਸਟਰ ਬਣਾਵਟੀ ਰੇਸ਼ਾ ਹੈ। II. ਕਪਾਹ ਕੁਦਰਤੀ ਰੇਸ਼ਾ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਪਾਲੀਐਸਟਰ ਰਸਾਇਣਕ ਵਿਧੀ ਨਾਲ ਬਣਾਇਆ ਜਾਂਦਾ ਹੈ, ਜਦਕਿ ਕਪਾਹ ਪੌਦੇ ਤੋਂ ਮਿਲਦਾ ਕੁਦਰਤੀ ਰੇਸ਼ਾ ਹੈ।"]},
"GEO-IND-001-CP003-Q028":{"h":"b00cd64c","hi":["रेशों के वर्गीकरण में कौन-सा युग्म सही सुमेलित है?",["कपास — संश्लेषित रेशा","जूट — पेट्रोरासायनिक रेशा","ऊन — खनिज रेशा","पॉलिएस्टर — संश्लेषित रेशा"],"पॉलिएस्टर संश्लेषित रेशा है, जबकि कपास, जूट और ऊन प्राकृतिक रेशे हैं।"],"pa":["ਰੇਸ਼ਿਆਂ ਦੇ ਵਰਗੀਕਰਨ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਕਪਾਹ — ਬਣਾਵਟੀ ਰੇਸ਼ਾ","ਜੂਟ — ਪੈਟਰੋ-ਰਸਾਇਣਕ ਰੇਸ਼ਾ","ਉੱਨ — ਖਣਿਜ ਰੇਸ਼ਾ","ਪਾਲੀਐਸਟਰ — ਬਣਾਵਟੀ ਰੇਸ਼ਾ"],"ਪਾਲੀਐਸਟਰ ਬਣਾਵਟੀ ਰੇਸ਼ਾ ਹੈ, ਜਦਕਿ ਕਪਾਹ, ਜੂਟ ਅਤੇ ਉੱਨ ਕੁਦਰਤੀ ਰੇਸ਼ੇ ਹਨ।"]},
"GEO-IND-001-CP003-Q029":{"h":"bed39fe7","hi":["संश्लेषित रेशा उद्योगों की अवस्थिति फसल उत्पादक क्षेत्रों पर कम निर्भर क्यों हो सकती है?",["इनका कच्चा माल रासायनिक और पेट्रोरासायनिक स्रोतों से मिलता है","इन्हें कपास के खेतों की आवश्यकता होती है","ये केवल गन्ने पर निर्भर हैं","ये लौह अयस्क को रेशे के रूप में उपयोग करते हैं"],"संश्लेषित रेशे रासायनिक विधि से बनाए जाते हैं। इसलिए इन उद्योगों की अवस्थिति पर फसल उत्पादक क्षेत्रों की निकटता से अधिक रासायनिक कच्चे माल, बाज़ार, आधारभूत संरचना और बिजली का प्रभाव पड़ता है।"],"pa":["ਬਣਾਵਟੀ ਰੇਸ਼ਾ ਉਦਯੋਗਾਂ ਦੀ ਥਾਂ ਫ਼ਸਲਾਂ ਉਗਾਉਣ ਵਾਲੇ ਇਲਾਕਿਆਂ 'ਤੇ ਘੱਟ ਨਿਰਭਰ ਕਿਉਂ ਹੋ ਸਕਦੀ ਹੈ?",["ਇਨ੍ਹਾਂ ਦਾ ਕੱਚਾ ਮਾਲ ਰਸਾਇਣਕ ਅਤੇ ਪੈਟਰੋ-ਰਸਾਇਣਕ ਸਰੋਤਾਂ ਤੋਂ ਆਉਂਦਾ ਹੈ","ਇਨ੍ਹਾਂ ਨੂੰ ਕਪਾਹ ਦੇ ਖੇਤ ਚਾਹੀਦੇ ਹਨ","ਇਹ ਸਿਰਫ਼ ਗੰਨੇ 'ਤੇ ਨਿਰਭਰ ਹਨ","ਇਹ ਕੱਚੇ ਲੋਹੇ ਨੂੰ ਰੇਸ਼ੇ ਵਜੋਂ ਵਰਤਦੇ ਹਨ"],"ਬਣਾਵਟੀ ਰੇਸ਼ੇ ਰਸਾਇਣਕ ਤਰੀਕੇ ਨਾਲ ਬਣਦੇ ਹਨ। ਇਸ ਲਈ ਉਦਯੋਗ ਦੀ ਥਾਂ 'ਤੇ ਫ਼ਸਲੀ ਇਲਾਕਿਆਂ ਦੀ ਨੇੜਤਾ ਨਾਲੋਂ ਰਸਾਇਣਕ ਕੱਚੇ ਮਾਲ, ਬਾਜ਼ਾਰਾਂ, ਬੁਨਿਆਦੀ ਢਾਂਚੇ ਅਤੇ ਬਿਜਲੀ ਦਾ ਵੱਧ ਅਸਰ ਪੈਂਦਾ ਹੈ।"]},
"GEO-IND-001-CP003-Q030":{"h":"53d6a6ee","hi":["एक वस्त्र संयंत्र पेट्रोरसायन से मिले कच्चे माल का उपयोग करके रेशा बनाता है। उसके उत्पाद का सबसे उपयुक्त उदाहरण क्या है?",["कच्चा जूट","पॉलिएस्टर","कच्ची कपास","कतरकर उतारी गई ऊन"],"पॉलिएस्टर पेट्रोरसायन आधारित कच्चे माल से बनाया जाने वाला संश्लेषित रेशा है।"],"pa":["ਇੱਕ ਕੱਪੜਾ ਪਲਾਂਟ ਪੈਟਰੋ-ਰਸਾਇਣਾਂ ਤੋਂ ਮਿਲੇ ਕੱਚੇ ਮਾਲ ਨਾਲ ਰੇਸ਼ਾ ਬਣਾਉਂਦਾ ਹੈ। ਉਸ ਦੇ ਉਤਪਾਦ ਦੀ ਸਭ ਤੋਂ ਢੁੱਕਵੀਂ ਉਦਾਹਰਨ ਕਿਹੜੀ ਹੈ?",["ਕੱਚਾ ਜੂਟ","ਪਾਲੀਐਸਟਰ","ਕੱਚੀ ਕਪਾਹ","ਕੱਟ ਕੇ ਉਤਾਰੀ ਉੱਨ"],"ਪਾਲੀਐਸਟਰ ਪੈਟਰੋ-ਰਸਾਇਣਾਂ ਤੋਂ ਮਿਲਦੇ ਕੱਚੇ ਮਾਲ ਨਾਲ ਬਣਾਇਆ ਜਾਣ ਵਾਲਾ ਬਣਾਵਟੀ ਰੇਸ਼ਾ ਹੈ।"]},
"GEO-IND-001-CP003-Q031":{"h":"09079fd0","hi":["परिधान विनिर्माण के लिए बड़ी संख्या में श्रमिकों की उपलब्धता क्यों महत्वपूर्ण है?",["परिधान अयस्क के खनन से प्राप्त होते हैं","परिधान कारखानों को श्रमिकों की आवश्यकता नहीं होती","परिधान उत्पादन में कटाई, सिलाई और अंतिम साज-सँवार के लिए बहुत श्रम लगता है","परिधान उत्पादन केवल वर्षा पर निर्भर है"],"परिधान विनिर्माण श्रम प्रधान है। यह उत्पादन और सिलाई में कुशल श्रमिकों पर निर्भर है।"],"pa":["ਪਹਿਰਾਵੇ ਬਣਾਉਣ ਲਈ ਵੱਡੀ ਗਿਣਤੀ ਵਿੱਚ ਕਾਮਿਆਂ ਦੀ ਉਪਲਬਧਤਾ ਕਿਉਂ ਜ਼ਰੂਰੀ ਹੈ?",["ਪਹਿਰਾਵੇ ਖਣਿਜ ਅਯਸਕ ਦੀ ਖੁਦਾਈ ਤੋਂ ਮਿਲਦੇ ਹਨ","ਪਹਿਰਾਵਾ ਕਾਰਖ਼ਾਨਿਆਂ ਨੂੰ ਕਾਮਿਆਂ ਦੀ ਲੋੜ ਨਹੀਂ ਹੁੰਦੀ","ਪਹਿਰਾਵੇ ਬਣਾਉਣ ਲਈ ਕਟਾਈ, ਸਿਲਾਈ ਅਤੇ ਆਖ਼ਰੀ ਸੰਵਾਰ ਵਿੱਚ ਬਹੁਤ ਕਿਰਤ ਲੱਗਦੀ ਹੈ","ਪਹਿਰਾਵੇ ਦਾ ਉਤਪਾਦਨ ਸਿਰਫ਼ ਵਰਖਾ 'ਤੇ ਨਿਰਭਰ ਹੈ"],"ਪਹਿਰਾਵੇ ਬਣਾਉਣ ਵਿੱਚ ਬਹੁਤ ਕਿਰਤ ਲੱਗਦੀ ਹੈ। ਇਹ ਕੰਮ ਉਤਪਾਦਨ ਅਤੇ ਸਿਲਾਈ ਵਿੱਚ ਹੁਨਰਮੰਦ ਕਾਮਿਆਂ 'ਤੇ ਨਿਰਭਰ ਹੈ।"]},
"GEO-IND-001-CP003-Q032":{"h":"31fd2168","hi":["वस्त्र उद्योग प्रायः स्थापित केंद्रों में क्यों इकट्ठा होते हैं?",["संकुल बनने से उत्पादन सामग्री मिलनी बंद हो जाती है","संकुल बनने से विशिष्टीकरण रुक जाता है","वस्त्र उद्योग को आपूर्तिकर्ताओं की आवश्यकता नहीं होती","कुशल श्रम, आपूर्तिकर्ताओं, मशीनरी सेवाओं और बाज़ारों का लाभ मिलता है"],"उद्योगों के एक जगह केंद्रित होने से श्रमिकों, प्रसंस्करण सेवाओं और आपूर्तिकर्ताओं के साझा तंत्र बनते हैं, जो वस्त्र उत्पादन में सहायक होते हैं।"],"pa":["ਕੱਪੜਾ ਉਦਯੋਗ ਅਕਸਰ ਸਥਾਪਤ ਕੇਂਦਰਾਂ ਵਿੱਚ ਕਿਉਂ ਇਕੱਠੇ ਹੁੰਦੇ ਹਨ?",["ਗੁੱਛ ਬਣਨ ਨਾਲ ਉਤਪਾਦਨ ਦੀ ਸਮੱਗਰੀ ਮਿਲਣੀ ਬੰਦ ਹੋ ਜਾਂਦੀ ਹੈ","ਗੁੱਛ ਬਣਨ ਨਾਲ ਕਿਸੇ ਖ਼ਾਸ ਕੰਮ ਵਿੱਚ ਮੁਹਾਰਤ ਹਾਸਲ ਨਹੀਂ ਹੁੰਦੀ","ਕੱਪੜਾ ਉਦਯੋਗ ਨੂੰ ਸਪਲਾਇਰਾਂ ਦੀ ਲੋੜ ਨਹੀਂ ਹੁੰਦੀ","ਹੁਨਰਮੰਦ ਕਾਮਿਆਂ, ਸਪਲਾਇਰਾਂ, ਮਸ਼ੀਨਰੀ ਸੇਵਾਵਾਂ ਅਤੇ ਬਾਜ਼ਾਰਾਂ ਦਾ ਲਾਭ ਮਿਲਦਾ ਹੈ"],"ਉਦਯੋਗਾਂ ਦੇ ਇੱਕ ਥਾਂ ਇਕੱਠੇ ਹੋਣ ਨਾਲ ਕਾਮੇ, ਪ੍ਰੋਸੈਸਿੰਗ ਸੇਵਾਵਾਂ ਅਤੇ ਸਪਲਾਇਰਾਂ ਦੇ ਤੰਤਰ ਸਾਂਝੇ ਹੋ ਜਾਂਦੇ ਹਨ, ਜਿਸ ਨਾਲ ਕੱਪੜਾ ਉਤਪਾਦਨ ਨੂੰ ਮਦਦ ਮਿਲਦੀ ਹੈ।"]},
"GEO-IND-001-CP003-Q033":{"h":"0b7c84f8","hi":["कथनों पर विचार कीजिए: I. परिधान उत्पादन श्रम प्रधान हो सकता है। II. फ़ैशन और परिधान उद्योग को बाज़ारों तक पहुँच से लाभ होता है। कौन-सा/से कथन सही है/हैं?",["I और II दोनों सही हैं","केवल I सही है","केवल II सही है","न तो I और न ही II सही है"],"श्रम की आवश्यकता और उपभोक्ताओं या निर्यात बाज़ारों की निकटता, दोनों वस्त्र और परिधान उद्योग की अवस्थिति को प्रभावित करती हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਪਹਿਰਾਵੇ ਬਣਾਉਣ ਲਈ ਵੱਡੀ ਮਾਤਰਾ ਵਿੱਚ ਕਿਰਤ ਦੀ ਲੋੜ ਪੈ ਸਕਦੀ ਹੈ। II. ਫ਼ੈਸ਼ਨ ਅਤੇ ਪਹਿਰਾਵਾ ਉਦਯੋਗਾਂ ਨੂੰ ਬਾਜ਼ਾਰਾਂ ਤੱਕ ਪਹੁੰਚ ਦਾ ਲਾਭ ਹੁੰਦਾ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਕਿਰਤ ਦੀ ਲੋੜ ਅਤੇ ਖਪਤਕਾਰਾਂ ਜਾਂ ਨਿਰਯਾਤ ਬਾਜ਼ਾਰਾਂ ਦੀ ਨੇੜਤਾ, ਦੋਵੇਂ ਕੱਪੜਾ ਅਤੇ ਪਹਿਰਾਵਾ ਉਦਯੋਗਾਂ ਦੀ ਥਾਂ 'ਤੇ ਅਸਰ ਪਾਉਂਦੇ ਹਨ।"]},
"GEO-IND-001-CP003-Q034":{"h":"88ab4a0a","hi":["जब किसी बड़े महानगरीय बाज़ार के निकट परिधान केंद्र विकसित होता है, तो कौन-सा अवस्थितिक कारक सामने आता है?",["लौह अयस्क की श्रेणी","बाज़ार तक पहुँच","कोयले की परत की मोटाई","द्रवीय दाबोच्चता"],"बड़े शहरी बाज़ारों और माल की आवाजाही के तंत्र से परिधानों की अच्छी माँग और वितरण की सुविधा मिलती है।"],"pa":["ਕਿਸੇ ਵੱਡੇ ਮਹਾਂਨਗਰੀ ਬਾਜ਼ਾਰ ਦੇ ਨੇੜੇ ਪਹਿਰਾਵਾ ਕੇਂਦਰ ਵਿਕਸਿਤ ਹੋਵੇ ਤਾਂ ਥਾਂ ਦੀ ਚੋਣ ਦਾ ਕਿਹੜਾ ਕਾਰਕ ਸਾਹਮਣੇ ਆਉਂਦਾ ਹੈ?",["ਕੱਚੇ ਲੋਹੇ ਦੀ ਦਰਜਾਬੰਦੀ","ਬਾਜ਼ਾਰ ਤੱਕ ਪਹੁੰਚ","ਕੋਲੇ ਦੀ ਪਰਤ ਦੀ ਮੋਟਾਈ","ਪਾਣੀ ਦੇ ਦਬਾਅ ਦੀ ਉਚਾਈ"],"ਵੱਡੇ ਸ਼ਹਿਰੀ ਬਾਜ਼ਾਰਾਂ ਅਤੇ ਮਾਲ ਦੀ ਢੋਆ-ਢੁਆਈ ਦੇ ਤੰਤਰਾਂ ਤੋਂ ਪਹਿਰਾਵਿਆਂ ਦੀ ਚੰਗੀ ਮੰਗ ਅਤੇ ਵੰਡ ਦੀ ਸਹੂਲਤ ਮਿਲਦੀ ਹੈ।"]},
"GEO-IND-001-CP003-Q035":{"h":"19f7a803","hi":["जिन स्थानों पर प्रशिक्षित कताई श्रमिक और बुनकर उपलब्ध हैं, वहाँ वस्त्र मिलें लगने से किस कारक का महत्व स्पष्ट होता है?",["खनिज भंडार","ज्वारीय परास","कुशल श्रम","वन घनत्व"],"वस्त्र उद्योग के विशिष्ट कौशल वाले श्रमिकों की उपलब्धता अवस्थिति का श्रम आधारित लाभ है।"],"pa":["ਜਿੱਥੇ ਕਤਾਈ ਅਤੇ ਬੁਣਾਈ ਦੇ ਸਿਖਲਾਈ ਪ੍ਰਾਪਤ ਕਾਮੇ ਮਿਲਦੇ ਹੋਣ, ਉੱਥੇ ਕੱਪੜਾ ਮਿੱਲਾਂ ਲੱਗਣ ਨਾਲ ਕਿਹੜੇ ਕਾਰਕ ਦੀ ਮਹੱਤਤਾ ਸਪਸ਼ਟ ਹੁੰਦੀ ਹੈ?",["ਖਣਿਜ ਭੰਡਾਰ","ਜਵਾਰ-ਭਾਟਾ ਅੰਤਰ","ਹੁਨਰਮੰਦ ਕਾਮੇ","ਜੰਗਲਾਂ ਦੀ ਸੰਘਣਤਾ"],"ਕੱਪੜਾ ਉਦਯੋਗ ਦੇ ਖ਼ਾਸ ਹੁਨਰ ਵਾਲੇ ਕਾਮਿਆਂ ਦੀ ਉਪਲਬਧਤਾ ਉਸ ਥਾਂ ਦਾ ਕਿਰਤ ਨਾਲ ਜੁੜਿਆ ਲਾਭ ਹੈ।"]},
"GEO-IND-001-CP003-Q036":{"h":"b1c59496","hi":["लंबे समय से स्थापित केंद्रों में वस्त्र उत्पादन जारी रहने का क्या कारण है?",["श्रमिकों का अभाव","बाज़ार तक पहुँच का अभाव","परिवहन का अभाव","उद्योगों के संकेंद्रण से मिलने वाले लाभ और समय के साथ विकसित कौशल"],"पुराने केंद्रों में आपूर्तिकर्ताओं का तंत्र, कौशल, मशीनरी सेवाएँ और बाज़ार बने रहते हैं। इनके कारण कंपनियाँ आगे भी वहाँ आकर्षित हो सकती हैं।"],"pa":["ਲੰਮੇ ਸਮੇਂ ਤੋਂ ਸਥਾਪਤ ਕੇਂਦਰਾਂ ਵਿੱਚ ਕੱਪੜਾ ਉਤਪਾਦਨ ਜਾਰੀ ਰਹਿਣ ਦਾ ਕੀ ਕਾਰਨ ਹੈ?",["ਕਾਮਿਆਂ ਦੀ ਅਣਹੋਂਦ","ਬਾਜ਼ਾਰ ਤੱਕ ਪਹੁੰਚ ਦੀ ਅਣਹੋਂਦ","ਆਵਾਜਾਈ ਦੀ ਘਾਟ","ਉਦਯੋਗਾਂ ਦੇ ਇੱਕ ਥਾਂ ਇਕੱਠੇ ਹੋਣ ਦੇ ਲਾਭ ਅਤੇ ਸਮੇਂ ਨਾਲ ਵਿਕਸਿਤ ਹੋਏ ਹੁਨਰ"],"ਪੁਰਾਣੇ ਕੇਂਦਰਾਂ ਵਿੱਚ ਸਪਲਾਇਰਾਂ ਦੇ ਤੰਤਰ, ਹੁਨਰ, ਮਸ਼ੀਨਰੀ ਸੇਵਾਵਾਂ ਅਤੇ ਬਾਜ਼ਾਰ ਬਣੇ ਰਹਿੰਦੇ ਹਨ। ਇਨ੍ਹਾਂ ਸਦਕਾ ਕੰਪਨੀਆਂ ਅੱਗੇ ਵੀ ਉੱਥੇ ਆ ਸਕਦੀਆਂ ਹਨ।"]},
"GEO-IND-001-CP003-Q037":{"h":"cfafd73b","hi":["तिरुप्पुर विशेष रूप से किस उद्योग के लिए प्रसिद्ध है?",["जूट मिलें","लौह और इस्पात","निटवियर और परिधान","पेट्रोलियम शोधन"],"तमिलनाडु का तिरुप्पुर निटवियर और परिधानों के उत्पादन के लिए भारत के सबसे प्रसिद्ध औद्योगिक संकुलों में से एक है।"],"pa":["ਤਿਰੁੱਪੁਰ ਖ਼ਾਸ ਤੌਰ 'ਤੇ ਕਿਹੜੇ ਉਦਯੋਗ ਲਈ ਮਸ਼ਹੂਰ ਹੈ?",["ਜੂਟ ਮਿੱਲਾਂ","ਲੋਹਾ ਅਤੇ ਸਟੀਲ","ਨਿਟਵੀਅਰ ਅਤੇ ਪਹਿਰਾਵੇ","ਪੈਟਰੋਲੀਅਮ ਦੀ ਸੁਧਾਈ"],"ਤਾਮਿਲਨਾਡੂ ਦਾ ਤਿਰੁੱਪੁਰ ਨਿਟਵੀਅਰ ਅਤੇ ਪਹਿਰਾਵਿਆਂ ਲਈ ਭਾਰਤ ਦੇ ਸਭ ਤੋਂ ਮਸ਼ਹੂਰ ਉਦਯੋਗਿਕ ਗੁੱਛਾਂ ਵਿੱਚੋਂ ਇੱਕ ਹੈ।"]},
"GEO-IND-001-CP003-Q038":{"h":"a7e298b1","hi":["तिरुप्पुर किस राज्य में स्थित है?",["गुजरात","पश्चिम बंगाल","पंजाब","तमिलनाडु"],"तिरुप्पुर तमिलनाडु की प्रमुख वस्त्र उद्योग पट्टी में स्थित है।"],"pa":["ਤਿਰੁੱਪੁਰ ਕਿਹੜੇ ਰਾਜ ਵਿੱਚ ਹੈ?",["ਗੁਜਰਾਤ","ਪੱਛਮੀ ਬੰਗਾਲ","ਪੰਜਾਬ","ਤਾਮਿਲਨਾਡੂ"],"ਤਿਰੁੱਪੁਰ ਤਾਮਿਲਨਾਡੂ ਦੀ ਪ੍ਰਮੁੱਖ ਕੱਪੜਾ ਉਦਯੋਗ ਪੱਟੀ ਵਿੱਚ ਪੈਂਦਾ ਹੈ।"]},
"GEO-IND-001-CP003-Q039":{"h":"c378f5b5","hi":["वस्त्र उद्योग संकुल के रूप में तिरुप्पुर के संचालन में कौन-सा कारक सहायक है?",["विशिष्ट कौशल वाले श्रमिक और आपूर्तिकर्ताओं का तंत्र","पास में लौह अयस्क","केवल कोयला खदानें","ज्वारीय ऊर्जा"],"तिरुप्पुर को परिधान कंपनियों, प्रसंस्करण इकाइयों, श्रमिकों और आपूर्तिकर्ताओं के सघन तंत्र का लाभ मिलता है।"],"pa":["ਤਿਰੁੱਪੁਰ ਨੂੰ ਕੱਪੜਾ ਉਦਯੋਗ ਦੇ ਗੁੱਛ ਵਜੋਂ ਚੱਲਣ ਵਿੱਚ ਕਿਹੜਾ ਕਾਰਕ ਮਦਦ ਕਰਦਾ ਹੈ?",["ਖ਼ਾਸ ਹੁਨਰ ਵਾਲੇ ਕਾਮੇ ਅਤੇ ਸਪਲਾਇਰਾਂ ਦੇ ਤੰਤਰ","ਨੇੜੇ ਮਿਲਦਾ ਕੱਚਾ ਲੋਹਾ","ਸਿਰਫ਼ ਕੋਲੇ ਦੀਆਂ ਖਾਣਾਂ","ਜਵਾਰ-ਭਾਟੇ ਤੋਂ ਮਿਲਦੀ ਊਰਜਾ"],"ਤਿਰੁੱਪੁਰ ਨੂੰ ਪਹਿਰਾਵਾ ਕੰਪਨੀਆਂ, ਪ੍ਰੋਸੈਸਿੰਗ ਇਕਾਈਆਂ, ਕਾਮਿਆਂ ਅਤੇ ਸਪਲਾਇਰਾਂ ਦੇ ਸੰਘਣੇ ਤੰਤਰ ਦਾ ਲਾਭ ਮਿਲਦਾ ਹੈ।"]},
"GEO-IND-001-CP003-Q040":{"h":"6347a0de","hi":["कथनों पर विचार कीजिए: I. तिरुप्पुर निटवियर के लिए प्रसिद्ध है। II. यह तमिलनाडु के वस्त्र उद्योग क्षेत्र का हिस्सा है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","I और II दोनों सही हैं","केवल II सही है","न तो I और न ही II सही है"],"दोनों कथन तिरुप्पुर के औद्योगिक भूगोल का सही वर्णन करते हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਤਿਰੁੱਪੁਰ ਨਿਟਵੀਅਰ ਲਈ ਮਸ਼ਹੂਰ ਹੈ। II. ਇਹ ਤਾਮਿਲਨਾਡੂ ਦੇ ਕੱਪੜਾ ਉਦਯੋਗ ਖੇਤਰ ਦਾ ਹਿੱਸਾ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਦੋਵੇਂ ਕਥਨ ਤਿਰੁੱਪੁਰ ਦੇ ਉਦਯੋਗਿਕ ਭੂਗੋਲ ਦਾ ਸਹੀ ਵਰਣਨ ਕਰਦੇ ਹਨ।"]},
"GEO-IND-001-CP003-Q041":{"h":"b1fbe12e","hi":["तमिलनाडु के वस्त्र उद्योग के भूगोल में कौन-सा युग्म सही सुमेलित है?",["तिरुप्पुर — जूट","तिरुप्पुर — इस्पात","तिरुप्पुर — निटवियर","तिरुप्पुर — पेट्रोलियम"],"तिरुप्पुर की विशेष पहचान निटवियर और परिधान बनाने वाले केंद्र के रूप में है।"],"pa":["ਤਾਮਿਲਨਾਡੂ ਦੇ ਕੱਪੜਾ ਉਦਯੋਗ ਦੇ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਤਿਰੁੱਪੁਰ — ਜੂਟ","ਤਿਰੁੱਪੁਰ — ਸਟੀਲ","ਤਿਰੁੱਪੁਰ — ਨਿਟਵੀਅਰ","ਤਿਰੁੱਪੁਰ — ਪੈਟਰੋਲੀਅਮ"],"ਤਿਰੁੱਪੁਰ ਦੀ ਖ਼ਾਸ ਪਛਾਣ ਨਿਟਵੀਅਰ ਅਤੇ ਪਹਿਰਾਵੇ ਬਣਾਉਣ ਨਾਲ ਜੁੜੀ ਹੈ।"]},
"GEO-IND-001-CP003-Q042":{"h":"0c95aeae","hi":["तमिलनाडु के वस्त्र उद्योग केंद्रों की कौन-सी तुलना सही है?",["दोनों जूट के केंद्र हैं","तिरुप्पुर इस्पात का केंद्र है","कोयंबटूर कोयला क्षेत्र है","कोयंबटूर कताई का प्रमुख केंद्र है, जबकि तिरुप्पुर निटवियर का प्रमुख केंद्र है"],"तमिलनाडु की वस्त्र अर्थव्यवस्था में दोनों शहरों की भूमिकाएँ अलग हैं और एक-दूसरे से जुड़ी हैं।"],"pa":["ਤਾਮਿਲਨਾਡੂ ਦੇ ਕੱਪੜਾ ਉਦਯੋਗ ਕੇਂਦਰਾਂ ਦੀ ਕਿਹੜੀ ਤੁਲਨਾ ਸਹੀ ਹੈ?",["ਦੋਵੇਂ ਜੂਟ ਦੇ ਕੇਂਦਰ ਹਨ","ਤਿਰੁੱਪੁਰ ਸਟੀਲ ਦਾ ਕੇਂਦਰ ਹੈ","ਕੋਇੰਬਟੂਰ ਕੋਲਾ ਖੇਤਰ ਹੈ","ਕੋਇੰਬਟੂਰ ਕਤਾਈ ਦਾ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰ ਹੈ, ਜਦਕਿ ਤਿਰੁੱਪੁਰ ਨਿਟਵੀਅਰ ਦਾ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰ ਹੈ"],"ਤਾਮਿਲਨਾਡੂ ਦੀ ਕੱਪੜਾ ਅਰਥਵਿਵਸਥਾ ਵਿੱਚ ਦੋਵੇਂ ਸ਼ਹਿਰ ਵੱਖੋ-ਵੱਖਰੀਆਂ ਭੂਮਿਕਾਵਾਂ ਨਿਭਾਉਂਦੇ ਹਨ ਅਤੇ ਇਹ ਭੂਮਿਕਾਵਾਂ ਆਪਸ ਵਿੱਚ ਜੁੜੀਆਂ ਹਨ।"]},
"GEO-IND-001-CP003-Q043":{"h":"093993b8","hi":["सूरत वस्त्र उद्योग की किस शाखा के लिए विशेष रूप से प्रसिद्ध है?",["संश्लेषित और मानव निर्मित रेशों के वस्त्र","केवल जूट","केवल ऊन","लौह और इस्पात"],"गुजरात का सूरत संश्लेषित वस्त्रों, बुनाई और प्रसंस्करण का प्रमुख केंद्र है।"],"pa":["ਸੂਰਤ ਕੱਪੜਾ ਉਦਯੋਗ ਦੀ ਕਿਹੜੀ ਸ਼ਾਖਾ ਲਈ ਖ਼ਾਸ ਤੌਰ 'ਤੇ ਮਸ਼ਹੂਰ ਹੈ?",["ਬਣਾਵਟੀ ਤੇ ਮਨੁੱਖ-ਨਿਰਮਿਤ ਰੇਸ਼ਿਆਂ ਦੇ ਕੱਪੜੇ","ਸਿਰਫ਼ ਜੂਟ","ਸਿਰਫ਼ ਉੱਨ","ਲੋਹਾ ਅਤੇ ਸਟੀਲ"],"ਗੁਜਰਾਤ ਦਾ ਸੂਰਤ ਬਣਾਵਟੀ ਰੇਸ਼ਿਆਂ ਦੇ ਕੱਪੜਿਆਂ, ਬੁਣਾਈ ਅਤੇ ਪ੍ਰੋਸੈਸਿੰਗ ਦਾ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰ ਹੈ।"]},
"GEO-IND-001-CP003-Q044":{"h":"3b143f87","hi":["सूरत किस राज्य में स्थित है?",["तमिलनाडु","गुजरात","पश्चिम बंगाल","पंजाब"],"सूरत गुजरात में है और पश्चिमी भारत के प्रमुख वस्त्र उद्योग केंद्रों में से एक है।"],"pa":["ਸੂਰਤ ਕਿਹੜੇ ਰਾਜ ਵਿੱਚ ਹੈ?",["ਤਾਮਿਲਨਾਡੂ","ਗੁਜਰਾਤ","ਪੱਛਮੀ ਬੰਗਾਲ","ਪੰਜਾਬ"],"ਸੂਰਤ ਗੁਜਰਾਤ ਵਿੱਚ ਹੈ ਅਤੇ ਪੱਛਮੀ ਭਾਰਤ ਦੇ ਪ੍ਰਮੁੱਖ ਕੱਪੜਾ ਉਦਯੋਗ ਕੇਂਦਰਾਂ ਵਿੱਚੋਂ ਇੱਕ ਹੈ।"]},
"GEO-IND-001-CP003-Q045":{"h":"d14f8cf6","hi":["संश्लेषित रेशों के उत्पादन को किस आपूर्तिकर्ता उद्योग से सहायता मिलती है?",["चीनी उद्योग","लौह अयस्क खनन","पेट्रोरसायन उद्योग","जूट की खेती"],"पॉलिएस्टर जैसे कई संश्लेषित रेशे पेट्रोरसायन से प्राप्त कच्चे माल से बनाए जाते हैं।"],"pa":["ਬਣਾਵਟੀ ਰੇਸ਼ੇ ਬਣਾਉਣ ਲਈ ਕਿਹੜਾ ਉਦਯੋਗ ਕੱਚਾ ਮਾਲ ਦਿੰਦਾ ਹੈ?",["ਖੰਡ ਉਦਯੋਗ","ਕੱਚੇ ਲੋਹੇ ਦੀ ਖੁਦਾਈ","ਪੈਟਰੋ-ਰਸਾਇਣ ਉਦਯੋਗ","ਜੂਟ ਦੀ ਖੇਤੀ"],"ਪਾਲੀਐਸਟਰ ਵਰਗੇ ਕਈ ਬਣਾਵਟੀ ਰੇਸ਼ੇ ਪੈਟਰੋ-ਰਸਾਇਣਾਂ ਤੋਂ ਮਿਲਦੇ ਕੱਚੇ ਮਾਲ ਨਾਲ ਬਣਾਏ ਜਾਂਦੇ ਹਨ।"]},
"GEO-IND-001-CP003-Q046":{"h":"e6301223","hi":["कथनों पर विचार कीजिए: I. सूरत संश्लेषित वस्त्रों का प्रमुख केंद्र है। II. पेट्रोरसायन से मिला कच्चा माल मानव निर्मित रेशों के उत्पादन में सहायक है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","न तो I और न ही II सही है","I और II दोनों सही हैं"],"दोनों कथन सूरत के वस्त्र उद्योग के भूगोल को संश्लेषित रेशों के उत्पादन से सही ढंग से जोड़ते हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਸੂਰਤ ਬਣਾਵਟੀ ਰੇਸ਼ਿਆਂ ਦੇ ਕੱਪੜਿਆਂ ਦਾ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰ ਹੈ। II. ਪੈਟਰੋ-ਰਸਾਇਣਾਂ ਤੋਂ ਮਿਲਿਆ ਕੱਚਾ ਮਾਲ ਮਨੁੱਖ-ਨਿਰਮਿਤ ਰੇਸ਼ੇ ਬਣਾਉਣ ਦੇ ਕੰਮ ਆਉਂਦਾ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ"],"ਦੋਵੇਂ ਕਥਨ ਸੂਰਤ ਦੇ ਕੱਪੜਾ ਉਦਯੋਗ ਦੇ ਭੂਗੋਲ ਨੂੰ ਬਣਾਵਟੀ ਰੇਸ਼ਿਆਂ ਦੇ ਉਤਪਾਦਨ ਨਾਲ ਸਹੀ ਤਰ੍ਹਾਂ ਜੋੜਦੇ ਹਨ।"]},
"GEO-IND-001-CP003-Q047":{"h":"048da213","hi":["कौन-सा युग्म सूरत के वस्त्र उद्योग की विशेषज्ञता सही दर्शाता है?",["सूरत — संश्लेषित वस्त्र","सूरत — केवल जूट","सूरत — कोकिंग कोयला","सूरत — लौह अयस्क"],"सूरत संश्लेषित वस्त्रों और उनके प्रसंस्करण का एक प्रमुख केंद्र है।"],"pa":["ਕਿਹੜਾ ਜੋੜਾ ਸੂਰਤ ਦੇ ਕੱਪੜਾ ਉਦਯੋਗ ਦੀ ਮੁਹਾਰਤ ਸਹੀ ਦਰਸਾਉਂਦਾ ਹੈ?",["ਸੂਰਤ — ਬਣਾਵਟੀ ਰੇਸ਼ਿਆਂ ਦੇ ਕੱਪੜੇ","ਸੂਰਤ — ਸਿਰਫ਼ ਜੂਟ","ਸੂਰਤ — ਕੋਕਿੰਗ ਕੋਲਾ","ਸੂਰਤ — ਕੱਚਾ ਲੋਹਾ"],"ਸੂਰਤ ਬਣਾਵਟੀ ਰੇਸ਼ਿਆਂ ਦੇ ਕੱਪੜਿਆਂ ਅਤੇ ਉਨ੍ਹਾਂ ਦੀ ਪ੍ਰੋਸੈਸਿੰਗ ਦਾ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰ ਹੈ।"]},
"GEO-IND-001-CP003-Q048":{"h":"6146d0f3","hi":["अहमदाबाद और सूरत की कौन-सी तुलना सही है?",["दोनों केवल जूट के केंद्र हैं","अहमदाबाद का ऐतिहासिक संबंध सूती वस्त्रों से है, जबकि सूरत का संश्लेषित वस्त्रों से गहरा संबंध है","सूरत पश्चिम बंगाल में है","अहमदाबाद कोयला क्षेत्र है"],"दोनों वस्त्र उद्योग के केंद्र हैं, लेकिन जिन उद्योगों से उनका सबसे गहरा पारंपरिक संबंध रहा है, वे अलग-अलग हैं।"],"pa":["ਅਹਿਮਦਾਬਾਦ ਅਤੇ ਸੂਰਤ ਦੀ ਕਿਹੜੀ ਤੁਲਨਾ ਸਹੀ ਹੈ?",["ਦੋਵੇਂ ਸਿਰਫ਼ ਜੂਟ ਦੇ ਕੇਂਦਰ ਹਨ","ਅਹਿਮਦਾਬਾਦ ਦਾ ਸੂਤੀ ਕੱਪੜੇ ਨਾਲ ਇਤਿਹਾਸਕ ਸਬੰਧ ਹੈ, ਜਦਕਿ ਸੂਰਤ ਦਾ ਬਣਾਵਟੀ ਰੇਸ਼ਿਆਂ ਦੇ ਕੱਪੜਿਆਂ ਨਾਲ ਡੂੰਘਾ ਸਬੰਧ ਹੈ","ਸੂਰਤ ਪੱਛਮੀ ਬੰਗਾਲ ਵਿੱਚ ਹੈ","ਅਹਿਮਦਾਬਾਦ ਕੋਲਾ ਖੇਤਰ ਹੈ"],"ਦੋਵੇਂ ਕੱਪੜਾ ਉਦਯੋਗ ਦੇ ਕੇਂਦਰ ਹਨ, ਪਰ ਰਵਾਇਤੀ ਤੌਰ 'ਤੇ ਦੋਵਾਂ ਦਾ ਵੱਖੋ-ਵੱਖਰੇ ਉਦਯੋਗਾਂ ਨਾਲ ਸਭ ਤੋਂ ਡੂੰਘਾ ਸਬੰਧ ਰਿਹਾ ਹੈ।"]},
"GEO-IND-001-CP003-Q049":{"h":"81db7fd2","hi":["भारत के रेशम उद्योग के लिए कौन-सा राज्य विशेष रूप से महत्वपूर्ण है?",["कर्नाटक","पंजाब","राजस्थान","हरियाणा"],"कर्नाटक भारत में रेशम के उत्पादन और प्रसंस्करण के लिए सबसे प्रसिद्ध राज्यों में से एक है।"],"pa":["ਭਾਰਤ ਦੇ ਰੇਸ਼ਮ ਉਦਯੋਗ ਲਈ ਕਿਹੜਾ ਰਾਜ ਖ਼ਾਸ ਤੌਰ 'ਤੇ ਮਹੱਤਵਪੂਰਨ ਹੈ?",["ਕਰਨਾਟਕ","ਪੰਜਾਬ","ਰਾਜਸਥਾਨ","ਹਰਿਆਣਾ"],"ਕਰਨਾਟਕ ਭਾਰਤ ਵਿੱਚ ਰੇਸ਼ਮ ਦੇ ਉਤਪਾਦਨ ਅਤੇ ਪ੍ਰੋਸੈਸਿੰਗ ਲਈ ਸਭ ਤੋਂ ਮਸ਼ਹੂਰ ਰਾਜਾਂ ਵਿੱਚੋਂ ਇੱਕ ਹੈ।"]},
"GEO-IND-001-CP003-Q050":{"h":"3fae9545","hi":["किस नगरीय क्षेत्र का कर्नाटक के रेशम उद्योग से गहरा संबंध है?",["धनबाद-झरिया","मैसूरु-बेंगलुरु क्षेत्र","खेतड़ी-जावर","डिगबोई-मोरान"],"मैसूरु-बेंगलुरु क्षेत्र कर्नाटक में रेशम उत्पादन और प्रसंस्करण का पारंपरिक केंद्र है।"],"pa":["ਕਿਸ ਸ਼ਹਿਰੀ ਖੇਤਰ ਦਾ ਕਰਨਾਟਕ ਦੇ ਰੇਸ਼ਮ ਉਦਯੋਗ ਨਾਲ ਡੂੰਘਾ ਸਬੰਧ ਹੈ?",["ਧਨਬਾਦ-ਝਰੀਆ","ਮੈਸੂਰੂ-ਬੈਂਗਲੁਰੂ ਖੇਤਰ","ਖੇਤੜੀ-ਜ਼ਾਵਰ","ਡਿਗਬੋਈ-ਮੋਰਾਨ"],"ਮੈਸੂਰੂ-ਬੈਂਗਲੁਰੂ ਖੇਤਰ ਕਰਨਾਟਕ ਵਿੱਚ ਰੇਸ਼ਮ ਉਤਪਾਦਨ ਅਤੇ ਪ੍ਰੋਸੈਸਿੰਗ ਦਾ ਰਵਾਇਤੀ ਕੇਂਦਰ ਹੈ।"]},
"GEO-IND-001-CP003-Q051":{"h":"ed2bd628","hi":["कथनों पर विचार कीजिए: I. रेशम एक प्राकृतिक रेशा है। II. कर्नाटक रेशम उत्पादन में प्रमुख राज्य है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","I और II दोनों सही हैं","न तो I और न ही II सही है"],"रेशम प्राकृतिक रेशा है और कर्नाटक लंबे समय से प्रमुख रेशम उत्पादक क्षेत्र रहा है।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਰੇਸ਼ਮ ਕੁਦਰਤੀ ਰੇਸ਼ਾ ਹੈ। II. ਕਰਨਾਟਕ ਰੇਸ਼ਮ ਉਤਪਾਦਨ ਵਿੱਚ ਪ੍ਰਮੁੱਖ ਰਾਜ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਰੇਸ਼ਮ ਕੁਦਰਤੀ ਰੇਸ਼ਾ ਹੈ ਅਤੇ ਕਰਨਾਟਕ ਲੰਮੇ ਸਮੇਂ ਤੋਂ ਰੇਸ਼ਮ ਉਤਪਾਦਨ ਵਾਲਾ ਪ੍ਰਮੁੱਖ ਖੇਤਰ ਰਿਹਾ ਹੈ।"]},
"GEO-IND-001-CP003-Q052":{"h":"4d02fba8","hi":["रेशम उद्योग के भूगोल में कौन-सा युग्म सही सुमेलित है?",["कर्नाटक — केवल जूट","पंजाब — केवल शहतूती रेशम","राजस्थान — कच्चा जूट","कर्नाटक — रेशम"],"कर्नाटक का रेशम उत्पादन और प्रसंस्करण से गहरा संबंध है।"],"pa":["ਰੇਸ਼ਮ ਉਦਯੋਗ ਦੇ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਕਰਨਾਟਕ — ਸਿਰਫ਼ ਜੂਟ","ਪੰਜਾਬ — ਸਿਰਫ਼ ਸ਼ਹਿਤੂਤੀ ਰੇਸ਼ਮ","ਰਾਜਸਥਾਨ — ਕੱਚਾ ਜੂਟ","ਕਰਨਾਟਕ — ਰੇਸ਼ਮ"],"ਕਰਨਾਟਕ ਦਾ ਰੇਸ਼ਮ ਉਤਪਾਦਨ ਅਤੇ ਪ੍ਰੋਸੈਸਿੰਗ ਨਾਲ ਡੂੰਘਾ ਸਬੰਧ ਹੈ।"]},
"GEO-IND-001-CP003-Q053":{"h":"5f8a6a4c","hi":["कौन-सा उद्योग कोयों का प्रसंस्करण करके रेशमी धागा और कपड़ा बनाता है?",["रेशमी वस्त्र उद्योग","जूट उद्योग","सीमेंट उद्योग","इस्पात उद्योग"],"रेशमी वस्त्र विनिर्माण में कोयों से प्राप्त रेशे को धागे और कपड़े में बदला जाता है।"],"pa":["ਕਿਹੜਾ ਉਦਯੋਗ ਰੇਸ਼ਮ ਦੇ ਕੀੜੇ ਦੇ ਕੋਇਆਂ ਤੋਂ ਰੇਸ਼ਮੀ ਧਾਗਾ ਅਤੇ ਕੱਪੜਾ ਬਣਾਉਂਦਾ ਹੈ?",["ਰੇਸ਼ਮੀ ਕੱਪੜਾ ਉਦਯੋਗ","ਜੂਟ ਉਦਯੋਗ","ਸੀਮਿੰਟ ਉਦਯੋਗ","ਸਟੀਲ ਉਦਯੋਗ"],"ਰੇਸ਼ਮੀ ਕੱਪੜਾ ਉਦਯੋਗ ਵਿੱਚ ਕੋਇਆਂ ਤੋਂ ਮਿਲੇ ਰੇਸ਼ੇ ਨੂੰ ਧਾਗੇ ਅਤੇ ਕੱਪੜੇ ਵਿੱਚ ਬਦਲਿਆ ਜਾਂਦਾ ਹੈ।"]},
"GEO-IND-001-CP003-Q054":{"h":"523b270c","hi":["वस्त्र उद्योग के भूगोल में कौन-सी तुलना सही है?",["दोनों केवल कोयला क्षेत्र हैं","कर्नाटक का रेशम से गहरा संबंध है, जबकि पश्चिम बंगाल का जूट से गहरा संबंध है","पश्चिम बंगाल में जूट उद्योग नहीं है","कर्नाटक केवल जूट उत्पादक राज्य है"],"दोनों राज्य अलग-अलग प्रकार के रेशों पर आधारित उद्योगों में अपनी विशेषज्ञता के लिए जाने जाते हैं।"],"pa":["ਕੱਪੜਾ ਉਦਯੋਗ ਦੇ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜੀ ਤੁਲਨਾ ਸਹੀ ਹੈ?",["ਦੋਵੇਂ ਸਿਰਫ਼ ਕੋਲਾ ਖੇਤਰ ਹਨ","ਕਰਨਾਟਕ ਦਾ ਰੇਸ਼ਮ ਨਾਲ ਡੂੰਘਾ ਸਬੰਧ ਹੈ, ਜਦਕਿ ਪੱਛਮੀ ਬੰਗਾਲ ਦਾ ਜੂਟ ਨਾਲ ਡੂੰਘਾ ਸਬੰਧ ਹੈ","ਪੱਛਮੀ ਬੰਗਾਲ ਵਿੱਚ ਜੂਟ ਉਦਯੋਗ ਨਹੀਂ ਹੈ","ਕਰਨਾਟਕ ਸਿਰਫ਼ ਜੂਟ ਉਤਪਾਦਕ ਰਾਜ ਹੈ"],"ਦੋਵੇਂ ਰਾਜ ਵੱਖੋ-ਵੱਖਰੇ ਰੇਸ਼ਿਆਂ 'ਤੇ ਆਧਾਰਿਤ ਉਦਯੋਗਾਂ ਵਿੱਚ ਆਪਣੀ ਮੁਹਾਰਤ ਲਈ ਮਸ਼ਹੂਰ ਹਨ।"]},
"GEO-IND-001-CP003-Q055":{"h":"b4394c90","hi":["लुधियाना वस्त्र उद्योग की किस शाखा के लिए विशेष रूप से प्रसिद्ध है?",["जूट मिलें","लौह और इस्पात","सीमेंट","ऊनी और होज़री उत्पाद"],"पंजाब का लुधियाना होज़री और ऊनी परिधानों का प्रमुख केंद्र है।"],"pa":["ਲੁਧਿਆਣਾ ਕੱਪੜਾ ਉਦਯੋਗ ਦੀ ਕਿਹੜੀ ਸ਼ਾਖਾ ਲਈ ਖ਼ਾਸ ਤੌਰ 'ਤੇ ਮਸ਼ਹੂਰ ਹੈ?",["ਜੂਟ ਮਿੱਲਾਂ","ਲੋਹਾ ਅਤੇ ਸਟੀਲ","ਸੀਮਿੰਟ","ਊਨੀ ਅਤੇ ਹੌਜ਼ਰੀ ਉਤਪਾਦ"],"ਪੰਜਾਬ ਦਾ ਲੁਧਿਆਣਾ ਹੌਜ਼ਰੀ ਅਤੇ ਊਨੀ ਪਹਿਰਾਵਿਆਂ ਦਾ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰ ਹੈ।"]},
"GEO-IND-001-CP003-Q056":{"h":"a5458ddb","hi":["लुधियाना किस राज्य में स्थित है?",["पंजाब","गुजरात","कर्नाटक","पश्चिम बंगाल"],"लुधियाना पंजाब का प्रमुख औद्योगिक शहर है।"],"pa":["ਲੁਧਿਆਣਾ ਕਿਹੜੇ ਰਾਜ ਵਿੱਚ ਹੈ?",["ਪੰਜਾਬ","ਗੁਜਰਾਤ","ਕਰਨਾਟਕ","ਪੱਛਮੀ ਬੰਗਾਲ"],"ਲੁਧਿਆਣਾ ਪੰਜਾਬ ਦਾ ਪ੍ਰਮੁੱਖ ਉਦਯੋਗਿਕ ਸ਼ਹਿਰ ਹੈ।"]},
"GEO-IND-001-CP003-Q057":{"h":"17f9b3d1","hi":["उत्तर भारत के किस क्षेत्र में ठंडी जलवायु और ऊन के उपयोग से जुड़ी ऊनी वस्त्र उत्पादन की पुरानी परंपरा है?",["केवल तटीय ओडिशा","पंजाब और उससे सटे उत्तर-पश्चिमी भारत के क्षेत्र","केवल सुंदरबन","केवल अंडमान द्वीपसमूह"],"उत्तर-पश्चिमी भारत में ऊनी वस्त्र और होज़री के महत्वपूर्ण केंद्र हैं। लुधियाना उनमें से एक है।"],"pa":["ਉੱਤਰੀ ਭਾਰਤ ਦੇ ਕਿਸ ਖੇਤਰ ਵਿੱਚ ਠੰਢੇ ਜਲਵਾਯੂ ਅਤੇ ਉੱਨ ਦੀ ਵਰਤੋਂ ਨਾਲ ਜੁੜੀ ਊਨੀ ਕੱਪੜਾ ਬਣਾਉਣ ਦੀ ਪੁਰਾਣੀ ਰਵਾਇਤ ਹੈ?",["ਸਿਰਫ਼ ਤੱਟੀ ਓਡੀਸ਼ਾ","ਪੰਜਾਬ ਅਤੇ ਨਾਲ ਲੱਗਦੇ ਉੱਤਰ-ਪੱਛਮੀ ਭਾਰਤ ਦੇ ਇਲਾਕੇ","ਸਿਰਫ਼ ਸੁੰਦਰਬਨ","ਸਿਰਫ਼ ਅੰਡਮਾਨ ਟਾਪੂ"],"ਉੱਤਰ-ਪੱਛਮੀ ਭਾਰਤ ਵਿੱਚ ਊਨੀ ਕੱਪੜੇ ਅਤੇ ਹੌਜ਼ਰੀ ਦੇ ਮਹੱਤਵਪੂਰਨ ਕੇਂਦਰ ਹਨ। ਲੁਧਿਆਣਾ ਉਨ੍ਹਾਂ ਵਿੱਚੋਂ ਇੱਕ ਹੈ।"]},
"GEO-IND-001-CP003-Q058":{"h":"b7518d1b","hi":["कथनों पर विचार कीजिए: I. ऊनी वस्त्रों में जंतु रेशे का उपयोग होता है। II. लुधियाना होज़री का प्रमुख केंद्र है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","I और II दोनों सही हैं","न तो I और न ही II सही है"],"ऊन जंतु रेशा है और लुधियाना होज़री तथा ऊनी वस्त्रों का प्रमुख केंद्र है।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਊਨੀ ਕੱਪੜਿਆਂ ਵਿੱਚ ਪਸ਼ੂਆਂ ਤੋਂ ਮਿਲਦਾ ਰੇਸ਼ਾ ਵਰਤਿਆ ਜਾਂਦਾ ਹੈ। II. ਲੁਧਿਆਣਾ ਹੌਜ਼ਰੀ ਦਾ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਉੱਨ ਪਸ਼ੂਆਂ ਤੋਂ ਮਿਲਦਾ ਰੇਸ਼ਾ ਹੈ ਅਤੇ ਲੁਧਿਆਣਾ ਹੌਜ਼ਰੀ ਤੇ ਊਨੀ ਕੱਪੜਿਆਂ ਦਾ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰ ਹੈ।"]},
"GEO-IND-001-CP003-Q059":{"h":"53e39a65","hi":["ऊनी वस्त्र उद्योग के भूगोल में कौन-सा युग्म सही सुमेलित है?",["लुधियाना — केवल जूट","लुधियाना — पेट्रोलियम शोधन","लुधियाना — ऐलुमिनियम प्रगलन","लुधियाना — होज़री और ऊनी वस्त्र"],"लुधियाना होज़री और ऊनी उत्पादों के लिए दूर-दूर तक प्रसिद्ध है।"],"pa":["ਊਨੀ ਕੱਪੜਾ ਉਦਯੋਗ ਦੇ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਲੁਧਿਆਣਾ — ਸਿਰਫ਼ ਜੂਟ","ਲੁਧਿਆਣਾ — ਪੈਟਰੋਲੀਅਮ ਦੀ ਸੁਧਾਈ","ਲੁਧਿਆਣਾ — ਐਲੂਮੀਨੀਅਮ ਦੀ ਗਲਾਈ","ਲੁਧਿਆਣਾ — ਹੌਜ਼ਰੀ ਅਤੇ ਊਨੀ ਕੱਪੜੇ"],"ਲੁਧਿਆਣਾ ਹੌਜ਼ਰੀ ਅਤੇ ਊਨੀ ਉਤਪਾਦਾਂ ਲਈ ਦੂਰ-ਦੂਰ ਤੱਕ ਮਸ਼ਹੂਰ ਹੈ।"]},
"GEO-IND-001-CP003-Q060":{"h":"99df2829","hi":["वस्त्र उद्योग केंद्रों की कौन-सी तुलना सही है?",["तिरुप्पुर निटवियर के लिए प्रसिद्ध है, जबकि लुधियाना होज़री और ऊनी वस्त्रों के लिए प्रसिद्ध है","दोनों जूट के केंद्र हैं","दोनों इस्पात के केंद्र हैं","लुधियाना तमिलनाडु में है"],"दोनों शहर परिधान और वस्त्र उद्योग के प्रमुख संकुल हैं, लेकिन दोनों की क्षेत्रीय विशेषज्ञताएँ अलग हैं।"],"pa":["ਕੱਪੜਾ ਉਦਯੋਗ ਕੇਂਦਰਾਂ ਦੀ ਕਿਹੜੀ ਤੁਲਨਾ ਸਹੀ ਹੈ?",["ਤਿਰੁੱਪੁਰ ਨਿਟਵੀਅਰ ਲਈ ਮਸ਼ਹੂਰ ਹੈ, ਜਦਕਿ ਲੁਧਿਆਣਾ ਹੌਜ਼ਰੀ ਅਤੇ ਊਨੀ ਕੱਪੜਿਆਂ ਲਈ ਮਸ਼ਹੂਰ ਹੈ","ਦੋਵੇਂ ਜੂਟ ਦੇ ਕੇਂਦਰ ਹਨ","ਦੋਵੇਂ ਸਟੀਲ ਦੇ ਕੇਂਦਰ ਹਨ","ਲੁਧਿਆਣਾ ਤਾਮਿਲਨਾਡੂ ਵਿੱਚ ਹੈ"],"ਦੋਵੇਂ ਸ਼ਹਿਰ ਪਹਿਰਾਵਾ ਅਤੇ ਕੱਪੜਾ ਉਦਯੋਗ ਦੇ ਪ੍ਰਮੁੱਖ ਗੁੱਛ ਹਨ, ਪਰ ਦੋਵਾਂ ਦੀ ਖੇਤਰੀ ਮੁਹਾਰਤ ਵੱਖਰੀ ਹੈ।"]},
"GEO-IND-001-CP004-Q001":{"h":"feff656b","hi":["भारत के चीनी उद्योग का मुख्य कच्चा माल कौन-सी फसल है?",["गन्ना","कपास","जूट","चाय"],"गन्ने के प्रसंस्करण से चीनी बनती है। इसीलिए चीनी उद्योग कृषि आधारित है।"],"pa":["ਭਾਰਤ ਦੇ ਖੰਡ ਉਦਯੋਗ ਦਾ ਮੁੱਖ ਕੱਚਾ ਮਾਲ ਕਿਹੜੀ ਫ਼ਸਲ ਹੈ?",["ਗੰਨਾ","ਕਪਾਹ","ਜੂਟ","ਚਾਹ"],"ਗੰਨੇ ਦੀ ਪ੍ਰੋਸੈਸਿੰਗ ਨਾਲ ਖੰਡ ਬਣਦੀ ਹੈ। ਇਸ ਕਰਕੇ ਖੰਡ ਉਦਯੋਗ ਖੇਤੀ-ਆਧਾਰਿਤ ਹੈ।"]},
"GEO-IND-001-CP004-Q002":{"h":"b22f2cc8","hi":["चीनी मिलें प्रायः गन्ना उत्पादक क्षेत्रों के निकट क्यों लगाई जाती हैं?",["गन्ना एक खनिज है","गन्ना भारी होता है और कटाई के बाद उसमें सुक्रोज़ घटता है","मिलों को सिर्फ़ लौह अयस्क चाहिए","गन्ने को ढोना बिल्कुल संभव नहीं है"],"कटाई के तुरंत बाद पेराई करने से सुक्रोज़ की हानि कम होती है। मिल पास हो तो इस भारी फसल को कम दूरी तक ढोना पड़ता है।"],"pa":["ਖੰਡ ਮਿੱਲਾਂ ਆਮ ਤੌਰ 'ਤੇ ਗੰਨਾ ਉਗਾਉਣ ਵਾਲੇ ਇਲਾਕਿਆਂ ਨੇੜੇ ਕਿਉਂ ਲੱਗਦੀਆਂ ਹਨ?",["ਗੰਨਾ ਇੱਕ ਖਣਿਜ ਹੈ","ਗੰਨਾ ਭਾਰਾ ਹੁੰਦਾ ਹੈ ਅਤੇ ਵਾਢੀ ਪਿੱਛੋਂ ਉਸ ਵਿੱਚ ਸੁਕਰੋਜ਼ ਘਟਦਾ ਹੈ","ਮਿੱਲਾਂ ਨੂੰ ਸਿਰਫ਼ ਕੱਚਾ ਲੋਹਾ ਚਾਹੀਦਾ ਹੈ","ਗੰਨੇ ਨੂੰ ਬਿਲਕੁਲ ਢੋਇਆ ਨਹੀਂ ਜਾ ਸਕਦਾ"],"ਗੰਨੇ ਦੀ ਵਾਢੀ ਤੋਂ ਛੇਤੀ ਬਾਅਦ ਪਿੜਾਈ ਕਰਨ ਨਾਲ ਸੁਕਰੋਜ਼ ਦੀ ਹਾਨੀ ਘਟਦੀ ਹੈ। ਮਿੱਲ ਨੇੜੇ ਹੋਵੇ ਤਾਂ ਇਸ ਭਾਰੀ ਫ਼ਸਲ ਨੂੰ ਘੱਟ ਦੂਰੀ ਤੱਕ ਢੋਣਾ ਪੈਂਦਾ ਹੈ।"]},
"GEO-IND-001-CP004-Q003":{"h":"58c617d8","hi":["कथनों पर विचार कीजिए: I. चीनी उद्योग कृषि आधारित है। II. गन्ने के जल्दी खराब होने का असर मिल की अवस्थिति पर पड़ता है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","I और II दोनों सही हैं","न तो I और न ही II सही है"],"यह उद्योग एक कृषि फसल पर निर्भर है। कटाई के बाद गन्ने की गुणवत्ता गिरती है, इसलिए मिलें प्रायः गन्ना उत्पादक क्षेत्रों के पास लगती हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਖੰਡ ਉਦਯੋਗ ਖੇਤੀ-ਆਧਾਰਿਤ ਹੈ। II. ਗੰਨੇ ਦੇ ਛੇਤੀ ਖ਼ਰਾਬ ਹੋਣ ਦਾ ਅਸਰ ਮਿੱਲ ਦੀ ਥਾਂ 'ਤੇ ਪੈਂਦਾ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਇਹ ਉਦਯੋਗ ਇੱਕ ਖੇਤੀ ਫ਼ਸਲ 'ਤੇ ਨਿਰਭਰ ਹੈ। ਵਾਢੀ ਤੋਂ ਬਾਅਦ ਗੰਨੇ ਦੀ ਗੁਣਵੱਤਾ ਘਟਦੀ ਹੈ, ਇਸ ਲਈ ਮਿੱਲਾਂ ਗੰਨੇ ਦੇ ਸਰੋਤ ਦੇ ਨੇੜੇ ਲਾਉਣ ਨੂੰ ਤਰਜੀਹ ਦਿੱਤੀ ਜਾਂਦੀ ਹੈ।"]},
"GEO-IND-001-CP004-Q004":{"h":"23f46404","hi":["गन्ना उत्पादक पट्टी में चीनी मिल लगाने का सबसे सीधा कारण क्या है?",["लौह अयस्क तक पहुँच","केवल पत्तन तक पहुँच","ज्वारीय परास","कच्चे माल की निकटता"],"चीनी मिल की अवस्थिति तय करने में कच्चे माल के लिहाज़ से गन्ने की आपूर्ति सबसे महत्वपूर्ण है।"],"pa":["ਗੰਨਾ ਉਗਾਉਣ ਵਾਲੀ ਪੱਟੀ ਵਿੱਚ ਖੰਡ ਮਿੱਲ ਲਾਉਣ ਦਾ ਸਭ ਤੋਂ ਸਿੱਧਾ ਕਾਰਨ ਕੀ ਹੈ?",["ਕੱਚੇ ਲੋਹੇ ਤੱਕ ਪਹੁੰਚ","ਸਿਰਫ਼ ਬੰਦਰਗਾਹ ਤੱਕ ਪਹੁੰਚ","ਜਵਾਰ-ਭਾਟਾ ਅੰਤਰ","ਕੱਚੇ ਮਾਲ ਦੀ ਨੇੜਤਾ"],"ਖੰਡ ਮਿੱਲ ਦੀ ਥਾਂ ਚੁਣਨ ਵੇਲੇ ਕੱਚੇ ਮਾਲ ਪੱਖੋਂ ਗੰਨੇ ਦੀ ਸਪਲਾਈ ਸਭ ਤੋਂ ਅਹਿਮ ਹੈ।"]},
"GEO-IND-001-CP004-Q005":{"h":"93554481","hi":["चीनी उद्योग के भूगोल में कौन-सा युग्म सही सुमेलित है?",["चीनी मिल — गन्ना उत्पादक पट्टी","चीनी मिल — लौह अयस्क पट्टी","चीनी मिल — यूरेनियम पट्टी","चीनी मिल — पेट्रोलियम क्षेत्र"],"चीनी मिलें आसपास के गन्ना उत्पादक क्षेत्रों पर सीधे निर्भर हैं।"],"pa":["ਖੰਡ ਉਦਯੋਗ ਦੇ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਖੰਡ ਮਿੱਲ — ਗੰਨੇ ਦੀ ਪੱਟੀ","ਖੰਡ ਮਿੱਲ — ਕੱਚੇ ਲੋਹੇ ਦੀ ਪੱਟੀ","ਖੰਡ ਮਿੱਲ — ਯੂਰੇਨੀਅਮ ਪੱਟੀ","ਖੰਡ ਮਿੱਲ — ਪੈਟਰੋਲੀਅਮ ਖੇਤਰ"],"ਖੰਡ ਮਿੱਲਾਂ ਆਲੇ-ਦੁਆਲੇ ਦੇ ਗੰਨਾ ਉਗਾਉਣ ਵਾਲੇ ਇਲਾਕਿਆਂ 'ਤੇ ਸਿੱਧੀਆਂ ਨਿਰਭਰ ਹਨ।"]},
"GEO-IND-001-CP004-Q006":{"h":"630d83d4","hi":["एक कारखाना ताज़ा काटे गए गन्ने की पेराई करके दानेदार चीनी बनाता है। यह कौन-सा उद्योग है?",["जूट उद्योग","चीनी उद्योग","इस्पात उद्योग","सीमेंट उद्योग"],"गन्ने की पेराई और उसके रस को परिष्कृत करके चीनी बनाना इस उद्योग की बुनियादी प्रक्रियाएँ हैं।"],"pa":["ਇੱਕ ਕਾਰਖ਼ਾਨਾ ਤਾਜ਼ੇ ਵੱਢੇ ਗੰਨੇ ਦੀ ਪਿੜਾਈ ਕਰਕੇ ਦਾਣੇਦਾਰ ਖੰਡ ਬਣਾਉਂਦਾ ਹੈ। ਇਹ ਕਿਹੜਾ ਉਦਯੋਗ ਹੈ?",["ਜੂਟ ਉਦਯੋਗ","ਖੰਡ ਉਦਯੋਗ","ਸਟੀਲ ਉਦਯੋਗ","ਸੀਮਿੰਟ ਉਦਯੋਗ"],"ਗੰਨੇ ਦੀ ਪਿੜਾਈ ਕਰਨੀ ਅਤੇ ਰਸ ਨੂੰ ਸੋਧ ਕੇ ਖੰਡ ਬਣਾਉਣੀ ਖੰਡ ਉਦਯੋਗ ਦੀਆਂ ਬੁਨਿਆਦੀ ਪ੍ਰਕਿਰਿਆਵਾਂ ਹਨ।"]},
"GEO-IND-001-CP004-Q007":{"h":"4437640e","hi":["उत्तर भारत का कौन-सा राज्य गन्ने और चीनी का प्रमुख उत्पादक है?",["राजस्थान","उत्तर प्रदेश","असम","ओडिशा"],"उत्तर प्रदेश में गन्ने की खेती की एक बड़ी पट्टी है और वहाँ कई चीनी मिलें हैं।"],"pa":["ਉੱਤਰੀ ਭਾਰਤ ਦਾ ਕਿਹੜਾ ਰਾਜ ਗੰਨੇ ਅਤੇ ਖੰਡ ਦਾ ਪ੍ਰਮੁੱਖ ਉਤਪਾਦਕ ਹੈ?",["ਰਾਜਸਥਾਨ","ਉੱਤਰ ਪ੍ਰਦੇਸ਼","ਅਸਾਮ","ਓਡੀਸ਼ਾ"],"ਉੱਤਰ ਪ੍ਰਦੇਸ਼ ਵਿੱਚ ਗੰਨਾ ਉਗਾਉਣ ਵਾਲੀ ਵੱਡੀ ਪੱਟੀ ਅਤੇ ਕਈ ਖੰਡ ਮਿੱਲਾਂ ਹਨ।"]},
"GEO-IND-001-CP004-Q008":{"h":"294b87f0","hi":["उत्तर प्रदेश का कौन-सा क्षेत्र गन्ने की खेती और चीनी मिलों के लिए जाना जाता है?",["थार मरुस्थल","छोटानागपुर पठार","पश्चिमी उत्तर प्रदेश","कोंकण तट"],"पश्चिमी उत्तर प्रदेश में व्यापक रूप से गन्ना उगाया जाता है और चीनी मिलों का तंत्र लंबे समय से स्थापित है।"],"pa":["ਉੱਤਰ ਪ੍ਰਦੇਸ਼ ਦਾ ਕਿਹੜਾ ਇਲਾਕਾ ਗੰਨੇ ਦੀ ਖੇਤੀ ਅਤੇ ਖੰਡ ਮਿੱਲਾਂ ਲਈ ਜਾਣਿਆ ਜਾਂਦਾ ਹੈ?",["ਥਾਰ ਦਾ ਮਾਰੂਥਲ","ਛੋਟਾਨਾਗਪੁਰ ਦਾ ਪਠਾਰ","ਪੱਛਮੀ ਉੱਤਰ ਪ੍ਰਦੇਸ਼","ਕੋਂਕਣ ਤੱਟ"],"ਪੱਛਮੀ ਉੱਤਰ ਪ੍ਰਦੇਸ਼ ਵਿੱਚ ਵੱਡੇ ਪੱਧਰ 'ਤੇ ਗੰਨਾ ਉਗਾਇਆ ਜਾਂਦਾ ਹੈ ਅਤੇ ਖੰਡ ਮਿੱਲਾਂ ਦਾ ਜਾਲ ਲੰਮੇ ਸਮੇਂ ਤੋਂ ਸਥਾਪਤ ਹੈ।"]},
"GEO-IND-001-CP004-Q009":{"h":"23777e8a","hi":["कथनों पर विचार कीजिए: I. उत्तर प्रदेश में चीनी उद्योग बड़े पैमाने पर विकसित है। II. यह उद्योग आसपास के गन्ना उत्पादक क्षेत्रों से जुड़ा है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","न तो I और न ही II सही है","I और II दोनों सही हैं"],"राज्य में गन्ने की खेती की विस्तृत पट्टी के कारण वहाँ चीनी मिलों का घना तंत्र विकसित हुआ है।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਉੱਤਰ ਪ੍ਰਦੇਸ਼ ਵਿੱਚ ਖੰਡ ਉਦਯੋਗ ਵੱਡੇ ਪੱਧਰ 'ਤੇ ਵਿਕਸਿਤ ਹੈ। II. ਇਹ ਉਦਯੋਗ ਨੇੜਲੇ ਗੰਨਾ ਉਗਾਉਣ ਵਾਲੇ ਇਲਾਕਿਆਂ ਨਾਲ ਜੁੜਿਆ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ"],"ਰਾਜ ਵਿੱਚ ਗੰਨੇ ਦੀ ਖੇਤੀ ਦੀ ਵੱਡੀ ਪੱਟੀ ਹੋਣ ਕਰਕੇ ਖੰਡ ਮਿੱਲਾਂ ਦਾ ਸੰਘਣਾ ਜਾਲ ਵਿਕਸਿਤ ਹੋਇਆ ਹੈ।"]},
"GEO-IND-001-CP004-Q010":{"h":"b15a4137","hi":["चीनी उद्योग के भूगोल में कौन-सा युग्म सही सुमेलित है?",["पश्चिमी उत्तर प्रदेश — गन्ना और चीनी मिलें","पश्चिमी उत्तर प्रदेश — केवल जूट","पश्चिमी उत्तर प्रदेश — केवल पेट्रोलियम","पश्चिमी उत्तर प्रदेश — केवल लौह अयस्क"],"पश्चिमी उत्तर प्रदेश भारत में गन्ने की खेती और चीनी उत्पादन के पारंपरिक क्षेत्रों में से एक है।"],"pa":["ਖੰਡ ਉਦਯੋਗ ਦੇ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਪੱਛਮੀ ਉੱਤਰ ਪ੍ਰਦੇਸ਼ — ਗੰਨਾ ਅਤੇ ਖੰਡ ਮਿੱਲਾਂ","ਪੱਛਮੀ ਉੱਤਰ ਪ੍ਰਦੇਸ਼ — ਸਿਰਫ਼ ਜੂਟ","ਪੱਛਮੀ ਉੱਤਰ ਪ੍ਰਦੇਸ਼ — ਸਿਰਫ਼ ਪੈਟਰੋਲੀਅਮ","ਪੱਛਮੀ ਉੱਤਰ ਪ੍ਰਦੇਸ਼ — ਸਿਰਫ਼ ਕੱਚਾ ਲੋਹਾ"],"ਪੱਛਮੀ ਉੱਤਰ ਪ੍ਰਦੇਸ਼ ਭਾਰਤ ਵਿੱਚ ਗੰਨੇ ਦੀ ਖੇਤੀ ਅਤੇ ਖੰਡ ਦੇ ਉਤਪਾਦਨ ਦੇ ਰਵਾਇਤੀ ਖੇਤਰਾਂ ਵਿੱਚੋਂ ਇੱਕ ਹੈ।"]},
"GEO-IND-001-CP004-Q011":{"h":"664ebb51","hi":["पश्चिमी उत्तर प्रदेश में चीनी उद्योग व्यापक रूप से क्यों विकसित हुआ है?",["क्षेत्र में बॉक्साइट की प्रमुख खदानें हैं","गन्ने की भरपूर आपूर्ति, सिंचाई, श्रम और बाज़ार उपलब्ध हैं","यह केवल पत्तनों पर निर्भर है","यहाँ खेती नहीं होती"],"इस क्षेत्र में गन्ने की खेती के साथ परिवहन, श्रम और बाज़ार की ऐसी सुविधाएँ हैं जो चीनी मिलों के लिए अनुकूल हैं।"],"pa":["ਪੱਛਮੀ ਉੱਤਰ ਪ੍ਰਦੇਸ਼ ਵਿੱਚ ਖੰਡ ਉਦਯੋਗ ਵੱਡੇ ਪੱਧਰ 'ਤੇ ਕਿਉਂ ਫੈਲਿਆ ਹੈ?",["ਇਲਾਕੇ ਵਿੱਚ ਬਾਕਸਾਈਟ ਦੀਆਂ ਪ੍ਰਮੁੱਖ ਖਾਣਾਂ ਹਨ","ਗੰਨੇ ਦੀ ਭਰਪੂਰ ਸਪਲਾਈ, ਸਿੰਜਾਈ, ਕਾਮੇ ਅਤੇ ਬਾਜ਼ਾਰਾਂ ਤੱਕ ਪਹੁੰਚ ਹੈ","ਇਹ ਸਿਰਫ਼ ਬੰਦਰਗਾਹਾਂ 'ਤੇ ਨਿਰਭਰ ਹੈ","ਇੱਥੇ ਖੇਤੀ ਨਹੀਂ ਹੁੰਦੀ"],"ਇਸ ਇਲਾਕੇ ਵਿੱਚ ਗੰਨੇ ਦੀ ਖੇਤੀ ਦੇ ਨਾਲ ਆਵਾਜਾਈ, ਕਾਮਿਆਂ ਅਤੇ ਬਾਜ਼ਾਰਾਂ ਦੀਆਂ ਅਜਿਹੀਆਂ ਸਹੂਲਤਾਂ ਹਨ ਜੋ ਖੰਡ ਮਿੱਲਾਂ ਲਈ ਅਨੁਕੂਲ ਹਨ।"]},
"GEO-IND-001-CP004-Q012":{"h":"3565995b","hi":["एक मानचित्र में ऊपरी गंगा के मैदान में चीनी मिलों की सघन पट्टी दिखाई गई है। कौन-सा राज्य सबसे उपयुक्त उत्तर है?",["केरल","गोवा","उत्तर प्रदेश","असम"],"ऊपरी गंगा का मैदान, विशेषकर पश्चिमी उत्तर प्रदेश, गन्ने की खेती और चीनी मिलों की प्रमुख पट्टी है।"],"pa":["ਇੱਕ ਨਕਸ਼ੇ ਵਿੱਚ ਗੰਗਾ ਦੇ ਉੱਪਰਲੇ ਮੈਦਾਨ ਵਿੱਚ ਖੰਡ ਮਿੱਲਾਂ ਦੀ ਸੰਘਣੀ ਪੱਟੀ ਦਿਖਾਈ ਗਈ ਹੈ। ਕਿਹੜਾ ਰਾਜ ਸਭ ਤੋਂ ਢੁੱਕਵਾਂ ਉੱਤਰ ਹੈ?",["ਕੇਰਲ","ਗੋਆ","ਉੱਤਰ ਪ੍ਰਦੇਸ਼","ਅਸਾਮ"],"ਗੰਗਾ ਦੇ ਉੱਪਰਲੇ ਮੈਦਾਨ ਵਿੱਚ, ਖ਼ਾਸ ਕਰਕੇ ਪੱਛਮੀ ਉੱਤਰ ਪ੍ਰਦੇਸ਼ ਵਿੱਚ, ਗੰਨੇ ਦੀ ਖੇਤੀ ਅਤੇ ਖੰਡ ਮਿੱਲਾਂ ਦੀ ਪ੍ਰਮੁੱਖ ਪੱਟੀ ਹੈ।"]},
"GEO-IND-001-CP004-Q013":{"h":"139ae077","hi":["पश्चिमी भारत का कौन-सा राज्य सहकारी चीनी मिलों के लिए विशेष रूप से प्रसिद्ध है?",["पंजाब","असम","महाराष्ट्र","झारखंड"],"महाराष्ट्र में गन्ना उत्पादक क्षेत्रों से जुड़ी सहकारी चीनी मिलों की सुदृढ़ परंपरा है।"],"pa":["ਪੱਛਮੀ ਭਾਰਤ ਦਾ ਕਿਹੜਾ ਰਾਜ ਸਹਿਕਾਰੀ ਖੰਡ ਮਿੱਲਾਂ ਲਈ ਖ਼ਾਸ ਤੌਰ 'ਤੇ ਮਸ਼ਹੂਰ ਹੈ?",["ਪੰਜਾਬ","ਅਸਾਮ","ਮਹਾਰਾਸ਼ਟਰ","ਝਾਰਖੰਡ"],"ਮਹਾਰਾਸ਼ਟਰ ਵਿੱਚ ਗੰਨਾ ਉਗਾਉਣ ਵਾਲੇ ਇਲਾਕਿਆਂ ਨਾਲ ਜੁੜੀਆਂ ਸਹਿਕਾਰੀ ਖੰਡ ਮਿੱਲਾਂ ਦੀ ਮਜ਼ਬੂਤ ਰਵਾਇਤ ਹੈ।"]},
"GEO-IND-001-CP004-Q014":{"h":"6caed717","hi":["महाराष्ट्र में सहकारी चीनी मिलें महत्वपूर्ण क्यों हो गईं?",["गन्ना एक खनिज है","मिलों का स्वामित्व केवल सरकार के पास हो सकता है","सहकारी संस्थाओं को किसानों की आवश्यकता नहीं होती","गन्ना उत्पादक मिलकर प्रसंस्करण इकाइयों के मालिक बन सकते थे और उन्हें सहारा दे सकते थे"],"सहकारी स्वामित्व से उत्पादक मिलकर प्रसंस्करण की व्यवस्था कर पाए और उद्यम में हिस्सेदार बने।"],"pa":["ਮਹਾਰਾਸ਼ਟਰ ਵਿੱਚ ਸਹਿਕਾਰੀ ਖੰਡ ਮਿੱਲਾਂ ਦੀ ਮਹੱਤਤਾ ਕਿਉਂ ਵਧੀ?",["ਗੰਨਾ ਇੱਕ ਖਣਿਜ ਹੈ","ਸਿਰਫ਼ ਸਰਕਾਰ ਹੀ ਮਿੱਲਾਂ ਦੀ ਮਾਲਕ ਹੋ ਸਕਦੀ ਹੈ","ਸਹਿਕਾਰੀ ਸੰਸਥਾਵਾਂ ਨੂੰ ਕਿਸਾਨਾਂ ਦੀ ਲੋੜ ਨਹੀਂ ਹੁੰਦੀ","ਗੰਨਾ ਉਤਪਾਦਕ ਰਲ ਕੇ ਪ੍ਰੋਸੈਸਿੰਗ ਇਕਾਈਆਂ ਦੇ ਮਾਲਕ ਬਣ ਸਕਦੇ ਅਤੇ ਉਨ੍ਹਾਂ ਨੂੰ ਸਹਾਰਾ ਦੇ ਸਕਦੇ ਸਨ"],"ਸਹਿਕਾਰੀ ਮਲਕੀਅਤ ਸਦਕਾ ਉਤਪਾਦਕ ਰਲ ਕੇ ਪ੍ਰੋਸੈਸਿੰਗ ਦਾ ਪ੍ਰਬੰਧ ਕਰ ਸਕੇ ਅਤੇ ਉੱਦਮ ਵਿੱਚ ਹਿੱਸੇਦਾਰ ਬਣੇ।"]},
"GEO-IND-001-CP004-Q015":{"h":"07db0301","hi":["कथनों पर विचार कीजिए: I. महाराष्ट्र चीनी उत्पादन में प्रमुख राज्य है। II. उसके चीनी उद्योग में सहकारी स्वामित्व की महत्वपूर्ण भूमिका रही है। कौन-सा/से कथन सही है/हैं?",["I और II दोनों सही हैं","केवल I सही है","केवल II सही है","न तो I और न ही II सही है"],"महाराष्ट्र में गन्ना प्रसंस्करण का बड़ा क्षेत्र और सहकारी परंपरा, दोनों औद्योगिक भूगोल के स्थापित तथ्य हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਮਹਾਰਾਸ਼ਟਰ ਖੰਡ ਉਤਪਾਦਨ ਵਿੱਚ ਪ੍ਰਮੁੱਖ ਰਾਜ ਹੈ। II. ਇਸ ਦੇ ਖੰਡ ਉਦਯੋਗ ਵਿੱਚ ਸਹਿਕਾਰੀ ਮਲਕੀਅਤ ਦੀ ਅਹਿਮ ਭੂਮਿਕਾ ਰਹੀ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਰਾਜ ਵਿੱਚ ਗੰਨੇ ਦੀ ਪ੍ਰੋਸੈਸਿੰਗ ਦਾ ਵੱਡਾ ਖੇਤਰ ਅਤੇ ਸਹਿਕਾਰੀ ਰਵਾਇਤ, ਦੋਵੇਂ ਉਦਯੋਗਿਕ ਭੂਗੋਲ ਦੇ ਸਥਾਪਤ ਤੱਥ ਹਨ।"]},
"GEO-IND-001-CP004-Q016":{"h":"ef055f9c","hi":["चीनी उद्योग के स्वामित्व के भूगोल में कौन-सा युग्म सही सुमेलित है?",["महाराष्ट्र — केवल जूट मिलें","महाराष्ट्र — सहकारी चीनी मिलें","महाराष्ट्र — चीनी उद्योग का अभाव","महाराष्ट्र — यूरेनियम आधारित चीनी"],"महाराष्ट्र में चीनी उत्पादन से सहकारी संस्थाओं का गहरा संबंध है।"],"pa":["ਖੰਡ ਉਦਯੋਗ ਦੀ ਮਲਕੀਅਤ ਦੇ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਮਹਾਰਾਸ਼ਟਰ — ਸਿਰਫ਼ ਜੂਟ ਮਿੱਲਾਂ","ਮਹਾਰਾਸ਼ਟਰ — ਸਹਿਕਾਰੀ ਖੰਡ ਮਿੱਲਾਂ","ਮਹਾਰਾਸ਼ਟਰ — ਖੰਡ ਉਦਯੋਗ ਦੀ ਅਣਹੋਂਦ","ਮਹਾਰਾਸ਼ਟਰ — ਯੂਰੇਨੀਅਮ-ਆਧਾਰਿਤ ਖੰਡ"],"ਮਹਾਰਾਸ਼ਟਰ ਦਾ ਖੰਡ ਉਤਪਾਦਨ ਸਹਿਕਾਰੀ ਸੰਸਥਾਵਾਂ ਨਾਲ ਨੇੜਿਓਂ ਜੁੜਿਆ ਹੈ।"]},
"GEO-IND-001-CP004-Q017":{"h":"252bf407","hi":["जब गन्ना उत्पादक मिलकर चीनी मिल के मालिक होते हैं, तो यह स्वामित्व के किस प्रकार का उदाहरण है?",["केवल सार्वजनिक क्षेत्रक","केवल निजी क्षेत्रक","सहकारी क्षेत्रक","केवल संयुक्त क्षेत्रक"],"यदि कोई मिल उत्पादकों के स्वामित्व में है और सहकारी समिति के ज़रिए संगठित है, तो वह सहकारी क्षेत्रक में आती है।"],"pa":["ਜਦੋਂ ਗੰਨਾ ਉਤਪਾਦਕ ਰਲ ਕੇ ਕਿਸੇ ਖੰਡ ਮਿੱਲ ਦੇ ਮਾਲਕ ਹੁੰਦੇ ਹਨ, ਤਾਂ ਇਹ ਕਿਸ ਕਿਸਮ ਦੀ ਮਲਕੀਅਤ ਹੈ?",["ਸਿਰਫ਼ ਜਨਤਕ ਖੇਤਰ","ਸਿਰਫ਼ ਨਿੱਜੀ ਖੇਤਰ","ਸਹਿਕਾਰੀ ਖੇਤਰ","ਸਿਰਫ਼ ਸਾਂਝਾ ਖੇਤਰ"],"ਜੇ ਕਿਸੇ ਮਿੱਲ ਦੀ ਮਲਕੀਅਤ ਉਤਪਾਦਕਾਂ ਕੋਲ ਹੋਵੇ ਅਤੇ ਉਸ ਦਾ ਪ੍ਰਬੰਧ ਸਹਿਕਾਰੀ ਸਭਾ ਰਾਹੀਂ ਹੁੰਦਾ ਹੋਵੇ, ਤਾਂ ਉਹ ਸਹਿਕਾਰੀ ਖੇਤਰ ਵਿੱਚ ਆਉਂਦੀ ਹੈ।"]},
"GEO-IND-001-CP004-Q018":{"h":"45143dcf","hi":["भारत के चीनी उद्योग के भूगोल में कौन-सी तुलना सही है?",["दोनों केवल जूट उत्पादक क्षेत्र हैं","महाराष्ट्र में गन्ने की खेती नहीं होती","उत्तर प्रदेश में चीनी मिलें नहीं हैं","उत्तर प्रदेश में उत्तर की प्रमुख पट्टी है, जबकि महाराष्ट्र में पश्चिम की प्रमुख सहकारी पट्टी है"],"दोनों राज्यों में चीनी उद्योग सघन है, लेकिन दोनों अलग-अलग क्षेत्रों में हैं।"],"pa":["ਭਾਰਤ ਦੇ ਖੰਡ ਉਦਯੋਗ ਦੇ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜੀ ਤੁਲਨਾ ਸਹੀ ਹੈ?",["ਦੋਵੇਂ ਸਿਰਫ਼ ਜੂਟ ਵਾਲੇ ਖੇਤਰ ਹਨ","ਮਹਾਰਾਸ਼ਟਰ ਵਿੱਚ ਗੰਨੇ ਦੀ ਖੇਤੀ ਨਹੀਂ ਹੁੰਦੀ","ਉੱਤਰ ਪ੍ਰਦੇਸ਼ ਵਿੱਚ ਖੰਡ ਮਿੱਲਾਂ ਨਹੀਂ ਹਨ","ਉੱਤਰ ਪ੍ਰਦੇਸ਼ ਵਿੱਚ ਉੱਤਰ ਦੀ ਪ੍ਰਮੁੱਖ ਪੱਟੀ ਹੈ, ਜਦਕਿ ਮਹਾਰਾਸ਼ਟਰ ਵਿੱਚ ਪੱਛਮ ਦੀ ਪ੍ਰਮੁੱਖ ਸਹਿਕਾਰੀ ਪੱਟੀ ਹੈ"],"ਦੋਵੇਂ ਰਾਜ ਖੰਡ ਉਦਯੋਗ ਦੇ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰ ਹਨ, ਪਰ ਵੱਖੋ-ਵੱਖਰੇ ਇਲਾਕਿਆਂ ਵਿੱਚ ਹਨ।"]},
"GEO-IND-001-CP004-Q019":{"h":"6dbcfc02","hi":["कई खाद्य प्रसंस्करण उद्योग कृषि क्षेत्रों के पास क्यों लगाए जाते हैं?",["ताज़े और भारी कच्चे माल का स्रोत के पास जल्दी प्रसंस्करण हो सकता है","उन्हें लौह अयस्क की आवश्यकता होती है","वे कृषि से प्राप्त सामग्री का उपयोग नहीं करते","केवल पत्तनों का महत्व है"],"कच्चा माल जल्दी खराब होता हो, भारी हो या किसी खास मौसम में मिलता हो, तो खेतों की निकटता अवस्थिति का महत्वपूर्ण कारक बन सकती है।"],"pa":["ਕਈ ਖ਼ੁਰਾਕੀ ਪ੍ਰੋਸੈਸਿੰਗ ਉਦਯੋਗ ਖੇਤੀ ਵਾਲੇ ਇਲਾਕਿਆਂ ਦੇ ਨੇੜੇ ਕਿਉਂ ਲੱਗਦੇ ਹਨ?",["ਤਾਜ਼ਾ ਅਤੇ ਭਾਰਾ ਕੱਚਾ ਮਾਲ ਸਰੋਤ ਕੋਲ ਛੇਤੀ ਪ੍ਰੋਸੈਸ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ","ਉਨ੍ਹਾਂ ਨੂੰ ਕੱਚਾ ਲੋਹਾ ਚਾਹੀਦਾ ਹੈ","ਉਹ ਖੇਤੀ ਤੋਂ ਮਿਲੀ ਸਮੱਗਰੀ ਨਹੀਂ ਵਰਤਦੇ","ਸਿਰਫ਼ ਬੰਦਰਗਾਹਾਂ ਦਾ ਮਹੱਤਵ ਹੈ"],"ਜੇ ਕੱਚਾ ਮਾਲ ਛੇਤੀ ਖ਼ਰਾਬ ਹੁੰਦਾ ਹੋਵੇ, ਭਾਰਾ ਹੋਵੇ ਜਾਂ ਕਿਸੇ ਖ਼ਾਸ ਮੌਸਮ ਵਿੱਚ ਮਿਲਦਾ ਹੋਵੇ, ਤਾਂ ਖੇਤਾਂ ਦੀ ਨੇੜਤਾ ਥਾਂ ਦੀ ਚੋਣ ਲਈ ਅਹਿਮ ਹੋ ਸਕਦੀ ਹੈ।"]},
"GEO-IND-001-CP004-Q020":{"h":"e0314947","hi":["किस उद्योग के प्रमुख फल उत्पादक क्षेत्र के पास लगने की सबसे अधिक संभावना है?",["इस्पात निर्माण","फल प्रसंस्करण","ऐलुमिनियम प्रगलन","सीमेंट उत्पादन"],"फल प्रसंस्करण इकाइयाँ ताज़े कच्चे माल के पास लगाकर खराब होने से होने वाली हानि और परिवहन लागत घटा सकती हैं।"],"pa":["ਕਿਹੜੇ ਉਦਯੋਗ ਦੇ ਫਲ ਉਗਾਉਣ ਵਾਲੇ ਪ੍ਰਮੁੱਖ ਇਲਾਕੇ ਨੇੜੇ ਲੱਗਣ ਦੀ ਸਭ ਤੋਂ ਵੱਧ ਸੰਭਾਵਨਾ ਹੈ?",["ਸਟੀਲ ਬਣਾਉਣਾ","ਫਲਾਂ ਦੀ ਪ੍ਰੋਸੈਸਿੰਗ","ਐਲੂਮੀਨੀਅਮ ਦੀ ਗਲਾਈ","ਸੀਮਿੰਟ ਦਾ ਉਤਪਾਦਨ"],"ਫਲਾਂ ਦੀ ਪ੍ਰੋਸੈਸਿੰਗ ਵਾਲੇ ਪਲਾਂਟ ਤਾਜ਼ੇ ਕੱਚੇ ਮਾਲ ਦੇ ਨੇੜੇ ਹੋਣ ਤਾਂ ਮਾਲ ਘੱਟ ਖ਼ਰਾਬ ਹੁੰਦਾ ਹੈ ਅਤੇ ਢੋਆ-ਢੁਆਈ ਦਾ ਖ਼ਰਚ ਘਟਦਾ ਹੈ।"]},
"GEO-IND-001-CP004-Q021":{"h":"2a6726f6","hi":["कथनों पर विचार कीजिए: I. कच्चे माल के जल्दी खराब होने का खाद्य उद्योग की अवस्थिति पर असर पड़ सकता है। II. शीत भंडारण से कच्चे माल को अधिक समय तक उपयोग में लाया जा सकता है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","I और II दोनों सही हैं","न तो I और न ही II सही है"],"जल्दी खराब होने वाली सामग्री का शीघ्र प्रसंस्करण लाभदायक है। शीत शृंखला की सुविधाएँ हानि घटा सकती हैं और आपूर्ति का क्षेत्र बढ़ा सकती हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਕੱਚੇ ਮਾਲ ਦੇ ਛੇਤੀ ਖ਼ਰਾਬ ਹੋਣ ਦਾ ਅਸਰ ਖ਼ੁਰਾਕੀ ਉਦਯੋਗ ਦੀ ਥਾਂ 'ਤੇ ਪੈ ਸਕਦਾ ਹੈ। II. ਠੰਢੇ ਭੰਡਾਰਨ ਨਾਲ ਕੱਚਾ ਮਾਲ ਲੰਮਾ ਸਮਾਂ ਵਰਤਣਯੋਗ ਰਹਿ ਸਕਦਾ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਛੇਤੀ ਖ਼ਰਾਬ ਹੋਣ ਵਾਲੇ ਮਾਲ ਦੀ ਪ੍ਰੋਸੈਸਿੰਗ ਛੇਤੀ ਕਰਨੀ ਲਾਹੇਵੰਦ ਹੈ। ਠੰਢੀ ਲੜੀ ਦੀਆਂ ਸਹੂਲਤਾਂ ਨੁਕਸਾਨ ਘਟਾ ਸਕਦੀਆਂ ਹਨ ਅਤੇ ਸਪਲਾਈ ਦਾ ਖੇਤਰ ਵਧਾ ਸਕਦੀਆਂ ਹਨ।"]},
"GEO-IND-001-CP004-Q022":{"h":"65c03b37","hi":["दूध प्रसंस्करण संयंत्रों के लिए कौन-सा कारक विशेष रूप से महत्वपूर्ण है?",["लौह अयस्क की श्रेणी","कोयले की परत की मोटाई","ज्वारीय परास","विश्वसनीय संग्रह और शीत शृंखला"],"दूध बहुत जल्दी खराब होता है। इसलिए उसका शीघ्र संग्रह, शीतलन और परिवहन दुग्ध प्रसंस्करण के लिए आवश्यक हैं।"],"pa":["ਦੁੱਧ ਦੀ ਪ੍ਰੋਸੈਸਿੰਗ ਵਾਲੇ ਪਲਾਂਟਾਂ ਲਈ ਕਿਹੜਾ ਕਾਰਕ ਖ਼ਾਸ ਤੌਰ 'ਤੇ ਅਹਿਮ ਹੈ?",["ਕੱਚੇ ਲੋਹੇ ਦਾ ਦਰਜਾ","ਕੋਲੇ ਦੀ ਪਰਤ ਦੀ ਮੋਟਾਈ","ਜਵਾਰ-ਭਾਟਾ ਅੰਤਰ","ਭਰੋਸੇਯੋਗ ਇਕੱਤਰੀਕਰਨ ਅਤੇ ਠੰਢੀ ਲੜੀ"],"ਦੁੱਧ ਬਹੁਤ ਛੇਤੀ ਖ਼ਰਾਬ ਹੁੰਦਾ ਹੈ। ਇਸ ਲਈ ਦੁੱਧ ਦੀ ਪ੍ਰੋਸੈਸਿੰਗ ਵਾਸਤੇ ਉਸ ਨੂੰ ਛੇਤੀ ਇਕੱਠਾ ਕਰਨਾ, ਠੰਢਾ ਕਰਨਾ ਅਤੇ ਢੋਣਾ ਬਹੁਤ ਜ਼ਰੂਰੀ ਹੈ।"]},
"GEO-IND-001-CP004-Q023":{"h":"60eb0482","hi":["खाद्य प्रसंस्करण की अवस्थिति में कौन-सा युग्म सही सुमेलित है?",["दुग्ध संयंत्र — दूध उत्पादक क्षेत्र","दुग्ध संयंत्र — लौह अयस्क पट्टी","फल डिब्बाबंदी इकाई — केवल कोयला क्षेत्र","चीनी मिल — पेट्रोलियम द्रोणी"],"खाद्य प्रसंस्करण संयंत्रों की अवस्थिति में प्रायः उनसे जुड़े कृषि कच्चे माल का भौगोलिक वितरण झलकता है।"],"pa":["ਖ਼ੁਰਾਕੀ ਪ੍ਰੋਸੈਸਿੰਗ ਦੀ ਥਾਂ ਸਬੰਧੀ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਦੁੱਧ ਪ੍ਰੋਸੈਸਿੰਗ ਪਲਾਂਟ — ਦੁੱਧ ਉਤਪਾਦਕ ਇਲਾਕਾ","ਦੁੱਧ ਪ੍ਰੋਸੈਸਿੰਗ ਪਲਾਂਟ — ਕੱਚੇ ਲੋਹੇ ਦੀ ਪੱਟੀ","ਫਲ ਡੱਬਾਬੰਦੀ ਇਕਾਈ — ਸਿਰਫ਼ ਕੋਲਾ ਖੇਤਰ","ਖੰਡ ਮਿੱਲ — ਪੈਟਰੋਲੀਅਮ ਬੇਸਿਨ"],"ਖ਼ੁਰਾਕੀ ਪ੍ਰੋਸੈਸਿੰਗ ਪਲਾਂਟਾਂ ਦੀ ਥਾਂ ਅਕਸਰ ਇਸ ਗੱਲ 'ਤੇ ਨਿਰਭਰ ਕਰਦੀ ਹੈ ਕਿ ਉਨ੍ਹਾਂ ਦਾ ਖੇਤੀ ਕੱਚਾ ਮਾਲ ਕਿੱਥੇ ਮਿਲਦਾ ਹੈ।"]},
"GEO-IND-001-CP004-Q024":{"h":"6276620f","hi":["एक संयंत्र सब्ज़ियों के खेतों के पास लगाया गया है क्योंकि उपज जल्दी खराब होती है। कौन-सा कारक प्रमुख है?",["खनिज भंडार","जल्दी खराब होने वाला कच्चा माल","जलविद्युत के लिए जल शीर्ष","ज्वारीय ऊर्जा"],"उपज जल्दी खराब हो तो प्रसंस्करण इकाई को उत्पादक क्षेत्र के पास लगाने का प्रबल कारण होता है।"],"pa":["ਸਬਜ਼ੀਆਂ ਛੇਤੀ ਖ਼ਰਾਬ ਹੋ ਜਾਂਦੀਆਂ ਹਨ, ਇਸ ਲਈ ਇੱਕ ਪਲਾਂਟ ਸਬਜ਼ੀਆਂ ਦੇ ਖੇਤਾਂ ਕੋਲ ਲਾਇਆ ਗਿਆ ਹੈ। ਕਿਹੜਾ ਕਾਰਕ ਮੁੱਖ ਹੈ?",["ਖਣਿਜ ਭੰਡਾਰ","ਛੇਤੀ ਖ਼ਰਾਬ ਹੋਣ ਵਾਲਾ ਕੱਚਾ ਮਾਲ","ਪਣ-ਬਿਜਲੀ ਲਈ ਪਾਣੀ ਦੀ ਉਚਾਈ","ਜਵਾਰ-ਭਾਟੇ ਦੀ ਊਰਜਾ"],"ਉਪਜ ਛੇਤੀ ਖ਼ਰਾਬ ਹੁੰਦੀ ਹੋਵੇ ਤਾਂ ਉਸ ਦੀ ਪ੍ਰੋਸੈਸਿੰਗ ਵਾਲੀ ਇਕਾਈ ਨੂੰ ਉਤਪਾਦਕ ਇਲਾਕੇ ਦੇ ਨੇੜੇ ਲਾਉਣ ਦਾ ਮਜ਼ਬੂਤ ਕਾਰਨ ਬਣਦਾ ਹੈ।"]},
"GEO-IND-001-CP004-Q025":{"h":"5901a0d5","hi":["कौन-सा उद्योग दूध से मक्खन, चीज़ और दूध का पाउडर जैसे उत्पाद बनाता है?",["जूट उद्योग","इस्पात उद्योग","दुग्ध प्रसंस्करण उद्योग","सीमेंट उद्योग"],"दुग्ध संयंत्र कच्चे दूध का प्रसंस्करण करके उपभोक्ताओं के लिए कई तरह के उत्पाद बनाते हैं।"],"pa":["ਕਿਹੜਾ ਉਦਯੋਗ ਦੁੱਧ ਤੋਂ ਮੱਖਣ, ਚੀਜ਼ ਅਤੇ ਦੁੱਧ ਦਾ ਪਾਊਡਰ ਵਰਗੇ ਉਤਪਾਦ ਬਣਾਉਂਦਾ ਹੈ?",["ਜੂਟ ਉਦਯੋਗ","ਸਟੀਲ ਉਦਯੋਗ","ਦੁੱਧ ਪ੍ਰੋਸੈਸਿੰਗ ਉਦਯੋਗ","ਸੀਮਿੰਟ ਉਦਯੋਗ"],"ਦੁੱਧ ਪ੍ਰੋਸੈਸਿੰਗ ਪਲਾਂਟ ਕੱਚੇ ਦੁੱਧ ਤੋਂ ਖਪਤਕਾਰਾਂ ਲਈ ਕਈ ਤਰ੍ਹਾਂ ਦੇ ਉਤਪਾਦ ਬਣਾਉਂਦੇ ਹਨ।"]},
"GEO-IND-001-CP004-Q026":{"h":"a4f8f89b","hi":["दुग्ध सहकारी समितियाँ ग्रामीण उत्पादकों की मदद कैसे कर सकती हैं?",["वे दूध उत्पादन बंद कर देती हैं","वे लौह अयस्क पर निर्भर हैं","वे शीत भंडारण की जगह खनन कराती हैं","वे मिलकर दूध के संग्रह, प्रसंस्करण और विपणन की व्यवस्था करती हैं"],"सहकारी समितियाँ अनेक छोटे उत्पादकों को शीतलन, प्रसंस्करण और विपणन की व्यवस्थाओं से जोड़ सकती हैं।"],"pa":["ਦੁੱਧ ਦੀਆਂ ਸਹਿਕਾਰੀ ਸਭਾਵਾਂ ਪੇਂਡੂ ਉਤਪਾਦਕਾਂ ਦੀ ਮਦਦ ਕਿਵੇਂ ਕਰ ਸਕਦੀਆਂ ਹਨ?",["ਉਹ ਦੁੱਧ ਦਾ ਉਤਪਾਦਨ ਬੰਦ ਕਰ ਦਿੰਦੀਆਂ ਹਨ","ਉਹ ਕੱਚੇ ਲੋਹੇ 'ਤੇ ਨਿਰਭਰ ਹਨ","ਉਹ ਠੰਢੇ ਭੰਡਾਰਨ ਦੀ ਥਾਂ ਖੁਦਾਈ ਕਰਵਾਉਂਦੀਆਂ ਹਨ","ਉਹ ਰਲ ਕੇ ਦੁੱਧ ਇਕੱਠਾ ਕਰਨ, ਪ੍ਰੋਸੈਸ ਕਰਨ ਅਤੇ ਵੇਚਣ ਦਾ ਪ੍ਰਬੰਧ ਕਰਦੀਆਂ ਹਨ"],"ਸਹਿਕਾਰੀ ਸਭਾਵਾਂ ਕਈ ਛੋਟੇ ਉਤਪਾਦਕਾਂ ਨੂੰ ਦੁੱਧ ਠੰਢਾ ਕਰਨ, ਪ੍ਰੋਸੈਸ ਕਰਨ ਅਤੇ ਵੇਚਣ ਦੀਆਂ ਸਹੂਲਤਾਂ ਨਾਲ ਜੋੜ ਸਕਦੀਆਂ ਹਨ।"]},
"GEO-IND-001-CP004-Q027":{"h":"577d32a3","hi":["कथनों पर विचार कीजिए: I. दूध जल्दी खराब होता है। II. दुग्ध प्रसंस्करण के लिए शीतलन सुविधाएँ महत्वपूर्ण हैं। कौन-सा/से कथन सही है/हैं?",["I और II दोनों सही हैं","केवल I सही है","केवल II सही है","न तो I और न ही II सही है"],"दूध को ठंडा रखे बिना उसकी गुणवत्ता तेज़ी से गिरती है, इसलिए संग्रह और शीतलन आवश्यक हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਦੁੱਧ ਛੇਤੀ ਖ਼ਰਾਬ ਹੁੰਦਾ ਹੈ। II. ਦੁੱਧ ਦੀ ਪ੍ਰੋਸੈਸਿੰਗ ਲਈ ਉਸ ਨੂੰ ਠੰਢਾ ਕਰਨ ਦੀਆਂ ਸਹੂਲਤਾਂ ਅਹਿਮ ਹਨ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਦੁੱਧ ਠੰਢਾ ਨਾ ਰੱਖਿਆ ਜਾਵੇ ਤਾਂ ਉਸ ਦੀ ਗੁਣਵੱਤਾ ਛੇਤੀ ਘਟ ਜਾਂਦੀ ਹੈ। ਇਸ ਲਈ ਉਸ ਨੂੰ ਇਕੱਠਾ ਕਰਨਾ ਅਤੇ ਠੰਢਾ ਕਰਨਾ ਜ਼ਰੂਰੀ ਹੈ।"]},
"GEO-IND-001-CP004-Q028":{"h":"4bcde0cb","hi":["घने दूध उत्पादक क्षेत्रों के पास दुग्ध संयंत्र लगाने का सबसे सीधा कारण क्या है?",["लौह अयस्क","कच्चे माल की आपूर्ति","बॉक्साइट","क्रोमाइट"],"आसपास के उत्पादकों से नियमित दूध मिलना कच्चे माल की मुख्य आवश्यकता है।"],"pa":["ਦੁੱਧ ਦੀ ਬਹੁਤਾਤ ਵਾਲੇ ਇਲਾਕਿਆਂ ਦੇ ਨੇੜੇ ਦੁੱਧ ਪ੍ਰੋਸੈਸਿੰਗ ਪਲਾਂਟ ਲਾਉਣ ਦਾ ਸਭ ਤੋਂ ਸਿੱਧਾ ਕਾਰਨ ਕੀ ਹੈ?",["ਕੱਚਾ ਲੋਹਾ","ਕੱਚੇ ਮਾਲ ਦੀ ਸਪਲਾਈ","ਬਾਕਸਾਈਟ","ਕ੍ਰੋਮਾਈਟ"],"ਆਲੇ-ਦੁਆਲੇ ਦੇ ਉਤਪਾਦਕਾਂ ਤੋਂ ਦੁੱਧ ਦੀ ਨਿਯਮਤ ਸਪਲਾਈ ਕੱਚੇ ਮਾਲ ਦੀ ਮੁੱਖ ਲੋੜ ਹੈ।"]},
"GEO-IND-001-CP004-Q029":{"h":"740482cc","hi":["भारत में संगठित दुग्ध प्रसंस्करण में स्वामित्व का कौन-सा प्रकार अक्सर महत्वपूर्ण होता है?",["केवल खनन पट्टा","केवल पत्तन प्राधिकरण","सहकारी मॉडल","केवल परमाणु निगम"],"दुग्ध सहकारी समितियाँ उत्पादकों को प्रसंस्करण और विपणन से जोड़ने वाला एक प्रमुख संगठनात्मक ढाँचा हैं।"],"pa":["ਭਾਰਤ ਵਿੱਚ ਸੰਗਠਿਤ ਦੁੱਧ ਪ੍ਰੋਸੈਸਿੰਗ ਲਈ ਕਿਹੜੀ ਕਿਸਮ ਦੀ ਮਲਕੀਅਤ ਅਕਸਰ ਅਹਿਮ ਹੁੰਦੀ ਹੈ?",["ਸਿਰਫ਼ ਖੁਦਾਈ ਦਾ ਪਟਾ","ਸਿਰਫ਼ ਬੰਦਰਗਾਹ ਅਥਾਰਟੀ","ਸਹਿਕਾਰੀ ਪ੍ਰਬੰਧ","ਸਿਰਫ਼ ਪਰਮਾਣੂ ਨਿਗਮ"],"ਦੁੱਧ ਦੀਆਂ ਸਹਿਕਾਰੀ ਸਭਾਵਾਂ ਇੱਕ ਪ੍ਰਮੁੱਖ ਜਥੇਬੰਦਕ ਰੂਪ ਹਨ, ਜੋ ਉਤਪਾਦਕਾਂ ਨੂੰ ਪ੍ਰੋਸੈਸਿੰਗ ਅਤੇ ਮੰਡੀਕਰਨ ਨਾਲ ਜੋੜਦੀਆਂ ਹਨ।"]},
"GEO-IND-001-CP004-Q030":{"h":"39d0401e","hi":["दुग्ध उत्पादों में मूल्यवर्धन का सही क्रम कौन-सा है?",["लौह अयस्क → दूध → चीज़","जूट → दूध का पाउडर → इस्पात","कोयला → मक्खन → सीमेंट","दूध → प्रसंस्करण → पैक किए गए दुग्ध उत्पाद"],"प्रसंस्करण से कच्चे दूध को मक्खन, चीज़ और दूध का पाउडर जैसे अधिक मूल्य वाले उत्पादों में बदला जाता है।"],"pa":["ਦੁੱਧ ਦੇ ਉਤਪਾਦਾਂ ਵਿੱਚ ਮੁੱਲ-ਵਾਧੇ ਦੀ ਸਹੀ ਲੜੀ ਕਿਹੜੀ ਹੈ?",["ਕੱਚਾ ਲੋਹਾ → ਦੁੱਧ → ਚੀਜ਼","ਜੂਟ → ਦੁੱਧ ਦਾ ਪਾਊਡਰ → ਸਟੀਲ","ਕੋਲਾ → ਮੱਖਣ → ਸੀਮਿੰਟ","ਦੁੱਧ → ਪ੍ਰੋਸੈਸਿੰਗ → ਪੈਕ ਕੀਤੇ ਦੁੱਧ ਉਤਪਾਦ"],"ਪ੍ਰੋਸੈਸਿੰਗ ਨਾਲ ਕੱਚੇ ਦੁੱਧ ਤੋਂ ਮੱਖਣ, ਚੀਜ਼ ਅਤੇ ਦੁੱਧ ਦਾ ਪਾਊਡਰ ਵਰਗੇ ਵੱਧ ਕੀਮਤ ਵਾਲੇ ਉਤਪਾਦ ਬਣਦੇ ਹਨ।"]},
"GEO-IND-001-CP004-Q031":{"h":"ebad65d8","hi":["खाद्य प्रसंस्करण के लिए प्रशीतित परिवहन क्यों महत्वपूर्ण है?",["यह अयस्क की श्रेणी बढ़ाता है","यह कोयला बनाता है","यह ढुलाई के दौरान जल्दी खराब होने वाले उत्पादों की हानि घटाता है","यह बाज़ारों की जगह लेता है"],"ठंडे परिवहन से खेत से संयंत्र तक और संयंत्र से बाज़ार तक उत्पादों की गुणवत्ता बनाए रखने में मदद मिलती है।"],"pa":["ਖ਼ੁਰਾਕੀ ਪ੍ਰੋਸੈਸਿੰਗ ਲਈ ਠੰਢੀ ਢੋਆ-ਢੁਆਈ ਕਿਉਂ ਅਹਿਮ ਹੈ?",["ਇਸ ਨਾਲ ਅਯਸਕ ਦਾ ਦਰਜਾ ਵਧਦਾ ਹੈ","ਇਸ ਨਾਲ ਕੋਲਾ ਬਣਦਾ ਹੈ","ਇਸ ਨਾਲ ਢੋਆ-ਢੁਆਈ ਦੌਰਾਨ ਛੇਤੀ ਖ਼ਰਾਬ ਹੋਣ ਵਾਲੇ ਉਤਪਾਦ ਘੱਟ ਵਿਗੜਦੇ ਹਨ","ਇਹ ਬਾਜ਼ਾਰਾਂ ਦੀ ਥਾਂ ਲੈਂਦੀ ਹੈ"],"ਠੰਢੀ ਢੋਆ-ਢੁਆਈ ਖੇਤ ਤੋਂ ਪਲਾਂਟ ਅਤੇ ਪਲਾਂਟ ਤੋਂ ਬਾਜ਼ਾਰ ਤੱਕ ਉਤਪਾਦਾਂ ਦੀ ਗੁਣਵੱਤਾ ਬਣਾਈ ਰੱਖਣ ਵਿੱਚ ਮਦਦ ਕਰਦੀ ਹੈ।"]},
"GEO-IND-001-CP004-Q032":{"h":"ad4b8de8","hi":["किस कारक की मदद से जल्दी खराब होने वाले खाद्य पदार्थों के उद्योग दूर के शहरी बाज़ारों तक पहुँचते हैं?",["लौह अयस्क की खदानें","ज्वारीय बाँध","कोयले की धुलाई","शीत शृंखला की परिवहन व भंडारण व्यवस्था"],"शीत भंडार और प्रशीतित परिवहन से खाद्य पदार्थ अधिक समय तक उपयोग योग्य रहते हैं और उन्हें अधिक दूर तक पहुँचाया जा सकता है।"],"pa":["ਕਿਹੜੇ ਕਾਰਕ ਸਦਕਾ ਛੇਤੀ ਖ਼ਰਾਬ ਹੋਣ ਵਾਲੇ ਖ਼ੁਰਾਕੀ ਪਦਾਰਥਾਂ ਦੇ ਉਦਯੋਗ ਦੂਰਲੇ ਸ਼ਹਿਰੀ ਬਾਜ਼ਾਰਾਂ ਤੱਕ ਪਹੁੰਚ ਸਕਦੇ ਹਨ?",["ਕੱਚੇ ਲੋਹੇ ਦੀਆਂ ਖਾਣਾਂ","ਜਵਾਰੀ ਬੰਨ੍ਹ","ਕੋਲੇ ਦੀ ਧੁਆਈ","ਠੰਢੀ ਲੜੀ ਦੀ ਢੋਆ-ਢੁਆਈ ਅਤੇ ਭੰਡਾਰਨ"],"ਠੰਢੇ ਗੋਦਾਮਾਂ ਅਤੇ ਠੰਢੀ ਢੋਆ-ਢੁਆਈ ਨਾਲ ਉਤਪਾਦ ਲੰਮਾ ਸਮਾਂ ਵਰਤਣਯੋਗ ਰਹਿੰਦੇ ਹਨ ਅਤੇ ਉਨ੍ਹਾਂ ਨੂੰ ਵੱਧ ਦੂਰੀ ਤੱਕ ਪਹੁੰਚਾਇਆ ਜਾ ਸਕਦਾ ਹੈ।"]},
"GEO-IND-001-CP004-Q033":{"h":"99b858f0","hi":["कथनों पर विचार कीजिए: I. शहरी बाज़ार पैक किए गए खाद्य पदार्थों के उद्योगों को आकर्षित कर सकते हैं। II. कुशल परिवहन से बाज़ार का क्षेत्र बढ़ता है। कौन-सा/से कथन सही है/हैं?",["I और II दोनों सही हैं","केवल I सही है","केवल II सही है","न तो I और न ही II सही है"],"माँग का संकेंद्रण और परिवहन का तंत्र, दोनों खाद्य प्रसंस्करण की अवस्थिति को प्रभावित करते हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਸ਼ਹਿਰੀ ਬਾਜ਼ਾਰ ਪੈਕ ਕੀਤੇ ਖ਼ੁਰਾਕੀ ਪਦਾਰਥਾਂ ਦੇ ਉਦਯੋਗਾਂ ਨੂੰ ਖਿੱਚ ਸਕਦੇ ਹਨ। II. ਸੁਚੱਜੀ ਆਵਾਜਾਈ ਨਾਲ ਬਾਜ਼ਾਰ ਦਾ ਘੇਰਾ ਵਧਦਾ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਮੰਗ ਦਾ ਇੱਕ ਥਾਂ ਕੇਂਦਰਿਤ ਹੋਣਾ ਅਤੇ ਆਵਾਜਾਈ ਦੇ ਜਾਲ, ਦੋਵੇਂ ਖ਼ੁਰਾਕੀ ਪ੍ਰੋਸੈਸਿੰਗ ਦੀ ਥਾਂ 'ਤੇ ਅਸਰ ਪਾਉਂਦੇ ਹਨ।"]},
"GEO-IND-001-CP004-Q034":{"h":"ac94f2e2","hi":["बड़े शहर को पैक किए गए खाद्य पदार्थों की आपूर्ति करने वाले संयंत्र के लिए कौन-सी जगह अनुकूल है?",["केवल दूर की अयस्क खदान","अच्छे परिवहन और बाज़ार संपर्क वाली जगह","बिना सड़क वाली ज्वारीय खाड़ी","केवल वर्षा के आधार पर चुनी जगह"],"पैक किए गए खाद्य पदार्थों के लिए उपभोक्ता माँग और माल की आवाजाही की व्यवस्था निर्णायक हो सकती है।"],"pa":["ਵੱਡੇ ਸ਼ਹਿਰ ਨੂੰ ਪੈਕ ਕੀਤੇ ਖ਼ੁਰਾਕੀ ਪਦਾਰਥ ਭੇਜਣ ਵਾਲੇ ਪਲਾਂਟ ਲਈ ਕਿਹੜੀ ਥਾਂ ਅਨੁਕੂਲ ਹੈ?",["ਸਿਰਫ਼ ਦੂਰ ਦੀ ਅਯਸਕ ਖਾਣ","ਚੰਗੀ ਆਵਾਜਾਈ ਅਤੇ ਬਾਜ਼ਾਰ ਤੱਕ ਪਹੁੰਚ ਵਾਲੀ ਥਾਂ","ਸੜਕਾਂ ਤੋਂ ਬਿਨਾਂ ਜਵਾਰੀ ਖਾੜੀ","ਸਿਰਫ਼ ਵਰਖਾ ਦੇ ਆਧਾਰ 'ਤੇ ਚੁਣੀ ਥਾਂ"],"ਪੈਕ ਕੀਤੇ ਖ਼ੁਰਾਕੀ ਪਦਾਰਥਾਂ ਲਈ ਖਪਤਕਾਰਾਂ ਦੀ ਮੰਗ ਅਤੇ ਮਾਲ ਭੇਜਣ ਦਾ ਪ੍ਰਬੰਧ ਫ਼ੈਸਲਾਕੁਨ ਹੋ ਸਕਦੇ ਹਨ।"]},
"GEO-IND-001-CP004-Q035":{"h":"18d20b42","hi":["खाद्य पदार्थों की परिवहन व भंडारण व्यवस्था में कौन-सा युग्म सही सुमेलित है?",["शीत भंडारण — इस्पात प्रगलन","शीत भंडारण — सीमेंट क्लिंकर","शीत भंडारण — कटाई के बाद उपज की हानि में कमी","शीत भंडारण — यूरेनियम संवर्धन"],"शीत भंडारण तापमान के प्रति संवेदनशील कृषि और खाद्य उत्पादों को सुरक्षित रखता है।"],"pa":["ਖ਼ੁਰਾਕੀ ਪਦਾਰਥਾਂ ਦੀ ਢੋਆ-ਢੁਆਈ ਅਤੇ ਭੰਡਾਰਨ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਠੰਢਾ ਭੰਡਾਰਨ — ਸਟੀਲ ਦੀ ਗਲਾਈ","ਠੰਢਾ ਭੰਡਾਰਨ — ਸੀਮਿੰਟ ਕਲਿੰਕਰ","ਠੰਢਾ ਭੰਡਾਰਨ — ਵਾਢੀ ਪਿੱਛੋਂ ਉਪਜ ਦਾ ਨੁਕਸਾਨ ਘਟਾਉਣਾ","ਠੰਢਾ ਭੰਡਾਰਨ — ਯੂਰੇਨੀਅਮ ਦਾ ਸੰਵਰਧਨ"],"ਠੰਢਾ ਭੰਡਾਰਨ ਉਨ੍ਹਾਂ ਖੇਤੀ ਅਤੇ ਖ਼ੁਰਾਕੀ ਉਤਪਾਦਾਂ ਨੂੰ ਸੰਭਾਲਦਾ ਹੈ ਜਿਨ੍ਹਾਂ 'ਤੇ ਤਾਪਮਾਨ ਦਾ ਅਸਰ ਪੈਂਦਾ ਹੈ।"]},
"GEO-IND-001-CP004-Q036":{"h":"46ff503b","hi":["एक प्रसंस्करण संयंत्र खेतों से सब्ज़ियाँ लेता है और पास के शहर में पैक किए गए उत्पाद बेचता है। अवस्थिति के कौन-से दो कारक सबसे स्पष्ट हैं?",["अयस्क और ज्वारीय ऊर्जा","कोयला और यूरेनियम","खनिज की श्रेणी और नदी का जल शीर्ष","कच्चा माल और बाज़ार"],"संयंत्र खेतों से मिलने वाली सामग्री और उपभोक्ता माँग, दोनों पर निर्भर है। यह स्रोत और बाज़ार, दोनों की ओर उन्मुख है।"],"pa":["ਇੱਕ ਪ੍ਰੋਸੈਸਿੰਗ ਪਲਾਂਟ ਖੇਤਾਂ ਤੋਂ ਸਬਜ਼ੀਆਂ ਲੈਂਦਾ ਹੈ ਅਤੇ ਨੇੜਲੇ ਸ਼ਹਿਰ ਵਿੱਚ ਪੈਕ ਕੀਤੇ ਉਤਪਾਦ ਵੇਚਦਾ ਹੈ। ਥਾਂ ਦੀ ਚੋਣ ਦੇ ਕਿਹੜੇ ਦੋ ਕਾਰਕ ਸਭ ਤੋਂ ਸਪਸ਼ਟ ਹਨ?",["ਅਯਸਕ ਅਤੇ ਜਵਾਰ-ਭਾਟੇ ਦੀ ਊਰਜਾ","ਕੋਲਾ ਅਤੇ ਯੂਰੇਨੀਅਮ","ਖਣਿਜ ਦਾ ਦਰਜਾ ਅਤੇ ਦਰਿਆ ਦੇ ਪਾਣੀ ਦੀ ਉਚਾਈ","ਕੱਚਾ ਮਾਲ ਅਤੇ ਬਾਜ਼ਾਰ"],"ਪਲਾਂਟ ਖੇਤਾਂ ਤੋਂ ਮਿਲਦੀ ਸਮੱਗਰੀ ਅਤੇ ਖਪਤਕਾਰਾਂ ਦੀ ਮੰਗ 'ਤੇ ਨਿਰਭਰ ਹੈ। ਇਸ ਦੀ ਥਾਂ ਸਰੋਤ ਅਤੇ ਬਾਜ਼ਾਰ ਦੋਵਾਂ ਨਾਲ ਜੁੜੀ ਹੈ।"]},
"GEO-IND-001-CP004-Q037":{"h":"1935c42e","hi":["कौन-सा राज्य भारत की उष्णकटिबंधीय गन्ना पट्टी का हिस्सा है?",["पंजाब","हरियाणा","उत्तराखंड","महाराष्ट्र"],"महाराष्ट्र प्रायद्वीपीय भारत की उष्णकटिबंधीय गन्ना पट्टी में है।"],"pa":["ਕਿਹੜਾ ਰਾਜ ਭਾਰਤ ਦੀ ਤਪਤ-ਖੰਡੀ ਗੰਨਾ ਪੱਟੀ ਦਾ ਹਿੱਸਾ ਹੈ?",["ਪੰਜਾਬ","ਹਰਿਆਣਾ","ਉੱਤਰਾਖੰਡ","ਮਹਾਰਾਸ਼ਟਰ"],"ਮਹਾਰਾਸ਼ਟਰ ਪ੍ਰਾਇਦੀਪੀ ਭਾਰਤ ਦੀ ਤਪਤ-ਖੰਡੀ ਗੰਨਾ ਪੱਟੀ ਵਿੱਚ ਪੈਂਦਾ ਹੈ।"]},
"GEO-IND-001-CP004-Q038":{"h":"69b61788","hi":["कौन-सा राज्य भारत की उपोष्णकटिबंधीय गन्ना पट्टी का प्रमुख हिस्सा है?",["उत्तर प्रदेश","केरल","गोवा","तमिलनाडु"],"उत्तर प्रदेश उत्तरी भारत की उपोष्णकटिबंधीय गन्ना पट्टी में है।"],"pa":["ਕਿਹੜਾ ਰਾਜ ਭਾਰਤ ਦੀ ਉਪ-ਤਪਤ-ਖੰਡੀ ਗੰਨਾ ਪੱਟੀ ਦਾ ਪ੍ਰਮੁੱਖ ਹਿੱਸਾ ਹੈ?",["ਉੱਤਰ ਪ੍ਰਦੇਸ਼","ਕੇਰਲ","ਗੋਆ","ਤਾਮਿਲਨਾਡੂ"],"ਉੱਤਰ ਪ੍ਰਦੇਸ਼ ਉੱਤਰੀ ਭਾਰਤ ਦੀ ਉਪ-ਤਪਤ-ਖੰਡੀ ਗੰਨਾ ਪੱਟੀ ਵਿੱਚ ਪੈਂਦਾ ਹੈ।"]},
"GEO-IND-001-CP004-Q039":{"h":"412f4344","hi":["प्रायद्वीपीय भारत के चीनी उत्पादक क्षेत्रों में पेराई का मौसम अधिक लंबा क्यों हो सकता है?",["वहाँ गन्ना नहीं उग सकता","गर्म उष्णकटिबंधीय दशाओं से गन्ने की खेती और पेराई की अवधि बढ़ती है","केवल पत्तनों का महत्व है","पूरे भारत में कहीं सर्दी नहीं पड़ती"],"प्रायद्वीपीय भारत की अपेक्षाकृत गर्म दशाओं में सामान्यतः ठंडे उत्तरी क्षेत्र से अधिक समय तक पेराई हो सकती है।"],"pa":["ਪ੍ਰਾਇਦੀਪੀ ਭਾਰਤ ਦੇ ਖੰਡ ਉਤਪਾਦਕ ਖੇਤਰਾਂ ਵਿੱਚ ਪਿੜਾਈ ਦਾ ਮੌਸਮ ਲੰਮਾ ਕਿਉਂ ਹੋ ਸਕਦਾ ਹੈ?",["ਉੱਥੇ ਗੰਨਾ ਉੱਗ ਨਹੀਂ ਸਕਦਾ","ਤਪਤ-ਖੰਡੀ ਗਰਮੀ ਨਾਲ ਗੰਨਾ ਉਗਾਉਣ ਅਤੇ ਪਿੜਾਈ ਦਾ ਸਮਾਂ ਵਧਦਾ ਹੈ","ਸਿਰਫ਼ ਬੰਦਰਗਾਹਾਂ ਦਾ ਮਹੱਤਵ ਹੈ","ਭਾਰਤ ਵਿੱਚ ਕਿਤੇ ਵੀ ਸਰਦੀ ਨਹੀਂ ਪੈਂਦੀ"],"ਪ੍ਰਾਇਦੀਪੀ ਭਾਰਤ ਦੇ ਗਰਮ ਹਾਲਾਤਾਂ ਵਿੱਚ ਆਮ ਤੌਰ 'ਤੇ ਠੰਢੇ ਉੱਤਰੀ ਖੇਤਰ ਨਾਲੋਂ ਲੰਮਾ ਸਮਾਂ ਪਿੜਾਈ ਕੀਤੀ ਜਾ ਸਕਦੀ ਹੈ।"]},
"GEO-IND-001-CP004-Q040":{"h":"81a4a9fa","hi":["कथनों पर विचार कीजिए: I. महाराष्ट्र उष्णकटिबंधीय चीनी उत्पादन क्षेत्र का उदाहरण है। II. उत्तर प्रदेश उपोष्णकटिबंधीय चीनी उत्पादन क्षेत्र का उदाहरण है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","I और II दोनों सही हैं","न तो I और न ही II सही है"],"दोनों राज्य भारत में चीनी उत्पादन के प्रमुख उष्णकटिबंधीय और उपोष्णकटिबंधीय प्रतिरूपों के उदाहरण हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਮਹਾਰਾਸ਼ਟਰ ਤਪਤ-ਖੰਡੀ ਖੰਡ ਉਤਪਾਦਨ ਦੀ ਉਦਾਹਰਨ ਹੈ। II. ਉੱਤਰ ਪ੍ਰਦੇਸ਼ ਉਪ-ਤਪਤ-ਖੰਡੀ ਖੰਡ ਉਤਪਾਦਨ ਦੀ ਉਦਾਹਰਨ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਦੋਵੇਂ ਰਾਜ ਭਾਰਤ ਵਿੱਚ ਖੰਡ ਉਤਪਾਦਨ ਦੇ ਪ੍ਰਮੁੱਖ ਤਪਤ-ਖੰਡੀ ਅਤੇ ਉਪ-ਤਪਤ-ਖੰਡੀ ਰੂਪਾਂ ਦੀਆਂ ਉਦਾਹਰਨਾਂ ਹਨ।"]},
"GEO-IND-001-CP004-Q041":{"h":"704d498e","hi":["चीनी उद्योग के भूगोल में कौन-सी तुलना सही है?",["उत्तर प्रदेश उष्णकटिबंधीय है","दोनों की जलवायु एक जैसी है","गन्ना केवल उत्तर भारत में उगता है","महाराष्ट्र में पेराई का मौसम आम तौर पर उत्तर प्रदेश से लंबा होता है"],"प्रायद्वीपीय भारत की अधिक गर्म जलवायु आम तौर पर पेराई के लंबे मौसम के अनुकूल है।"],"pa":["ਖੰਡ ਉਦਯੋਗ ਦੇ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜੀ ਤੁਲਨਾ ਸਹੀ ਹੈ?",["ਉੱਤਰ ਪ੍ਰਦੇਸ਼ ਤਪਤ-ਖੰਡੀ ਹੈ","ਦੋਵਾਂ ਦਾ ਜਲਵਾਯੂ ਇੱਕੋ ਜਿਹਾ ਹੈ","ਗੰਨਾ ਸਿਰਫ਼ ਉੱਤਰੀ ਭਾਰਤ ਵਿੱਚ ਉੱਗਦਾ ਹੈ","ਮਹਾਰਾਸ਼ਟਰ ਵਿੱਚ ਪਿੜਾਈ ਦਾ ਮੌਸਮ ਆਮ ਤੌਰ 'ਤੇ ਉੱਤਰ ਪ੍ਰਦੇਸ਼ ਨਾਲੋਂ ਲੰਮਾ ਹੁੰਦਾ ਹੈ"],"ਪ੍ਰਾਇਦੀਪੀ ਭਾਰਤ ਦਾ ਵੱਧ ਗਰਮ ਜਲਵਾਯੂ ਆਮ ਤੌਰ 'ਤੇ ਪਿੜਾਈ ਦੇ ਲੰਮੇ ਮੌਸਮ ਲਈ ਅਨੁਕੂਲ ਹੈ।"]},
"GEO-IND-001-CP004-Q042":{"h":"358ac99b","hi":["किस कारक ने चीनी उद्योग के विकास को प्रायद्वीपीय भारत के कुछ हिस्सों की ओर बढ़ाने में मदद की?",["पेराई का लंबा मौसम और अनुकूल उष्णकटिबंधीय दशाएँ","गन्ने का अभाव","श्रमिकों की कमी","कहीं भी सिंचाई न होना"],"जलवायु और संगठन संबंधी लाभों के कारण प्रायद्वीपीय चीनी उत्पादक क्षेत्र अधिक प्रतिस्पर्धी बने।"],"pa":["ਕਿਹੜੇ ਕਾਰਕ ਨੇ ਪ੍ਰਾਇਦੀਪੀ ਭਾਰਤ ਦੇ ਕੁਝ ਹਿੱਸਿਆਂ ਵੱਲ ਖੰਡ ਉਦਯੋਗ ਦਾ ਵਿਕਾਸ ਵਧਾਉਣ ਵਿੱਚ ਮਦਦ ਕੀਤੀ?",["ਪਿੜਾਈ ਦਾ ਲੰਮਾ ਮੌਸਮ ਅਤੇ ਅਨੁਕੂਲ ਤਪਤ-ਖੰਡੀ ਹਾਲਾਤ","ਗੰਨੇ ਦੀ ਅਣਹੋਂਦ","ਕਾਮਿਆਂ ਦੀ ਘਾਟ","ਕਿਤੇ ਵੀ ਸਿੰਜਾਈ ਨਾ ਹੋਣਾ"],"ਪ੍ਰਾਇਦੀਪੀ ਖੰਡ ਉਤਪਾਦਕ ਇਲਾਕਿਆਂ ਨੂੰ ਜਲਵਾਯੂ ਅਤੇ ਪ੍ਰਬੰਧ ਦੇ ਲਾਭ ਮਿਲੇ, ਜਿਸ ਨਾਲ ਉਨ੍ਹਾਂ ਦੀ ਮੁਕਾਬਲੇਬਾਜ਼ੀ ਦੀ ਸਮਰੱਥਾ ਵਧੀ।"]},
"GEO-IND-001-CP004-Q043":{"h":"5fa3c68c","hi":["चीनी उद्योग का कौन-सा उपोत्पाद बिजली के सह-उत्पादन में इस्तेमाल हो सकता है?",["लौह धातुमल","बॉक्साइट का अवशेष","गन्ने की खोई","अभ्रक"],"गन्ने की पेराई के बाद बचा रेशेदार अवशेष खोई कहलाता है। इसे जलाकर भाप और बिजली बनाई जा सकती है।"],"pa":["ਖੰਡ ਉਦਯੋਗ ਦਾ ਕਿਹੜਾ ਉਪ-ਉਤਪਾਦ ਬਿਜਲੀ ਦੇ ਸਹਿ-ਉਤਪਾਦਨ ਲਈ ਵਰਤਿਆ ਜਾ ਸਕਦਾ ਹੈ?",["ਲੋਹੇ ਦੀ ਸਲੈਗ","ਬਾਕਸਾਈਟ ਦੀ ਰਹਿੰਦ-ਖੂੰਹਦ","ਗੰਨੇ ਦੀ ਖੋਈ","ਅਬਰਕ"],"ਗੰਨੇ ਦੀ ਪਿੜਾਈ ਪਿੱਛੋਂ ਬਚੀ ਰੇਸ਼ੇਦਾਰ ਰਹਿੰਦ-ਖੂੰਹਦ ਨੂੰ ਖੋਈ ਕਹਿੰਦੇ ਹਨ। ਇਸ ਨੂੰ ਸਾੜ ਕੇ ਭਾਫ਼ ਅਤੇ ਬਿਜਲੀ ਪੈਦਾ ਕੀਤੀ ਜਾ ਸਕਦੀ ਹੈ।"]},
"GEO-IND-001-CP004-Q044":{"h":"68361d01","hi":["चीनी उद्योग का कौन-सा उपोत्पाद आसवनशालाओं में उपयोग होता है?",["चूना पत्थर","जूट का रेशा","लौह अयस्क","शीरा"],"शीरे से अल्कोहल और एथेनॉल बनाए जाते हैं।"],"pa":["ਖੰਡ ਉਦਯੋਗ ਦਾ ਕਿਹੜਾ ਉਪ-ਉਤਪਾਦ ਸ਼ਰਾਬ ਬਣਾਉਣ ਵਾਲੀਆਂ ਭੱਠੀਆਂ ਵਿੱਚ ਵਰਤਿਆ ਜਾਂਦਾ ਹੈ?",["ਚੂਨਾ ਪੱਥਰ","ਜੂਟ ਦਾ ਰੇਸ਼ਾ","ਕੱਚਾ ਲੋਹਾ","ਸ਼ੀਰਾ"],"ਸ਼ੀਰੇ ਤੋਂ ਅਲਕੋਹਲ ਅਤੇ ਐਥਾਨੋਲ ਬਣਾਏ ਜਾਂਦੇ ਹਨ।"]},
"GEO-IND-001-CP004-Q045":{"h":"66bf4b29","hi":["कथनों पर विचार कीजिए: I. गन्ने की खोई से ऊर्जा पैदा की जा सकती है। II. शीरे का उपयोग अल्कोहल उत्पादन में किया जा सकता है। कौन-सा/से कथन सही है/हैं?",["I और II दोनों सही हैं","केवल I सही है","केवल II सही है","न तो I और न ही II सही है"],"दोनों उपोत्पाद अन्य औद्योगिक गतिविधियों में काम आते हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਗੰਨੇ ਦੀ ਖੋਈ ਤੋਂ ਊਰਜਾ ਪੈਦਾ ਕੀਤੀ ਜਾ ਸਕਦੀ ਹੈ। II. ਸ਼ੀਰੇ ਤੋਂ ਅਲਕੋਹਲ ਬਣਾਈ ਜਾ ਸਕਦੀ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਦੋਵੇਂ ਉਪ-ਉਤਪਾਦ ਹੋਰ ਉਦਯੋਗਿਕ ਕੰਮਾਂ ਵਿੱਚ ਵਰਤੇ ਜਾਂਦੇ ਹਨ।"]},
"GEO-IND-001-CP004-Q046":{"h":"117c59be","hi":["कौन-सा क्रम चीनी उद्योग के एकीकृत उपयोग को सही दर्शाता है?",["गन्ना → लोहा + इस्पात","गन्ना → चीनी + खोई + शीरा","गन्ना → बॉक्साइट + ऐलुमिनियम","गन्ना → जूट + अभ्रक"],"गन्ने के प्रसंस्करण से चीनी के साथ खोई और शीरे जैसे उपयोगी उपोत्पाद मिलते हैं।"],"pa":["ਖੰਡ ਉਦਯੋਗ ਵਿੱਚ ਗੰਨੇ ਦੀ ਏਕੀਕ੍ਰਿਤ ਵਰਤੋਂ ਕਿਹੜੀ ਲੜੀ ਸਹੀ ਦਰਸਾਉਂਦੀ ਹੈ?",["ਗੰਨਾ → ਲੋਹਾ + ਸਟੀਲ","ਗੰਨਾ → ਖੰਡ + ਖੋਈ + ਸ਼ੀਰਾ","ਗੰਨਾ → ਬਾਕਸਾਈਟ + ਐਲੂਮੀਨੀਅਮ","ਗੰਨਾ → ਜੂਟ + ਅਬਰਕ"],"ਗੰਨੇ ਦੀ ਪ੍ਰੋਸੈਸਿੰਗ ਨਾਲ ਖੰਡ ਦੇ ਨਾਲ ਖੋਈ ਅਤੇ ਸ਼ੀਰੇ ਵਰਗੇ ਲਾਹੇਵੰਦ ਉਪ-ਉਤਪਾਦ ਮਿਲਦੇ ਹਨ।"]},
"GEO-IND-001-CP004-Q047":{"h":"c3937446","hi":["चीनी उद्योग के उपोत्पादों में कौन-सा युग्म सही सुमेलित है?",["खोई — लौह प्रगलन","शीरा — सीमेंट क्लिंकर","खोई — सह-उत्पादन","शीरा — जूट का रेशा"],"भाप और बिजली पैदा करने के लिए खोई का व्यापक रूप से बॉयलर के ईंधन के रूप में उपयोग होता है।"],"pa":["ਖੰਡ ਉਦਯੋਗ ਦੇ ਉਪ-ਉਤਪਾਦਾਂ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਖੋਈ — ਲੋਹੇ ਦੀ ਗਲਾਈ","ਸ਼ੀਰਾ — ਸੀਮਿੰਟ ਕਲਿੰਕਰ","ਖੋਈ — ਸਹਿ-ਉਤਪਾਦਨ","ਸ਼ੀਰਾ — ਜੂਟ ਦਾ ਰੇਸ਼ਾ"],"ਭਾਫ਼ ਅਤੇ ਬਿਜਲੀ ਪੈਦਾ ਕਰਨ ਲਈ ਖੋਈ ਵੱਡੇ ਪੱਧਰ 'ਤੇ ਬਾਇਲਰ ਦੇ ਬਾਲਣ ਵਜੋਂ ਵਰਤੀ ਜਾਂਦੀ ਹੈ।"]},
"GEO-IND-001-CP004-Q048":{"h":"941609e0","hi":["आधुनिक चीनी औद्योगिक परिसर चीनी के अलावा अन्य उत्पाद क्यों बना सकता है?",["चीनी मिलें लौह अयस्क का खनन करती हैं","गन्ने से बॉक्साइट बनता है","चीनी के परिष्करण से कोयले की परतें बनती हैं","उपोत्पाद बिजली उत्पादन और आसवन के काम आ सकते हैं"],"खोई और शीरे का एकीकृत उपयोग करने से बिजली का सह-उत्पादन और आसवनशाला में उत्पादन संभव होता है।"],"pa":["ਆਧੁਨਿਕ ਖੰਡ ਉਦਯੋਗ ਦੇ ਅਹਾਤੇ ਵਿੱਚ ਖੰਡ ਤੋਂ ਇਲਾਵਾ ਹੋਰ ਉਤਪਾਦ ਕਿਉਂ ਬਣ ਸਕਦੇ ਹਨ?",["ਖੰਡ ਮਿੱਲਾਂ ਕੱਚੇ ਲੋਹੇ ਦੀ ਖੁਦਾਈ ਕਰਦੀਆਂ ਹਨ","ਗੰਨੇ ਤੋਂ ਬਾਕਸਾਈਟ ਬਣਦਾ ਹੈ","ਖੰਡ ਸੋਧਣ ਨਾਲ ਕੋਲੇ ਦੀਆਂ ਪਰਤਾਂ ਬਣਦੀਆਂ ਹਨ","ਉਪ-ਉਤਪਾਦ ਬਿਜਲੀ ਬਣਾਉਣ ਅਤੇ ਅਲਕੋਹਲ ਕੱਢਣ ਦੇ ਕੰਮ ਆ ਸਕਦੇ ਹਨ"],"ਖੋਈ ਅਤੇ ਸ਼ੀਰੇ ਦੀ ਏਕੀਕ੍ਰਿਤ ਵਰਤੋਂ ਨਾਲ ਬਿਜਲੀ ਦਾ ਸਹਿ-ਉਤਪਾਦਨ ਅਤੇ ਸ਼ਰਾਬ ਦੀ ਭੱਠੀ ਵਿੱਚ ਉਤਪਾਦਨ ਸੰਭਵ ਹੁੰਦਾ ਹੈ।"]},
"GEO-IND-001-CP004-Q049":{"h":"4c75959a","hi":["फल प्रसंस्करण संयंत्र की अवस्थिति तय करते समय कौन-सा कारक विशेष रूप से महत्वपूर्ण है?",["फल उत्पादक क्षेत्रों और शीत शृंखला सुविधाओं की निकटता","लौह अयस्क के निक्षेप","कोयले की परतें","यूरेनियम की खदानें"],"फल जल्दी खराब होते हैं। इसलिए उनका शीघ्र संग्रह, प्रसंस्करण और शीतलन महत्वपूर्ण है।"],"pa":["ਫਲਾਂ ਦੀ ਪ੍ਰੋਸੈਸਿੰਗ ਵਾਲੇ ਪਲਾਂਟ ਦੀ ਥਾਂ ਚੁਣਨ ਵੇਲੇ ਕਿਹੜਾ ਕਾਰਕ ਖ਼ਾਸ ਤੌਰ 'ਤੇ ਅਹਿਮ ਹੈ?",["ਫਲ ਉਗਾਉਣ ਵਾਲੇ ਇਲਾਕਿਆਂ ਅਤੇ ਠੰਢੀ ਲੜੀ ਦੀਆਂ ਸਹੂਲਤਾਂ ਦੀ ਨੇੜਤਾ","ਕੱਚੇ ਲੋਹੇ ਦੇ ਭੰਡਾਰ","ਕੋਲੇ ਦੀਆਂ ਪਰਤਾਂ","ਯੂਰੇਨੀਅਮ ਦੀਆਂ ਖਾਣਾਂ"],"ਫਲ ਛੇਤੀ ਖ਼ਰਾਬ ਹੁੰਦੇ ਹਨ। ਇਸ ਲਈ ਉਨ੍ਹਾਂ ਨੂੰ ਛੇਤੀ ਇਕੱਠਾ ਕਰਨਾ, ਪ੍ਰੋਸੈਸ ਕਰਨਾ ਅਤੇ ਠੰਢਾ ਕਰਨਾ ਜ਼ਰੂਰੀ ਹੈ।"]},
"GEO-IND-001-CP004-Q050":{"h":"6f48edb9","hi":["फल और सब्ज़ी प्रसंस्करण के लिए शीत भंडार क्यों महत्वपूर्ण हैं?",["वे अयस्क की श्रेणी बढ़ाते हैं","वे प्रसंस्करण से पहले और बाद में खराब होने से होने वाली हानि घटाते हैं","वे परिवहन की जगह लेते हैं","वे सीमेंट बनाते हैं"],"तापमान पर नियंत्रण रखने से उपज अधिक समय तक उपयोग योग्य रहती है और कटाई के बाद होने वाली हानि घटती है।"],"pa":["ਫਲਾਂ ਅਤੇ ਸਬਜ਼ੀਆਂ ਦੀ ਪ੍ਰੋਸੈਸਿੰਗ ਲਈ ਠੰਢੇ ਗੋਦਾਮ ਕਿਉਂ ਅਹਿਮ ਹਨ?",["ਇਨ੍ਹਾਂ ਨਾਲ ਅਯਸਕ ਦਾ ਦਰਜਾ ਵਧਦਾ ਹੈ","ਇਨ੍ਹਾਂ ਨਾਲ ਪ੍ਰੋਸੈਸਿੰਗ ਤੋਂ ਪਹਿਲਾਂ ਅਤੇ ਬਾਅਦ ਮਾਲ ਘੱਟ ਖ਼ਰਾਬ ਹੁੰਦਾ ਹੈ","ਇਹ ਢੋਆ-ਢੁਆਈ ਦੀ ਥਾਂ ਲੈਂਦੇ ਹਨ","ਇਨ੍ਹਾਂ ਨਾਲ ਸੀਮਿੰਟ ਬਣਦਾ ਹੈ"],"ਤਾਪਮਾਨ ਕਾਬੂ ਵਿੱਚ ਰੱਖਣ ਨਾਲ ਉਪਜ ਲੰਮਾ ਸਮਾਂ ਵਰਤਣਯੋਗ ਰਹਿੰਦੀ ਹੈ ਅਤੇ ਵਾਢੀ ਪਿੱਛੋਂ ਨੁਕਸਾਨ ਘਟਦਾ ਹੈ।"]},
"GEO-IND-001-CP004-Q051":{"h":"a3b97ea0","hi":["कथनों पर विचार कीजिए: I. जल्दी खराब होने वाली फसलों का शीघ्र प्रसंस्करण लाभदायक है। II. शीत शृंखला से आपूर्ति और बाज़ार का क्षेत्र बढ़ता है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","I और II दोनों सही हैं","न तो I और न ही II सही है"],"आधुनिक खाद्य प्रसंस्करण के भूगोल में शीघ्र प्रसंस्करण और प्रशीतित परिवहन व भंडारण एक-दूसरे के पूरक हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਛੇਤੀ ਖ਼ਰਾਬ ਹੋਣ ਵਾਲੀਆਂ ਫ਼ਸਲਾਂ ਦੀ ਛੇਤੀ ਪ੍ਰੋਸੈਸਿੰਗ ਲਾਹੇਵੰਦ ਹੈ। II. ਠੰਢੀ ਲੜੀ ਨਾਲ ਸਪਲਾਈ ਅਤੇ ਬਾਜ਼ਾਰ ਦਾ ਘੇਰਾ ਵਧਦਾ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਆਧੁਨਿਕ ਖ਼ੁਰਾਕੀ ਪ੍ਰੋਸੈਸਿੰਗ ਦੇ ਭੂਗੋਲ ਵਿੱਚ ਛੇਤੀ ਪ੍ਰੋਸੈਸਿੰਗ ਅਤੇ ਠੰਢੀ ਢੋਆ-ਢੁਆਈ ਤੇ ਭੰਡਾਰਨ ਇੱਕ-ਦੂਜੇ ਦੇ ਪੂਰਕ ਹਨ।"]},
"GEO-IND-001-CP004-Q052":{"h":"0656e8eb","hi":["किस उद्योग के आम उत्पादक प्रमुख क्षेत्र के पास विकसित होने की सबसे अधिक संभावना है?",["इस्पात उद्योग","ऐलुमिनियम प्रगलन","सीमेंट उद्योग","फलों का गूदा बनाने और प्रसंस्करण का उद्योग"],"फल प्रसंस्करण इकाइयों को उस क्षेत्र की निकटता का सीधा लाभ मिलता है जहाँ बागवानी का कच्चा माल बड़ी मात्रा में उपलब्ध है।"],"pa":["ਕਿਹੜੇ ਉਦਯੋਗ ਦੇ ਅੰਬ ਉਗਾਉਣ ਵਾਲੇ ਪ੍ਰਮੁੱਖ ਇਲਾਕੇ ਨੇੜੇ ਵਿਕਸਿਤ ਹੋਣ ਦੀ ਸਭ ਤੋਂ ਵੱਧ ਸੰਭਾਵਨਾ ਹੈ?",["ਸਟੀਲ ਉਦਯੋਗ","ਐਲੂਮੀਨੀਅਮ ਦੀ ਗਲਾਈ","ਸੀਮਿੰਟ ਉਦਯੋਗ","ਫਲਾਂ ਦਾ ਗੁੱਦਾ ਬਣਾਉਣ ਅਤੇ ਪ੍ਰੋਸੈਸਿੰਗ ਦਾ ਉਦਯੋਗ"],"ਫਲਾਂ ਦੀ ਪ੍ਰੋਸੈਸਿੰਗ ਕਰਨ ਵਾਲੀਆਂ ਇਕਾਈਆਂ ਨੂੰ ਉਸ ਇਲਾਕੇ ਦੇ ਨੇੜੇ ਹੋਣ ਦਾ ਸਿੱਧਾ ਲਾਭ ਹੁੰਦਾ ਹੈ, ਜਿੱਥੇ ਬਾਗ਼ਬਾਨੀ ਦਾ ਕੱਚਾ ਮਾਲ ਵੱਡੀ ਮਾਤਰਾ ਵਿੱਚ ਮਿਲਦਾ ਹੈ।"]},
"GEO-IND-001-CP004-Q053":{"h":"d1c87621","hi":["बागवानी उत्पादों के प्रसंस्करण में कौन-सा युग्म सही सुमेलित है?",["फल प्रसंस्करण संयंत्र — बागवानी पट्टी","फल प्रसंस्करण संयंत्र — लौह अयस्क पट्टी","सब्ज़ी डिब्बाबंदी इकाई — केवल कोयला क्षेत्र","दुग्ध संयंत्र — क्रोमाइट खदान"],"बागवानी उत्पादों का प्रसंस्करण ताज़े कृषि कच्चे माल से निकटता से जुड़ा है।"],"pa":["ਬਾਗ਼ਬਾਨੀ ਉਪਜ ਦੀ ਪ੍ਰੋਸੈਸਿੰਗ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਫਲ ਪ੍ਰੋਸੈਸਿੰਗ ਪਲਾਂਟ — ਬਾਗ਼ਬਾਨੀ ਪੱਟੀ","ਫਲ ਪ੍ਰੋਸੈਸਿੰਗ ਪਲਾਂਟ — ਕੱਚੇ ਲੋਹੇ ਦੀ ਪੱਟੀ","ਸਬਜ਼ੀਆਂ ਦੀ ਡੱਬਾਬੰਦੀ ਇਕਾਈ — ਸਿਰਫ਼ ਕੋਲਾ ਖੇਤਰ","ਦੁੱਧ ਪ੍ਰੋਸੈਸਿੰਗ ਪਲਾਂਟ — ਕ੍ਰੋਮਾਈਟ ਖਾਣ"],"ਬਾਗ਼ਬਾਨੀ ਉਪਜ ਦੀ ਪ੍ਰੋਸੈਸਿੰਗ ਤਾਜ਼ੇ ਖੇਤੀ ਕੱਚੇ ਮਾਲ ਨਾਲ ਨੇੜਿਓਂ ਜੁੜੀ ਹੈ।"]},
"GEO-IND-001-CP004-Q054":{"h":"8e65c051","hi":["एक क्षेत्र में बड़ी मात्रा में टमाटर उगते हैं और वहाँ शीत भंडार और राजमार्ग हैं। कौन-सा उद्योग स्वाभाविक रूप से अनुकूल है?",["लौह और इस्पात","टमाटर और सब्ज़ी प्रसंस्करण","ताँबा प्रगलन","सीमेंट"],"जल्दी खराब होने वाले कच्चे माल के साथ शीत शृंखला और परिवहन की सुविधाएँ सब्ज़ी प्रसंस्करण के लिए अनुकूल हैं।"],"pa":["ਇੱਕ ਇਲਾਕੇ ਵਿੱਚ ਵੱਡੀ ਮਾਤਰਾ ਵਿੱਚ ਟਮਾਟਰ ਉਗਾਏ ਜਾਂਦੇ ਹਨ ਅਤੇ ਉੱਥੇ ਠੰਢੇ ਗੋਦਾਮ ਤੇ ਰਾਜਮਾਰਗ ਹਨ। ਕਿਹੜੇ ਉਦਯੋਗ ਲਈ ਸੁਭਾਵਕ ਤੌਰ 'ਤੇ ਅਨੁਕੂਲ ਹਾਲਾਤ ਹਨ?",["ਲੋਹਾ ਅਤੇ ਸਟੀਲ","ਟਮਾਟਰਾਂ ਅਤੇ ਸਬਜ਼ੀਆਂ ਦੀ ਪ੍ਰੋਸੈਸਿੰਗ","ਤਾਂਬੇ ਦੀ ਗਲਾਈ","ਸੀਮਿੰਟ"],"ਛੇਤੀ ਖ਼ਰਾਬ ਹੋਣ ਵਾਲੇ ਕੱਚੇ ਮਾਲ ਦੇ ਨਾਲ ਠੰਢੀ ਲੜੀ ਅਤੇ ਆਵਾਜਾਈ ਦੀਆਂ ਸਹੂਲਤਾਂ ਸਬਜ਼ੀਆਂ ਦੀ ਪ੍ਰੋਸੈਸਿੰਗ ਲਈ ਅਨੁਕੂਲ ਹਨ।"]},
"GEO-IND-001-CP004-Q055":{"h":"27d4f403","hi":["खाद्य तेल उद्योग के लिए कौन-सा कच्चा माल उपयोग होता है?",["लौह अयस्क","बॉक्साइट","तिलहन","चूना पत्थर"],"मूँगफली, सरसों और सोयाबीन जैसे तिलहनों के प्रसंस्करण से खाद्य तेल बनाए जाते हैं।"],"pa":["ਖਾਣ ਵਾਲੇ ਤੇਲ ਦੇ ਉਦਯੋਗ ਲਈ ਕਿਹੜਾ ਕੱਚਾ ਮਾਲ ਵਰਤਿਆ ਜਾਂਦਾ ਹੈ?",["ਕੱਚਾ ਲੋਹਾ","ਬਾਕਸਾਈਟ","ਤੇਲ ਬੀਜ","ਚੂਨਾ ਪੱਥਰ"],"ਮੂੰਗਫਲੀ, ਸਰ੍ਹੋਂ ਅਤੇ ਸੋਇਆਬੀਨ ਵਰਗੇ ਤੇਲ ਬੀਜਾਂ ਦੀ ਪ੍ਰੋਸੈਸਿੰਗ ਨਾਲ ਖਾਣ ਵਾਲੇ ਤੇਲ ਬਣਦੇ ਹਨ।"]},
"GEO-IND-001-CP004-Q056":{"h":"5a6aafb5","hi":["किस उद्योग के तिलहन उत्पादक प्रमुख क्षेत्र के पास विकसित होने की सबसे अधिक संभावना है?",["इस्पात निर्माण","सीमेंट उत्पादन","ऐलुमिनियम प्रगलन","खाद्य तेल प्रसंस्करण"],"तिलहन की उपलब्धता से पेराई और तेल शोधन इकाइयों को कच्चे माल का लाभ मिलता है।"],"pa":["ਕਿਹੜੇ ਉਦਯੋਗ ਦੇ ਤੇਲ ਬੀਜ ਉਗਾਉਣ ਵਾਲੇ ਪ੍ਰਮੁੱਖ ਇਲਾਕੇ ਨੇੜੇ ਵਿਕਸਿਤ ਹੋਣ ਦੀ ਸਭ ਤੋਂ ਵੱਧ ਸੰਭਾਵਨਾ ਹੈ?",["ਸਟੀਲ ਬਣਾਉਣਾ","ਸੀਮਿੰਟ ਦਾ ਉਤਪਾਦਨ","ਐਲੂਮੀਨੀਅਮ ਦੀ ਗਲਾਈ","ਖਾਣ ਵਾਲੇ ਤੇਲ ਦੀ ਪ੍ਰੋਸੈਸਿੰਗ"],"ਤੇਲ ਬੀਜ ਉਪਲਬਧ ਹੋਣ ਨਾਲ ਪਿੜਾਈ ਅਤੇ ਤੇਲ ਸੋਧਣ ਵਾਲੀਆਂ ਇਕਾਈਆਂ ਨੂੰ ਕੱਚੇ ਮਾਲ ਦਾ ਲਾਭ ਮਿਲਦਾ ਹੈ।"]},
"GEO-IND-001-CP004-Q057":{"h":"f3dd533c","hi":["कथनों पर विचार कीजिए: I. मूँगफली और सरसों तिलहन हैं। II. तिलहन प्रसंस्करण उद्योग कृषि आधारित हैं। कौन-सा/से कथन सही है/हैं?",["I और II दोनों सही हैं","केवल I सही है","केवल II सही है","न तो I और न ही II सही है"],"दोनों कथन खाद्य तेल प्रसंस्करण के कृषि आधार का सही वर्णन करते हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਮੂੰਗਫਲੀ ਅਤੇ ਸਰ੍ਹੋਂ ਤੇਲ ਬੀਜ ਹਨ। II. ਤੇਲ ਬੀਜਾਂ ਦੀ ਪ੍ਰੋਸੈਸਿੰਗ ਦੇ ਉਦਯੋਗ ਖੇਤੀ-ਆਧਾਰਿਤ ਹਨ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਦੋਵੇਂ ਕਥਨ ਖਾਣ ਵਾਲੇ ਤੇਲ ਦੀ ਪ੍ਰੋਸੈਸਿੰਗ ਦੇ ਖੇਤੀ ਆਧਾਰ ਦਾ ਸਹੀ ਵਰਣਨ ਕਰਦੇ ਹਨ।"]},
"GEO-IND-001-CP004-Q058":{"h":"9e6ef1d0","hi":["खाद्य उद्योगों के वर्गीकरण में कौन-सा युग्म सही सुमेलित है?",["तिलहन की पेराई — खनिज आधारित उद्योग","तिलहन की पेराई — कृषि आधारित उद्योग","सरसों का तेल — इस्पात उत्पाद","मूँगफली का तेल — सीमेंट उत्पाद"],"तिलहन के प्रसंस्करण में कृषि से प्राप्त कच्चा माल उपयोग होता है, इसलिए यह कृषि आधारित उद्योग है।"],"pa":["ਖ਼ੁਰਾਕੀ ਉਦਯੋਗਾਂ ਦੇ ਵਰਗੀਕਰਨ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਤੇਲ ਬੀਜਾਂ ਦੀ ਪਿੜਾਈ — ਖਣਿਜ-ਆਧਾਰਿਤ ਉਦਯੋਗ","ਤੇਲ ਬੀਜਾਂ ਦੀ ਪਿੜਾਈ — ਖੇਤੀ-ਆਧਾਰਿਤ ਉਦਯੋਗ","ਸਰ੍ਹੋਂ ਦਾ ਤੇਲ — ਸਟੀਲ ਉਤਪਾਦ","ਮੂੰਗਫਲੀ ਦਾ ਤੇਲ — ਸੀਮਿੰਟ ਉਤਪਾਦ"],"ਤੇਲ ਬੀਜਾਂ ਦੀ ਪ੍ਰੋਸੈਸਿੰਗ ਲਈ ਖੇਤੀ ਤੋਂ ਮਿਲਿਆ ਕੱਚਾ ਮਾਲ ਵਰਤਿਆ ਜਾਂਦਾ ਹੈ, ਇਸ ਲਈ ਇਹ ਖੇਤੀ-ਆਧਾਰਿਤ ਉਦਯੋਗ ਹੈ।"]},
"GEO-IND-001-CP004-Q059":{"h":"dcb646ce","hi":["खाद्य तेल मिलें खेतों के साथ-साथ तिलहन मंडियों के पास भी क्यों लग सकती हैं?",["उन्हें यूरेनियम चाहिए","वे कोई कच्चा माल इस्तेमाल नहीं करतीं","उन्हें कृषि कच्चे माल की एक जगह पर्याप्त आपूर्ति चाहिए","वे केवल पत्तनों पर निर्भर हैं"],"मंडियाँ और तिलहन उत्पादक पट्टियाँ, दोनों प्रसंस्करण इकाइयों को भरोसेमंद आपूर्ति दे सकती हैं।"],"pa":["ਖਾਣ ਵਾਲੇ ਤੇਲ ਦੀਆਂ ਮਿੱਲਾਂ ਖੇਤਾਂ ਦੇ ਨਾਲ-ਨਾਲ ਤੇਲ ਬੀਜਾਂ ਦੀਆਂ ਮੰਡੀਆਂ ਨੇੜੇ ਵੀ ਕਿਉਂ ਲੱਗ ਸਕਦੀਆਂ ਹਨ?",["ਉਨ੍ਹਾਂ ਨੂੰ ਯੂਰੇਨੀਅਮ ਚਾਹੀਦਾ ਹੈ","ਉਹ ਕੋਈ ਕੱਚਾ ਮਾਲ ਨਹੀਂ ਵਰਤਦੀਆਂ","ਉਨ੍ਹਾਂ ਨੂੰ ਖੇਤੀ ਦਾ ਕੱਚਾ ਮਾਲ ਇੱਕੋ ਥਾਂ ਕਾਫ਼ੀ ਮਾਤਰਾ ਵਿੱਚ ਚਾਹੀਦਾ ਹੈ","ਉਹ ਸਿਰਫ਼ ਬੰਦਰਗਾਹਾਂ 'ਤੇ ਨਿਰਭਰ ਹਨ"],"ਮੰਡੀਆਂ ਅਤੇ ਤੇਲ ਬੀਜ ਉਗਾਉਣ ਵਾਲੀਆਂ ਪੱਟੀਆਂ, ਦੋਵੇਂ ਪ੍ਰੋਸੈਸਿੰਗ ਇਕਾਈਆਂ ਨੂੰ ਭਰੋਸੇਯੋਗ ਸਪਲਾਈ ਦੇ ਸਕਦੀਆਂ ਹਨ।"]},
"GEO-IND-001-CP004-Q060":{"h":"1bd33d8b","hi":["खाद्य तेलों में मूल्यवर्धन का सही क्रम कौन-सा है?",["लौह अयस्क → तेल → इस्पात","कोयला → सरसों → तेल","बॉक्साइट → सोयाबीन → ऐलुमिनियम","तिलहन → पेराई/शोधन → खाद्य तेल"],"प्रसंस्करण के दौरान तिलहनों से तेल निकालकर उसका शोधन किया जाता है।"],"pa":["ਖਾਣ ਵਾਲੇ ਤੇਲਾਂ ਵਿੱਚ ਮੁੱਲ-ਵਾਧੇ ਦੀ ਸਹੀ ਲੜੀ ਕਿਹੜੀ ਹੈ?",["ਕੱਚਾ ਲੋਹਾ → ਤੇਲ → ਸਟੀਲ","ਕੋਲਾ → ਸਰ੍ਹੋਂ → ਤੇਲ","ਬਾਕਸਾਈਟ → ਸੋਇਆਬੀਨ → ਐਲੂਮੀਨੀਅਮ","ਤੇਲ ਬੀਜ → ਪਿੜਾਈ/ਸੋਧਾਈ → ਖਾਣ ਵਾਲਾ ਤੇਲ"],"ਪ੍ਰੋਸੈਸਿੰਗ ਦੌਰਾਨ ਖੇਤੀ ਤੋਂ ਮਿਲੇ ਤੇਲ ਬੀਜਾਂ ਵਿੱਚੋਂ ਤੇਲ ਕੱਢ ਕੇ ਸੋਧਿਆ ਜਾਂਦਾ ਹੈ।"]},
"GEO-IND-001-CP005-Q001":{"h":"c9f4c60e","hi":["सीमेंट विनिर्माण का मुख्य खनिज कच्चा माल कौन-सा है?",["अभ्रक","बॉक्साइट","चूना पत्थर","क्रोमाइट"],"सीमेंट बनाने के लिए आवश्यक कैल्शियम-समृद्ध सामग्री चूना पत्थर से मिलती है।"],"pa":["ਸੀਮਿੰਟ ਬਣਾਉਣ ਲਈ ਮੁੱਖ ਖਣਿਜ ਕੱਚਾ ਮਾਲ ਕਿਹੜਾ ਹੈ?",["ਅਬਰਕ","ਬਾਕਸਾਈਟ","ਚੂਨਾ ਪੱਥਰ","ਕ੍ਰੋਮਾਈਟ"],"ਸੀਮਿੰਟ ਬਣਾਉਣ ਲਈ ਕੈਲਸ਼ੀਅਮ ਭਰਪੂਰ ਸਮੱਗਰੀ ਚੂਨਾ ਪੱਥਰ ਤੋਂ ਮਿਲਦੀ ਹੈ।"]},
"GEO-IND-001-CP005-Q002":{"h":"e1b2d4a7","hi":["सीमेंट के जमने का समय नियंत्रित करने के लिए कौन-सा खनिज मिलाया जाता है?",["मैंगनीज़","ताँबा","बेराइट","जिप्सम"],"सीमेंट बनाते समय उसके जमने का समय नियंत्रित करने के लिए थोड़ी मात्रा में जिप्सम मिलाया जाता है।"],"pa":["ਸੀਮਿੰਟ ਦੇ ਜੰਮਣ ਦਾ ਸਮਾਂ ਕਾਬੂ ਵਿੱਚ ਰੱਖਣ ਲਈ ਕਿਹੜਾ ਖਣਿਜ ਮਿਲਾਇਆ ਜਾਂਦਾ ਹੈ?",["ਮੈਂਗਨੀਜ਼","ਤਾਂਬਾ","ਬੇਰਾਈਟ","ਜਿਪਸਮ"],"ਸੀਮਿੰਟ ਬਣਾਉਣ ਵੇਲੇ ਉਸ ਦੇ ਜੰਮਣ ਦਾ ਸਮਾਂ ਕਾਬੂ ਵਿੱਚ ਰੱਖਣ ਲਈ ਥੋੜ੍ਹੀ ਮਾਤਰਾ ਵਿੱਚ ਜਿਪਸਮ ਮਿਲਾਇਆ ਜਾਂਦਾ ਹੈ।"]},
"GEO-IND-001-CP005-Q003":{"h":"8572ff48","hi":["कथनों पर विचार कीजिए: I. चूना पत्थर सीमेंट का प्रमुख कच्चा माल है। II. सीमेंट बनाते समय जिप्सम का उपयोग होता है। कौन-सा/से कथन सही है/हैं?",["I और II दोनों सही हैं","केवल I सही है","केवल II सही है","न तो I और न ही II सही है"],"चूना पत्थर और जिप्सम दोनों सीमेंट उद्योग की महत्वपूर्ण उत्पादन सामग्रियाँ हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਚੂਨਾ ਪੱਥਰ ਸੀਮਿੰਟ ਦਾ ਮੁੱਖ ਕੱਚਾ ਮਾਲ ਹੈ। II. ਸੀਮਿੰਟ ਬਣਾਉਣ ਵੇਲੇ ਜਿਪਸਮ ਵਰਤਿਆ ਜਾਂਦਾ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਚੂਨਾ ਪੱਥਰ ਅਤੇ ਜਿਪਸਮ ਦੋਵੇਂ ਸੀਮਿੰਟ ਉਦਯੋਗ ਲਈ ਅਹਿਮ ਸਮੱਗਰੀ ਹਨ।"]},
"GEO-IND-001-CP005-Q004":{"h":"4508b07d","hi":["कौन-सा उद्योग चूना पत्थर के बड़े निक्षेपों पर सीधे निर्भर है?",["जूट उद्योग","सीमेंट उद्योग","चीनी उद्योग","सूती वस्त्र उद्योग"],"सीमेंट बनाने में बड़ी मात्रा में चूना पत्थर लगता है। इसलिए इस उद्योग की अवस्थिति का चूना पत्थर के वितरण से गहरा संबंध है।"],"pa":["ਕਿਹੜਾ ਉਦਯੋਗ ਚੂਨਾ ਪੱਥਰ ਦੇ ਵੱਡੇ ਭੰਡਾਰਾਂ 'ਤੇ ਸਿੱਧਾ ਨਿਰਭਰ ਹੈ?",["ਜੂਟ ਉਦਯੋਗ","ਸੀਮਿੰਟ ਉਦਯੋਗ","ਖੰਡ ਉਦਯੋਗ","ਸੂਤੀ ਕੱਪੜਾ ਉਦਯੋਗ"],"ਸੀਮਿੰਟ ਬਣਾਉਣ ਲਈ ਵੱਡੀ ਮਾਤਰਾ ਵਿੱਚ ਚੂਨਾ ਪੱਥਰ ਚਾਹੀਦਾ ਹੈ। ਇਸ ਲਈ ਉਦਯੋਗ ਦੀ ਥਾਂ ਦਾ ਚੂਨਾ ਪੱਥਰ ਦੇ ਭੰਡਾਰਾਂ ਨਾਲ ਡੂੰਘਾ ਸਬੰਧ ਹੈ।"]},
"GEO-IND-001-CP005-Q005":{"h":"c2d496c1","hi":["सीमेंट के कच्चे माल के संबंध में कौन-सा युग्म सही सुमेलित है?",["अभ्रक — मुख्य कच्चा माल","कपास — मुख्य खनिज सामग्री","चूना पत्थर — मुख्य कच्चा माल","जूट — गालक"],"चूना पत्थर सीमेंट उत्पादन का मुख्य खनिज कच्चा माल है।"],"pa":["ਸੀਮਿੰਟ ਦੇ ਕੱਚੇ ਮਾਲ ਬਾਰੇ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਅਬਰਕ — ਮੁੱਖ ਕੱਚਾ ਮਾਲ","ਕਪਾਹ — ਮੁੱਖ ਖਣਿਜ ਸਮੱਗਰੀ","ਚੂਨਾ ਪੱਥਰ — ਮੁੱਖ ਕੱਚਾ ਮਾਲ","ਜੂਟ — ਫਲਕਸ"],"ਚੂਨਾ ਪੱਥਰ ਸੀਮਿੰਟ ਬਣਾਉਣ ਲਈ ਮੁੱਖ ਖਣਿਜ ਕੱਚਾ ਮਾਲ ਹੈ।"]},
"GEO-IND-001-CP005-Q006":{"h":"f52d8196","hi":["एक संयंत्र चूना पत्थर, जिप्सम और ईंधन लेकर क्लिंकर और सीमेंट बनाता है। यह कौन-सा उद्योग है?",["चीनी उद्योग","इस्पात उद्योग","जूट उद्योग","सीमेंट उद्योग"],"इन उत्पादन सामग्रियों और क्लिंकर के उत्पादन से सीमेंट संयंत्र की पहचान होती है।"],"pa":["ਇੱਕ ਪਲਾਂਟ ਚੂਨਾ ਪੱਥਰ, ਜਿਪਸਮ ਅਤੇ ਬਾਲਣ ਲੈ ਕੇ ਕਲਿੰਕਰ ਅਤੇ ਸੀਮਿੰਟ ਬਣਾਉਂਦਾ ਹੈ। ਇਹ ਕਿਹੜਾ ਉਦਯੋਗ ਹੈ?",["ਖੰਡ ਉਦਯੋਗ","ਸਟੀਲ ਉਦਯੋਗ","ਜੂਟ ਉਦਯੋਗ","ਸੀਮਿੰਟ ਉਦਯੋਗ"],"ਇਨ੍ਹਾਂ ਸਮੱਗਰੀਆਂ ਦੀ ਵਰਤੋਂ ਅਤੇ ਕਲਿੰਕਰ ਦੇ ਉਤਪਾਦਨ ਤੋਂ ਸੀਮਿੰਟ ਪਲਾਂਟ ਦੀ ਪਛਾਣ ਹੁੰਦੀ ਹੈ।"]},
"GEO-IND-001-CP005-Q007":{"h":"a37149df","hi":["सीमेंट संयंत्र अक्सर चूना पत्थर के निक्षेपों के पास क्यों लगाए जाते हैं?",["सीमेंट में केवल आयातित कपास का उपयोग होता है","चूना पत्थर को ढोना बिल्कुल संभव नहीं है","बाज़ारों का कोई महत्व नहीं है","चूना पत्थर भारी है और बड़ी मात्रा में चाहिए"],"बड़ी मात्रा में चूना पत्थर ढोना महँगा पड़ता है। निक्षेपों के पास संयंत्र लगाने से माल-भाड़ा घट सकता है।"],"pa":["ਸੀਮਿੰਟ ਪਲਾਂਟ ਅਕਸਰ ਚੂਨਾ ਪੱਥਰ ਦੇ ਭੰਡਾਰਾਂ ਦੇ ਨੇੜੇ ਕਿਉਂ ਲਾਏ ਜਾਂਦੇ ਹਨ?",["ਸੀਮਿੰਟ ਵਿੱਚ ਸਿਰਫ਼ ਬਾਹਰੋਂ ਮੰਗਵਾਈ ਕਪਾਹ ਵਰਤੀ ਜਾਂਦੀ ਹੈ","ਚੂਨਾ ਪੱਥਰ ਬਿਲਕੁਲ ਢੋਇਆ ਨਹੀਂ ਜਾ ਸਕਦਾ","ਬਾਜ਼ਾਰਾਂ ਦਾ ਕੋਈ ਮਹੱਤਵ ਨਹੀਂ ਹੈ","ਚੂਨਾ ਪੱਥਰ ਭਾਰਾ ਹੈ ਅਤੇ ਵੱਡੀ ਮਾਤਰਾ ਵਿੱਚ ਚਾਹੀਦਾ ਹੈ"],"ਵੱਡੀ ਮਾਤਰਾ ਵਿੱਚ ਚੂਨਾ ਪੱਥਰ ਢੋਣਾ ਮਹਿੰਗਾ ਪੈਂਦਾ ਹੈ। ਭੰਡਾਰਾਂ ਨੇੜੇ ਪਲਾਂਟ ਲਾਉਣ ਨਾਲ ਮਾਲ-ਭਾੜਾ ਘਟ ਸਕਦਾ ਹੈ।"]},
"GEO-IND-001-CP005-Q008":{"h":"3d4ad535","hi":["चूना पत्थर की खदान के पास सीमेंट संयंत्र लगाने का सबसे सीधा कारण क्या है?",["कच्चे माल की निकटता","पर्यटन","ज्वारीय परास","कपास की आपूर्ति"],"चूना पत्थर मुख्य भारी कच्चा माल है। इसलिए यह संयंत्र कच्चे माल के स्रोत की ओर उन्मुख है।"],"pa":["ਚੂਨਾ ਪੱਥਰ ਦੀ ਖਾਣ ਕੋਲ ਸੀਮਿੰਟ ਪਲਾਂਟ ਲਾਉਣ ਦਾ ਸਭ ਤੋਂ ਸਿੱਧਾ ਕਾਰਨ ਕੀ ਹੈ?",["ਕੱਚੇ ਮਾਲ ਦੀ ਨੇੜਤਾ","ਸੈਰ-ਸਪਾਟਾ","ਜਵਾਰ-ਭਾਟਾ ਅੰਤਰ","ਕਪਾਹ ਦੀ ਸਪਲਾਈ"],"ਚੂਨਾ ਪੱਥਰ ਮੁੱਖ ਭਾਰਾ ਕੱਚਾ ਮਾਲ ਹੈ। ਇਸ ਲਈ ਪਲਾਂਟ ਉਸ ਦੇ ਸਰੋਤ ਨੇੜੇ ਲਾਇਆ ਜਾਂਦਾ ਹੈ।"]},
"GEO-IND-001-CP005-Q009":{"h":"20cbf959","hi":["कथनों पर विचार कीजिए: I. सीमेंट संयंत्र कच्चे माल के स्रोत की ओर उन्मुख हो सकते हैं। II. सीमेंट को बाज़ार तक पहुँचाने में परिवहन का महत्व बना रहता है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","I और II दोनों सही हैं","केवल II सही है","न तो I और न ही II सही है"],"संयंत्रों को चूना पत्थर की निकटता का लाभ मिलता है। तैयार सीमेंट के वितरण के लिए उन्हें कुशल परिवहन भी चाहिए।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਸੀਮਿੰਟ ਪਲਾਂਟ ਕੱਚੇ ਮਾਲ ਦੇ ਸਰੋਤ ਨੇੜੇ ਲੱਗ ਸਕਦੇ ਹਨ। II. ਸੀਮਿੰਟ ਨੂੰ ਬਾਜ਼ਾਰਾਂ ਤੱਕ ਪਹੁੰਚਾਉਣ ਲਈ ਢੋਆ-ਢੁਆਈ ਅਹਿਮ ਰਹਿੰਦੀ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਪਲਾਂਟਾਂ ਨੂੰ ਚੂਨਾ ਪੱਥਰ ਦੇ ਭੰਡਾਰਾਂ ਦੇ ਨੇੜੇ ਹੋਣ ਦਾ ਲਾਭ ਹੁੰਦਾ ਹੈ। ਤਿਆਰ ਸੀਮਿੰਟ ਦੀ ਵੰਡ ਲਈ ਸੁਚੱਜੀ ਢੋਆ-ਢੁਆਈ ਵੀ ਚਾਹੀਦੀ ਹੈ।"]},
"GEO-IND-001-CP005-Q010":{"h":"dc18cf94","hi":["सीमेंट बन जाने के बाद कौन-सा कारक विशेष रूप से महत्वपूर्ण होता है?",["केवल अयस्क का सांद्रण","गन्ने की कटाई","निर्माण क्षेत्र के बाज़ारों तक परिवहन","जूट को पानी में सड़ाना"],"सीमेंट भारी होता है। संयंत्र कच्चे माल के पास हो, तब भी वितरण की व्यवस्था महत्वपूर्ण है।"],"pa":["ਸੀਮਿੰਟ ਬਣ ਜਾਣ ਪਿੱਛੋਂ ਕਿਹੜਾ ਕਾਰਕ ਖ਼ਾਸ ਤੌਰ 'ਤੇ ਅਹਿਮ ਹੁੰਦਾ ਹੈ?",["ਸਿਰਫ਼ ਅਯਸਕ ਵਿੱਚ ਲਾਭਕਾਰੀ ਖਣਿਜ ਦੀ ਮਾਤਰਾ ਵਧਾਉਣੀ","ਗੰਨੇ ਦੀ ਵਾਢੀ","ਉਸਾਰੀ ਦੇ ਬਾਜ਼ਾਰਾਂ ਤੱਕ ਢੋਆ-ਢੁਆਈ","ਜੂਟ ਨੂੰ ਪਾਣੀ ਵਿੱਚ ਗਾਲਣਾ"],"ਸੀਮਿੰਟ ਭਾਰਾ ਹੁੰਦਾ ਹੈ। ਪਲਾਂਟ ਕੱਚੇ ਮਾਲ ਦੇ ਨੇੜੇ ਹੋਣ ਤਾਂ ਵੀ ਤਿਆਰ ਮਾਲ ਦੀ ਵੰਡ ਦਾ ਪ੍ਰਬੰਧ ਅਹਿਮ ਹੈ।"]},
"GEO-IND-001-CP005-Q011":{"h":"084ce34f","hi":["सीमेंट संयंत्र की अवस्थिति के संबंध में कौन-सा युग्म सही सुमेलित है?",["चाय बागान — सीमेंट संयंत्र की अवस्थिति","कपास पट्टी — क्लिंकर का स्रोत","जूट पट्टी — चूना पत्थर का स्रोत","चूना पत्थर के निक्षेप — स्रोत के पास संयंत्र"],"सीमेंट संयंत्रों की अवस्थिति प्रायः चूना पत्थर के निक्षेपों से निकटता से जुड़ी होती है।"],"pa":["ਸੀਮਿੰਟ ਪਲਾਂਟ ਦੀ ਥਾਂ ਬਾਰੇ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਚਾਹ ਦੇ ਬਾਗ਼ — ਸੀਮਿੰਟ ਪਲਾਂਟ ਦੀ ਥਾਂ","ਕਪਾਹ ਪੱਟੀ — ਕਲਿੰਕਰ ਦਾ ਸਰੋਤ","ਜੂਟ ਪੱਟੀ — ਚੂਨਾ ਪੱਥਰ ਦਾ ਸਰੋਤ","ਚੂਨਾ ਪੱਥਰ ਦੇ ਭੰਡਾਰ — ਸਰੋਤ ਨੇੜੇ ਪਲਾਂਟ"],"ਸੀਮਿੰਟ ਪਲਾਂਟਾਂ ਦੀ ਥਾਂ ਅਕਸਰ ਚੂਨਾ ਪੱਥਰ ਦੇ ਭੰਡਾਰਾਂ ਨਾਲ ਨੇੜਿਓਂ ਜੁੜੀ ਹੁੰਦੀ ਹੈ।"]},
"GEO-IND-001-CP005-Q012":{"h":"c3b7ccb0","hi":["एक सीमेंट कारखाना खदान के पास है और रेल से बड़े शहरों से जुड़ा है। यहाँ किन दो कारकों का मेल है?",["कच्चा माल और बाज़ार तक परिवहन","ज्वारीय ऊर्जा और मत्स्यन","कपास और जूट","चाय और कॉफ़ी"],"संयंत्र चूना पत्थर का माल-भाड़ा कम से कम रखता है और शहरी निर्माण बाज़ारों तक पहुँच बनाए रखता है।"],"pa":["ਇੱਕ ਸੀਮਿੰਟ ਕਾਰਖ਼ਾਨਾ ਖਾਣ ਦੇ ਨੇੜੇ ਹੈ ਅਤੇ ਰੇਲ ਰਾਹੀਂ ਵੱਡੇ ਸ਼ਹਿਰਾਂ ਨਾਲ ਜੁੜਿਆ ਹੈ। ਇੱਥੇ ਕਿਹੜੇ ਦੋ ਕਾਰਕ ਇਕੱਠੇ ਕੰਮ ਕਰਦੇ ਹਨ?",["ਕੱਚਾ ਮਾਲ ਅਤੇ ਬਾਜ਼ਾਰ ਤੱਕ ਢੋਆ-ਢੁਆਈ","ਜਵਾਰ-ਭਾਟੇ ਦੀ ਊਰਜਾ ਅਤੇ ਮੱਛੀ ਫੜਨ ਦਾ ਕੰਮ","ਕਪਾਹ ਅਤੇ ਜੂਟ","ਚਾਹ ਅਤੇ ਕੌਫ਼ੀ"],"ਪਲਾਂਟ ਚੂਨਾ ਪੱਥਰ ਦੀ ਢੋਆ-ਢੁਆਈ ਦਾ ਖ਼ਰਚ ਘੱਟ ਰੱਖਦਾ ਹੈ ਅਤੇ ਸ਼ਹਿਰੀ ਉਸਾਰੀ ਬਾਜ਼ਾਰਾਂ ਤੱਕ ਪਹੁੰਚ ਵੀ ਬਣਾਈ ਰੱਖਦਾ ਹੈ।"]},
"GEO-IND-001-CP005-Q013":{"h":"bc35a27d","hi":["उत्तर-पश्चिमी भारत के किस राज्य का चूना पत्थर आधारित सीमेंट उत्पादन से गहरा संबंध है?",["असम","पंजाब","राजस्थान","केरल"],"राजस्थान में चूना पत्थर के विस्तृत संसाधन हैं और सीमेंट उद्योग बड़े पैमाने पर विकसित है।"],"pa":["ਉੱਤਰ-ਪੱਛਮੀ ਭਾਰਤ ਦਾ ਕਿਹੜਾ ਰਾਜ ਚੂਨਾ ਪੱਥਰ 'ਤੇ ਆਧਾਰਿਤ ਸੀਮਿੰਟ ਉਤਪਾਦਨ ਨਾਲ ਨੇੜਿਓਂ ਜੁੜਿਆ ਹੈ?",["ਅਸਾਮ","ਪੰਜਾਬ","ਰਾਜਸਥਾਨ","ਕੇਰਲ"],"ਰਾਜਸਥਾਨ ਵਿੱਚ ਚੂਨਾ ਪੱਥਰ ਦੇ ਵੱਡੇ ਸਰੋਤ ਹਨ ਅਤੇ ਸੀਮਿੰਟ ਉਦਯੋਗ ਵੱਡੇ ਪੱਧਰ 'ਤੇ ਵਿਕਸਿਤ ਹੈ।"]},
"GEO-IND-001-CP005-Q014":{"h":"6d42ae7b","hi":["राजस्थान सीमेंट विनिर्माण के लिए अनुकूल क्यों है?",["वहाँ खनिज कच्चे माल की कमी है","वह केवल आयातित गन्ने पर निर्भर है","वहाँ परिवहन संपर्क नहीं हैं","वहाँ चूना पत्थर के बड़े संसाधन हैं"],"चूना पत्थर की प्रचुरता से राजस्थान को सीमेंट उत्पादन के लिए कच्चे माल का बड़ा लाभ मिलता है।"],"pa":["ਰਾਜਸਥਾਨ ਵਿੱਚ ਸੀਮਿੰਟ ਬਣਾਉਣ ਲਈ ਹਾਲਾਤ ਅਨੁਕੂਲ ਕਿਉਂ ਹਨ?",["ਉੱਥੇ ਖਣਿਜ ਕੱਚੇ ਮਾਲ ਦੀ ਘਾਟ ਹੈ","ਇਹ ਸਿਰਫ਼ ਬਾਹਰੋਂ ਮੰਗਵਾਏ ਗੰਨੇ 'ਤੇ ਨਿਰਭਰ ਹੈ","ਇੱਥੇ ਆਵਾਜਾਈ ਦੇ ਸੰਪਰਕ ਨਹੀਂ ਹਨ","ਇੱਥੇ ਚੂਨਾ ਪੱਥਰ ਦੇ ਵੱਡੇ ਸਰੋਤ ਹਨ"],"ਚੂਨਾ ਪੱਥਰ ਦੀ ਬਹੁਤਾਤ ਸਦਕਾ ਰਾਜਸਥਾਨ ਨੂੰ ਸੀਮਿੰਟ ਲਈ ਕੱਚੇ ਮਾਲ ਦਾ ਵੱਡਾ ਲਾਭ ਮਿਲਦਾ ਹੈ।"]},
"GEO-IND-001-CP005-Q015":{"h":"5b0e1216","hi":["कथनों पर विचार कीजिए: I. राजस्थान में चूना पत्थर के बड़े निक्षेप हैं। II. चूना पत्थर सीमेंट विनिर्माण में काम आता है। कौन-सा/से कथन सही है/हैं?",["I और II दोनों सही हैं","केवल I सही है","केवल II सही है","न तो I और न ही II सही है"],"राजस्थान के औद्योगिक भूगोल में ये दोनों तथ्य सीधे जुड़े हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਰਾਜਸਥਾਨ ਵਿੱਚ ਚੂਨਾ ਪੱਥਰ ਦੇ ਵੱਡੇ ਭੰਡਾਰ ਹਨ। II. ਚੂਨਾ ਪੱਥਰ ਸੀਮਿੰਟ ਬਣਾਉਣ ਦੇ ਕੰਮ ਆਉਂਦਾ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਰਾਜਸਥਾਨ ਦੇ ਉਦਯੋਗਿਕ ਭੂਗੋਲ ਵਿੱਚ ਇਨ੍ਹਾਂ ਦੋਵਾਂ ਤੱਥਾਂ ਦਾ ਸਿੱਧਾ ਸਬੰਧ ਹੈ।"]},
"GEO-IND-001-CP005-Q016":{"h":"bd087a11","hi":["राजस्थान में सीमेंट और उसके संसाधनों के भूगोल को कौन-सा युग्म सही दर्शाता है?",["राजस्थान — केवल जूट","राजस्थान — चूना पत्थर और सीमेंट","राजस्थान — सीमेंट उद्योग का अभाव","राजस्थान — केवल अपतटीय तेल"],"राजस्थान चूना पत्थर और सीमेंट के लिए प्रमुख राज्य है।"],"pa":["ਕਿਹੜਾ ਜੋੜਾ ਰਾਜਸਥਾਨ ਦੇ ਸੀਮਿੰਟ ਉਦਯੋਗ ਅਤੇ ਉਸ ਦੇ ਸਰੋਤਾਂ ਨੂੰ ਸਹੀ ਦਰਸਾਉਂਦਾ ਹੈ?",["ਰਾਜਸਥਾਨ — ਸਿਰਫ਼ ਜੂਟ","ਰਾਜਸਥਾਨ — ਚੂਨਾ ਪੱਥਰ ਅਤੇ ਸੀਮਿੰਟ","ਰਾਜਸਥਾਨ — ਸੀਮਿੰਟ ਉਦਯੋਗ ਦੀ ਅਣਹੋਂਦ","ਰਾਜਸਥਾਨ — ਸਿਰਫ਼ ਸਮੁੰਦਰੀ ਤੇਲ"],"ਰਾਜਸਥਾਨ ਚੂਨਾ ਪੱਥਰ ਅਤੇ ਸੀਮਿੰਟ ਲਈ ਪ੍ਰਮੁੱਖ ਰਾਜ ਹੈ।"]},
"GEO-IND-001-CP005-Q017":{"h":"31ce02a9","hi":["एक मानचित्र में चूना पत्थर से समृद्ध उत्तर-पश्चिमी भारत में सीमेंट की एक प्रमुख पट्टी दिखाई गई है। कौन-सा राज्य उपयुक्त उत्तर है?",["नागालैंड","मणिपुर","राजस्थान","त्रिपुरा"],"राजस्थान देश के सबसे प्रसिद्ध चूना पत्थर-समृद्ध सीमेंट क्षेत्रों में से एक है।"],"pa":["ਇੱਕ ਨਕਸ਼ੇ ਵਿੱਚ ਚੂਨਾ ਪੱਥਰ ਨਾਲ ਭਰਪੂਰ ਉੱਤਰ-ਪੱਛਮੀ ਭਾਰਤ ਵਿੱਚ ਸੀਮਿੰਟ ਦੀ ਇੱਕ ਪ੍ਰਮੁੱਖ ਪੱਟੀ ਦਿਖਾਈ ਗਈ ਹੈ। ਕਿਹੜਾ ਰਾਜ ਢੁੱਕਵਾਂ ਉੱਤਰ ਹੈ?",["ਨਾਗਾਲੈਂਡ","ਮਣੀਪੁਰ","ਰਾਜਸਥਾਨ","ਤ੍ਰਿਪੁਰਾ"],"ਰਾਜਸਥਾਨ ਚੂਨਾ ਪੱਥਰ ਨਾਲ ਭਰਪੂਰ ਦੇਸ਼ ਦੇ ਸਭ ਤੋਂ ਮਸ਼ਹੂਰ ਸੀਮਿੰਟ ਖੇਤਰਾਂ ਵਿੱਚੋਂ ਇੱਕ ਹੈ।"]},
"GEO-IND-001-CP005-Q018":{"h":"5478eded","hi":["राजस्थान के लिए संसाधन से उद्योग तक का कौन-सा क्रम सही है?",["अभ्रक → चीनी","कपास → इस्पात","जूट → ऐलुमिनियम","चूना पत्थर → सीमेंट"],"चूना पत्थर सीमेंट का मुख्य कच्चा माल है और राजस्थान में प्रचुर मात्रा में मिलता है।"],"pa":["ਰਾਜਸਥਾਨ ਲਈ ਸਰੋਤ ਤੋਂ ਉਦਯੋਗ ਤੱਕ ਕਿਹੜੀ ਲੜੀ ਸਹੀ ਹੈ?",["ਅਬਰਕ → ਖੰਡ","ਕਪਾਹ → ਸਟੀਲ","ਜੂਟ → ਐਲੂਮੀਨੀਅਮ","ਚੂਨਾ ਪੱਥਰ → ਸੀਮਿੰਟ"],"ਚੂਨਾ ਪੱਥਰ ਸੀਮਿੰਟ ਦਾ ਮੁੱਖ ਕੱਚਾ ਮਾਲ ਹੈ ਅਤੇ ਰਾਜਸਥਾਨ ਵਿੱਚ ਭਰਪੂਰ ਮਾਤਰਾ ਵਿੱਚ ਮਿਲਦਾ ਹੈ।"]},
"GEO-IND-001-CP005-Q019":{"h":"deeabcd5","hi":["मध्य भारत के किस राज्य में चूना पत्थर के बड़े संसाधन हैं, जिनसे सीमेंट उद्योग को आधार मिलता है?",["पंजाब","असम","मध्य प्रदेश","केवल गोवा"],"मध्य प्रदेश में चूना पत्थर के बड़े निक्षेप हैं और सीमेंट उद्योग की महत्वपूर्ण गतिविधियाँ होती हैं।"],"pa":["ਮੱਧ ਭਾਰਤ ਦੇ ਕਿਹੜੇ ਰਾਜ ਵਿੱਚ ਚੂਨਾ ਪੱਥਰ ਦੇ ਵੱਡੇ ਸਰੋਤ ਸੀਮਿੰਟ ਉਤਪਾਦਨ ਨੂੰ ਆਧਾਰ ਦਿੰਦੇ ਹਨ?",["ਪੰਜਾਬ","ਅਸਾਮ","ਮੱਧ ਪ੍ਰਦੇਸ਼","ਸਿਰਫ਼ ਗੋਆ"],"ਮੱਧ ਪ੍ਰਦੇਸ਼ ਵਿੱਚ ਚੂਨਾ ਪੱਥਰ ਦੇ ਵੱਡੇ ਭੰਡਾਰ ਹਨ ਅਤੇ ਸੀਮਿੰਟ ਉਦਯੋਗ ਦੀਆਂ ਅਹਿਮ ਸਰਗਰਮੀਆਂ ਹੁੰਦੀਆਂ ਹਨ।"]},
"GEO-IND-001-CP005-Q020":{"h":"a5af4f9a","hi":["पश्चिमी भारत के किस राज्य में चूना पत्थर के संसाधन और प्रमुख सीमेंट उद्योग दोनों हैं?",["सिक्किम","नागालैंड","त्रिपुरा","गुजरात"],"गुजरात में चूना पत्थर के निक्षेप, औद्योगिक आधारभूत संरचना और बाज़ारों व पत्तनों से अच्छे संपर्क हैं।"],"pa":["ਪੱਛਮੀ ਭਾਰਤ ਦੇ ਕਿਹੜੇ ਰਾਜ ਵਿੱਚ ਚੂਨਾ ਪੱਥਰ ਦੇ ਸਰੋਤ ਅਤੇ ਪ੍ਰਮੁੱਖ ਸੀਮਿੰਟ ਉਦਯੋਗ ਦੋਵੇਂ ਹਨ?",["ਸਿੱਕਮ","ਨਾਗਾਲੈਂਡ","ਤ੍ਰਿਪੁਰਾ","ਗੁਜਰਾਤ"],"ਗੁਜਰਾਤ ਵਿੱਚ ਚੂਨਾ ਪੱਥਰ ਦੇ ਭੰਡਾਰ, ਉਦਯੋਗਿਕ ਬੁਨਿਆਦੀ ਢਾਂਚਾ ਅਤੇ ਬਾਜ਼ਾਰਾਂ ਤੇ ਬੰਦਰਗਾਹਾਂ ਨਾਲ ਚੰਗੇ ਸੰਪਰਕ ਹਨ।"]},
"GEO-IND-001-CP005-Q021":{"h":"a089d7e6","hi":["कथनों पर विचार कीजिए: I. मध्य प्रदेश सीमेंट उत्पादन के लिए महत्वपूर्ण है। II. गुजरात भी बड़े पैमाने पर सीमेंट का उत्पादन करता है। कौन-सा/से कथन सही है/हैं?",["I और II दोनों सही हैं","केवल I सही है","केवल II सही है","न तो I और न ही II सही है"],"दोनों राज्यों में चूना पत्थर और सीमेंट उद्योग का संबंध लंबे समय से बना हुआ है।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਮੱਧ ਪ੍ਰਦੇਸ਼ ਸੀਮਿੰਟ ਉਤਪਾਦਨ ਲਈ ਮਹੱਤਵਪੂਰਨ ਹੈ। II. ਗੁਜਰਾਤ ਵੀ ਵੱਡੇ ਪੱਧਰ 'ਤੇ ਸੀਮਿੰਟ ਬਣਾਉਂਦਾ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਦੋਵੇਂ ਰਾਜਾਂ ਵਿੱਚ ਚੂਨਾ ਪੱਥਰ ਅਤੇ ਸੀਮਿੰਟ ਉਦਯੋਗ ਦਾ ਸਬੰਧ ਲੰਮੇ ਸਮੇਂ ਤੋਂ ਕਾਇਮ ਹੈ।"]},
"GEO-IND-001-CP005-Q022":{"h":"b96fbf1b","hi":["कौन-सा युग्म मध्य भारत के एक सीमेंट क्षेत्र की सही पहचान करता है?",["मध्य प्रदेश — केवल जूट","मध्य प्रदेश — चूना पत्थर आधारित सीमेंट","गुजरात — चूना पत्थर का अभाव","गुजरात — केवल चाय प्रसंस्करण"],"मध्य प्रदेश चूना पत्थर आधारित सीमेंट का प्रमुख क्षेत्र है। गुजरात में भी महत्वपूर्ण सीमेंट उद्योग है।"],"pa":["ਕਿਹੜਾ ਜੋੜਾ ਮੱਧ ਭਾਰਤ ਦੇ ਇੱਕ ਸੀਮਿੰਟ ਖੇਤਰ ਦੀ ਸਹੀ ਪਛਾਣ ਕਰਦਾ ਹੈ?",["ਮੱਧ ਪ੍ਰਦੇਸ਼ — ਸਿਰਫ਼ ਜੂਟ","ਮੱਧ ਪ੍ਰਦੇਸ਼ — ਚੂਨਾ ਪੱਥਰ 'ਤੇ ਆਧਾਰਿਤ ਸੀਮਿੰਟ","ਗੁਜਰਾਤ — ਚੂਨਾ ਪੱਥਰ ਦੀ ਅਣਹੋਂਦ","ਗੁਜਰਾਤ — ਸਿਰਫ਼ ਚਾਹ ਦੀ ਪ੍ਰੋਸੈਸਿੰਗ"],"ਮੱਧ ਪ੍ਰਦੇਸ਼ ਚੂਨਾ ਪੱਥਰ 'ਤੇ ਆਧਾਰਿਤ ਸੀਮਿੰਟ ਦਾ ਪ੍ਰਮੁੱਖ ਖੇਤਰ ਹੈ। ਗੁਜਰਾਤ ਵਿੱਚ ਵੀ ਸੀਮਿੰਟ ਉਦਯੋਗ ਅਹਿਮ ਹੈ।"]},
"GEO-IND-001-CP005-Q023":{"h":"9ba813b7","hi":["कच्चे माल की उपलब्धता के अलावा गुजरात में बड़े सीमेंट संयंत्रों के लिए क्या अनुकूल है?",["वहाँ परिवहन नहीं है","वहाँ बाज़ारों की कमी है","पत्तन, परिवहन और बड़े बाज़ार अवस्थिति के अतिरिक्त लाभ देते हैं","वह केवल वनों पर निर्भर है"],"औद्योगिक आधारभूत संरचना और बाज़ार तक पहुँच गुजरात के कच्चे माल के आधार को और मज़बूत करती हैं।"],"pa":["ਕੱਚੇ ਮਾਲ ਦੀ ਉਪਲਬਧਤਾ ਤੋਂ ਇਲਾਵਾ ਗੁਜਰਾਤ ਵਿੱਚ ਵੱਡੇ ਸੀਮਿੰਟ ਪਲਾਂਟਾਂ ਲਈ ਕੀ ਅਨੁਕੂਲ ਹੈ?",["ਉੱਥੇ ਆਵਾਜਾਈ ਨਹੀਂ ਹੈ","ਉੱਥੇ ਬਾਜ਼ਾਰਾਂ ਦੀ ਘਾਟ ਹੈ","ਬੰਦਰਗਾਹਾਂ, ਆਵਾਜਾਈ ਅਤੇ ਵੱਡੇ ਬਾਜ਼ਾਰ ਥਾਂ ਦਾ ਵਾਧੂ ਲਾਭ ਦਿੰਦੇ ਹਨ","ਇਹ ਸਿਰਫ਼ ਜੰਗਲਾਂ 'ਤੇ ਨਿਰਭਰ ਹੈ"],"ਕੱਚੇ ਮਾਲ ਦੇ ਨਾਲ ਉਦਯੋਗਿਕ ਬੁਨਿਆਦੀ ਢਾਂਚਾ ਅਤੇ ਬਾਜ਼ਾਰਾਂ ਤੱਕ ਪਹੁੰਚ ਵੀ ਗੁਜਰਾਤ ਦੇ ਹੱਕ ਵਿੱਚ ਜਾਂਦੇ ਹਨ।"]},
"GEO-IND-001-CP005-Q024":{"h":"234ef429","hi":["सीमेंट उद्योग के भूगोल में कौन-सी तुलना सही है?",["दोनों केवल जूट उत्पादक क्षेत्र हैं","दोनों में चूना पत्थर नहीं है","दोनों केवल आयातित क्लिंकर पर निर्भर हैं","राजस्थान और मध्य प्रदेश दोनों में चूना पत्थर आधारित सीमेंट के प्रमुख क्षेत्र हैं"],"दोनों राज्य चूना पत्थर से समृद्ध महत्वपूर्ण सीमेंट क्षेत्र हैं।"],"pa":["ਸੀਮਿੰਟ ਉਦਯੋਗ ਦੇ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜੀ ਤੁਲਨਾ ਸਹੀ ਹੈ?",["ਦੋਵੇਂ ਸਿਰਫ਼ ਜੂਟ ਵਾਲੇ ਖੇਤਰ ਹਨ","ਦੋਵਾਂ ਵਿੱਚ ਚੂਨਾ ਪੱਥਰ ਨਹੀਂ ਹੈ","ਦੋਵੇਂ ਸਿਰਫ਼ ਬਾਹਰੋਂ ਮੰਗਵਾਏ ਕਲਿੰਕਰ 'ਤੇ ਨਿਰਭਰ ਹਨ","ਰਾਜਸਥਾਨ ਅਤੇ ਮੱਧ ਪ੍ਰਦੇਸ਼ ਦੋਵਾਂ ਵਿੱਚ ਚੂਨਾ ਪੱਥਰ 'ਤੇ ਆਧਾਰਿਤ ਸੀਮਿੰਟ ਦੇ ਪ੍ਰਮੁੱਖ ਖੇਤਰ ਹਨ"],"ਦੋਵੇਂ ਰਾਜ ਚੂਨਾ ਪੱਥਰ ਨਾਲ ਭਰਪੂਰ ਮਹੱਤਵਪੂਰਨ ਸੀਮਿੰਟ ਖੇਤਰ ਹਨ।"]},
"GEO-IND-001-CP005-Q025":{"h":"1646e213","hi":["सीमेंट बनाने में बहुत ऊर्जा क्यों लगती है?",["सीमेंट खेतों में उगता है","ऊष्मा का उपयोग नहीं होता","केवल सूर्य का प्रकाश चाहिए","क्लिंकर बनाने के लिए कच्चे माल को बहुत अधिक तापमान तक गर्म करना पड़ता है"],"क्लिंकर उत्पादन के लिए उच्च तापमान वाली भट्टियाँ चाहिए। इसलिए ऊर्जा एक प्रमुख उत्पादन सामग्री है।"],"pa":["ਸੀਮਿੰਟ ਬਣਾਉਣ ਲਈ ਬਹੁਤ ਊਰਜਾ ਕਿਉਂ ਲੱਗਦੀ ਹੈ?",["ਸੀਮਿੰਟ ਖੇਤਾਂ ਵਿੱਚ ਉੱਗਦਾ ਹੈ","ਗਰਮੀ ਨਹੀਂ ਵਰਤੀ ਜਾਂਦੀ","ਸਿਰਫ਼ ਧੁੱਪ ਚਾਹੀਦੀ ਹੈ","ਕਲਿੰਕਰ ਬਣਾਉਣ ਲਈ ਕੱਚੇ ਮਾਲ ਨੂੰ ਬਹੁਤ ਉੱਚੇ ਤਾਪਮਾਨ ਤੱਕ ਗਰਮ ਕਰਨਾ ਪੈਂਦਾ ਹੈ"],"ਕਲਿੰਕਰ ਬਣਾਉਣ ਲਈ ਉੱਚੇ ਤਾਪਮਾਨ ਵਾਲੀਆਂ ਭੱਠੀਆਂ ਵਰਤੀਆਂ ਜਾਂਦੀਆਂ ਹਨ। ਇਸ ਲਈ ਊਰਜਾ ਇੱਕ ਮੁੱਖ ਲੋੜ ਹੈ।"]},
"GEO-IND-001-CP005-Q026":{"h":"3e219f7c","hi":["सीमेंट उत्पादन के किस चरण में विशेष रूप से अधिक ऊर्जा लगती है?",["भट्टियों में क्लिंकर उत्पादन","केवल खुदरा बिक्री","केवल पैकिंग","केवल चूना पत्थर का मानचित्रण"],"कच्चे पिसे मिश्रण को क्लिंकर में बदलने के लिए भट्टियों में बहुत अधिक ऊष्मा चाहिए।"],"pa":["ਸੀਮਿੰਟ ਉਤਪਾਦਨ ਦੇ ਕਿਹੜੇ ਪੜਾਅ ਵਿੱਚ ਖ਼ਾਸ ਤੌਰ 'ਤੇ ਵੱਧ ਊਰਜਾ ਲੱਗਦੀ ਹੈ?",["ਭੱਠੀਆਂ ਵਿੱਚ ਕਲਿੰਕਰ ਬਣਾਉਣਾ","ਸਿਰਫ਼ ਪਰਚੂਨ ਵਿਕਰੀ","ਸਿਰਫ਼ ਪੈਕਿੰਗ","ਸਿਰਫ਼ ਚੂਨਾ ਪੱਥਰ ਦਾ ਨਕਸ਼ਾ ਬਣਾਉਣਾ"],"ਪੀਸੇ ਕੱਚੇ ਮਿਸ਼ਰਣ ਨੂੰ ਕਲਿੰਕਰ ਵਿੱਚ ਬਦਲਣ ਲਈ ਭੱਠੀਆਂ ਵਿੱਚ ਬਹੁਤ ਗਰਮੀ ਚਾਹੀਦੀ ਹੈ।"]},
"GEO-IND-001-CP005-Q027":{"h":"13c348dd","hi":["कथनों पर विचार कीजिए: I. सीमेंट संयंत्रों को भट्टियों के लिए ऊर्जा चाहिए। II. सीमेंट भारी है, इसलिए परिवहन महत्वपूर्ण है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","I और II दोनों सही हैं","केवल II सही है","न तो I और न ही II सही है"],"ऊर्जा की खपत और माल ढुलाई की ज़रूरत, दोनों सीमेंट उत्पादन की लागत और अवस्थिति को प्रभावित करती हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਸੀਮਿੰਟ ਪਲਾਂਟਾਂ ਨੂੰ ਭੱਠੀਆਂ ਲਈ ਊਰਜਾ ਚਾਹੀਦੀ ਹੈ। II. ਸੀਮਿੰਟ ਭਾਰਾ ਹੋਣ ਕਰਕੇ ਢੋਆ-ਢੁਆਈ ਅਹਿਮ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਊਰਜਾ ਦੀ ਖਪਤ ਅਤੇ ਢੋਆ-ਢੁਆਈ ਦੀ ਲੋੜ ਦੋਵੇਂ ਸੀਮਿੰਟ ਉਦਯੋਗ ਦੇ ਅਰਥਚਾਰੇ ਅਤੇ ਥਾਂ 'ਤੇ ਅਸਰ ਪਾਉਂਦੀਆਂ ਹਨ।"]},
"GEO-IND-001-CP005-Q028":{"h":"a34ed58c","hi":["स्थल मार्ग से बड़ी मात्रा में सीमेंट ढोने के लिए कौन-सा साधन उपयोगी है?",["केवल हवाई माल ढुलाई","केवल पाइपलाइन","रेल से माल ढुलाई","केवल पशुओं से ढुलाई"],"रेल से सीमेंट और अन्य भारी औद्योगिक माल की बड़ी मात्रा में कुशलतापूर्वक ढुलाई की जा सकती है।"],"pa":["ਜ਼ਮੀਨੀ ਰਸਤੇ ਰਾਹੀਂ ਵੱਡੀ ਮਾਤਰਾ ਵਿੱਚ ਸੀਮਿੰਟ ਢੋਣ ਲਈ ਕਿਹੜਾ ਸਾਧਨ ਲਾਹੇਵੰਦ ਹੈ?",["ਸਿਰਫ਼ ਹਵਾਈ ਢੋਆ-ਢੁਆਈ","ਸਿਰਫ਼ ਪਾਈਪਲਾਈਨਾਂ","ਰੇਲ ਰਾਹੀਂ ਢੋਆ-ਢੁਆਈ","ਸਿਰਫ਼ ਪਸ਼ੂਆਂ ਨਾਲ ਢੋਆ-ਢੁਆਈ"],"ਸੀਮਿੰਟ ਅਤੇ ਹੋਰ ਭਾਰੇ ਉਦਯੋਗਿਕ ਮਾਲ ਨੂੰ ਵੱਡੀ ਮਾਤਰਾ ਵਿੱਚ ਢੋਣ ਲਈ ਰੇਲ ਸੁਚੱਜਾ ਸਾਧਨ ਹੈ।"]},
"GEO-IND-001-CP005-Q029":{"h":"c706379a","hi":["सीमेंट उत्पादन में कौन-सा युग्म सही सुमेलित है?",["क्लिंकर भट्टी — कपास की कताई","जिप्सम — चीनी का परिष्करण","चूना पत्थर — जूट को पानी में सड़ाना","क्लिंकर भट्टी — अधिक ऊर्जा खपत"],"ऊँचे तापमान पर क्लिंकर बनाना सीमेंट विनिर्माण की मुख्य प्रक्रिया है।"],"pa":["ਸੀਮਿੰਟ ਉਤਪਾਦਨ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਕਲਿੰਕਰ ਭੱਠੀ — ਕਪਾਹ ਦੀ ਕਤਾਈ","ਜਿਪਸਮ — ਖੰਡ ਦੀ ਸੋਧਾਈ","ਚੂਨਾ ਪੱਥਰ — ਜੂਟ ਨੂੰ ਪਾਣੀ ਵਿੱਚ ਗਾਲਣਾ","ਕਲਿੰਕਰ ਭੱਠੀ — ਵੱਧ ਊਰਜਾ ਦੀ ਖਪਤ"],"ਉੱਚੇ ਤਾਪਮਾਨ 'ਤੇ ਕਲਿੰਕਰ ਬਣਾਉਣਾ ਸੀਮਿੰਟ ਨਿਰਮਾਣ ਦੀ ਮੁੱਖ ਪ੍ਰਕਿਰਿਆ ਹੈ।"]},
"GEO-IND-001-CP005-Q030":{"h":"5dd8ad4a","hi":["एक संयंत्र के पास चूना पत्थर, भरोसेमंद बिजली और रेलवे साइडिंग है। कौन-सा उद्योग सबसे उपयुक्त है?",["सीमेंट","जूट वस्त्र","चीनी","चाय प्रसंस्करण"],"चूना पत्थर, ऊर्जा और बड़ी मात्रा में माल ढोने की सुविधा का मेल स्पष्ट रूप से सीमेंट विनिर्माण की ओर संकेत करता है।"],"pa":["ਇੱਕ ਪਲਾਂਟ ਦੇ ਨੇੜੇ ਚੂਨਾ ਪੱਥਰ ਹੈ ਅਤੇ ਉਸ ਕੋਲ ਭਰੋਸੇਯੋਗ ਬਿਜਲੀ ਤੇ ਰੇਲਵੇ ਸਾਈਡਿੰਗ ਹੈ। ਕਿਹੜਾ ਉਦਯੋਗ ਸਭ ਤੋਂ ਢੁੱਕਵਾਂ ਹੈ?",["ਸੀਮਿੰਟ","ਜੂਟ ਦਾ ਕੱਪੜਾ","ਖੰਡ","ਚਾਹ ਦੀ ਪ੍ਰੋਸੈਸਿੰਗ"],"ਚੂਨਾ ਪੱਥਰ, ਊਰਜਾ ਅਤੇ ਵੱਡੀ ਮਾਤਰਾ ਵਿੱਚ ਮਾਲ ਢੋਣ ਦੀ ਸਹੂਲਤ ਦਾ ਮੇਲ ਸਾਫ਼ ਤੌਰ 'ਤੇ ਸੀਮਿੰਟ ਨਿਰਮਾਣ ਵੱਲ ਇਸ਼ਾਰਾ ਕਰਦਾ ਹੈ।"]},
"GEO-IND-001-CP005-Q031":{"h":"05424943","hi":["मध्य-पूर्वी भारत के किस राज्य में चूना पत्थर के बड़े संसाधन और विकसित सीमेंट उद्योग दोनों हैं?",["छत्तीसगढ़","पंजाब","असम","केरल"],"छत्तीसगढ़ में चूना पत्थर के पर्याप्त संसाधन हैं, जिनसे सीमेंट विनिर्माण को आधार मिलता है।"],"pa":["ਮੱਧ-ਪੂਰਬੀ ਭਾਰਤ ਦੇ ਕਿਹੜੇ ਰਾਜ ਵਿੱਚ ਚੂਨਾ ਪੱਥਰ ਦੇ ਵੱਡੇ ਸਰੋਤ ਅਤੇ ਵਿਕਸਿਤ ਸੀਮਿੰਟ ਉਦਯੋਗ ਦੋਵੇਂ ਹਨ?",["ਛੱਤੀਸਗੜ੍ਹ","ਪੰਜਾਬ","ਅਸਾਮ","ਕੇਰਲ"],"ਛੱਤੀਸਗੜ੍ਹ ਵਿੱਚ ਚੂਨਾ ਪੱਥਰ ਦੇ ਵੱਡੇ ਸਰੋਤ ਹਨ, ਜੋ ਸੀਮਿੰਟ ਨਿਰਮਾਣ ਨੂੰ ਆਧਾਰ ਦਿੰਦੇ ਹਨ।"]},
"GEO-IND-001-CP005-Q032":{"h":"da94d9a3","hi":["छत्तीसगढ़ सीमेंट संयंत्रों के लिए अनुकूल क्यों है?",["वहाँ खनिज संसाधन नहीं हैं","चूना पत्थर और ऊर्जा संसाधन उपलब्ध हैं","केवल जूट का महत्व है","केवल पत्तनों का महत्व है"],"राज्य में चूना पत्थर के साथ कोयला, बिजली और औद्योगिक आधारभूत संरचना भी है।"],"pa":["ਛੱਤੀਸਗੜ੍ਹ ਵਿੱਚ ਸੀਮਿੰਟ ਪਲਾਂਟਾਂ ਲਈ ਹਾਲਾਤ ਅਨੁਕੂਲ ਕਿਉਂ ਹਨ?",["ਇੱਥੇ ਖਣਿਜ ਸਰੋਤ ਨਹੀਂ ਹਨ","ਚੂਨਾ ਪੱਥਰ ਅਤੇ ਊਰਜਾ ਦੇ ਸਰੋਤ ਮਿਲਦੇ ਹਨ","ਸਿਰਫ਼ ਜੂਟ ਦਾ ਮਹੱਤਵ ਹੈ","ਸਿਰਫ਼ ਬੰਦਰਗਾਹਾਂ ਦਾ ਮਹੱਤਵ ਹੈ"],"ਇਸ ਰਾਜ ਵਿੱਚ ਚੂਨਾ ਪੱਥਰ ਦੇ ਨਾਲ ਕੋਲਾ, ਬਿਜਲੀ ਅਤੇ ਉਦਯੋਗਿਕ ਬੁਨਿਆਦੀ ਢਾਂਚਾ ਵੀ ਹੈ।"]},
"GEO-IND-001-CP005-Q033":{"h":"16a2bc2e","hi":["कथनों पर विचार कीजिए: I. छत्तीसगढ़ में चूना पत्थर है। II. चूना पत्थर सीमेंट बनाने में काम आता है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","I और II दोनों सही हैं","न तो I और न ही II सही है"],"राज्य के चूना पत्थर संसाधनों का सीमेंट उद्योग के विकास से सीधा संबंध है।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਛੱਤੀਸਗੜ੍ਹ ਵਿੱਚ ਚੂਨਾ ਪੱਥਰ ਹੈ। II. ਚੂਨਾ ਪੱਥਰ ਸੀਮਿੰਟ ਬਣਾਉਣ ਦੇ ਕੰਮ ਆਉਂਦਾ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਰਾਜ ਦੇ ਚੂਨਾ ਪੱਥਰ ਦੇ ਭੰਡਾਰਾਂ ਦਾ ਸੀਮਿੰਟ ਉਦਯੋਗ ਦੇ ਵਿਕਾਸ ਨਾਲ ਸਿੱਧਾ ਸਬੰਧ ਹੈ।"]},
"GEO-IND-001-CP005-Q034":{"h":"445f476d","hi":["छत्तीसगढ़ के औद्योगिक भूगोल में कौन-सा युग्म सही सुमेलित है?",["छत्तीसगढ़ — केवल जूट","छत्तीसगढ़ — चूना पत्थर का अभाव","छत्तीसगढ़ — केवल चाय","छत्तीसगढ़ — चूना पत्थर आधारित सीमेंट"],"छत्तीसगढ़ चूना पत्थर आधारित सीमेंट का एक प्रमुख क्षेत्र है।"],"pa":["ਛੱਤੀਸਗੜ੍ਹ ਦੇ ਉਦਯੋਗਿਕ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਛੱਤੀਸਗੜ੍ਹ — ਸਿਰਫ਼ ਜੂਟ","ਛੱਤੀਸਗੜ੍ਹ — ਚੂਨਾ ਪੱਥਰ ਦੀ ਅਣਹੋਂਦ","ਛੱਤੀਸਗੜ੍ਹ — ਸਿਰਫ਼ ਚਾਹ","ਛੱਤੀਸਗੜ੍ਹ — ਚੂਨਾ ਪੱਥਰ 'ਤੇ ਆਧਾਰਿਤ ਸੀਮਿੰਟ"],"ਛੱਤੀਸਗੜ੍ਹ ਚੂਨਾ ਪੱਥਰ 'ਤੇ ਆਧਾਰਿਤ ਸੀਮਿੰਟ ਦਾ ਪ੍ਰਮੁੱਖ ਖੇਤਰ ਹੈ।"]},
"GEO-IND-001-CP005-Q035":{"h":"4472decb","hi":["सीमेंट उद्योग के एक मानचित्र में रायपुर और दुर्ग वाले राज्य को दर्शाया गया है। वह कौन-सा राज्य है?",["छत्तीसगढ़","हरियाणा","पंजाब","केरल"],"रायपुर और दुर्ग छत्तीसगढ़ की चूना पत्थर-समृद्ध औद्योगिक पट्टी में हैं।"],"pa":["ਸੀਮਿੰਟ ਉਦਯੋਗ ਦੇ ਨਕਸ਼ੇ ਵਿੱਚ ਰਾਏਪੁਰ ਅਤੇ ਦੁਰਗ ਵਾਲਾ ਰਾਜ ਦਿਖਾਇਆ ਗਿਆ ਹੈ। ਉਹ ਕਿਹੜਾ ਰਾਜ ਹੈ?",["ਛੱਤੀਸਗੜ੍ਹ","ਹਰਿਆਣਾ","ਪੰਜਾਬ","ਕੇਰਲ"],"ਰਾਏਪੁਰ ਅਤੇ ਦੁਰਗ ਛੱਤੀਸਗੜ੍ਹ ਦੀ ਚੂਨਾ ਪੱਥਰ ਨਾਲ ਭਰਪੂਰ ਉਦਯੋਗਿਕ ਪੱਟੀ ਵਿੱਚ ਹਨ।"]},
"GEO-IND-001-CP005-Q036":{"h":"52463e35","hi":["मध्य भारत के सीमेंट उद्योग के भूगोल में कौन-सी तुलना सही है?",["दोनों में चूना पत्थर नहीं है","मध्य प्रदेश और छत्तीसगढ़ दोनों में प्रमुख चूना पत्थर आधारित सीमेंट उद्योग हैं","दोनों केवल जूट उत्पादक राज्य हैं","दोनों केवल आयातित क्लिंकर पर निर्भर हैं"],"दोनों राज्यों में चूना पत्थर के बड़े संसाधन और सीमेंट उद्योग हैं।"],"pa":["ਮੱਧ ਭਾਰਤ ਦੇ ਸੀਮਿੰਟ ਉਦਯੋਗ ਦੇ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜੀ ਤੁਲਨਾ ਸਹੀ ਹੈ?",["ਦੋਵਾਂ ਵਿੱਚ ਚੂਨਾ ਪੱਥਰ ਨਹੀਂ ਹੈ","ਮੱਧ ਪ੍ਰਦੇਸ਼ ਅਤੇ ਛੱਤੀਸਗੜ੍ਹ ਦੋਵਾਂ ਵਿੱਚ ਚੂਨਾ ਪੱਥਰ 'ਤੇ ਆਧਾਰਿਤ ਪ੍ਰਮੁੱਖ ਸੀਮਿੰਟ ਉਦਯੋਗ ਹਨ","ਦੋਵੇਂ ਸਿਰਫ਼ ਜੂਟ ਵਾਲੇ ਰਾਜ ਹਨ","ਦੋਵੇਂ ਸਿਰਫ਼ ਬਾਹਰੋਂ ਮੰਗਵਾਏ ਕਲਿੰਕਰ 'ਤੇ ਨਿਰਭਰ ਹਨ"],"ਦੋਵਾਂ ਰਾਜਾਂ ਵਿੱਚ ਚੂਨਾ ਪੱਥਰ ਦੇ ਵੱਡੇ ਸਰੋਤ ਅਤੇ ਸੀਮਿੰਟ ਉਦਯੋਗ ਹਨ।"]},
"GEO-IND-001-CP005-Q037":{"h":"cc5d8ce3","hi":["ताप विद्युत का कौन-सा उपोत्पाद मिश्रित सीमेंट में इस्तेमाल किया जा सकता है?",["गन्ने की खोई","कच्चा जूट","बॉक्साइट अयस्क","उड़न राख"],"उड़न राख का उपयोग पोर्टलैंड पोज़ोलाना सीमेंट और उससे जुड़े मिश्रित उत्पादों में किया जा सकता है।"],"pa":["ਤਾਪ ਬਿਜਲੀ ਦਾ ਕਿਹੜਾ ਉਪ-ਉਤਪਾਦ ਮਿਸ਼ਰਤ ਸੀਮਿੰਟ ਵਿੱਚ ਵਰਤਿਆ ਜਾ ਸਕਦਾ ਹੈ?",["ਗੰਨੇ ਦੀ ਖੋਈ","ਕੱਚਾ ਜੂਟ","ਬਾਕਸਾਈਟ ਅਯਸਕ","ਉੱਡਣ ਵਾਲੀ ਸੁਆਹ"],"ਉੱਡਣ ਵਾਲੀ ਸੁਆਹ ਪੋਰਟਲੈਂਡ ਪੋਜ਼ੋਲਾਨਾ ਸੀਮਿੰਟ ਅਤੇ ਇਸ ਨਾਲ ਜੁੜੇ ਮਿਸ਼ਰਤ ਉਤਪਾਦਾਂ ਵਿੱਚ ਵਰਤੀ ਜਾ ਸਕਦੀ ਹੈ।"]},
"GEO-IND-001-CP005-Q038":{"h":"5b1f1eaf","hi":["लौह-इस्पात उद्योग का कौन-सा उपोत्पाद कुछ मिश्रित सीमेंटों में काम आ सकता है?",["वात्या भट्टी का दानेदार धातुमल","कपास का रेशा","शीरा","कच्चा अभ्रक"],"वात्या भट्टी के दानेदार धातुमल को पीसकर धातुमल सीमेंट में इस्तेमाल किया जा सकता है।"],"pa":["ਲੋਹਾ-ਸਟੀਲ ਉਦਯੋਗ ਦਾ ਕਿਹੜਾ ਉਪ-ਉਤਪਾਦ ਕੁਝ ਮਿਸ਼ਰਤ ਸੀਮਿੰਟਾਂ ਵਿੱਚ ਵਰਤਿਆ ਜਾ ਸਕਦਾ ਹੈ?",["ਬਲਾਸਟ ਫਰਨੇਸ ਦੀ ਦਾਣੇਦਾਰ ਸਲੈਗ","ਕਪਾਹ ਦਾ ਰੇਸ਼ਾ","ਸ਼ੀਰਾ","ਕੱਚਾ ਅਬਰਕ"],"ਬਲਾਸਟ ਫਰਨੇਸ ਦੀ ਦਾਣੇਦਾਰ ਸਲੈਗ ਪੀਸ ਕੇ ਸਲੈਗ ਸੀਮਿੰਟ ਵਿੱਚ ਵਰਤੀ ਜਾ ਸਕਦੀ ਹੈ।"]},
"GEO-IND-001-CP005-Q039":{"h":"f942c85a","hi":["कथनों पर विचार कीजिए: I. उड़न राख का उपयोग मिश्रित सीमेंट में हो सकता है। II. वात्या भट्टी का धातुमल भी सीमेंट बनाने में काम आ सकता है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","I और II दोनों सही हैं","केवल II सही है","न तो I और न ही II सही है"],"दोनों औद्योगिक उपोत्पाद पूरक सीमेंटकारी सामग्री के रूप में काम आ सकते हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਉੱਡਣ ਵਾਲੀ ਸੁਆਹ ਮਿਸ਼ਰਤ ਸੀਮਿੰਟ ਵਿੱਚ ਵਰਤੀ ਜਾ ਸਕਦੀ ਹੈ। II. ਬਲਾਸਟ ਫਰਨੇਸ ਦੀ ਸਲੈਗ ਵੀ ਸੀਮਿੰਟ ਬਣਾਉਣ ਦੇ ਕੰਮ ਆ ਸਕਦੀ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਦੋਵੇਂ ਉਦਯੋਗਿਕ ਉਪ-ਉਤਪਾਦ ਸੀਮਿੰਟ ਬਣਾਉਣ ਲਈ ਪੂਰਕ ਸਮੱਗਰੀ ਵਜੋਂ ਵਰਤੇ ਜਾ ਸਕਦੇ ਹਨ।"]},
"GEO-IND-001-CP005-Q040":{"h":"442b63b1","hi":["निम्नलिखित में से कौन-सा क्रम औद्योगिक सहजीविता को सही दर्शाता है?",["जूट मिल → लौह अयस्क → सीमेंट","चीनी मिल → क्रोमाइट → सीमेंट","ताप विद्युत संयंत्र → उड़न राख → मिश्रित सीमेंट","सूती मिल → यूरेनियम → सीमेंट"],"सीमेंट में उड़न राख का उपयोग करने से एक उद्योग का उपोत्पाद दूसरे उद्योग की उत्पादन सामग्री बन जाता है।"],"pa":["ਕਿਹੜੀ ਲੜੀ ਉਦਯੋਗਿਕ ਸਹਿਜੀਵਤਾ ਨੂੰ ਸਹੀ ਦਰਸਾਉਂਦੀ ਹੈ?",["ਜੂਟ ਮਿੱਲ → ਕੱਚਾ ਲੋਹਾ → ਸੀਮਿੰਟ","ਖੰਡ ਮਿੱਲ → ਕ੍ਰੋਮਾਈਟ → ਸੀਮਿੰਟ","ਤਾਪ ਬਿਜਲੀ ਪਲਾਂਟ → ਉੱਡਣ ਵਾਲੀ ਸੁਆਹ → ਮਿਸ਼ਰਤ ਸੀਮਿੰਟ","ਸੂਤੀ ਕੱਪੜਾ ਮਿੱਲ → ਯੂਰੇਨੀਅਮ → ਸੀਮਿੰਟ"],"ਸੀਮਿੰਟ ਵਿੱਚ ਉੱਡਣ ਵਾਲੀ ਸੁਆਹ ਵਰਤਣ ਨਾਲ ਇੱਕ ਉਦਯੋਗ ਦਾ ਉਪ-ਉਤਪਾਦ ਦੂਜੇ ਉਦਯੋਗ ਦੀ ਸਮੱਗਰੀ ਬਣ ਜਾਂਦਾ ਹੈ।"]},
"GEO-IND-001-CP005-Q041":{"h":"c882e386","hi":["मिश्रित सीमेंट उत्पादन में कौन-सा युग्म सही सुमेलित है?",["इस्पात का धातुमल — कपास का रेशा","उड़न राख — जूट का रेशा","शीरा — क्लिंकर","इस्पात संयंत्र का धातुमल — सीमेंट की उत्पादन सामग्री"],"वात्या भट्टी के धातुमल का प्रसंस्करण करके सीमेंट बनाने में इस्तेमाल किया जा सकता है।"],"pa":["ਮਿਸ਼ਰਤ ਸੀਮਿੰਟ ਬਣਾਉਣ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਸਟੀਲ ਦੀ ਸਲੈਗ — ਕਪਾਹ ਦਾ ਰੇਸ਼ਾ","ਉੱਡਣ ਵਾਲੀ ਸੁਆਹ — ਜੂਟ ਦਾ ਰੇਸ਼ਾ","ਸ਼ੀਰਾ — ਕਲਿੰਕਰ","ਸਟੀਲ ਪਲਾਂਟ ਦੀ ਸਲੈਗ — ਸੀਮਿੰਟ ਦੀ ਸਮੱਗਰੀ"],"ਬਲਾਸਟ ਫਰਨੇਸ ਦੀ ਸਲੈਗ ਨੂੰ ਪ੍ਰੋਸੈਸ ਕਰਕੇ ਸੀਮਿੰਟ ਬਣਾਉਣ ਵਿੱਚ ਵਰਤਿਆ ਜਾ ਸਕਦਾ ਹੈ।"]},
"GEO-IND-001-CP005-Q042":{"h":"58c9f953","hi":["ताप विद्युत या इस्पात परिसरों के पास होने से सीमेंट संयंत्रों को क्यों लाभ हो सकता है?",["उड़न राख या धातुमल पूरक सामग्री बन सकते हैं","वहाँ से उन्हें गन्ना मिलता है","वहाँ वे जूट का खनन करते हैं","उन्हें चाय की पत्तियाँ चाहिए"],"औद्योगिक उपोत्पाद सीमेंट की उपयोगी उत्पादन सामग्री बन सकते हैं। इससे अपशिष्ट और ढुलाई दोनों घटते हैं।"],"pa":["ਤਾਪ ਬਿਜਲੀ ਜਾਂ ਸਟੀਲ ਕੰਪਲੈਕਸਾਂ ਦੇ ਨੇੜੇ ਹੋਣ ਨਾਲ ਸੀਮਿੰਟ ਪਲਾਂਟਾਂ ਨੂੰ ਕਿਉਂ ਲਾਭ ਹੋ ਸਕਦਾ ਹੈ?",["ਉੱਡਣ ਵਾਲੀ ਸੁਆਹ ਜਾਂ ਸਲੈਗ ਪੂਰਕ ਸਮੱਗਰੀ ਵਜੋਂ ਵਰਤੀ ਜਾ ਸਕਦੀ ਹੈ","ਉੱਥੋਂ ਉਨ੍ਹਾਂ ਨੂੰ ਗੰਨਾ ਮਿਲਦਾ ਹੈ","ਉਹ ਉੱਥੇ ਜੂਟ ਦੀ ਖੁਦਾਈ ਕਰਦੇ ਹਨ","ਉਨ੍ਹਾਂ ਨੂੰ ਚਾਹ ਦੀਆਂ ਪੱਤੀਆਂ ਚਾਹੀਦੀਆਂ ਹਨ"],"ਉਦਯੋਗਿਕ ਉਪ-ਉਤਪਾਦ ਸੀਮਿੰਟ ਦੀ ਲਾਹੇਵੰਦ ਸਮੱਗਰੀ ਬਣ ਸਕਦੇ ਹਨ। ਇਸ ਨਾਲ ਰਹਿੰਦ-ਖੂੰਹਦ ਅਤੇ ਢੋਆ-ਢੁਆਈ ਘਟਦੀ ਹੈ।"]},
"GEO-IND-001-CP005-Q043":{"h":"d1fabbec","hi":["दक्षिण भारत का कौन-सा राज्य चूना पत्थर आधारित सीमेंट का प्रमुख क्षेत्र है?",["पंजाब","असम","सिक्किम","आंध्र प्रदेश"],"आंध्र प्रदेश में चूना पत्थर के बड़े निक्षेप और महत्वपूर्ण सीमेंट उद्योग हैं।"],"pa":["ਦੱਖਣੀ ਭਾਰਤ ਦਾ ਕਿਹੜਾ ਰਾਜ ਚੂਨਾ ਪੱਥਰ 'ਤੇ ਆਧਾਰਿਤ ਸੀਮਿੰਟ ਦਾ ਪ੍ਰਮੁੱਖ ਖੇਤਰ ਹੈ?",["ਪੰਜਾਬ","ਅਸਾਮ","ਸਿੱਕਮ","ਆਂਧਰਾ ਪ੍ਰਦੇਸ਼"],"ਆਂਧਰਾ ਪ੍ਰਦੇਸ਼ ਵਿੱਚ ਚੂਨਾ ਪੱਥਰ ਦੇ ਵੱਡੇ ਭੰਡਾਰ ਹਨ ਅਤੇ ਸੀਮਿੰਟ ਉਦਯੋਗ ਅਹਿਮ ਹੈ।"]},
"GEO-IND-001-CP005-Q044":{"h":"4d27bc62","hi":["दक्षिण भारत के किस अन्य राज्य में चूना पत्थर आधारित सीमेंट उद्योग लंबे समय से स्थापित है?",["तमिलनाडु","नागालैंड","त्रिपुरा","पंजाब"],"तमिलनाडु में चूना पत्थर के महत्वपूर्ण निक्षेप और सीमेंट संयंत्र हैं।"],"pa":["ਦੱਖਣੀ ਭਾਰਤ ਦੇ ਕਿਹੜੇ ਹੋਰ ਰਾਜ ਵਿੱਚ ਚੂਨਾ ਪੱਥਰ 'ਤੇ ਆਧਾਰਿਤ ਸੀਮਿੰਟ ਉਦਯੋਗ ਲੰਮੇ ਸਮੇਂ ਤੋਂ ਸਥਾਪਤ ਹੈ?",["ਤਾਮਿਲਨਾਡੂ","ਨਾਗਾਲੈਂਡ","ਤ੍ਰਿਪੁਰਾ","ਪੰਜਾਬ"],"ਤਾਮਿਲਨਾਡੂ ਵਿੱਚ ਚੂਨਾ ਪੱਥਰ ਦੇ ਅਹਿਮ ਭੰਡਾਰ ਅਤੇ ਸੀਮਿੰਟ ਪਲਾਂਟ ਹਨ।"]},
"GEO-IND-001-CP005-Q045":{"h":"5990ffca","hi":["कथनों पर विचार कीजिए: I. आंध्र प्रदेश बड़े पैमाने पर सीमेंट बनाता है। II. तमिलनाडु में भी चूना पत्थर आधारित सीमेंट संयंत्र हैं। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","I और II दोनों सही हैं","केवल II सही है","न तो I और न ही II सही है"],"दोनों राज्य दक्षिण भारत के महत्वपूर्ण सीमेंट क्षेत्र हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਆਂਧਰਾ ਪ੍ਰਦੇਸ਼ ਵੱਡੇ ਪੱਧਰ 'ਤੇ ਸੀਮਿੰਟ ਬਣਾਉਂਦਾ ਹੈ। II. ਤਾਮਿਲਨਾਡੂ ਵਿੱਚ ਵੀ ਚੂਨਾ ਪੱਥਰ 'ਤੇ ਆਧਾਰਿਤ ਸੀਮਿੰਟ ਪਲਾਂਟ ਹਨ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਦੋਵੇਂ ਰਾਜ ਦੱਖਣੀ ਭਾਰਤ ਦੇ ਅਹਿਮ ਸੀਮਿੰਟ ਖੇਤਰ ਹਨ।"]},
"GEO-IND-001-CP005-Q046":{"h":"e49a56c6","hi":["दक्षिण भारत के सीमेंट उद्योग के भूगोल में कौन-सा युग्म सही सुमेलित है?",["आंध्र प्रदेश — केवल जूट","तमिलनाडु — सीमेंट उद्योग का अभाव","आंध्र प्रदेश — चूना पत्थर और सीमेंट","तमिलनाडु — केवल कोयला खनन"],"आंध्र प्रदेश और तमिलनाडु दोनों में चूना पत्थर और सीमेंट उद्योग का संबंध लंबे समय से बना हुआ है।"],"pa":["ਦੱਖਣੀ ਭਾਰਤ ਦੇ ਸੀਮਿੰਟ ਉਦਯੋਗ ਦੇ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਆਂਧਰਾ ਪ੍ਰਦੇਸ਼ — ਸਿਰਫ਼ ਜੂਟ","ਤਾਮਿਲਨਾਡੂ — ਸੀਮਿੰਟ ਉਦਯੋਗ ਦੀ ਅਣਹੋਂਦ","ਆਂਧਰਾ ਪ੍ਰਦੇਸ਼ — ਚੂਨਾ ਪੱਥਰ ਅਤੇ ਸੀਮਿੰਟ","ਤਾਮਿਲਨਾਡੂ — ਸਿਰਫ਼ ਕੋਲੇ ਦੀ ਖੁਦਾਈ"],"ਆਂਧਰਾ ਪ੍ਰਦੇਸ਼ ਅਤੇ ਤਾਮਿਲਨਾਡੂ ਦੋਵਾਂ ਵਿੱਚ ਚੂਨਾ ਪੱਥਰ ਅਤੇ ਸੀਮਿੰਟ ਉਦਯੋਗ ਦਾ ਸਬੰਧ ਲੰਮੇ ਸਮੇਂ ਤੋਂ ਕਾਇਮ ਹੈ।"]},
"GEO-IND-001-CP005-Q047":{"h":"151e02b4","hi":["दक्षिण भारत के कई सीमेंट संयंत्र तट से दूर आंतरिक भागों में क्यों लगाए जाते हैं?",["सीमेंट के लिए कच्चा माल नहीं चाहिए","पत्तन उत्पादन में बाधा डालते हैं","केवल मत्स्यन का महत्व है","चूना पत्थर के निक्षेप आंतरिक भूवैज्ञानिक पट्टियों में केंद्रित हैं"],"संयंत्र भारी चूना पत्थर के स्रोत के पास लगाए जाते हैं, भले ही तैयार सीमेंट तटीय या शहरी बाज़ारों में जाता हो।"],"pa":["ਦੱਖਣੀ ਭਾਰਤ ਵਿੱਚ ਕਈ ਸੀਮਿੰਟ ਪਲਾਂਟ ਤੱਟ ਤੋਂ ਦੂਰ ਅੰਦਰੂਨੀ ਇਲਾਕਿਆਂ ਵਿੱਚ ਕਿਉਂ ਲੱਗਦੇ ਹਨ?",["ਸੀਮਿੰਟ ਲਈ ਕੱਚੇ ਮਾਲ ਦੀ ਲੋੜ ਨਹੀਂ ਹੈ","ਬੰਦਰਗਾਹਾਂ ਉਤਪਾਦਨ ਵਿੱਚ ਰੁਕਾਵਟ ਪਾਉਂਦੀਆਂ ਹਨ","ਸਿਰਫ਼ ਮੱਛੀ ਫੜਨ ਦਾ ਕੰਮ ਦਾ ਮਹੱਤਵ ਹੈ","ਚੂਨਾ ਪੱਥਰ ਦੇ ਭੰਡਾਰ ਅੰਦਰੂਨੀ ਭੂ-ਵਿਗਿਆਨਕ ਪੱਟੀਆਂ ਵਿੱਚ ਕੇਂਦਰਿਤ ਹਨ"],"ਭਾਵੇਂ ਤਿਆਰ ਸੀਮਿੰਟ ਤੱਟੀ ਜਾਂ ਸ਼ਹਿਰੀ ਬਾਜ਼ਾਰਾਂ ਵਿੱਚ ਜਾਂਦਾ ਹੋਵੇ, ਪਲਾਂਟ ਭਾਰੇ ਚੂਨਾ ਪੱਥਰ ਦੇ ਸਰੋਤ ਨੇੜੇ ਲਾਏ ਜਾਂਦੇ ਹਨ।"]},
"GEO-IND-001-CP005-Q048":{"h":"f3939ac2","hi":["दक्षिण भारत के उद्योगों की कौन-सी तुलना सही है?",["सीमेंट उद्योग चूना पत्थर की पट्टियों के पास लगता है, जबकि वस्त्र उद्योग के संकुल श्रम, बाज़ार और रेशों की आपूर्ति के तंत्र के पास लग सकते हैं","दोनों केवल लौह अयस्क पर निर्भर हैं","दोनों में परिवहन का उपयोग नहीं होता","सीमेंट उद्योग कपास के खेतों के पास लगता है"],"अलग-अलग उद्योगों की अवस्थिति अलग-अलग कारकों के मेल पर निर्भर करती है।"],"pa":["ਦੱਖਣੀ ਭਾਰਤ ਦੇ ਉਦਯੋਗਾਂ ਦੀ ਕਿਹੜੀ ਤੁਲਨਾ ਸਹੀ ਹੈ?",["ਸੀਮਿੰਟ ਪਲਾਂਟ ਚੂਨਾ ਪੱਥਰ ਦੀਆਂ ਪੱਟੀਆਂ ਕੋਲ ਲੱਗਦੇ ਹਨ, ਜਦਕਿ ਕੱਪੜਾ ਉਦਯੋਗ ਕਾਮਿਆਂ, ਬਾਜ਼ਾਰਾਂ ਅਤੇ ਰੇਸ਼ਿਆਂ ਦੀ ਸਪਲਾਈ ਦੇ ਜਾਲ ਕੋਲ ਇਕੱਠੇ ਹੋ ਸਕਦੇ ਹਨ","ਦੋਵੇਂ ਸਿਰਫ਼ ਕੱਚੇ ਲੋਹੇ 'ਤੇ ਨਿਰਭਰ ਹਨ","ਦੋਵੇਂ ਆਵਾਜਾਈ ਨਹੀਂ ਵਰਤਦੇ","ਸੀਮਿੰਟ ਪਲਾਂਟ ਕਪਾਹ ਦੇ ਖੇਤਾਂ ਕੋਲ ਲੱਗਦੇ ਹਨ"],"ਵੱਖ-ਵੱਖ ਉਦਯੋਗਾਂ ਦੀ ਥਾਂ ਵੱਖ-ਵੱਖ ਕਾਰਕਾਂ ਦੇ ਮੇਲ 'ਤੇ ਨਿਰਭਰ ਕਰਦੀ ਹੈ।"]},
"GEO-IND-001-CP005-Q049":{"h":"0e7f947a","hi":["तटीय सीमेंट संयंत्र को पत्तन तक पहुँच से क्यों लाभ हो सकता है?",["पत्तन अपने आप चूना पत्थर की आपूर्ति करते हैं","सीमेंट सड़क से नहीं ढोया जा सकता","सीमेंट और क्लिंकर की बड़ी मात्रा समुद्र से कम लागत में ढोई जा सकती है","पत्तन भट्टियों की जगह लेते हैं"],"समुद्री परिवहन से बड़ी मात्रा में क्लिंकर और सीमेंट को लंबी दूरी तक भेजने का खर्च घट सकता है।"],"pa":["ਤੱਟੀ ਸੀਮਿੰਟ ਪਲਾਂਟ ਨੂੰ ਬੰਦਰਗਾਹ ਤੱਕ ਪਹੁੰਚ ਤੋਂ ਕਿਉਂ ਲਾਭ ਹੋ ਸਕਦਾ ਹੈ?",["ਬੰਦਰਗਾਹਾਂ ਆਪਣੇ ਆਪ ਚੂਨਾ ਪੱਥਰ ਦਿੰਦੀਆਂ ਹਨ","ਸੀਮਿੰਟ ਸੜਕ ਰਾਹੀਂ ਨਹੀਂ ਢੋਇਆ ਜਾ ਸਕਦਾ","ਸੀਮਿੰਟ ਅਤੇ ਕਲਿੰਕਰ ਦੀ ਵੱਡੀ ਮਾਤਰਾ ਸਮੁੰਦਰ ਰਾਹੀਂ ਘੱਟ ਖ਼ਰਚ 'ਤੇ ਢੋਈ ਜਾ ਸਕਦੀ ਹੈ","ਬੰਦਰਗਾਹਾਂ ਭੱਠੀਆਂ ਦੀ ਥਾਂ ਲੈਂਦੀਆਂ ਹਨ"],"ਸਮੁੰਦਰੀ ਢੋਆ-ਢੁਆਈ ਨਾਲ ਵੱਡੀ ਮਾਤਰਾ ਵਿੱਚ ਕਲਿੰਕਰ ਅਤੇ ਸੀਮਿੰਟ ਨੂੰ ਲੰਮੀ ਦੂਰੀ ਤੱਕ ਭੇਜਣ ਦਾ ਖ਼ਰਚ ਘਟ ਸਕਦਾ ਹੈ।"]},
"GEO-IND-001-CP005-Q050":{"h":"0f4ba944","hi":["कौन-सा कारक बड़े शहरी बाज़ारों के पास पिसाई इकाइयों को आकर्षित कर सकता है?",["लौह अयस्क की श्रेणी","गन्ने की आपूर्ति","जूट की खेती","माँग और वितरण की सुविधा"],"क्लिंकर कहीं और बनता हो, तब भी पिसाई और वितरण की सुविधाएँ उपभोक्ताओं के पास स्थापित की जा सकती हैं।"],"pa":["ਕਿਹੜਾ ਕਾਰਕ ਵੱਡੇ ਸ਼ਹਿਰੀ ਬਾਜ਼ਾਰਾਂ ਦੇ ਨੇੜੇ ਪਿਸਾਈ ਇਕਾਈਆਂ ਨੂੰ ਖਿੱਚ ਸਕਦਾ ਹੈ?",["ਕੱਚੇ ਲੋਹੇ ਦਾ ਦਰਜਾ","ਗੰਨੇ ਦੀ ਸਪਲਾਈ","ਜੂਟ ਦੀ ਖੇਤੀ","ਮੰਗ ਅਤੇ ਵੰਡ ਦੀ ਸਹੂਲਤ"],"ਕਲਿੰਕਰ ਕਿਤੇ ਹੋਰ ਬਣਦਾ ਹੋਵੇ ਤਾਂ ਵੀ ਪਿਸਾਈ ਤੇ ਵੰਡ ਦੀਆਂ ਇਕਾਈਆਂ ਖਪਤਕਾਰਾਂ ਦੇ ਨੇੜੇ ਲੱਗ ਸਕਦੀਆਂ ਹਨ।"]},
"GEO-IND-001-CP005-Q051":{"h":"c211df18","hi":["कथनों पर विचार कीजिए: I. सीमेंट भारी होता है। II. बाज़ार तक पहुँच पिसाई और वितरण की अवस्थिति को प्रभावित कर सकती है। कौन-सा/से कथन सही है/हैं?",["I और II दोनों सही हैं","केवल I सही है","केवल II सही है","न तो I और न ही II सही है"],"बड़ी मात्रा में माल ढुलाई और बाज़ार की निकटता, दोनों सीमेंट की पिसाई और वितरण के तंत्र को प्रभावित करती हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਸੀਮਿੰਟ ਭਾਰਾ ਹੁੰਦਾ ਹੈ। II. ਬਾਜ਼ਾਰ ਤੱਕ ਪਹੁੰਚ ਪਿਸਾਈ ਤੇ ਵੰਡ ਦੀ ਥਾਂ 'ਤੇ ਅਸਰ ਪਾ ਸਕਦੀ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਵੱਡੀ ਮਾਤਰਾ ਵਿੱਚ ਮਾਲ ਦੀ ਢੋਆ-ਢੁਆਈ ਅਤੇ ਬਾਜ਼ਾਰ ਦੀ ਨੇੜਤਾ, ਦੋਵੇਂ ਸੀਮਿੰਟ ਦੀ ਪਿਸਾਈ ਅਤੇ ਵੰਡ ਦੇ ਜਾਲ 'ਤੇ ਅਸਰ ਪਾਉਂਦੇ ਹਨ।"]},
"GEO-IND-001-CP005-Q052":{"h":"90cc9db5","hi":["सीमेंट की परिवहन व्यवस्था में कौन-सा युग्म सही सुमेलित है?",["पत्तन तक पहुँच — जूट की खेती","पत्तन तक पहुँच — बड़ी मात्रा में क्लिंकर की ढुलाई","रेलवे साइडिंग — गन्ने की खेती","चूना पत्थर की खदान — परिधान बाज़ार"],"पत्तनों से बड़ी मात्रा में क्लिंकर और सीमेंट की ढुलाई में मदद मिल सकती है।"],"pa":["ਸੀਮਿੰਟ ਦੀ ਢੋਆ-ਢੁਆਈ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਬੰਦਰਗਾਹ ਤੱਕ ਪਹੁੰਚ — ਜੂਟ ਦੀ ਖੇਤੀ","ਬੰਦਰਗਾਹ ਤੱਕ ਪਹੁੰਚ — ਵੱਡੀ ਮਾਤਰਾ ਵਿੱਚ ਕਲਿੰਕਰ ਦੀ ਢੋਆ-ਢੁਆਈ","ਰੇਲਵੇ ਸਾਈਡਿੰਗ — ਗੰਨੇ ਦੀ ਖੇਤੀ","ਚੂਨਾ ਪੱਥਰ ਦੀ ਖਾਣ — ਪਹਿਰਾਵਿਆਂ ਦਾ ਬਾਜ਼ਾਰ"],"ਬੰਦਰਗਾਹਾਂ ਤੋਂ ਵੱਡੀ ਮਾਤਰਾ ਵਿੱਚ ਕਲਿੰਕਰ ਅਤੇ ਸੀਮਿੰਟ ਢੋਣ ਵਿੱਚ ਮਦਦ ਮਿਲ ਸਕਦੀ ਹੈ।"]},
"GEO-IND-001-CP005-Q053":{"h":"18bba33a","hi":["क्लिंकर का उत्पादन और अंतिम पिसाई अलग-अलग स्थानों पर क्यों हो सकते हैं?",["दोनों चरणों का आपस में कोई संबंध नहीं है","क्लिंकर के लिए कपास चाहिए","क्लिंकर उत्पादन कच्चे माल के पास होता है, जबकि पिसाई बाज़ार के पास हो सकती है","पिसाई के लिए लौह अयस्क चाहिए"],"उत्पादन के चरणों को अलग रखने से स्रोत और बाज़ार संबंधी अवस्थितिक कारकों के बीच संतुलन बनाया जा सकता है।"],"pa":["ਕਲਿੰਕਰ ਦਾ ਉਤਪਾਦਨ ਅਤੇ ਆਖ਼ਰੀ ਪਿਸਾਈ ਵੱਖ-ਵੱਖ ਥਾਵਾਂ 'ਤੇ ਕਿਉਂ ਹੋ ਸਕਦੇ ਹਨ?",["ਦੋਵਾਂ ਪੜਾਵਾਂ ਦਾ ਆਪਸ ਵਿੱਚ ਕੋਈ ਸਬੰਧ ਨਹੀਂ ਹੈ","ਕਲਿੰਕਰ ਲਈ ਕਪਾਹ ਚਾਹੀਦੀ ਹੈ","ਕਲਿੰਕਰ ਕੱਚੇ ਮਾਲ ਨੇੜੇ ਬਣਦਾ ਹੈ, ਜਦਕਿ ਪਿਸਾਈ ਬਾਜ਼ਾਰ ਦੇ ਨੇੜੇ ਹੋ ਸਕਦੀ ਹੈ","ਪਿਸਾਈ ਲਈ ਕੱਚਾ ਲੋਹਾ ਚਾਹੀਦਾ ਹੈ"],"ਉਤਪਾਦਨ ਦੇ ਪੜਾਅ ਵੱਖ ਕਰਨ ਨਾਲ ਸਰੋਤ ਅਤੇ ਬਾਜ਼ਾਰ ਨਾਲ ਜੁੜੇ ਥਾਂ ਦੀ ਚੋਣ ਦੇ ਕਾਰਕਾਂ ਵਿਚਾਲੇ ਸੰਤੁਲਨ ਬਣ ਸਕਦਾ ਹੈ।"]},
"GEO-IND-001-CP005-Q054":{"h":"f6a2a9c3","hi":["सीमेंट वितरण का सही क्रम कौन-सा है?",["कपास पट्टी → क्लिंकर → जूट मिल","कोयला क्षेत्र → चीनी → सीमेंट","चाय बागान → क्लिंकर → इस्पात","चूना पत्थर पट्टी → क्लिंकर संयंत्र → पिसाई/वितरण बाज़ार"],"इस क्रम में क्लिंकर उत्पादन की स्रोत-उन्मुखता और अंतिम वितरण की बाज़ार-उन्मुखता दिखाई देती है।"],"pa":["ਸੀਮਿੰਟ ਦੀ ਵੰਡ ਦੀ ਸਹੀ ਲੜੀ ਕਿਹੜੀ ਹੈ?",["ਕਪਾਹ ਪੱਟੀ → ਕਲਿੰਕਰ → ਜੂਟ ਮਿੱਲ","ਕੋਲਾ ਖੇਤਰ → ਖੰਡ → ਸੀਮਿੰਟ","ਚਾਹ ਬਾਗ਼ → ਕਲਿੰਕਰ → ਸਟੀਲ","ਚੂਨਾ ਪੱਥਰ ਪੱਟੀ → ਕਲਿੰਕਰ ਪਲਾਂਟ → ਪਿਸਾਈ/ਵੰਡ ਦਾ ਬਾਜ਼ਾਰ"],"ਲੜੀ ਦਰਸਾਉਂਦੀ ਹੈ ਕਿ ਕਲਿੰਕਰ ਦਾ ਉਤਪਾਦਨ ਸਰੋਤ ਦੇ ਨੇੜੇ ਅਤੇ ਆਖ਼ਰੀ ਵੰਡ ਬਾਜ਼ਾਰ ਦੇ ਨੇੜੇ ਹੁੰਦੀ ਹੈ।"]},
"GEO-IND-001-CP006-Q001":{"h":"1d8179be","hi":["ऐलुमिनियम उत्पादन का मुख्य कच्चा माल कौन-सा अयस्क है?",["हेमेटाइट","क्रोमाइट","बॉक्साइट","अभ्रक"],"बॉक्साइट का शोधन करके ऐलुमिना प्राप्त किया जाता है। फिर उसके प्रगलन से ऐलुमिनियम धातु बनती है।"],"pa":["ਐਲੂਮੀਨੀਅਮ ਬਣਾਉਣ ਲਈ ਮੁੱਖ ਕੱਚਾ ਮਾਲ ਕਿਹੜਾ ਅਯਸਕ ਹੈ?",["ਹੈਮੇਟਾਈਟ","ਕ੍ਰੋਮਾਈਟ","ਬਾਕਸਾਈਟ","ਅਬਰਕ"],"ਬਾਕਸਾਈਟ ਨੂੰ ਸੋਧ ਕੇ ਐਲੂਮੀਨਾ ਬਣਾਇਆ ਜਾਂਦਾ ਹੈ। ਫਿਰ ਉਸ ਦੀ ਗਲਾਈ ਨਾਲ ਐਲੂਮੀਨੀਅਮ ਧਾਤ ਬਣਦੀ ਹੈ।"]},
"GEO-IND-001-CP006-Q002":{"h":"8df4baa5","hi":["ऐलुमिनियम के प्रगलन से पहले बॉक्साइट से कौन-सा मध्यवर्ती उत्पाद मिलता है?",["कच्चा लोहा","क्लिंकर","कोक","ऐलुमिना"],"पहले बॉक्साइट का शोधन करके ऐलुमिना प्राप्त किया जाता है। फिर विद्युत अपघटनी अपचयन से उसे ऐलुमिनियम में बदला जाता है।"],"pa":["ਐਲੂਮੀਨੀਅਮ ਦੀ ਗਲਾਈ ਤੋਂ ਪਹਿਲਾਂ ਬਾਕਸਾਈਟ ਤੋਂ ਕਿਹੜਾ ਵਿਚਕਾਰਲਾ ਉਤਪਾਦ ਮਿਲਦਾ ਹੈ?",["ਪਿਗ ਆਇਰਨ","ਕਲਿੰਕਰ","ਕੋਕ","ਐਲੂਮੀਨਾ"],"ਬਾਕਸਾਈਟ ਨੂੰ ਪਹਿਲਾਂ ਸੋਧ ਕੇ ਐਲੂਮੀਨਾ ਬਣਾਇਆ ਜਾਂਦਾ ਹੈ। ਫਿਰ ਬਿਜਲਈ ਅਪਘਟਨ ਰਾਹੀਂ ਉਸ ਦਾ ਅਪਚਯਨ ਕਰਕੇ ਐਲੂਮੀਨੀਅਮ ਬਣਾਇਆ ਜਾਂਦਾ ਹੈ।"]},
"GEO-IND-001-CP006-Q003":{"h":"845a7d8f","hi":["कथनों पर विचार कीजिए: I. बॉक्साइट ऐलुमिनियम का अयस्क है। II. ऐलुमिना ऐलुमिनियम उत्पादन का एक मध्यवर्ती उत्पाद है। कौन-सा/से कथन सही है/हैं?",["I और II दोनों सही हैं","केवल I सही है","केवल II सही है","न तो I और न ही II सही है"],"ये दोनों तथ्य बॉक्साइट से ऐलुमिनियम बनाने की शृंखला का आधार हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਬਾਕਸਾਈਟ ਐਲੂਮੀਨੀਅਮ ਦਾ ਅਯਸਕ ਹੈ। II. ਐਲੂਮੀਨਾ ਐਲੂਮੀਨੀਅਮ ਬਣਾਉਣ ਦਾ ਇੱਕ ਵਿਚਕਾਰਲਾ ਉਤਪਾਦ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਇਹ ਦੋਵੇਂ ਤੱਥ ਬਾਕਸਾਈਟ ਤੋਂ ਐਲੂਮੀਨੀਅਮ ਬਣਾਉਣ ਦੀ ਲੜੀ ਦਾ ਆਧਾਰ ਹਨ।"]},
"GEO-IND-001-CP006-Q004":{"h":"ce421425","hi":["ऐलुमिनियम उत्पादन का सही क्रम कौन-सा है?",["लौह अयस्क → ऐलुमिना → ऐलुमिनियम","बॉक्साइट → ऐलुमिना → ऐलुमिनियम","बॉक्साइट → क्लिंकर → इस्पात","अभ्रक → ऐलुमिना → ताँबा"],"ऐलुमिनियम उत्पादन में पहले बॉक्साइट का शोधन करके ऐलुमिना बनाया जाता है और फिर प्रगलन से धातु प्राप्त की जाती है।"],"pa":["ਐਲੂਮੀਨੀਅਮ ਬਣਾਉਣ ਦੀ ਸਹੀ ਲੜੀ ਕਿਹੜੀ ਹੈ?",["ਕੱਚਾ ਲੋਹਾ → ਐਲੂਮੀਨਾ → ਐਲੂਮੀਨੀਅਮ","ਬਾਕਸਾਈਟ → ਐਲੂਮੀਨਾ → ਐਲੂਮੀਨੀਅਮ","ਬਾਕਸਾਈਟ → ਕਲਿੰਕਰ → ਸਟੀਲ","ਅਬਰਕ → ਐਲੂਮੀਨਾ → ਤਾਂਬਾ"],"ਐਲੂਮੀਨੀਅਮ ਉਤਪਾਦਨ ਵਿੱਚ ਪਹਿਲਾਂ ਬਾਕਸਾਈਟ ਨੂੰ ਸੋਧ ਕੇ ਐਲੂਮੀਨਾ ਬਣਦਾ ਹੈ ਤੇ ਫਿਰ ਗਲਾਈ ਨਾਲ ਧਾਤ ਮਿਲਦੀ ਹੈ।"]},
"GEO-IND-001-CP006-Q005":{"h":"74c51bcc","hi":["ऐलुमिनियम धातुकर्म में कौन-सा युग्म सही सुमेलित है?",["क्रोमाइट — ऐलुमिनियम का अयस्क","जिप्सम — ऐलुमिनियम का अयस्क","बॉक्साइट — ऐलुमिनियम का अयस्क","अभ्रक — ऐलुमिनियम का अयस्क"],"बॉक्साइट ऐलुमिनियम का प्रचलित अयस्क है।"],"pa":["ਐਲੂਮੀਨੀਅਮ ਧਾਤਕਾਰੀ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਕ੍ਰੋਮਾਈਟ — ਐਲੂਮੀਨੀਅਮ ਦਾ ਅਯਸਕ","ਜਿਪਸਮ — ਐਲੂਮੀਨੀਅਮ ਦਾ ਅਯਸਕ","ਬਾਕਸਾਈਟ — ਐਲੂਮੀਨੀਅਮ ਦਾ ਅਯਸਕ","ਅਬਰਕ — ਐਲੂਮੀਨੀਅਮ ਦਾ ਅਯਸਕ"],"ਬਾਕਸਾਈਟ ਐਲੂਮੀਨੀਅਮ ਦਾ ਪ੍ਰਚੱਲਿਤ ਅਯਸਕ ਹੈ।"]},
"GEO-IND-001-CP006-Q006":{"h":"162055b9","hi":["एक संयंत्र विद्युत अपघटन से पहले बॉक्साइट का शोधन कर ऐलुमिना बनाता है। यह किस उद्योग का वर्णन है?",["इस्पात उद्योग","सीमेंट उद्योग","चीनी उद्योग","ऐलुमिनियम उद्योग"],"बॉक्साइट के शोधन से ऐलुमिना बनाना और फिर विद्युत अपघटन करना ऐलुमिनियम उत्पादन के विशिष्ट चरण हैं।"],"pa":["ਇੱਕ ਪਲਾਂਟ ਬਿਜਲਈ ਅਪਘਟਨ ਤੋਂ ਪਹਿਲਾਂ ਬਾਕਸਾਈਟ ਨੂੰ ਸੋਧ ਕੇ ਐਲੂਮੀਨਾ ਬਣਾਉਂਦਾ ਹੈ। ਇਹ ਕਿਸ ਉਦਯੋਗ ਦਾ ਵਰਣਨ ਹੈ?",["ਸਟੀਲ ਉਦਯੋਗ","ਸੀਮਿੰਟ ਉਦਯੋਗ","ਖੰਡ ਉਦਯੋਗ","ਐਲੂਮੀਨੀਅਮ ਉਦਯੋਗ"],"ਬਾਕਸਾਈਟ ਨੂੰ ਸੋਧ ਕੇ ਐਲੂਮੀਨਾ ਬਣਾਉਣਾ ਅਤੇ ਫਿਰ ਬਿਜਲਈ ਅਪਘਟਨ ਕਰਨਾ ਐਲੂਮੀਨੀਅਮ ਉਤਪਾਦਨ ਦੇ ਖ਼ਾਸ ਪੜਾਅ ਹਨ।"]},
"GEO-IND-001-CP006-Q007":{"h":"fc3009a2","hi":["ऐलुमिनियम प्रगलन संयंत्र की अवस्थिति तय करने में सस्ती बिजली प्रमुख कारक क्यों है?",["ऐलुमिनियम बनाने में बिजली नहीं लगती","ऐलुमिनियम के प्रगलन में बहुत अधिक बिजली लगती है","बिजली केवल प्रकाश के लिए लगती है","बॉक्साइट एक ईंधन है"],"ऐलुमिना के विद्युत अपघटनी अपचयन में बहुत अधिक बिजली लगती है। इसलिए संयंत्र की अवस्थिति पर बिजली की लागत और आपूर्ति की विश्वसनीयता का बहुत असर पड़ता है।"],"pa":["ਐਲੂਮੀਨੀਅਮ ਗਲਾਈ ਪਲਾਂਟ ਦੀ ਥਾਂ ਚੁਣਨ ਵੇਲੇ ਸਸਤੀ ਬਿਜਲੀ ਅਹਿਮ ਕਿਉਂ ਹੁੰਦੀ ਹੈ?",["ਐਲੂਮੀਨੀਅਮ ਲਈ ਬਿਜਲੀ ਨਹੀਂ ਚਾਹੀਦੀ","ਐਲੂਮੀਨੀਅਮ ਦੀ ਗਲਾਈ ਵਿੱਚ ਬਹੁਤ ਬਿਜਲੀ ਲੱਗਦੀ ਹੈ","ਬਿਜਲੀ ਸਿਰਫ਼ ਰੌਸ਼ਨੀ ਲਈ ਵਰਤੀ ਜਾਂਦੀ ਹੈ","ਬਾਕਸਾਈਟ ਇੱਕ ਬਾਲਣ ਹੈ"],"ਐਲੂਮੀਨਾ ਦੇ ਬਿਜਲਈ ਅਪਘਟਨ ਰਾਹੀਂ ਅਪਚਯਨ ਵਿੱਚ ਬਹੁਤ ਬਿਜਲੀ ਲੱਗਦੀ ਹੈ। ਇਸ ਲਈ ਬਿਜਲੀ ਦਾ ਖ਼ਰਚ ਅਤੇ ਸਪਲਾਈ ਦਾ ਭਰੋਸਾ ਪਲਾਂਟ ਦੀ ਥਾਂ 'ਤੇ ਬਹੁਤ ਅਸਰ ਪਾਉਂਦੇ ਹਨ।"]},
"GEO-IND-001-CP006-Q008":{"h":"dbb3670a","hi":["ऐलुमिनियम उत्पादन के किस चरण में विशेष रूप से अधिक बिजली लगती है?",["केवल बॉक्साइट का खनन","केवल ऐलुमिनियम की पैकिंग","ऐलुमिना का प्रगलन कर ऐलुमिनियम बनाना","केवल अयस्क का परिवहन"],"विद्युत अपघटन द्वारा प्रगलन के चरण में बहुत बड़ी मात्रा में बिजली इस्तेमाल होती है।"],"pa":["ਐਲੂਮੀਨੀਅਮ ਬਣਾਉਣ ਦੇ ਕਿਹੜੇ ਪੜਾਅ ਵਿੱਚ ਖ਼ਾਸ ਤੌਰ 'ਤੇ ਵੱਧ ਬਿਜਲੀ ਲੱਗਦੀ ਹੈ?",["ਸਿਰਫ਼ ਬਾਕਸਾਈਟ ਦੀ ਖੁਦਾਈ","ਸਿਰਫ਼ ਐਲੂਮੀਨੀਅਮ ਦੀ ਪੈਕਿੰਗ","ਐਲੂਮੀਨਾ ਦੀ ਗਲਾਈ ਨਾਲ ਐਲੂਮੀਨੀਅਮ ਬਣਾਉਣਾ","ਸਿਰਫ਼ ਅਯਸਕ ਦੀ ਢੋਆ-ਢੁਆਈ"],"ਬਿਜਲਈ ਅਪਘਟਨ ਨਾਲ ਗਲਾਈ ਕਰਨ ਦੇ ਪੜਾਅ ਵਿੱਚ ਬਹੁਤ ਵੱਡੀ ਮਾਤਰਾ ਵਿੱਚ ਬਿਜਲੀ ਵਰਤੀ ਜਾਂਦੀ ਹੈ।"]},
"GEO-IND-001-CP006-Q009":{"h":"458e5e3c","hi":["कथनों पर विचार कीजिए: I. ऐलुमिनियम प्रगलन में बहुत बिजली लगती है। II. प्रगलन संयंत्र बिजली के बड़े स्रोतों के पास लगाए जा सकते हैं। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","न तो I और न ही II सही है","I और II दोनों सही हैं"],"बिजली की अधिक माँग के कारण ऐलुमिनियम प्रगलन संयंत्र भरोसेमंद और सस्ती बिजली के स्रोतों के पास आकर्षित हो सकते हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਐਲੂਮੀਨੀਅਮ ਦੀ ਗਲਾਈ ਵਿੱਚ ਬਹੁਤ ਬਿਜਲੀ ਲੱਗਦੀ ਹੈ। II. ਗਲਾਈ ਪਲਾਂਟ ਬਿਜਲੀ ਦੇ ਵੱਡੇ ਸਰੋਤਾਂ ਨੇੜੇ ਲੱਗ ਸਕਦੇ ਹਨ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ"],"ਬਿਜਲੀ ਦੀ ਵੱਡੀ ਮੰਗ ਕਰਕੇ ਐਲੂਮੀਨੀਅਮ ਗਲਾਈ ਪਲਾਂਟ ਭਰੋਸੇਯੋਗ ਅਤੇ ਸਸਤੀ ਬਿਜਲੀ ਦੇ ਸਰੋਤਾਂ ਕੋਲ ਲੱਗ ਸਕਦੇ ਹਨ।"]},
"GEO-IND-001-CP006-Q010":{"h":"d35d1dba","hi":["कच्चे माल की आपूर्ति के बाद ऐलुमिनियम प्रगलन संयंत्र की अवस्थिति का सबसे महत्वपूर्ण कारक कौन-सा है?",["भरोसेमंद और सस्ती बिजली","पर्यटकों की आवाजाही","जूट की आपूर्ति","चाय के बागान"],"ऐलुमिनियम प्रगलन संयंत्र चलाने में बिजली सबसे अधिक इस्तेमाल होने वाले संसाधनों में से एक है।"],"pa":["ਕੱਚੇ ਮਾਲ ਦੀ ਸਪਲਾਈ ਤੋਂ ਬਾਅਦ ਐਲੂਮੀਨੀਅਮ ਗਲਾਈ ਪਲਾਂਟ ਦੀ ਥਾਂ ਲਈ ਸਭ ਤੋਂ ਅਹਿਮ ਕਾਰਕ ਕਿਹੜਾ ਹੈ?",["ਭਰੋਸੇਯੋਗ ਤੇ ਸਸਤੀ ਬਿਜਲੀ","ਸੈਲਾਨੀਆਂ ਦੀ ਆਵਾਜਾਈ","ਜੂਟ ਦੀ ਸਪਲਾਈ","ਚਾਹ ਦੇ ਬਾਗ਼"],"ਐਲੂਮੀਨੀਅਮ ਗਲਾਈ ਪਲਾਂਟ ਚਲਾਉਣ ਲਈ ਸਭ ਤੋਂ ਵੱਧ ਵਰਤੇ ਜਾਂਦੇ ਸਾਧਨਾਂ ਵਿੱਚ ਬਿਜਲੀ ਸ਼ਾਮਲ ਹੈ।"]},
"GEO-IND-001-CP006-Q011":{"h":"05067a0b","hi":["ऐलुमिनियम प्रगलन की अवस्थिति के संबंध में कौन-सा युग्म सही सुमेलित है?",["ऐलुमिनियम प्रगलन — जूट पट्टी","ऐलुमिनियम प्रगलन — भरपूर बिजली","ऐलुमिनियम प्रगलन — गन्ने का खेत","ऐलुमिनियम प्रगलन — ज्वारीय मत्स्य क्षेत्र"],"भरपूर बिजली की उपलब्धता ऐलुमिनियम प्रगलन के लिए एक प्रमुख अवस्थितिक लाभ है।"],"pa":["ਐਲੂਮੀਨੀਅਮ ਗਲਾਈ ਦੀ ਥਾਂ ਬਾਰੇ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਐਲੂਮੀਨੀਅਮ ਦੀ ਗਲਾਈ — ਜੂਟ ਪੱਟੀ","ਐਲੂਮੀਨੀਅਮ ਦੀ ਗਲਾਈ — ਭਰਪੂਰ ਬਿਜਲੀ","ਐਲੂਮੀਨੀਅਮ ਦੀ ਗਲਾਈ — ਗੰਨੇ ਦਾ ਖੇਤ","ਐਲੂਮੀਨੀਅਮ ਦੀ ਗਲਾਈ — ਜਵਾਰੀ ਮੱਛੀ-ਪਕੜ ਖੇਤਰ"],"ਭਰਪੂਰ ਬਿਜਲੀ ਮਿਲਣੀ ਐਲੂਮੀਨੀਅਮ ਦੀ ਗਲਾਈ ਲਈ ਥਾਂ ਦਾ ਇੱਕ ਪ੍ਰਮੁੱਖ ਲਾਭ ਹੈ।"]},
"GEO-IND-001-CP006-Q012":{"h":"ce8b7600","hi":["एक धातु संयंत्र बड़े बिजलीघर के पास बनाया गया है, क्योंकि उसकी विद्युत अपघटनी प्रक्रिया में बहुत अधिक बिजली लगती है। वहाँ कौन-सी धातु बनती है?",["जूट","चीनी","ऐलुमिनियम","सीमेंट"],"ऐलुमिनियम ऐसी विद्युत अपघटनी प्रक्रिया से बनाया जाता है जिसमें बहुत अधिक बिजली लगती है।"],"pa":["ਇੱਕ ਧਾਤ ਪਲਾਂਟ ਵੱਡੇ ਬਿਜਲੀ ਘਰ ਨੇੜੇ ਲੱਗਿਆ ਹੈ ਕਿਉਂਕਿ ਉਸ ਦੀ ਬਿਜਲਈ ਅਪਘਟਨ ਪ੍ਰਕਿਰਿਆ ਵਿੱਚ ਬਹੁਤ ਬਿਜਲੀ ਲੱਗਦੀ ਹੈ। ਕਿਹੜੀ ਧਾਤ ਬਣਦੀ ਹੈ?",["ਜੂਟ","ਖੰਡ","ਐਲੂਮੀਨੀਅਮ","ਸੀਮਿੰਟ"],"ਐਲੂਮੀਨੀਅਮ ਬਿਜਲਈ ਅਪਘਟਨ ਦੀ ਅਜਿਹੀ ਪ੍ਰਕਿਰਿਆ ਨਾਲ ਬਣਦਾ ਹੈ ਜਿਸ ਵਿੱਚ ਬਹੁਤ ਜ਼ਿਆਦਾ ਬਿਜਲੀ ਲੱਗਦੀ ਹੈ।"]},
"GEO-IND-001-CP006-Q013":{"h":"960bd698","hi":["किस राज्य में बॉक्साइट के बड़े संसाधन और विकसित ऐलुमिनियम उद्योग दोनों हैं?",["पंजाब","हरियाणा","असम","ओडिशा"],"ओडिशा में बॉक्साइट के विस्तृत संसाधन और ऐलुमिना/ऐलुमिनियम की प्रमुख उत्पादन इकाइयाँ हैं।"],"pa":["ਕਿਹੜੇ ਰਾਜ ਵਿੱਚ ਬਾਕਸਾਈਟ ਦੇ ਵੱਡੇ ਸਰੋਤ ਅਤੇ ਵਿਕਸਿਤ ਐਲੂਮੀਨੀਅਮ ਉਦਯੋਗ ਦੋਵੇਂ ਹਨ?",["ਪੰਜਾਬ","ਹਰਿਆਣਾ","ਅਸਾਮ","ਓਡੀਸ਼ਾ"],"ਓਡੀਸ਼ਾ ਵਿੱਚ ਬਾਕਸਾਈਟ ਦੇ ਵੱਡੇ ਸਰੋਤ ਅਤੇ ਐਲੂਮੀਨਾ/ਐਲੂਮੀਨੀਅਮ ਦੀਆਂ ਪ੍ਰਮੁੱਖ ਉਤਪਾਦਨ ਇਕਾਈਆਂ ਹਨ।"]},
"GEO-IND-001-CP006-Q014":{"h":"56b1d2ce","hi":["कौन-सा संसाधन ओडिशा को ऐलुमिनियम उत्पादन के लिए कच्चे माल का बड़ा लाभ देता है?",["बॉक्साइट","जूट","गन्ना","केवल अभ्रक"],"बॉक्साइट के बड़े निक्षेपों के कारण ओडिशा ऐलुमिना शोधन और ऐलुमिनियम उत्पादन के लिए स्वाभाविक रूप से उपयुक्त है।"],"pa":["ਕਿਹੜਾ ਸਰੋਤ ਓਡੀਸ਼ਾ ਨੂੰ ਐਲੂਮੀਨੀਅਮ ਬਣਾਉਣ ਲਈ ਕੱਚੇ ਮਾਲ ਦਾ ਵੱਡਾ ਲਾਭ ਦਿੰਦਾ ਹੈ?",["ਬਾਕਸਾਈਟ","ਜੂਟ","ਗੰਨਾ","ਸਿਰਫ਼ ਅਬਰਕ"],"ਬਾਕਸਾਈਟ ਦੇ ਵੱਡੇ ਭੰਡਾਰਾਂ ਕਰਕੇ ਓਡੀਸ਼ਾ ਐਲੂਮੀਨਾ ਦੀ ਸੋਧਾਈ ਅਤੇ ਐਲੂਮੀਨੀਅਮ ਉਤਪਾਦਨ ਲਈ ਸੁਭਾਵਕ ਤੌਰ 'ਤੇ ਢੁੱਕਵਾਂ ਹੈ।"]},
"GEO-IND-001-CP006-Q015":{"h":"f9825b92","hi":["कथनों पर विचार कीजिए: I. ओडिशा में बॉक्साइट के बड़े संसाधन हैं। II. राज्य में ऐलुमिनियम उत्पादन महत्वपूर्ण है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","I और II दोनों सही हैं","केवल II सही है","न तो I और न ही II सही है"],"राज्य के खनिज संसाधन उसके प्रमुख ऐलुमिनियम उद्योग का आधार हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਓਡੀਸ਼ਾ ਵਿੱਚ ਬਾਕਸਾਈਟ ਦੇ ਵੱਡੇ ਸਰੋਤ ਹਨ। II. ਇਸ ਰਾਜ ਵਿੱਚ ਐਲੂਮੀਨੀਅਮ ਦਾ ਉਤਪਾਦਨ ਅਹਿਮ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਰਾਜ ਦੇ ਖਣਿਜ ਸਰੋਤ ਇਸ ਦੇ ਪ੍ਰਮੁੱਖ ਐਲੂਮੀਨੀਅਮ ਉਦਯੋਗ ਨੂੰ ਆਧਾਰ ਦਿੰਦੇ ਹਨ।"]},
"GEO-IND-001-CP006-Q016":{"h":"50b785b7","hi":["ऐलुमिनियम उद्योग के भूगोल में कौन-सा युग्म सही सुमेलित है?",["ओडिशा — केवल जूट","ओडिशा — बॉक्साइट का अभाव","ओडिशा — बॉक्साइट और ऐलुमिनियम","ओडिशा — केवल चीनी"],"ओडिशा बॉक्साइट से समृद्ध है और ऐलुमिनियम उत्पादन में प्रमुख राज्य है।"],"pa":["ਐਲੂਮੀਨੀਅਮ ਉਦਯੋਗ ਦੇ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਓਡੀਸ਼ਾ — ਸਿਰਫ਼ ਜੂਟ","ਓਡੀਸ਼ਾ — ਬਾਕਸਾਈਟ ਦੀ ਅਣਹੋਂਦ","ਓਡੀਸ਼ਾ — ਬਾਕਸਾਈਟ ਅਤੇ ਐਲੂਮੀਨੀਅਮ","ਓਡੀਸ਼ਾ — ਸਿਰਫ਼ ਖੰਡ"],"ਓਡੀਸ਼ਾ ਬਾਕਸਾਈਟ ਨਾਲ ਭਰਪੂਰ ਹੈ ਅਤੇ ਐਲੂਮੀਨੀਅਮ ਉਤਪਾਦਨ ਵਿੱਚ ਪ੍ਰਮੁੱਖ ਰਾਜ ਹੈ।"]},
"GEO-IND-001-CP006-Q017":{"h":"f9d5fb0a","hi":["ओडिशा ऐलुमिनियम के शोधन और प्रगलन के लिए उपयुक्त क्यों है?",["वहाँ खनिज संसाधन नहीं हैं","केवल वर्षा का महत्व है","वह केवल आयातित कपास पर निर्भर है","बॉक्साइट, बिजली और औद्योगिक आधारभूत संरचना उपलब्ध हैं"],"कच्चे माल, ऊर्जा और आधारभूत संरचना का मेल ऐलुमिनियम उत्पादन में सहायक है।"],"pa":["ਓਡੀਸ਼ਾ ਐਲੂਮੀਨੀਅਮ ਦੀ ਸੋਧਾਈ ਅਤੇ ਗਲਾਈ ਲਈ ਢੁੱਕਵਾਂ ਕਿਉਂ ਹੈ?",["ਉੱਥੇ ਖਣਿਜ ਸਰੋਤ ਨਹੀਂ ਹਨ","ਸਿਰਫ਼ ਵਰਖਾ ਦਾ ਮਹੱਤਵ ਹੈ","ਇਹ ਸਿਰਫ਼ ਬਾਹਰੋਂ ਮੰਗਵਾਈ ਕਪਾਹ 'ਤੇ ਨਿਰਭਰ ਹੈ","ਬਾਕਸਾਈਟ, ਬਿਜਲੀ ਅਤੇ ਉਦਯੋਗਿਕ ਬੁਨਿਆਦੀ ਢਾਂਚਾ ਮਿਲਦੇ ਹਨ"],"ਕੱਚਾ ਮਾਲ, ਊਰਜਾ ਅਤੇ ਬੁਨਿਆਦੀ ਢਾਂਚਾ ਮਿਲ ਕੇ ਐਲੂਮੀਨੀਅਮ ਉਤਪਾਦਨ ਨੂੰ ਆਧਾਰ ਦਿੰਦੇ ਹਨ।"]},
"GEO-IND-001-CP006-Q018":{"h":"a0f6dcdd","hi":["एक मानचित्र में पंचपटमाली के बॉक्साइट क्षेत्र और प्रमुख ऐलुमिनियम उद्योग को एक ही राज्य में दिखाया गया है। वह राज्य कौन-सा है?",["ओडिशा","राजस्थान","पंजाब","केरल"],"पंचपटमाली ओडिशा का प्रमुख बॉक्साइट क्षेत्र है और राज्य के ऐलुमिनियम संसाधनों के भूगोल का हिस्सा है।"],"pa":["ਇੱਕ ਨਕਸ਼ੇ ਵਿੱਚ ਪੰਚਪਟਮਾਲੀ ਦਾ ਬਾਕਸਾਈਟ ਖੇਤਰ ਅਤੇ ਪ੍ਰਮੁੱਖ ਐਲੂਮੀਨੀਅਮ ਉਦਯੋਗ ਇੱਕੋ ਰਾਜ ਵਿੱਚ ਦਿਖਾਏ ਗਏ ਹਨ। ਉਹ ਕਿਹੜਾ ਰਾਜ ਹੈ?",["ਓਡੀਸ਼ਾ","ਰਾਜਸਥਾਨ","ਪੰਜਾਬ","ਕੇਰਲ"],"ਪੰਚਪਟਮਾਲੀ ਓਡੀਸ਼ਾ ਦਾ ਪ੍ਰਮੁੱਖ ਬਾਕਸਾਈਟ ਖੇਤਰ ਹੈ ਅਤੇ ਰਾਜ ਦੇ ਐਲੂਮੀਨੀਅਮ ਸਰੋਤਾਂ ਦੇ ਭੂਗੋਲ ਦਾ ਹਿੱਸਾ ਹੈ।"]},
"GEO-IND-001-CP006-Q019":{"h":"c3a4d021","hi":["परिवहन उपकरणों में ऐलुमिनियम का व्यापक उपयोग क्यों होता है?",["यह हल्का है और इससे मज़बूत मिश्रधातुएँ बन सकती हैं","यह अत्यंत भंगुर है","यह एक ईंधन है","यह पानी में आसानी से घुलता है"],"कम घनत्व और इसकी मिश्रधातुओं की उपयोगी मज़बूती के कारण ऐलुमिनियम विमान, वाहन और परिवहन उपकरणों के लिए उपयोगी है।"],"pa":["ਆਵਾਜਾਈ ਦੇ ਸਾਜ਼ੋ-ਸਾਮਾਨ ਵਿੱਚ ਐਲੂਮੀਨੀਅਮ ਦੀ ਵੱਡੇ ਪੱਧਰ 'ਤੇ ਵਰਤੋਂ ਕਿਉਂ ਹੁੰਦੀ ਹੈ?",["ਇਹ ਹਲਕਾ ਹੈ ਅਤੇ ਇਸ ਤੋਂ ਮਜ਼ਬੂਤ ਮਿਸ਼ਰਤ ਧਾਤਾਂ ਬਣ ਸਕਦੀਆਂ ਹਨ","ਇਹ ਬਹੁਤ ਭੁਰਭੁਰਾ ਹੈ","ਇਹ ਇੱਕ ਬਾਲਣ ਹੈ","ਇਹ ਪਾਣੀ ਵਿੱਚ ਸੌਖਿਆਂ ਘੁਲ ਜਾਂਦਾ ਹੈ"],"ਘੱਟ ਘਣਤਾ ਅਤੇ ਇਸ ਦੀਆਂ ਮਿਸ਼ਰਤ ਧਾਤਾਂ ਦੀ ਮਜ਼ਬੂਤੀ ਕਰਕੇ ਐਲੂਮੀਨੀਅਮ ਜਹਾਜ਼ਾਂ, ਵਾਹਨਾਂ ਅਤੇ ਆਵਾਜਾਈ ਦੇ ਸਾਜ਼ੋ-ਸਾਮਾਨ ਵਿੱਚ ਲਾਹੇਵੰਦ ਹੈ।"]},
"GEO-IND-001-CP006-Q020":{"h":"d3c51cc9","hi":["कौन-सा गुण विद्युत पारेषण में ऐलुमिनियम के उपयोग के लिए अनुकूल है?",["पूर्ण विद्युतरोधन","अच्छी विद्युत चालकता","बहुत अधिक भंगुरता","रेडियोधर्मिता"],"ऐलुमिनियम बिजली का चालक है और हल्का होता है। इसलिए यह ऊपर खींची गई विद्युत पारेषण लाइनों में उपयोगी है।"],"pa":["ਕਿਹੜਾ ਗੁਣ ਬਿਜਲੀ ਸੰਚਾਰ ਵਿੱਚ ਐਲੂਮੀਨੀਅਮ ਦੀ ਵਰਤੋਂ ਲਈ ਅਨੁਕੂਲ ਹੈ?",["ਪੂਰੀ ਤਰ੍ਹਾਂ ਬਿਜਲੀ ਨਾ ਲੰਘਣ ਦੇਣਾ","ਚੰਗੀ ਬਿਜਲਈ ਚਾਲਕਤਾ","ਬਹੁਤ ਵੱਧ ਭੁਰਭੁਰਾਪਣ","ਰੇਡੀਓਧਰਮਿਤਾ"],"ਐਲੂਮੀਨੀਅਮ ਬਿਜਲੀ ਦਾ ਚਾਲਕ ਹੈ ਅਤੇ ਹਲਕਾ ਵੀ ਹੈ। ਇਸ ਲਈ ਇਹ ਉੱਪਰ ਖਿੱਚੀਆਂ ਬਿਜਲੀ ਦੀਆਂ ਤਾਰਾਂ ਵਿੱਚ ਲਾਹੇਵੰਦ ਹੈ।"]},
"GEO-IND-001-CP006-Q021":{"h":"39569f98","hi":["कथनों पर विचार कीजिए: I. ऐलुमिनियम हल्का होता है। II. यह संक्षारण का अच्छी तरह प्रतिरोध करता है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","I और II दोनों सही हैं","न तो I और न ही II सही है"],"इन दोनों गुणों के कारण ऐलुमिनियम का व्यापक औद्योगिक उपयोग होता है।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਐਲੂਮੀਨੀਅਮ ਹਲਕਾ ਹੁੰਦਾ ਹੈ। II. ਇਹ ਖੋਰ ਦਾ ਚੰਗਾ ਟਾਕਰਾ ਕਰਦਾ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਇਨ੍ਹਾਂ ਦੋਵਾਂ ਗੁਣਾਂ ਕਰਕੇ ਉਦਯੋਗਾਂ ਵਿੱਚ ਐਲੂਮੀਨੀਅਮ ਦੀ ਵਿਆਪਕ ਵਰਤੋਂ ਹੁੰਦੀ ਹੈ।"]},
"GEO-IND-001-CP006-Q022":{"h":"fc18cc10","hi":["वज़न कम रखने की आवश्यकता के कारण किस उत्पाद में ऐलुमिनियम का आम तौर पर उपयोग होता है?",["कोयले की परत","गन्ने का तना","जूट का रेशा","विमान का ढाँचा और पुर्ज़े"],"विमानों में ऐलुमिनियम की मिश्रधातुएँ इस्तेमाल होती हैं, क्योंकि वे हल्की होने के साथ पर्याप्त मज़बूत होती हैं।"],"pa":["ਭਾਰ ਘੱਟ ਰੱਖਣ ਦੀ ਲੋੜ ਕਰਕੇ ਕਿਹੜੇ ਉਤਪਾਦ ਵਿੱਚ ਐਲੂਮੀਨੀਅਮ ਆਮ ਤੌਰ 'ਤੇ ਵਰਤਿਆ ਜਾਂਦਾ ਹੈ?",["ਕੋਲੇ ਦੀ ਪਰਤ","ਗੰਨੇ ਦਾ ਤਣਾ","ਜੂਟ ਦਾ ਰੇਸ਼ਾ","ਹਵਾਈ ਜਹਾਜ਼ ਦਾ ਢਾਂਚਾ ਅਤੇ ਪੁਰਜ਼ੇ"],"ਹਵਾਈ ਜਹਾਜ਼ਾਂ ਵਿੱਚ ਐਲੂਮੀਨੀਅਮ ਦੀਆਂ ਮਿਸ਼ਰਤ ਧਾਤਾਂ ਵਰਤੀਆਂ ਜਾਂਦੀਆਂ ਹਨ ਕਿਉਂਕਿ ਉਹ ਹਲਕੀਆਂ ਹੋਣ ਦੇ ਨਾਲ ਕਾਫ਼ੀ ਮਜ਼ਬੂਤ ਵੀ ਹੁੰਦੀਆਂ ਹਨ।"]},
"GEO-IND-001-CP006-Q023":{"h":"8e71291c","hi":["ऐलुमिनियम के उपयोग में कौन-सा युग्म सही सुमेलित है?",["ऐलुमिनियम — ऊपर लगी विद्युत लाइनों के चालक","ऐलुमिनियम — कोकिंग कोयला","ऐलुमिनियम — उर्वरक का कच्चा माल","ऐलुमिनियम — जूट का बोरा"],"अच्छी चालकता और कम वज़न के कारण ऐलुमिनियम का विद्युत चालकों में व्यापक उपयोग होता है।"],"pa":["ਐਲੂਮੀਨੀਅਮ ਦੀ ਵਰਤੋਂ ਬਾਰੇ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਐਲੂਮੀਨੀਅਮ — ਉੱਪਰ ਲੱਗੀਆਂ ਬਿਜਲੀ ਦੀਆਂ ਤਾਰਾਂ ਦੇ ਚਾਲਕ","ਐਲੂਮੀਨੀਅਮ — ਕੋਕਿੰਗ ਕੋਲਾ","ਐਲੂਮੀਨੀਅਮ — ਖਾਦ ਦਾ ਕੱਚਾ ਮਾਲ","ਐਲੂਮੀਨੀਅਮ — ਜੂਟ ਦੀ ਬੋਰੀ"],"ਚੰਗੀ ਚਾਲਕਤਾ ਅਤੇ ਘੱਟ ਭਾਰ ਕਰਕੇ ਬਿਜਲੀ ਦੇ ਚਾਲਕਾਂ ਵਿੱਚ ਐਲੂਮੀਨੀਅਮ ਦੀ ਵਿਆਪਕ ਵਰਤੋਂ ਹੁੰਦੀ ਹੈ।"]},
"GEO-IND-001-CP006-Q024":{"h":"4ae19012","hi":["गुणों का कौन-सा मेल अभियांत्रिकी में ऐलुमिनियम के व्यापक उपयोग को समझाता है?",["जल्दी खराब होना और चीनी की अधिक मात्रा","कम घनत्व, संक्षारण प्रतिरोध और चालकता","केवल चुंबकीय गुण","केवल रेडियोधर्मिता"],"ये भौतिक गुण ऐलुमिनियम को परिवहन, निर्माण और विद्युत संबंधी उपयोगों के लिए उपयुक्त बनाते हैं।"],"pa":["ਗੁਣਾਂ ਦਾ ਕਿਹੜਾ ਮੇਲ ਇੰਜੀਨੀਅਰਿੰਗ ਵਿੱਚ ਐਲੂਮੀਨੀਅਮ ਦੀ ਵਿਆਪਕ ਵਰਤੋਂ ਦਾ ਕਾਰਨ ਦੱਸਦਾ ਹੈ?",["ਛੇਤੀ ਖ਼ਰਾਬ ਹੋਣਾ ਅਤੇ ਖੰਡ ਦੀ ਵੱਧ ਮਾਤਰਾ","ਘੱਟ ਘਣਤਾ, ਖੋਰ ਦਾ ਟਾਕਰਾ ਅਤੇ ਚਾਲਕਤਾ","ਸਿਰਫ਼ ਚੁੰਬਕੀ ਗੁਣ","ਸਿਰਫ਼ ਰੇਡੀਓਧਰਮਿਤਾ"],"ਇਹ ਭੌਤਿਕ ਗੁਣ ਐਲੂਮੀਨੀਅਮ ਨੂੰ ਆਵਾਜਾਈ, ਉਸਾਰੀ ਅਤੇ ਬਿਜਲੀ ਨਾਲ ਜੁੜੇ ਕੰਮਾਂ ਲਈ ਲਾਹੇਵੰਦ ਬਣਾਉਂਦੇ ਹਨ।"]},
"GEO-IND-001-CP006-Q025":{"h":"1c2885d4","hi":["ताँबा उद्योग का मुख्य खनिज कच्चा माल कौन-सा है?",["बॉक्साइट","ताँबे का अयस्क","जिप्सम","केवल चूना पत्थर"],"ताँबायुक्त अयस्कों से ताँबा निकालकर औद्योगिक उपयोग के लिए उसका शोधन किया जाता है।"],"pa":["ਤਾਂਬਾ ਉਦਯੋਗ ਦਾ ਮੁੱਖ ਖਣਿਜ ਕੱਚਾ ਮਾਲ ਕਿਹੜਾ ਹੈ?",["ਬਾਕਸਾਈਟ","ਤਾਂਬੇ ਦਾ ਅਯਸਕ","ਜਿਪਸਮ","ਸਿਰਫ਼ ਚੂਨਾ ਪੱਥਰ"],"ਤਾਂਬੇ ਵਾਲੇ ਅਯਸਕਾਂ ਤੋਂ ਤਾਂਬਾ ਕੱਢਿਆ ਜਾਂਦਾ ਹੈ ਅਤੇ ਉਦਯੋਗਿਕ ਵਰਤੋਂ ਲਈ ਸੋਧਿਆ ਜਾਂਦਾ ਹੈ।"]},
"GEO-IND-001-CP006-Q026":{"h":"d99be6fa","hi":["भारत के किस स्थान का ताँबे के खनन और धातुकर्म से गहरा संबंध है?",["सांभर","नेवेली","खेतड़ी","झरिया"],"राजस्थान का खेतड़ी भारत में ताँबे के खनन और धातुकर्म के सबसे प्रसिद्ध केंद्रों में से एक है।"],"pa":["ਭਾਰਤ ਦੀ ਕਿਹੜੀ ਥਾਂ ਦਾ ਤਾਂਬੇ ਦੀ ਖੁਦਾਈ ਅਤੇ ਧਾਤਕਾਰੀ ਨਾਲ ਡੂੰਘਾ ਸਬੰਧ ਹੈ?",["ਸਾਂਭਰ","ਨੇਵੇਲੀ","ਖੇਤੜੀ","ਝਰੀਆ"],"ਰਾਜਸਥਾਨ ਦੀ ਖੇਤੜੀ ਤਾਂਬੇ ਦੀ ਖੁਦਾਈ ਅਤੇ ਧਾਤਕਾਰੀ ਲਈ ਭਾਰਤ ਦੇ ਸਭ ਤੋਂ ਮਸ਼ਹੂਰ ਕੇਂਦਰਾਂ ਵਿੱਚੋਂ ਇੱਕ ਹੈ।"]},
"GEO-IND-001-CP006-Q027":{"h":"e2751737","hi":["कथनों पर विचार कीजिए: I. ताँबा एक अलौह धातु है। II. खेतड़ी ताँबे का प्रमुख केंद्र है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","न तो I और न ही II सही है","I और II दोनों सही हैं"],"ताँबा अलौह धातुओं के समूह में आता है और खेतड़ी ताँबे का पारंपरिक केंद्र है।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਤਾਂਬਾ ਅਲੋਹ ਧਾਤ ਹੈ। II. ਖੇਤੜੀ ਤਾਂਬੇ ਦਾ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ"],"ਤਾਂਬਾ ਅਲੋਹ ਧਾਤਾਂ ਦੇ ਸਮੂਹ ਵਿੱਚ ਆਉਂਦਾ ਹੈ ਅਤੇ ਖੇਤੜੀ ਤਾਂਬੇ ਦਾ ਰਵਾਇਤੀ ਕੇਂਦਰ ਹੈ।"]},
"GEO-IND-001-CP006-Q028":{"h":"51f1ceca","hi":["ताँबा उद्योग के भूगोल में कौन-सा युग्म सही सुमेलित है?",["खेतड़ी — राजस्थान","खेतड़ी — ओडिशा","खेतड़ी — तमिलनाडु","खेतड़ी — असम"],"खेतड़ी राजस्थान में स्थित है।"],"pa":["ਤਾਂਬਾ ਉਦਯੋਗ ਦੇ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਖੇਤੜੀ — ਰਾਜਸਥਾਨ","ਖੇਤੜੀ — ਓਡੀਸ਼ਾ","ਖੇਤੜੀ — ਤਾਮਿਲਨਾਡੂ","ਖੇਤੜੀ — ਅਸਾਮ"],"ਖੇਤੜੀ ਰਾਜਸਥਾਨ ਵਿੱਚ ਹੈ।"]},
"GEO-IND-001-CP006-Q029":{"h":"ffd68443","hi":["ताँबा विद्युत उद्योगों के लिए क्यों महत्वपूर्ण है?",["यह ईंधन है","यह बिजली का उत्कृष्ट चालक है","यह विद्युतरोधी है","यह सीमेंट का कच्चा माल है"],"उच्च विद्युत चालकता के कारण तारों, मोटरों और विद्युत उपकरणों में ताँबे का उपयोग महत्वपूर्ण है।"],"pa":["ਬਿਜਲੀ ਨਾਲ ਜੁੜੇ ਉਦਯੋਗਾਂ ਲਈ ਤਾਂਬਾ ਅਹਿਮ ਕਿਉਂ ਹੈ?",["ਇਹ ਬਾਲਣ ਹੈ","ਇਹ ਬਿਜਲੀ ਦਾ ਬਹੁਤ ਵਧੀਆ ਚਾਲਕ ਹੈ","ਇਹ ਬਿਜਲੀ ਨਹੀਂ ਲੰਘਣ ਦਿੰਦਾ","ਇਹ ਸੀਮਿੰਟ ਦਾ ਕੱਚਾ ਮਾਲ ਹੈ"],"ਚੰਗੀ ਬਿਜਲਈ ਚਾਲਕਤਾ ਕਰਕੇ ਤਾਰਾਂ, ਮੋਟਰਾਂ ਅਤੇ ਬਿਜਲੀ ਦੇ ਸਾਜ਼ੋ-ਸਾਮਾਨ ਵਿੱਚ ਤਾਂਬੇ ਦੀ ਅਹਿਮੀਅਤ ਹੈ।"]},
"GEO-IND-001-CP006-Q030":{"h":"5e068ed8","hi":["एक धातु शोधन केंद्र खेतड़ी और विद्युत चालकों के उत्पादन से जुड़ा है। किस धातु की ओर संकेत है?",["केवल ऐलुमिनियम का अयस्क","जिप्सम","ताँबा","जूट"],"खेतड़ी और विद्युत चालकता, दोनों ताँबे की ओर प्रबल संकेत करते हैं।"],"pa":["ਇੱਕ ਧਾਤ ਸੋਧਾਈ ਕੇਂਦਰ ਖੇਤੜੀ ਅਤੇ ਬਿਜਲੀ ਦੇ ਚਾਲਕ ਬਣਾਉਣ ਨਾਲ ਜੁੜਿਆ ਹੈ। ਕਿਹੜੀ ਧਾਤ ਵੱਲ ਇਸ਼ਾਰਾ ਹੈ?",["ਸਿਰਫ਼ ਐਲੂਮੀਨੀਅਮ ਦਾ ਅਯਸਕ","ਜਿਪਸਮ","ਤਾਂਬਾ","ਜੂਟ"],"ਖੇਤੜੀ ਅਤੇ ਬਿਜਲਈ ਚਾਲਕਤਾ, ਦੋਵੇਂ ਤਾਂਬੇ ਵੱਲ ਸਪਸ਼ਟ ਇਸ਼ਾਰਾ ਕਰਦੇ ਹਨ।"]},
"GEO-IND-001-CP006-Q031":{"h":"1ba088bc","hi":["जावर जैसे सीसा-जस्ता खनन के प्रमुख केंद्र किस राज्य में हैं?",["पंजाब","राजस्थान","असम","केरल"],"राजस्थान भारत में सीसा-जस्ता खनन और धातुकर्म का पारंपरिक क्षेत्र है।"],"pa":["ਜ਼ਾਵਰ ਵਰਗੇ ਸਿੱਕਾ-ਜ਼ਿੰਕ ਦੀ ਖੁਦਾਈ ਦੇ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰ ਕਿਹੜੇ ਰਾਜ ਵਿੱਚ ਹਨ?",["ਪੰਜਾਬ","ਰਾਜਸਥਾਨ","ਅਸਾਮ","ਕੇਰਲ"],"ਰਾਜਸਥਾਨ ਭਾਰਤ ਵਿੱਚ ਸਿੱਕਾ-ਜ਼ਿੰਕ ਦੀ ਖੁਦਾਈ ਅਤੇ ਧਾਤਕਾਰੀ ਦਾ ਰਵਾਇਤੀ ਖੇਤਰ ਹੈ।"]},
"GEO-IND-001-CP006-Q032":{"h":"0a575d86","hi":["सीसा और जस्ता औद्योगिक धातुओं के किस समूह में आते हैं?",["लौह धातुएँ","ईंधन खनिज","अलौह धातुएँ","अधात्विक रेशे"],"सीसा और जस्ता धातुएँ हैं, लेकिन वे लोहे पर आधारित लौह समूह में नहीं आते।"],"pa":["ਸਿੱਕਾ ਅਤੇ ਜ਼ਿੰਕ ਉਦਯੋਗਿਕ ਧਾਤਾਂ ਦੇ ਕਿਹੜੇ ਸਮੂਹ ਵਿੱਚ ਆਉਂਦੇ ਹਨ?",["ਲੋਹ ਧਾਤਾਂ","ਬਾਲਣ ਖਣਿਜ","ਅਲੋਹ ਧਾਤਾਂ","ਅਧਾਤੂ ਰੇਸ਼ੇ"],"ਸਿੱਕਾ ਅਤੇ ਜ਼ਿੰਕ ਧਾਤਾਂ ਹਨ, ਪਰ ਇਹ ਲੋਹੇ 'ਤੇ ਆਧਾਰਿਤ ਲੋਹ ਸਮੂਹ ਵਿੱਚ ਨਹੀਂ ਆਉਂਦੇ।"]},
"GEO-IND-001-CP006-Q033":{"h":"dd132e64","hi":["कथनों पर विचार कीजिए: I. जावर का संबंध सीसा-जस्ता से है। II. राजस्थान सीसा-जस्ता के लिए प्रमुख राज्य है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","न तो I और न ही II सही है","I और II दोनों सही हैं"],"दोनों खनिज उद्योग के भूगोल के स्थापित तथ्य हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਜ਼ਾਵਰ ਦਾ ਸਬੰਧ ਸਿੱਕਾ-ਜ਼ਿੰਕ ਨਾਲ ਹੈ। II. ਰਾਜਸਥਾਨ ਸਿੱਕਾ-ਜ਼ਿੰਕ ਲਈ ਪ੍ਰਮੁੱਖ ਰਾਜ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ"],"ਇਹ ਦੋਵੇਂ ਖਣਿਜ ਉਦਯੋਗ ਦੇ ਭੂਗੋਲ ਦੇ ਸਥਾਪਤ ਤੱਥ ਹਨ।"]},
"GEO-IND-001-CP006-Q034":{"h":"076f97cc","hi":["सीसा-जस्ता उद्योग के भूगोल में कौन-सा युग्म सही सुमेलित है?",["जावर — राजस्थान","जावर — असम","जावर — तमिलनाडु","जावर — ओडिशा"],"जावर राजस्थान की अरावली खनिज पट्टी में है।"],"pa":["ਸਿੱਕਾ-ਜ਼ਿੰਕ ਉਦਯੋਗ ਦੇ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਜ਼ਾਵਰ — ਰਾਜਸਥਾਨ","ਜ਼ਾਵਰ — ਅਸਾਮ","ਜ਼ਾਵਰ — ਤਾਮਿਲਨਾਡੂ","ਜ਼ਾਵਰ — ਓਡੀਸ਼ਾ"],"ਜ਼ਾਵਰ ਰਾਜਸਥਾਨ ਦੀ ਅਰਾਵਲੀ ਖਣਿਜ ਪੱਟੀ ਵਿੱਚ ਹੈ।"]},
"GEO-IND-001-CP006-Q035":{"h":"82db344c","hi":["किस औद्योगिक श्रेणी में ताँबा, ऐलुमिनियम, सीसा और जस्ता शामिल हैं?",["कृषि प्रसंस्करण","अलौह धातुकर्म","जूट वस्त्र","चीनी उद्योग"],"ये धातुएँ लोहे पर आधारित लौह समूह से बाहर हैं और अलौह धातुकर्म की श्रेणी में आती हैं।"],"pa":["ਤਾਂਬਾ, ਐਲੂਮੀਨੀਅਮ, ਸਿੱਕਾ ਅਤੇ ਜ਼ਿੰਕ ਕਿਸ ਉਦਯੋਗਿਕ ਸ਼੍ਰੇਣੀ ਵਿੱਚ ਸ਼ਾਮਲ ਹਨ?",["ਖੇਤੀ ਉਪਜ ਦੀ ਪ੍ਰੋਸੈਸਿੰਗ","ਅਲੋਹ ਧਾਤਕਾਰੀ","ਜੂਟ ਦੇ ਕੱਪੜੇ","ਖੰਡ ਉਦਯੋਗ"],"ਇਹ ਧਾਤਾਂ ਲੋਹੇ 'ਤੇ ਆਧਾਰਿਤ ਸਮੂਹ ਵਿੱਚ ਨਹੀਂ ਆਉਂਦੀਆਂ। ਇਹ ਅਲੋਹ ਧਾਤਕਾਰੀ ਦੀ ਸ਼੍ਰੇਣੀ ਵਿੱਚ ਆਉਂਦੀਆਂ ਹਨ।"]},
"GEO-IND-001-CP006-Q036":{"h":"12afab89","hi":["एक खनिज और धातुकर्म मानचित्र में खेतड़ी और जावर को एक ही राज्य में दिखाया गया है। वह राज्य कौन-सा है?",["झारखंड","ओडिशा","राजस्थान","तमिलनाडु"],"ताँबे के लिए खेतड़ी और सीसा-जस्ता के लिए जावर, दोनों राजस्थान के प्रमुख केंद्र हैं।"],"pa":["ਖਣਿਜਾਂ ਅਤੇ ਧਾਤਕਾਰੀ ਦੇ ਇੱਕ ਨਕਸ਼ੇ ਵਿੱਚ ਖੇਤੜੀ ਅਤੇ ਜ਼ਾਵਰ ਇੱਕੋ ਰਾਜ ਵਿੱਚ ਦਿਖਾਏ ਗਏ ਹਨ। ਉਹ ਕਿਹੜਾ ਰਾਜ ਹੈ?",["ਝਾਰਖੰਡ","ਓਡੀਸ਼ਾ","ਰਾਜਸਥਾਨ","ਤਾਮਿਲਨਾਡੂ"],"ਤਾਂਬੇ ਲਈ ਖੇਤੜੀ ਅਤੇ ਸਿੱਕਾ-ਜ਼ਿੰਕ ਲਈ ਜ਼ਾਵਰ, ਦੋਵੇਂ ਰਾਜਸਥਾਨ ਦੇ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰ ਹਨ।"]},
"GEO-IND-001-CP006-Q037":{"h":"e95b83c9","hi":["दामनजोड़ी का ऐलुमिनियम उद्योग के किस चरण से गहरा संबंध है?",["जूट मिलों में उत्पादन","केवल इस्पात की बेलन प्रक्रिया","चीनी का परिष्करण","ऐलुमिना का शोधन"],"ओडिशा का दामनजोड़ी बॉक्साइट संसाधनों से जुड़ा ऐलुमिना शोधन का प्रमुख केंद्र है।"],"pa":["ਦਾਮਨਜੋੜੀ ਦਾ ਐਲੂਮੀਨੀਅਮ ਉਦਯੋਗ ਦੇ ਕਿਹੜੇ ਪੜਾਅ ਨਾਲ ਡੂੰਘਾ ਸਬੰਧ ਹੈ?",["ਜੂਟ ਮਿੱਲਾਂ ਵਿੱਚ ਉਤਪਾਦਨ","ਸਿਰਫ਼ ਸਟੀਲ ਨੂੰ ਰੋਲਰਾਂ ਨਾਲ ਦਬਾਉਣਾ","ਖੰਡ ਦੀ ਸੋਧਾਈ","ਐਲੂਮੀਨਾ ਦੀ ਸੋਧਾਈ"],"ਓਡੀਸ਼ਾ ਦੀ ਦਾਮਨਜੋੜੀ ਬਾਕਸਾਈਟ ਸਰੋਤਾਂ ਨਾਲ ਜੁੜਿਆ ਐਲੂਮੀਨਾ ਦੀ ਸੋਧਾਈ ਦਾ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰ ਹੈ।"]},
"GEO-IND-001-CP006-Q038":{"h":"4912df6c","hi":["अंगुल का ऐलुमिनियम उद्योग के किस चरण से गहरा संबंध है?",["ऐलुमिनियम प्रगलन","कपास की कताई","जूट को पानी में सड़ाना","सीमेंट की खुदाई"],"ओडिशा का अंगुल ऐलुमिनियम प्रगलन का प्रमुख केंद्र है।"],"pa":["ਅੰਗੁਲ ਦਾ ਐਲੂਮੀਨੀਅਮ ਉਦਯੋਗ ਦੇ ਕਿਹੜੇ ਪੜਾਅ ਨਾਲ ਡੂੰਘਾ ਸਬੰਧ ਹੈ?",["ਐਲੂਮੀਨੀਅਮ ਦੀ ਗਲਾਈ","ਕਪਾਹ ਦੀ ਕਤਾਈ","ਜੂਟ ਨੂੰ ਪਾਣੀ ਵਿੱਚ ਗਾਲਣਾ","ਸੀਮਿੰਟ ਦੀ ਖੁਦਾਈ"],"ਓਡੀਸ਼ਾ ਦਾ ਅੰਗੁਲ ਐਲੂਮੀਨੀਅਮ ਦੀ ਗਲਾਈ ਦਾ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰ ਹੈ।"]},
"GEO-IND-001-CP006-Q039":{"h":"d3282579","hi":["कौन-सा क्रम ओडिशा के दो ऐलुमिनियम केंद्रों को सही जोड़ता है?",["दामनजोड़ी — जूट; अंगुल — चीनी","दामनजोड़ी — ऐलुमिना; अंगुल — ऐलुमिनियम प्रगलन","दामनजोड़ी — इस्पात; अंगुल — चाय","दामनजोड़ी — पेट्रोलियम; अंगुल — कपास"],"ये दोनों केंद्र बॉक्साइट से ऐलुमिनियम बनाने की शृंखला के अलग-अलग चरणों के उदाहरण हैं।"],"pa":["ਕਿਹੜੀ ਲੜੀ ਓਡੀਸ਼ਾ ਦੇ ਦੋ ਐਲੂਮੀਨੀਅਮ ਕੇਂਦਰਾਂ ਨੂੰ ਸਹੀ ਜੋੜਦੀ ਹੈ?",["ਦਾਮਨਜੋੜੀ — ਜੂਟ; ਅੰਗੁਲ — ਖੰਡ","ਦਾਮਨਜੋੜੀ — ਐਲੂਮੀਨਾ; ਅੰਗੁਲ — ਐਲੂਮੀਨੀਅਮ ਦੀ ਗਲਾਈ","ਦਾਮਨਜੋੜੀ — ਸਟੀਲ; ਅੰਗੁਲ — ਚਾਹ","ਦਾਮਨਜੋੜੀ — ਪੈਟਰੋਲੀਅਮ; ਅੰਗੁਲ — ਕਪਾਹ"],"ਦੋਵੇਂ ਕੇਂਦਰ ਬਾਕਸਾਈਟ ਤੋਂ ਐਲੂਮੀਨੀਅਮ ਬਣਾਉਣ ਦੀ ਲੜੀ ਦੇ ਵੱਖੋ-ਵੱਖਰੇ ਪੜਾਵਾਂ ਦੀਆਂ ਉਦਾਹਰਨਾਂ ਹਨ।"]},
"GEO-IND-001-CP006-Q040":{"h":"94212cde","hi":["कथनों पर विचार कीजिए: I. दामनजोड़ी का संबंध ऐलुमिना से है। II. अंगुल का संबंध ऐलुमिनियम प्रगलन से है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","I और II दोनों सही हैं","न तो I और न ही II सही है"],"ओडिशा के ऐलुमिनियम उद्योग में इन दोनों संयंत्रों की अवस्थिति और उनके काम के बीच स्थापित संबंध हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਦਾਮਨਜੋੜੀ ਦਾ ਸਬੰਧ ਐਲੂਮੀਨਾ ਨਾਲ ਹੈ। II. ਅੰਗੁਲ ਦਾ ਸਬੰਧ ਐਲੂਮੀਨੀਅਮ ਦੀ ਗਲਾਈ ਨਾਲ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਓਡੀਸ਼ਾ ਦੇ ਐਲੂਮੀਨੀਅਮ ਉਦਯੋਗ ਵਿੱਚ ਇਨ੍ਹਾਂ ਦੋਵਾਂ ਥਾਵਾਂ 'ਤੇ ਇਹ ਕੰਮ ਲੰਮੇ ਸਮੇਂ ਤੋਂ ਹੁੰਦੇ ਆ ਰਹੇ ਹਨ।"]},
"GEO-IND-001-CP006-Q041":{"h":"2858314c","hi":["ऐलुमिना शोधन और ऐलुमिनियम प्रगलन हमेशा एक ही जगह क्यों नहीं होते?",["दोनों प्रक्रियाएँ एक जैसी हैं","दोनों में कच्चे माल की आवश्यकता नहीं है","प्रगलन में बिजली नहीं लगती","शोधन की अवस्थिति बॉक्साइट और प्रक्रिया की ज़रूरतों पर, जबकि प्रगलन की अवस्थिति मुख्यतः बिजली पर निर्भर करती है"],"दोनों चरण एक ही औद्योगिक शृंखला में हैं, लेकिन उनकी अवस्थिति की प्राथमिकताएँ अलग हैं।"],"pa":["ਐਲੂਮੀਨਾ ਦੀ ਸੋਧਾਈ ਅਤੇ ਐਲੂਮੀਨੀਅਮ ਦੀ ਗਲਾਈ ਹਮੇਸ਼ਾ ਇੱਕੋ ਥਾਂ ਕਿਉਂ ਨਹੀਂ ਹੁੰਦੀਆਂ?",["ਦੋਵੇਂ ਪ੍ਰਕਿਰਿਆਵਾਂ ਇੱਕੋ ਜਿਹੀਆਂ ਹਨ","ਦੋਵਾਂ ਨੂੰ ਕੱਚਾ ਮਾਲ ਨਹੀਂ ਚਾਹੀਦਾ","ਗਲਾਈ ਵਿੱਚ ਬਿਜਲੀ ਨਹੀਂ ਲੱਗਦੀ","ਸੋਧਾਈ ਦੀ ਥਾਂ ਬਾਕਸਾਈਟ ਤੇ ਪ੍ਰਕਿਰਿਆ ਦੀਆਂ ਲੋੜਾਂ ਅਤੇ ਗਲਾਈ ਦੀ ਥਾਂ ਮੁੱਖ ਤੌਰ 'ਤੇ ਬਿਜਲੀ 'ਤੇ ਨਿਰਭਰ ਹੈ"],"ਦੋਵੇਂ ਪੜਾਅ ਇੱਕੋ ਉਦਯੋਗਿਕ ਲੜੀ ਦੇ ਹਨ, ਪਰ ਥਾਂ ਦੀ ਚੋਣ ਵੇਲੇ ਦੋਵਾਂ ਦੀਆਂ ਤਰਜੀਹਾਂ ਵੱਖੋ-ਵੱਖਰੀਆਂ ਹਨ।"]},
"GEO-IND-001-CP006-Q042":{"h":"bebcce3f","hi":["ओडिशा के ऐलुमिनियम उद्योग के भूगोल में कौन-सी तुलना सही है?",["दामनजोड़ी शोधन का और अंगुल प्रगलन का केंद्र है","दोनों जूट के केंद्र हैं","अंगुल केवल कोयला क्षेत्र है","दामनजोड़ी चीनी का केंद्र है"],"ये स्थान ऐलुमिनियम उत्पादन के अलग-अलग चरणों के केंद्र हैं।"],"pa":["ਓਡੀਸ਼ਾ ਦੇ ਐਲੂਮੀਨੀਅਮ ਉਦਯੋਗ ਦੇ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜੀ ਤੁਲਨਾ ਸਹੀ ਹੈ?",["ਦਾਮਨਜੋੜੀ ਸੋਧਾਈ ਦਾ ਅਤੇ ਅੰਗੁਲ ਗਲਾਈ ਦਾ ਕੇਂਦਰ ਹੈ","ਦੋਵੇਂ ਜੂਟ ਦੇ ਕੇਂਦਰ ਹਨ","ਅੰਗੁਲ ਸਿਰਫ਼ ਕੋਲਾ ਖੇਤਰ ਹੈ","ਦਾਮਨਜੋੜੀ ਖੰਡ ਦਾ ਕੇਂਦਰ ਹੈ"],"ਦੋਵੇਂ ਥਾਵਾਂ ਐਲੂਮੀਨੀਅਮ ਉਤਪਾਦਨ ਦੇ ਵੱਖੋ-ਵੱਖਰੇ ਪੜਾਵਾਂ ਦੇ ਕੇਂਦਰ ਹਨ।"]},
"GEO-IND-001-CP006-Q043":{"h":"f835b2b2","hi":["प्रमुख ऐलुमिनियम प्रगलन केंद्र कोरबा किस राज्य में है?",["पंजाब","असम","छत्तीसगढ़","केरल"],"छत्तीसगढ़ के कोरबा का ऐलुमिनियम प्रगलन और बड़े पैमाने पर बिजली उत्पादन से संबंध है।"],"pa":["ਐਲੂਮੀਨੀਅਮ ਦੀ ਗਲਾਈ ਦਾ ਅਹਿਮ ਕੇਂਦਰ ਕੋਰਬਾ ਕਿਹੜੇ ਰਾਜ ਵਿੱਚ ਹੈ?",["ਪੰਜਾਬ","ਅਸਾਮ","ਛੱਤੀਸਗੜ੍ਹ","ਕੇਰਲ"],"ਛੱਤੀਸਗੜ੍ਹ ਦਾ ਕੋਰਬਾ ਐਲੂਮੀਨੀਅਮ ਦੀ ਗਲਾਈ ਅਤੇ ਵੱਡੇ ਪੱਧਰ 'ਤੇ ਬਿਜਲੀ ਉਤਪਾਦਨ ਨਾਲ ਜੁੜਿਆ ਹੈ।"]},
"GEO-IND-001-CP006-Q044":{"h":"8b7580f7","hi":["प्रमुख ऐलुमिनियम केंद्र रेणुकूट किस राज्य में है?",["ओडिशा","तमिलनाडु","गुजरात","उत्तर प्रदेश"],"उत्तर प्रदेश के सोनभद्र ज़िले का रेणुकूट ऐलुमिनियम उद्योग का एक प्रमुख केंद्र है।"],"pa":["ਐਲੂਮੀਨੀਅਮ ਦਾ ਅਹਿਮ ਕੇਂਦਰ ਰੇਣੂਕੂਟ ਕਿਹੜੇ ਰਾਜ ਵਿੱਚ ਹੈ?",["ਓਡੀਸ਼ਾ","ਤਾਮਿਲਨਾਡੂ","ਗੁਜਰਾਤ","ਉੱਤਰ ਪ੍ਰਦੇਸ਼"],"ਉੱਤਰ ਪ੍ਰਦੇਸ਼ ਦੇ ਸੋਨਭੱਦਰ ਜ਼ਿਲ੍ਹੇ ਦਾ ਰੇਣੂਕੂਟ ਐਲੂਮੀਨੀਅਮ ਉਦਯੋਗ ਦਾ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰ ਹੈ।"]},
"GEO-IND-001-CP006-Q045":{"h":"27852d61","hi":["कौन-सा कारक कोरबा और रेणुकूट में ऐलुमिनियम प्रगलन को मज़बूत आधार देता है?",["बिजली की भरपूर आपूर्ति","जूट की खेती","समुद्री मत्स्यन","केवल कपास के खेत"],"दोनों केंद्रों को ऐसे औद्योगिक क्षेत्रों में होने का लाभ मिलता है जहाँ बिजली भरपूर है।"],"pa":["ਕਿਹੜਾ ਕਾਰਕ ਕੋਰਬਾ ਅਤੇ ਰੇਣੂਕੂਟ ਵਿੱਚ ਐਲੂਮੀਨੀਅਮ ਦੀ ਗਲਾਈ ਨੂੰ ਮਜ਼ਬੂਤ ਆਧਾਰ ਦਿੰਦਾ ਹੈ?",["ਬਿਜਲੀ ਦੀ ਭਰਪੂਰ ਸਪਲਾਈ","ਜੂਟ ਦੀ ਖੇਤੀ","ਸਮੁੰਦਰੀ ਮੱਛੀ ਫੜਨ ਦਾ ਕੰਮ","ਸਿਰਫ਼ ਕਪਾਹ ਦੇ ਖੇਤ"],"ਦੋਵੇਂ ਕੇਂਦਰਾਂ ਨੂੰ ਬਿਜਲੀ ਨਾਲ ਭਰਪੂਰ ਉਦਯੋਗਿਕ ਇਲਾਕਿਆਂ ਵਿੱਚ ਹੋਣ ਦਾ ਫ਼ਾਇਦਾ ਮਿਲਦਾ ਹੈ।"]},
"GEO-IND-001-CP006-Q046":{"h":"fe76c74e","hi":["कथनों पर विचार कीजिए: I. कोरबा छत्तीसगढ़ में है। II. रेणुकूट उत्तर प्रदेश में है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","I और II दोनों सही हैं","केवल II सही है","न तो I और न ही II सही है"],"दोनों स्थानों के लिए दिए गए राज्य सही हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਕੋਰਬਾ ਛੱਤੀਸਗੜ੍ਹ ਵਿੱਚ ਹੈ। II. ਰੇਣੂਕੂਟ ਉੱਤਰ ਪ੍ਰਦੇਸ਼ ਵਿੱਚ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਦੋਵਾਂ ਥਾਵਾਂ ਲਈ ਦੱਸੇ ਰਾਜ ਸਹੀ ਹਨ।"]},
"GEO-IND-001-CP006-Q047":{"h":"49279620","hi":["ऐलुमिनियम उद्योग के भूगोल में कौन-सा युग्म रेणुकूट की सही पहचान करता है?",["रेणुकूट — ओडिशा","कोरबा — तमिलनाडु","रेणुकूट — उत्तर प्रदेश","कोरबा — असम"],"रेणुकूट उत्तर प्रदेश में है और कोरबा छत्तीसगढ़ में है।"],"pa":["ਐਲੂਮੀਨੀਅਮ ਉਦਯੋਗ ਦੇ ਭੂਗੋਲ ਵਿੱਚ ਰੇਣੂਕੂਟ ਦੀ ਸਹੀ ਪਛਾਣ ਕਿਹੜਾ ਜੋੜਾ ਕਰਦਾ ਹੈ?",["ਰੇਣੂਕੂਟ — ਓਡੀਸ਼ਾ","ਕੋਰਬਾ — ਤਾਮਿਲਨਾਡੂ","ਰੇਣੂਕੂਟ — ਉੱਤਰ ਪ੍ਰਦੇਸ਼","ਕੋਰਬਾ — ਅਸਾਮ"],"ਰੇਣੂਕੂਟ ਉੱਤਰ ਪ੍ਰਦੇਸ਼ ਵਿੱਚ ਹੈ ਅਤੇ ਕੋਰਬਾ ਛੱਤੀਸਗੜ੍ਹ ਵਿੱਚ ਹੈ।"]},
"GEO-IND-001-CP006-Q048":{"h":"24cd8143","hi":["कोरबा और रेणुकूट ऐलुमिनियम प्रगलन संयंत्रों की अवस्थिति के बारे में क्या दर्शाते हैं?",["प्रगलन संयंत्रों को बिजली नहीं चाहिए","केवल पत्तनों का महत्व है","ऐलुमिनियम कोयले से बनता है","बिजली की उपलब्धता प्रगलन संयंत्र को बॉक्साइट की खदान से दूर खींच सकती है"],"प्रगलन में बहुत अधिक बिजली लगती है। इसलिए बिजली की भरपूर आपूर्ति अवस्थिति तय करने में निर्णायक हो सकती है।"],"pa":["ਕੋਰਬਾ ਅਤੇ ਰੇਣੂਕੂਟ ਐਲੂਮੀਨੀਅਮ ਦੀ ਗਲਾਈ ਦੀ ਥਾਂ ਬਾਰੇ ਕੀ ਦਰਸਾਉਂਦੇ ਹਨ?",["ਗਲਾਈ ਪਲਾਂਟਾਂ ਨੂੰ ਬਿਜਲੀ ਨਹੀਂ ਚਾਹੀਦੀ","ਸਿਰਫ਼ ਬੰਦਰਗਾਹਾਂ ਦਾ ਮਹੱਤਵ ਹੈ","ਐਲੂਮੀਨੀਅਮ ਕੋਲੇ ਤੋਂ ਬਣਦਾ ਹੈ","ਬਿਜਲੀ ਮਿਲਣ ਕਾਰਨ ਗਲਾਈ ਪਲਾਂਟ ਬਾਕਸਾਈਟ ਖਾਣ ਤੋਂ ਦੂਰ ਲੱਗ ਸਕਦੇ ਹਨ"],"ਗਲਾਈ ਵਿੱਚ ਬਹੁਤ ਜ਼ਿਆਦਾ ਬਿਜਲੀ ਲੱਗਦੀ ਹੈ। ਇਸ ਲਈ ਥਾਂ ਚੁਣਨ ਵੇਲੇ ਬਿਜਲੀ ਦੀ ਵੱਡੀ ਸਪਲਾਈ ਫ਼ੈਸਲਾਕੁਨ ਹੋ ਸਕਦੀ ਹੈ।"]},
"GEO-IND-001-CP006-Q049":{"h":"9d204a36","hi":["मलांजखंड की ताँबे की खदान किस राज्य में है?",["राजस्थान","झारखंड","मध्य प्रदेश","ओडिशा"],"मध्य प्रदेश के बालाघाट ज़िले का मलांजखंड ताँबा खनन का प्रमुख केंद्र है।"],"pa":["ਮਲਾਂਜਖੰਡ ਦੀ ਤਾਂਬੇ ਦੀ ਖਾਣ ਕਿਹੜੇ ਰਾਜ ਵਿੱਚ ਹੈ?",["ਰਾਜਸਥਾਨ","ਝਾਰਖੰਡ","ਮੱਧ ਪ੍ਰਦੇਸ਼","ਓਡੀਸ਼ਾ"],"ਮੱਧ ਪ੍ਰਦੇਸ਼ ਦੇ ਬਾਲਾਘਾਟ ਜ਼ਿਲ੍ਹੇ ਦਾ ਮਲਾਂਜਖੰਡ ਤਾਂਬੇ ਦੀ ਖੁਦਾਈ ਦਾ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰ ਹੈ।"]},
"GEO-IND-001-CP006-Q050":{"h":"03fb5669","hi":["घाटशिला का ऐतिहासिक संबंध किस धातु उद्योग से है?",["ऐलुमिनियम","केवल लौह अयस्क","जूट","ताँबा"],"झारखंड का घाटशिला ताँबे के खनन और धातुकर्म का ऐतिहासिक केंद्र है।"],"pa":["ਘਾਟਸ਼ਿਲਾ ਦਾ ਇਤਿਹਾਸਕ ਸਬੰਧ ਕਿਸ ਧਾਤ ਉਦਯੋਗ ਨਾਲ ਹੈ?",["ਐਲੂਮੀਨੀਅਮ","ਸਿਰਫ਼ ਕੱਚਾ ਲੋਹਾ","ਜੂਟ","ਤਾਂਬਾ"],"ਝਾਰਖੰਡ ਦਾ ਘਾਟਸ਼ਿਲਾ ਤਾਂਬੇ ਦੀ ਖੁਦਾਈ ਅਤੇ ਧਾਤਕਾਰੀ ਦਾ ਇਤਿਹਾਸਕ ਕੇਂਦਰ ਹੈ।"]},
"GEO-IND-001-CP006-Q051":{"h":"55e23961","hi":["कथनों पर विचार कीजिए: I. मलांजखंड मध्य प्रदेश में है। II. घाटशिला झारखंड में है। कौन-सा/से कथन सही है/हैं?",["I और II दोनों सही हैं","केवल I सही है","केवल II सही है","न तो I और न ही II सही है"],"दोनों अलग-अलग राज्यों के महत्वपूर्ण ताँबा केंद्र हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਮਲਾਂਜਖੰਡ ਮੱਧ ਪ੍ਰਦੇਸ਼ ਵਿੱਚ ਹੈ। II. ਘਾਟਸ਼ਿਲਾ ਝਾਰਖੰਡ ਵਿੱਚ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਦੋਵੇਂ ਵੱਖੋ-ਵੱਖਰੇ ਰਾਜਾਂ ਦੇ ਅਹਿਮ ਤਾਂਬਾ ਕੇਂਦਰ ਹਨ।"]},
"GEO-IND-001-CP006-Q052":{"h":"db755b7d","hi":["ताँबा उद्योग के भूगोल में कौन-सा युग्म मलांजखंड की सही पहचान करता है?",["मलांजखंड — राजस्थान","मलांजखंड — मध्य प्रदेश","घाटशिला — तमिलनाडु","घाटशिला — गुजरात"],"मलांजखंड मध्य प्रदेश में और घाटशिला झारखंड में है।"],"pa":["ਤਾਂਬਾ ਉਦਯੋਗ ਦੇ ਭੂਗੋਲ ਵਿੱਚ ਮਲਾਂਜਖੰਡ ਦੀ ਸਹੀ ਪਛਾਣ ਕਿਹੜਾ ਜੋੜਾ ਕਰਦਾ ਹੈ?",["ਮਲਾਂਜਖੰਡ — ਰਾਜਸਥਾਨ","ਮਲਾਂਜਖੰਡ — ਮੱਧ ਪ੍ਰਦੇਸ਼","ਘਾਟਸ਼ਿਲਾ — ਤਾਮਿਲਨਾਡੂ","ਘਾਟਸ਼ਿਲਾ — ਗੁਜਰਾਤ"],"ਮਲਾਂਜਖੰਡ ਮੱਧ ਪ੍ਰਦੇਸ਼ ਵਿੱਚ ਹੈ ਅਤੇ ਘਾਟਸ਼ਿਲਾ ਝਾਰਖੰਡ ਵਿੱਚ ਹੈ।"]},
"GEO-IND-001-CP006-Q053":{"h":"bbca2b51","hi":["किस समूह में केवल ताँबे के प्रमुख केंद्र शामिल हैं?",["झरिया, नेवेली और डिगबोई","कोडरमा, सांभर और पन्ना","खेतड़ी, मलांजखंड और घाटशिला","राउरकेला, दुर्गापुर और भिलाई"],"खेतड़ी, मलांजखंड और घाटशिला ताँबा खनन/धातुकर्म के पारंपरिक केंद्र हैं।"],"pa":["ਕਿਹੜੇ ਸਮੂਹ ਵਿੱਚ ਸਿਰਫ਼ ਤਾਂਬੇ ਦੇ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰ ਸ਼ਾਮਲ ਹਨ?",["ਝਰੀਆ, ਨੇਵੇਲੀ ਅਤੇ ਡਿਗਬੋਈ","ਕੋਡਰਮਾ, ਸਾਂਭਰ ਅਤੇ ਪੰਨਾ","ਖੇਤੜੀ, ਮਲਾਂਜਖੰਡ ਅਤੇ ਘਾਟਸ਼ਿਲਾ","ਰਾਉਰਕੇਲਾ, ਦੁਰਗਾਪੁਰ ਅਤੇ ਭਿਲਾਈ"],"ਖੇਤੜੀ, ਮਲਾਂਜਖੰਡ ਅਤੇ ਘਾਟਸ਼ਿਲਾ ਤਾਂਬੇ ਦੀ ਖੁਦਾਈ/ਧਾਤਕਾਰੀ ਦੇ ਰਵਾਇਤੀ ਕੇਂਦਰ ਹਨ।"]},
"GEO-IND-001-CP006-Q054":{"h":"789356da","hi":["एक मानचित्र में राजस्थान, मध्य प्रदेश और झारखंड के ताँबा केंद्र दिखाए गए हैं। कौन-सा क्रम सही बैठता है?",["झरिया — नेवेली — डिगबोई","सांभर — पन्ना — कोडरमा","भिलाई — राउरकेला — सेलम","खेतड़ी — मलांजखंड — घाटशिला"],"यह क्रम तीनों राज्यों को उनके प्रमुख ताँबा केंद्रों से सही जोड़ता है।"],"pa":["ਇੱਕ ਨਕਸ਼ੇ ਵਿੱਚ ਰਾਜਸਥਾਨ, ਮੱਧ ਪ੍ਰਦੇਸ਼ ਅਤੇ ਝਾਰਖੰਡ ਦੇ ਤਾਂਬਾ ਕੇਂਦਰ ਦਿਖਾਏ ਗਏ ਹਨ। ਕਿਹੜਾ ਕ੍ਰਮ ਸਹੀ ਹੈ?",["ਝਰੀਆ — ਨੇਵੇਲੀ — ਡਿਗਬੋਈ","ਸਾਂਭਰ — ਪੰਨਾ — ਕੋਡਰਮਾ","ਭਿਲਾਈ — ਰਾਉਰਕੇਲਾ — ਸੇਲਮ","ਖੇਤੜੀ — ਮਲਾਂਜਖੰਡ — ਘਾਟਸ਼ਿਲਾ"],"ਇਹ ਕ੍ਰਮ ਤਿੰਨਾਂ ਰਾਜਾਂ ਨੂੰ ਉਨ੍ਹਾਂ ਦੇ ਪ੍ਰਮੁੱਖ ਤਾਂਬਾ ਕੇਂਦਰਾਂ ਨਾਲ ਸਹੀ ਜੋੜਦਾ ਹੈ।"]},
"GEO-IND-001-CP006-Q055":{"h":"7e648b73","hi":["ऐलुमिनियम उद्योग में पुनर्चक्रण का विशेष महत्व क्यों है?",["पुनर्चक्रित ऐलुमिनियम दोबारा इस्तेमाल नहीं हो सकता","बॉक्साइट एक ईंधन है","पुनर्चक्रण के लिए अधिक अयस्क चाहिए","अयस्क से प्राथमिक ऐलुमिनियम बनाने की तुलना में पुनर्चक्रण में बहुत कम ऊर्जा लगती है"],"द्वितीयक ऐलुमिनियम बनाने में प्राथमिक धातु के लिए ज़रूरी ऊर्जा-प्रधान शोधन और प्रगलन का बड़ा हिस्सा बच जाता है।"],"pa":["ਐਲੂਮੀਨੀਅਮ ਉਦਯੋਗ ਵਿੱਚ ਮੁੜ-ਵਰਤੋਂ ਲਈ ਪ੍ਰੋਸੈਸਿੰਗ ਖ਼ਾਸ ਲਾਹੇਵੰਦ ਕਿਉਂ ਹੈ?",["ਮੁੜ ਪ੍ਰੋਸੈਸ ਕੀਤਾ ਐਲੂਮੀਨੀਅਮ ਦੁਬਾਰਾ ਵਰਤਿਆ ਨਹੀਂ ਜਾ ਸਕਦਾ","ਬਾਕਸਾਈਟ ਇੱਕ ਬਾਲਣ ਹੈ","ਮੁੜ ਪ੍ਰੋਸੈਸ ਕਰਨ ਲਈ ਵੱਧ ਅਯਸਕ ਚਾਹੀਦਾ ਹੈ","ਅਯਸਕ ਤੋਂ ਮੁੱਢਲਾ ਐਲੂਮੀਨੀਅਮ ਬਣਾਉਣ ਨਾਲੋਂ ਮੁੜ ਪ੍ਰੋਸੈਸ ਕਰਨ ਵਿੱਚ ਕਿਤੇ ਘੱਟ ਊਰਜਾ ਲੱਗਦੀ ਹੈ"],"ਦੁਜੈਲਾ ਐਲੂਮੀਨੀਅਮ ਬਣਾਉਣ ਨਾਲ ਮੁੱਢਲੀ ਧਾਤ ਲਈ ਲੋੜੀਂਦੀ ਵੱਧ ਊਰਜਾ ਵਾਲੀ ਸੋਧਾਈ ਤੇ ਗਲਾਈ ਦਾ ਵੱਡਾ ਹਿੱਸਾ ਬਚ ਜਾਂਦਾ ਹੈ।"]},
"GEO-IND-001-CP006-Q056":{"h":"496b01de","hi":["द्वितीयक ऐलुमिनियम क्या है?",["धातु के कबाड़ के पुनर्चक्रण से बना ऐलुमिनियम","बॉक्साइट अयस्क","प्रगलन से पहले का ऐलुमिना","लोहे की मिश्रधातु"],"द्वितीयक ऐलुमिनियम सीधे बॉक्साइट से बनाने के बजाय ऐलुमिनियम के कबाड़ से प्राप्त किया जाता है।"],"pa":["ਦੁਜੈਲਾ ਐਲੂਮੀਨੀਅਮ ਕੀ ਹੈ?",["ਕਬਾੜ ਨੂੰ ਮੁੜ ਪ੍ਰੋਸੈਸ ਕਰਕੇ ਬਣਿਆ ਐਲੂਮੀਨੀਅਮ","ਬਾਕਸਾਈਟ ਅਯਸਕ","ਗਲਾਈ ਤੋਂ ਪਹਿਲਾਂ ਦਾ ਐਲੂਮੀਨਾ","ਲੋਹੇ ਦੀ ਮਿਸ਼ਰਤ ਧਾਤ"],"ਦੁਜੈਲਾ ਐਲੂਮੀਨੀਅਮ ਬਾਕਸਾਈਟ ਤੋਂ ਸਿੱਧਾ ਬਣਾਉਣ ਦੀ ਥਾਂ ਐਲੂਮੀਨੀਅਮ ਦੇ ਕਬਾੜ ਤੋਂ ਲਿਆ ਜਾਂਦਾ ਹੈ।"]},
"GEO-IND-001-CP006-Q057":{"h":"a03383f6","hi":["कथनों पर विचार कीजिए: I. ऐलुमिनियम का पुनर्चक्रण किया जा सकता है। II. प्राथमिक प्रगलन की तुलना में पुनर्चक्रण से ऊर्जा की माँग घटती है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","I और II दोनों सही हैं","केवल II सही है","न तो I और न ही II सही है"],"दोनों कथन बताते हैं कि ऐलुमिनियम का पुनर्चक्रण औद्योगिक रूप से महत्वपूर्ण क्यों है।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਐਲੂਮੀਨੀਅਮ ਨੂੰ ਮੁੜ ਵਰਤਣ ਲਈ ਪ੍ਰੋਸੈਸ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ। II. ਮੁੱਢਲੀ ਗਲਾਈ ਨਾਲੋਂ ਮੁੜ ਪ੍ਰੋਸੈਸ ਕਰਨ ਨਾਲ ਊਰਜਾ ਦੀ ਮੰਗ ਘਟਦੀ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਦੋਵੇਂ ਕਥਨ ਦੱਸਦੇ ਹਨ ਕਿ ਐਲੂਮੀਨੀਅਮ ਨੂੰ ਮੁੜ ਵਰਤਣ ਲਈ ਪ੍ਰੋਸੈਸ ਕਰਨਾ ਉਦਯੋਗ ਲਈ ਅਹਿਮ ਕਿਉਂ ਹੈ।"]},
"GEO-IND-001-CP006-Q058":{"h":"576513e1","hi":["ऐलुमिनियम उत्पादन में कौन-सा युग्म सही सुमेलित है?",["द्वितीयक ऐलुमिनियम — कच्चा जूट","प्राथमिक ऐलुमिनियम — गन्ना","द्वितीयक ऐलुमिनियम — पुनर्चक्रित धातु का कबाड़","बॉक्साइट — पुनर्चक्रित इस्पात"],"द्वितीयक ऐलुमिनियम कबाड़ से बनता है, जबकि प्राथमिक ऐलुमिनियम बॉक्साइट से प्राप्त होता है।"],"pa":["ਐਲੂਮੀਨੀਅਮ ਉਤਪਾਦਨ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਦੁਜੈਲਾ ਐਲੂਮੀਨੀਅਮ — ਕੱਚਾ ਜੂਟ","ਮੁੱਢਲਾ ਐਲੂਮੀਨੀਅਮ — ਗੰਨਾ","ਦੁਜੈਲਾ ਐਲੂਮੀਨੀਅਮ — ਮੁੜ ਪ੍ਰੋਸੈਸ ਕੀਤਾ ਕਬਾੜ","ਬਾਕਸਾਈਟ — ਮੁੜ ਪ੍ਰੋਸੈਸ ਕੀਤਾ ਸਟੀਲ"],"ਦੁਜੈਲਾ ਐਲੂਮੀਨੀਅਮ ਕਬਾੜ ਤੋਂ ਬਣਦਾ ਹੈ, ਜਦਕਿ ਮੁੱਢਲਾ ਐਲੂਮੀਨੀਅਮ ਬਾਕਸਾਈਟ ਤੋਂ ਮਿਲਦਾ ਹੈ।"]},
"GEO-IND-001-CP006-Q059":{"h":"06849f64","hi":["ऐलुमिनियम के पुनर्चक्रण से उद्योग को कौन-सा लाभ मिलता है?",["बॉक्साइट की अधिक खपत","अधिक खनन की आवश्यकता","सारे परिवहन की समाप्ति","ऊर्जा की कम आवश्यकता"],"सबसे बड़ा लाभ यह है कि प्राथमिक निष्कर्षण और प्रगलन में लगने वाली ऊर्जा का बड़ा हिस्सा बच जाता है।"],"pa":["ਐਲੂਮੀਨੀਅਮ ਨੂੰ ਮੁੜ ਵਰਤਣ ਲਈ ਪ੍ਰੋਸੈਸ ਕਰਨ ਨਾਲ ਉਦਯੋਗ ਨੂੰ ਕਿਹੜਾ ਲਾਭ ਹੁੰਦਾ ਹੈ?",["ਬਾਕਸਾਈਟ ਦੀ ਵੱਧ ਖਪਤ","ਵੱਧ ਖੁਦਾਈ ਦੀ ਲੋੜ","ਸਾਰੀ ਢੋਆ-ਢੁਆਈ ਖ਼ਤਮ","ਘੱਟ ਊਰਜਾ ਦੀ ਲੋੜ"],"ਸਭ ਤੋਂ ਵੱਡਾ ਲਾਭ ਮੁੱਢਲੀ ਧਾਤ ਕੱਢਣ ਤੇ ਗਲਾਈ ਵਿੱਚ ਲੱਗਦੀ ਊਰਜਾ ਦਾ ਵੱਡਾ ਹਿੱਸਾ ਬਚਣਾ ਹੈ।"]},
"GEO-IND-001-CP006-Q060":{"h":"229e7cff","hi":["कौन-सा क्रम प्राथमिक और द्वितीयक ऐलुमिनियम का अंतर सही दर्शाता है?",["बॉक्साइट → ऐलुमिना → प्राथमिक ऐलुमिनियम; कबाड़ → द्वितीयक ऐलुमिनियम","कोयला → ऐलुमिनियम; जूट → ऐलुमिनियम","चूना पत्थर → प्राथमिक ऐलुमिनियम; कपास → द्वितीयक ऐलुमिनियम","लौह अयस्क → ऐलुमिना; गन्ना → ऐलुमिनियम"],"प्राथमिक ऐलुमिनियम बॉक्साइट से और द्वितीयक ऐलुमिनियम धातु के पुनर्चक्रित कबाड़ से प्राप्त होता है।"],"pa":["ਕਿਹੜੀ ਲੜੀ ਮੁੱਢਲੇ ਅਤੇ ਦੁਜੈਲੇ ਐਲੂਮੀਨੀਅਮ ਦਾ ਫ਼ਰਕ ਸਹੀ ਦਰਸਾਉਂਦੀ ਹੈ?",["ਬਾਕਸਾਈਟ → ਐਲੂਮੀਨਾ → ਮੁੱਢਲਾ ਐਲੂਮੀਨੀਅਮ; ਕਬਾੜ → ਦੁਜੈਲਾ ਐਲੂਮੀਨੀਅਮ","ਕੋਲਾ → ਐਲੂਮੀਨੀਅਮ; ਜੂਟ → ਐਲੂਮੀਨੀਅਮ","ਚੂਨਾ ਪੱਥਰ → ਮੁੱਢਲਾ ਐਲੂਮੀਨੀਅਮ; ਕਪਾਹ → ਦੁਜੈਲਾ ਐਲੂਮੀਨੀਅਮ","ਕੱਚਾ ਲੋਹਾ → ਐਲੂਮੀਨਾ; ਗੰਨਾ → ਐਲੂਮੀਨੀਅਮ"],"ਮੁੱਢਲਾ ਐਲੂਮੀਨੀਅਮ ਬਾਕਸਾਈਟ ਤੋਂ ਅਤੇ ਦੁਜੈਲਾ ਐਲੂਮੀਨੀਅਮ ਮੁੜ ਪ੍ਰੋਸੈਸ ਕੀਤੇ ਧਾਤ ਦੇ ਕਬਾੜ ਤੋਂ ਮਿਲਦਾ ਹੈ।"]},
"GEO-IND-001-CP007-Q001":{"h":"4ff03432","hi":["कौन-सा उद्योग मशीनें, औज़ार और औद्योगिक उपकरण बनाता है?",["चीनी उद्योग","जूट उद्योग","अभियांत्रिकी उद्योग","चाय प्रसंस्करण"],"अभियांत्रिकी उद्योग मशीनरी, औज़ार, परिवहन उपकरण और अर्थव्यवस्था के विभिन्न क्षेत्रों में इस्तेमाल होने वाली अन्य पूँजीगत वस्तुएँ बनाते हैं।"],"pa":["ਕਿਹੜਾ ਉਦਯੋਗ ਮਸ਼ੀਨਾਂ, ਔਜ਼ਾਰ ਅਤੇ ਉਦਯੋਗਿਕ ਸਾਜ਼ੋ-ਸਾਮਾਨ ਬਣਾਉਂਦਾ ਹੈ?",["ਖੰਡ ਉਦਯੋਗ","ਜੂਟ ਉਦਯੋਗ","ਇੰਜੀਨੀਅਰਿੰਗ ਉਦਯੋਗ","ਚਾਹ ਦੀ ਪ੍ਰੋਸੈਸਿੰਗ"],"ਇੰਜੀਨੀਅਰਿੰਗ ਉਦਯੋਗ ਮਸ਼ੀਨਰੀ, ਔਜ਼ਾਰ, ਆਵਾਜਾਈ ਲਈ ਸਾਜ਼ੋ-ਸਾਮਾਨ ਅਤੇ ਅਰਥਚਾਰੇ ਦੇ ਵੱਖ-ਵੱਖ ਖੇਤਰਾਂ ਵਿੱਚ ਵਰਤੀਆਂ ਜਾਂਦੀਆਂ ਹੋਰ ਪੂੰਜੀਗਤ ਵਸਤਾਂ ਬਣਾਉਂਦੇ ਹਨ।"]},
"GEO-IND-001-CP007-Q002":{"h":"8fe65329","hi":["औद्योगीकरण में अभियांत्रिकी उद्योगों का क्या महत्व है?",["वे केवल कृषि फसलें उगाते हैं","वे परिवहन तंत्र की जगह लेते हैं","वे केवल वर्षा पर निर्भर हैं","वे दूसरे उद्योगों को मशीनें और उपकरण देते हैं"],"अभियांत्रिकी कंपनियाँ ऐसी पूँजीगत वस्तुएँ देती हैं जो कई क्षेत्रकों के उत्पादन में काम आती हैं।"],"pa":["ਉਦਯੋਗੀਕਰਨ ਲਈ ਇੰਜੀਨੀਅਰਿੰਗ ਉਦਯੋਗ ਕਿਉਂ ਅਹਿਮ ਹਨ?",["ਉਹ ਸਿਰਫ਼ ਖੇਤੀ ਫ਼ਸਲਾਂ ਉਗਾਉਂਦੇ ਹਨ","ਉਹ ਆਵਾਜਾਈ ਦੇ ਜਾਲ ਦੀ ਥਾਂ ਲੈਂਦੇ ਹਨ","ਉਹ ਸਿਰਫ਼ ਵਰਖਾ 'ਤੇ ਨਿਰਭਰ ਹਨ","ਉਹ ਹੋਰ ਉਦਯੋਗਾਂ ਨੂੰ ਮਸ਼ੀਨਰੀ ਅਤੇ ਸਾਜ਼ੋ-ਸਾਮਾਨ ਦਿੰਦੇ ਹਨ"],"ਇੰਜੀਨੀਅਰਿੰਗ ਕੰਪਨੀਆਂ ਅਜਿਹੀਆਂ ਪੂੰਜੀਗਤ ਵਸਤਾਂ ਦਿੰਦੀਆਂ ਹਨ ਜੋ ਕਈ ਖੇਤਰਾਂ ਵਿੱਚ ਉਤਪਾਦਨ ਦੇ ਕੰਮ ਆਉਂਦੀਆਂ ਹਨ।"]},
"GEO-IND-001-CP007-Q003":{"h":"9e281c56","hi":["कथनों पर विचार कीजिए: I. अभियांत्रिकी उद्योग पूँजीगत वस्तुएँ बनाते हैं। II. उनके उत्पाद दूसरे विनिर्माण क्षेत्रकों में काम आते हैं। कौन-सा/से कथन सही है/हैं?",["I और II दोनों सही हैं","केवल I सही है","केवल II सही है","न तो I और न ही II सही है"],"विनिर्माण क्षेत्र में इस्तेमाल होने वाली मशीनों और उपकरणों का प्रमुख स्रोत अभियांत्रिकी उद्योग हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਇੰਜੀਨੀਅਰਿੰਗ ਉਦਯੋਗ ਪੂੰਜੀਗਤ ਵਸਤਾਂ ਬਣਾਉਂਦੇ ਹਨ। II. ਉਨ੍ਹਾਂ ਦੇ ਉਤਪਾਦ ਹੋਰ ਨਿਰਮਾਣ ਖੇਤਰਾਂ ਵਿੱਚ ਕੰਮ ਆਉਂਦੇ ਹਨ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਨਿਰਮਾਣ ਖੇਤਰ ਨੂੰ ਮਸ਼ੀਨਾਂ ਅਤੇ ਸਾਜ਼ੋ-ਸਾਮਾਨ ਮੁਹੱਈਆ ਕਰਵਾਉਣ ਦਾ ਮੁੱਖ ਸਰੋਤ ਇੰਜੀਨੀਅਰਿੰਗ ਉਦਯੋਗ ਹਨ।"]},
"GEO-IND-001-CP007-Q004":{"h":"6b734a3a","hi":["अभियांत्रिकी उद्योगों का कौन-सा उत्पाद पूँजीगत वस्तु है?",["कच्ची कपास","मशीन औज़ार","गन्ना","जूट का रेशा"],"मशीन औज़ारों से दूसरी वस्तुएँ बनाई जाती हैं, इसलिए वे पूँजीगत वस्तुएँ हैं।"],"pa":["ਇੰਜੀਨੀਅਰਿੰਗ ਉਦਯੋਗਾਂ ਦਾ ਕਿਹੜਾ ਉਤਪਾਦ ਪੂੰਜੀਗਤ ਵਸਤ ਹੈ?",["ਕੱਚੀ ਕਪਾਹ","ਮਸ਼ੀਨੀ ਔਜ਼ਾਰ","ਗੰਨਾ","ਜੂਟ ਦਾ ਰੇਸ਼ਾ"],"ਮਸ਼ੀਨੀ ਔਜ਼ਾਰ ਹੋਰ ਵਸਤਾਂ ਬਣਾਉਣ ਲਈ ਵਰਤੇ ਜਾਂਦੇ ਹਨ। ਇਸ ਲਈ ਉਹ ਪੂੰਜੀਗਤ ਵਸਤਾਂ ਹਨ।"]},
"GEO-IND-001-CP007-Q005":{"h":"43e0877b","hi":["अभियांत्रिकी उद्योग के वर्गीकरण में कौन-सा युग्म सही सुमेलित है?",["परिधान — पूँजीगत वस्तुएँ","चीनी — भारी अभियांत्रिकी","मशीन औज़ार — पूँजीगत वस्तुएँ","जूट के बोरे — मशीन औज़ार"],"मशीन औज़ार उत्पादन के उपकरण हैं, इसलिए वे पूँजीगत वस्तुएँ हैं।"],"pa":["ਇੰਜੀਨੀਅਰਿੰਗ ਉਦਯੋਗ ਦੇ ਵਰਗੀਕਰਨ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਪਹਿਰਾਵੇ — ਪੂੰਜੀਗਤ ਵਸਤਾਂ","ਖੰਡ — ਭਾਰੀ ਇੰਜੀਨੀਅਰਿੰਗ","ਮਸ਼ੀਨੀ ਔਜ਼ਾਰ — ਪੂੰਜੀਗਤ ਵਸਤਾਂ","ਜੂਟ ਦੀਆਂ ਬੋਰੀਆਂ — ਮਸ਼ੀਨੀ ਔਜ਼ਾਰ"],"ਮਸ਼ੀਨੀ ਔਜ਼ਾਰ ਉਤਪਾਦਨ ਦਾ ਸਾਜ਼ੋ-ਸਾਮਾਨ ਹਨ। ਇਸ ਲਈ ਉਹ ਪੂੰਜੀਗਤ ਵਸਤਾਂ ਹਨ।"]},
"GEO-IND-001-CP007-Q006":{"h":"db823894","hi":["एक कारखाना औद्योगिक टरबाइन, मशीन औज़ार और भारी विद्युत उपकरण बनाता है। वह किस उद्योग समूह में आता है?",["खाद्य प्रसंस्करण","जूट वस्त्र","चीनी मिलें","भारी अभियांत्रिकी"],"बड़ी औद्योगिक मशीनें और विद्युत प्रणालियाँ भारी अभियांत्रिकी के अंतर्गत आती हैं।"],"pa":["ਇੱਕ ਕਾਰਖ਼ਾਨਾ ਉਦਯੋਗਿਕ ਟਰਬਾਈਨਾਂ, ਮਸ਼ੀਨੀ ਔਜ਼ਾਰ ਅਤੇ ਭਾਰੀ ਬਿਜਲਈ ਸਾਜ਼ੋ-ਸਾਮਾਨ ਬਣਾਉਂਦਾ ਹੈ। ਉਹ ਕਿਹੜੇ ਉਦਯੋਗ ਸਮੂਹ ਵਿੱਚ ਆਉਂਦਾ ਹੈ?",["ਖ਼ੁਰਾਕੀ ਪ੍ਰੋਸੈਸਿੰਗ","ਜੂਟ ਦੇ ਕੱਪੜੇ","ਖੰਡ ਮਿੱਲਾਂ","ਭਾਰੀ ਇੰਜੀਨੀਅਰਿੰਗ"],"ਵੱਡੀਆਂ ਉਦਯੋਗਿਕ ਮਸ਼ੀਨਾਂ ਅਤੇ ਬਿਜਲਈ ਪ੍ਰਣਾਲੀਆਂ ਭਾਰੀ ਇੰਜੀਨੀਅਰਿੰਗ ਵਿੱਚ ਆਉਂਦੀਆਂ ਹਨ।"]},
"GEO-IND-001-CP007-Q007":{"h":"345d561a","hi":["इस्पात, कोयले और बिजली की उपलब्धता के कारण किस क्षेत्र का भारी अभियांत्रिकी से गहरा संबंध है?",["छोटानागपुर पठार क्षेत्र","थार मरुस्थल","केरल तट","कश्मीर घाटी"],"छोटानागपुर की खनिज-औद्योगिक पट्टी में इस्पात, कोयला, बिजली और परिवहन की सुविधाएँ साथ मिलती हैं। इनसे भारी अभियांत्रिकी को आधार मिलता है।"],"pa":["ਸਟੀਲ, ਕੋਲੇ ਅਤੇ ਬਿਜਲੀ ਦੇ ਆਧਾਰ ਕਰਕੇ ਕਿਹੜਾ ਇਲਾਕਾ ਭਾਰੀ ਇੰਜੀਨੀਅਰਿੰਗ ਨਾਲ ਨੇੜਿਓਂ ਜੁੜਿਆ ਹੈ?",["ਛੋਟਾਨਾਗਪੁਰ ਪਠਾਰ ਦਾ ਇਲਾਕਾ","ਥਾਰ ਦਾ ਮਾਰੂਥਲ","ਕੇਰਲ ਤੱਟ","ਕਸ਼ਮੀਰ ਘਾਟੀ"],"ਛੋਟਾਨਾਗਪੁਰ ਦੀ ਖਣਿਜ-ਉਦਯੋਗਿਕ ਪੱਟੀ ਵਿੱਚ ਸਟੀਲ, ਕੋਲਾ, ਬਿਜਲੀ ਅਤੇ ਆਵਾਜਾਈ ਦੀਆਂ ਸਹੂਲਤਾਂ ਇਕੱਠੀਆਂ ਮਿਲਦੀਆਂ ਹਨ। ਇਨ੍ਹਾਂ ਨਾਲ ਭਾਰੀ ਇੰਜੀਨੀਅਰਿੰਗ ਨੂੰ ਆਧਾਰ ਮਿਲਦਾ ਹੈ।"]},
"GEO-IND-001-CP007-Q008":{"h":"045a346e","hi":["राँची ऐतिहासिक रूप से किस औद्योगिक गतिविधि के लिए प्रसिद्ध है?",["केवल जूट मिलें","भारी अभियांत्रिकी","केवल चीनी का परिष्करण","केवल चाय प्रसंस्करण"],"राँची पूर्वी भारत की खनिज-समृद्ध औद्योगिक पट्टी में भारी अभियांत्रिकी के प्रमुख केंद्र के रूप में विकसित हुआ।"],"pa":["ਰਾਂਚੀ ਇਤਿਹਾਸਕ ਤੌਰ 'ਤੇ ਕਿਹੜੀ ਉਦਯੋਗਿਕ ਸਰਗਰਮੀ ਲਈ ਮਸ਼ਹੂਰ ਹੈ?",["ਸਿਰਫ਼ ਜੂਟ ਮਿੱਲਾਂ","ਭਾਰੀ ਇੰਜੀਨੀਅਰਿੰਗ","ਸਿਰਫ਼ ਖੰਡ ਦੀ ਸੋਧਾਈ","ਸਿਰਫ਼ ਚਾਹ ਦੀ ਪ੍ਰੋਸੈਸਿੰਗ"],"ਰਾਂਚੀ ਪੂਰਬੀ ਭਾਰਤ ਦੀ ਖਣਿਜਾਂ ਨਾਲ ਭਰਪੂਰ ਉਦਯੋਗਿਕ ਪੱਟੀ ਵਿੱਚ ਭਾਰੀ ਇੰਜੀਨੀਅਰਿੰਗ ਦੇ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰ ਵਜੋਂ ਵਿਕਸਿਤ ਹੋਇਆ।"]},
"GEO-IND-001-CP007-Q009":{"h":"d5cb01e2","hi":["कथनों पर विचार कीजिए: I. राँची झारखंड में है। II. इस क्षेत्र का भारी अभियांत्रिकी से गहरा संबंध है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","I और II दोनों सही हैं","न तो I और न ही II सही है"],"राँची झारखंड में है और छोटानागपुर के भारी उद्योग क्षेत्र का हिस्सा है।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਰਾਂਚੀ ਝਾਰਖੰਡ ਵਿੱਚ ਹੈ। II. ਇਸ ਇਲਾਕੇ ਦਾ ਭਾਰੀ ਇੰਜੀਨੀਅਰਿੰਗ ਨਾਲ ਡੂੰਘਾ ਸਬੰਧ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਰਾਂਚੀ ਝਾਰਖੰਡ ਵਿੱਚ ਹੈ ਅਤੇ ਛੋਟਾਨਾਗਪੁਰ ਦੇ ਭਾਰੀ ਉਦਯੋਗ ਖੇਤਰ ਦਾ ਹਿੱਸਾ ਹੈ।"]},
"GEO-IND-001-CP007-Q010":{"h":"b5fe265f","hi":["भारी अभियांत्रिकी के भूगोल में कौन-सा युग्म सही सुमेलित है?",["राँची — केवल जूट","राँची — पेट्रोलियम क्षेत्र","राँची — केवल चीनी","राँची — भारी अभियांत्रिकी"],"राँची भारी अभियांत्रिकी का पारंपरिक केंद्र है।"],"pa":["ਭਾਰੀ ਇੰਜੀਨੀਅਰਿੰਗ ਦੇ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਰਾਂਚੀ — ਸਿਰਫ਼ ਜੂਟ","ਰਾਂਚੀ — ਪੈਟਰੋਲੀਅਮ ਖੇਤਰ","ਰਾਂਚੀ — ਸਿਰਫ਼ ਖੰਡ","ਰਾਂਚੀ — ਭਾਰੀ ਇੰਜੀਨੀਅਰਿੰਗ"],"ਰਾਂਚੀ ਭਾਰੀ ਇੰਜੀਨੀਅਰਿੰਗ ਦਾ ਰਵਾਇਤੀ ਕੇਂਦਰ ਹੈ।"]},
"GEO-IND-001-CP007-Q011":{"h":"9775f1e7","hi":["छोटानागपुर क्षेत्र भारी अभियांत्रिकी के लिए अनुकूल क्यों है?",["इस्पात, कोयला, बिजली और परिवहन पास में उपलब्ध हैं","वहाँ औद्योगिक कच्चा माल नहीं है","केवल जलवायु का महत्व है","वह केवल पत्तनों पर निर्भर है"],"धातु उद्योगों, ऊर्जा और परिवहन सुविधाओं की निकटता से भारी अभियांत्रिकी को लाभ मिलता है।"],"pa":["ਛੋਟਾਨਾਗਪੁਰ ਦਾ ਇਲਾਕਾ ਭਾਰੀ ਇੰਜੀਨੀਅਰਿੰਗ ਲਈ ਅਨੁਕੂਲ ਕਿਉਂ ਹੈ?",["ਸਟੀਲ, ਕੋਲਾ, ਬਿਜਲੀ ਅਤੇ ਆਵਾਜਾਈ ਨੇੜੇ ਹੀ ਮਿਲਦੇ ਹਨ","ਉੱਥੇ ਉਦਯੋਗਿਕ ਕੱਚਾ ਮਾਲ ਨਹੀਂ ਹੈ","ਸਿਰਫ਼ ਜਲਵਾਯੂ ਦਾ ਮਹੱਤਵ ਹੈ","ਇਹ ਸਿਰਫ਼ ਬੰਦਰਗਾਹਾਂ 'ਤੇ ਨਿਰਭਰ ਹੈ"],"ਧਾਤ ਉਦਯੋਗਾਂ, ਊਰਜਾ ਅਤੇ ਆਵਾਜਾਈ ਦੇ ਬੁਨਿਆਦੀ ਢਾਂਚੇ ਦੀ ਨੇੜਤਾ ਤੋਂ ਭਾਰੀ ਇੰਜੀਨੀਅਰਿੰਗ ਨੂੰ ਲਾਭ ਹੁੰਦਾ ਹੈ।"]},
"GEO-IND-001-CP007-Q012":{"h":"bc2ba74d","hi":["छोटानागपुर पट्टी के लिए कौन-सी औद्योगिक शृंखला सबसे उपयुक्त है?",["जूट → ऐलुमिनियम प्रगलन","कोयला और इस्पात → भारी अभियांत्रिकी","गन्ना → इस्पात","चाय → मशीन औज़ार"],"इस क्षेत्र के खनिज और इस्पात आगे की उत्पादन शृंखला में अभियांत्रिकी उद्योगों को आधार देते हैं।"],"pa":["ਛੋਟਾਨਾਗਪੁਰ ਪੱਟੀ ਲਈ ਕਿਹੜੀ ਉਦਯੋਗਿਕ ਲੜੀ ਸਭ ਤੋਂ ਢੁੱਕਵੀਂ ਹੈ?",["ਜੂਟ → ਐਲੂਮੀਨੀਅਮ ਦੀ ਗਲਾਈ","ਕੋਲਾ ਅਤੇ ਸਟੀਲ → ਭਾਰੀ ਇੰਜੀਨੀਅਰਿੰਗ","ਗੰਨਾ → ਸਟੀਲ","ਚਾਹ → ਮਸ਼ੀਨੀ ਔਜ਼ਾਰ"],"ਇਸ ਇਲਾਕੇ ਦੇ ਖਣਿਜ ਅਤੇ ਸਟੀਲ ਅਗਲੇ ਪੜਾਅ ਦੇ ਇੰਜੀਨੀਅਰਿੰਗ ਉਦਯੋਗਾਂ ਨੂੰ ਆਧਾਰ ਦਿੰਦੇ ਹਨ।"]},
"GEO-IND-001-CP007-Q013":{"h":"4aa55af9","hi":["कौन-सा शहर भारत के प्रमुख मोटर वाहन विनिर्माण केंद्रों में से एक है?",["झरिया","चेन्नई","कोडरमा","सांभर"],"चेन्नई और आसपास की औद्योगिक पट्टी भारत में मोटर वाहन और उनके पुर्ज़े बनाने वाले प्रमुख संकुलों में से एक है।"],"pa":["ਕਿਹੜਾ ਸ਼ਹਿਰ ਭਾਰਤ ਦੇ ਪ੍ਰਮੁੱਖ ਮੋਟਰ ਵਾਹਨ ਨਿਰਮਾਣ ਕੇਂਦਰਾਂ ਵਿੱਚੋਂ ਇੱਕ ਹੈ?",["ਝਰੀਆ","ਚੇਨਈ","ਕੋਡਰਮਾ","ਸਾਂਭਰ"],"ਚੇਨਈ ਅਤੇ ਉਸ ਦੇ ਆਲੇ-ਦੁਆਲੇ ਦੀ ਉਦਯੋਗਿਕ ਪੱਟੀ ਭਾਰਤ ਵਿੱਚ ਮੋਟਰ ਵਾਹਨ ਅਤੇ ਉਨ੍ਹਾਂ ਦੇ ਪੁਰਜ਼ੇ ਬਣਾਉਣ ਦੇ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰਾਂ ਵਿੱਚੋਂ ਇੱਕ ਹੈ।"]},
"GEO-IND-001-CP007-Q014":{"h":"234a07e8","hi":["चेन्नई का मोटर वाहन उद्योग संकुल किस राज्य में है?",["गुजरात","महाराष्ट्र","तमिलनाडु","झारखंड"],"चेन्नई तमिलनाडु की राजधानी और मोटर वाहन विनिर्माण का प्रमुख केंद्र है।"],"pa":["ਚੇਨਈ ਦਾ ਮੋਟਰ ਵਾਹਨ ਉਦਯੋਗ ਕਿਹੜੇ ਰਾਜ ਵਿੱਚ ਹੈ?",["ਗੁਜਰਾਤ","ਮਹਾਰਾਸ਼ਟਰ","ਤਾਮਿਲਨਾਡੂ","ਝਾਰਖੰਡ"],"ਚੇਨਈ ਤਾਮਿਲਨਾਡੂ ਦੀ ਰਾਜਧਾਨੀ ਅਤੇ ਮੋਟਰ ਵਾਹਨ ਬਣਾਉਣ ਦਾ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰ ਹੈ।"]},
"GEO-IND-001-CP007-Q015":{"h":"b876f05a","hi":["चेन्नई में बड़े मोटर वाहन उद्योग संकुल को बनाए रखने में क्या सहायक है?",["केवल लौह अयस्क","चाय के बागान","जूट के खेत","आपूर्तिकर्ताओं का तंत्र, कुशल श्रम, पत्तन और बाज़ार"],"मोटर वाहन विनिर्माण जटिल आपूर्ति शृंखलाओं, श्रम, माल की आवाजाही और बाज़ार तक पहुँच पर निर्भर है।"],"pa":["ਚੇਨਈ ਵਿੱਚ ਮੋਟਰ ਵਾਹਨ ਉਦਯੋਗ ਦੇ ਵੱਡੇ ਗੁੱਛ ਨੂੰ ਕਿਹੜਾ ਕਾਰਕ ਕਾਇਮ ਰੱਖਣ ਵਿੱਚ ਮਦਦ ਕਰਦਾ ਹੈ?",["ਸਿਰਫ਼ ਕੱਚਾ ਲੋਹਾ","ਚਾਹ ਦੇ ਬਾਗ਼","ਜੂਟ ਦੇ ਖੇਤ","ਸਪਲਾਇਰਾਂ ਦਾ ਜਾਲ, ਹੁਨਰਮੰਦ ਕਾਮੇ, ਬੰਦਰਗਾਹਾਂ ਅਤੇ ਬਾਜ਼ਾਰ"],"ਮੋਟਰ ਵਾਹਨ ਬਣਾਉਣ ਲਈ ਗੁੰਝਲਦਾਰ ਸਪਲਾਈ ਲੜੀਆਂ, ਕਾਮੇ, ਮਾਲ ਦੀ ਢੋਆ-ਢੁਆਈ ਅਤੇ ਬਾਜ਼ਾਰਾਂ ਤੱਕ ਪਹੁੰਚ ਚਾਹੀਦੀ ਹੈ।"]},
"GEO-IND-001-CP007-Q016":{"h":"fdb98530","hi":["कथनों पर विचार कीजिए: I. चेन्नई मोटर वाहन उद्योग का प्रमुख केंद्र है। II. पत्तन तक पहुँच से वहाँ औद्योगिक माल की आवाजाही में मदद मिलती है। कौन-सा/से कथन सही है/हैं?",["I और II दोनों सही हैं","केवल I सही है","केवल II सही है","न तो I और न ही II सही है"],"दोनों तथ्य चेन्नई के औद्योगिक भूगोल के लिए महत्वपूर्ण हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਚੇਨਈ ਮੋਟਰ ਵਾਹਨ ਉਦਯੋਗ ਦਾ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰ ਹੈ। II. ਬੰਦਰਗਾਹ ਤੱਕ ਪਹੁੰਚ ਉਦਯੋਗਿਕ ਮਾਲ ਦੀ ਢੋਆ-ਢੁਆਈ ਵਿੱਚ ਮਦਦ ਕਰਦੀ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਦੋਵੇਂ ਤੱਥ ਚੇਨਈ ਦੇ ਉਦਯੋਗਿਕ ਭੂਗੋਲ ਲਈ ਅਹਿਮ ਹਨ।"]},
"GEO-IND-001-CP007-Q017":{"h":"36650a21","hi":["कौन-सा युग्म चेन्नई के मोटर वाहन उद्योग का भूगोल सही दर्शाता है?",["चेन्नई — जूट पट्टी","चेन्नई — तमिलनाडु का मोटर वाहन संकुल","चेन्नई — कोयला क्षेत्र","चेन्नई — यूरेनियम खदान"],"चेन्नई तमिलनाडु में मोटर वाहन विनिर्माण का प्रमुख केंद्र है।"],"pa":["ਕਿਹੜਾ ਜੋੜਾ ਚੇਨਈ ਦੇ ਮੋਟਰ ਵਾਹਨ ਉਦਯੋਗ ਦੇ ਭੂਗੋਲ ਨੂੰ ਸਹੀ ਦਰਸਾਉਂਦਾ ਹੈ?",["ਚੇਨਈ — ਜੂਟ ਪੱਟੀ","ਚੇਨਈ — ਤਾਮਿਲਨਾਡੂ ਦਾ ਮੋਟਰ ਵਾਹਨ ਗੁੱਛ","ਚੇਨਈ — ਕੋਲਾ ਖੇਤਰ","ਚੇਨਈ — ਯੂਰੇਨੀਅਮ ਖਾਣ"],"ਚੇਨਈ ਤਾਮਿਲਨਾਡੂ ਵਿੱਚ ਮੋਟਰ ਵਾਹਨ ਬਣਾਉਣ ਦਾ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰ ਹੈ।"]},
"GEO-IND-001-CP007-Q018":{"h":"652d8b18","hi":["चेन्नई की मोटर वाहन उद्योग पट्टी किस बात का उदाहरण है?",["उद्योगों का पूर्ण अलगाव","केवल खदानों पर निर्भरता","वाहन संयोजन इकाइयों और पुर्ज़ा आपूर्तिकर्ताओं का संकेंद्रण","माल की आवाजाही की सुविधाओं का अभाव"],"बड़े मोटर वाहन संकुल विशिष्ट आपूर्तिकर्ताओं और सेवाओं को आकर्षित करते हैं, जिससे उद्योगों को एक जगह होने का लाभ मिलता है।"],"pa":["ਚੇਨਈ ਦੀ ਮੋਟਰ ਵਾਹਨ ਪੱਟੀ ਕਿਸ ਗੱਲ ਦੀ ਉਦਾਹਰਨ ਹੈ?",["ਉਦਯੋਗਾਂ ਦਾ ਪੂਰੀ ਤਰ੍ਹਾਂ ਅਲੱਗ ਹੋਣਾ","ਸਿਰਫ਼ ਖਾਣਾਂ 'ਤੇ ਨਿਰਭਰਤਾ","ਵਾਹਨ ਜੋੜਨ ਵਾਲੀਆਂ ਇਕਾਈਆਂ ਅਤੇ ਪੁਰਜ਼ੇ ਦੇਣ ਵਾਲਿਆਂ ਦਾ ਇੱਕ ਥਾਂ ਇਕੱਠਾ ਹੋਣਾ","ਮਾਲ ਢੋਣ ਦੇ ਪ੍ਰਬੰਧ ਦੀ ਅਣਹੋਂਦ"],"ਮੋਟਰ ਵਾਹਨ ਉਦਯੋਗ ਦੇ ਵੱਡੇ ਗੁੱਛ ਖ਼ਾਸ ਸਪਲਾਇਰਾਂ ਅਤੇ ਸੇਵਾਵਾਂ ਨੂੰ ਖਿੱਚਦੇ ਹਨ। ਇਸ ਨਾਲ ਇੱਕ ਥਾਂ ਇਕੱਠੇ ਹੋਣ ਦੇ ਲਾਭ ਮਿਲਦੇ ਹਨ।"]},
"GEO-IND-001-CP007-Q019":{"h":"1544eaa8","hi":["पुणे का किस विनिर्माण क्षेत्र से गहरा संबंध है?",["केवल जूट मिलें","केवल चाय प्रसंस्करण","मोटर वाहन और अभियांत्रिकी","केवल कोयला खनन"],"पुणे पश्चिमी भारत के प्रमुख मोटर वाहन और अभियांत्रिकी केंद्रों में से एक है।"],"pa":["ਪੁਣੇ ਦਾ ਨਿਰਮਾਣ ਦੇ ਕਿਹੜੇ ਖੇਤਰ ਨਾਲ ਡੂੰਘਾ ਸਬੰਧ ਹੈ?",["ਸਿਰਫ਼ ਜੂਟ ਮਿੱਲਾਂ","ਸਿਰਫ਼ ਚਾਹ ਦੀ ਪ੍ਰੋਸੈਸਿੰਗ","ਮੋਟਰ ਵਾਹਨ ਅਤੇ ਇੰਜੀਨੀਅਰਿੰਗ","ਸਿਰਫ਼ ਕੋਲੇ ਦੀ ਖੁਦਾਈ"],"ਪੁਣੇ ਪੱਛਮੀ ਭਾਰਤ ਦੇ ਪ੍ਰਮੁੱਖ ਮੋਟਰ ਵਾਹਨ ਅਤੇ ਇੰਜੀਨੀਅਰਿੰਗ ਕੇਂਦਰਾਂ ਵਿੱਚੋਂ ਇੱਕ ਹੈ।"]},
"GEO-IND-001-CP007-Q020":{"h":"f0851cf6","hi":["पुणे किस राज्य में है?",["तमिलनाडु","गुजरात","ओडिशा","महाराष्ट्र"],"पुणे महाराष्ट्र में है और व्यापक मुंबई-पुणे औद्योगिक क्षेत्र का हिस्सा है।"],"pa":["ਪੁਣੇ ਕਿਹੜੇ ਰਾਜ ਵਿੱਚ ਹੈ?",["ਤਾਮਿਲਨਾਡੂ","ਗੁਜਰਾਤ","ਓਡੀਸ਼ਾ","ਮਹਾਰਾਸ਼ਟਰ"],"ਪੁਣੇ ਮਹਾਰਾਸ਼ਟਰ ਵਿੱਚ ਹੈ ਅਤੇ ਵਡੇਰੇ ਮੁੰਬਈ-ਪੁਣੇ ਉਦਯੋਗਿਕ ਖੇਤਰ ਦਾ ਹਿੱਸਾ ਹੈ।"]},
"GEO-IND-001-CP007-Q021":{"h":"e229435c","hi":["पुणे-मुंबई पट्टी में अभियांत्रिकी उद्योगों को किससे सहारा मिलता है?",["बड़ा बाज़ार, कुशल श्रम, परिवहन और आपूर्तिकर्ताओं का तंत्र","केवल लौह अयस्क","केवल वर्षा","केवल मत्स्यन"],"इस औद्योगिक गलियारे में पूँजी, श्रम, आधारभूत संरचना और माँग एक साथ उपलब्ध हैं।"],"pa":["ਪੁਣੇ-ਮੁੰਬਈ ਪੱਟੀ ਵਿੱਚ ਇੰਜੀਨੀਅਰਿੰਗ ਉਦਯੋਗਾਂ ਨੂੰ ਕਿਸ ਤੋਂ ਮਦਦ ਮਿਲਦੀ ਹੈ?",["ਵੱਡਾ ਬਾਜ਼ਾਰ, ਹੁਨਰਮੰਦ ਕਾਮੇ, ਆਵਾਜਾਈ ਅਤੇ ਸਪਲਾਇਰਾਂ ਦਾ ਜਾਲ","ਸਿਰਫ਼ ਕੱਚਾ ਲੋਹਾ","ਸਿਰਫ਼ ਵਰਖਾ","ਸਿਰਫ਼ ਮੱਛੀ ਫੜਨ ਦਾ ਕੰਮ"],"ਇਸ ਉਦਯੋਗਿਕ ਗਲਿਆਰੇ ਵਿੱਚ ਪੂੰਜੀ, ਕਾਮੇ, ਬੁਨਿਆਦੀ ਢਾਂਚਾ ਅਤੇ ਮੰਗ ਇਕੱਠੇ ਮਿਲਦੇ ਹਨ।"]},
"GEO-IND-001-CP007-Q022":{"h":"6f4b7f67","hi":["कथनों पर विचार कीजिए: I. पुणे मोटर वाहन उद्योग का प्रमुख केंद्र है। II. यह मुंबई-पुणे औद्योगिक पट्टी का हिस्सा है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","I और II दोनों सही हैं","केवल II सही है","न तो I और न ही II सही है"],"दोनों कथन पुणे की औद्योगिक भूमिका का सही वर्णन करते हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਪੁਣੇ ਮੋਟਰ ਵਾਹਨ ਉਦਯੋਗ ਦਾ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰ ਹੈ। II. ਇਹ ਮੁੰਬਈ-ਪੁਣੇ ਉਦਯੋਗਿਕ ਪੱਟੀ ਦਾ ਹਿੱਸਾ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਦੋਵੇਂ ਕਥਨ ਪੁਣੇ ਦੀ ਉਦਯੋਗਿਕ ਭੂਮਿਕਾ ਦਾ ਸਹੀ ਵਰਣਨ ਕਰਦੇ ਹਨ।"]},
"GEO-IND-001-CP007-Q023":{"h":"78311bc6","hi":["मोटर वाहन उद्योग के भूगोल में कौन-सा युग्म पुणे की सही पहचान करता है?",["पुणे — ओडिशा","पुणे — पश्चिम बंगाल","पुणे — महाराष्ट्र","पुणे — असम"],"पुणे महाराष्ट्र में है।"],"pa":["ਮੋਟਰ ਵਾਹਨ ਉਦਯੋਗ ਦੇ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਪੁਣੇ ਦੀ ਸਹੀ ਪਛਾਣ ਕਰਦਾ ਹੈ?",["ਪੁਣੇ — ਓਡੀਸ਼ਾ","ਪੁਣੇ — ਪੱਛਮੀ ਬੰਗਾਲ","ਪੁਣੇ — ਮਹਾਰਾਸ਼ਟਰ","ਪੁਣੇ — ਅਸਾਮ"],"ਪੁਣੇ ਮਹਾਰਾਸ਼ਟਰ ਵਿੱਚ ਹੈ।"]},
"GEO-IND-001-CP007-Q024":{"h":"7bbc5dfa","hi":["मोटर वाहन उद्योग के भूगोल में कौन-सी तुलना सही है?",["दोनों कोयला क्षेत्र हैं","दोनों केवल जूट के केंद्र हैं","पुणे तमिलनाडु में है","चेन्नई दक्षिण भारत का प्रमुख संकुल है और पुणे पश्चिम भारत का"],"दोनों शहर मोटर वाहन उद्योग के महत्वपूर्ण संकुल हैं और अलग-अलग भौगोलिक क्षेत्रों में हैं।"],"pa":["ਮੋਟਰ ਵਾਹਨ ਉਦਯੋਗ ਦੇ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜੀ ਤੁਲਨਾ ਸਹੀ ਹੈ?",["ਦੋਵੇਂ ਕੋਲਾ ਖੇਤਰ ਹਨ","ਦੋਵੇਂ ਸਿਰਫ਼ ਜੂਟ ਦੇ ਕੇਂਦਰ ਹਨ","ਪੁਣੇ ਤਾਮਿਲਨਾਡੂ ਵਿੱਚ ਹੈ","ਚੇਨਈ ਦੱਖਣੀ ਭਾਰਤ ਦਾ ਅਤੇ ਪੁਣੇ ਪੱਛਮੀ ਭਾਰਤ ਦਾ ਪ੍ਰਮੁੱਖ ਉਦਯੋਗਿਕ ਗੁੱਛ ਹੈ"],"ਦੋਵੇਂ ਮੋਟਰ ਵਾਹਨ ਉਦਯੋਗ ਦੇ ਮਹੱਤਵਪੂਰਨ ਗੁੱਛ ਹਨ ਅਤੇ ਵੱਖੋ-ਵੱਖਰੇ ਭੂਗੋਲਿਕ ਖੇਤਰਾਂ ਵਿੱਚ ਹਨ।"]},
"GEO-IND-001-CP007-Q025":{"h":"292dede4","hi":["उत्तर भारत का कौन-सा नगरीय औद्योगिक क्षेत्र मोटर वाहन और उनके पुर्ज़ों का प्रमुख संकुल है?",["सुंदरबन","कोडरमा अभ्रक पट्टी","झरिया कोयला क्षेत्र","दिल्ली राष्ट्रीय राजधानी क्षेत्र (NCR)"],"दिल्ली राष्ट्रीय राजधानी क्षेत्र (NCR), विशेषकर गुरुग्राम-मानेसर-नोएडा और आसपास के इलाकों में वाहन और उनके पुर्ज़े बनाने का बड़ा आधार है।"],"pa":["ਉੱਤਰੀ ਭਾਰਤ ਦਾ ਕਿਹੜਾ ਸ਼ਹਿਰੀ-ਉਦਯੋਗਿਕ ਖੇਤਰ ਮੋਟਰ ਵਾਹਨ ਅਤੇ ਉਨ੍ਹਾਂ ਦੇ ਪੁਰਜ਼ੇ ਬਣਾਉਣ ਦਾ ਪ੍ਰਮੁੱਖ ਗੁੱਛ ਹੈ?",["ਸੁੰਦਰਬਨ","ਕੋਡਰਮਾ ਅਬਰਕ ਪੱਟੀ","ਝਰੀਆ ਕੋਲਾ ਖੇਤਰ","ਦਿੱਲੀ ਰਾਸ਼ਟਰੀ ਰਾਜਧਾਨੀ ਖੇਤਰ (NCR)"],"ਦਿੱਲੀ ਰਾਸ਼ਟਰੀ ਰਾਜਧਾਨੀ ਖੇਤਰ (NCR), ਖ਼ਾਸ ਕਰਕੇ ਗੁਰੂਗ੍ਰਾਮ-ਮਾਨੇਸਰ-ਨੋਇਡਾ ਅਤੇ ਨਾਲ ਲੱਗਦੇ ਇਲਾਕਿਆਂ ਵਿੱਚ, ਮੋਟਰ ਵਾਹਨ ਅਤੇ ਉਨ੍ਹਾਂ ਦੇ ਪੁਰਜ਼ੇ ਬਣਾਉਣ ਦਾ ਵੱਡਾ ਆਧਾਰ ਹੈ।"]},
"GEO-IND-001-CP007-Q026":{"h":"a694f373","hi":["दिल्ली राष्ट्रीय राजधानी क्षेत्र (NCR) में मोटर वाहन विनिर्माण के लिए कौन-सा अवस्थितिक लाभ विशेष रूप से सहायक है?",["बड़ा बाज़ार और अच्छे परिवहन संपर्क","केवल पास का कोकिंग कोयला","चाय के बागान","ज्वारीय ऊर्जा"],"इस क्षेत्र में बहुत बड़ा उपभोक्ता बाज़ार है। साथ ही राजमार्ग, आपूर्तिकर्ता, श्रमिक और माल की आवाजाही की सुविधाएँ उपलब्ध हैं।"],"pa":["ਦਿੱਲੀ ਰਾਸ਼ਟਰੀ ਰਾਜਧਾਨੀ ਖੇਤਰ (NCR) ਵਿੱਚ ਮੋਟਰ ਵਾਹਨ ਬਣਾਉਣ ਲਈ ਥਾਂ ਦਾ ਕਿਹੜਾ ਲਾਭ ਖ਼ਾਸ ਤੌਰ 'ਤੇ ਸਹਾਇਕ ਹੈ?",["ਵੱਡਾ ਬਾਜ਼ਾਰ ਅਤੇ ਆਵਾਜਾਈ ਦੇ ਚੰਗੇ ਸੰਪਰਕ","ਸਿਰਫ਼ ਨੇੜੇ ਮਿਲਦਾ ਕੋਕਿੰਗ ਕੋਲਾ","ਚਾਹ ਦੇ ਬਾਗ਼","ਜਵਾਰ-ਭਾਟੇ ਦੀ ਊਰਜਾ"],"ਇਸ ਇਲਾਕੇ ਵਿੱਚ ਖਪਤਕਾਰਾਂ ਦਾ ਵੱਡਾ ਬਾਜ਼ਾਰ ਹੈ ਅਤੇ ਰਾਜਮਾਰਗ, ਸਪਲਾਇਰ, ਕਾਮੇ ਅਤੇ ਮਾਲ ਢੋਣ ਦੇ ਪ੍ਰਬੰਧ ਵੀ ਹਨ।"]},
"GEO-IND-001-CP007-Q027":{"h":"529be51d","hi":["कथनों पर विचार कीजिए: I. दिल्ली राष्ट्रीय राजधानी क्षेत्र (NCR) मोटर वाहन उद्योग का प्रमुख संकुल है। II. बाज़ार तक पहुँच इसके लाभों में से एक है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","I और II दोनों सही हैं","केवल II सही है","न तो I और न ही II सही है"],"दोनों कथन इस संकुल का सही वर्णन करते हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਦਿੱਲੀ ਰਾਸ਼ਟਰੀ ਰਾਜਧਾਨੀ ਖੇਤਰ (NCR) ਮੋਟਰ ਵਾਹਨ ਉਦਯੋਗ ਦਾ ਪ੍ਰਮੁੱਖ ਗੁੱਛ ਹੈ। II. ਬਾਜ਼ਾਰ ਤੱਕ ਪਹੁੰਚ ਇਸ ਦੇ ਲਾਭਾਂ ਵਿੱਚੋਂ ਇੱਕ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਦੋਵੇਂ ਕਥਨ ਇਸ ਉਦਯੋਗਿਕ ਗੁੱਛ ਦਾ ਸਹੀ ਵਰਣਨ ਕਰਦੇ ਹਨ।"]},
"GEO-IND-001-CP007-Q028":{"h":"58654ae4","hi":["कौन-सा युग्म दिल्ली राष्ट्रीय राजधानी क्षेत्र (NCR) की मोटर वाहन पट्टी की सही पहचान करता है?",["गुरुग्राम-मानेसर — जूट पट्टी","गुरुग्राम-मानेसर — कोयला क्षेत्र","गुरुग्राम-मानेसर — दिल्ली राष्ट्रीय राजधानी क्षेत्र (NCR) की मोटर वाहन पट्टी","गुरुग्राम-मानेसर — बॉक्साइट पट्टी"],"गुरुग्राम-मानेसर पट्टी राष्ट्रीय राजधानी क्षेत्र (NCR) में मोटर वाहन विनिर्माण का प्रमुख इलाका है।"],"pa":["ਕਿਹੜਾ ਜੋੜਾ ਦਿੱਲੀ ਰਾਸ਼ਟਰੀ ਰਾਜਧਾਨੀ ਖੇਤਰ (NCR) ਦੀ ਮੋਟਰ ਵਾਹਨ ਪੱਟੀ ਦੀ ਸਹੀ ਪਛਾਣ ਕਰਦਾ ਹੈ?",["ਗੁਰੂਗ੍ਰਾਮ-ਮਾਨੇਸਰ — ਜੂਟ ਪੱਟੀ","ਗੁਰੂਗ੍ਰਾਮ-ਮਾਨੇਸਰ — ਕੋਲਾ ਖੇਤਰ","ਗੁਰੂਗ੍ਰਾਮ-ਮਾਨੇਸਰ — ਦਿੱਲੀ ਰਾਸ਼ਟਰੀ ਰਾਜਧਾਨੀ ਖੇਤਰ (NCR) ਦੀ ਮੋਟਰ ਵਾਹਨ ਪੱਟੀ","ਗੁਰੂਗ੍ਰਾਮ-ਮਾਨੇਸਰ — ਬਾਕਸਾਈਟ ਪੱਟੀ"],"ਗੁਰੂਗ੍ਰਾਮ-ਮਾਨੇਸਰ ਪੱਟੀ ਰਾਸ਼ਟਰੀ ਰਾਜਧਾਨੀ ਖੇਤਰ (NCR) ਵਿੱਚ ਮੋਟਰ ਵਾਹਨ ਬਣਾਉਣ ਦਾ ਪ੍ਰਮੁੱਖ ਇਲਾਕਾ ਹੈ।"]},
"GEO-IND-001-CP007-Q029":{"h":"6fee2427","hi":["वाहनों के पुर्ज़े बनाने वाली कंपनियाँ वाहन संयोजन इकाइयों के आसपास क्यों इकट्ठी हो सकती हैं?",["उन्हें गन्ना चाहिए","वे केवल खदानों पर निर्भर हैं","वे बाज़ारों से दूर रहती हैं","उन्हें ढुलाई और आपूर्ति शृंखला का लाभ मिलता है"],"पास होने से पुर्ज़े पहुँचाने का समय घटता है और ज़रूरत के ठीक समय पर आपूर्ति करना आसान होता है।"],"pa":["ਮੋਟਰ ਵਾਹਨਾਂ ਦੇ ਪੁਰਜ਼ੇ ਬਣਾਉਣ ਵਾਲੀਆਂ ਕੰਪਨੀਆਂ ਵਾਹਨ ਜੋੜਨ ਵਾਲੇ ਕਾਰਖ਼ਾਨਿਆਂ ਕੋਲ ਕਿਉਂ ਇਕੱਠੀਆਂ ਹੋ ਸਕਦੀਆਂ ਹਨ?",["ਉਨ੍ਹਾਂ ਨੂੰ ਗੰਨਾ ਚਾਹੀਦਾ ਹੈ","ਉਹ ਸਿਰਫ਼ ਖਾਣਾਂ 'ਤੇ ਨਿਰਭਰ ਹਨ","ਉਹ ਬਾਜ਼ਾਰਾਂ ਤੋਂ ਦੂਰ ਰਹਿੰਦੀਆਂ ਹਨ","ਉਨ੍ਹਾਂ ਨੂੰ ਢੋਆ-ਢੁਆਈ ਅਤੇ ਸਪਲਾਈ ਲੜੀ ਦਾ ਲਾਭ ਮਿਲਦਾ ਹੈ"],"ਨੇੜੇ ਹੋਣ ਨਾਲ ਪੁਰਜ਼ੇ ਭੇਜਣ ਦਾ ਸਮਾਂ ਘਟਦਾ ਹੈ ਅਤੇ ਲੋੜ ਪੈਣ ਦੇ ਠੀਕ ਸਮੇਂ ਸਪਲਾਈ ਕਰਨੀ ਸੌਖੀ ਹੁੰਦੀ ਹੈ।"]},
"GEO-IND-001-CP007-Q030":{"h":"dd4f44a1","hi":["भारत के मोटर वाहन संकुलों की कौन-सी तुलना सही है?",["दिल्ली राष्ट्रीय राजधानी क्षेत्र (NCR) उत्तर में, चेन्नई दक्षिण में और पुणे पश्चिम में है","तीनों एक ही राज्य में हैं","तीनों कोयला क्षेत्र हैं","चेन्नई उत्तर भारत में है"],"तीनों संकुल भारत के अलग-अलग भागों के प्रमुख मोटर वाहन उद्योग क्षेत्रों के उदाहरण हैं।"],"pa":["ਭਾਰਤ ਦੇ ਮੋਟਰ ਵਾਹਨ ਉਦਯੋਗਿਕ ਗੁੱਛਾਂ ਬਾਰੇ ਕਿਹੜੀ ਤੁਲਨਾ ਸਹੀ ਹੈ?",["ਦਿੱਲੀ ਰਾਸ਼ਟਰੀ ਰਾਜਧਾਨੀ ਖੇਤਰ (NCR) ਉੱਤਰ ਵਿੱਚ, ਚੇਨਈ ਦੱਖਣ ਵਿੱਚ ਅਤੇ ਪੁਣੇ ਪੱਛਮ ਵਿੱਚ ਹੈ","ਤਿੰਨੇ ਇੱਕ ਰਾਜ ਵਿੱਚ ਹਨ","ਤਿੰਨੇ ਕੋਲਾ ਖੇਤਰ ਹਨ","ਚੇਨਈ ਉੱਤਰੀ ਭਾਰਤ ਵਿੱਚ ਹੈ"],"ਤਿੰਨੇ ਗੁੱਛ ਭਾਰਤ ਦੇ ਵੱਖੋ-ਵੱਖਰੇ ਹਿੱਸਿਆਂ ਵਿਚਲੇ ਪ੍ਰਮੁੱਖ ਮੋਟਰ ਵਾਹਨ ਖੇਤਰਾਂ ਦੀਆਂ ਉਦਾਹਰਨਾਂ ਹਨ।"]},
"GEO-IND-001-CP007-Q031":{"h":"354d48c1","hi":["बेंगलुरु का किन विनिर्माण गतिविधियों से गहरा संबंध है?",["केवल जूट मिलें","केवल कोयला खनन","केवल चीनी का परिष्करण","अभियांत्रिकी, वायु-अंतरिक्ष और उच्च प्रौद्योगिकी उद्योग"],"बेंगलुरु में अभियांत्रिकी और वायु-अंतरिक्ष उद्योग लंबे समय से स्थापित हैं। वहाँ आधुनिक प्रौद्योगिकी उद्योग भी हैं।"],"pa":["ਬੈਂਗਲੁਰੂ ਦਾ ਨਿਰਮਾਣ ਦੀਆਂ ਕਿਹੜੀਆਂ ਸਰਗਰਮੀਆਂ ਨਾਲ ਡੂੰਘਾ ਸਬੰਧ ਹੈ?",["ਸਿਰਫ਼ ਜੂਟ ਮਿੱਲਾਂ","ਸਿਰਫ਼ ਕੋਲੇ ਦੀ ਖੁਦਾਈ","ਸਿਰਫ਼ ਖੰਡ ਦੀ ਸੋਧਾਈ","ਇੰਜੀਨੀਅਰਿੰਗ, ਹਵਾਈ ਤੇ ਪੁਲਾੜ ਉਦਯੋਗ ਅਤੇ ਉੱਚ ਤਕਨਾਲੋਜੀ"],"ਬੈਂਗਲੁਰੂ ਵਿੱਚ ਇੰਜੀਨੀਅਰਿੰਗ ਅਤੇ ਹਵਾਈ ਤੇ ਪੁਲਾੜ ਉਦਯੋਗ ਲੰਮੇ ਸਮੇਂ ਤੋਂ ਸਥਾਪਤ ਹਨ। ਉੱਥੇ ਆਧੁਨਿਕ ਤਕਨਾਲੋਜੀ ਉਦਯੋਗ ਵੀ ਹਨ।"]},
"GEO-IND-001-CP007-Q032":{"h":"39a608a5","hi":["बेंगलुरु किस राज्य में है?",["कर्नाटक","तमिलनाडु","महाराष्ट्र","गुजरात"],"बेंगलुरु कर्नाटक की राजधानी है।"],"pa":["ਬੈਂਗਲੁਰੂ ਕਿਹੜੇ ਰਾਜ ਵਿੱਚ ਹੈ?",["ਕਰਨਾਟਕ","ਤਾਮਿਲਨਾਡੂ","ਮਹਾਰਾਸ਼ਟਰ","ਗੁਜਰਾਤ"],"ਬੈਂਗਲੁਰੂ ਕਰਨਾਟਕ ਦੀ ਰਾਜਧਾਨੀ ਹੈ।"]},
"GEO-IND-001-CP007-Q033":{"h":"6f052d8e","hi":["बेंगलुरु में अभियांत्रिकी और वायु-अंतरिक्ष उद्योगों को किससे आधार मिलता है?",["जूट के खेत","कुशल तकनीकी श्रम और अनुसंधान संस्थान","केवल कोयले की परतें","गन्ने की खेती"],"तकनीकी कौशल, अनुसंधान संस्थान और आपूर्तिकर्ताओं का तंत्र वहाँ के प्रमुख अवस्थितिक लाभ हैं।"],"pa":["ਬੈਂਗਲੁਰੂ ਵਿੱਚ ਇੰਜੀਨੀਅਰਿੰਗ ਅਤੇ ਹਵਾਈ ਤੇ ਪੁਲਾੜ ਉਦਯੋਗਾਂ ਨੂੰ ਕਿਸ ਤੋਂ ਆਧਾਰ ਮਿਲਦਾ ਹੈ?",["ਜੂਟ ਦੇ ਖੇਤ","ਹੁਨਰਮੰਦ ਤਕਨੀਕੀ ਕਾਮੇ ਅਤੇ ਖੋਜ ਸੰਸਥਾਵਾਂ","ਸਿਰਫ਼ ਕੋਲੇ ਦੀਆਂ ਪਰਤਾਂ","ਗੰਨੇ ਦੀ ਖੇਤੀ"],"ਤਕਨੀਕੀ ਹੁਨਰ, ਖੋਜ ਸੰਸਥਾਵਾਂ ਅਤੇ ਸਪਲਾਇਰਾਂ ਦੇ ਜਾਲ ਇਸ ਥਾਂ ਦੇ ਪ੍ਰਮੁੱਖ ਲਾਭ ਹਨ।"]},
"GEO-IND-001-CP007-Q034":{"h":"2f563f94","hi":["कथनों पर विचार कीजिए: I. बेंगलुरु अभियांत्रिकी का प्रमुख केंद्र है। II. उसके औद्योगिक आधार में कुशल श्रम महत्वपूर्ण है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","I और II दोनों सही हैं","न तो I और न ही II सही है"],"दोनों कथन बेंगलुरु के औद्योगिक भूगोल को समझाते हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਬੈਂਗਲੁਰੂ ਇੰਜੀਨੀਅਰਿੰਗ ਦਾ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰ ਹੈ। II. ਇਸ ਦੇ ਉਦਯੋਗਿਕ ਆਧਾਰ ਵਿੱਚ ਹੁਨਰਮੰਦ ਕਾਮੇ ਅਹਿਮ ਹਨ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਦੋਵੇਂ ਕਥਨ ਬੈਂਗਲੁਰੂ ਦੇ ਉਦਯੋਗਿਕ ਭੂਗੋਲ ਨੂੰ ਸਮਝਾਉਂਦੇ ਹਨ।"]},
"GEO-IND-001-CP007-Q035":{"h":"38f58c3d","hi":["कौन-सा युग्म बेंगलुरु की अभियांत्रिकी विशेषज्ञता सही दर्शाता है?",["बेंगलुरु — केवल जूट","बेंगलुरु — कोकिंग कोयला","बेंगलुरु — केवल चीनी","बेंगलुरु — वायु-अंतरिक्ष और अभियांत्रिकी"],"बेंगलुरु का वायु-अंतरिक्ष, अभियांत्रिकी और उच्च प्रौद्योगिकी वाले विनिर्माण से गहरा संबंध है।"],"pa":["ਕਿਹੜਾ ਜੋੜਾ ਬੈਂਗਲੁਰੂ ਦੇ ਇੰਜੀਨੀਅਰਿੰਗ ਉਦਯੋਗਾਂ ਦੀ ਸਹੀ ਪਛਾਣ ਕਰਦਾ ਹੈ?",["ਬੈਂਗਲੁਰੂ — ਸਿਰਫ਼ ਜੂਟ","ਬੈਂਗਲੁਰੂ — ਕੋਕਿੰਗ ਕੋਲਾ","ਬੈਂਗਲੁਰੂ — ਸਿਰਫ਼ ਖੰਡ","ਬੈਂਗਲੁਰੂ — ਹਵਾਈ ਤੇ ਪੁਲਾੜ ਉਦਯੋਗ ਅਤੇ ਇੰਜੀਨੀਅਰਿੰਗ"],"ਬੈਂਗਲੁਰੂ ਦਾ ਹਵਾਈ ਤੇ ਪੁਲਾੜ ਉਦਯੋਗ, ਇੰਜੀਨੀਅਰਿੰਗ ਅਤੇ ਉੱਚ ਤਕਨਾਲੋਜੀ ਵਾਲੇ ਨਿਰਮਾਣ ਨਾਲ ਡੂੰਘਾ ਸਬੰਧ ਹੈ।"]},
"GEO-IND-001-CP007-Q036":{"h":"0c8ac34f","hi":["उद्योगों की अवस्थिति के कारकों की कौन-सी तुलना सही है?",["बेंगलुरु में कुशल श्रम की बड़ी भूमिका है, जबकि इस्पात संयंत्र भारी खनिज सामग्री पर अधिक निर्भर हैं","दोनों केवल गन्ने पर निर्भर हैं","दोनों को परिवहन की ज़रूरत नहीं है","इस्पात संयंत्र केवल सॉफ़्टवेयर पर निर्भर हैं"],"अभियांत्रिकी और भारी उद्योगों की अवस्थिति में कौशल, बाज़ार, आपूर्तिकर्ता, बिजली और परिवहन का महत्व अलग-अलग होता है। कोई एक कारक हर जगह निर्णायक नहीं होता।"],"pa":["ਉਦਯੋਗਾਂ ਦੀ ਥਾਂ ਦੀ ਚੋਣ ਦੇ ਕਾਰਕਾਂ ਦੀ ਕਿਹੜੀ ਤੁਲਨਾ ਸਹੀ ਹੈ?",["ਬੈਂਗਲੁਰੂ ਹੁਨਰਮੰਦ ਕਾਮਿਆਂ 'ਤੇ ਬਹੁਤ ਨਿਰਭਰ ਹੈ, ਜਦਕਿ ਸਟੀਲ ਪਲਾਂਟ ਭਾਰੀ ਖਣਿਜ ਸਮੱਗਰੀ 'ਤੇ ਵੱਧ ਨਿਰਭਰ ਹਨ","ਦੋਵੇਂ ਸਿਰਫ਼ ਗੰਨੇ 'ਤੇ ਨਿਰਭਰ ਹਨ","ਦੋਵਾਂ ਨੂੰ ਆਵਾਜਾਈ ਦੀ ਲੋੜ ਨਹੀਂ ਹੈ","ਸਟੀਲ ਪਲਾਂਟ ਸਿਰਫ਼ ਸਾਫ਼ਟਵੇਅਰ 'ਤੇ ਨਿਰਭਰ ਹਨ"],"ਇੰਜੀਨੀਅਰਿੰਗ ਅਤੇ ਭਾਰੀ ਉਦਯੋਗਾਂ ਲਈ ਹੁਨਰ, ਬਾਜ਼ਾਰਾਂ, ਸਪਲਾਇਰਾਂ, ਬਿਜਲੀ ਅਤੇ ਆਵਾਜਾਈ ਦਾ ਮਹੱਤਵ ਵੱਖੋ-ਵੱਖਰਾ ਹੁੰਦਾ ਹੈ। ਕੋਈ ਇੱਕ ਕਾਰਕ ਹਰ ਥਾਂ ਫ਼ੈਸਲਾਕੁਨ ਨਹੀਂ ਹੁੰਦਾ।"]},
"GEO-IND-001-CP007-Q037":{"h":"db99f556","hi":["भोपाल का किस भारी विनिर्माण गतिविधि से ऐतिहासिक संबंध है?",["भारी विद्युत उपकरण","जूट मिलें","चीनी का परिष्करण","चाय प्रसंस्करण"],"भोपाल भारत में भारी विद्युत उपकरण बनाने के महत्वपूर्ण केंद्रों में से एक है।"],"pa":["ਭੋਪਾਲ ਦਾ ਭਾਰੀ ਨਿਰਮਾਣ ਦੀ ਕਿਹੜੀ ਸਰਗਰਮੀ ਨਾਲ ਇਤਿਹਾਸਕ ਸਬੰਧ ਹੈ?",["ਭਾਰੀ ਬਿਜਲਈ ਸਾਜ਼ੋ-ਸਾਮਾਨ","ਜੂਟ ਮਿੱਲਾਂ","ਖੰਡ ਦੀ ਸੋਧਾਈ","ਚਾਹ ਦੀ ਪ੍ਰੋਸੈਸਿੰਗ"],"ਭੋਪਾਲ ਭਾਰੀ ਬਿਜਲਈ ਸਾਜ਼ੋ-ਸਾਮਾਨ ਬਣਾਉਣ ਵਾਲੇ ਭਾਰਤ ਦੇ ਅਹਿਮ ਕੇਂਦਰਾਂ ਵਿੱਚੋਂ ਇੱਕ ਹੈ।"]},
"GEO-IND-001-CP007-Q038":{"h":"b9713a69","hi":["कौन-सा उद्योग टरबाइन, जनित्र और बड़े विद्युत उपकरण बनाता है?",["खाद्य प्रसंस्करण","भारी विद्युत अभियांत्रिकी","जूट वस्त्र","चीनी मिलें"],"भारी विद्युत अभियांत्रिकी उद्योग बिजली उत्पादन और पारेषण के बड़े उपकरण बनाता है।"],"pa":["ਕਿਹੜਾ ਉਦਯੋਗ ਟਰਬਾਈਨਾਂ, ਜਨਰੇਟਰ ਅਤੇ ਵੱਡਾ ਬਿਜਲਈ ਸਾਜ਼ੋ-ਸਾਮਾਨ ਬਣਾਉਂਦਾ ਹੈ?",["ਖ਼ੁਰਾਕੀ ਪ੍ਰੋਸੈਸਿੰਗ","ਭਾਰੀ ਬਿਜਲਈ ਇੰਜੀਨੀਅਰਿੰਗ","ਜੂਟ ਦੇ ਕੱਪੜੇ","ਖੰਡ ਮਿੱਲਾਂ"],"ਭਾਰੀ ਬਿਜਲਈ ਇੰਜੀਨੀਅਰਿੰਗ ਉਦਯੋਗ ਬਿਜਲੀ ਪੈਦਾ ਕਰਨ ਅਤੇ ਉਸ ਨੂੰ ਅੱਗੇ ਭੇਜਣ ਲਈ ਵੱਡਾ ਸਾਜ਼ੋ-ਸਾਮਾਨ ਬਣਾਉਂਦਾ ਹੈ।"]},
"GEO-IND-001-CP007-Q039":{"h":"2b53041c","hi":["कथनों पर विचार कीजिए: I. भारी विद्युत उपकरण पूँजीगत वस्तुएँ हैं। II. इन्हें बनाने वाले उद्योगों को कुशल तकनीकी श्रमिक चाहिए। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","I और II दोनों सही हैं","न तो I और न ही II सही है"],"बड़ी विद्युत मशीनें पूँजीगत उपकरण हैं और उनके निर्माण के लिए अभियांत्रिकी कौशल चाहिए।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਭਾਰੀ ਬਿਜਲਈ ਸਾਜ਼ੋ-ਸਾਮਾਨ ਪੂੰਜੀਗਤ ਵਸਤਾਂ ਵਿੱਚ ਆਉਂਦਾ ਹੈ। II. ਅਜਿਹੇ ਉਦਯੋਗਾਂ ਨੂੰ ਹੁਨਰਮੰਦ ਤਕਨੀਕੀ ਕਾਮੇ ਚਾਹੀਦੇ ਹਨ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਵੱਡੀਆਂ ਬਿਜਲਈ ਮਸ਼ੀਨਾਂ ਪੂੰਜੀਗਤ ਸਾਜ਼ੋ-ਸਾਮਾਨ ਹਨ ਅਤੇ ਇਨ੍ਹਾਂ ਨੂੰ ਬਣਾਉਣ ਲਈ ਇੰਜੀਨੀਅਰਿੰਗ ਦਾ ਹੁਨਰ ਚਾਹੀਦਾ ਹੈ।"]},
"GEO-IND-001-CP007-Q040":{"h":"63c9913e","hi":["भारी अभियांत्रिकी में कौन-सा युग्म सही सुमेलित है?",["भोपाल — केवल जूट","भोपाल — पेट्रोलियम क्षेत्र","भोपाल — चीनी पट्टी","भोपाल — भारी विद्युत उपकरण"],"भोपाल में भारी विद्युत उपकरणों का विनिर्माण लंबे समय से स्थापित है।"],"pa":["ਭਾਰੀ ਇੰਜੀਨੀਅਰਿੰਗ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਭੋਪਾਲ — ਸਿਰਫ਼ ਜੂਟ","ਭੋਪਾਲ — ਪੈਟਰੋਲੀਅਮ ਖੇਤਰ","ਭੋਪਾਲ — ਖੰਡ ਪੱਟੀ","ਭੋਪਾਲ — ਭਾਰੀ ਬਿਜਲਈ ਸਾਜ਼ੋ-ਸਾਮਾਨ"],"ਭੋਪਾਲ ਵਿੱਚ ਭਾਰੀ ਬਿਜਲਈ ਸਾਜ਼ੋ-ਸਾਮਾਨ ਦਾ ਨਿਰਮਾਣ ਲੰਮੇ ਸਮੇਂ ਤੋਂ ਸਥਾਪਤ ਹੈ।"]},
"GEO-IND-001-CP007-Q041":{"h":"bc362164","hi":["भारी विद्युत अभियांत्रिकी उद्योग की अवस्थिति के लिए कौन-सा कारक विशेष रूप से महत्वपूर्ण है?",["अभियांत्रिकी में कुशल श्रम","जूट की खेती","गन्ने की आपूर्ति","ज्वारीय परास"],"जटिल मशीनों का उत्पादन काफी हद तक तकनीकी कौशल और औद्योगिक आधारभूत संरचना पर निर्भर है।"],"pa":["ਭਾਰੀ ਬਿਜਲਈ ਇੰਜੀਨੀਅਰਿੰਗ ਉਦਯੋਗ ਦੀ ਥਾਂ ਲਈ ਕਿਹੜਾ ਕਾਰਕ ਖ਼ਾਸ ਤੌਰ 'ਤੇ ਅਹਿਮ ਹੈ?",["ਇੰਜੀਨੀਅਰਿੰਗ ਵਿੱਚ ਹੁਨਰਮੰਦ ਕਾਮੇ","ਜੂਟ ਦੀ ਖੇਤੀ","ਗੰਨੇ ਦੀ ਸਪਲਾਈ","ਜਵਾਰ-ਭਾਟਾ ਅੰਤਰ"],"ਗੁੰਝਲਦਾਰ ਮਸ਼ੀਨਰੀ ਬਣਾਉਣਾ ਤਕਨੀਕੀ ਹੁਨਰ ਅਤੇ ਉਦਯੋਗਿਕ ਬੁਨਿਆਦੀ ਢਾਂਚੇ 'ਤੇ ਬਹੁਤ ਨਿਰਭਰ ਹੈ।"]},
"GEO-IND-001-CP007-Q042":{"h":"84e4f290","hi":["एक कारखाना विद्युत परियोजनाओं के लिए टरबाइन और जनित्र बनाता है। यह कौन-सा उद्योग है?",["सूती वस्त्र","भारी विद्युत अभियांत्रिकी","खाद्य प्रसंस्करण","सीमेंट"],"टरबाइन और जनित्र बड़ी विद्युत पूँजीगत वस्तुएँ हैं।"],"pa":["ਇੱਕ ਕਾਰਖ਼ਾਨਾ ਬਿਜਲੀ ਪ੍ਰਾਜੈਕਟਾਂ ਲਈ ਟਰਬਾਈਨਾਂ ਅਤੇ ਜਨਰੇਟਰ ਬਣਾਉਂਦਾ ਹੈ। ਇਹ ਕਿਹੜਾ ਉਦਯੋਗ ਹੈ?",["ਸੂਤੀ ਕੱਪੜਾ","ਭਾਰੀ ਬਿਜਲਈ ਇੰਜੀਨੀਅਰਿੰਗ","ਖ਼ੁਰਾਕੀ ਪ੍ਰੋਸੈਸਿੰਗ","ਸੀਮਿੰਟ"],"ਟਰਬਾਈਨਾਂ ਅਤੇ ਜਨਰੇਟਰ ਵੱਡੀਆਂ ਬਿਜਲਈ ਪੂੰਜੀਗਤ ਵਸਤਾਂ ਹਨ।"]},
"GEO-IND-001-CP007-Q043":{"h":"9b41bac4","hi":["कौन-सा शहर भारत के मशीन औज़ार उद्योग का महत्वपूर्ण केंद्र है?",["झरिया","बेंगलुरु","सांभर","डिगबोई"],"बेंगलुरु में मशीन औज़ार और परिशुद्ध अभियांत्रिकी उद्योग लंबे समय से स्थापित हैं।"],"pa":["ਕਿਹੜਾ ਸ਼ਹਿਰ ਭਾਰਤ ਵਿੱਚ ਮਸ਼ੀਨੀ ਔਜ਼ਾਰਾਂ ਦੇ ਉਦਯੋਗ ਦਾ ਅਹਿਮ ਕੇਂਦਰ ਹੈ?",["ਝਰੀਆ","ਬੈਂਗਲੁਰੂ","ਸਾਂਭਰ","ਡਿਗਬੋਈ"],"ਬੈਂਗਲੁਰੂ ਵਿੱਚ ਮਸ਼ੀਨੀ ਔਜ਼ਾਰਾਂ ਅਤੇ ਬਾਰੀਕੀ ਵਾਲੀ ਇੰਜੀਨੀਅਰਿੰਗ ਦਾ ਕੰਮ ਲੰਮੇ ਸਮੇਂ ਤੋਂ ਸਥਾਪਤ ਹੈ।"]},
"GEO-IND-001-CP007-Q044":{"h":"c087fb03","hi":["मशीन औज़ार किस प्रकार के औद्योगिक उत्पाद हैं?",["कृषि फसलें","उपभोग के लिए खाद्य पदार्थ","पूँजीगत वस्तुएँ","खनिज अयस्क"],"मशीन औज़ारों का इस्तेमाल दूसरे उत्पाद बनाने में होता है, इसलिए वे पूँजीगत वस्तुएँ हैं।"],"pa":["ਮਸ਼ੀਨੀ ਔਜ਼ਾਰ ਕਿਸ ਕਿਸਮ ਦੇ ਉਦਯੋਗਿਕ ਉਤਪਾਦ ਹਨ?",["ਖੇਤੀ ਫ਼ਸਲਾਂ","ਖਪਤ ਵਾਲੇ ਖ਼ੁਰਾਕੀ ਪਦਾਰਥ","ਪੂੰਜੀਗਤ ਵਸਤਾਂ","ਖਣਿਜ ਅਯਸਕ"],"ਮਸ਼ੀਨੀ ਔਜ਼ਾਰ ਹੋਰ ਉਤਪਾਦ ਬਣਾਉਣ ਲਈ ਵਰਤੇ ਜਾਂਦੇ ਹਨ। ਇਸ ਲਈ ਉਹ ਪੂੰਜੀਗਤ ਵਸਤਾਂ ਹਨ।"]},
"GEO-IND-001-CP007-Q045":{"h":"a0bdeb0b","hi":["कथनों पर विचार कीजिए: I. मशीन औज़ार दूसरे विनिर्माण उद्योगों में काम आते हैं। II. उन्हें बनाने में परिशुद्ध अभियांत्रिकी का कौशल महत्वपूर्ण है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","न तो I और न ही II सही है","I और II दोनों सही हैं"],"मशीन औज़ार उत्पादन के बुनियादी उपकरण हैं। उन्हें बनाने के लिए अभियांत्रिकी कौशल चाहिए।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਮਸ਼ੀਨੀ ਔਜ਼ਾਰ ਹੋਰ ਨਿਰਮਾਣ ਉਦਯੋਗਾਂ ਦੇ ਕੰਮ ਆਉਂਦੇ ਹਨ। II. ਇਨ੍ਹਾਂ ਨੂੰ ਬਣਾਉਣ ਲਈ ਬਾਰੀਕੀ ਵਾਲੀ ਇੰਜੀਨੀਅਰਿੰਗ ਦਾ ਹੁਨਰ ਅਹਿਮ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ"],"ਮਸ਼ੀਨੀ ਔਜ਼ਾਰ ਉਤਪਾਦਨ ਲਈ ਬੁਨਿਆਦੀ ਸਾਜ਼ੋ-ਸਾਮਾਨ ਹਨ ਅਤੇ ਇਨ੍ਹਾਂ ਨੂੰ ਬਣਾਉਣ ਲਈ ਇੰਜੀਨੀਅਰਿੰਗ ਦਾ ਹੁਨਰ ਚਾਹੀਦਾ ਹੈ।"]},
"GEO-IND-001-CP007-Q046":{"h":"7f535ecd","hi":["मशीन औज़ार उद्योग के भूगोल में कौन-सा युग्म बेंगलुरु की सही पहचान करता है?",["बेंगलुरु — मशीन औज़ार","बेंगलुरु — केवल जूट","बेंगलुरु — कोयला क्षेत्र","बेंगलुरु — केवल चीनी"],"बेंगलुरु मशीन औज़ार और अभियांत्रिकी का महत्वपूर्ण केंद्र है।"],"pa":["ਮਸ਼ੀਨੀ ਔਜ਼ਾਰਾਂ ਦੇ ਉਦਯੋਗ ਦੇ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਬੈਂਗਲੁਰੂ ਦੀ ਸਹੀ ਪਛਾਣ ਕਰਦਾ ਹੈ?",["ਬੈਂਗਲੁਰੂ — ਮਸ਼ੀਨੀ ਔਜ਼ਾਰ","ਬੈਂਗਲੁਰੂ — ਸਿਰਫ਼ ਜੂਟ","ਬੈਂਗਲੁਰੂ — ਕੋਲਾ ਖੇਤਰ","ਬੈਂਗਲੁਰੂ — ਸਿਰਫ਼ ਖੰਡ"],"ਬੈਂਗਲੁਰੂ ਮਸ਼ੀਨੀ ਔਜ਼ਾਰਾਂ ਅਤੇ ਇੰਜੀਨੀਅਰਿੰਗ ਦਾ ਅਹਿਮ ਕੇਂਦਰ ਹੈ।"]},
"GEO-IND-001-CP007-Q047":{"h":"ef34aa1f","hi":["मशीन औज़ार उद्योग अभियांत्रिकी केंद्रों के पास क्यों इकट्ठे होते हैं?",["उन्हें गन्ना चाहिए","उन्हें कुशल श्रम, आपूर्तिकर्ताओं और औद्योगिक ग्राहकों का लाभ मिलता है","वे केवल पत्तनों पर निर्भर हैं","उन्हें चाय के बागान चाहिए"],"अभियांत्रिकी संकुलों में विशेष उत्पादन सामग्री भी मिलती है और आगे के उत्पादन चरणों में मशीन औज़ार इस्तेमाल करने वाले ग्राहक भी।"],"pa":["ਮਸ਼ੀਨੀ ਔਜ਼ਾਰ ਬਣਾਉਣ ਵਾਲੇ ਉਦਯੋਗ ਇੰਜੀਨੀਅਰਿੰਗ ਕੇਂਦਰਾਂ ਦੇ ਨੇੜੇ ਕਿਉਂ ਇਕੱਠੇ ਹੁੰਦੇ ਹਨ?",["ਉਨ੍ਹਾਂ ਨੂੰ ਗੰਨਾ ਚਾਹੀਦਾ ਹੈ","ਉਨ੍ਹਾਂ ਨੂੰ ਹੁਨਰਮੰਦ ਕਾਮਿਆਂ, ਸਪਲਾਇਰਾਂ ਅਤੇ ਉਦਯੋਗਿਕ ਗਾਹਕਾਂ ਦਾ ਲਾਭ ਮਿਲਦਾ ਹੈ","ਉਹ ਸਿਰਫ਼ ਬੰਦਰਗਾਹਾਂ 'ਤੇ ਨਿਰਭਰ ਹਨ","ਉਨ੍ਹਾਂ ਨੂੰ ਚਾਹ ਦੇ ਬਾਗ਼ ਚਾਹੀਦੇ ਹਨ"],"ਇੰਜੀਨੀਅਰਿੰਗ ਦੇ ਗੁੱਛਾਂ ਵਿੱਚ ਖ਼ਾਸ ਉਤਪਾਦਨ ਸਮੱਗਰੀ ਦੇ ਨਾਲ ਅੱਗੇ ਮਸ਼ੀਨੀ ਔਜ਼ਾਰ ਵਰਤਣ ਵਾਲੇ ਗਾਹਕ ਵੀ ਮਿਲਦੇ ਹਨ।"]},
"GEO-IND-001-CP007-Q048":{"h":"9f0d21a3","hi":["मशीन औज़ारों की भूमिका कौन-सी शृंखला सही दर्शाती है?",["जूट → मशीन औज़ार → चीनी","कोयला → कपास → मशीन औज़ार","मशीन औज़ार → विनिर्माण उपकरण → औद्योगिक उत्पादन","बॉक्साइट → चाय → मशीनरी"],"मशीन औज़ारों से विभिन्न विनिर्माण उद्योगों में इस्तेमाल होने वाले पुर्ज़े और उपकरण बनाए जाते हैं।"],"pa":["ਮਸ਼ੀਨੀ ਔਜ਼ਾਰਾਂ ਦੀ ਭੂਮਿਕਾ ਕਿਹੜੀ ਲੜੀ ਸਹੀ ਦਰਸਾਉਂਦੀ ਹੈ?",["ਜੂਟ → ਮਸ਼ੀਨੀ ਔਜ਼ਾਰ → ਖੰਡ","ਕੋਲਾ → ਕਪਾਹ → ਮਸ਼ੀਨੀ ਔਜ਼ਾਰ","ਮਸ਼ੀਨੀ ਔਜ਼ਾਰ → ਨਿਰਮਾਣ ਦਾ ਸਾਜ਼ੋ-ਸਾਮਾਨ → ਉਦਯੋਗਿਕ ਉਤਪਾਦਨ","ਬਾਕਸਾਈਟ → ਚਾਹ → ਮਸ਼ੀਨਰੀ"],"ਮਸ਼ੀਨੀ ਔਜ਼ਾਰਾਂ ਨਾਲ ਵੱਖ-ਵੱਖ ਨਿਰਮਾਣ ਉਦਯੋਗਾਂ ਵਿੱਚ ਵਰਤੇ ਜਾਂਦੇ ਪੁਰਜ਼ੇ ਅਤੇ ਸਾਜ਼ੋ-ਸਾਮਾਨ ਬਣਾਏ ਜਾਂਦੇ ਹਨ।"]},
"GEO-IND-001-CP007-Q049":{"h":"9bf95158","hi":["कौन-सा तटीय शहर भारत का प्रमुख जहाज़ निर्माण केंद्र है?",["झरिया","कोडरमा","भिलाई","कोच्चि"],"कोच्चि भारत के सबसे प्रसिद्ध जहाज़ निर्माण केंद्रों में से एक है और वहाँ एक प्रमुख पोत निर्माणशाला है।"],"pa":["ਕਿਹੜਾ ਤੱਟੀ ਸ਼ਹਿਰ ਭਾਰਤ ਵਿੱਚ ਸਮੁੰਦਰੀ ਜਹਾਜ਼ ਬਣਾਉਣ ਦਾ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰ ਹੈ?",["ਝਰੀਆ","ਕੋਡਰਮਾ","ਭਿਲਾਈ","ਕੋਚੀ"],"ਕੋਚੀ ਭਾਰਤ ਵਿੱਚ ਸਮੁੰਦਰੀ ਜਹਾਜ਼ ਬਣਾਉਣ ਦੇ ਸਭ ਤੋਂ ਮਸ਼ਹੂਰ ਕੇਂਦਰਾਂ ਵਿੱਚੋਂ ਇੱਕ ਹੈ। ਉੱਥੇ ਜਹਾਜ਼ ਬਣਾਉਣ ਦੀ ਪ੍ਰਮੁੱਖ ਗੋਦੀ ਹੈ।"]},
"GEO-IND-001-CP007-Q050":{"h":"83900cc7","hi":["किस अन्य पत्तन शहर का जहाज़ निर्माण से गहरा संबंध है?",["विशाखापत्तनम","सांभर","पन्ना","खेतड़ी"],"विशाखापत्तनम में जहाज़ निर्माण और मरम्मत का प्रमुख उद्योग है।"],"pa":["ਕਿਸ ਹੋਰ ਬੰਦਰਗਾਹੀ ਸ਼ਹਿਰ ਦਾ ਸਮੁੰਦਰੀ ਜਹਾਜ਼ ਬਣਾਉਣ ਨਾਲ ਡੂੰਘਾ ਸਬੰਧ ਹੈ?",["ਵਿਸ਼ਾਖਾਪਟਨਮ","ਸਾਂਭਰ","ਪੰਨਾ","ਖੇਤੜੀ"],"ਵਿਸ਼ਾਖਾਪਟਨਮ ਵਿੱਚ ਸਮੁੰਦਰੀ ਜਹਾਜ਼ ਬਣਾਉਣ ਅਤੇ ਉਨ੍ਹਾਂ ਦੀ ਮੁਰੰਮਤ ਦਾ ਪ੍ਰਮੁੱਖ ਉਦਯੋਗ ਹੈ।"]},
"GEO-IND-001-CP007-Q051":{"h":"05670878","hi":["प्रमुख पोत निर्माणशालाएँ तट पर क्यों होती हैं?",["उन्हें केवल कोयला खदानें चाहिए","जहाज़ों को नौचालन योग्य समुद्री जल तक सीधी पहुँच चाहिए","उन्हें जूट के खेत चाहिए","वे गन्ने पर निर्भर हैं"],"बड़े जहाज़ों को पानी में उतारने, गोदी में लगाने और उनकी मरम्मत करने के लिए उपयुक्त तटीय स्थान चाहिए।"],"pa":["ਸਮੁੰਦਰੀ ਜਹਾਜ਼ ਬਣਾਉਣ ਦੀਆਂ ਪ੍ਰਮੁੱਖ ਗੋਦੀਆਂ ਤੱਟ 'ਤੇ ਕਿਉਂ ਹੁੰਦੀਆਂ ਹਨ?",["ਉਨ੍ਹਾਂ ਨੂੰ ਸਿਰਫ਼ ਕੋਲੇ ਦੀਆਂ ਖਾਣਾਂ ਚਾਹੀਦੀਆਂ ਹਨ","ਜਹਾਜ਼ਾਂ ਨੂੰ ਆਵਾਜਾਈ ਯੋਗ ਸਮੁੰਦਰੀ ਪਾਣੀ ਤੱਕ ਸਿੱਧੀ ਪਹੁੰਚ ਚਾਹੀਦੀ ਹੈ","ਉਨ੍ਹਾਂ ਨੂੰ ਜੂਟ ਦੇ ਖੇਤ ਚਾਹੀਦੇ ਹਨ","ਉਹ ਗੰਨੇ 'ਤੇ ਨਿਰਭਰ ਹਨ"],"ਵੱਡੇ ਜਹਾਜ਼ ਪਾਣੀ ਵਿੱਚ ਉਤਾਰਨ, ਗੋਦੀ ਵਿੱਚ ਲਾਉਣ ਅਤੇ ਮੁਰੰਮਤ ਕਰਨ ਲਈ ਢੁੱਕਵੀਆਂ ਤੱਟੀ ਥਾਵਾਂ ਚਾਹੀਦੀਆਂ ਹਨ।"]},
"GEO-IND-001-CP007-Q052":{"h":"2726e967","hi":["कथनों पर विचार कीजिए: I. कोच्चि जहाज़ निर्माण केंद्र है। II. विशाखापत्तनम का भी जहाज़ निर्माण से संबंध है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","I और II दोनों सही हैं","न तो I और न ही II सही है"],"दोनों जहाज़ निर्माण के महत्वपूर्ण तटीय स्थान हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਕੋਚੀ ਸਮੁੰਦਰੀ ਜਹਾਜ਼ ਬਣਾਉਣ ਦਾ ਕੇਂਦਰ ਹੈ। II. ਵਿਸ਼ਾਖਾਪਟਨਮ ਦਾ ਵੀ ਸਮੁੰਦਰੀ ਜਹਾਜ਼ ਬਣਾਉਣ ਨਾਲ ਸਬੰਧ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਦੋਵੇਂ ਸਮੁੰਦਰੀ ਜਹਾਜ਼ ਬਣਾਉਣ ਲਈ ਅਹਿਮ ਤੱਟੀ ਥਾਵਾਂ ਹਨ।"]},
"GEO-IND-001-CP007-Q053":{"h":"2f147247","hi":["जहाज़ निर्माण के भूगोल में कौन-सा युग्म सही सुमेलित है?",["कोच्चि — कोकिंग कोयला","विशाखापत्तनम — केवल जूट","कोच्चि — लौह अयस्क खदान","कोच्चि — जहाज़ निर्माण"],"कोच्चि जहाज़ निर्माण का प्रमुख केंद्र है।"],"pa":["ਸਮੁੰਦਰੀ ਜਹਾਜ਼ ਬਣਾਉਣ ਦੇ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਕੋਚੀ — ਕੋਕਿੰਗ ਕੋਲਾ","ਵਿਸ਼ਾਖਾਪਟਨਮ — ਸਿਰਫ਼ ਜੂਟ","ਕੋਚੀ — ਕੱਚੇ ਲੋਹੇ ਦੀ ਖਾਣ","ਕੋਚੀ — ਸਮੁੰਦਰੀ ਜਹਾਜ਼ ਬਣਾਉਣਾ"],"ਕੋਚੀ ਸਮੁੰਦਰੀ ਜਹਾਜ਼ ਬਣਾਉਣ ਦਾ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰ ਹੈ।"]},
"GEO-IND-001-CP007-Q054":{"h":"4d205e10","hi":["जहाज़ निर्माण की अवस्थिति का सबसे विशिष्ट कारक कौन-सा है?",["तट पर गहरे पानी तक पहुँच","कपास की खेती","शैल फ़ॉस्फ़ेट के निक्षेप","गन्ना उत्पादक पट्टी"],"बड़े जहाज़ बनाने और पानी में उतारने के लिए पोत निर्माणशालाओं को जलतट पर उपयुक्त स्थान चाहिए।"],"pa":["ਸਮੁੰਦਰੀ ਜਹਾਜ਼ ਬਣਾਉਣ ਦੀ ਥਾਂ ਦਾ ਸਭ ਤੋਂ ਖ਼ਾਸ ਕਾਰਕ ਕਿਹੜਾ ਹੈ?",["ਤੱਟ 'ਤੇ ਡੂੰਘੇ ਪਾਣੀ ਤੱਕ ਪਹੁੰਚ","ਕਪਾਹ ਦੀ ਖੇਤੀ","ਚੱਟਾਨੀ ਫ਼ਾਸਫ਼ੇਟ ਦੇ ਭੰਡਾਰ","ਗੰਨਾ ਉਗਾਉਣ ਵਾਲੀ ਪੱਟੀ"],"ਵੱਡੇ ਜਹਾਜ਼ ਬਣਾਉਣ ਅਤੇ ਪਾਣੀ ਵਿੱਚ ਉਤਾਰਨ ਲਈ ਗੋਦੀਆਂ ਵਾਸਤੇ ਪਾਣੀ ਦੇ ਕੰਢੇ ਢੁੱਕਵੀਆਂ ਥਾਵਾਂ ਚਾਹੀਦੀਆਂ ਹਨ।"]},
"GEO-IND-001-CP007-Q055":{"h":"e694dff3","hi":["कौन-सा उद्योग रेल इंजन, डिब्बे और रेल उपकरण बनाता है?",["जूट उद्योग","चीनी उद्योग","सीमेंट उद्योग","परिवहन अभियांत्रिकी"],"रेल के चल वाहन और उपकरण परिवहन अभियांत्रिकी के अंतर्गत आते हैं।"],"pa":["ਕਿਹੜਾ ਉਦਯੋਗ ਰੇਲ ਇੰਜਣ, ਡੱਬੇ ਅਤੇ ਰੇਲ ਦਾ ਸਾਜ਼ੋ-ਸਾਮਾਨ ਬਣਾਉਂਦਾ ਹੈ?",["ਜੂਟ ਉਦਯੋਗ","ਖੰਡ ਉਦਯੋਗ","ਸੀਮਿੰਟ ਉਦਯੋਗ","ਆਵਾਜਾਈ ਇੰਜੀਨੀਅਰਿੰਗ"],"ਰੇਲ ਇੰਜਣ, ਡੱਬੇ ਅਤੇ ਰੇਲ ਦਾ ਸਾਜ਼ੋ-ਸਾਮਾਨ ਆਵਾਜਾਈ ਇੰਜੀਨੀਅਰਿੰਗ ਵਿੱਚ ਆਉਂਦੇ ਹਨ।"]},
"GEO-IND-001-CP007-Q056":{"h":"ef0b85d3","hi":["चित्तरंजन ऐतिहासिक रूप से कौन-सा परिवहन उपकरण बनाने के लिए प्रसिद्ध है?",["रेल इंजन","जहाज़","केवल विमान","केवल जूट के करघे"],"पश्चिम बंगाल का चित्तरंजन रेल इंजन बनाने का प्रमुख केंद्र है।"],"pa":["ਚਿੱਤਰੰਜਨ ਇਤਿਹਾਸਕ ਤੌਰ 'ਤੇ ਆਵਾਜਾਈ ਦਾ ਕਿਹੜਾ ਸਾਜ਼ੋ-ਸਾਮਾਨ ਬਣਾਉਣ ਲਈ ਜਾਣਿਆ ਜਾਂਦਾ ਹੈ?",["ਰੇਲ ਇੰਜਣ","ਸਮੁੰਦਰੀ ਜਹਾਜ਼","ਸਿਰਫ਼ ਹਵਾਈ ਜਹਾਜ਼","ਸਿਰਫ਼ ਜੂਟ ਦੇ ਖੱਡੇ"],"ਪੱਛਮੀ ਬੰਗਾਲ ਦਾ ਚਿੱਤਰੰਜਨ ਰੇਲ ਇੰਜਣ ਬਣਾਉਣ ਦਾ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰ ਹੈ।"]},
"GEO-IND-001-CP007-Q057":{"h":"84414a2e","hi":["कथनों पर विचार कीजिए: I. रेल उपकरण पूँजीगत वस्तुएँ हैं। II. रेल इंजन का निर्माण अभियांत्रिकी उद्योग में आता है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","I और II दोनों सही हैं","केवल II सही है","न तो I और न ही II सही है"],"रेल उपकरण परिवहन की आधारभूत संरचना में काम आते हैं और अभियांत्रिकी विनिर्माण के अंतर्गत आते हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਰੇਲ ਦਾ ਸਾਜ਼ੋ-ਸਾਮਾਨ ਪੂੰਜੀਗਤ ਵਸਤਾਂ ਵਿੱਚ ਆਉਂਦਾ ਹੈ। II. ਰੇਲ ਇੰਜਣ ਬਣਾਉਣ ਦਾ ਕੰਮ ਇੰਜੀਨੀਅਰਿੰਗ ਉਦਯੋਗ ਵਿੱਚ ਆਉਂਦਾ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਰੇਲ ਦਾ ਸਾਜ਼ੋ-ਸਾਮਾਨ ਆਵਾਜਾਈ ਦੇ ਬੁਨਿਆਦੀ ਢਾਂਚੇ ਦੇ ਕੰਮ ਆਉਂਦਾ ਹੈ ਅਤੇ ਇੰਜੀਨੀਅਰਿੰਗ ਨਿਰਮਾਣ ਵਿੱਚ ਆਉਂਦਾ ਹੈ।"]},
"GEO-IND-001-CP007-Q058":{"h":"2c880e02","hi":["रेल उपकरण उद्योग के भूगोल में कौन-सा युग्म सही सुमेलित है?",["चित्तरंजन — केवल जूट","चित्तरंजन — पेट्रोलियम","चित्तरंजन — रेल इंजन","चित्तरंजन — सीमेंट"],"चित्तरंजन का रेल इंजन के विनिर्माण से ऐतिहासिक संबंध है।"],"pa":["ਰੇਲ ਸਾਜ਼ੋ-ਸਾਮਾਨ ਦੇ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਚਿੱਤਰੰਜਨ — ਸਿਰਫ਼ ਜੂਟ","ਚਿੱਤਰੰਜਨ — ਪੈਟਰੋਲੀਅਮ","ਚਿੱਤਰੰਜਨ — ਰੇਲ ਇੰਜਣ","ਚਿੱਤਰੰਜਨ — ਸੀਮਿੰਟ"],"ਚਿੱਤਰੰਜਨ ਦਾ ਰੇਲ ਇੰਜਣ ਬਣਾਉਣ ਨਾਲ ਇਤਿਹਾਸਕ ਸਬੰਧ ਹੈ।"]},
"GEO-IND-001-CP007-Q059":{"h":"16c6ade2","hi":["रेल उपकरण संयंत्रों को मज़बूत अभियांत्रिकी आपूर्ति शृंखलाओं की ज़रूरत क्यों होती है?",["वे गन्ने पर निर्भर हैं","उन्हें चाय के बागान चाहिए","वे धातु का उपयोग नहीं करते","वे जटिल धातु पुर्ज़े और मशीनरी इस्तेमाल करते हैं"],"रेल के चल वाहन बनाने में इस्पात, विद्युत प्रणालियाँ और परिशुद्ध पुर्ज़े इस्तेमाल होते हैं।"],"pa":["ਰੇਲ ਦਾ ਸਾਜ਼ੋ-ਸਾਮਾਨ ਬਣਾਉਣ ਵਾਲੇ ਪਲਾਂਟਾਂ ਨੂੰ ਮਜ਼ਬੂਤ ਇੰਜੀਨੀਅਰਿੰਗ ਸਪਲਾਈ ਲੜੀਆਂ ਕਿਉਂ ਚਾਹੀਦੀਆਂ ਹਨ?",["ਉਹ ਗੰਨੇ 'ਤੇ ਨਿਰਭਰ ਹਨ","ਉਨ੍ਹਾਂ ਨੂੰ ਚਾਹ ਦੇ ਬਾਗ਼ ਚਾਹੀਦੇ ਹਨ","ਉਹ ਧਾਤ ਨਹੀਂ ਵਰਤਦੇ","ਉਹ ਗੁੰਝਲਦਾਰ ਧਾਤੂ ਪੁਰਜ਼ੇ ਅਤੇ ਮਸ਼ੀਨਰੀ ਵਰਤਦੇ ਹਨ"],"ਰੇਲ ਇੰਜਣ ਤੇ ਡੱਬੇ ਬਣਾਉਣ ਲਈ ਸਟੀਲ, ਬਿਜਲਈ ਪ੍ਰਣਾਲੀਆਂ ਅਤੇ ਬਾਰੀਕੀ ਨਾਲ ਬਣੇ ਪੁਰਜ਼ੇ ਚਾਹੀਦੇ ਹਨ।"]},
"GEO-IND-001-CP007-Q060":{"h":"80f5668a","hi":["एक कारखाना रेल डिब्बे और रेल इंजन बनाता है। उसके लिए कौन-सी औद्योगिक श्रेणी सबसे उपयुक्त है?",["भारी परिवहन अभियांत्रिकी","खाद्य प्रसंस्करण","वस्त्र उद्योग","कृषि प्रसंस्करण"],"रेल के चल वाहन भारी अभियांत्रिकी के उत्पाद हैं।"],"pa":["ਇੱਕ ਕਾਰਖ਼ਾਨਾ ਰੇਲ ਦੇ ਡੱਬੇ ਅਤੇ ਇੰਜਣ ਬਣਾਉਂਦਾ ਹੈ। ਉਸ ਲਈ ਕਿਹੜੀ ਉਦਯੋਗਿਕ ਸ਼੍ਰੇਣੀ ਸਭ ਤੋਂ ਢੁੱਕਵੀਂ ਹੈ?",["ਭਾਰੀ ਆਵਾਜਾਈ ਇੰਜੀਨੀਅਰਿੰਗ","ਖ਼ੁਰਾਕੀ ਪ੍ਰੋਸੈਸਿੰਗ","ਕੱਪੜਾ ਉਦਯੋਗ","ਖੇਤੀ ਉਪਜ ਦੀ ਪ੍ਰੋਸੈਸਿੰਗ"],"ਰੇਲ ਦੇ ਡੱਬੇ ਤੇ ਇੰਜਣ ਭਾਰੀ ਇੰਜੀਨੀਅਰਿੰਗ ਦੇ ਉਤਪਾਦ ਹਨ।"]},
"GEO-IND-001-CP008-Q001":{"h":"014bdc1a","hi":["कई संश्लेषित रेशों और प्लास्टिक के लिए मूल कच्चा माल कौन-सा उद्योग देता है?",["चीनी उद्योग","जूट उद्योग","पेट्रोरसायन उद्योग","सीमेंट उद्योग"],"पेट्रोरसायनों से प्लास्टिक, संश्लेषित रेशों, रबर और कई रसायनों का कच्चा माल मिलता है।"],"pa":["ਕਈ ਬਣਾਵਟੀ ਰੇਸ਼ਿਆਂ ਅਤੇ ਪਲਾਸਟਿਕ ਲਈ ਬੁਨਿਆਦੀ ਕੱਚਾ ਮਾਲ ਕਿਹੜਾ ਉਦਯੋਗ ਦਿੰਦਾ ਹੈ?",["ਖੰਡ ਉਦਯੋਗ","ਜੂਟ ਉਦਯੋਗ","ਪੈਟਰੋ-ਰਸਾਇਣ ਉਦਯੋਗ","ਸੀਮਿੰਟ ਉਦਯੋਗ"],"ਪੈਟਰੋ-ਰਸਾਇਣਾਂ ਤੋਂ ਪਲਾਸਟਿਕ, ਬਣਾਵਟੀ ਰੇਸ਼ੇ, ਰਬੜ ਅਤੇ ਕਈ ਰਸਾਇਣ ਬਣਾਉਣ ਲਈ ਕੱਚਾ ਮਾਲ ਮਿਲਦਾ ਹੈ।"]},
"GEO-IND-001-CP008-Q002":{"h":"78d7254a","hi":["पेट्रोरसायन परिसर अक्सर तेल शोधनशालाओं के पास क्यों विकसित होते हैं?",["उन्हें जूट का रेशा चाहिए","वे केवल चूना पत्थर पर निर्भर हैं","उन्हें गन्ने की ज़रूरत है","शोधनशालाएँ हाइड्रोकार्बन कच्चा माल देती हैं"],"शोधनशालाओं से नैफ़्था और अन्य हाइड्रोकार्बन धाराएँ मिलती हैं, जिनका उपयोग पेट्रोरसायन संयंत्र करते हैं।"],"pa":["ਪੈਟਰੋ-ਰਸਾਇਣ ਕੰਪਲੈਕਸ ਅਕਸਰ ਤੇਲ ਸੋਧਣ ਵਾਲੀਆਂ ਰਿਫ਼ਾਇਨਰੀਆਂ ਕੋਲ ਕਿਉਂ ਵਿਕਸਿਤ ਹੁੰਦੇ ਹਨ?",["ਉਨ੍ਹਾਂ ਨੂੰ ਜੂਟ ਦਾ ਰੇਸ਼ਾ ਚਾਹੀਦਾ ਹੈ","ਉਹ ਸਿਰਫ਼ ਚੂਨਾ ਪੱਥਰ 'ਤੇ ਨਿਰਭਰ ਹਨ","ਉਨ੍ਹਾਂ ਨੂੰ ਗੰਨਾ ਚਾਹੀਦਾ ਹੈ","ਰਿਫ਼ਾਇਨਰੀਆਂ ਹਾਈਡ੍ਰੋਕਾਰਬਨ ਕੱਚਾ ਮਾਲ ਦਿੰਦੀਆਂ ਹਨ"],"ਪੈਟਰੋ-ਰਸਾਇਣ ਪਲਾਂਟਾਂ ਨੂੰ ਨੈਫ਼ਥਾ ਅਤੇ ਹੋਰ ਹਾਈਡ੍ਰੋਕਾਰਬਨ ਪਦਾਰਥ ਰਿਫ਼ਾਇਨਰੀਆਂ ਤੋਂ ਮਿਲਦੇ ਹਨ।"]},
"GEO-IND-001-CP008-Q003":{"h":"19cec5fc","hi":["कथनों पर विचार कीजिए: I. पेट्रोरसायन उद्योग हाइड्रोकार्बन कच्चा माल इस्तेमाल करता है। II. शोधनशालाएँ यह कच्चा माल दे सकती हैं। कौन-सा/से कथन सही है/हैं?",["I और II दोनों सही हैं","केवल I सही है","केवल II सही है","न तो I और न ही II सही है"],"दोनों कथन समझाते हैं कि तेल शोधन और पेट्रोरसायन उत्पादन का एकीकरण इतना आम क्यों है।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਪੈਟਰੋ-ਰਸਾਇਣ ਉਦਯੋਗ ਹਾਈਡ੍ਰੋਕਾਰਬਨ ਕੱਚਾ ਮਾਲ ਵਰਤਦਾ ਹੈ। II. ਰਿਫ਼ਾਇਨਰੀਆਂ ਇਹ ਕੱਚਾ ਮਾਲ ਦੇ ਸਕਦੀਆਂ ਹਨ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਦੋਵੇਂ ਕਥਨ ਦੱਸਦੇ ਹਨ ਕਿ ਤੇਲ ਦੀ ਸੋਧਾਈ ਅਤੇ ਪੈਟਰੋ-ਰਸਾਇਣ ਉਤਪਾਦਨ ਨੂੰ ਇਕੱਠੇ ਚਲਾਉਣਾ ਆਮ ਕਿਉਂ ਹੈ।"]},
"GEO-IND-001-CP008-Q004":{"h":"dbc83e60","hi":["पेट्रोरसायन उद्योग की अवस्थिति के संबंध में कौन-सा युग्म सही सुमेलित है?",["जूट मिल — नैफ़्था का स्रोत","तेल शोधनशाला — पेट्रोरसायन के कच्चे माल का स्रोत","चीनी मिल — एथिलीन का स्रोत","सीमेंट संयंत्र — बहुलक का कच्चा माल"],"पेट्रोरसायन परिसरों को उत्पादन के पहले चरण का कच्चा माल देने में शोधनशालाओं की महत्वपूर्ण भूमिका है।"],"pa":["ਪੈਟਰੋ-ਰਸਾਇਣ ਉਦਯੋਗ ਦੀ ਥਾਂ ਬਾਰੇ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਜੂਟ ਮਿੱਲ — ਨੈਫ਼ਥਾ ਦਾ ਸਰੋਤ","ਤੇਲ ਰਿਫ਼ਾਇਨਰੀ — ਪੈਟਰੋ-ਰਸਾਇਣਾਂ ਦੇ ਕੱਚੇ ਮਾਲ ਦਾ ਸਰੋਤ","ਖੰਡ ਮਿੱਲ — ਐਥੀਲੀਨ ਦਾ ਸਰੋਤ","ਸੀਮਿੰਟ ਪਲਾਂਟ — ਪਾਲੀਮਰ ਦਾ ਕੱਚਾ ਮਾਲ"],"ਪੈਟਰੋ-ਰਸਾਇਣ ਕੰਪਲੈਕਸਾਂ ਨੂੰ ਮੁੱਢਲੇ ਪੜਾਅ ਦਾ ਕੱਚਾ ਮਾਲ ਦੇਣ ਵਿੱਚ ਰਿਫ਼ਾਇਨਰੀਆਂ ਦੀ ਅਹਿਮ ਭੂਮਿਕਾ ਹੈ।"]},
"GEO-IND-001-CP008-Q005":{"h":"50434c77","hi":["कौन-सा उत्पाद आम तौर पर पेट्रोरसायन से मिले कच्चे माल से बनता है?",["कच्चा जूट","लौह अयस्क","संश्लेषित बहुलक","चूना पत्थर"],"बहुलक और कई संश्लेषित पदार्थ पेट्रोरसायन से मिले कच्चे माल से बनते हैं।"],"pa":["ਕਿਹੜਾ ਉਤਪਾਦ ਆਮ ਤੌਰ 'ਤੇ ਪੈਟਰੋ-ਰਸਾਇਣਾਂ ਤੋਂ ਮਿਲੇ ਕੱਚੇ ਮਾਲ ਨਾਲ ਬਣਦਾ ਹੈ?",["ਕੱਚਾ ਜੂਟ","ਕੱਚਾ ਲੋਹਾ","ਬਣਾਵਟੀ ਪਾਲੀਮਰ","ਚੂਨਾ ਪੱਥਰ"],"ਪਾਲੀਮਰ ਅਤੇ ਕਈ ਬਣਾਵਟੀ ਪਦਾਰਥ ਪੈਟਰੋ-ਰਸਾਇਣਾਂ ਤੋਂ ਮਿਲੇ ਕੱਚੇ ਮਾਲ ਨਾਲ ਬਣਦੇ ਹਨ।"]},
"GEO-IND-001-CP008-Q006":{"h":"952dd6f4","hi":["एक रासायनिक परिसर बड़ी तेल शोधनशाला और पत्तन के पास बनाया गया है। कच्चे माल और माल की आवाजाही के इन लाभों का उपयोग कौन-सा उद्योग करता है?",["जूट वस्त्र","चीनी","सीमेंट","पेट्रोरसायन"],"कच्चे माल की आपूर्ति और पत्तन पर माल की आवाजाही की सुविधाएँ पेट्रोरसायन उद्योग के विकास के लिए बहुत अनुकूल हैं।"],"pa":["ਇੱਕ ਰਸਾਇਣਕ ਕੰਪਲੈਕਸ ਵੱਡੀ ਰਿਫ਼ਾਇਨਰੀ ਅਤੇ ਬੰਦਰਗਾਹ ਕੋਲ ਬਣਿਆ ਹੈ। ਕਿਹੜਾ ਉਦਯੋਗ ਕੱਚੇ ਮਾਲ ਅਤੇ ਢੋਆ-ਢੁਆਈ ਦੇ ਇਨ੍ਹਾਂ ਲਾਭਾਂ ਦੀ ਵਰਤੋਂ ਕਰਦਾ ਹੈ?",["ਜੂਟ ਦੇ ਕੱਪੜੇ","ਖੰਡ","ਸੀਮਿੰਟ","ਪੈਟਰੋ-ਰਸਾਇਣ"],"ਕੱਚੇ ਮਾਲ ਦੀ ਸਪਲਾਈ ਅਤੇ ਬੰਦਰਗਾਹ 'ਤੇ ਮਾਲ ਢੋਣ ਦੀਆਂ ਸਹੂਲਤਾਂ ਪੈਟਰੋ-ਰਸਾਇਣ ਉਦਯੋਗ ਦੇ ਵਿਕਾਸ ਲਈ ਬਹੁਤ ਅਨੁਕੂਲ ਹਨ।"]},
"GEO-IND-001-CP008-Q007":{"h":"5351165a","hi":["पश्चिमी भारत का कौन-सा राज्य पेट्रोरसायन और तेल शोधन का प्रमुख क्षेत्र है?",["गुजरात","पंजाब","असम","केरल"],"गुजरात में प्रमुख तेल शोधनशालाएँ, पत्तन, रसायन उद्योग और पेट्रोरसायन परिसर हैं।"],"pa":["ਪੱਛਮੀ ਭਾਰਤ ਦਾ ਕਿਹੜਾ ਰਾਜ ਤੇਲ ਦੀ ਸੋਧਾਈ ਅਤੇ ਪੈਟਰੋ-ਰਸਾਇਣਾਂ ਦਾ ਪ੍ਰਮੁੱਖ ਖੇਤਰ ਹੈ?",["ਗੁਜਰਾਤ","ਪੰਜਾਬ","ਅਸਾਮ","ਕੇਰਲ"],"ਗੁਜਰਾਤ ਵਿੱਚ ਪ੍ਰਮੁੱਖ ਤੇਲ ਰਿਫ਼ਾਇਨਰੀਆਂ, ਬੰਦਰਗਾਹਾਂ, ਰਸਾਇਣ ਉਦਯੋਗ ਅਤੇ ਪੈਟਰੋ-ਰਸਾਇਣ ਕੰਪਲੈਕਸ ਹਨ।"]},
"GEO-IND-001-CP008-Q008":{"h":"ed6e60f3","hi":["गुजरात में पेट्रोरसायन उद्योग के विकास में कौन-सा कारक सहायक है?",["जूट के खेत","शोधनशालाएँ, पत्तन और हाइड्रोकार्बन संबंधी आधारभूत संरचना","चाय के बागान","केवल लौह अयस्क की खदानें"],"राज्य में कच्चे माल की उपलब्धता, पत्तन, पाइपलाइन और औद्योगिक बाज़ार एक साथ मिलते हैं।"],"pa":["ਗੁਜਰਾਤ ਵਿੱਚ ਪੈਟਰੋ-ਰਸਾਇਣ ਉਦਯੋਗ ਦੇ ਵਿਕਾਸ ਨੂੰ ਕਿਹੜਾ ਕਾਰਕ ਸਹਾਰਾ ਦਿੰਦਾ ਹੈ?",["ਜੂਟ ਦੇ ਖੇਤ","ਰਿਫ਼ਾਇਨਰੀਆਂ, ਬੰਦਰਗਾਹਾਂ ਅਤੇ ਹਾਈਡ੍ਰੋਕਾਰਬਨਾਂ ਲਈ ਬੁਨਿਆਦੀ ਢਾਂਚਾ","ਚਾਹ ਦੇ ਬਾਗ਼","ਸਿਰਫ਼ ਕੱਚੇ ਲੋਹੇ ਦੀਆਂ ਖਾਣਾਂ"],"ਰਾਜ ਵਿੱਚ ਕੱਚਾ ਮਾਲ, ਬੰਦਰਗਾਹਾਂ, ਪਾਈਪਲਾਈਨਾਂ ਅਤੇ ਉਦਯੋਗਿਕ ਬਾਜ਼ਾਰ ਇਕੱਠੇ ਮਿਲਦੇ ਹਨ।"]},
"GEO-IND-001-CP008-Q009":{"h":"989d7b9a","hi":["कथनों पर विचार कीजिए: I. गुजरात में तेल शोधन की बड़ी क्षमता है। II. पेट्रोरसायन उद्योगों को शोधनशालाओं से मिले कच्चे माल का लाभ होता है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","I और II दोनों सही हैं","न तो I और न ही II सही है"],"दोनों कथन बताते हैं कि गुजरात पेट्रोरसायन उद्योग का प्रमुख क्षेत्र क्यों है।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਗੁਜਰਾਤ ਵਿੱਚ ਤੇਲ ਸੋਧਣ ਦੀ ਵੱਡੀ ਸਮਰੱਥਾ ਹੈ। II. ਪੈਟਰੋ-ਰਸਾਇਣ ਉਦਯੋਗਾਂ ਨੂੰ ਰਿਫ਼ਾਇਨਰੀਆਂ ਤੋਂ ਮਿਲੇ ਕੱਚੇ ਮਾਲ ਦਾ ਲਾਭ ਹੁੰਦਾ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਦੋਵੇਂ ਕਥਨ ਦੱਸਦੇ ਹਨ ਕਿ ਗੁਜਰਾਤ ਪੈਟਰੋ-ਰਸਾਇਣ ਉਦਯੋਗ ਦਾ ਪ੍ਰਮੁੱਖ ਖੇਤਰ ਕਿਉਂ ਹੈ।"]},
"GEO-IND-001-CP008-Q010":{"h":"f8cf5c7a","hi":["पेट्रोरसायन उद्योग के भूगोल में कौन-सा युग्म सही सुमेलित है?",["गुजरात — केवल जूट की पट्टी","गुजरात — शोधनशालाओं का अभाव","गुजरात — केवल चीनी का क्षेत्र","गुजरात — तेल शोधन और पेट्रोरसायन क्षेत्र"],"गुजरात भारत के प्रमुख तेल शोधन और पेट्रोरसायन उत्पादक राज्यों में से एक है।"],"pa":["ਪੈਟਰੋ-ਰਸਾਇਣ ਉਦਯੋਗ ਦੇ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਗੁਜਰਾਤ — ਸਿਰਫ਼ ਜੂਟ ਦੀ ਪੱਟੀ","ਗੁਜਰਾਤ — ਰਿਫ਼ਾਇਨਰੀਆਂ ਦੀ ਅਣਹੋਂਦ","ਗੁਜਰਾਤ — ਸਿਰਫ਼ ਖੰਡ ਦਾ ਖੇਤਰ","ਗੁਜਰਾਤ — ਤੇਲ ਸੋਧਾਈ ਅਤੇ ਪੈਟਰੋ-ਰਸਾਇਣ ਖੇਤਰ"],"ਗੁਜਰਾਤ ਭਾਰਤ ਵਿੱਚ ਤੇਲ ਸੋਧਣ ਅਤੇ ਪੈਟਰੋ-ਰਸਾਇਣ ਬਣਾਉਣ ਵਾਲੇ ਪ੍ਰਮੁੱਖ ਰਾਜਾਂ ਵਿੱਚੋਂ ਇੱਕ ਹੈ।"]},
"GEO-IND-001-CP008-Q011":{"h":"b7da85a6","hi":["गुजरात के रसायन उद्योगों को तटीय अवस्थिति से क्यों लाभ मिलता है?",["पत्तनों से कच्चे माल और उत्पादों का बड़ी मात्रा में आयात-निर्यात संभव है","पत्तन गन्ना उगाते हैं","पत्तन लौह अयस्क बनाते हैं","पत्तन पाइपलाइन की पूरी तरह जगह लेते हैं"],"पत्तनों से बड़ी मात्रा में तरल और रासायनिक माल की कुशल ढुलाई हो सकती है।"],"pa":["ਗੁਜਰਾਤ ਦੇ ਰਸਾਇਣ ਉਦਯੋਗਾਂ ਨੂੰ ਤੱਟ 'ਤੇ ਹੋਣ ਦਾ ਕੀ ਲਾਭ ਹੈ?",["ਬੰਦਰਗਾਹਾਂ ਤੋਂ ਕੱਚੇ ਮਾਲ ਅਤੇ ਉਤਪਾਦਾਂ ਦਾ ਵੱਡੀ ਮਾਤਰਾ ਵਿੱਚ ਆਯਾਤ ਤੇ ਨਿਰਯਾਤ ਹੁੰਦਾ ਹੈ","ਬੰਦਰਗਾਹਾਂ ਗੰਨਾ ਉਗਾਉਂਦੀਆਂ ਹਨ","ਬੰਦਰਗਾਹਾਂ ਕੱਚਾ ਲੋਹਾ ਬਣਾਉਂਦੀਆਂ ਹਨ","ਬੰਦਰਗਾਹਾਂ ਪਾਈਪਲਾਈਨਾਂ ਦੀ ਪੂਰੀ ਤਰ੍ਹਾਂ ਥਾਂ ਲੈਂਦੀਆਂ ਹਨ"],"ਬੰਦਰਗਾਹਾਂ ਰਾਹੀਂ ਵੱਡੀ ਮਾਤਰਾ ਵਿੱਚ ਤਰਲ ਅਤੇ ਰਸਾਇਣਕ ਮਾਲ ਸੁਚੱਜੇ ਢੰਗ ਨਾਲ ਢੋਇਆ ਜਾ ਸਕਦਾ ਹੈ।"]},
"GEO-IND-001-CP008-Q012":{"h":"3eb3f9d0","hi":["गुजरात के उद्योगों की कौन-सी तुलना सही है?",["दोनों केवल जूट पर निर्भर हैं","पेट्रोरसायन उद्योग को शोधनशालाओं से और सीमेंट उद्योग को चूना पत्थर से लाभ मिलता है","दोनों में परिवहन इस्तेमाल नहीं होता","सीमेंट उद्योग नैफ़्था पर निर्भर है"],"दोनों उद्योगों के कच्चे माल और अवस्थिति के आधार अलग-अलग हैं।"],"pa":["ਗੁਜਰਾਤ ਦੇ ਉਦਯੋਗਾਂ ਦੀ ਕਿਹੜੀ ਤੁਲਨਾ ਸਹੀ ਹੈ?",["ਦੋਵੇਂ ਸਿਰਫ਼ ਜੂਟ 'ਤੇ ਨਿਰਭਰ ਹਨ","ਪੈਟਰੋ-ਰਸਾਇਣਾਂ ਨੂੰ ਰਿਫ਼ਾਇਨਰੀਆਂ ਦਾ ਅਤੇ ਸੀਮਿੰਟ ਨੂੰ ਚੂਨਾ ਪੱਥਰ ਦਾ ਲਾਭ ਹੁੰਦਾ ਹੈ","ਦੋਵੇਂ ਆਵਾਜਾਈ ਨਹੀਂ ਵਰਤਦੇ","ਸੀਮਿੰਟ ਉਦਯੋਗ ਨੈਫ਼ਥਾ 'ਤੇ ਨਿਰਭਰ ਹੈ"],"ਦੋਵਾਂ ਉਦਯੋਗਾਂ ਵਿੱਚ ਕੱਚੇ ਮਾਲ ਦੀ ਲੋੜ ਅਤੇ ਥਾਂ ਦੀ ਚੋਣ ਦੇ ਆਧਾਰ ਵੱਖੋ-ਵੱਖਰੇ ਹਨ।"]},
"GEO-IND-001-CP008-Q013":{"h":"7772105f","hi":["नाइट्रोजनयुक्त उर्वरक बनाने के लिए कौन-सा ईंधन महत्वपूर्ण कच्चा माल है?",["जूट","प्राकृतिक गैस","अभ्रक","केवल चूना पत्थर"],"प्राकृतिक गैस से बड़े पैमाने पर हाइड्रोजन बनाया जाता है। इससे अमोनिया बनता है, जो नाइट्रोजनयुक्त उर्वरकों की मुख्य उत्पादन सामग्री है।"],"pa":["ਨਾਈਟ੍ਰੋਜਨ ਵਾਲੀਆਂ ਖਾਦਾਂ ਬਣਾਉਣ ਲਈ ਕਿਹੜਾ ਬਾਲਣ ਅਹਿਮ ਕੱਚਾ ਮਾਲ ਹੈ?",["ਜੂਟ","ਕੁਦਰਤੀ ਗੈਸ","ਅਬਰਕ","ਸਿਰਫ਼ ਚੂਨਾ ਪੱਥਰ"],"ਕੁਦਰਤੀ ਗੈਸ ਤੋਂ ਹਾਈਡ੍ਰੋਜਨ ਵੱਡੇ ਪੱਧਰ 'ਤੇ ਬਣਾਇਆ ਜਾਂਦਾ ਹੈ। ਇਸ ਨਾਲ ਅਮੋਨੀਆ ਬਣਦਾ ਹੈ, ਜੋ ਨਾਈਟ੍ਰੋਜਨ ਵਾਲੀਆਂ ਖਾਦਾਂ ਦੀ ਮੁੱਖ ਸਮੱਗਰੀ ਹੈ।"]},
"GEO-IND-001-CP008-Q014":{"h":"0c3d03af","hi":["नाइट्रोजनयुक्त उर्वरक उत्पादन में कौन-सा मध्यवर्ती रसायन मुख्य भूमिका निभाता है?",["क्लिंकर","कच्चा लोहा","अमोनिया","ऐलुमिना"],"अमोनिया एक मूल रसायन है, जिससे यूरिया और दूसरे नाइट्रोजनयुक्त उर्वरक बनाए जाते हैं।"],"pa":["ਨਾਈਟ੍ਰੋਜਨ ਵਾਲੀਆਂ ਖਾਦਾਂ ਬਣਾਉਣ ਵਿੱਚ ਕਿਹੜਾ ਵਿਚਕਾਰਲਾ ਰਸਾਇਣ ਮੁੱਖ ਭੂਮਿਕਾ ਨਿਭਾਉਂਦਾ ਹੈ?",["ਕਲਿੰਕਰ","ਪਿਗ ਆਇਰਨ","ਅਮੋਨੀਆ","ਐਲੂਮੀਨਾ"],"ਅਮੋਨੀਆ ਇੱਕ ਬੁਨਿਆਦੀ ਰਸਾਇਣ ਹੈ ਜਿਸ ਤੋਂ ਯੂਰੀਆ ਅਤੇ ਹੋਰ ਨਾਈਟ੍ਰੋਜਨ ਵਾਲੀਆਂ ਖਾਦਾਂ ਬਣਦੀਆਂ ਹਨ।"]},
"GEO-IND-001-CP008-Q015":{"h":"569bc9e3","hi":["कथनों पर विचार कीजिए: I. प्राकृतिक गैस उर्वरक के कच्चे माल के तौर पर इस्तेमाल होती है। II. नाइट्रोजनयुक्त उर्वरकों के लिए अमोनिया महत्वपूर्ण है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","न तो I और न ही II सही है","I और II दोनों सही हैं"],"दोनों नाइट्रोजनयुक्त उर्वरकों की उत्पादन शृंखला के मुख्य हिस्से हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਕੁਦਰਤੀ ਗੈਸ ਖਾਦਾਂ ਦੇ ਕੱਚੇ ਮਾਲ ਵਜੋਂ ਵਰਤੀ ਜਾਂਦੀ ਹੈ। II. ਨਾਈਟ੍ਰੋਜਨ ਵਾਲੀਆਂ ਖਾਦਾਂ ਲਈ ਅਮੋਨੀਆ ਅਹਿਮ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ"],"ਦੋਵੇਂ ਨਾਈਟ੍ਰੋਜਨ ਵਾਲੀਆਂ ਖਾਦਾਂ ਦੀ ਉਤਪਾਦਨ ਲੜੀ ਦੇ ਮੁੱਖ ਹਿੱਸੇ ਹਨ।"]},
"GEO-IND-001-CP008-Q016":{"h":"b20bb070","hi":["नाइट्रोजनयुक्त उर्वरक उत्पादन का सही क्रम कौन-सा है?",["प्राकृतिक गैस → अमोनिया → यूरिया","लौह अयस्क → अमोनिया → यूरिया","जूट → अमोनिया → इस्पात","चूना पत्थर → यूरिया → सीमेंट"],"प्राकृतिक गैस से अमोनिया के लिए हाइड्रोजन मिलता है। फिर अमोनिया से यूरिया बनाया जाता है।"],"pa":["ਨਾਈਟ੍ਰੋਜਨ ਵਾਲੀਆਂ ਖਾਦਾਂ ਬਣਾਉਣ ਦੀ ਸਹੀ ਲੜੀ ਕਿਹੜੀ ਹੈ?",["ਕੁਦਰਤੀ ਗੈਸ → ਅਮੋਨੀਆ → ਯੂਰੀਆ","ਕੱਚਾ ਲੋਹਾ → ਅਮੋਨੀਆ → ਯੂਰੀਆ","ਜੂਟ → ਅਮੋਨੀਆ → ਸਟੀਲ","ਚੂਨਾ ਪੱਥਰ → ਯੂਰੀਆ → ਸੀਮਿੰਟ"],"ਅਮੋਨੀਆ ਬਣਾਉਣ ਲਈ ਹਾਈਡ੍ਰੋਜਨ ਕੁਦਰਤੀ ਗੈਸ ਤੋਂ ਮਿਲਦਾ ਹੈ। ਫਿਰ ਅਮੋਨੀਆ ਤੋਂ ਯੂਰੀਆ ਬਣਾਇਆ ਜਾਂਦਾ ਹੈ।"]},
"GEO-IND-001-CP008-Q017":{"h":"fdd8715c","hi":["उर्वरक उद्योग के संबंध में कौन-सा युग्म सही सुमेलित है?",["जूट — अमोनिया का कच्चा माल","प्राकृतिक गैस — अमोनिया का कच्चा माल","बॉक्साइट — यूरिया का कच्चा माल","अभ्रक — उर्वरक की गैस"],"प्राकृतिक गैस अमोनिया आधारित उर्वरक उत्पादन का प्रमुख कच्चा माल है।"],"pa":["ਖਾਦ ਉਦਯੋਗ ਬਾਰੇ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਜੂਟ — ਅਮੋਨੀਆ ਦਾ ਕੱਚਾ ਮਾਲ","ਕੁਦਰਤੀ ਗੈਸ — ਅਮੋਨੀਆ ਦਾ ਕੱਚਾ ਮਾਲ","ਬਾਕਸਾਈਟ — ਯੂਰੀਆ ਦਾ ਕੱਚਾ ਮਾਲ","ਅਬਰਕ — ਖਾਦ ਦੀ ਗੈਸ"],"ਅਮੋਨੀਆ ਤੋਂ ਬਣਨ ਵਾਲੀਆਂ ਖਾਦਾਂ ਲਈ ਕੁਦਰਤੀ ਗੈਸ ਪ੍ਰਮੁੱਖ ਕੱਚਾ ਮਾਲ ਹੈ।"]},
"GEO-IND-001-CP008-Q018":{"h":"0a79774f","hi":["एक उर्वरक संयंत्र बड़ी गैस पाइपलाइन के पास है। उसे अवस्थिति के किस कारक का लाभ मिलता है?",["जूट की खेती","लौह अयस्क की श्रेणी","कच्चे माल तक पहुँच","ज्वारीय ऊर्जा"],"पाइपलाइन की गैस से उर्वरक संयंत्रों को कच्चे माल और ऊर्जा की भरोसेमंद आपूर्ति मिल सकती है।"],"pa":["ਇੱਕ ਖਾਦ ਪਲਾਂਟ ਵੱਡੀ ਗੈਸ ਪਾਈਪਲਾਈਨ ਨੇੜੇ ਹੈ। ਉਸ ਨੂੰ ਥਾਂ ਦੇ ਕਿਹੜੇ ਕਾਰਕ ਦਾ ਲਾਭ ਮਿਲਦਾ ਹੈ?",["ਜੂਟ ਦੀ ਖੇਤੀ","ਕੱਚੇ ਲੋਹੇ ਦਾ ਦਰਜਾ","ਕੱਚੇ ਮਾਲ ਤੱਕ ਪਹੁੰਚ","ਜਵਾਰ-ਭਾਟੇ ਦੀ ਊਰਜਾ"],"ਪਾਈਪਲਾਈਨ ਦੀ ਗੈਸ ਖਾਦ ਪਲਾਂਟਾਂ ਨੂੰ ਕੱਚੇ ਮਾਲ ਅਤੇ ਊਰਜਾ ਦੀ ਭਰੋਸੇਯੋਗ ਸਪਲਾਈ ਦੇ ਸਕਦੀ ਹੈ।"]},
"GEO-IND-001-CP008-Q019":{"h":"a7f09ab7","hi":["फ़ॉस्फ़ेटयुक्त उर्वरकों के लिए कौन-सा खनिज प्रमुख कच्चा माल है?",["अभ्रक","क्रोमाइट","बॉक्साइट","शैल फ़ॉस्फ़ेट"],"उर्वरक उत्पादन के लिए फ़ॉस्फ़ोरस का मुख्य खनिज स्रोत शैल फ़ॉस्फ़ेट है।"],"pa":["ਫ਼ਾਸਫ਼ੇਟ ਵਾਲੀਆਂ ਖਾਦਾਂ ਲਈ ਮੁੱਖ ਕੱਚਾ ਮਾਲ ਕਿਹੜਾ ਖਣਿਜ ਹੈ?",["ਅਬਰਕ","ਕ੍ਰੋਮਾਈਟ","ਬਾਕਸਾਈਟ","ਚੱਟਾਨੀ ਫ਼ਾਸਫ਼ੇਟ"],"ਖਾਦਾਂ ਬਣਾਉਣ ਲਈ ਫ਼ਾਸਫ਼ੋਰਸ ਦਾ ਮੁੱਖ ਖਣਿਜ ਸਰੋਤ ਚੱਟਾਨੀ ਫ਼ਾਸਫ਼ੇਟ ਹੈ।"]},
"GEO-IND-001-CP008-Q020":{"h":"2673bdcd","hi":["फ़ॉस्फ़ेटयुक्त उर्वरक बनाने में आम तौर पर कौन-सा औद्योगिक अम्ल इस्तेमाल होता है?",["सल्फ़्यूरिक अम्ल","केवल कार्बोनिक अम्ल","केवल ऐसीटिक अम्ल","केवल हाइड्रोक्लोरिक अम्ल"],"फ़ॉस्फ़ेट शैल का प्रसंस्करण कर फ़ॉस्फ़ेटयुक्त उर्वरक बनाने में सल्फ़्यूरिक अम्ल का व्यापक उपयोग होता है।"],"pa":["ਫ਼ਾਸਫ਼ੇਟ ਵਾਲੀਆਂ ਖਾਦਾਂ ਬਣਾਉਣ ਲਈ ਆਮ ਤੌਰ 'ਤੇ ਕਿਹੜਾ ਉਦਯੋਗਿਕ ਤੇਜ਼ਾਬ ਵਰਤਿਆ ਜਾਂਦਾ ਹੈ?",["ਸਲਫ਼ਿਊਰਿਕ ਤੇਜ਼ਾਬ","ਸਿਰਫ਼ ਕਾਰਬੋਨਿਕ ਤੇਜ਼ਾਬ","ਸਿਰਫ਼ ਐਸੀਟਿਕ ਤੇਜ਼ਾਬ","ਸਿਰਫ਼ ਹਾਈਡ੍ਰੋਕਲੋਰਿਕ ਤੇਜ਼ਾਬ"],"ਫ਼ਾਸਫ਼ੇਟ ਚੱਟਾਨ ਤੋਂ ਫ਼ਾਸਫ਼ੇਟ ਵਾਲੀਆਂ ਖਾਦਾਂ ਬਣਾਉਣ ਲਈ ਸਲਫ਼ਿਊਰਿਕ ਤੇਜ਼ਾਬ ਵੱਡੇ ਪੱਧਰ 'ਤੇ ਵਰਤਿਆ ਜਾਂਦਾ ਹੈ।"]},
"GEO-IND-001-CP008-Q021":{"h":"289b53c6","hi":["कथनों पर विचार कीजिए: I. शैल फ़ॉस्फ़ेट से फ़ॉस्फ़ोरस मिलता है। II. फ़ॉस्फ़ेटयुक्त उर्वरकों के प्रसंस्करण में सल्फ़्यूरिक अम्ल महत्वपूर्ण है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","I और II दोनों सही हैं","केवल II सही है","न तो I और न ही II सही है"],"ये दोनों सामग्रियाँ फ़ॉस्फ़ेटयुक्त उर्वरक बनाने के लिए महत्वपूर्ण हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਚੱਟਾਨੀ ਫ਼ਾਸਫ਼ੇਟ ਤੋਂ ਫ਼ਾਸਫ਼ੋਰਸ ਮਿਲਦਾ ਹੈ। II. ਫ਼ਾਸਫ਼ੇਟ ਵਾਲੀਆਂ ਖਾਦਾਂ ਦੀ ਪ੍ਰੋਸੈਸਿੰਗ ਵਿੱਚ ਸਲਫ਼ਿਊਰਿਕ ਤੇਜ਼ਾਬ ਅਹਿਮ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਇਹ ਦੋਵੇਂ ਸਮੱਗਰੀਆਂ ਫ਼ਾਸਫ਼ੇਟ ਵਾਲੀਆਂ ਖਾਦਾਂ ਬਣਾਉਣ ਲਈ ਅਹਿਮ ਹਨ।"]},
"GEO-IND-001-CP008-Q022":{"h":"8432ade1","hi":["उर्वरकों के कच्चे माल के संबंध में कौन-सा युग्म सही सुमेलित है?",["शैल फ़ॉस्फ़ेट — जूट का रेशा","जिप्सम — नाइट्रोजन गैस का कच्चा माल","शैल फ़ॉस्फ़ेट — फ़ॉस्फ़ेटयुक्त उर्वरक","बॉक्साइट — यूरिया"],"शैल फ़ॉस्फ़ेट फ़ॉस्फ़ोरस देने वाला मुख्य खनिज कच्चा माल है।"],"pa":["ਖਾਦਾਂ ਦੇ ਕੱਚੇ ਮਾਲ ਬਾਰੇ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਚੱਟਾਨੀ ਫ਼ਾਸਫ਼ੇਟ — ਜੂਟ ਦਾ ਰੇਸ਼ਾ","ਜਿਪਸਮ — ਨਾਈਟ੍ਰੋਜਨ ਗੈਸ ਦਾ ਕੱਚਾ ਮਾਲ","ਚੱਟਾਨੀ ਫ਼ਾਸਫ਼ੇਟ — ਫ਼ਾਸਫ਼ੇਟ ਵਾਲੀ ਖਾਦ","ਬਾਕਸਾਈਟ — ਯੂਰੀਆ"],"ਚੱਟਾਨੀ ਫ਼ਾਸਫ਼ੇਟ ਫ਼ਾਸਫ਼ੋਰਸ ਵਾਲਾ ਮੁੱਖ ਖਣਿਜ ਕੱਚਾ ਮਾਲ ਹੈ।"]},
"GEO-IND-001-CP008-Q023":{"h":"392a64ca","hi":["फ़ॉस्फ़ेटयुक्त उर्वरक संयंत्र पत्तनों के पास क्यों विकसित हो सकते हैं?",["पत्तन गन्ने की आपूर्ति करते हैं","पत्तन कोयला बनाते हैं","पत्तन परिवहन की ज़रूरत समाप्त करते हैं","आयातित फ़ॉस्फ़ेट शैल और गंधक की बड़ी खेपें सँभाली जा सकती हैं"],"बड़ी मात्रा में आयात करने की सुविधा फ़ॉस्फ़ेटयुक्त उर्वरक संयंत्रों के लिए तटीय अवस्थिति को लाभदायक बना सकती है।"],"pa":["ਫ਼ਾਸਫ਼ੇਟ ਵਾਲੀਆਂ ਖਾਦਾਂ ਦੇ ਪਲਾਂਟ ਬੰਦਰਗਾਹਾਂ ਨੇੜੇ ਕਿਉਂ ਵਿਕਸਿਤ ਹੋ ਸਕਦੇ ਹਨ?",["ਬੰਦਰਗਾਹਾਂ ਗੰਨੇ ਦੀ ਸਪਲਾਈ ਕਰਦੀਆਂ ਹਨ","ਬੰਦਰਗਾਹਾਂ ਕੋਲਾ ਬਣਾਉਂਦੀਆਂ ਹਨ","ਬੰਦਰਗਾਹਾਂ ਢੋਆ-ਢੁਆਈ ਦੀ ਲੋੜ ਖ਼ਤਮ ਕਰਦੀਆਂ ਹਨ","ਬਾਹਰੋਂ ਮੰਗਵਾਈ ਫ਼ਾਸਫ਼ੇਟ ਚੱਟਾਨ ਅਤੇ ਗੰਧਕ ਦੀਆਂ ਵੱਡੀਆਂ ਖੇਪਾਂ ਸੰਭਾਲੀਆਂ ਜਾ ਸਕਦੀਆਂ ਹਨ"],"ਵੱਡੀ ਮਾਤਰਾ ਵਿੱਚ ਆਯਾਤ ਕਰਨ ਦੀ ਸਹੂਲਤ ਫ਼ਾਸਫ਼ੇਟ ਵਾਲੀਆਂ ਖਾਦਾਂ ਦੇ ਪਲਾਂਟਾਂ ਲਈ ਤੱਟੀ ਥਾਵਾਂ ਨੂੰ ਲਾਹੇਵੰਦ ਬਣਾ ਸਕਦੀ ਹੈ।"]},
"GEO-IND-001-CP008-Q024":{"h":"a52acaef","hi":["एक उर्वरक परिसर पत्तन से फ़ॉस्फ़ेट शैल का आयात करता है। यह उर्वरकों के किस वर्ग की ओर संकेत करता है?",["फ़ॉस्फ़ेटयुक्त उर्वरक","केवल नाइट्रोजनयुक्त उर्वरक","जूट उत्पाद","सीमेंट"],"फ़ॉस्फ़ेट शैल सीधे फ़ॉस्फ़ेटयुक्त उर्वरकों के उत्पादन की ओर संकेत करती है।"],"pa":["ਇੱਕ ਖਾਦ ਕੰਪਲੈਕਸ ਬੰਦਰਗਾਹ ਰਾਹੀਂ ਫ਼ਾਸਫ਼ੇਟ ਚੱਟਾਨ ਮੰਗਵਾਉਂਦਾ ਹੈ। ਇਹ ਕਿਸ ਤਰ੍ਹਾਂ ਦੀਆਂ ਖਾਦਾਂ ਵੱਲ ਇਸ਼ਾਰਾ ਕਰਦਾ ਹੈ?",["ਫ਼ਾਸਫ਼ੇਟ ਵਾਲੀਆਂ ਖਾਦਾਂ","ਸਿਰਫ਼ ਨਾਈਟ੍ਰੋਜਨ ਵਾਲੀਆਂ ਖਾਦਾਂ","ਜੂਟ ਦੇ ਉਤਪਾਦ","ਸੀਮਿੰਟ"],"ਫ਼ਾਸਫ਼ੇਟ ਚੱਟਾਨ ਸਿੱਧੇ ਤੌਰ 'ਤੇ ਫ਼ਾਸਫ਼ੇਟ ਵਾਲੀਆਂ ਖਾਦਾਂ ਦੇ ਉਤਪਾਦਨ ਵੱਲ ਇਸ਼ਾਰਾ ਕਰਦੀ ਹੈ।"]},
"GEO-IND-001-CP008-Q025":{"h":"e61c668f","hi":["रसायन उद्योग अक्सर एक ही क्षेत्र में क्यों इकट्ठे होते हैं?",["उन्हें आधारभूत संरचना नहीं चाहिए","वे केवल खेतों पर निर्भर हैं","वे परिवहन संपर्कों से बचते हैं","वे कच्चा माल, आवश्यक सेवाएँ, पाइपलाइन और उपोत्पाद साझा कर सकते हैं"],"रासायनिक परिसरों को सामग्री के एकीकृत प्रवाह, साझा सेवाओं और माल की आवाजाही की सुविधाओं का लाभ मिलता है।"],"pa":["ਰਸਾਇਣ ਉਦਯੋਗ ਅਕਸਰ ਇੱਕੋ ਥਾਂ ਕਿਉਂ ਇਕੱਠੇ ਹੁੰਦੇ ਹਨ?",["ਉਨ੍ਹਾਂ ਨੂੰ ਬੁਨਿਆਦੀ ਢਾਂਚੇ ਦੀ ਲੋੜ ਨਹੀਂ ਹੁੰਦੀ","ਉਹ ਸਿਰਫ਼ ਖੇਤਾਂ 'ਤੇ ਨਿਰਭਰ ਹਨ","ਉਹ ਆਵਾਜਾਈ ਦੇ ਸੰਪਰਕਾਂ ਤੋਂ ਬਚਦੇ ਹਨ","ਉਹ ਕੱਚਾ ਮਾਲ, ਸਹੂਲਤਾਂ, ਪਾਈਪਲਾਈਨਾਂ ਅਤੇ ਉਪ-ਉਤਪਾਦ ਸਾਂਝੇ ਕਰ ਸਕਦੇ ਹਨ"],"ਰਸਾਇਣਕ ਕੰਪਲੈਕਸਾਂ ਨੂੰ ਸਮੱਗਰੀ ਦੀ ਆਪਸੀ ਸਪਲਾਈ, ਸਾਂਝੀਆਂ ਸਹੂਲਤਾਂ ਅਤੇ ਢੋਆ-ਢੁਆਈ ਦੇ ਪ੍ਰਬੰਧਾਂ ਦਾ ਲਾਭ ਹੁੰਦਾ ਹੈ।"]},
"GEO-IND-001-CP008-Q026":{"h":"f270c594","hi":["बड़े रासायनिक परिसर के लिए कौन-सा कारक विशेष रूप से अनुकूल है?",["भरोसेमंद बिजली, पानी और परिवहन","केवल अधिक वर्षा","केवल उपजाऊ मिट्टी","केवल पर्यटन"],"रसायन विनिर्माण में अक्सर बड़े पैमाने पर बिजली-पानी जैसी सेवाओं और बड़ी खेपों की ढुलाई की आवश्यकता होती है।"],"pa":["ਵੱਡੇ ਰਸਾਇਣਕ ਕੰਪਲੈਕਸ ਲਈ ਕਿਹੜਾ ਕਾਰਕ ਖ਼ਾਸ ਤੌਰ 'ਤੇ ਅਨੁਕੂਲ ਹੈ?",["ਭਰੋਸੇਯੋਗ ਬਿਜਲੀ, ਪਾਣੀ ਅਤੇ ਆਵਾਜਾਈ","ਸਿਰਫ਼ ਵੱਧ ਵਰਖਾ","ਸਿਰਫ਼ ਉਪਜਾਊ ਮਿੱਟੀ","ਸਿਰਫ਼ ਸੈਰ-ਸਪਾਟਾ"],"ਰਸਾਇਣ ਬਣਾਉਣ ਲਈ ਅਕਸਰ ਵੱਡੇ ਪੱਧਰ 'ਤੇ ਬਿਜਲੀ-ਪਾਣੀ ਵਰਗੀਆਂ ਸਹੂਲਤਾਂ ਅਤੇ ਵੱਡੀਆਂ ਖੇਪਾਂ ਢੋਣ ਦਾ ਪ੍ਰਬੰਧ ਚਾਹੀਦਾ ਹੈ।"]},
"GEO-IND-001-CP008-Q027":{"h":"33474aba","hi":["कथनों पर विचार कीजिए: I. रसायन संयंत्र मध्यवर्ती उत्पादों का आदान-प्रदान कर सकते हैं। II. साझा आधारभूत संरचना लागत घटा सकती है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","I और II दोनों सही हैं","केवल II सही है","न तो I और न ही II सही है"],"औद्योगिक एकीकरण रसायन उद्योग के संकुलों का एक प्रमुख लाभ है।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਰਸਾਇਣਕ ਪਲਾਂਟ ਵਿਚਕਾਰਲੇ ਉਤਪਾਦਾਂ ਦਾ ਆਦਾਨ-ਪ੍ਰਦਾਨ ਕਰ ਸਕਦੇ ਹਨ। II. ਸਾਂਝਾ ਬੁਨਿਆਦੀ ਢਾਂਚਾ ਖ਼ਰਚ ਘਟਾ ਸਕਦਾ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਉਦਯੋਗਾਂ ਦਾ ਆਪਸ ਵਿੱਚ ਜੁੜ ਕੇ ਕੰਮ ਕਰਨਾ ਰਸਾਇਣ ਉਦਯੋਗਾਂ ਦੇ ਗੁੱਛਾਂ ਦਾ ਇੱਕ ਵੱਡਾ ਲਾਭ ਹੈ।"]},
"GEO-IND-001-CP008-Q028":{"h":"10df4dfb","hi":["रसायन उद्योग के संकुलों में कौन-सा युग्म सही सुमेलित है?",["पाइपलाइन तंत्र — जूट की खेती","शीत भंडारण — नैफ़्था उत्पादन","पाइपलाइन तंत्र — कच्चे माल की ढुलाई","चूना पत्थर की खदान — बहुलक का कच्चा माल"],"पाइपलाइन से रासायनिक इकाइयों के बीच गैसों और तरल पदार्थों को कुशलता से पहुँचाया जा सकता है।"],"pa":["ਰਸਾਇਣ ਉਦਯੋਗਾਂ ਦੇ ਗੁੱਛਾਂ ਬਾਰੇ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਪਾਈਪਲਾਈਨਾਂ ਦਾ ਜਾਲ — ਜੂਟ ਦੀ ਖੇਤੀ","ਠੰਢਾ ਭੰਡਾਰਨ — ਨੈਫ਼ਥਾ ਉਤਪਾਦਨ","ਪਾਈਪਲਾਈਨਾਂ ਦਾ ਜਾਲ — ਕੱਚੇ ਮਾਲ ਦੀ ਢੋਆ-ਢੁਆਈ","ਚੂਨਾ ਪੱਥਰ ਦੀ ਖਾਣ — ਪਾਲੀਮਰ ਦਾ ਕੱਚਾ ਮਾਲ"],"ਰਸਾਇਣਕ ਇਕਾਈਆਂ ਵਿਚਕਾਰ ਗੈਸਾਂ ਅਤੇ ਤਰਲ ਪਦਾਰਥ ਭੇਜਣ ਲਈ ਪਾਈਪਲਾਈਨਾਂ ਸੁਚੱਜਾ ਸਾਧਨ ਹਨ।"]},
"GEO-IND-001-CP008-Q029":{"h":"113bb0bb","hi":["रसायन और पेट्रोरसायन उद्योगों के लिए पत्तन क्यों उपयोगी हैं?",["वे अपने आप लौह अयस्क की आपूर्ति करते हैं","वे सभी पाइपलाइनों की जगह लेते हैं","वे सीधे उर्वरक बनाते हैं","वे तरल माल की बड़ी खेपें और आयातित कच्चा माल सँभालते हैं"],"पत्तनों से वैश्विक कच्चे माल और निर्यात बाज़ारों तक पहुँच बेहतर होती है।"],"pa":["ਰਸਾਇਣ ਅਤੇ ਪੈਟਰੋ-ਰਸਾਇਣ ਉਦਯੋਗਾਂ ਲਈ ਬੰਦਰਗਾਹਾਂ ਕਿਉਂ ਲਾਹੇਵੰਦ ਹਨ?",["ਉਹ ਆਪਣੇ ਆਪ ਕੱਚਾ ਲੋਹਾ ਦਿੰਦੀਆਂ ਹਨ","ਉਹ ਸਾਰੀਆਂ ਪਾਈਪਲਾਈਨਾਂ ਦੀ ਥਾਂ ਲੈਂਦੀਆਂ ਹਨ","ਉਹ ਸਿੱਧੀਆਂ ਖਾਦਾਂ ਬਣਾਉਂਦੀਆਂ ਹਨ","ਉਹ ਤਰਲ ਮਾਲ ਦੀਆਂ ਵੱਡੀਆਂ ਖੇਪਾਂ ਅਤੇ ਆਯਾਤ ਕੀਤਾ ਕੱਚਾ ਮਾਲ ਸੰਭਾਲਦੀਆਂ ਹਨ"],"ਬੰਦਰਗਾਹਾਂ ਰਾਹੀਂ ਦੁਨੀਆ ਭਰ ਦੇ ਕੱਚੇ ਮਾਲ ਅਤੇ ਨਿਰਯਾਤ ਬਾਜ਼ਾਰਾਂ ਤੱਕ ਪਹੁੰਚ ਵਧਦੀ ਹੈ।"]},
"GEO-IND-001-CP008-Q030":{"h":"83f75bf7","hi":["एक तटीय औद्योगिक क्षेत्र में तेल शोधनशालाएँ, रसायन संयंत्र और भंडारण केंद्र हैं। यह किस प्रकार की व्यवस्था है?",["एकीकृत रसायन और पेट्रोरसायन संकुल","कृषि मंडी","जूट उत्पादक पट्टी","खनन शिविर"],"आपस में जुड़ी प्रसंस्करण इकाइयों का एक ही जगह होना एकीकृत रासायनिक संकुल की विशेषता है।"],"pa":["ਇੱਕ ਤੱਟੀ ਉਦਯੋਗਿਕ ਖੇਤਰ ਵਿੱਚ ਰਿਫ਼ਾਇਨਰੀਆਂ, ਰਸਾਇਣਕ ਪਲਾਂਟ ਅਤੇ ਭੰਡਾਰਨ ਕੇਂਦਰ ਹਨ। ਇਹ ਕਿਸ ਕਿਸਮ ਦੀ ਬਣਤਰ ਹੈ?",["ਏਕੀਕ੍ਰਿਤ ਰਸਾਇਣ ਅਤੇ ਪੈਟਰੋ-ਰਸਾਇਣ ਗੁੱਛ","ਖੇਤੀ ਮੰਡੀ","ਜੂਟ ਉਗਾਉਣ ਵਾਲੀ ਪੱਟੀ","ਖੁਦਾਈ ਕੈਂਪ"],"ਆਪਸ ਵਿੱਚ ਜੁੜੀਆਂ ਪ੍ਰੋਸੈਸਿੰਗ ਇਕਾਈਆਂ ਦਾ ਇੱਕੋ ਥਾਂ ਹੋਣਾ ਏਕੀਕ੍ਰਿਤ ਰਸਾਇਣਕ ਗੁੱਛ ਦੀ ਵਿਸ਼ੇਸ਼ਤਾ ਹੈ।"]},
"GEO-IND-001-CP008-Q031":{"h":"0f991fa7","hi":["कृषि बाज़ारों तक पहुँच उर्वरक संयंत्रों के लिए क्यों महत्वपूर्ण है?",["उर्वरक भारी कृषि सामग्री हैं, जिनका किसान व्यापक उपयोग करते हैं","उर्वरक तैयार माल के रूप में खदानों से निकलते हैं","उन्हें केवल पत्तन इस्तेमाल करते हैं","उनकी ढुलाई में कोई लागत नहीं आती"],"बड़े कृषि बाज़ारों में अच्छी माँग होती है और उनका असर वितरण के तंत्र पर पड़ता है।"],"pa":["ਖਾਦ ਪਲਾਂਟਾਂ ਲਈ ਖੇਤੀ ਬਾਜ਼ਾਰਾਂ ਤੱਕ ਪਹੁੰਚ ਕਿਉਂ ਅਹਿਮ ਹੈ?",["ਖਾਦਾਂ ਭਾਰੀ ਖੇਤੀ ਸਮੱਗਰੀ ਹਨ, ਜਿਨ੍ਹਾਂ ਨੂੰ ਕਿਸਾਨ ਵੱਡੇ ਪੱਧਰ 'ਤੇ ਵਰਤਦੇ ਹਨ","ਖਾਦਾਂ ਖਾਣਾਂ ਤੋਂ ਤਿਆਰ ਮਾਲ ਵਜੋਂ ਨਿਕਲਦੀਆਂ ਹਨ","ਇਨ੍ਹਾਂ ਦੀ ਵਰਤੋਂ ਸਿਰਫ਼ ਬੰਦਰਗਾਹਾਂ ਕਰਦੀਆਂ ਹਨ","ਇਨ੍ਹਾਂ ਦੀ ਢੋਆ-ਢੁਆਈ ਦਾ ਕੋਈ ਖ਼ਰਚ ਨਹੀਂ ਹੈ"],"ਵੱਡੇ ਖੇਤੀ ਬਾਜ਼ਾਰਾਂ ਵਿੱਚ ਖਾਦ ਦੀ ਕਾਫ਼ੀ ਮੰਗ ਹੁੰਦੀ ਹੈ ਅਤੇ ਇਸ ਦਾ ਅਸਰ ਵੰਡ ਦੇ ਜਾਲਾਂ 'ਤੇ ਪੈਂਦਾ ਹੈ।"]},
"GEO-IND-001-CP008-Q032":{"h":"4f7c58df","hi":["उर्वरक संयंत्र की अवस्थिति को कौन-से दो कारक अक्सर मिलकर प्रभावित करते हैं?",["लौह अयस्क और पर्यटन","कच्चे माल की आपूर्ति और कृषि बाज़ारों तक पहुँच","जूट और मत्स्यन","कोयले की परत की मोटाई और चाय के बागान"],"संयंत्रों को गैस या फ़ॉस्फ़ेट जैसे कच्चे माल और कृषि क्षेत्रों तक सुगम पहुँच की आवश्यकता होती है।"],"pa":["ਖਾਦ ਪਲਾਂਟ ਦੀ ਥਾਂ 'ਤੇ ਕਿਹੜੇ ਦੋ ਕਾਰਕ ਅਕਸਰ ਰਲ ਕੇ ਅਸਰ ਪਾਉਂਦੇ ਹਨ?",["ਕੱਚਾ ਲੋਹਾ ਅਤੇ ਸੈਰ-ਸਪਾਟਾ","ਕੱਚੇ ਮਾਲ ਦੀ ਸਪਲਾਈ ਅਤੇ ਖੇਤੀ ਬਾਜ਼ਾਰਾਂ ਤੱਕ ਪਹੁੰਚ","ਜੂਟ ਅਤੇ ਮੱਛੀ ਫੜਨ ਦਾ ਕੰਮ","ਕੋਲੇ ਦੀ ਪਰਤ ਦੀ ਮੋਟਾਈ ਅਤੇ ਚਾਹ ਦੇ ਬਾਗ਼"],"ਪਲਾਂਟਾਂ ਨੂੰ ਗੈਸ ਜਾਂ ਫ਼ਾਸਫ਼ੇਟ ਵਰਗਾ ਕੱਚਾ ਮਾਲ ਅਤੇ ਖੇਤੀ ਵਾਲੇ ਇਲਾਕਿਆਂ ਤੱਕ ਸੌਖੀ ਪਹੁੰਚ ਚਾਹੀਦੀ ਹੈ।"]},
"GEO-IND-001-CP008-Q033":{"h":"1c3cc201","hi":["कथनों पर विचार कीजिए: I. गैस पाइपलाइन उर्वरक संयंत्र की अवस्थिति को प्रभावित कर सकती हैं। II. कृषि की माँग भी वितरण को प्रभावित कर सकती है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","I और II दोनों सही हैं","न तो I और न ही II सही है"],"आपूर्ति स्रोत और बाज़ार, दोनों से जुड़े कारक महत्वपूर्ण हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਗੈਸ ਪਾਈਪਲਾਈਨਾਂ ਖਾਦ ਪਲਾਂਟ ਦੀ ਥਾਂ 'ਤੇ ਅਸਰ ਪਾ ਸਕਦੀਆਂ ਹਨ। II. ਖੇਤੀ ਦੀ ਮੰਗ ਵੀ ਵੰਡ 'ਤੇ ਅਸਰ ਪਾ ਸਕਦੀ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਕੱਚੇ ਮਾਲ ਦੇ ਸਰੋਤ ਅਤੇ ਬਾਜ਼ਾਰ ਨਾਲ ਜੁੜੇ ਕਾਰਕ ਦੋਵੇਂ ਅਹਿਮ ਹਨ।"]},
"GEO-IND-001-CP008-Q034":{"h":"d4b40f40","hi":["उर्वरक उद्योग के भूगोल में कौन-सा युग्म सिंदरी की सही पहचान करता है?",["गैस पाइपलाइन — जूट का कच्चा माल","पत्तन — केवल गन्ने का स्रोत","शैल फ़ॉस्फ़ेट — कपास का रेशा","गैस पाइपलाइन — नाइट्रोजनयुक्त उर्वरक के कच्चे माल तक पहुँच"],"प्राकृतिक गैस की पाइपलाइन अमोनिया और यूरिया संयंत्रों को गैस उपलब्ध करा सकती हैं।"],"pa":["ਖਾਦ ਉਦਯੋਗ ਦੇ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਿੰਦਰੀ ਦੀ ਸਹੀ ਪਛਾਣ ਕਰਦਾ ਹੈ?",["ਗੈਸ ਪਾਈਪਲਾਈਨ — ਜੂਟ ਦਾ ਕੱਚਾ ਮਾਲ","ਬੰਦਰਗਾਹ — ਸਿਰਫ਼ ਗੰਨੇ ਦਾ ਸਰੋਤ","ਚੱਟਾਨੀ ਫ਼ਾਸਫ਼ੇਟ — ਕਪਾਹ ਦਾ ਰੇਸ਼ਾ","ਗੈਸ ਪਾਈਪਲਾਈਨ — ਨਾਈਟ੍ਰੋਜਨ ਵਾਲੀ ਖਾਦ ਦੇ ਕੱਚੇ ਮਾਲ ਤੱਕ ਪਹੁੰਚ"],"ਕੁਦਰਤੀ ਗੈਸ ਦੀਆਂ ਪਾਈਪਲਾਈਨਾਂ ਅਮੋਨੀਆ ਅਤੇ ਯੂਰੀਆ ਪਲਾਂਟਾਂ ਨੂੰ ਗੈਸ ਦੇ ਸਕਦੀਆਂ ਹਨ।"]},
"GEO-IND-001-CP008-Q035":{"h":"99b3e8a9","hi":["पत्तन तक पहुँच से किस प्रकार के उर्वरक संयंत्र को विशेष लाभ हो सकता है?",["आयातित कच्चा माल इस्तेमाल करने वाला फ़ॉस्फ़ेटयुक्त उर्वरक संयंत्र","जूट मिल","कपास से बिनौले अलग करने की इकाई","चीनी मिल"],"पत्तनों से फ़ॉस्फ़ेट शैल, गंधक और संबंधित सामग्री का बड़ी मात्रा में आयात आसान हो जाता है।"],"pa":["ਬੰਦਰਗਾਹ ਤੱਕ ਪਹੁੰਚ ਦਾ ਖ਼ਾਸ ਲਾਭ ਕਿਸ ਕਿਸਮ ਦੇ ਖਾਦ ਪਲਾਂਟ ਨੂੰ ਹੋ ਸਕਦਾ ਹੈ?",["ਆਯਾਤ ਕੀਤਾ ਕੱਚਾ ਮਾਲ ਵਰਤਣ ਵਾਲਾ ਫ਼ਾਸਫ਼ੇਟ ਖਾਦ ਪਲਾਂਟ","ਜੂਟ ਮਿੱਲ","ਕਪਾਹ ਵਿੱਚੋਂ ਵੜੇਵੇਂ ਕੱਢਣ ਵਾਲੀ ਇਕਾਈ","ਖੰਡ ਮਿੱਲ"],"ਬੰਦਰਗਾਹਾਂ ਤੋਂ ਫ਼ਾਸਫ਼ੇਟ ਚੱਟਾਨ, ਗੰਧਕ ਅਤੇ ਇਸ ਨਾਲ ਜੁੜੀ ਸਮੱਗਰੀ ਦਾ ਵੱਡੀ ਮਾਤਰਾ ਵਿੱਚ ਆਯਾਤ ਸੌਖਾ ਹੁੰਦਾ ਹੈ।"]},
"GEO-IND-001-CP008-Q036":{"h":"7ef54df4","hi":["एक संयंत्र गैस पाइपलाइन और प्रमुख कृषि पट्टी के पास है। कौन-सा उद्योग गैस के कच्चे माल और पास की कृषि माँग, दोनों का लाभ लेता है?",["जूट वस्त्र","नाइट्रोजनयुक्त उर्वरक","ऐलुमिनियम प्रगलन","सीमेंट"],"कच्चे माल के रूप में गैस और कृषि माँग का मेल नाइट्रोजनयुक्त उर्वरक उत्पादन की ओर प्रबल संकेत करता है।"],"pa":["ਇੱਕ ਪਲਾਂਟ ਗੈਸ ਪਾਈਪਲਾਈਨ ਅਤੇ ਪ੍ਰਮੁੱਖ ਖੇਤੀ ਪੱਟੀ ਨੇੜੇ ਹੈ। ਕਿਹੜਾ ਉਦਯੋਗ ਗੈਸ ਨੂੰ ਕੱਚੇ ਮਾਲ ਵਜੋਂ ਵਰਤਦਾ ਹੈ ਅਤੇ ਨੇੜਲੀ ਖੇਤੀ ਦੀ ਮੰਗ ਦਾ ਵੀ ਲਾਭ ਲੈਂਦਾ ਹੈ?",["ਜੂਟ ਦੇ ਕੱਪੜੇ","ਨਾਈਟ੍ਰੋਜਨ ਵਾਲੀ ਖਾਦ","ਐਲੂਮੀਨੀਅਮ ਦੀ ਗਲਾਈ","ਸੀਮਿੰਟ"],"ਕੱਚੇ ਮਾਲ ਵਜੋਂ ਗੈਸ ਅਤੇ ਖੇਤੀ ਦੀ ਮੰਗ ਦੋਵੇਂ ਨਾਈਟ੍ਰੋਜਨ ਵਾਲੀ ਖਾਦ ਬਣਾਉਣ ਵੱਲ ਸਪਸ਼ਟ ਇਸ਼ਾਰਾ ਕਰਦੇ ਹਨ।"]},
"GEO-IND-001-CP008-Q037":{"h":"e240323c","hi":["सिंदरी ऐतिहासिक रूप से किस उद्योग के लिए प्रसिद्ध है?",["जूट मिलें","जहाज़ निर्माण","कपास की कताई","उर्वरक उद्योग"],"झारखंड का सिंदरी भारत के ऐतिहासिक उर्वरक उद्योग केंद्रों में से एक है।"],"pa":["ਸਿੰਦਰੀ ਇਤਿਹਾਸਕ ਤੌਰ 'ਤੇ ਕਿਹੜੇ ਉਦਯੋਗ ਲਈ ਜਾਣਿਆ ਜਾਂਦਾ ਹੈ?",["ਜੂਟ ਮਿੱਲਾਂ","ਸਮੁੰਦਰੀ ਜਹਾਜ਼ ਬਣਾਉਣਾ","ਕਪਾਹ ਦੀ ਕਤਾਈ","ਖਾਦ ਉਦਯੋਗ"],"ਝਾਰਖੰਡ ਦਾ ਸਿੰਦਰੀ ਭਾਰਤ ਦੇ ਇਤਿਹਾਸਕ ਖਾਦ ਉਦਯੋਗ ਕੇਂਦਰਾਂ ਵਿੱਚੋਂ ਇੱਕ ਹੈ।"]},
"GEO-IND-001-CP008-Q038":{"h":"b840a480","hi":["सिंदरी किस राज्य में है?",["झारखंड","गुजरात","तमिलनाडु","पंजाब"],"सिंदरी झारखंड में दामोदर औद्योगिक क्षेत्र का हिस्सा है।"],"pa":["ਸਿੰਦਰੀ ਕਿਹੜੇ ਰਾਜ ਵਿੱਚ ਹੈ?",["ਝਾਰਖੰਡ","ਗੁਜਰਾਤ","ਤਾਮਿਲਨਾਡੂ","ਪੰਜਾਬ"],"ਸਿੰਦਰੀ ਝਾਰਖੰਡ ਵਿੱਚ ਦਾਮੋਦਰ ਉਦਯੋਗਿਕ ਖੇਤਰ ਦਾ ਹਿੱਸਾ ਹੈ।"]},
"GEO-IND-001-CP008-Q039":{"h":"3f5e6144","hi":["कथनों पर विचार कीजिए: I. सिंदरी झारखंड में है। II. इसका ऐतिहासिक संबंध उर्वरक विनिर्माण से है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","I और II दोनों सही हैं","केवल II सही है","न तो I और न ही II सही है"],"दोनों औद्योगिक अवस्थिति के स्थापित तथ्य हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਸਿੰਦਰੀ ਝਾਰਖੰਡ ਵਿੱਚ ਹੈ। II. ਇਸ ਦਾ ਖਾਦ ਬਣਾਉਣ ਨਾਲ ਇਤਿਹਾਸਕ ਸਬੰਧ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਦੋਵੇਂ ਉਦਯੋਗਿਕ ਥਾਵਾਂ ਦੇ ਭੂਗੋਲ ਨਾਲ ਜੁੜੇ ਸਥਾਪਤ ਤੱਥ ਹਨ।"]},
"GEO-IND-001-CP008-Q040":{"h":"4a7df146","hi":["उर्वरक उद्योग के भूगोल में कौन-सा युग्म नामरूप की सही पहचान करता है?",["सिंदरी — केरल","सिंदरी — राजस्थान","सिंदरी — झारखंड","सिंदरी — तमिलनाडु"],"सिंदरी झारखंड में है।"],"pa":["ਖਾਦ ਉਦਯੋਗ ਦੇ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਨਾਮਰੂਪ ਦੀ ਸਹੀ ਪਛਾਣ ਕਰਦਾ ਹੈ?",["ਸਿੰਦਰੀ — ਕੇਰਲ","ਸਿੰਦਰੀ — ਰਾਜਸਥਾਨ","ਸਿੰਦਰੀ — ਝਾਰਖੰਡ","ਸਿੰਦਰੀ — ਤਾਮਿਲਨਾਡੂ"],"ਸਿੰਦਰੀ ਝਾਰਖੰਡ ਵਿੱਚ ਹੈ।"]},
"GEO-IND-001-CP008-Q041":{"h":"6360535b","hi":["सिंदरी किस औद्योगिक क्षेत्र में है?",["केवल कोंकण तट","थार मरुस्थल","केवल कावेरी डेल्टा","दामोदर-छोटानागपुर औद्योगिक पट्टी"],"सिंदरी पूर्वी भारत की खनिज-औद्योगिक पट्टी में है।"],"pa":["ਸਿੰਦਰੀ ਕਿਹੜੇ ਉਦਯੋਗਿਕ ਖੇਤਰ ਵਿੱਚ ਹੈ?",["ਸਿਰਫ਼ ਕੋਂਕਣ ਤੱਟ","ਥਾਰ ਦਾ ਮਾਰੂਥਲ","ਸਿਰਫ਼ ਕਾਵੇਰੀ ਡੈਲਟਾ","ਦਾਮੋਦਰ-ਛੋਟਾਨਾਗਪੁਰ ਉਦਯੋਗਿਕ ਪੱਟੀ"],"ਸਿੰਦਰੀ ਪੂਰਬੀ ਭਾਰਤ ਦੀ ਖਣਿਜ-ਉਦਯੋਗਿਕ ਪੱਟੀ ਵਿੱਚ ਪੈਂਦਾ ਹੈ।"]},
"GEO-IND-001-CP008-Q042":{"h":"26f223ec","hi":["एक मानचित्र में झारखंड के धनबाद के पास एक ऐतिहासिक उर्वरक केंद्र दिखाया गया है। वह कौन-सा स्थान है?",["सिंदरी","तिरुप्पुर","खेतड़ी","सांभर"],"सिंदरी धनबाद के पास है और उसका उर्वरक विनिर्माण से ऐतिहासिक संबंध है।"],"pa":["ਇੱਕ ਨਕਸ਼ੇ ਵਿੱਚ ਝਾਰਖੰਡ ਦੇ ਧਨਬਾਦ ਨੇੜੇ ਇੱਕ ਇਤਿਹਾਸਕ ਖਾਦ ਕੇਂਦਰ ਦਿਖਾਇਆ ਗਿਆ ਹੈ। ਉਹ ਕਿਹੜੀ ਥਾਂ ਹੈ?",["ਸਿੰਦਰੀ","ਤਿਰੁੱਪੁਰ","ਖੇਤੜੀ","ਸਾਂਭਰ"],"ਸਿੰਦਰੀ ਧਨਬਾਦ ਨੇੜੇ ਹੈ ਅਤੇ ਇਸ ਦਾ ਖਾਦ ਬਣਾਉਣ ਨਾਲ ਇਤਿਹਾਸਕ ਸਬੰਧ ਹੈ।"]},
"GEO-IND-001-CP008-Q043":{"h":"c303991b","hi":["नामरूप किस राज्य का महत्वपूर्ण उर्वरक केंद्र है?",["असम","गुजरात","ओडिशा","राजस्थान"],"असम के नामरूप में उर्वरक उद्योग लंबे समय से स्थापित है।"],"pa":["ਨਾਮਰੂਪ ਕਿਹੜੇ ਰਾਜ ਦਾ ਅਹਿਮ ਖਾਦ ਕੇਂਦਰ ਹੈ?",["ਅਸਾਮ","ਗੁਜਰਾਤ","ਓਡੀਸ਼ਾ","ਰਾਜਸਥਾਨ"],"ਅਸਾਮ ਦੇ ਨਾਮਰੂਪ ਵਿੱਚ ਖਾਦ ਉਦਯੋਗ ਲੰਮੇ ਸਮੇਂ ਤੋਂ ਸਥਾਪਤ ਹੈ।"]},
"GEO-IND-001-CP008-Q044":{"h":"6078ff8a","hi":["नामरूप में उर्वरक उत्पादन पर किस स्थानीय संसाधन का गहरा प्रभाव पड़ा?",["जूट","प्राकृतिक गैस","बॉक्साइट","चूना पत्थर"],"असम के प्राकृतिक गैस संसाधनों से नाइट्रोजनयुक्त उर्वरक उत्पादन का कच्चा माल मिला।"],"pa":["ਨਾਮਰੂਪ ਵਿੱਚ ਖਾਦ ਉਤਪਾਦਨ 'ਤੇ ਕਿਹੜੇ ਸਥਾਨਕ ਸਰੋਤ ਦਾ ਵੱਡਾ ਅਸਰ ਪਿਆ?",["ਜੂਟ","ਕੁਦਰਤੀ ਗੈਸ","ਬਾਕਸਾਈਟ","ਚੂਨਾ ਪੱਥਰ"],"ਅਸਾਮ ਦੇ ਕੁਦਰਤੀ ਗੈਸ ਸਰੋਤਾਂ ਤੋਂ ਨਾਈਟ੍ਰੋਜਨ ਵਾਲੀ ਖਾਦ ਬਣਾਉਣ ਲਈ ਕੱਚਾ ਮਾਲ ਮਿਲਿਆ।"]},
"GEO-IND-001-CP008-Q045":{"h":"afe66f70","hi":["कथनों पर विचार कीजिए: I. नामरूप असम में है। II. प्राकृतिक गैस नाइट्रोजनयुक्त उर्वरक उत्पादन में सहायक है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","I और II दोनों सही हैं","न तो I और न ही II सही है"],"दोनों तथ्य नामरूप में उद्योग की अवस्थिति को समझाते हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਨਾਮਰੂਪ ਅਸਾਮ ਵਿੱਚ ਹੈ। II. ਨਾਈਟ੍ਰੋਜਨ ਵਾਲੀ ਖਾਦ ਬਣਾਉਣ ਵਿੱਚ ਕੁਦਰਤੀ ਗੈਸ ਮਦਦ ਕਰਦੀ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਦੋਵੇਂ ਤੱਥ ਸਮਝਾਉਂਦੇ ਹਨ ਕਿ ਉਦਯੋਗ ਨਾਮਰੂਪ ਵਿੱਚ ਕਿਉਂ ਲੱਗਿਆ।"]},
"GEO-IND-001-CP008-Q046":{"h":"5f89fc90","hi":["कौन-सा युग्म गैस से जुड़े उर्वरक केंद्र की सही पहचान करता है?",["नामरूप — केवल जूट","नामरूप — केवल सीमेंट","नामरूप — ऐलुमिनियम प्रगलन","नामरूप — प्राकृतिक गैस आधारित उर्वरक"],"नामरूप गैस से जुड़े उर्वरक केंद्र का पारंपरिक उदाहरण है।"],"pa":["ਕਿਹੜਾ ਜੋੜਾ ਗੈਸ ਨਾਲ ਜੁੜੇ ਖਾਦ ਕੇਂਦਰ ਦੀ ਸਹੀ ਪਛਾਣ ਕਰਦਾ ਹੈ?",["ਨਾਮਰੂਪ — ਸਿਰਫ਼ ਜੂਟ","ਨਾਮਰੂਪ — ਸਿਰਫ਼ ਸੀਮਿੰਟ","ਨਾਮਰੂਪ — ਐਲੂਮੀਨੀਅਮ ਦੀ ਗਲਾਈ","ਨਾਮਰੂਪ — ਕੁਦਰਤੀ ਗੈਸ 'ਤੇ ਆਧਾਰਿਤ ਖਾਦ"],"ਨਾਮਰੂਪ ਗੈਸ ਨਾਲ ਜੁੜੇ ਖਾਦ ਕੇਂਦਰ ਦੀ ਰਵਾਇਤੀ ਉਦਾਹਰਨ ਹੈ।"]},
"GEO-IND-001-CP008-Q047":{"h":"bb7680c4","hi":["नामरूप कच्चे माल के स्रोत की ओर उन्मुख उद्योग का उपयुक्त उदाहरण क्यों है?",["संयंत्र ने पास की प्राकृतिक गैस कच्चे माल के रूप में इस्तेमाल की","वह जूट के खेतों पर निर्भर था","केवल पत्तनों का महत्व था","स्थानीय संसाधनों से उसका कोई संबंध नहीं था"],"गैस की उपलब्धता का उर्वरक संयंत्र की अवस्थिति पर गहरा प्रभाव पड़ा।"],"pa":["ਨਾਮਰੂਪ ਕੱਚੇ ਮਾਲ ਦੇ ਸਰੋਤ ਨੇੜੇ ਲੱਗੇ ਉਦਯੋਗ ਦੀ ਢੁੱਕਵੀਂ ਉਦਾਹਰਨ ਕਿਉਂ ਹੈ?",["ਪਲਾਂਟ ਨੇ ਨੇੜੇ ਮਿਲਦੀ ਕੁਦਰਤੀ ਗੈਸ ਕੱਚੇ ਮਾਲ ਵਜੋਂ ਵਰਤੀ","ਇਹ ਜੂਟ ਦੇ ਖੇਤਾਂ 'ਤੇ ਨਿਰਭਰ ਸੀ","ਸਿਰਫ਼ ਬੰਦਰਗਾਹਾਂ ਦਾ ਮਹੱਤਵ ਸੀ","ਇਸ ਦਾ ਸਥਾਨਕ ਸਰੋਤ ਨਾਲ ਕੋਈ ਸਬੰਧ ਨਹੀਂ ਸੀ"],"ਗੈਸ ਦੀ ਉਪਲਬਧਤਾ ਦਾ ਖਾਦ ਪਲਾਂਟ ਦੀ ਥਾਂ 'ਤੇ ਡੂੰਘਾ ਅਸਰ ਪਿਆ।"]},
"GEO-IND-001-CP008-Q048":{"h":"072cb815","hi":["कौन-सी शृंखला नामरूप के उद्योग का आधार सही दर्शाती है?",["जूट → अमोनिया → इस्पात","प्राकृतिक गैस → अमोनिया/यूरिया उर्वरक","बॉक्साइट → उर्वरक → ऐलुमिनियम","कोयला → कपास → यूरिया"],"प्राकृतिक गैस से अमोनिया और नाइट्रोजनयुक्त उर्वरक बनाए जाते हैं।"],"pa":["ਕਿਹੜੀ ਲੜੀ ਨਾਮਰੂਪ ਦੇ ਉਦਯੋਗ ਦਾ ਆਧਾਰ ਸਹੀ ਦਰਸਾਉਂਦੀ ਹੈ?",["ਜੂਟ → ਅਮੋਨੀਆ → ਸਟੀਲ","ਕੁਦਰਤੀ ਗੈਸ → ਅਮੋਨੀਆ/ਯੂਰੀਆ ਖਾਦ","ਬਾਕਸਾਈਟ → ਖਾਦ → ਐਲੂਮੀਨੀਅਮ","ਕੋਲਾ → ਕਪਾਹ → ਯੂਰੀਆ"],"ਕੁਦਰਤੀ ਗੈਸ ਤੋਂ ਅਮੋਨੀਆ ਅਤੇ ਨਾਈਟ੍ਰੋਜਨ ਵਾਲੀਆਂ ਖਾਦਾਂ ਬਣਾਈਆਂ ਜਾਂਦੀਆਂ ਹਨ।"]},
"GEO-IND-001-CP008-Q049":{"h":"0e275dc1","hi":["किस पश्चिमी महानगरीय क्षेत्र में रसायन उद्योग बड़े पैमाने पर केंद्रित हैं?",["झरिया-बोकारो","कोडरमा-गया","मुंबई-ठाणे क्षेत्र","सांभर-खेतड़ी"],"मुंबई-ठाणे रसायन और पेट्रोरसायन उद्योग का महत्वपूर्ण क्षेत्र है।"],"pa":["ਕਿਹੜੇ ਪੱਛਮੀ ਮਹਾਂਨਗਰੀ ਖੇਤਰ ਵਿੱਚ ਰਸਾਇਣ ਉਦਯੋਗ ਵੱਡੇ ਪੱਧਰ 'ਤੇ ਕੇਂਦਰਿਤ ਹਨ?",["ਝਰੀਆ-ਬੋਕਾਰੋ","ਕੋਡਰਮਾ-ਗਯਾ","ਮੁੰਬਈ-ਠਾਣੇ ਖੇਤਰ","ਸਾਂਭਰ-ਖੇਤੜੀ"],"ਮੁੰਬਈ-ਠਾਣੇ ਰਸਾਇਣ ਅਤੇ ਪੈਟਰੋ-ਰਸਾਇਣ ਉਦਯੋਗ ਦਾ ਅਹਿਮ ਖੇਤਰ ਹੈ।"]},
"GEO-IND-001-CP008-Q050":{"h":"b0f45058","hi":["मुंबई-ठाणे के आसपास रसायन उद्योगों को किन कारकों से सहारा मिलता है?",["केवल जूट के खेत","केवल लौह अयस्क","चाय के बागान","पत्तन तक पहुँच, शोधनशालाएँ, बाज़ार और परिवहन"],"तटीय महानगरीय अवस्थिति से कच्चा माल, माल की आवाजाही की सुविधाएँ और बड़ा बाज़ार मिलता है।"],"pa":["ਮੁੰਬਈ-ਠਾਣੇ ਦੇ ਆਲੇ-ਦੁਆਲੇ ਰਸਾਇਣ ਉਦਯੋਗਾਂ ਨੂੰ ਕਿਹੜੇ ਕਾਰਕਾਂ ਤੋਂ ਸਹਾਰਾ ਮਿਲਦਾ ਹੈ?",["ਸਿਰਫ਼ ਜੂਟ ਦੇ ਖੇਤ","ਸਿਰਫ਼ ਕੱਚਾ ਲੋਹਾ","ਚਾਹ ਦੇ ਬਾਗ਼","ਬੰਦਰਗਾਹ ਤੱਕ ਪਹੁੰਚ, ਰਿਫ਼ਾਇਨਰੀਆਂ, ਬਾਜ਼ਾਰ ਅਤੇ ਆਵਾਜਾਈ"],"ਤੱਟੀ ਮਹਾਂਨਗਰੀ ਥਾਂ 'ਤੇ ਕੱਚਾ ਮਾਲ, ਮਾਲ ਢੋਣ ਦੇ ਪ੍ਰਬੰਧ ਅਤੇ ਵੱਡਾ ਬਾਜ਼ਾਰ ਮਿਲਦੇ ਹਨ।"]},
"GEO-IND-001-CP008-Q051":{"h":"fcd94a85","hi":["कथनों पर विचार कीजिए: I. मुंबई में प्रमुख पत्तन की सुविधा है। II. शोधनशालाओं और रसायन उद्योगों को इस अवस्थिति से लाभ है। कौन-सा/से कथन सही है/हैं?",["I और II दोनों सही हैं","केवल I सही है","केवल II सही है","न तो I और न ही II सही है"],"पत्तन और तेल शोधन की सुविधाएँ रसायन उद्योग की अवस्थिति को मज़बूत बनाती हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਮੁੰਬਈ ਨੂੰ ਪ੍ਰਮੁੱਖ ਬੰਦਰਗਾਹ ਦੀ ਸਹੂਲਤ ਹੈ। II. ਰਿਫ਼ਾਇਨਰੀਆਂ ਅਤੇ ਰਸਾਇਣ ਉਦਯੋਗਾਂ ਨੂੰ ਇਸ ਥਾਂ ਦਾ ਲਾਭ ਹੁੰਦਾ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਬੰਦਰਗਾਹ ਅਤੇ ਰਿਫ਼ਾਇਨਰੀਆਂ ਦੀਆਂ ਸਹੂਲਤਾਂ ਇਸ ਥਾਂ ਨੂੰ ਰਸਾਇਣ ਉਦਯੋਗਾਂ ਲਈ ਹੋਰ ਅਨੁਕੂਲ ਬਣਾਉਂਦੀਆਂ ਹਨ।"]},
"GEO-IND-001-CP008-Q052":{"h":"455a825e","hi":["रसायन उद्योग के भूगोल में कौन-सा युग्म सही सुमेलित है?",["मुंबई-ठाणे — केवल जूट","मुंबई-ठाणे — रसायन और पेट्रोरसायन","मुंबई-ठाणे — कोयला क्षेत्र","मुंबई-ठाणे — केवल चीनी"],"इस क्षेत्र में कई तरह के रसायन और पेट्रोरसायन उद्योग हैं।"],"pa":["ਰਸਾਇਣ ਉਦਯੋਗ ਦੇ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਮੁੰਬਈ-ਠਾਣੇ — ਸਿਰਫ਼ ਜੂਟ","ਮੁੰਬਈ-ਠਾਣੇ — ਰਸਾਇਣ ਅਤੇ ਪੈਟਰੋ-ਰਸਾਇਣ","ਮੁੰਬਈ-ਠਾਣੇ — ਕੋਲਾ ਖੇਤਰ","ਮੁੰਬਈ-ਠਾਣੇ — ਸਿਰਫ਼ ਖੰਡ"],"ਇਸ ਖੇਤਰ ਵਿੱਚ ਕਈ ਤਰ੍ਹਾਂ ਦੇ ਰਸਾਇਣ ਅਤੇ ਪੈਟਰੋ-ਰਸਾਇਣ ਉਦਯੋਗ ਹਨ।"]},
"GEO-IND-001-CP008-Q053":{"h":"7d00b66a","hi":["पास में खदानें न होने पर भी महानगरीय रसायन उद्योग क्षेत्र क्यों बने रहते हैं?",["रसायन संयंत्रों को उत्पादन सामग्री नहीं चाहिए","केवल अयस्क का महत्व है","वे पत्तनों, पाइपलाइन, बाज़ारों और औद्योगिक तंत्र पर निर्भर हैं","परिवहन का कोई महत्व नहीं है"],"आधुनिक रसायन उद्योग काफी हद तक आधारभूत संरचना और बाज़ारों की ओर उन्मुख हो सकते हैं।"],"pa":["ਨੇੜੇ ਖਾਣਾਂ ਨਾ ਹੋਣ ਦੇ ਬਾਵਜੂਦ ਮਹਾਂਨਗਰਾਂ ਦੇ ਰਸਾਇਣ ਉਦਯੋਗ ਖੇਤਰ ਕਿਉਂ ਕਾਇਮ ਰਹਿੰਦੇ ਹਨ?",["ਰਸਾਇਣ ਪਲਾਂਟਾਂ ਨੂੰ ਸਮੱਗਰੀ ਦੀ ਲੋੜ ਨਹੀਂ ਹੁੰਦੀ","ਸਿਰਫ਼ ਅਯਸਕ ਦਾ ਮਹੱਤਵ ਹੈ","ਉਹ ਬੰਦਰਗਾਹਾਂ, ਪਾਈਪਲਾਈਨਾਂ, ਬਾਜ਼ਾਰਾਂ ਅਤੇ ਉਦਯੋਗਿਕ ਜਾਲਾਂ 'ਤੇ ਨਿਰਭਰ ਹਨ","ਆਵਾਜਾਈ ਦਾ ਕੋਈ ਮਹੱਤਵ ਨਹੀਂ ਹੈ"],"ਆਧੁਨਿਕ ਰਸਾਇਣ ਉਦਯੋਗਾਂ ਦੀ ਥਾਂ ਕਾਫ਼ੀ ਹੱਦ ਤੱਕ ਬੁਨਿਆਦੀ ਢਾਂਚੇ ਅਤੇ ਬਾਜ਼ਾਰਾਂ 'ਤੇ ਨਿਰਭਰ ਹੋ ਸਕਦੀ ਹੈ।"]},
"GEO-IND-001-CP008-Q054":{"h":"ba21f77d","hi":["रसायन उद्योग क्षेत्रों की कौन-सी तुलना सही है?",["दोनों केवल जूट के क्षेत्र हैं","दोनों में पत्तन नहीं हैं","दोनों केवल लौह अयस्क पर निर्भर हैं","गुजरात और मुंबई-ठाणे दोनों को पश्चिमी तट की तेल शोधन और पत्तन सुविधाओं से लाभ मिलता है"],"तटीय हाइड्रोकार्बन आधारभूत संरचना दोनों क्षेत्रों को सहारा देती है।"],"pa":["ਰਸਾਇਣ ਉਦਯੋਗ ਖੇਤਰਾਂ ਦੀ ਕਿਹੜੀ ਤੁਲਨਾ ਸਹੀ ਹੈ?",["ਦੋਵੇਂ ਸਿਰਫ਼ ਜੂਟ ਦੇ ਖੇਤਰ ਹਨ","ਦੋਵਾਂ ਕੋਲ ਬੰਦਰਗਾਹਾਂ ਨਹੀਂ ਹਨ","ਦੋਵੇਂ ਸਿਰਫ਼ ਕੱਚੇ ਲੋਹੇ 'ਤੇ ਨਿਰਭਰ ਹਨ","ਗੁਜਰਾਤ ਅਤੇ ਮੁੰਬਈ-ਠਾਣੇ ਦੋਵਾਂ ਨੂੰ ਪੱਛਮੀ ਤੱਟ ਦੀਆਂ ਰਿਫ਼ਾਇਨਰੀਆਂ ਅਤੇ ਬੰਦਰਗਾਹਾਂ ਦਾ ਲਾਭ ਹੁੰਦਾ ਹੈ"],"ਤੱਟ 'ਤੇ ਹਾਈਡ੍ਰੋਕਾਰਬਨਾਂ ਲਈ ਬਣਿਆ ਬੁਨਿਆਦੀ ਢਾਂਚਾ ਦੋਵਾਂ ਖੇਤਰਾਂ ਨੂੰ ਸਹਾਰਾ ਦਿੰਦਾ ਹੈ।"]},
"GEO-IND-001-CP008-Q055":{"h":"5bc9045e","hi":["कौन-सा भारतीय शहर औषधि विनिर्माण का महत्वपूर्ण केंद्र है?",["झरिया","सांभर","हैदराबाद","पन्ना"],"हैदराबाद भारत के प्रमुख औषधि और जीवन विज्ञान संबंधी विनिर्माण केंद्रों में से एक है।"],"pa":["ਕਿਹੜਾ ਭਾਰਤੀ ਸ਼ਹਿਰ ਦਵਾਈਆਂ ਬਣਾਉਣ ਦਾ ਅਹਿਮ ਕੇਂਦਰ ਹੈ?",["ਝਰੀਆ","ਸਾਂਭਰ","ਹੈਦਰਾਬਾਦ","ਪੰਨਾ"],"ਹੈਦਰਾਬਾਦ ਭਾਰਤ ਵਿੱਚ ਦਵਾਈਆਂ ਅਤੇ ਜੀਵਨ ਵਿਗਿਆਨ ਨਾਲ ਜੁੜੇ ਨਿਰਮਾਣ ਦੇ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰਾਂ ਵਿੱਚੋਂ ਇੱਕ ਹੈ।"]},
"GEO-IND-001-CP008-Q056":{"h":"26d2b2bf","hi":["किस पश्चिमी राज्य में भी औषधि और रसायन उद्योग प्रमुख हैं?",["पंजाब","असम","मेघालय","गुजरात"],"गुजरात में औषधि और रसायन विनिर्माण का मज़बूत आधार है।"],"pa":["ਪੱਛਮੀ ਭਾਰਤ ਦੇ ਕਿਹੜੇ ਰਾਜ ਵਿੱਚ ਵੀ ਦਵਾਈਆਂ ਅਤੇ ਰਸਾਇਣਾਂ ਦਾ ਪ੍ਰਮੁੱਖ ਉਦਯੋਗ ਹੈ?",["ਪੰਜਾਬ","ਅਸਾਮ","ਮੇਘਾਲਿਆ","ਗੁਜਰਾਤ"],"ਗੁਜਰਾਤ ਵਿੱਚ ਦਵਾਈਆਂ ਅਤੇ ਰਸਾਇਣ ਬਣਾਉਣ ਦਾ ਮਜ਼ਬੂਤ ਆਧਾਰ ਹੈ।"]},
"GEO-IND-001-CP008-Q057":{"h":"511faa16","hi":["औषधि विनिर्माण के लिए कौन-सा अवस्थितिक कारक विशेष रूप से महत्वपूर्ण है?",["कुशल वैज्ञानिक श्रम और रसायन उद्योग की आधारभूत संरचना","जूट के खेत","केवल कोयले की परतें","गन्ने की आपूर्ति"],"औषधि विनिर्माण काफी हद तक तकनीकी कौशल, प्रयोगशालाओं और रासायनिक सामग्री पर निर्भर है।"],"pa":["ਦਵਾਈਆਂ ਬਣਾਉਣ ਲਈ ਥਾਂ ਦੀ ਚੋਣ ਦਾ ਕਿਹੜਾ ਕਾਰਕ ਖ਼ਾਸ ਤੌਰ 'ਤੇ ਅਹਿਮ ਹੈ?",["ਵਿਗਿਆਨਕ ਹੁਨਰ ਵਾਲੇ ਕਾਮੇ ਅਤੇ ਰਸਾਇਣ ਉਦਯੋਗ ਦਾ ਬੁਨਿਆਦੀ ਢਾਂਚਾ","ਜੂਟ ਦੇ ਖੇਤ","ਸਿਰਫ਼ ਕੋਲੇ ਦੀਆਂ ਪਰਤਾਂ","ਗੰਨੇ ਦੀ ਸਪਲਾਈ"],"ਦਵਾਈਆਂ ਬਣਾਉਣਾ ਤਕਨੀਕੀ ਹੁਨਰ, ਪ੍ਰਯੋਗਸ਼ਾਲਾਵਾਂ ਅਤੇ ਰਸਾਇਣਕ ਸਮੱਗਰੀ 'ਤੇ ਬਹੁਤ ਨਿਰਭਰ ਹੈ।"]},
"GEO-IND-001-CP008-Q058":{"h":"44a1283e","hi":["कथनों पर विचार कीजिए: I. हैदराबाद औषधि उद्योग का केंद्र है। II. कुशल वैज्ञानिक श्रम से औषधि उद्योग के संकुलों को सहारा मिलता है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","I और II दोनों सही हैं","केवल II सही है","न तो I और न ही II सही है"],"दोनों तथ्य आधुनिक औषधि उद्योग के भूगोल के लिए महत्वपूर्ण हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਹੈਦਰਾਬਾਦ ਦਵਾਈ ਉਦਯੋਗ ਦਾ ਕੇਂਦਰ ਹੈ। II. ਵਿਗਿਆਨਕ ਹੁਨਰ ਵਾਲੇ ਕਾਮੇ ਦਵਾਈ ਉਦਯੋਗ ਦੇ ਗੁੱਛਾਂ ਨੂੰ ਸਹਾਰਾ ਦਿੰਦੇ ਹਨ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਦੋਵੇਂ ਤੱਥ ਆਧੁਨਿਕ ਦਵਾਈ ਉਦਯੋਗ ਦੇ ਭੂਗੋਲ ਲਈ ਅਹਿਮ ਹਨ।"]},
"GEO-IND-001-CP008-Q059":{"h":"69b26b1c","hi":["औषधि उद्योग के भूगोल में कौन-सा युग्म सही सुमेलित है?",["हैदराबाद — केवल जूट","हैदराबाद — कोकिंग कोयला","हैदराबाद — औषधि उद्योग","हैदराबाद — केवल चीनी"],"हैदराबाद औषधि विनिर्माण का प्रमुख केंद्र है।"],"pa":["ਦਵਾਈ ਉਦਯੋਗ ਦੇ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਹੈਦਰਾਬਾਦ — ਸਿਰਫ਼ ਜੂਟ","ਹੈਦਰਾਬਾਦ — ਕੋਕਿੰਗ ਕੋਲਾ","ਹੈਦਰਾਬਾਦ — ਦਵਾਈ ਉਦਯੋਗ","ਹੈਦਰਾਬਾਦ — ਸਿਰਫ਼ ਖੰਡ"],"ਹੈਦਰਾਬਾਦ ਦਵਾਈਆਂ ਬਣਾਉਣ ਦਾ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰ ਹੈ।"]},
"GEO-IND-001-CP008-Q060":{"h":"a4cf3905","hi":["औषधि संयंत्र अनुसंधान संस्थानों के पास क्यों इकट्ठे हो सकते हैं?",["उन्हें लौह अयस्क चाहिए","वे केवल खेतों पर निर्भर हैं","वे तकनीकी श्रम से बचते हैं","उन्हें वैज्ञानिक कौशल, अनुसंधान और विशिष्ट सेवाओं का लाभ मिलता है"],"ज्ञान और विशिष्ट कौशल वाले श्रमिक औषधि उद्योग की अवस्थिति के प्रमुख कारक हैं।"],"pa":["ਦਵਾਈਆਂ ਬਣਾਉਣ ਵਾਲੇ ਪਲਾਂਟ ਖੋਜ ਸੰਸਥਾਵਾਂ ਨੇੜੇ ਕਿਉਂ ਇਕੱਠੇ ਹੋ ਸਕਦੇ ਹਨ?",["ਉਨ੍ਹਾਂ ਨੂੰ ਕੱਚਾ ਲੋਹਾ ਚਾਹੀਦਾ ਹੈ","ਉਹ ਸਿਰਫ਼ ਖੇਤਾਂ 'ਤੇ ਨਿਰਭਰ ਹਨ","ਉਹ ਤਕਨੀਕੀ ਕਾਮਿਆਂ ਤੋਂ ਬਚਦੇ ਹਨ","ਉਨ੍ਹਾਂ ਨੂੰ ਵਿਗਿਆਨਕ ਹੁਨਰ, ਖੋਜ ਅਤੇ ਖ਼ਾਸ ਸੇਵਾਵਾਂ ਦਾ ਲਾਭ ਹੁੰਦਾ ਹੈ"],"ਗਿਆਨ ਅਤੇ ਖ਼ਾਸ ਹੁਨਰ ਵਾਲੇ ਕਾਮੇ ਦਵਾਈ ਉਦਯੋਗ ਦੀ ਥਾਂ ਦੀ ਚੋਣ ਦੇ ਪ੍ਰਮੁੱਖ ਕਾਰਕ ਹਨ।"]},
"GEO-IND-001-CP009-Q001":{"h":"b250b7e6","hi":["किस औद्योगिक क्षेत्र में मुंबई के पत्तन और बाज़ारों के लाभ तथा पुणे का अभियांत्रिकी आधार एक साथ मिलते हैं?",["हुगली औद्योगिक क्षेत्र","छोटानागपुर औद्योगिक क्षेत्र","कोल्लम-तिरुवनंतपुरम क्षेत्र","मुंबई-पुणे औद्योगिक क्षेत्र"],"मुंबई-पुणे पट्टी भारत के प्रमुख विविधतापूर्ण औद्योगिक क्षेत्रों में से एक है।"],"pa":["ਕਿਹੜੇ ਉਦਯੋਗਿਕ ਖੇਤਰ ਵਿੱਚ ਮੁੰਬਈ ਦੀ ਬੰਦਰਗਾਹ ਤੇ ਬਾਜ਼ਾਰਾਂ ਦੇ ਲਾਭ ਅਤੇ ਪੁਣੇ ਦਾ ਇੰਜੀਨੀਅਰਿੰਗ ਆਧਾਰ ਇਕੱਠੇ ਮਿਲਦੇ ਹਨ?",["ਹੁਗਲੀ ਉਦਯੋਗਿਕ ਖੇਤਰ","ਛੋਟਾਨਾਗਪੁਰ ਉਦਯੋਗਿਕ ਖੇਤਰ","ਕੋਲਮ-ਤਿਰੂਵਨੰਤਪੁਰਮ ਖੇਤਰ","ਮੁੰਬਈ-ਪੁਣੇ ਉਦਯੋਗਿਕ ਖੇਤਰ"],"ਮੁੰਬਈ-ਪੁਣੇ ਪੱਟੀ ਭਾਰਤ ਦੇ ਵੱਖ-ਵੱਖ ਕਿਸਮਾਂ ਦੇ ਉਦਯੋਗਾਂ ਵਾਲੇ ਪ੍ਰਮੁੱਖ ਖੇਤਰਾਂ ਵਿੱਚੋਂ ਇੱਕ ਹੈ।"]},
"GEO-IND-001-CP009-Q002":{"h":"79bbf111","hi":["मुंबई-पुणे औद्योगिक क्षेत्र किस राज्य में है?",["महाराष्ट्र","गुजरात","पश्चिम बंगाल","कर्नाटक"],"मुंबई और पुणे, दोनों महाराष्ट्र में हैं।"],"pa":["ਮੁੰਬਈ-ਪੁਣੇ ਉਦਯੋਗਿਕ ਖੇਤਰ ਕਿਹੜੇ ਰਾਜ ਵਿੱਚ ਹੈ?",["ਮਹਾਰਾਸ਼ਟਰ","ਗੁਜਰਾਤ","ਪੱਛਮੀ ਬੰਗਾਲ","ਕਰਨਾਟਕ"],"ਮੁੰਬਈ ਅਤੇ ਪੁਣੇ, ਦੋਵੇਂ ਮਹਾਰਾਸ਼ਟਰ ਵਿੱਚ ਹਨ।"]},
"GEO-IND-001-CP009-Q003":{"h":"5e05c061","hi":["मुंबई-पुणे को प्रमुख औद्योगिक क्षेत्र बनाने में कौन-से कारक सहायक रहे?",["केवल लौह अयस्क","पत्तन, बाज़ार, पूँजी, परिवहन और कुशल श्रम","केवल गन्ना","केवल वर्षा"],"पत्तन तक पहुँच, वित्त, श्रम, बाज़ार और परिवहन के संयुक्त योगदान से इस क्षेत्र का विकास हुआ।"],"pa":["ਮੁੰਬਈ-ਪੁਣੇ ਨੂੰ ਪ੍ਰਮੁੱਖ ਉਦਯੋਗਿਕ ਖੇਤਰ ਬਣਾਉਣ ਵਿੱਚ ਕਿਹੜੇ ਕਾਰਕਾਂ ਨੇ ਮਦਦ ਕੀਤੀ?",["ਸਿਰਫ਼ ਕੱਚਾ ਲੋਹਾ","ਬੰਦਰਗਾਹ, ਬਾਜ਼ਾਰ, ਪੂੰਜੀ, ਆਵਾਜਾਈ ਅਤੇ ਹੁਨਰਮੰਦ ਕਾਮੇ","ਸਿਰਫ਼ ਗੰਨਾ","ਸਿਰਫ਼ ਵਰਖਾ"],"ਬੰਦਰਗਾਹ ਤੱਕ ਪਹੁੰਚ, ਵਿੱਤ, ਕਾਮਿਆਂ, ਬਾਜ਼ਾਰਾਂ ਅਤੇ ਆਵਾਜਾਈ ਦੇ ਸਾਂਝੇ ਯੋਗਦਾਨ ਨਾਲ ਇਸ ਖੇਤਰ ਦਾ ਵਿਕਾਸ ਹੋਇਆ।"]},
"GEO-IND-001-CP009-Q004":{"h":"ec3e55a0","hi":["कथनों पर विचार कीजिए: I. मुंबई एक प्रमुख पत्तन शहर है। II. पुणे अभियांत्रिकी और मोटर वाहन उद्योग का प्रमुख केंद्र है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","I और II दोनों सही हैं","न तो I और न ही II सही है"],"दोनों शहर अपनी अलग-अलग विशेषताओं से पूरे औद्योगिक क्षेत्र को मज़बूत बनाते हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਮੁੰਬਈ ਇੱਕ ਪ੍ਰਮੁੱਖ ਬੰਦਰਗਾਹੀ ਸ਼ਹਿਰ ਹੈ। II. ਪੁਣੇ ਇੰਜੀਨੀਅਰਿੰਗ ਅਤੇ ਮੋਟਰ ਵਾਹਨ ਉਦਯੋਗ ਦਾ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਦੋਵੇਂ ਸ਼ਹਿਰ ਆਪਣੀਆਂ ਵੱਖੋ-ਵੱਖਰੀਆਂ ਖ਼ੂਬੀਆਂ ਨਾਲ ਸਮੁੱਚੇ ਉਦਯੋਗਿਕ ਖੇਤਰ ਨੂੰ ਮਜ਼ਬੂਤ ਬਣਾਉਂਦੇ ਹਨ।"]},
"GEO-IND-001-CP009-Q005":{"h":"ad794a65","hi":["कौन-सा युग्म मुंबई-पुणे औद्योगिक क्षेत्र की सही पहचान करता है?",["मुंबई-पुणे — पश्चिम बंगाल","मुंबई-पुणे — ओडिशा","मुंबई-पुणे — असम","मुंबई-पुणे — महाराष्ट्र"],"यह क्षेत्र महाराष्ट्र में है।"],"pa":["ਕਿਹੜਾ ਜੋੜਾ ਮੁੰਬਈ-ਪੁਣੇ ਉਦਯੋਗਿਕ ਖੇਤਰ ਦੀ ਸਹੀ ਪਛਾਣ ਕਰਦਾ ਹੈ?",["ਮੁੰਬਈ-ਪੁਣੇ — ਪੱਛਮੀ ਬੰਗਾਲ","ਮੁੰਬਈ-ਪੁਣੇ — ਓਡੀਸ਼ਾ","ਮੁੰਬਈ-ਪੁਣੇ — ਅਸਾਮ","ਮੁੰਬਈ-ਪੁਣੇ — ਮਹਾਰਾਸ਼ਟਰ"],"ਇਹ ਖੇਤਰ ਮਹਾਰਾਸ਼ਟਰ ਵਿੱਚ ਹੈ।"]},
"GEO-IND-001-CP009-Q006":{"h":"f64778cb","hi":["मुंबई-पुणे क्षेत्र के पुणे वाले भाग में कौन-सा उद्योग प्रमुख है?",["मोटर वाहन और अभियांत्रिकी","केवल जूट","केवल चाय प्रसंस्करण","केवल कोयला खनन"],"पुणे मोटर वाहन और अभियांत्रिकी उद्योग का प्रमुख केंद्र है।"],"pa":["ਮੁੰਬਈ-ਪੁਣੇ ਖੇਤਰ ਦੇ ਪੁਣੇ ਵਾਲੇ ਹਿੱਸੇ ਵਿੱਚ ਕਿਹੜਾ ਉਦਯੋਗ ਪ੍ਰਮੁੱਖ ਹੈ?",["ਮੋਟਰ ਵਾਹਨ ਅਤੇ ਇੰਜੀਨੀਅਰਿੰਗ","ਸਿਰਫ਼ ਜੂਟ","ਸਿਰਫ਼ ਚਾਹ ਦੀ ਪ੍ਰੋਸੈਸਿੰਗ","ਸਿਰਫ਼ ਕੋਲੇ ਦੀ ਖੁਦਾਈ"],"ਪੁਣੇ ਮੋਟਰ ਵਾਹਨ ਅਤੇ ਇੰਜੀਨੀਅਰਿੰਗ ਉਦਯੋਗ ਦਾ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰ ਹੈ।"]},
"GEO-IND-001-CP009-Q007":{"h":"b0fcb887","hi":["हुगली औद्योगिक क्षेत्र के लिए कौन-सी नदी केंद्रीय महत्व रखती है?",["नर्मदा","गोदावरी","हुगली नदी","सतलुज"],"हुगली औद्योगिक पट्टी कोलकाता के आसपास हुगली नदी के किनारे विकसित हुई।"],"pa":["ਹੁਗਲੀ ਉਦਯੋਗਿਕ ਖੇਤਰ ਲਈ ਕਿਹੜਾ ਦਰਿਆ ਮੁੱਖ ਮਹੱਤਵ ਰੱਖਦਾ ਹੈ?",["ਨਰਮਦਾ","ਗੋਦਾਵਰੀ","ਹੁਗਲੀ ਦਰਿਆ","ਸਤਲੁਜ"],"ਹੁਗਲੀ ਉਦਯੋਗਿਕ ਪੱਟੀ ਕੋਲਕਾਤਾ ਦੇ ਆਲੇ-ਦੁਆਲੇ ਹੁਗਲੀ ਦਰਿਆ ਦੇ ਕੰਢੇ ਵਿਕਸਿਤ ਹੋਈ।"]},
"GEO-IND-001-CP009-Q008":{"h":"964b4b16","hi":["हुगली औद्योगिक पट्टी में ऐतिहासिक रूप से कौन-सा उद्योग प्रमुख रहा है?",["केवल ऐलुमिनियम","केवल चीनी","केवल सीमेंट","जूट वस्त्र"],"हुगली पट्टी भारत में जूट मिलों का पारंपरिक क्षेत्र है।"],"pa":["ਹੁਗਲੀ ਉਦਯੋਗਿਕ ਪੱਟੀ ਵਿੱਚ ਇਤਿਹਾਸਕ ਤੌਰ 'ਤੇ ਕਿਹੜਾ ਉਦਯੋਗ ਪ੍ਰਮੁੱਖ ਰਿਹਾ ਹੈ?",["ਸਿਰਫ਼ ਐਲੂਮੀਨੀਅਮ","ਸਿਰਫ਼ ਖੰਡ","ਸਿਰਫ਼ ਸੀਮਿੰਟ","ਜੂਟ ਦੇ ਕੱਪੜੇ"],"ਹੁਗਲੀ ਪੱਟੀ ਭਾਰਤ ਵਿੱਚ ਜੂਟ ਮਿੱਲਾਂ ਦਾ ਰਵਾਇਤੀ ਇਲਾਕਾ ਹੈ।"]},
"GEO-IND-001-CP009-Q009":{"h":"e1d87c43","hi":["हुगली औद्योगिक क्षेत्र किस राज्य में है?",["पश्चिम बंगाल","गुजरात","तमिलनाडु","पंजाब"],"हुगली पट्टी पश्चिम बंगाल में है।"],"pa":["ਹੁਗਲੀ ਉਦਯੋਗਿਕ ਖੇਤਰ ਕਿਹੜੇ ਰਾਜ ਵਿੱਚ ਹੈ?",["ਪੱਛਮੀ ਬੰਗਾਲ","ਗੁਜਰਾਤ","ਤਾਮਿਲਨਾਡੂ","ਪੰਜਾਬ"],"ਹੁਗਲੀ ਪੱਟੀ ਪੱਛਮੀ ਬੰਗਾਲ ਵਿੱਚ ਹੈ।"]},
"GEO-IND-001-CP009-Q010":{"h":"952b5a88","hi":["कथनों पर विचार कीजिए: I. कोलकाता पत्तन हुगली क्षेत्र के विकास में सहायक रहा। II. जूट मिलें नदी के किनारे केंद्रित हुईं। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","I और II दोनों सही हैं","केवल II सही है","न तो I और न ही II सही है"],"पत्तन, नदी, श्रम और जूट की आपूर्ति, सभी ने इस क्षेत्र के विकास में योगदान दिया।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਕੋਲਕਾਤਾ ਬੰਦਰਗਾਹ ਨੇ ਹੁਗਲੀ ਖੇਤਰ ਦੇ ਵਿਕਾਸ ਵਿੱਚ ਮਦਦ ਕੀਤੀ। II. ਜੂਟ ਮਿੱਲਾਂ ਦਰਿਆ ਦੇ ਕੰਢੇ ਕੇਂਦਰਿਤ ਹੋਈਆਂ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਬੰਦਰਗਾਹ, ਦਰਿਆ, ਕਾਮਿਆਂ ਅਤੇ ਜੂਟ ਦੀ ਸਪਲਾਈ, ਸਾਰਿਆਂ ਨੇ ਖੇਤਰ ਦੇ ਵਿਕਾਸ ਵਿੱਚ ਮਦਦ ਕੀਤੀ।"]},
"GEO-IND-001-CP009-Q011":{"h":"ec51cc1f","hi":["कौन-सा युग्म हुगली औद्योगिक क्षेत्र की सही पहचान करता है?",["हुगली — राजस्थान","हुगली — कर्नाटक","हुगली — पश्चिम बंगाल","हुगली — पंजाब"],"हुगली औद्योगिक क्षेत्र पश्चिम बंगाल में है।"],"pa":["ਕਿਹੜਾ ਜੋੜਾ ਹੁਗਲੀ ਉਦਯੋਗਿਕ ਖੇਤਰ ਦੀ ਸਹੀ ਪਛਾਣ ਕਰਦਾ ਹੈ?",["ਹੁਗਲੀ — ਰਾਜਸਥਾਨ","ਹੁਗਲੀ — ਕਰਨਾਟਕ","ਹੁਗਲੀ — ਪੱਛਮੀ ਬੰਗਾਲ","ਹੁਗਲੀ — ਪੰਜਾਬ"],"ਹੁਗਲੀ ਉਦਯੋਗਿਕ ਖੇਤਰ ਪੱਛਮੀ ਬੰਗਾਲ ਵਿੱਚ ਹੈ।"]},
"GEO-IND-001-CP009-Q012":{"h":"c1b2a61f","hi":["हुगली क्षेत्र में बड़े पैमाने पर औद्योगीकरण क्यों हुआ?",["वहाँ परिवहन नहीं था","वह केवल पर्यटन पर निर्भर था","केवल जलवायु का महत्व था","पत्तन और कोयले तक पहुँच थी और श्रम, परिवहन व कच्चा माल उपलब्ध थे"],"इस क्षेत्र में औद्योगिक अवस्थिति के कई लाभ एक साथ उपलब्ध थे।"],"pa":["ਹੁਗਲੀ ਖੇਤਰ ਵਿੱਚ ਵੱਡੇ ਪੱਧਰ 'ਤੇ ਉਦਯੋਗੀਕਰਨ ਕਿਉਂ ਹੋਇਆ?",["ਉੱਥੇ ਆਵਾਜਾਈ ਨਹੀਂ ਸੀ","ਇਹ ਸਿਰਫ਼ ਸੈਰ-ਸਪਾਟੇ 'ਤੇ ਨਿਰਭਰ ਸੀ","ਸਿਰਫ਼ ਜਲਵਾਯੂ ਦਾ ਮਹੱਤਵ ਸੀ","ਬੰਦਰਗਾਹ, ਕੋਲੇ ਤੱਕ ਪਹੁੰਚ, ਕਾਮੇ, ਆਵਾਜਾਈ ਅਤੇ ਕੱਚਾ ਮਾਲ ਮਿਲਦੇ ਸਨ"],"ਇਸ ਖੇਤਰ ਵਿੱਚ ਉਦਯੋਗ ਲਾਉਣ ਲਈ ਥਾਂ ਦੇ ਕਈ ਲਾਭ ਇਕੱਠੇ ਮਿਲਦੇ ਸਨ।"]},
"GEO-IND-001-CP009-Q013":{"h":"394c5ecf","hi":["कौन-सा औद्योगिक क्षेत्र भारत की प्रमुख कोयला और लौह अयस्क पट्टी पर केंद्रित है?",["मुंबई-पुणे क्षेत्र","हुगली क्षेत्र","कोल्लम-तिरुवनंतपुरम क्षेत्र","छोटानागपुर औद्योगिक क्षेत्र"],"छोटानागपुर में कोयला, लौह अयस्क, इस्पात संयंत्र और भारी अभियांत्रिकी उद्योग एक साथ मिलते हैं।"],"pa":["ਕਿਹੜਾ ਉਦਯੋਗਿਕ ਖੇਤਰ ਭਾਰਤ ਦੀ ਪ੍ਰਮੁੱਖ ਕੋਲਾ ਅਤੇ ਕੱਚੇ ਲੋਹੇ ਦੀ ਪੱਟੀ ਵਿੱਚ ਕੇਂਦਰਿਤ ਹੈ?",["ਮੁੰਬਈ-ਪੁਣੇ ਖੇਤਰ","ਹੁਗਲੀ ਖੇਤਰ","ਕੋਲਮ-ਤਿਰੂਵਨੰਤਪੁਰਮ ਖੇਤਰ","ਛੋਟਾਨਾਗਪੁਰ ਉਦਯੋਗਿਕ ਖੇਤਰ"],"ਛੋਟਾਨਾਗਪੁਰ ਵਿੱਚ ਕੋਲਾ, ਕੱਚਾ ਲੋਹਾ, ਸਟੀਲ ਪਲਾਂਟ ਅਤੇ ਭਾਰੀ ਇੰਜੀਨੀਅਰਿੰਗ ਉਦਯੋਗ ਇਕੱਠੇ ਮਿਲਦੇ ਹਨ।"]},
"GEO-IND-001-CP009-Q014":{"h":"f4265e7e","hi":["छोटानागपुर औद्योगिक क्षेत्र में कौन-से उद्योग प्रमुख हैं?",["लौह-इस्पात, अभियांत्रिकी और खनिज आधारित उद्योग","केवल जूट","केवल चीनी","केवल चाय"],"इस क्षेत्र के खनिज संसाधन भारी उद्योगों और धातुकर्म को आधार देते हैं।"],"pa":["ਛੋਟਾਨਾਗਪੁਰ ਉਦਯੋਗਿਕ ਖੇਤਰ ਵਿੱਚ ਕਿਹੜੇ ਉਦਯੋਗ ਪ੍ਰਮੁੱਖ ਹਨ?",["ਲੋਹਾ-ਸਟੀਲ, ਇੰਜੀਨੀਅਰਿੰਗ ਅਤੇ ਖਣਿਜ-ਆਧਾਰਿਤ ਉਦਯੋਗ","ਸਿਰਫ਼ ਜੂਟ","ਸਿਰਫ਼ ਖੰਡ","ਸਿਰਫ਼ ਚਾਹ"],"ਇਸ ਖੇਤਰ ਦੇ ਖਣਿਜ ਸਰੋਤ ਭਾਰੀ ਉਦਯੋਗਾਂ ਅਤੇ ਧਾਤਕਾਰੀ ਨੂੰ ਆਧਾਰ ਦਿੰਦੇ ਹਨ।"]},
"GEO-IND-001-CP009-Q015":{"h":"adaa32c6","hi":["छोटानागपुर की खनिज-औद्योगिक पट्टी में कौन-से राज्य प्रमुख रूप से शामिल हैं?",["केवल केरल और गोवा","झारखंड, ओडिशा और उनसे सटे पूर्वी-मध्य राज्य","केवल पंजाब और हरियाणा","केवल असम और मेघालय"],"औद्योगिक पट्टी पूर्वी खनिज क्षेत्र में फैली है।"],"pa":["ਛੋਟਾਨਾਗਪੁਰ ਦੀ ਖਣਿਜ-ਉਦਯੋਗਿਕ ਪੱਟੀ ਵਿੱਚ ਕਿਹੜੇ ਰਾਜ ਪ੍ਰਮੁੱਖ ਤੌਰ 'ਤੇ ਸ਼ਾਮਲ ਹਨ?",["ਸਿਰਫ਼ ਕੇਰਲ ਅਤੇ ਗੋਆ","ਝਾਰਖੰਡ, ਓਡੀਸ਼ਾ ਅਤੇ ਨਾਲ ਲੱਗਦੇ ਪੂਰਬੀ-ਕੇਂਦਰੀ ਰਾਜ","ਸਿਰਫ਼ ਪੰਜਾਬ ਅਤੇ ਹਰਿਆਣਾ","ਸਿਰਫ਼ ਅਸਾਮ ਅਤੇ ਮੇਘਾਲਿਆ"],"ਉਦਯੋਗਿਕ ਪੱਟੀ ਪੂਰਬੀ ਖਣਿਜ ਖੇਤਰ ਵਿੱਚ ਫੈਲੀ ਹੋਈ ਹੈ।"]},
"GEO-IND-001-CP009-Q016":{"h":"39d8a2cf","hi":["कथनों पर विचार कीजिए: I. जमशेदपुर इस क्षेत्र में है। II. कोयला और लौह अयस्क इसकी अवस्थिति के प्रमुख लाभ हैं। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","I और II दोनों सही हैं","न तो I और न ही II सही है"],"दोनों तथ्य छोटानागपुर के औद्योगिक भूगोल के लिए महत्वपूर्ण हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਜਮਸ਼ੇਦਪੁਰ ਇਸ ਖੇਤਰ ਵਿੱਚ ਹੈ। II. ਕੋਲਾ ਅਤੇ ਕੱਚਾ ਲੋਹਾ ਇਸ ਥਾਂ ਦੇ ਪ੍ਰਮੁੱਖ ਲਾਭ ਹਨ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਦੋਵੇਂ ਤੱਥ ਛੋਟਾਨਾਗਪੁਰ ਦੇ ਉਦਯੋਗਿਕ ਭੂਗੋਲ ਲਈ ਅਹਿਮ ਹਨ।"]},
"GEO-IND-001-CP009-Q017":{"h":"b2a7567d","hi":["कौन-सा युग्म छोटानागपुर औद्योगिक क्षेत्र की सही पहचान करता है?",["छोटानागपुर — केवल जूट","छोटानागपुर — खनिजों का अभाव","छोटानागपुर — केवल चीनी","छोटानागपुर — खनिज आधारित भारी उद्योग"],"इस क्षेत्र में खनिज आधारित भारी उद्योग प्रमुख हैं।"],"pa":["ਕਿਹੜਾ ਜੋੜਾ ਛੋਟਾਨਾਗਪੁਰ ਉਦਯੋਗਿਕ ਖੇਤਰ ਦੀ ਸਹੀ ਪਛਾਣ ਕਰਦਾ ਹੈ?",["ਛੋਟਾਨਾਗਪੁਰ — ਸਿਰਫ਼ ਜੂਟ","ਛੋਟਾਨਾਗਪੁਰ — ਖਣਿਜਾਂ ਦੀ ਅਣਹੋਂਦ","ਛੋਟਾਨਾਗਪੁਰ — ਸਿਰਫ਼ ਖੰਡ","ਛੋਟਾਨਾਗਪੁਰ — ਖਣਿਜ-ਆਧਾਰਿਤ ਭਾਰੀ ਉਦਯੋਗ"],"ਇਸ ਖੇਤਰ ਵਿੱਚ ਖਣਿਜਾਂ 'ਤੇ ਆਧਾਰਿਤ ਭਾਰੀ ਉਦਯੋਗ ਪ੍ਰਮੁੱਖ ਹਨ।"]},
"GEO-IND-001-CP009-Q018":{"h":"f53d2bde","hi":["छोटानागपुर संसाधन-उन्मुख औद्योगिक पट्टी का पारंपरिक उदाहरण क्यों है?",["प्रमुख खनिज और ऊर्जा संसाधन एक-दूसरे के पास मिलते हैं","वहाँ कोयला नहीं है","वहाँ लौह अयस्क नहीं है","केवल पत्तनों का महत्व है"],"कोयला, लौह अयस्क और अन्य खनिज पास-पास पाए जाते हैं। इससे भारी उद्योगों को आधार मिलता है।"],"pa":["ਛੋਟਾਨਾਗਪੁਰ ਸਰੋਤਾਂ 'ਤੇ ਆਧਾਰਿਤ ਉਦਯੋਗਿਕ ਪੱਟੀ ਦੀ ਰਵਾਇਤੀ ਉਦਾਹਰਨ ਕਿਉਂ ਹੈ?",["ਪ੍ਰਮੁੱਖ ਖਣਿਜ ਅਤੇ ਊਰਜਾ ਸਰੋਤ ਨੇੜੇ-ਨੇੜੇ ਮਿਲਦੇ ਹਨ","ਉੱਥੇ ਕੋਲਾ ਨਹੀਂ ਹੈ","ਉੱਥੇ ਕੱਚਾ ਲੋਹਾ ਨਹੀਂ ਹੈ","ਸਿਰਫ਼ ਬੰਦਰਗਾਹਾਂ ਦਾ ਮਹੱਤਵ ਹੈ"],"ਕੋਲਾ, ਕੱਚਾ ਲੋਹਾ ਅਤੇ ਹੋਰ ਖਣਿਜ ਨੇੜੇ-ਨੇੜੇ ਮਿਲਦੇ ਹਨ। ਇਸ ਨਾਲ ਭਾਰੀ ਉਦਯੋਗਾਂ ਨੂੰ ਆਧਾਰ ਮਿਲਦਾ ਹੈ।"]},
"GEO-IND-001-CP009-Q019":{"h":"5820e2da","hi":["किस औद्योगिक क्षेत्र का अहमदाबाद, वडोदरा और सूरत से गहरा संबंध है?",["हुगली क्षेत्र","छोटानागपुर क्षेत्र","कोल्लम क्षेत्र","गुजरात औद्योगिक क्षेत्र"],"अहमदाबाद, वडोदरा और सूरत गुजरात के प्रमुख औद्योगिक केंद्र हैं।"],"pa":["ਕਿਹੜਾ ਉਦਯੋਗਿਕ ਖੇਤਰ ਅਹਿਮਦਾਬਾਦ, ਵਡੋਦਰਾ ਅਤੇ ਸੂਰਤ ਨਾਲ ਨੇੜਿਓਂ ਜੁੜਿਆ ਹੈ?",["ਹੁਗਲੀ ਖੇਤਰ","ਛੋਟਾਨਾਗਪੁਰ ਖੇਤਰ","ਕੋਲਮ ਖੇਤਰ","ਗੁਜਰਾਤ ਉਦਯੋਗਿਕ ਖੇਤਰ"],"ਅਹਿਮਦਾਬਾਦ, ਵਡੋਦਰਾ ਅਤੇ ਸੂਰਤ ਗੁਜਰਾਤ ਦੇ ਪ੍ਰਮੁੱਖ ਉਦਯੋਗਿਕ ਕੇਂਦਰ ਹਨ।"]},
"GEO-IND-001-CP009-Q020":{"h":"889d75e0","hi":["गुजरात के औद्योगिक क्षेत्र में कौन-से उद्योग प्रमुख हैं?",["वस्त्र, रसायन, पेट्रोरसायन और अभियांत्रिकी","केवल जूट","केवल चाय","केवल कोयला खनन"],"गुजरात के विविध उद्योगों को पत्तनों, शोधनशालाओं और बाज़ारों से आधार मिलता है।"],"pa":["ਗੁਜਰਾਤ ਦੇ ਉਦਯੋਗਿਕ ਖੇਤਰ ਵਿੱਚ ਕਿਹੜੇ ਉਦਯੋਗ ਪ੍ਰਮੁੱਖ ਹਨ?",["ਕੱਪੜਾ, ਰਸਾਇਣ, ਪੈਟਰੋ-ਰਸਾਇਣ ਅਤੇ ਇੰਜੀਨੀਅਰਿੰਗ","ਸਿਰਫ਼ ਜੂਟ","ਸਿਰਫ਼ ਚਾਹ","ਸਿਰਫ਼ ਕੋਲੇ ਦੀ ਖੁਦਾਈ"],"ਗੁਜਰਾਤ ਦੇ ਵੱਖ-ਵੱਖ ਉਦਯੋਗਾਂ ਨੂੰ ਬੰਦਰਗਾਹਾਂ, ਰਿਫ਼ਾਇਨਰੀਆਂ ਅਤੇ ਬਾਜ਼ਾਰਾਂ ਤੋਂ ਸਹਾਰਾ ਮਿਲਦਾ ਹੈ।"]},
"GEO-IND-001-CP009-Q021":{"h":"d8812f52","hi":["कौन-सा अवस्थितिक कारक गुजरात के औद्योगिक क्षेत्र को विशेष रूप से मज़बूत बनाता है?",["केवल हिमावरण","पत्तन तक पहुँच और तेल शोधन व पेट्रोरसायन की सुविधाएँ","केवल वन उत्पाद","केवल लौह अयस्क"],"पत्तन और हाइड्रोकार्बन संबंधी आधारभूत संरचना प्रमुख लाभ हैं।"],"pa":["ਕਿਹੜਾ ਸਥਾਨਕ ਕਾਰਕ ਗੁਜਰਾਤ ਦੇ ਉਦਯੋਗਿਕ ਖੇਤਰ ਨੂੰ ਖ਼ਾਸ ਤੌਰ 'ਤੇ ਮਜ਼ਬੂਤ ਬਣਾਉਂਦਾ ਹੈ?",["ਸਿਰਫ਼ ਬਰਫ਼ ਦੀ ਪਰਤ","ਬੰਦਰਗਾਹ ਤੱਕ ਪਹੁੰਚ ਅਤੇ ਤੇਲ ਸੋਧਾਈ ਤੇ ਪੈਟਰੋ-ਰਸਾਇਣਾਂ ਦੀਆਂ ਸਹੂਲਤਾਂ","ਸਿਰਫ਼ ਜੰਗਲੀ ਉਤਪਾਦ","ਸਿਰਫ਼ ਕੱਚਾ ਲੋਹਾ"],"ਬੰਦਰਗਾਹਾਂ ਅਤੇ ਹਾਈਡ੍ਰੋਕਾਰਬਨਾਂ ਲਈ ਬੁਨਿਆਦੀ ਢਾਂਚਾ ਪ੍ਰਮੁੱਖ ਲਾਭ ਹਨ।"]},
"GEO-IND-001-CP009-Q022":{"h":"642951cc","hi":["कथनों पर विचार कीजिए: I. अहमदाबाद वस्त्र उद्योग का केंद्र है। II. सूरत संश्लेषित रेशों के वस्त्रों के लिए महत्वपूर्ण है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","I और II दोनों सही हैं","न तो I और न ही II सही है"],"दोनों प्रमुख वस्त्र केंद्र हैं और उनकी विशेषज्ञताएँ अलग-अलग हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਅਹਿਮਦਾਬਾਦ ਕੱਪੜਾ ਉਦਯੋਗ ਦਾ ਕੇਂਦਰ ਹੈ। II. ਸੂਰਤ ਬਣਾਵਟੀ ਰੇਸ਼ਿਆਂ ਦੇ ਕੱਪੜਿਆਂ ਲਈ ਅਹਿਮ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਦੋਵੇਂ ਕੱਪੜਾ ਉਦਯੋਗ ਦੇ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰ ਹਨ ਅਤੇ ਦੋਵਾਂ ਦੀ ਵੱਖੋ-ਵੱਖਰੇ ਕੰਮਾਂ ਵਿੱਚ ਮੁਹਾਰਤ ਹੈ।"]},
"GEO-IND-001-CP009-Q023":{"h":"e744c6d0","hi":["कौन-सा युग्म बेंगलुरु-तमिलनाडु औद्योगिक क्षेत्र की सही पहचान करता है?",["गुजरात — केवल जूट","गुजरात — पत्तनों का अभाव","गुजरात — रसायनों का अभाव","गुजरात — वस्त्र और पेट्रोरसायन"],"राज्य में प्रमुख वस्त्र और पेट्रोरसायन उद्योग हैं।"],"pa":["ਕਿਹੜਾ ਜੋੜਾ ਬੈਂਗਲੁਰੂ-ਤਾਮਿਲਨਾਡੂ ਉਦਯੋਗਿਕ ਖੇਤਰ ਦੀ ਸਹੀ ਪਛਾਣ ਕਰਦਾ ਹੈ?",["ਗੁਜਰਾਤ — ਸਿਰਫ਼ ਜੂਟ","ਗੁਜਰਾਤ — ਬੰਦਰਗਾਹਾਂ ਦੀ ਅਣਹੋਂਦ","ਗੁਜਰਾਤ — ਰਸਾਇਣਾਂ ਦੀ ਅਣਹੋਂਦ","ਗੁਜਰਾਤ — ਕੱਪੜਾ ਅਤੇ ਪੈਟਰੋ-ਰਸਾਇਣ"],"ਇਸ ਰਾਜ ਵਿੱਚ ਕੱਪੜੇ ਅਤੇ ਪੈਟਰੋ-ਰਸਾਇਣਾਂ ਦੇ ਪ੍ਰਮੁੱਖ ਉਦਯੋਗ ਹਨ।"]},
"GEO-IND-001-CP009-Q024":{"h":"cdd5c959","hi":["गुजरात का कौन-सा शहर संश्लेषित रेशों के वस्त्रों के लिए विशेष रूप से महत्वपूर्ण है?",["सूरत","धनबाद","राउरकेला","झरिया"],"सूरत भारत के प्रमुख संश्लेषित रेशा वस्त्र केंद्रों में से एक है।"],"pa":["ਗੁਜਰਾਤ ਦਾ ਕਿਹੜਾ ਸ਼ਹਿਰ ਬਣਾਵਟੀ ਰੇਸ਼ਿਆਂ ਦੇ ਕੱਪੜਿਆਂ ਲਈ ਖ਼ਾਸ ਤੌਰ 'ਤੇ ਅਹਿਮ ਹੈ?",["ਸੂਰਤ","ਧਨਬਾਦ","ਰਾਉਰਕੇਲਾ","ਝਰੀਆ"],"ਸੂਰਤ ਭਾਰਤ ਵਿੱਚ ਬਣਾਵਟੀ ਰੇਸ਼ਿਆਂ ਦੇ ਕੱਪੜਿਆਂ ਦੇ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰਾਂ ਵਿੱਚੋਂ ਇੱਕ ਹੈ।"]},
"GEO-IND-001-CP009-Q025":{"h":"0c544f0d","hi":["कौन-सा औद्योगिक क्षेत्र बेंगलुरु के अभियांत्रिकी आधार को तमिलनाडु के मोटर वाहन और वस्त्र संकुलों से जोड़ता है?",["हुगली औद्योगिक क्षेत्र","बेंगलुरु-तमिलनाडु औद्योगिक क्षेत्र","छोटानागपुर औद्योगिक क्षेत्र","केवल मुंबई-पुणे"],"दक्षिणी प्रायद्वीप में उद्योगों की एक विस्तृत पट्टी बेंगलुरु को तमिलनाडु के प्रमुख केंद्रों से जोड़ती है।"],"pa":["ਕਿਹੜਾ ਉਦਯੋਗਿਕ ਖੇਤਰ ਬੈਂਗਲੁਰੂ ਦੇ ਇੰਜੀਨੀਅਰਿੰਗ ਆਧਾਰ ਨੂੰ ਤਾਮਿਲਨਾਡੂ ਦੇ ਮੋਟਰ ਵਾਹਨ ਅਤੇ ਕੱਪੜਾ ਉਦਯੋਗ ਦੇ ਗੁੱਛਾਂ ਨਾਲ ਜੋੜਦਾ ਹੈ?",["ਹੁਗਲੀ ਉਦਯੋਗਿਕ ਖੇਤਰ","ਬੈਂਗਲੁਰੂ-ਤਾਮਿਲਨਾਡੂ ਉਦਯੋਗਿਕ ਖੇਤਰ","ਛੋਟਾਨਾਗਪੁਰ ਉਦਯੋਗਿਕ ਖੇਤਰ","ਸਿਰਫ਼ ਮੁੰਬਈ-ਪੁਣੇ"],"ਦੱਖਣੀ ਪ੍ਰਾਇਦੀਪ ਵਿੱਚ ਉਦਯੋਗਾਂ ਦੀ ਇੱਕ ਵੱਡੀ ਪੱਟੀ ਬੈਂਗਲੁਰੂ ਨੂੰ ਤਾਮਿਲਨਾਡੂ ਦੇ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰਾਂ ਨਾਲ ਜੋੜਦੀ ਹੈ।"]},
"GEO-IND-001-CP009-Q026":{"h":"a4f7805f","hi":["इस दक्षिणी औद्योगिक क्षेत्र में कौन-से उद्योग प्रमुख हैं?",["केवल जूट","केवल कोयला खनन","अभियांत्रिकी, मोटर वाहन, वस्त्र और उच्च प्रौद्योगिकी विनिर्माण","केवल चीनी"],"क्षेत्र में अभियांत्रिकी और विनिर्माण की कई शाखाएँ हैं।"],"pa":["ਇਸ ਦੱਖਣੀ ਉਦਯੋਗਿਕ ਖੇਤਰ ਵਿੱਚ ਕਿਹੜੇ ਉਦਯੋਗ ਪ੍ਰਮੁੱਖ ਹਨ?",["ਸਿਰਫ਼ ਜੂਟ","ਸਿਰਫ਼ ਕੋਲੇ ਦੀ ਖੁਦਾਈ","ਇੰਜੀਨੀਅਰਿੰਗ, ਮੋਟਰ ਵਾਹਨ, ਕੱਪੜਾ ਅਤੇ ਉੱਚ ਤਕਨਾਲੋਜੀ ਵਾਲਾ ਨਿਰਮਾਣ","ਸਿਰਫ਼ ਖੰਡ"],"ਇਸ ਖੇਤਰ ਵਿੱਚ ਇੰਜੀਨੀਅਰਿੰਗ ਅਤੇ ਨਿਰਮਾਣ ਦੀਆਂ ਕਈ ਸ਼ਾਖਾਵਾਂ ਹਨ।"]},
"GEO-IND-001-CP009-Q027":{"h":"cb18dd4c","hi":["कथनों पर विचार कीजिए: I. बेंगलुरु अभियांत्रिकी का प्रमुख केंद्र है। II. चेन्नई मोटर वाहन उद्योग का प्रमुख केंद्र है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","न तो I और न ही II सही है","I और II दोनों सही हैं"],"दोनों शहर दक्षिण भारत के औद्योगिक भूगोल के प्रमुख केंद्र हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਬੈਂਗਲੁਰੂ ਇੰਜੀਨੀਅਰਿੰਗ ਦਾ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰ ਹੈ। II. ਚੇਨਈ ਮੋਟਰ ਵਾਹਨ ਉਦਯੋਗ ਦਾ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ"],"ਦੋਵੇਂ ਸ਼ਹਿਰ ਦੱਖਣੀ ਭਾਰਤ ਦੇ ਉਦਯੋਗਿਕ ਭੂਗੋਲ ਦੇ ਮੁੱਖ ਕੇਂਦਰ ਹਨ।"]},
"GEO-IND-001-CP009-Q028":{"h":"9fdb6600","hi":["दक्षिण भारत के औद्योगिक भूगोल में कौन-सा युग्म सही सुमेलित है?",["बेंगलुरु — अभियांत्रिकी और वायु-अंतरिक्ष","बेंगलुरु — केवल जूट","चेन्नई — कोयला क्षेत्र","कोयंबटूर — पेट्रोलियम क्षेत्र"],"बेंगलुरु अभियांत्रिकी और वायु-अंतरिक्ष उद्योग का प्रमुख केंद्र है।"],"pa":["ਦੱਖਣੀ ਭਾਰਤ ਦੇ ਉਦਯੋਗਿਕ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਬੈਂਗਲੁਰੂ — ਇੰਜੀਨੀਅਰਿੰਗ ਅਤੇ ਹਵਾਈ ਤੇ ਪੁਲਾੜ ਉਦਯੋਗ","ਬੈਂਗਲੁਰੂ — ਸਿਰਫ਼ ਜੂਟ","ਚੇਨਈ — ਕੋਲਾ ਖੇਤਰ","ਕੋਇੰਬਟੂਰ — ਪੈਟਰੋਲੀਅਮ ਖੇਤਰ"],"ਬੈਂਗਲੁਰੂ ਇੰਜੀਨੀਅਰਿੰਗ ਅਤੇ ਹਵਾਈ ਤੇ ਪੁਲਾੜ ਉਦਯੋਗ ਦਾ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰ ਹੈ।"]},
"GEO-IND-001-CP009-Q029":{"h":"5ce04c61","hi":["तमिलनाडु का कौन-सा शहर मोटर वाहन उद्योग के लिए विशेष रूप से महत्वपूर्ण है?",["झरिया","चेन्नई","कोडरमा","सांभर"],"चेन्नई भारत के सबसे बड़े मोटर वाहन संकुलों में से एक का मुख्य केंद्र है।"],"pa":["ਤਾਮਿਲਨਾਡੂ ਦਾ ਕਿਹੜਾ ਸ਼ਹਿਰ ਮੋਟਰ ਵਾਹਨ ਉਦਯੋਗ ਲਈ ਖ਼ਾਸ ਤੌਰ 'ਤੇ ਅਹਿਮ ਹੈ?",["ਝਰੀਆ","ਚੇਨਈ","ਕੋਡਰਮਾ","ਸਾਂਭਰ"],"ਚੇਨਈ ਭਾਰਤ ਦੇ ਸਭ ਤੋਂ ਵੱਡੇ ਮੋਟਰ ਵਾਹਨ ਉਦਯੋਗਿਕ ਗੁੱਛਾਂ ਵਿੱਚੋਂ ਇੱਕ ਦਾ ਮੁੱਖ ਕੇਂਦਰ ਹੈ।"]},
"GEO-IND-001-CP009-Q030":{"h":"3682bc36","hi":["पूर्वी भारत की पारंपरिक कोयला-इस्पात पट्टी से दूर होने के बावजूद इस क्षेत्र का विकास क्यों हुआ?",["यहाँ कोई उद्योग नहीं है","केवल खनिजों का महत्व है","कुशल श्रम, बाज़ार, आधारभूत संरचना और आधुनिक परिवहन से कोयला क्षेत्रों की निकटता पर निर्भरता घटती है","पत्तन विकास रोकते हैं"],"आधुनिक उद्योग अक्सर कोयला क्षेत्रों तक सीधी पहुँच की तुलना में कौशल, बाज़ारों और आधारभूत संरचना पर अधिक निर्भर होते हैं।"],"pa":["ਪੂਰਬੀ ਭਾਰਤ ਦੀ ਰਵਾਇਤੀ ਕੋਲਾ-ਸਟੀਲ ਪੱਟੀ ਤੋਂ ਦੂਰ ਹੋਣ ਦੇ ਬਾਵਜੂਦ ਇਸ ਖੇਤਰ ਦਾ ਵਿਕਾਸ ਕਿਉਂ ਹੋਇਆ?",["ਇੱਥੇ ਕੋਈ ਉਦਯੋਗ ਨਹੀਂ ਹੈ","ਸਿਰਫ਼ ਖਣਿਜਾਂ ਦਾ ਮਹੱਤਵ ਹੈ","ਹੁਨਰਮੰਦ ਕਾਮੇ, ਬਾਜ਼ਾਰ, ਬੁਨਿਆਦੀ ਢਾਂਚਾ ਅਤੇ ਆਧੁਨਿਕ ਆਵਾਜਾਈ ਕੋਲਾ ਖੇਤਰਾਂ ਦੀ ਨੇੜਤਾ 'ਤੇ ਨਿਰਭਰਤਾ ਘਟਾਉਂਦੇ ਹਨ","ਬੰਦਰਗਾਹਾਂ ਵਿਕਾਸ ਰੋਕਦੀਆਂ ਹਨ"],"ਆਧੁਨਿਕ ਉਦਯੋਗ ਅਕਸਰ ਕੋਲਾ ਖੇਤਰਾਂ ਤੱਕ ਸਿੱਧੀ ਪਹੁੰਚ ਨਾਲੋਂ ਹੁਨਰ, ਬਾਜ਼ਾਰਾਂ ਅਤੇ ਬੁਨਿਆਦੀ ਢਾਂਚੇ 'ਤੇ ਵੱਧ ਨਿਰਭਰ ਕਰਦੇ ਹਨ।"]},
"GEO-IND-001-CP009-Q031":{"h":"f7fc15f0","hi":["कौन-सा तटीय औद्योगिक क्षेत्र विशाखापत्तनम पर केंद्रित है और आंध्र प्रदेश के कुछ हिस्सों में फैला है?",["हुगली क्षेत्र","मुंबई-पुणे क्षेत्र","छोटानागपुर क्षेत्र","विशाखापत्तनम-गुंटूर औद्योगिक क्षेत्र"],"विशाखापत्तनम-गुंटूर पट्टी आंध्र प्रदेश का एक मान्य औद्योगिक क्षेत्र है।"],"pa":["ਕਿਹੜਾ ਤੱਟੀ ਉਦਯੋਗਿਕ ਖੇਤਰ ਵਿਸ਼ਾਖਾਪਟਨਮ ਦੇ ਦੁਆਲੇ ਕੇਂਦਰਿਤ ਹੈ ਅਤੇ ਆਂਧਰਾ ਪ੍ਰਦੇਸ਼ ਦੇ ਕੁਝ ਹਿੱਸਿਆਂ ਵਿੱਚ ਫੈਲਿਆ ਹੈ?",["ਹੁਗਲੀ ਖੇਤਰ","ਮੁੰਬਈ-ਪੁਣੇ ਖੇਤਰ","ਛੋਟਾਨਾਗਪੁਰ ਖੇਤਰ","ਵਿਸ਼ਾਖਾਪਟਨਮ-ਗੁੰਟੂਰ ਉਦਯੋਗਿਕ ਖੇਤਰ"],"ਵਿਸ਼ਾਖਾਪਟਨਮ-ਗੁੰਟੂਰ ਪੱਟੀ ਆਂਧਰਾ ਪ੍ਰਦੇਸ਼ ਦਾ ਇੱਕ ਮੰਨਿਆ-ਪ੍ਰਮੰਨਿਆ ਉਦਯੋਗਿਕ ਖੇਤਰ ਹੈ।"]},
"GEO-IND-001-CP009-Q032":{"h":"ad2d9267","hi":["विशाखापत्तनम के औद्योगिक विकास को किस कारक से विशेष सहारा मिलता है?",["प्रमुख पत्तन तक पहुँच","केवल जूट की खेती","परिवहन का अभाव","केवल वर्षा"],"पत्तन से बड़ी मात्रा में माल की ढुलाई, इस्पात, पेट्रोलियम और अन्य औद्योगिक गतिविधियों में मदद मिलती है।"],"pa":["ਕਿਹੜਾ ਕਾਰਕ ਵਿਸ਼ਾਖਾਪਟਨਮ ਦੇ ਉਦਯੋਗਿਕ ਵਿਕਾਸ ਨੂੰ ਖ਼ਾਸ ਸਹਾਰਾ ਦਿੰਦਾ ਹੈ?",["ਪ੍ਰਮੁੱਖ ਬੰਦਰਗਾਹ ਤੱਕ ਪਹੁੰਚ","ਸਿਰਫ਼ ਜੂਟ ਦੀ ਖੇਤੀ","ਆਵਾਜਾਈ ਦੀ ਅਣਹੋਂਦ","ਸਿਰਫ਼ ਵਰਖਾ"],"ਬੰਦਰਗਾਹ ਵੱਡੀਆਂ ਖੇਪਾਂ ਢੋਣ, ਸਟੀਲ, ਪੈਟਰੋਲੀਅਮ ਅਤੇ ਹੋਰ ਉਦਯੋਗਿਕ ਕੰਮਾਂ ਵਿੱਚ ਮਦਦ ਕਰਦੀ ਹੈ।"]},
"GEO-IND-001-CP009-Q033":{"h":"8264e2d3","hi":["कथनों पर विचार कीजिए: I. विशाखापत्तनम एक प्रमुख पत्तन है। II. वहाँ इस्पात और अन्य औद्योगिक गतिविधियाँ बड़े पैमाने पर होती हैं। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","I और II दोनों सही हैं","केवल II सही है","न तो I और न ही II सही है"],"दोनों इस क्षेत्र की प्रमुख विशेषताएँ हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਵਿਸ਼ਾਖਾਪਟਨਮ ਇੱਕ ਪ੍ਰਮੁੱਖ ਬੰਦਰਗਾਹ ਹੈ। II. ਇੱਥੇ ਸਟੀਲ ਅਤੇ ਹੋਰ ਉਦਯੋਗਿਕ ਸਰਗਰਮੀਆਂ ਵੱਡੇ ਪੱਧਰ 'ਤੇ ਹੁੰਦੀਆਂ ਹਨ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਦੋਵੇਂ ਇਸ ਖੇਤਰ ਦੀਆਂ ਮੁੱਖ ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ ਹਨ।"]},
"GEO-IND-001-CP009-Q034":{"h":"89e22ee0","hi":["कौन-सा युग्म विशाखापत्तनम-गुंटूर औद्योगिक क्षेत्र की सही पहचान करता है?",["विशाखापत्तनम-गुंटूर — पंजाब","विशाखापत्तनम-गुंटूर — राजस्थान","विशाखापत्तनम-गुंटूर — आंध्र प्रदेश","विशाखापत्तनम-गुंटूर — असम"],"यह क्षेत्र आंध्र प्रदेश में है।"],"pa":["ਕਿਹੜਾ ਜੋੜਾ ਵਿਸ਼ਾਖਾਪਟਨਮ-ਗੁੰਟੂਰ ਉਦਯੋਗਿਕ ਖੇਤਰ ਦੀ ਸਹੀ ਪਛਾਣ ਕਰਦਾ ਹੈ?",["ਵਿਸ਼ਾਖਾਪਟਨਮ-ਗੁੰਟੂਰ — ਪੰਜਾਬ","ਵਿਸ਼ਾਖਾਪਟਨਮ-ਗੁੰਟੂਰ — ਰਾਜਸਥਾਨ","ਵਿਸ਼ਾਖਾਪਟਨਮ-ਗੁੰਟੂਰ — ਆਂਧਰਾ ਪ੍ਰਦੇਸ਼","ਵਿਸ਼ਾਖਾਪਟਨਮ-ਗੁੰਟੂਰ — ਅਸਾਮ"],"ਇਹ ਖੇਤਰ ਆਂਧਰਾ ਪ੍ਰਦੇਸ਼ ਵਿੱਚ ਹੈ।"]},
"GEO-IND-001-CP009-Q035":{"h":"551d719d","hi":["विशाखापत्तनम में कौन-सा भारी उद्योग विशेष रूप से महत्वपूर्ण है?",["केवल जूट","केवल चीनी","केवल ऊन","लौह और इस्पात"],"विशाखापत्तनम इस्पात संयंत्र भारी उद्योग का प्रमुख आधार है।"],"pa":["ਵਿਸ਼ਾਖਾਪਟਨਮ ਵਿੱਚ ਕਿਹੜਾ ਭਾਰੀ ਉਦਯੋਗ ਖ਼ਾਸ ਤੌਰ 'ਤੇ ਅਹਿਮ ਹੈ?",["ਸਿਰਫ਼ ਜੂਟ","ਸਿਰਫ਼ ਖੰਡ","ਸਿਰਫ਼ ਉੱਨ","ਲੋਹਾ ਅਤੇ ਸਟੀਲ"],"ਵਿਸ਼ਾਖਾਪਟਨਮ ਸਟੀਲ ਪਲਾਂਟ ਭਾਰੀ ਉਦਯੋਗ ਦਾ ਮੁੱਖ ਆਧਾਰ ਹੈ।"]},
"GEO-IND-001-CP009-Q036":{"h":"6dfb365f","hi":["यह क्षेत्र विविध उद्योगों के लिए उपयुक्त क्यों है?",["पत्तन, परिवहन, बाज़ार और विस्तृत पृष्ठप्रदेश उपलब्ध हैं","आधारभूत संरचना की कमी है","केवल एक फसल का महत्व है","श्रमिक नहीं हैं"],"इस क्षेत्र की तटीय अवस्थिति और परिवहन सुविधाएँ कई उद्योगों के लिए अनुकूल हैं।"],"pa":["ਇਹ ਖੇਤਰ ਵੱਖ-ਵੱਖ ਉਦਯੋਗਾਂ ਲਈ ਢੁੱਕਵਾਂ ਕਿਉਂ ਹੈ?",["ਬੰਦਰਗਾਹ, ਆਵਾਜਾਈ, ਬਾਜ਼ਾਰ ਅਤੇ ਵੱਡਾ ਪਿਛਲਾ ਇਲਾਕਾ ਮਿਲਦੇ ਹਨ","ਬੁਨਿਆਦੀ ਢਾਂਚੇ ਦੀ ਘਾਟ ਹੈ","ਸਿਰਫ਼ ਇੱਕ ਫ਼ਸਲ ਦਾ ਮਹੱਤਵ ਹੈ","ਕਾਮੇ ਨਹੀਂ ਹਨ"],"ਤੱਟ ਅਤੇ ਆਵਾਜਾਈ ਦੇ ਲਾਭ ਕਈ ਉਦਯੋਗਾਂ ਨੂੰ ਸਹਾਰਾ ਦਿੰਦੇ ਹਨ।"]},
"GEO-IND-001-CP009-Q037":{"h":"079d7a62","hi":["दिल्ली राष्ट्रीय राजधानी क्षेत्र (NCR) के बड़े बाज़ार का किस औद्योगिक क्षेत्र पर गहरा प्रभाव है?",["हुगली क्षेत्र","छोटानागपुर क्षेत्र","कोल्लम क्षेत्र","दिल्ली-मेरठ-गुरुग्राम औद्योगिक क्षेत्र"],"राष्ट्रीय राजधानी क्षेत्र (NCR) की औद्योगिक पट्टी मुख्यतः बाज़ार और परिवहन की ओर उन्मुख है।"],"pa":["ਦਿੱਲੀ ਰਾਸ਼ਟਰੀ ਰਾਜਧਾਨੀ ਖੇਤਰ (NCR) ਦਾ ਵੱਡਾ ਬਾਜ਼ਾਰ ਕਿਹੜੇ ਉਦਯੋਗਿਕ ਖੇਤਰ 'ਤੇ ਡੂੰਘਾ ਅਸਰ ਪਾਉਂਦਾ ਹੈ?",["ਹੁਗਲੀ ਖੇਤਰ","ਛੋਟਾਨਾਗਪੁਰ ਖੇਤਰ","ਕੋਲਮ ਖੇਤਰ","ਦਿੱਲੀ-ਮੇਰਠ-ਗੁਰੂਗ੍ਰਾਮ ਉਦਯੋਗਿਕ ਖੇਤਰ"],"ਰਾਸ਼ਟਰੀ ਰਾਜਧਾਨੀ ਖੇਤਰ (NCR) ਦੀ ਉਦਯੋਗਿਕ ਪੱਟੀ ਮੁੱਖ ਤੌਰ 'ਤੇ ਬਾਜ਼ਾਰਾਂ ਅਤੇ ਆਵਾਜਾਈ ਨਾਲ ਜੁੜੀ ਹੋਈ ਹੈ।"]},
"GEO-IND-001-CP009-Q038":{"h":"fd9612d2","hi":["दिल्ली राष्ट्रीय राजधानी क्षेत्र (NCR) में कौन-से उद्योग प्रमुख हैं?",["मोटर वाहन, इलेक्ट्रॉनिक्स, अभियांत्रिकी और उपभोक्ता वस्तुएँ","केवल जूट","केवल कोयला खनन","केवल चाय"],"इस क्षेत्र में विविध प्रकार के विनिर्माण उद्योग हैं।"],"pa":["ਦਿੱਲੀ ਰਾਸ਼ਟਰੀ ਰਾਜਧਾਨੀ ਖੇਤਰ (NCR) ਵਿੱਚ ਕਿਹੜੇ ਉਦਯੋਗ ਪ੍ਰਮੁੱਖ ਹਨ?",["ਮੋਟਰ ਵਾਹਨ, ਇਲੈਕਟ੍ਰਾਨਿਕਸ, ਇੰਜੀਨੀਅਰਿੰਗ ਅਤੇ ਖਪਤਕਾਰੀ ਵਸਤਾਂ","ਸਿਰਫ਼ ਜੂਟ","ਸਿਰਫ਼ ਕੋਲੇ ਦੀ ਖੁਦਾਈ","ਸਿਰਫ਼ ਚਾਹ"],"ਇਸ ਖੇਤਰ ਵਿੱਚ ਕਈ ਕਿਸਮਾਂ ਦੇ ਨਿਰਮਾਣ ਉਦਯੋਗ ਹਨ।"]},
"GEO-IND-001-CP009-Q039":{"h":"c4e220f3","hi":["दिल्ली राष्ट्रीय राजधानी क्षेत्र (NCR) के औद्योगिक विकास में कौन-सा कारक विशेष रूप से महत्वपूर्ण है?",["केवल लौह अयस्क","बड़ा बाज़ार और अच्छे परिवहन संपर्क","जूट की खेती","ज्वारीय ऊर्जा"],"राष्ट्रीय राजधानी क्षेत्र (NCR) को सघन माँग, राजमार्गों, श्रम और आपूर्तिकर्ताओं के तंत्र का लाभ मिलता है।"],"pa":["ਦਿੱਲੀ ਰਾਸ਼ਟਰੀ ਰਾਜਧਾਨੀ ਖੇਤਰ (NCR) ਦੇ ਉਦਯੋਗਿਕ ਵਿਕਾਸ ਲਈ ਕਿਹੜਾ ਕਾਰਕ ਖ਼ਾਸ ਤੌਰ 'ਤੇ ਅਹਿਮ ਹੈ?",["ਸਿਰਫ਼ ਕੱਚਾ ਲੋਹਾ","ਵੱਡਾ ਬਾਜ਼ਾਰ ਅਤੇ ਆਵਾਜਾਈ ਦੇ ਚੰਗੇ ਸੰਪਰਕ","ਜੂਟ ਦੀ ਖੇਤੀ","ਜਵਾਰ-ਭਾਟੇ ਦੀ ਊਰਜਾ"],"ਰਾਸ਼ਟਰੀ ਰਾਜਧਾਨੀ ਖੇਤਰ (NCR) ਨੂੰ ਇੱਕ ਥਾਂ ਵੱਡੀ ਮੰਗ, ਰਾਜਮਾਰਗਾਂ, ਕਾਮਿਆਂ ਅਤੇ ਸਪਲਾਇਰਾਂ ਦੇ ਜਾਲਾਂ ਦਾ ਲਾਭ ਹੈ।"]},
"GEO-IND-001-CP009-Q040":{"h":"0dd32703","hi":["कथनों पर विचार कीजिए: I. गुरुग्राम-मानेसर मोटर वाहन उद्योग की पट्टी है। II. राष्ट्रीय राजधानी क्षेत्र (NCR) में बहुत बड़ा उपभोक्ता बाज़ार है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","I और II दोनों सही हैं","न तो I और न ही II सही है"],"दोनों तथ्य इस क्षेत्र के औद्योगिक भूगोल को समझाते हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਗੁਰੂਗ੍ਰਾਮ-ਮਾਨੇਸਰ ਮੋਟਰ ਵਾਹਨ ਉਦਯੋਗ ਦੀ ਪੱਟੀ ਹੈ। II. ਰਾਸ਼ਟਰੀ ਰਾਜਧਾਨੀ ਖੇਤਰ (NCR) ਵਿੱਚ ਖਪਤਕਾਰਾਂ ਦਾ ਬਹੁਤ ਵੱਡਾ ਬਾਜ਼ਾਰ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਦੋਵੇਂ ਤੱਥ ਇਸ ਖੇਤਰ ਦੇ ਉਦਯੋਗਿਕ ਭੂਗੋਲ ਨੂੰ ਸਮਝਾਉਂਦੇ ਹਨ।"]},
"GEO-IND-001-CP009-Q041":{"h":"3218ceb0","hi":["कौन-सा युग्म दिल्ली राष्ट्रीय राजधानी क्षेत्र (NCR) की औद्योगिक पहचान सही दर्शाता है?",["गुरुग्राम-मानेसर — केवल जूट","मेरठ — कोयला क्षेत्र","दिल्ली — लौह अयस्क खदान","गुरुग्राम-मानेसर — मोटर वाहन विनिर्माण"],"गुरुग्राम-मानेसर पट्टी में मोटर वाहन विनिर्माण का प्रमुख संकुल है।"],"pa":["ਕਿਹੜਾ ਜੋੜਾ ਦਿੱਲੀ ਰਾਸ਼ਟਰੀ ਰਾਜਧਾਨੀ ਖੇਤਰ (NCR) ਦੀ ਉਦਯੋਗਿਕ ਪਛਾਣ ਸਹੀ ਦਰਸਾਉਂਦਾ ਹੈ?",["ਗੁਰੂਗ੍ਰਾਮ-ਮਾਨੇਸਰ — ਸਿਰਫ਼ ਜੂਟ","ਮੇਰਠ — ਕੋਲਾ ਖੇਤਰ","ਦਿੱਲੀ — ਕੱਚੇ ਲੋਹੇ ਦੀ ਖਾਣ","ਗੁਰੂਗ੍ਰਾਮ-ਮਾਨੇਸਰ — ਮੋਟਰ ਵਾਹਨ ਨਿਰਮਾਣ"],"ਗੁਰੂਗ੍ਰਾਮ-ਮਾਨੇਸਰ ਪੱਟੀ ਮੋਟਰ ਵਾਹਨ ਬਣਾਉਣ ਦਾ ਪ੍ਰਮੁੱਖ ਗੁੱਛ ਹੈ।"]},
"GEO-IND-001-CP009-Q042":{"h":"7f668a98","hi":["यह क्षेत्र छोटानागपुर की तुलना में खनिज कच्चे माल की निकटता पर कम निर्भर क्यों है?",["कई उद्योग बाज़ार, कौशल और आधारभूत संरचना पर आधारित हैं","वहाँ कोई उद्योग नहीं है","सभी उद्योगों को कोयले की खदानें चाहिए","परिवहन का कोई महत्व नहीं है"],"आधुनिक अभियांत्रिकी और उपभोक्ता वस्तु उद्योग खनिज स्रोतों के बजाय बाज़ारों और श्रम के पास लग सकते हैं।"],"pa":["ਇਹ ਖੇਤਰ ਛੋਟਾਨਾਗਪੁਰ ਨਾਲੋਂ ਖਣਿਜ ਕੱਚੇ ਮਾਲ ਦੀ ਨੇੜਤਾ 'ਤੇ ਘੱਟ ਨਿਰਭਰ ਕਿਉਂ ਹੈ?",["ਕਈ ਉਦਯੋਗ ਬਾਜ਼ਾਰਾਂ, ਹੁਨਰ ਅਤੇ ਬੁਨਿਆਦੀ ਢਾਂਚੇ 'ਤੇ ਆਧਾਰਿਤ ਹਨ","ਇੱਥੇ ਕੋਈ ਉਦਯੋਗ ਨਹੀਂ ਹੈ","ਸਾਰੇ ਉਦਯੋਗਾਂ ਨੂੰ ਕੋਲੇ ਦੀਆਂ ਖਾਣਾਂ ਚਾਹੀਦੀਆਂ ਹਨ","ਆਵਾਜਾਈ ਦਾ ਕੋਈ ਮਹੱਤਵ ਨਹੀਂ ਹੈ"],"ਆਧੁਨਿਕ ਇੰਜੀਨੀਅਰਿੰਗ ਅਤੇ ਖਪਤਕਾਰੀ ਵਸਤਾਂ ਦੇ ਉਦਯੋਗ ਖਣਿਜ ਸਰੋਤਾਂ ਦੀ ਥਾਂ ਬਾਜ਼ਾਰਾਂ ਅਤੇ ਕਾਮਿਆਂ ਦੇ ਨੇੜੇ ਲੱਗ ਸਕਦੇ ਹਨ।"]},
"GEO-IND-001-CP009-Q043":{"h":"ea5cfcfa","hi":["दक्षिणी केरल में कौन-सा औद्योगिक क्षेत्र है?",["कोल्लम-तिरुवनंतपुरम औद्योगिक क्षेत्र","हुगली औद्योगिक क्षेत्र","छोटानागपुर औद्योगिक क्षेत्र","मुंबई-पुणे औद्योगिक क्षेत्र"],"कोल्लम-तिरुवनंतपुरम पट्टी भारत के मान्य औद्योगिक क्षेत्रों में से एक है।"],"pa":["ਦੱਖਣੀ ਕੇਰਲ ਵਿੱਚ ਕਿਹੜਾ ਉਦਯੋਗਿਕ ਖੇਤਰ ਹੈ?",["ਕੋਲਮ-ਤਿਰੂਵਨੰਤਪੁਰਮ ਉਦਯੋਗਿਕ ਖੇਤਰ","ਹੁਗਲੀ ਉਦਯੋਗਿਕ ਖੇਤਰ","ਛੋਟਾਨਾਗਪੁਰ ਉਦਯੋਗਿਕ ਖੇਤਰ","ਮੁੰਬਈ-ਪੁਣੇ ਉਦਯੋਗਿਕ ਖੇਤਰ"],"ਕੋਲਮ-ਤਿਰੂਵਨੰਤਪੁਰਮ ਪੱਟੀ ਭਾਰਤ ਦੇ ਮੰਨੇ-ਪ੍ਰਮੰਨੇ ਉਦਯੋਗਿਕ ਖੇਤਰਾਂ ਵਿੱਚੋਂ ਇੱਕ ਹੈ।"]},
"GEO-IND-001-CP009-Q044":{"h":"0d14878f","hi":["कोल्लम-तिरुवनंतपुरम औद्योगिक क्षेत्र किस राज्य में है?",["तमिलनाडु","केरल","कर्नाटक","गुजरात"],"कोल्लम और तिरुवनंतपुरम, दोनों केरल में हैं।"],"pa":["ਕੋਲਮ-ਤਿਰੂਵਨੰਤਪੁਰਮ ਉਦਯੋਗਿਕ ਖੇਤਰ ਕਿਹੜੇ ਰਾਜ ਵਿੱਚ ਹੈ?",["ਤਾਮਿਲਨਾਡੂ","ਕੇਰਲ","ਕਰਨਾਟਕ","ਗੁਜਰਾਤ"],"ਕੋਲਮ ਅਤੇ ਤਿਰੂਵਨੰਤਪੁਰਮ ਦੋਵੇਂ ਕੇਰਲ ਵਿੱਚ ਹਨ।"]},
"GEO-IND-001-CP009-Q045":{"h":"75198ef2","hi":["परंपरागत रूप से किन उद्योगों ने इस क्षेत्र के विकास में योगदान दिया है?",["केवल एकीकृत इस्पात","केवल जूट","कृषि प्रसंस्करण, खनिज आधारित उद्योग और हल्का विनिर्माण","केवल कोयला खनन"],"पूर्वी भारी उद्योग पट्टी की तुलना में इस क्षेत्र में प्रसंस्करण और हल्के उद्योगों की अधिक विविधता है।"],"pa":["ਰਵਾਇਤੀ ਤੌਰ 'ਤੇ ਕਿਹੜੇ ਉਦਯੋਗਾਂ ਨੇ ਇਸ ਖੇਤਰ ਦੇ ਵਿਕਾਸ ਵਿੱਚ ਯੋਗਦਾਨ ਪਾਇਆ ਹੈ?",["ਸਿਰਫ਼ ਏਕੀਕ੍ਰਿਤ ਸਟੀਲ","ਸਿਰਫ਼ ਜੂਟ","ਖੇਤੀ ਪ੍ਰੋਸੈਸਿੰਗ, ਖਣਿਜ-ਆਧਾਰਿਤ ਉਦਯੋਗ ਅਤੇ ਹਲਕਾ ਨਿਰਮਾਣ","ਸਿਰਫ਼ ਕੋਲੇ ਦੀ ਖੁਦਾਈ"],"ਪੂਰਬੀ ਭਾਰੀ ਉਦਯੋਗ ਪੱਟੀ ਨਾਲੋਂ ਇਸ ਖੇਤਰ ਵਿੱਚ ਪ੍ਰੋਸੈਸਿੰਗ ਅਤੇ ਹਲਕੇ ਉਦਯੋਗਾਂ ਦੀ ਵੱਧ ਵੰਨ-ਸੁਵੰਨਤਾ ਹੈ।"]},
"GEO-IND-001-CP009-Q046":{"h":"5551401c","hi":["कथनों पर विचार कीजिए: I. यह क्षेत्र केरल में है। II. छोटानागपुर की तुलना में यह कोयले और लौह अयस्क पर कम निर्भर है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","न तो I और न ही II सही है","I और II दोनों सही हैं"],"दोनों औद्योगिक क्षेत्रों के संसाधन और अवस्थितिक आधार बहुत अलग हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਇਹ ਖੇਤਰ ਕੇਰਲ ਵਿੱਚ ਹੈ। II. ਇਹ ਛੋਟਾਨਾਗਪੁਰ ਨਾਲੋਂ ਕੋਲੇ ਅਤੇ ਕੱਚੇ ਲੋਹੇ 'ਤੇ ਘੱਟ ਨਿਰਭਰ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ"],"ਦੋਵਾਂ ਉਦਯੋਗਿਕ ਖੇਤਰਾਂ ਦੇ ਸਰੋਤ ਅਤੇ ਥਾਂ ਦੀ ਚੋਣ ਦੇ ਆਧਾਰ ਬਹੁਤ ਵੱਖਰੇ ਹਨ।"]},
"GEO-IND-001-CP009-Q047":{"h":"84c07cac","hi":["औद्योगिक क्षेत्रों के भूगोल में कौन-सा युग्म सही सुमेलित है?",["कोल्लम-तिरुवनंतपुरम — केरल","कोल्लम-तिरुवनंतपुरम — झारखंड","कोल्लम-तिरुवनंतपुरम — गुजरात","कोल्लम-तिरुवनंतपुरम — पंजाब"],"यह क्षेत्र दक्षिणी केरल में है।"],"pa":["ਉਦਯੋਗਿਕ ਖੇਤਰਾਂ ਦੇ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਕੋਲਮ-ਤਿਰੂਵਨੰਤਪੁਰਮ — ਕੇਰਲ","ਕੋਲਮ-ਤਿਰੂਵਨੰਤਪੁਰਮ — ਝਾਰਖੰਡ","ਕੋਲਮ-ਤਿਰੂਵਨੰਤਪੁਰਮ — ਗੁਜਰਾਤ","ਕੋਲਮ-ਤਿਰੂਵਨੰਤਪੁਰਮ — ਪੰਜਾਬ"],"ਇਹ ਖੇਤਰ ਦੱਖਣੀ ਕੇਰਲ ਵਿੱਚ ਹੈ।"]},
"GEO-IND-001-CP009-Q048":{"h":"b193e871","hi":["भारत के औद्योगिक क्षेत्रों की कौन-सी तुलना सही है?",["दोनों एक जैसी इस्पात पट्टियाँ हैं","छोटानागपुर में खनिजों की बड़ी भूमिका है, जबकि कोल्लम-तिरुवनंतपुरम कोयले और लौह अयस्क पर कम निर्भर है","केरल का क्षेत्र कोयला क्षेत्र है","छोटानागपुर केवल पत्तनों पर आधारित क्षेत्र है"],"तुलना दोनों क्षेत्रों में उद्योगों की अवस्थिति के अलग-अलग आधार दिखाती है।"],"pa":["ਭਾਰਤ ਦੇ ਉਦਯੋਗਿਕ ਖੇਤਰਾਂ ਦੀ ਕਿਹੜੀ ਤੁਲਨਾ ਸਹੀ ਹੈ?",["ਦੋਵੇਂ ਇੱਕੋ ਜਿਹੀਆਂ ਸਟੀਲ ਪੱਟੀਆਂ ਹਨ","ਛੋਟਾਨਾਗਪੁਰ ਵਿੱਚ ਖਣਿਜਾਂ ਦੀ ਵੱਡੀ ਭੂਮਿਕਾ ਹੈ, ਜਦਕਿ ਕੋਲਮ-ਤਿਰੂਵਨੰਤਪੁਰਮ ਕੋਲੇ ਅਤੇ ਕੱਚੇ ਲੋਹੇ 'ਤੇ ਘੱਟ ਨਿਰਭਰ ਹੈ","ਕੇਰਲ ਦਾ ਖੇਤਰ ਕੋਲਾ ਖੇਤਰ ਹੈ","ਛੋਟਾਨਾਗਪੁਰ ਸਿਰਫ਼ ਬੰਦਰਗਾਹਾਂ 'ਤੇ ਆਧਾਰਿਤ ਹੈ"],"ਇਹ ਤੁਲਨਾ ਦਰਸਾਉਂਦੀ ਹੈ ਕਿ ਦੋਵਾਂ ਖੇਤਰਾਂ ਵਿੱਚ ਉਦਯੋਗਾਂ ਦੀ ਥਾਂ ਦੇ ਆਧਾਰ ਵੱਖਰੇ ਹਨ।"]},
"GEO-IND-001-CP009-Q049":{"h":"7804f78d","hi":["भारत का कौन-सा औद्योगिक क्षेत्र पारंपरिक जूट पट्टी है?",["छोटानागपुर","मुंबई-पुणे","बेंगलुरु-तमिलनाडु","हुगली"],"हुगली पट्टी भारत का पारंपरिक जूट उद्योग क्षेत्र है।"],"pa":["ਭਾਰਤ ਦਾ ਕਿਹੜਾ ਉਦਯੋਗਿਕ ਖੇਤਰ ਰਵਾਇਤੀ ਜੂਟ ਪੱਟੀ ਹੈ?",["ਛੋਟਾਨਾਗਪੁਰ","ਮੁੰਬਈ-ਪੁਣੇ","ਬੈਂਗਲੁਰੂ-ਤਾਮਿਲਨਾਡੂ","ਹੁਗਲੀ"],"ਹੁਗਲੀ ਪੱਟੀ ਭਾਰਤ ਦਾ ਰਵਾਇਤੀ ਜੂਟ ਉਦਯੋਗ ਖੇਤਰ ਹੈ।"]},
"GEO-IND-001-CP009-Q050":{"h":"0f933a53","hi":["भारत का कौन-सा औद्योगिक क्षेत्र कोयला, लौह अयस्क और इस्पात पर केंद्रित है?",["छोटानागपुर","कोल्लम-तिरुवनंतपुरम","दिल्ली राष्ट्रीय राजधानी क्षेत्र (NCR)","मुंबई-पुणे"],"कोयला, लौह अयस्क और इस्पात छोटानागपुर की औद्योगिक पहचान के मुख्य आधार हैं।"],"pa":["ਭਾਰਤ ਦਾ ਕਿਹੜਾ ਉਦਯੋਗਿਕ ਖੇਤਰ ਕੋਲੇ, ਕੱਚੇ ਲੋਹੇ ਅਤੇ ਸਟੀਲ 'ਤੇ ਕੇਂਦਰਿਤ ਹੈ?",["ਛੋਟਾਨਾਗਪੁਰ","ਕੋਲਮ-ਤਿਰੂਵਨੰਤਪੁਰਮ","ਦਿੱਲੀ ਰਾਸ਼ਟਰੀ ਰਾਜਧਾਨੀ ਖੇਤਰ (NCR)","ਮੁੰਬਈ-ਪੁਣੇ"],"ਕੋਲਾ, ਕੱਚਾ ਲੋਹਾ ਅਤੇ ਸਟੀਲ ਛੋਟਾਨਾਗਪੁਰ ਦੀ ਉਦਯੋਗਿਕ ਪਛਾਣ ਦੇ ਮੁੱਖ ਆਧਾਰ ਹਨ।"]},
"GEO-IND-001-CP009-Q051":{"h":"a649a4f5","hi":["पश्चिमी भारत के किस औद्योगिक क्षेत्र की पहचान मोटर वाहन और अभियांत्रिकी उद्योगों से है?",["हुगली","मुंबई-पुणे","कोल्लम-तिरुवनंतपुरम","केवल विशाखापत्तनम-गुंटूर"],"मुंबई-पुणे पट्टी में पुणे मोटर वाहन और अभियांत्रिकी का प्रमुख केंद्र है।"],"pa":["ਪੱਛਮੀ ਭਾਰਤ ਦਾ ਕਿਹੜਾ ਉਦਯੋਗਿਕ ਖੇਤਰ ਮੋਟਰ ਵਾਹਨ ਅਤੇ ਇੰਜੀਨੀਅਰਿੰਗ ਉਦਯੋਗਾਂ ਲਈ ਜਾਣਿਆ ਜਾਂਦਾ ਹੈ?",["ਹੁਗਲੀ","ਮੁੰਬਈ-ਪੁਣੇ","ਕੋਲਮ-ਤਿਰੂਵਨੰਤਪੁਰਮ","ਸਿਰਫ਼ ਵਿਸ਼ਾਖਾਪਟਨਮ-ਗੁੰਟੂਰ"],"ਮੁੰਬਈ-ਪੁਣੇ ਪੱਟੀ ਵਿੱਚ ਪੁਣੇ ਮੋਟਰ ਵਾਹਨ ਅਤੇ ਇੰਜੀਨੀਅਰਿੰਗ ਦਾ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰ ਹੈ।"]},
"GEO-IND-001-CP009-Q052":{"h":"0c25ec79","hi":["उत्तरी भारत के सबसे बड़े महानगरीय क्षेत्र के आसपास कौन-सा औद्योगिक क्षेत्र खास तौर पर बाज़ार-उन्मुख है?",["छोटानागपुर","हुगली","दिल्ली-मेरठ-गुरुग्राम","कोल्लम-तिरुवनंतपुरम"],"राष्ट्रीय राजधानी क्षेत्र (NCR) की औद्योगिक पट्टी को विशाल उपभोक्ता बाज़ार और अच्छे संपर्क का विशेष लाभ मिलता है।"],"pa":["ਉੱਤਰੀ ਭਾਰਤ ਦੇ ਸਭ ਤੋਂ ਵੱਡੇ ਮਹਾਂਨਗਰੀ ਖੇਤਰ ਦੇ ਆਲੇ-ਦੁਆਲੇ ਕਿਹੜਾ ਉਦਯੋਗਿਕ ਖੇਤਰ ਖ਼ਾਸ ਤੌਰ 'ਤੇ ਬਾਜ਼ਾਰਾਂ ਵੱਲ ਕੇਂਦਰਿਤ ਹੈ?",["ਛੋਟਾਨਾਗਪੁਰ","ਹੁਗਲੀ","ਦਿੱਲੀ-ਮੇਰਠ-ਗੁਰੂਗ੍ਰਾਮ","ਕੋਲਮ-ਤਿਰੂਵਨੰਤਪੁਰਮ"],"ਰਾਸ਼ਟਰੀ ਰਾਜਧਾਨੀ ਖੇਤਰ (NCR) ਦੀ ਉਦਯੋਗਿਕ ਪੱਟੀ ਨੂੰ ਖਪਤਕਾਰਾਂ ਦੇ ਵੱਡੇ ਬਾਜ਼ਾਰ ਅਤੇ ਚੰਗੇ ਸੰਪਰਕਾਂ ਦਾ ਖ਼ਾਸ ਲਾਭ ਹੈ।"]},
"GEO-IND-001-CP009-Q053":{"h":"2d573842","hi":["कौन-सा औद्योगिक क्षेत्र दक्षिण भारत के प्रमुख अभियांत्रिकी और मोटर वाहन केंद्रों को जोड़ता है?",["हुगली","छोटानागपुर","केवल गुजरात","बेंगलुरु-तमिलनाडु"],"बेंगलुरु और चेन्नई दक्षिण भारत के एक प्रमुख विनिर्माण क्षेत्र के मुख्य केंद्र हैं।"],"pa":["ਕਿਹੜਾ ਉਦਯੋਗਿਕ ਖੇਤਰ ਦੱਖਣੀ ਭਾਰਤ ਦੇ ਪ੍ਰਮੁੱਖ ਇੰਜੀਨੀਅਰਿੰਗ ਅਤੇ ਮੋਟਰ ਵਾਹਨ ਕੇਂਦਰਾਂ ਨੂੰ ਜੋੜਦਾ ਹੈ?",["ਹੁਗਲੀ","ਛੋਟਾਨਾਗਪੁਰ","ਸਿਰਫ਼ ਗੁਜਰਾਤ","ਬੈਂਗਲੁਰੂ-ਤਾਮਿਲਨਾਡੂ"],"ਬੈਂਗਲੁਰੂ ਅਤੇ ਚੇਨਈ ਦੱਖਣੀ ਭਾਰਤ ਦੇ ਇੱਕ ਪ੍ਰਮੁੱਖ ਨਿਰਮਾਣ ਖੇਤਰ ਦੇ ਮੁੱਖ ਕੇਂਦਰ ਹਨ।"]},
"GEO-IND-001-CP009-Q054":{"h":"3067382d","hi":["कौन-सा क्रम औद्योगिक क्षेत्रों को उनकी विशिष्ट पहचान से सही जोड़ता है?",["हुगली—जूट; छोटानागपुर—इस्पात; मुंबई-पुणे—अभियांत्रिकी","हुगली—केवल इस्पात; छोटानागपुर—जूट; मुंबई-पुणे—कोयला खनन","तीनों—जूट","तीनों—चीनी"],"यह क्रम तीनों क्षेत्रों की अलग-अलग पारंपरिक औद्योगिक विशेषज्ञताएँ दर्शाता है।"],"pa":["ਕਿਹੜਾ ਕ੍ਰਮ ਉਦਯੋਗਿਕ ਖੇਤਰਾਂ ਨੂੰ ਉਨ੍ਹਾਂ ਦੀ ਖ਼ਾਸ ਪਛਾਣ ਨਾਲ ਸਹੀ ਜੋੜਦਾ ਹੈ?",["ਹੁਗਲੀ—ਜੂਟ; ਛੋਟਾਨਾਗਪੁਰ—ਸਟੀਲ; ਮੁੰਬਈ-ਪੁਣੇ—ਇੰਜੀਨੀਅਰਿੰਗ","ਹੁਗਲੀ—ਸਿਰਫ਼ ਸਟੀਲ; ਛੋਟਾਨਾਗਪੁਰ—ਜੂਟ; ਮੁੰਬਈ-ਪੁਣੇ—ਕੋਲੇ ਦੀ ਖੁਦਾਈ","ਤਿੰਨੇ—ਜੂਟ","ਤਿੰਨੇ—ਖੰਡ"],"ਇਹ ਕ੍ਰਮ ਤਿੰਨਾਂ ਖੇਤਰਾਂ ਦੀ ਵੱਖੋ-ਵੱਖਰੀ ਰਵਾਇਤੀ ਉਦਯੋਗਿਕ ਪਛਾਣ ਦਰਸਾਉਂਦਾ ਹੈ।"]},
"GEO-IND-001-CP010-Q001":{"h":"7c9e57cc","hi":["कुछ भारी उद्योग प्रमुख पत्तनों के पास क्यों लगाए जाते हैं?",["पत्तन अपने आप लौह अयस्क देते हैं","पत्तनों से बाज़ारों की ज़रूरत खत्म होती है","पत्तन परिवहन की ज़रूरत खत्म करते हैं","पत्तन कच्चे माल के आयात और उत्पादों के निर्यात की लागत घटाते हैं"],"कच्चा तेल, कोयला, अयस्क, रसायन और इस्पात जैसे माल को समुद्र से बड़ी मात्रा में कुशलतापूर्वक ढोया जा सकता है।"],"pa":["ਕੁਝ ਭਾਰੀ ਉਦਯੋਗ ਪ੍ਰਮੁੱਖ ਬੰਦਰਗਾਹਾਂ ਨੇੜੇ ਕਿਉਂ ਲੱਗਦੇ ਹਨ?",["ਬੰਦਰਗਾਹਾਂ ਆਪਣੇ ਆਪ ਕੱਚਾ ਲੋਹਾ ਦਿੰਦੀਆਂ ਹਨ","ਬੰਦਰਗਾਹਾਂ ਨਾਲ ਬਾਜ਼ਾਰਾਂ ਦੀ ਲੋੜ ਮੁੱਕ ਜਾਂਦੀ ਹੈ","ਬੰਦਰਗਾਹਾਂ ਆਵਾਜਾਈ ਦੀ ਲੋੜ ਖ਼ਤਮ ਕਰਦੀਆਂ ਹਨ","ਬੰਦਰਗਾਹਾਂ ਕੱਚੇ ਮਾਲ ਦੇ ਆਯਾਤ ਅਤੇ ਉਤਪਾਦਾਂ ਦੇ ਨਿਰਯਾਤ ਦਾ ਖ਼ਰਚ ਘਟਾਉਂਦੀਆਂ ਹਨ"],"ਕੱਚਾ ਤੇਲ, ਕੋਲਾ, ਅਯਸਕ, ਰਸਾਇਣ ਅਤੇ ਸਟੀਲ ਵਰਗਾ ਮਾਲ ਸਮੁੰਦਰ ਰਾਹੀਂ ਵੱਡੀ ਮਾਤਰਾ ਵਿੱਚ ਸੁਚੱਜੇ ਢੰਗ ਨਾਲ ਢੋਇਆ ਜਾ ਸਕਦਾ ਹੈ।"]},
"GEO-IND-001-CP010-Q002":{"h":"ed8af5d7","hi":["पत्तनों से कच्चे तेल के आयात का विशेष लाभ किस उद्योग को होता है?",["पेट्रोलियम शोधन","जूट की खेती","केवल गन्ने की पेराई","केवल हथकरघा बुनाई"],"शोधनशालाएँ आयातित या घरेलू कच्चे तेल का प्रसंस्करण करती हैं। तट पर तेलवाहक जहाज़ों की पहुँच से उन्हें अक्सर लाभ मिलता है।"],"pa":["ਬੰਦਰਗਾਹਾਂ ਰਾਹੀਂ ਕੱਚੇ ਤੇਲ ਦੇ ਆਯਾਤ ਦਾ ਖ਼ਾਸ ਲਾਭ ਕਿਹੜੇ ਉਦਯੋਗ ਨੂੰ ਹੁੰਦਾ ਹੈ?",["ਪੈਟਰੋਲੀਅਮ ਦੀ ਸੋਧਾਈ","ਜੂਟ ਦੀ ਖੇਤੀ","ਸਿਰਫ਼ ਗੰਨੇ ਦੀ ਪਿੜਾਈ","ਸਿਰਫ਼ ਹੱਥ-ਖੱਡੀ ਨਾਲ ਬੁਣਾਈ"],"ਰਿਫ਼ਾਇਨਰੀਆਂ ਬਾਹਰੋਂ ਮੰਗਵਾਇਆ ਜਾਂ ਦੇਸ਼ ਵਿੱਚੋਂ ਮਿਲਿਆ ਕੱਚਾ ਤੇਲ ਸੋਧਦੀਆਂ ਹਨ। ਤੱਟ 'ਤੇ ਤੇਲ ਢੋਣ ਵਾਲੇ ਜਹਾਜ਼ਾਂ ਦੀ ਪਹੁੰਚ ਦਾ ਉਨ੍ਹਾਂ ਨੂੰ ਅਕਸਰ ਲਾਭ ਹੁੰਦਾ ਹੈ।"]},
"GEO-IND-001-CP010-Q003":{"h":"ebe64a14","hi":["कथनों पर विचार कीजिए: I. पत्तन बड़ी खेपों को सँभालते हैं। II. पत्तन तक पहुँच शोधनशालाओं और पेट्रोरसायन संयंत्रों को आकर्षित कर सकती है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","I और II दोनों सही हैं","केवल II सही है","न तो I और न ही II सही है"],"बड़ी मात्रा में आयात और निर्यात की सुविधा तटीय उद्योगों की अवस्थिति पर गहरा असर डाल सकती है।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਬੰਦਰਗਾਹਾਂ ਵੱਡੀਆਂ ਖੇਪਾਂ ਸੰਭਾਲਦੀਆਂ ਹਨ। II. ਬੰਦਰਗਾਹ ਤੱਕ ਪਹੁੰਚ ਰਿਫ਼ਾਇਨਰੀਆਂ ਅਤੇ ਪੈਟਰੋ-ਰਸਾਇਣ ਪਲਾਂਟਾਂ ਨੂੰ ਖਿੱਚ ਸਕਦੀ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਵੱਡੀ ਮਾਤਰਾ ਵਿੱਚ ਆਯਾਤ ਤੇ ਨਿਰਯਾਤ ਦੀ ਸਹੂਲਤ ਤੱਟੀ ਉਦਯੋਗਾਂ ਦੀ ਥਾਂ 'ਤੇ ਡੂੰਘਾ ਅਸਰ ਪਾ ਸਕਦੀ ਹੈ।"]},
"GEO-IND-001-CP010-Q004":{"h":"1660503c","hi":["पत्तन आधारित उद्योगों में कौन-सा युग्म सही सुमेलित है?",["प्रमुख पत्तन — जूट की खेती","प्रमुख पत्तन — लौह अयस्क की उत्पत्ति","प्रमुख पत्तन — शोधनशालाओं और पेट्रोरसायन उद्योग का लाभ","प्रमुख पत्तन — गन्ने की खेती"],"पत्तन बड़ी मात्रा में तरल और ठोस औद्योगिक माल की ढुलाई में मदद करते हैं।"],"pa":["ਬੰਦਰਗਾਹ-ਆਧਾਰਿਤ ਉਦਯੋਗਾਂ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਪ੍ਰਮੁੱਖ ਬੰਦਰਗਾਹ — ਜੂਟ ਦੀ ਖੇਤੀ","ਪ੍ਰਮੁੱਖ ਬੰਦਰਗਾਹ — ਕੱਚੇ ਲੋਹੇ ਦਾ ਬਣਨਾ","ਪ੍ਰਮੁੱਖ ਬੰਦਰਗਾਹ — ਰਿਫ਼ਾਇਨਰੀਆਂ ਤੇ ਪੈਟਰੋ-ਰਸਾਇਣ ਉਦਯੋਗ ਨੂੰ ਲਾਭ","ਪ੍ਰਮੁੱਖ ਬੰਦਰਗਾਹ — ਗੰਨੇ ਦੀ ਖੇਤੀ"],"ਬੰਦਰਗਾਹਾਂ ਵੱਡੀ ਮਾਤਰਾ ਵਿੱਚ ਤਰਲ ਅਤੇ ਠੋਸ ਉਦਯੋਗਿਕ ਮਾਲ ਢੋਣ ਵਿੱਚ ਮਦਦ ਕਰਦੀਆਂ ਹਨ।"]},
"GEO-IND-001-CP010-Q005":{"h":"5690fa67","hi":["किस तटीय इस्पात संयंत्र को पत्तन की निकटता का महत्वपूर्ण लाभ है?",["बोकारो","जमशेदपुर","भिलाई","विशाखापत्तनम"],"विशाखापत्तनम तटीय इस्पात केंद्र है, जिसे पत्तन तक सीधी पहुँच प्राप्त है।"],"pa":["ਕਿਹੜੇ ਤੱਟੀ ਸਟੀਲ ਪਲਾਂਟ ਨੂੰ ਬੰਦਰਗਾਹ ਨੇੜੇ ਹੋਣ ਦਾ ਅਹਿਮ ਲਾਭ ਹੈ?",["ਬੋਕਾਰੋ","ਜਮਸ਼ੇਦਪੁਰ","ਭਿਲਾਈ","ਵਿਸ਼ਾਖਾਪਟਨਮ"],"ਵਿਸ਼ਾਖਾਪਟਨਮ ਤੱਟੀ ਸਟੀਲ ਕੇਂਦਰ ਹੈ, ਜਿਸ ਦੀ ਬੰਦਰਗਾਹ ਤੱਕ ਸਿੱਧੀ ਪਹੁੰਚ ਹੈ।"]},
"GEO-IND-001-CP010-Q006":{"h":"385524d8","hi":["पत्तन आधारित संयंत्र और खदान के मुहाने पर लगे पारंपरिक संयंत्र में क्या अंतर है?",["पत्तन आधारित संयंत्र कच्चे माल के स्रोत की निकटता के बजाय समुद्री परिवहन पर अधिक निर्भर है","परिवहन की ज़रूरत नहीं है","पत्तन खदानें हैं","खदान के मुहाने के संयंत्र केवल आयात पर निर्भर हैं"],"पत्तन आधारित संयंत्र समुद्र के रास्ते दूर-दराज़ से कच्चा माल मँगा सकते हैं।"],"pa":["ਬੰਦਰਗਾਹ-ਆਧਾਰਿਤ ਪਲਾਂਟ ਅਤੇ ਖਾਣ ਦੇ ਮੂੰਹ 'ਤੇ ਲੱਗੇ ਰਵਾਇਤੀ ਪਲਾਂਟ ਵਿੱਚ ਕੀ ਫ਼ਰਕ ਹੈ?",["ਬੰਦਰਗਾਹੀ ਪਲਾਂਟ ਕੱਚੇ ਮਾਲ ਦੀ ਨੇੜਤਾ ਦੀ ਥਾਂ ਸਮੁੰਦਰੀ ਢੋਆ-ਢੁਆਈ 'ਤੇ ਵੱਧ ਨਿਰਭਰ ਕਰਦਾ ਹੈ","ਢੋਆ-ਢੁਆਈ ਦੀ ਲੋੜ ਨਹੀਂ ਹੁੰਦੀ","ਬੰਦਰਗਾਹਾਂ ਖਾਣਾਂ ਹਨ","ਖਾਣ ਦੇ ਮੂੰਹ 'ਤੇ ਲੱਗੇ ਪਲਾਂਟ ਸਿਰਫ਼ ਆਯਾਤ 'ਤੇ ਨਿਰਭਰ ਹਨ"],"ਬੰਦਰਗਾਹ-ਆਧਾਰਿਤ ਪਲਾਂਟ ਦੂਰੋਂ ਸਮੁੰਦਰ ਰਾਹੀਂ ਕੱਚਾ ਮਾਲ ਮੰਗਵਾ ਸਕਦੇ ਹਨ।"]},
"GEO-IND-001-CP010-Q007":{"h":"5675913a","hi":["दिल्ली-मुंबई औद्योगिक गलियारा किन दो प्रमुख महानगरीय क्षेत्रों को जोड़ता है?",["कोलकाता और चेन्नई","बेंगलुरु और कोच्चि","गुवाहाटी और जयपुर","दिल्ली और मुंबई"],"यह औद्योगिक गलियारा दिल्ली-मुंबई अक्ष के साथ विकसित किया गया है।"],"pa":["ਦਿੱਲੀ-ਮੁੰਬਈ ਉਦਯੋਗਿਕ ਗਲਿਆਰਾ ਕਿਹੜੇ ਦੋ ਪ੍ਰਮੁੱਖ ਮਹਾਂਨਗਰੀ ਖੇਤਰਾਂ ਨੂੰ ਜੋੜਦਾ ਹੈ?",["ਕੋਲਕਾਤਾ ਅਤੇ ਚੇਨਈ","ਬੈਂਗਲੁਰੂ ਅਤੇ ਕੋਚੀ","ਗੁਹਾਟੀ ਅਤੇ ਜੈਪੁਰ","ਦਿੱਲੀ ਅਤੇ ਮੁੰਬਈ"],"ਇਹ ਗਲਿਆਰਾ ਦਿੱਲੀ-ਮੁੰਬਈ ਧੁਰੇ ਦੇ ਨਾਲ ਬਣਾਇਆ ਗਿਆ ਹੈ।"]},
"GEO-IND-001-CP010-Q008":{"h":"bc2c4710","hi":["कौन-सा परिवहन अक्ष दिल्ली-मुंबई औद्योगिक गलियारे का प्रमुख आधार है?",["पश्चिमी समर्पित माल ढुलाई गलियारे का अक्ष","केवल कोंकण रेलवे","कालका-शिमला रेलमार्ग","दार्जिलिंग हिमालयन रेलवे"],"पश्चिमी माल ढुलाई गलियारा दिल्ली-मुंबई औद्योगिक गलियारे में माल की आवाजाही का प्रमुख आधार है।"],"pa":["ਕਿਹੜਾ ਆਵਾਜਾਈ ਧੁਰਾ ਦਿੱਲੀ-ਮੁੰਬਈ ਉਦਯੋਗਿਕ ਗਲਿਆਰੇ ਦਾ ਮੁੱਖ ਆਧਾਰ ਹੈ?",["ਪੱਛਮੀ ਸਮਰਪਿਤ ਮਾਲ-ਢੁਆਈ ਗਲਿਆਰੇ ਦਾ ਧੁਰਾ","ਸਿਰਫ਼ ਕੋਂਕਣ ਰੇਲਵੇ","ਕਾਲਕਾ-ਸ਼ਿਮਲਾ ਰੇਲ ਮਾਰਗ","ਦਾਰਜੀਲਿੰਗ ਹਿਮਾਲਿਆਈ ਰੇਲਵੇ"],"ਪੱਛਮੀ ਮਾਲ-ਢੁਆਈ ਗਲਿਆਰਾ ਦਿੱਲੀ-ਮੁੰਬਈ ਉਦਯੋਗਿਕ ਗਲਿਆਰੇ ਲਈ ਮਾਲ ਦੀ ਆਵਾਜਾਈ ਦਾ ਪ੍ਰਮੁੱਖ ਆਧਾਰ ਹੈ।"]},
"GEO-IND-001-CP010-Q009":{"h":"ba44c26b","hi":["कथनों पर विचार कीजिए: I. यह गलियारा पश्चिम और उत्तर के प्रमुख बाज़ारों को जोड़ता है। II. माल ढुलाई की आधारभूत संरचना इस औद्योगिक गलियारे का मूल आधार है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","I और II दोनों सही हैं","केवल II सही है","न तो I और न ही II सही है"],"बाज़ारों से संपर्क और कुशल माल ढुलाई इस गलियारे के प्रमुख लाभ हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਇਹ ਗਲਿਆਰਾ ਪੱਛਮ ਅਤੇ ਉੱਤਰ ਦੇ ਪ੍ਰਮੁੱਖ ਬਾਜ਼ਾਰਾਂ ਨੂੰ ਜੋੜਦਾ ਹੈ। II. ਮਾਲ ਢੋਣ ਦਾ ਬੁਨਿਆਦੀ ਢਾਂਚਾ ਇਸ ਉਦਯੋਗਿਕ ਗਲਿਆਰੇ ਦਾ ਮੁੱਖ ਆਧਾਰ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਬਾਜ਼ਾਰਾਂ ਨਾਲ ਸੰਪਰਕ ਅਤੇ ਸੁਚੱਜੀ ਮਾਲ-ਢੁਆਈ ਇਸ ਗਲਿਆਰੇ ਦੇ ਮੁੱਖ ਲਾਭ ਹਨ।"]},
"GEO-IND-001-CP010-Q010":{"h":"c47b149b","hi":["कौन-सा युग्म दिल्ली-मुंबई औद्योगिक गलियारे की सही पहचान करता है?",["दिल्ली-मुंबई गलियारा — जूट पट्टी","दिल्ली-मुंबई गलियारा — चाय पट्टी","दिल्ली-मुंबई गलियारा — पश्चिमी माल ढुलाई अक्ष","दिल्ली-मुंबई गलियारा — केवल कोयला क्षेत्र"],"यह गलियारा उत्तर-पश्चिम के एक प्रमुख माल ढुलाई और औद्योगिक अक्ष के साथ है।"],"pa":["ਕਿਹੜਾ ਜੋੜਾ ਦਿੱਲੀ-ਮੁੰਬਈ ਉਦਯੋਗਿਕ ਗਲਿਆਰੇ ਦੀ ਸਹੀ ਪਛਾਣ ਕਰਦਾ ਹੈ?",["ਦਿੱਲੀ-ਮੁੰਬਈ ਗਲਿਆਰਾ — ਜੂਟ ਪੱਟੀ","ਦਿੱਲੀ-ਮੁੰਬਈ ਗਲਿਆਰਾ — ਚਾਹ ਪੱਟੀ","ਦਿੱਲੀ-ਮੁੰਬਈ ਗਲਿਆਰਾ — ਪੱਛਮੀ ਮਾਲ-ਢੁਆਈ ਧੁਰਾ","ਦਿੱਲੀ-ਮੁੰਬਈ ਗਲਿਆਰਾ — ਸਿਰਫ਼ ਕੋਲਾ ਖੇਤਰ"],"ਇਹ ਗਲਿਆਰਾ ਉੱਤਰ-ਪੱਛਮ ਦੇ ਇੱਕ ਪ੍ਰਮੁੱਖ ਮਾਲ-ਢੁਆਈ ਅਤੇ ਉਦਯੋਗਿਕ ਧੁਰੇ ਦੇ ਨਾਲ ਹੈ।"]},
"GEO-IND-001-CP010-Q011":{"h":"259683c9","hi":["औद्योगिक गलियारे विनिर्माण उद्योगों को क्यों आकर्षित कर सकते हैं?",["वे सारी परिवहन व्यवस्था हटा देते हैं","वे केवल खदानों पर निर्भर हैं","वे शहरों को बाहर रखते हैं","वे माल ढुलाई संपर्क, औद्योगिक केंद्र, बाज़ार और आधारभूत संरचना जोड़ते हैं"],"गलियारों से माल की आवाजाही की बाधाएँ घटती हैं और आधारभूत संरचना तथा निवेश एक क्षेत्र में केंद्रित होते हैं।"],"pa":["ਉਦਯੋਗਿਕ ਗਲਿਆਰੇ ਨਿਰਮਾਣ ਉਦਯੋਗਾਂ ਨੂੰ ਕਿਉਂ ਖਿੱਚ ਸਕਦੇ ਹਨ?",["ਉਹ ਆਵਾਜਾਈ ਪੂਰੀ ਤਰ੍ਹਾਂ ਹਟਾਉਂਦੇ ਹਨ","ਉਹ ਸਿਰਫ਼ ਖਾਣਾਂ 'ਤੇ ਨਿਰਭਰ ਹਨ","ਉਹ ਸ਼ਹਿਰਾਂ ਨੂੰ ਬਾਹਰ ਰੱਖਦੇ ਹਨ","ਉਹ ਮਾਲ-ਢੁਆਈ ਸੰਪਰਕ, ਉਦਯੋਗਿਕ ਕੇਂਦਰ, ਬਾਜ਼ਾਰ ਅਤੇ ਬੁਨਿਆਦੀ ਢਾਂਚੇ ਨੂੰ ਜੋੜਦੇ ਹਨ"],"ਗਲਿਆਰੇ ਮਾਲ ਢੋਣ ਦੀਆਂ ਰੁਕਾਵਟਾਂ ਘਟਾਉਂਦੇ ਹਨ ਅਤੇ ਬੁਨਿਆਦੀ ਢਾਂਚਾ ਤੇ ਨਿਵੇਸ਼ ਇੱਕ ਖੇਤਰ ਵਿੱਚ ਕੇਂਦਰਿਤ ਕਰਦੇ ਹਨ।"]},
"GEO-IND-001-CP010-Q012":{"h":"219bf38f","hi":["समर्पित माल ढुलाई गलियारे से अवस्थिति के किस कारक में सबसे सीधा सुधार होता है?",["परिवहन और माल की आवाजाही की दक्षता","अयस्क की श्रेणी","वर्षा","मिट्टी की उर्वरता"],"समर्पित मालवाहक रेलमार्गों से औद्योगिक सामग्री और तैयार माल की आवाजाही बेहतर होती है।"],"pa":["ਸਮਰਪਿਤ ਮਾਲ-ਢੁਆਈ ਗਲਿਆਰੇ ਨਾਲ ਥਾਂ ਦੀ ਚੋਣ ਦੇ ਕਿਹੜੇ ਕਾਰਕ ਵਿੱਚ ਸਭ ਤੋਂ ਸਿੱਧਾ ਸੁਧਾਰ ਹੁੰਦਾ ਹੈ?",["ਆਵਾਜਾਈ ਅਤੇ ਮਾਲ ਢੋਣ ਦੀ ਕਾਰਗੁਜ਼ਾਰੀ","ਅਯਸਕ ਦਾ ਦਰਜਾ","ਵਰਖਾ","ਮਿੱਟੀ ਦੀ ਉਪਜਾਊ ਸ਼ਕਤੀ"],"ਸਿਰਫ਼ ਮਾਲ ਢੋਣ ਲਈ ਬਣੇ ਰੇਲ ਮਾਰਗ ਉਦਯੋਗਿਕ ਸਮੱਗਰੀ ਅਤੇ ਤਿਆਰ ਮਾਲ ਦੀ ਆਵਾਜਾਈ ਸੁਧਾਰਦੇ ਹਨ।"]},
"GEO-IND-001-CP010-Q013":{"h":"49748624","hi":["चेन्नई-बेंगलुरु औद्योगिक गलियारे के मुख्य केंद्र कौन-से दो महानगरीय क्षेत्र हैं?",["दिल्ली और मुंबई","चेन्नई और बेंगलुरु","कोलकाता और पटना","जयपुर और लखनऊ"],"यह गलियारा दक्षिण भारत के दो प्रमुख विनिर्माण और प्रौद्योगिकी केंद्रों को जोड़ता है।"],"pa":["ਚੇਨਈ-ਬੈਂਗਲੁਰੂ ਉਦਯੋਗਿਕ ਗਲਿਆਰੇ ਦੇ ਮੁੱਖ ਕੇਂਦਰ ਕਿਹੜੇ ਦੋ ਮਹਾਂਨਗਰੀ ਖੇਤਰ ਹਨ?",["ਦਿੱਲੀ ਅਤੇ ਮੁੰਬਈ","ਚੇਨਈ ਅਤੇ ਬੈਂਗਲੁਰੂ","ਕੋਲਕਾਤਾ ਅਤੇ ਪਟਨਾ","ਜੈਪੁਰ ਅਤੇ ਲਖਨਊ"],"ਇਹ ਗਲਿਆਰਾ ਦੱਖਣੀ ਭਾਰਤ ਦੇ ਦੋ ਪ੍ਰਮੁੱਖ ਨਿਰਮਾਣ ਅਤੇ ਤਕਨਾਲੋਜੀ ਕੇਂਦਰਾਂ ਨੂੰ ਜੋੜਦਾ ਹੈ।"]},
"GEO-IND-001-CP010-Q014":{"h":"3416487d","hi":["चेन्नई-बेंगलुरु अक्ष पर कौन-से उद्योग बड़े पैमाने पर मौजूद हैं?",["केवल जूट","केवल कोयला खनन","मोटर वाहन, अभियांत्रिकी और इलेक्ट्रॉनिक्स","केवल चीनी"],"यह गलियारा तमिलनाडु और कर्नाटक के प्रमुख विनिर्माण संकुलों को जोड़ता है।"],"pa":["ਚੇਨਈ-ਬੈਂਗਲੁਰੂ ਧੁਰੇ ਦੇ ਨਾਲ ਕਿਹੜੇ ਉਦਯੋਗ ਵੱਡੇ ਪੱਧਰ 'ਤੇ ਮੌਜੂਦ ਹਨ?",["ਸਿਰਫ਼ ਜੂਟ","ਸਿਰਫ਼ ਕੋਲੇ ਦੀ ਖੁਦਾਈ","ਮੋਟਰ ਵਾਹਨ, ਇੰਜੀਨੀਅਰਿੰਗ ਅਤੇ ਇਲੈਕਟ੍ਰਾਨਿਕਸ","ਸਿਰਫ਼ ਖੰਡ"],"ਇਹ ਗਲਿਆਰਾ ਤਾਮਿਲਨਾਡੂ ਅਤੇ ਕਰਨਾਟਕ ਦੇ ਪ੍ਰਮੁੱਖ ਨਿਰਮਾਣ ਗੁੱਛਾਂ ਨੂੰ ਜੋੜਦਾ ਹੈ।"]},
"GEO-IND-001-CP010-Q015":{"h":"b8ab3803","hi":["कथनों पर विचार कीजिए: I. चेन्नई मोटर वाहन उद्योग का प्रमुख केंद्र है। II. बेंगलुरु अभियांत्रिकी और प्रौद्योगिकी का प्रमुख केंद्र है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","न तो I और न ही II सही है","I और II दोनों सही हैं"],"दोनों केंद्र अपनी-अपनी औद्योगिक खूबियों से एक-दूसरे के पूरक हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਚੇਨਈ ਮੋਟਰ ਵਾਹਨ ਉਦਯੋਗ ਦਾ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰ ਹੈ। II. ਬੈਂਗਲੁਰੂ ਇੰਜੀਨੀਅਰਿੰਗ ਅਤੇ ਤਕਨਾਲੋਜੀ ਦਾ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ"],"ਦੋਵਾਂ ਮੁੱਖ ਕੇਂਦਰਾਂ ਦੀਆਂ ਉਦਯੋਗਿਕ ਖ਼ੂਬੀਆਂ ਇੱਕ-ਦੂਜੇ ਦੀਆਂ ਪੂਰਕ ਹਨ।"]},
"GEO-IND-001-CP010-Q016":{"h":"174e63e3","hi":["कौन-सा युग्म चेन्नई-बेंगलुरु औद्योगिक गलियारे की सही पहचान करता है?",["चेन्नई-बेंगलुरु — दक्षिणी विनिर्माण अक्ष","चेन्नई-बेंगलुरु — केवल जूट पट्टी","चेन्नई-बेंगलुरु — केवल कोयला क्षेत्र","चेन्नई-बेंगलुरु — चाय पट्टी"],"यह अक्ष दक्षिण भारत का प्रमुख विनिर्माण गलियारा है।"],"pa":["ਕਿਹੜਾ ਜੋੜਾ ਚੇਨਈ-ਬੈਂਗਲੁਰੂ ਉਦਯੋਗਿਕ ਗਲਿਆਰੇ ਦੀ ਸਹੀ ਪਛਾਣ ਕਰਦਾ ਹੈ?",["ਚੇਨਈ-ਬੈਂਗਲੁਰੂ — ਦੱਖਣੀ ਨਿਰਮਾਣ ਧੁਰਾ","ਚੇਨਈ-ਬੈਂਗਲੁਰੂ — ਸਿਰਫ਼ ਜੂਟ ਪੱਟੀ","ਚੇਨਈ-ਬੈਂਗਲੁਰੂ — ਸਿਰਫ਼ ਕੋਲਾ ਖੇਤਰ","ਚੇਨਈ-ਬੈਂਗਲੁਰੂ — ਚਾਹ ਪੱਟੀ"],"ਇਹ ਧੁਰਾ ਦੱਖਣੀ ਭਾਰਤ ਦਾ ਪ੍ਰਮੁੱਖ ਨਿਰਮਾਣ ਗਲਿਆਰਾ ਹੈ।"]},
"GEO-IND-001-CP010-Q017":{"h":"5cc34749","hi":["यह गलियारा आधुनिक विनिर्माण के लिए आकर्षक क्यों है?",["इसमें शहर नहीं हैं","यह कुशल श्रम, पत्तनों, बाज़ारों और आपूर्तिकर्ता संकुलों को जोड़ता है","इसमें परिवहन की कमी है","केवल खनिजों की निकटता का महत्व है"],"क्षेत्र की औद्योगिक और माल ढुलाई संबंधी सुविधाएँ एक-दूसरे की पूरक हैं।"],"pa":["ਇਹ ਗਲਿਆਰਾ ਆਧੁਨਿਕ ਨਿਰਮਾਣ ਨੂੰ ਕਿਉਂ ਖਿੱਚਦਾ ਹੈ?",["ਇਸ ਵਿੱਚ ਸ਼ਹਿਰ ਨਹੀਂ ਹਨ","ਇਹ ਹੁਨਰਮੰਦ ਕਾਮਿਆਂ, ਬੰਦਰਗਾਹਾਂ, ਬਾਜ਼ਾਰਾਂ ਅਤੇ ਸਪਲਾਇਰਾਂ ਦੇ ਗੁੱਛਾਂ ਨੂੰ ਜੋੜਦਾ ਹੈ","ਇਸ ਵਿੱਚ ਆਵਾਜਾਈ ਦੀ ਘਾਟ ਹੈ","ਸਿਰਫ਼ ਖਣਿਜਾਂ ਦੀ ਨੇੜਤਾ ਅਹਿਮ ਹੈ"],"ਇਸ ਖੇਤਰ ਦੇ ਉਦਯੋਗਿਕ ਅਤੇ ਮਾਲ-ਢੁਆਈ ਦੇ ਲਾਭ ਇੱਕ-ਦੂਜੇ ਦੇ ਪੂਰਕ ਹਨ।"]},
"GEO-IND-001-CP010-Q018":{"h":"ddaa8bbf","hi":["चेन्नई इस गलियारे को परिवहन का कौन-सा लाभ देता है?",["केवल लौह अयस्क की खदान","केवल कोयला क्षेत्र","प्रमुख समुद्री पत्तन तक पहुँच","ज्वारीय खेती"],"चेन्नई के पत्तन से अंतरराष्ट्रीय और तटीय माल ढुलाई बेहतर होती है।"],"pa":["ਚੇਨਈ ਇਸ ਗਲਿਆਰੇ ਨੂੰ ਆਵਾਜਾਈ ਦਾ ਕਿਹੜਾ ਲਾਭ ਦਿੰਦਾ ਹੈ?",["ਸਿਰਫ਼ ਕੱਚੇ ਲੋਹੇ ਦੀ ਖਾਣ","ਸਿਰਫ਼ ਕੋਲਾ ਖੇਤਰ","ਪ੍ਰਮੁੱਖ ਸਮੁੰਦਰੀ ਬੰਦਰਗਾਹ ਤੱਕ ਪਹੁੰਚ","ਜਵਾਰ-ਭਾਟੇ ਵਾਲੀ ਖੇਤੀ"],"ਚੇਨਈ ਦੀ ਬੰਦਰਗਾਹ ਨਾਲ ਕੌਮਾਂਤਰੀ ਅਤੇ ਤੱਟੀ ਮਾਲ-ਢੁਆਈ ਸੁਧਰਦੀ ਹੈ।"]},
"GEO-IND-001-CP010-Q019":{"h":"8ecab6c4","hi":["कौन-सा गलियारा उत्तर और पूर्व के एक प्रमुख माल ढुलाई और औद्योगिक अक्ष के साथ है?",["चेन्नई-बेंगलुरु गलियारा","दिल्ली-मुंबई गलियारा","अमृतसर-कोलकाता औद्योगिक गलियारा","कोच्चि-कोयंबटूर गलियारा"],"अमृतसर-कोलकाता गलियारे की योजना उत्तर और पूर्व के एक प्रमुख औद्योगिक व माल ढुलाई अक्ष के साथ बनाई गई है।"],"pa":["ਕਿਹੜਾ ਗਲਿਆਰਾ ਉੱਤਰ ਅਤੇ ਪੂਰਬ ਦੇ ਇੱਕ ਪ੍ਰਮੁੱਖ ਮਾਲ-ਢੁਆਈ ਅਤੇ ਉਦਯੋਗਿਕ ਧੁਰੇ ਦੇ ਨਾਲ ਹੈ?",["ਚੇਨਈ-ਬੈਂਗਲੁਰੂ ਗਲਿਆਰਾ","ਦਿੱਲੀ-ਮੁੰਬਈ ਗਲਿਆਰਾ","ਅੰਮ੍ਰਿਤਸਰ-ਕੋਲਕਾਤਾ ਉਦਯੋਗਿਕ ਗਲਿਆਰਾ","ਕੋਚੀ-ਕੋਇੰਬਟੂਰ ਗਲਿਆਰਾ"],"ਅੰਮ੍ਰਿਤਸਰ-ਕੋਲਕਾਤਾ ਗਲਿਆਰੇ ਦੀ ਯੋਜਨਾ ਉੱਤਰ ਅਤੇ ਪੂਰਬ ਦੇ ਇੱਕ ਪ੍ਰਮੁੱਖ ਉਦਯੋਗਿਕ ਤੇ ਮਾਲ-ਢੁਆਈ ਧੁਰੇ ਦੇ ਨਾਲ ਬਣਾਈ ਗਈ ਹੈ।"]},
"GEO-IND-001-CP010-Q020":{"h":"07428be3","hi":["अमृतसर-कोलकाता गलियारा भारत के किन हिस्सों को जोड़ता है?",["केवल तटीय केरल","केवल दक्कन के आंतरिक भाग","केवल थार मरुस्थल","उत्तर-पश्चिमी भारत को पूर्वी औद्योगिक पट्टी से"],"यह गलियारा उत्तर और पूर्व के प्रमुख जनसंख्या, कृषि और औद्योगिक क्षेत्रों को जोड़ता है।"],"pa":["ਅੰਮ੍ਰਿਤਸਰ-ਕੋਲਕਾਤਾ ਗਲਿਆਰਾ ਭਾਰਤ ਦੇ ਕਿਹੜੇ ਹਿੱਸਿਆਂ ਨੂੰ ਜੋੜਦਾ ਹੈ?",["ਸਿਰਫ਼ ਤੱਟੀ ਕੇਰਲ","ਸਿਰਫ਼ ਦੱਖਣ ਪਠਾਰ ਦੇ ਅੰਦਰੂਨੀ ਹਿੱਸੇ","ਸਿਰਫ਼ ਥਾਰ ਦਾ ਮਾਰੂਥਲ","ਉੱਤਰ-ਪੱਛਮੀ ਭਾਰਤ ਨੂੰ ਪੂਰਬੀ ਉਦਯੋਗਿਕ ਪੱਟੀ ਨਾਲ"],"ਇਹ ਗਲਿਆਰਾ ਉੱਤਰ ਅਤੇ ਪੂਰਬ ਦੇ ਪ੍ਰਮੁੱਖ ਆਬਾਦੀ, ਖੇਤੀ ਅਤੇ ਉਦਯੋਗਿਕ ਖੇਤਰਾਂ ਨੂੰ ਜੋੜਦਾ ਹੈ।"]},
"GEO-IND-001-CP010-Q021":{"h":"c5a2a0da","hi":["कथनों पर विचार कीजिए: I. यह गलियारा उत्तर के कई प्रमुख राज्यों से होकर गुजरता है। II. माल ढुलाई संपर्क इसके उद्देश्य का मुख्य हिस्सा है। कौन-सा/से कथन सही है/हैं?",["I और II दोनों सही हैं","केवल I सही है","केवल II सही है","न तो I और न ही II सही है"],"औद्योगिक गलियारे एकीकृत माल ढुलाई और औद्योगिक केंद्रों की आधारभूत संरचना पर काफी निर्भर होते हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਇਹ ਗਲਿਆਰਾ ਉੱਤਰ ਦੇ ਕਈ ਪ੍ਰਮੁੱਖ ਰਾਜਾਂ ਵਿੱਚੋਂ ਲੰਘਦਾ ਹੈ। II. ਮਾਲ-ਢੁਆਈ ਸੰਪਰਕ ਇਸ ਦੇ ਉਦੇਸ਼ ਦਾ ਮੁੱਖ ਹਿੱਸਾ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਉਦਯੋਗਿਕ ਗਲਿਆਰੇ ਇਕੱਠੇ ਜੁੜੇ ਮਾਲ-ਢੁਆਈ ਪ੍ਰਬੰਧ ਅਤੇ ਉਦਯੋਗਿਕ ਕੇਂਦਰਾਂ ਦੇ ਬੁਨਿਆਦੀ ਢਾਂਚੇ 'ਤੇ ਬਹੁਤ ਨਿਰਭਰ ਹਨ।"]},
"GEO-IND-001-CP010-Q022":{"h":"f2e24c2d","hi":["कौन-सा युग्म अमृतसर-कोलकाता औद्योगिक गलियारे की सही पहचान करता है?",["अमृतसर-कोलकाता — केवल दक्षिणी तट","अमृतसर-कोलकाता — उत्तरी-पूर्वी औद्योगिक अक्ष","अमृतसर-कोलकाता — केवल जूट गलियारा","अमृतसर-कोलकाता — माल ढुलाई संपर्क का अभाव"],"यह गलियारा उत्तर और पूर्व के औद्योगिक क्षेत्रों को जोड़ता है।"],"pa":["ਕਿਹੜਾ ਜੋੜਾ ਅੰਮ੍ਰਿਤਸਰ-ਕੋਲਕਾਤਾ ਉਦਯੋਗਿਕ ਗਲਿਆਰੇ ਦੀ ਸਹੀ ਪਛਾਣ ਕਰਦਾ ਹੈ?",["ਅੰਮ੍ਰਿਤਸਰ-ਕੋਲਕਾਤਾ — ਸਿਰਫ਼ ਦੱਖਣੀ ਤੱਟ","ਅੰਮ੍ਰਿਤਸਰ-ਕੋਲਕਾਤਾ — ਉੱਤਰੀ ਤੇ ਪੂਰਬੀ ਉਦਯੋਗਿਕ ਧੁਰਾ","ਅੰਮ੍ਰਿਤਸਰ-ਕੋਲਕਾਤਾ — ਸਿਰਫ਼ ਜੂਟ ਦਾ ਗਲਿਆਰਾ","ਅੰਮ੍ਰਿਤਸਰ-ਕੋਲਕਾਤਾ — ਮਾਲ-ਢੁਆਈ ਸੰਪਰਕ ਦੀ ਅਣਹੋਂਦ"],"ਇਹ ਗਲਿਆਰਾ ਉੱਤਰ ਅਤੇ ਪੂਰਬ ਦੇ ਉਦਯੋਗਿਕ ਖੇਤਰਾਂ ਨੂੰ ਜੋੜਦਾ ਹੈ।"]},
"GEO-IND-001-CP010-Q023":{"h":"85d7209b","hi":["यह गलियारा विनिर्माण के साथ कृषि प्रसंस्करण को भी क्यों सहारा दे सकता है?",["वहाँ खेती की ज़मीन नहीं है","केवल खदानों का महत्व है","यह बड़े कृषि और शहरी बाज़ारों से होकर गुजरता है","वहाँ बाज़ार नहीं हैं"],"यह गलियारा उपजाऊ कृषि क्षेत्रों और प्रमुख आबादी केंद्रों से होकर गुजरता है।"],"pa":["ਇਹ ਗਲਿਆਰਾ ਨਿਰਮਾਣ ਦੇ ਨਾਲ ਖੇਤੀ ਉਪਜ ਦੀ ਪ੍ਰੋਸੈਸਿੰਗ ਨੂੰ ਵੀ ਕਿਉਂ ਸਹਾਰਾ ਦੇ ਸਕਦਾ ਹੈ?",["ਇੱਥੇ ਖੇਤੀ ਦੀ ਜ਼ਮੀਨ ਨਹੀਂ ਹੈ","ਸਿਰਫ਼ ਖਾਣਾਂ ਅਹਿਮ ਹਨ","ਇਹ ਵੱਡੇ ਖੇਤੀ ਅਤੇ ਸ਼ਹਿਰੀ ਬਾਜ਼ਾਰਾਂ ਵਿੱਚੋਂ ਲੰਘਦਾ ਹੈ","ਇੱਥੇ ਬਾਜ਼ਾਰ ਨਹੀਂ ਹਨ"],"ਇਹ ਗਲਿਆਰਾ ਚੰਗੀ ਪੈਦਾਵਾਰ ਵਾਲੇ ਖੇਤੀ ਇਲਾਕਿਆਂ ਅਤੇ ਪ੍ਰਮੁੱਖ ਆਬਾਦੀ ਕੇਂਦਰਾਂ ਵਿੱਚੋਂ ਲੰਘਦਾ ਹੈ।"]},
"GEO-IND-001-CP010-Q024":{"h":"1fa1634b","hi":["औद्योगिक गलियारों से सामान्यतः अवस्थिति का कौन-सा कारक मज़बूत होता है?",["खनिजों की रासायनिक संरचना","फसलों का आनुवंशिक स्वरूप","वर्षा का बनना","अंतर-क्षेत्रीय संपर्क"],"गलियारे मुख्य रूप से उत्पादन केंद्रों, आपूर्तिकर्ताओं और बाज़ारों के बीच आवाजाही बेहतर करते हैं।"],"pa":["ਉਦਯੋਗਿਕ ਗਲਿਆਰੇ ਆਮ ਤੌਰ 'ਤੇ ਥਾਂ ਦੀ ਚੋਣ ਦੇ ਕਿਹੜੇ ਕਾਰਕ ਨੂੰ ਮਜ਼ਬੂਤ ਕਰਦੇ ਹਨ?",["ਖਣਿਜਾਂ ਦੀ ਰਸਾਇਣਕ ਬਣਤਰ","ਫ਼ਸਲਾਂ ਦੀ ਜਣਨਿਕ ਬਣਤਰ","ਵਰਖਾ ਦਾ ਬਣਨਾ","ਖੇਤਰਾਂ ਵਿਚਕਾਰ ਸੰਪਰਕ"],"ਗਲਿਆਰੇ ਮੁੱਖ ਤੌਰ 'ਤੇ ਉਤਪਾਦਨ ਕੇਂਦਰਾਂ, ਸਪਲਾਇਰਾਂ ਅਤੇ ਬਾਜ਼ਾਰਾਂ ਵਿਚਕਾਰ ਆਵਾਜਾਈ ਸੁਧਾਰਦੇ ਹਨ।"]},
"GEO-IND-001-CP010-Q025":{"h":"bb3599fb","hi":["मुंबई और कांडला-दीनदयाल जैसे प्रमुख पत्तन-औद्योगिक केंद्र किस तट पर हैं?",["पश्चिमी तट","पूर्वी हिमालय","ऊपरी गंगा का मैदान","केवल मध्य पठार"],"पश्चिमी तट पर कई प्रमुख पत्तन हैं, जो औद्योगिक और पेट्रोरसायन क्षेत्रों को सेवाएँ देते हैं।"],"pa":["ਮੁੰਬਈ ਅਤੇ ਕਾਂਡਲਾ-ਦੀਨਦਿਆਲ ਵਰਗੇ ਪ੍ਰਮੁੱਖ ਬੰਦਰਗਾਹੀ ਉਦਯੋਗਿਕ ਕੇਂਦਰ ਕਿਹੜੇ ਤੱਟ 'ਤੇ ਹਨ?",["ਪੱਛਮੀ ਤੱਟ","ਪੂਰਬੀ ਹਿਮਾਲਿਆ","ਗੰਗਾ ਦਾ ਉੱਪਰਲਾ ਮੈਦਾਨ","ਸਿਰਫ਼ ਕੇਂਦਰੀ ਪਠਾਰ"],"ਪੱਛਮੀ ਤੱਟ 'ਤੇ ਕਈ ਪ੍ਰਮੁੱਖ ਬੰਦਰਗਾਹਾਂ ਹਨ ਜੋ ਉਦਯੋਗਿਕ ਅਤੇ ਪੈਟਰੋ-ਰਸਾਇਣ ਖੇਤਰਾਂ ਨੂੰ ਸੇਵਾਵਾਂ ਦਿੰਦੀਆਂ ਹਨ।"]},
"GEO-IND-001-CP010-Q026":{"h":"f50dc98d","hi":["पश्चिमी तट के पत्तनों पर कच्चे तेल की आवाजाही का किस उद्योग से गहरा संबंध है?",["जूट की खेती","पेट्रोलियम शोधन","चाय की खेती","केवल कोयला खनन"],"कच्चे तेल के आयात और तैयार उत्पादों के निर्यात के कारण शोधनशालाओं के लिए पत्तन महत्वपूर्ण हैं।"],"pa":["ਪੱਛਮੀ ਤੱਟ ਦੀਆਂ ਬੰਦਰਗਾਹਾਂ 'ਤੇ ਕੱਚੇ ਤੇਲ ਦੀ ਢੋਆ-ਢੁਆਈ ਕਿਹੜੇ ਉਦਯੋਗ ਨਾਲ ਨੇੜਿਓਂ ਜੁੜੀ ਹੈ?",["ਜੂਟ ਦੀ ਖੇਤੀ","ਪੈਟਰੋਲੀਅਮ ਦੀ ਸੋਧਾਈ","ਚਾਹ ਦੀ ਖੇਤੀ","ਸਿਰਫ਼ ਕੋਲੇ ਦੀ ਖੁਦਾਈ"],"ਕੱਚੇ ਤੇਲ ਦਾ ਆਯਾਤ ਅਤੇ ਤਿਆਰ ਉਤਪਾਦਾਂ ਦਾ ਨਿਰਯਾਤ ਰਿਫ਼ਾਇਨਰੀਆਂ ਲਈ ਬੰਦਰਗਾਹਾਂ ਨੂੰ ਅਹਿਮ ਬਣਾਉਂਦੇ ਹਨ।"]},
"GEO-IND-001-CP010-Q027":{"h":"5128b6cc","hi":["कथनों पर विचार कीजिए: I. गुजरात में प्रमुख पत्तन हैं। II. गुजरात में प्रमुख पेट्रोरसायन उद्योग भी हैं। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","I और II दोनों सही हैं","न तो I और न ही II सही है"],"पत्तन तक पहुँच और पेट्रोरसायन उद्योग का विकास एक-दूसरे को बढ़ावा देते हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਗੁਜਰਾਤ ਵਿੱਚ ਪ੍ਰਮੁੱਖ ਬੰਦਰਗਾਹਾਂ ਹਨ। II. ਗੁਜਰਾਤ ਵਿੱਚ ਪ੍ਰਮੁੱਖ ਪੈਟਰੋ-ਰਸਾਇਣ ਉਦਯੋਗ ਵੀ ਹਨ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਬੰਦਰਗਾਹਾਂ ਤੱਕ ਪਹੁੰਚ ਅਤੇ ਪੈਟਰੋ-ਰਸਾਇਣਾਂ ਦਾ ਵਿਕਾਸ ਇੱਕ-ਦੂਜੇ ਨੂੰ ਮਜ਼ਬੂਤ ਕਰਦੇ ਹਨ।"]},
"GEO-IND-001-CP010-Q028":{"h":"9c8e1eea","hi":["पश्चिमी तट के औद्योगिक भूगोल में कौन-सा युग्म सही सुमेलित है?",["गुजरात के पत्तन — जूट की खेती","मुंबई पत्तन — कोयला खदान","कांडला — गन्ने का स्रोत","गुजरात के पत्तन — पेट्रोरसायन माल ढुलाई"],"पत्तन बड़ी मात्रा में हाइड्रोकार्बन और रासायनिक माल की आवाजाही में मदद करते हैं।"],"pa":["ਪੱਛਮੀ ਤੱਟ ਦੇ ਉਦਯੋਗਿਕ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਗੁਜਰਾਤ ਦੀਆਂ ਬੰਦਰਗਾਹਾਂ — ਜੂਟ ਦੀ ਖੇਤੀ","ਮੁੰਬਈ ਬੰਦਰਗਾਹ — ਕੋਲੇ ਦੀ ਖਾਣ","ਕਾਂਡਲਾ — ਗੰਨੇ ਦਾ ਸਰੋਤ","ਗੁਜਰਾਤ ਦੀਆਂ ਬੰਦਰਗਾਹਾਂ — ਪੈਟਰੋ-ਰਸਾਇਣਾਂ ਦੀ ਢੋਆ-ਢੁਆਈ"],"ਬੰਦਰਗਾਹਾਂ ਹਾਈਡ੍ਰੋਕਾਰਬਨਾਂ ਅਤੇ ਰਸਾਇਣਕ ਮਾਲ ਦੀਆਂ ਵੱਡੀਆਂ ਖੇਪਾਂ ਢੋਣ ਵਿੱਚ ਮਦਦ ਕਰਦੀਆਂ ਹਨ।"]},
"GEO-IND-001-CP010-Q029":{"h":"7be72770","hi":["पश्चिमी तट के पत्तन निर्यात-उन्मुख विनिर्माण को क्यों आकर्षित कर सकते हैं?",["उनसे अंतरराष्ट्रीय जहाज़रानी मार्गों तक सीधी पहुँच मिलती है","वे श्रम की ज़रूरत खत्म करते हैं","वे कच्चा माल बनाते हैं","वे बाज़ारों की जगह लेते हैं"],"पत्तन पास होने से आयात और निर्यात की समुद्री ढुलाई का ख़र्च घटता है।"],"pa":["ਪੱਛਮੀ ਤੱਟ ਦੀਆਂ ਬੰਦਰਗਾਹਾਂ ਨਿਰਯਾਤ ਲਈ ਉਤਪਾਦ ਬਣਾਉਣ ਵਾਲੇ ਉਦਯੋਗਾਂ ਨੂੰ ਕਿਉਂ ਖਿੱਚ ਸਕਦੀਆਂ ਹਨ?",["ਇਨ੍ਹਾਂ ਤੋਂ ਕੌਮਾਂਤਰੀ ਸਮੁੰਦਰੀ ਮਾਰਗਾਂ ਤੱਕ ਸਿੱਧੀ ਪਹੁੰਚ ਮਿਲਦੀ ਹੈ","ਇਨ੍ਹਾਂ ਨਾਲ ਕਾਮਿਆਂ ਦੀ ਲੋੜ ਮੁੱਕ ਜਾਂਦੀ ਹੈ","ਇਹ ਕੱਚਾ ਮਾਲ ਬਣਾਉਂਦੀਆਂ ਹਨ","ਇਹ ਬਾਜ਼ਾਰਾਂ ਦੀ ਥਾਂ ਲੈਂਦੀਆਂ ਹਨ"],"ਬੰਦਰਗਾਹ ਨੇੜੇ ਹੋਣ ਨਾਲ ਆਯਾਤ ਅਤੇ ਨਿਰਯਾਤ ਦੀ ਸਮੁੰਦਰੀ ਢੋਆ-ਢੁਆਈ ਦਾ ਖ਼ਰਚ ਘਟਦਾ ਹੈ।"]},
"GEO-IND-001-CP010-Q030":{"h":"ce653d9e","hi":["पत्तन आधारित और स्रोत-उन्मुख औद्योगिक अवस्थिति की कौन-सी तुलना सही है?",["दोनों परिवहन की अनदेखी करते हैं","पत्तन आधारित उद्योगों में समुद्री ढुलाई, जबकि खदान के मुहाने के उद्योगों में स्रोत की निकटता महत्वपूर्ण है","पत्तन खदानें हैं","खदान के मुहाने के संयंत्र केवल आयात पर निर्भर हैं"],"दोनों प्रकार की अवस्थिति अलग-अलग परिवहन और कच्चे माल की स्थितियों पर निर्भर करती हैं।"],"pa":["ਬੰਦਰਗਾਹ-ਆਧਾਰਿਤ ਅਤੇ ਕੱਚੇ ਮਾਲ ਦੇ ਸਰੋਤ ਨੇੜੇ ਲੱਗੇ ਉਦਯੋਗਾਂ ਦੀ ਕਿਹੜੀ ਤੁਲਨਾ ਸਹੀ ਹੈ?",["ਦੋਵੇਂ ਆਵਾਜਾਈ ਨੂੰ ਅਣਗੌਲਿਆ ਕਰਦੇ ਹਨ","ਬੰਦਰਗਾਹੀ ਉਦਯੋਗਾਂ ਲਈ ਸਮੁੰਦਰੀ ਢੋਆ-ਢੁਆਈ, ਜਦਕਿ ਖਾਣ ਦੇ ਮੂੰਹ ਵਾਲੇ ਉਦਯੋਗਾਂ ਲਈ ਸਰੋਤ ਦੀ ਨੇੜਤਾ ਅਹਿਮ ਹੈ","ਬੰਦਰਗਾਹਾਂ ਖਾਣਾਂ ਹਨ","ਖਾਣ ਦੇ ਮੂੰਹ ਵਾਲੇ ਪਲਾਂਟ ਸਿਰਫ਼ ਆਯਾਤ 'ਤੇ ਨਿਰਭਰ ਹਨ"],"ਦੋਵੇਂ ਕਿਸਮਾਂ ਦੀ ਥਾਂ ਢੋਆ-ਢੁਆਈ ਅਤੇ ਕੱਚੇ ਮਾਲ ਦੇ ਵੱਖੋ-ਵੱਖਰੇ ਹਾਲਾਤਾਂ 'ਤੇ ਨਿਰਭਰ ਹੈ।"]},
"GEO-IND-001-CP010-Q031":{"h":"377c6742","hi":["पूर्वी तट के किस शहर में प्रमुख पत्तन के साथ इस्पात और पेट्रोलियम उद्योग भी हैं?",["झरिया","कोडरमा","विशाखापत्तनम","सांभर"],"विशाखापत्तनम प्रमुख पत्तन-औद्योगिक केंद्र है, जहाँ इस्पात, तेल शोधन और अन्य उद्योग हैं।"],"pa":["ਪੂਰਬੀ ਤੱਟ ਦੇ ਕਿਹੜੇ ਸ਼ਹਿਰ ਵਿੱਚ ਪ੍ਰਮੁੱਖ ਬੰਦਰਗਾਹ ਦੇ ਨਾਲ ਸਟੀਲ ਅਤੇ ਪੈਟਰੋਲੀਅਮ ਉਦਯੋਗ ਹਨ?",["ਝਰੀਆ","ਕੋਡਰਮਾ","ਵਿਸ਼ਾਖਾਪਟਨਮ","ਸਾਂਭਰ"],"ਵਿਸ਼ਾਖਾਪਟਨਮ ਇੱਕ ਪ੍ਰਮੁੱਖ ਬੰਦਰਗਾਹੀ ਉਦਯੋਗਿਕ ਕੇਂਦਰ ਹੈ ਜਿੱਥੇ ਸਟੀਲ, ਤੇਲ ਦੀ ਸੋਧਾਈ ਅਤੇ ਹੋਰ ਉਦਯੋਗ ਹਨ।"]},
"GEO-IND-001-CP010-Q032":{"h":"ed6e9936","hi":["विशाखापत्तनम में भारी उद्योग को कौन-सा कारक सहारा देता है?",["केवल जूट की खेती","चाय के बागान","परिवहन का अभाव","बड़ी खेपों के लिए पत्तन तक पहुँच"],"पत्तन से कच्चे माल और तैयार उत्पादों की कुशल आवाजाही संभव होती है।"],"pa":["ਵਿਸ਼ਾਖਾਪਟਨਮ ਵਿੱਚ ਭਾਰੀ ਉਦਯੋਗ ਨੂੰ ਕਿਹੜਾ ਕਾਰਕ ਸਹਾਰਾ ਦਿੰਦਾ ਹੈ?",["ਸਿਰਫ਼ ਜੂਟ ਦੀ ਖੇਤੀ","ਚਾਹ ਦੇ ਬਾਗ਼","ਆਵਾਜਾਈ ਦੀ ਅਣਹੋਂਦ","ਵੱਡੀਆਂ ਖੇਪਾਂ ਲਈ ਬੰਦਰਗਾਹ ਤੱਕ ਪਹੁੰਚ"],"ਬੰਦਰਗਾਹ ਰਾਹੀਂ ਕੱਚਾ ਮਾਲ ਅਤੇ ਤਿਆਰ ਉਤਪਾਦ ਸੁਚੱਜੇ ਢੰਗ ਨਾਲ ਢੋਏ ਜਾ ਸਕਦੇ ਹਨ।"]},
"GEO-IND-001-CP010-Q033":{"h":"a39ce84b","hi":["कथनों पर विचार कीजिए: I. विशाखापत्तनम पूर्वी तट पर है। II. वहाँ एक प्रमुख इस्पात संयंत्र है। कौन-सा/से कथन सही है/हैं?",["I और II दोनों सही हैं","केवल I सही है","केवल II सही है","न तो I और न ही II सही है"],"दोनों कथन विशाखापत्तनम के पत्तन और औद्योगिक भूगोल के लिए महत्वपूर्ण हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਵਿਸ਼ਾਖਾਪਟਨਮ ਪੂਰਬੀ ਤੱਟ 'ਤੇ ਹੈ। II. ਇੱਥੇ ਇੱਕ ਪ੍ਰਮੁੱਖ ਸਟੀਲ ਪਲਾਂਟ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਦੋਵੇਂ ਕਥਨ ਵਿਸ਼ਾਖਾਪਟਨਮ ਦੀ ਬੰਦਰਗਾਹ ਅਤੇ ਉਦਯੋਗਿਕ ਭੂਗੋਲ ਲਈ ਅਹਿਮ ਹਨ।"]},
"GEO-IND-001-CP010-Q034":{"h":"93740ead","hi":["पूर्वी तट के पत्तन आधारित उद्योग में कौन-सा युग्म सही सुमेलित है?",["विशाखापत्तनम — केवल जूट पट्टी","विशाखापत्तनम — इस्पात और पत्तन","विशाखापत्तनम — आंतरिक कोयला क्षेत्र","विशाखापत्तनम — केवल चीनी क्षेत्र"],"विशाखापत्तनम पत्तन शहर है, जहाँ इस्पात और अन्य औद्योगिक गतिविधियाँ बड़े पैमाने पर होती हैं।"],"pa":["ਪੂਰਬੀ ਤੱਟ ਦੇ ਬੰਦਰਗਾਹੀ ਉਦਯੋਗਾਂ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਵਿਸ਼ਾਖਾਪਟਨਮ — ਸਿਰਫ਼ ਜੂਟ ਪੱਟੀ","ਵਿਸ਼ਾਖਾਪਟਨਮ — ਸਟੀਲ ਅਤੇ ਬੰਦਰਗਾਹ","ਵਿਸ਼ਾਖਾਪਟਨਮ — ਅੰਦਰੂਨੀ ਕੋਲਾ ਖੇਤਰ","ਵਿਸ਼ਾਖਾਪਟਨਮ — ਸਿਰਫ਼ ਖੰਡ ਖੇਤਰ"],"ਵਿਸ਼ਾਖਾਪਟਨਮ ਇੱਕ ਬੰਦਰਗਾਹੀ ਸ਼ਹਿਰ ਹੈ ਜਿੱਥੇ ਸਟੀਲ ਅਤੇ ਹੋਰ ਉਦਯੋਗਿਕ ਸਰਗਰਮੀਆਂ ਵੱਡੇ ਪੱਧਰ 'ਤੇ ਹੁੰਦੀਆਂ ਹਨ।"]},
"GEO-IND-001-CP010-Q035":{"h":"a2de85ea","hi":["पूर्वी तट के पत्तन खनिज आधारित उद्योगों की मदद कैसे कर सकते हैं?",["वे खनिज उगाते हैं","वे माल ढुलाई समाप्त करते हैं","वे अयस्क, कोयला और अन्य भारी खेपें कुशलता से सँभाल सकते हैं","वे केवल पर्यटन पर निर्भर हैं"],"पत्तनों से भारी औद्योगिक कच्चे माल की ढुलाई की लागत घटती है।"],"pa":["ਪੂਰਬੀ ਤੱਟ ਦੀਆਂ ਬੰਦਰਗਾਹਾਂ ਖਣਿਜ-ਆਧਾਰਿਤ ਉਦਯੋਗਾਂ ਨੂੰ ਕਿਵੇਂ ਸਹਾਰਾ ਦੇ ਸਕਦੀਆਂ ਹਨ?",["ਉਹ ਖਣਿਜ ਉਗਾਉਂਦੀਆਂ ਹਨ","ਉਹ ਮਾਲ-ਢੁਆਈ ਖ਼ਤਮ ਕਰਦੀਆਂ ਹਨ","ਉਹ ਅਯਸਕ, ਕੋਲਾ ਅਤੇ ਹੋਰ ਵੱਡੀਆਂ ਖੇਪਾਂ ਸੁਚੱਜੇ ਢੰਗ ਨਾਲ ਸੰਭਾਲ ਸਕਦੀਆਂ ਹਨ","ਉਹ ਸਿਰਫ਼ ਸੈਰ-ਸਪਾਟੇ 'ਤੇ ਨਿਰਭਰ ਹਨ"],"ਬੰਦਰਗਾਹਾਂ ਨਾਲ ਭਾਰੀ ਉਦਯੋਗਿਕ ਕੱਚਾ ਮਾਲ ਢੋਣ ਦਾ ਖ਼ਰਚ ਘਟਦਾ ਹੈ।"]},
"GEO-IND-001-CP010-Q036":{"h":"f86de816","hi":["विशाखापत्तनम और जमशेदपुर के इस्पात संयंत्रों की अवस्थिति की कौन-सी तुलना सही है?",["दोनों अपतटीय हैं","जमशेदपुर पत्तन शहर है","विशाखापत्तनम झारखंड में है","विशाखापत्तनम पत्तन की ओर, जबकि जमशेदपुर खनिज पट्टी की ओर उन्मुख है"],"दोनों संयंत्र अवस्थिति की अलग-अलग रणनीतियों के उदाहरण हैं।"],"pa":["ਵਿਸ਼ਾਖਾਪਟਨਮ ਅਤੇ ਜਮਸ਼ੇਦਪੁਰ ਦੇ ਸਟੀਲ ਪਲਾਂਟਾਂ ਦੀ ਥਾਂ ਦੀ ਕਿਹੜੀ ਤੁਲਨਾ ਸਹੀ ਹੈ?",["ਦੋਵੇਂ ਤੱਟ ਤੋਂ ਪਰ੍ਹੇ ਸਮੁੰਦਰ ਵਿੱਚ ਹਨ","ਜਮਸ਼ੇਦਪੁਰ ਬੰਦਰਗਾਹੀ ਸ਼ਹਿਰ ਹੈ","ਵਿਸ਼ਾਖਾਪਟਨਮ ਝਾਰਖੰਡ ਵਿੱਚ ਹੈ","ਵਿਸ਼ਾਖਾਪਟਨਮ ਬੰਦਰਗਾਹ ਵੱਲ ਅਤੇ ਜਮਸ਼ੇਦਪੁਰ ਖਣਿਜ ਪੱਟੀ ਵੱਲ ਕੇਂਦਰਿਤ ਹੈ"],"ਦੋਵੇਂ ਪਲਾਂਟ ਥਾਂ ਚੁਣਨ ਦੇ ਵੱਖੋ-ਵੱਖਰੇ ਢੰਗਾਂ ਦੀਆਂ ਉਦਾਹਰਨਾਂ ਹਨ।"]},
"GEO-IND-001-CP010-Q037":{"h":"48ee4faf","hi":["प्रमुख पूर्वी समर्पित माल ढुलाई अक्ष से भारत के किस भाग को सेवा मिलती है?",["उत्तरी और पूर्वी भारत","केवल केरल का तट","केवल पश्चिमी राजस्थान","केवल अंडमान द्वीपसमूह"],"पूर्वी माल ढुलाई अक्ष उत्तर और पूर्व के प्रमुख उत्पादन और उपभोग क्षेत्रों को जोड़ता है।"],"pa":["ਪ੍ਰਮੁੱਖ ਪੂਰਬੀ ਸਮਰਪਿਤ ਮਾਲ-ਢੁਆਈ ਧੁਰਾ ਭਾਰਤ ਦੇ ਕਿਹੜੇ ਹਿੱਸੇ ਨੂੰ ਸੇਵਾ ਦਿੰਦਾ ਹੈ?",["ਉੱਤਰੀ ਅਤੇ ਪੂਰਬੀ ਭਾਰਤ","ਸਿਰਫ਼ ਕੇਰਲ ਤੱਟ","ਸਿਰਫ਼ ਪੱਛਮੀ ਰਾਜਸਥਾਨ","ਸਿਰਫ਼ ਅੰਡਮਾਨ ਟਾਪੂ"],"ਪੂਰਬੀ ਮਾਲ-ਢੁਆਈ ਧੁਰਾ ਉੱਤਰ ਅਤੇ ਪੂਰਬ ਦੇ ਪ੍ਰਮੁੱਖ ਉਤਪਾਦਨ ਅਤੇ ਖਪਤ ਖੇਤਰਾਂ ਨੂੰ ਜੋੜਦਾ ਹੈ।"]},
"GEO-IND-001-CP010-Q038":{"h":"94314a8b","hi":["समर्पित माल ढुलाई गलियारा उद्योगों को क्यों आकर्षित कर सकता है?",["यह अयस्क की रासायनिक संरचना बदलता है","यह ढुलाई का समय घटाता है और बड़ी खेपों की आवाजाही सुधारता है","यह वर्षा बढ़ाता है","यह बाज़ार हटा देता है"],"माल ढुलाई में दक्षता से औद्योगिक केंद्र अधिक प्रतिस्पर्धी बन सकते हैं।"],"pa":["ਸਮਰਪਿਤ ਮਾਲ-ਢੁਆਈ ਗਲਿਆਰਾ ਉਦਯੋਗਾਂ ਨੂੰ ਕਿਉਂ ਖਿੱਚ ਸਕਦਾ ਹੈ?",["ਇਹ ਅਯਸਕ ਦੀ ਰਸਾਇਣਕ ਬਣਤਰ ਬਦਲਦਾ ਹੈ","ਇਹ ਮਾਲ ਢੋਣ ਦਾ ਸਮਾਂ ਘਟਾਉਂਦਾ ਹੈ ਅਤੇ ਵੱਡੀਆਂ ਖੇਪਾਂ ਦੀ ਆਵਾਜਾਈ ਸੁਧਾਰਦਾ ਹੈ","ਇਹ ਵਰਖਾ ਵਧਾਉਂਦਾ ਹੈ","ਇਹ ਬਾਜ਼ਾਰ ਹਟਾ ਦਿੰਦਾ ਹੈ"],"ਸੁਚੱਜੀ ਮਾਲ-ਢੁਆਈ ਨਾਲ ਉਦਯੋਗਿਕ ਕੇਂਦਰ ਵੱਧ ਮੁਕਾਬਲੇਬਾਜ਼ ਬਣ ਸਕਦੇ ਹਨ।"]},
"GEO-IND-001-CP010-Q039":{"h":"a353d305","hi":["कथनों पर विचार कीजिए: I. माल ढुलाई गलियारों से माल की आवाजाही की व्यवस्था सुधरती है। II. प्रमुख परिवहन अक्षों के आसपास औद्योगिक केंद्र विकसित हो सकते हैं। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","I और II दोनों सही हैं","न तो I और न ही II सही है"],"परिवहन की आधारभूत संरचना आधुनिक उद्योगों की अवस्थिति को प्रभावित कर सकती है।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਮਾਲ-ਢੁਆਈ ਗਲਿਆਰਿਆਂ ਨਾਲ ਮਾਲ ਢੋਣ ਦਾ ਪ੍ਰਬੰਧ ਸੁਧਰਦਾ ਹੈ। II. ਪ੍ਰਮੁੱਖ ਆਵਾਜਾਈ ਧੁਰਿਆਂ ਨੇੜੇ ਉਦਯੋਗਿਕ ਕੇਂਦਰ ਵਿਕਸਿਤ ਹੋ ਸਕਦੇ ਹਨ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਆਵਾਜਾਈ ਦਾ ਬੁਨਿਆਦੀ ਢਾਂਚਾ ਆਧੁਨਿਕ ਉਦਯੋਗਾਂ ਦੀ ਥਾਂ 'ਤੇ ਅਸਰ ਪਾ ਸਕਦਾ ਹੈ।"]},
"GEO-IND-001-CP010-Q040":{"h":"4568820d","hi":["माल ढुलाई गलियारे में कौन-सा युग्म सही सुमेलित है?",["समर्पित मालवाहक रेलमार्ग — जूट की खेती","समर्पित मालवाहक रेलमार्ग — अयस्क की उत्पत्ति","समर्पित मालवाहक रेलमार्ग — वर्षा","समर्पित मालवाहक रेलमार्ग — औद्योगिक माल ढुलाई"],"इसका मुख्य उद्देश्य कुशल माल ढुलाई है।"],"pa":["ਮਾਲ-ਢੁਆਈ ਗਲਿਆਰੇ ਬਾਰੇ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਸਮਰਪਿਤ ਮਾਲ ਰੇਲ ਮਾਰਗ — ਜੂਟ ਦੀ ਖੇਤੀ","ਸਮਰਪਿਤ ਮਾਲ ਰੇਲ ਮਾਰਗ — ਅਯਸਕ ਦਾ ਬਣਨਾ","ਸਮਰਪਿਤ ਮਾਲ ਰੇਲ ਮਾਰਗ — ਵਰਖਾ","ਸਮਰਪਿਤ ਮਾਲ ਰੇਲ ਮਾਰਗ — ਉਦਯੋਗਿਕ ਮਾਲ-ਢੁਆਈ"],"ਇਸ ਦਾ ਮੁੱਖ ਉਦੇਸ਼ ਮਾਲ ਨੂੰ ਸੁਚੱਜੇ ਢੰਗ ਨਾਲ ਢੋਣਾ ਹੈ।"]},
"GEO-IND-001-CP010-Q041":{"h":"b89a5308","hi":["बड़ी मात्रा में माल की भरोसेमंद रेल ढुलाई से किस प्रकार के उद्योग को विशेष लाभ होता है?",["भारी विनिर्माण","केवल कुटीर हस्तशिल्प","केवल पर्यटन","केवल निर्वाह कृषि"],"भारी विनिर्माण में बड़ी मात्रा में कच्चा माल और तैयार उत्पाद ढोए जाते हैं।"],"pa":["ਵੱਡੀ ਮਾਤਰਾ ਵਿੱਚ ਮਾਲ ਦੀ ਭਰੋਸੇਯੋਗ ਰੇਲ ਢੋਆ-ਢੁਆਈ ਦਾ ਖ਼ਾਸ ਲਾਭ ਕਿਸ ਕਿਸਮ ਦੇ ਉਦਯੋਗ ਨੂੰ ਹੁੰਦਾ ਹੈ?",["ਭਾਰੀ ਨਿਰਮਾਣ","ਸਿਰਫ਼ ਘਰੇਲੂ ਦਸਤਕਾਰੀ","ਸਿਰਫ਼ ਸੈਰ-ਸਪਾਟਾ","ਸਿਰਫ਼ ਗੁਜ਼ਾਰੇ ਲਈ ਖੇਤੀ"],"ਭਾਰੀ ਨਿਰਮਾਣ ਲਈ ਕੱਚਾ ਮਾਲ ਅਤੇ ਤਿਆਰ ਉਤਪਾਦ ਵੱਡੀ ਮਾਤਰਾ ਵਿੱਚ ਢੋਏ ਜਾਂਦੇ ਹਨ।"]},
"GEO-IND-001-CP010-Q042":{"h":"783e6832","hi":["माल ढुलाई गलियारे में निवेश से अवस्थिति का कौन-सा कारक सबसे सीधे मज़बूत होता है?",["खनिज की श्रेणी","परिवहन संपर्क","मिट्टी की उर्वरता","प्राकृतिक वनस्पति"],"माल ढुलाई गलियारे मुख्यतः माल की आवाजाही और परिवहन संपर्क में सुधार करते हैं।"],"pa":["ਮਾਲ-ਢੁਆਈ ਗਲਿਆਰੇ ਵਿੱਚ ਨਿਵੇਸ਼ ਨਾਲ ਥਾਂ ਦਾ ਕਿਹੜਾ ਕਾਰਕ ਸਭ ਤੋਂ ਸਿੱਧੇ ਤੌਰ 'ਤੇ ਮਜ਼ਬੂਤ ਹੁੰਦਾ ਹੈ?",["ਖਣਿਜ ਦਾ ਦਰਜਾ","ਆਵਾਜਾਈ ਸੰਪਰਕ","ਮਿੱਟੀ ਦੀ ਉਪਜਾਊ ਸ਼ਕਤੀ","ਕੁਦਰਤੀ ਬਨਸਪਤੀ"],"ਮਾਲ-ਢੁਆਈ ਗਲਿਆਰੇ ਮੁੱਖ ਤੌਰ 'ਤੇ ਮਾਲ ਢੋਣ ਦੇ ਪ੍ਰਬੰਧ ਅਤੇ ਆਵਾਜਾਈ ਸੰਪਰਕ ਸੁਧਾਰਦੇ ਹਨ।"]},
"GEO-IND-001-CP010-Q043":{"h":"a5cb5ce7","hi":["गलियारे की योजना में औद्योगिक केंद्र का क्या अर्थ है?",["खनिज का एक प्रकार","खेती का मौसम","प्रमुख परिवहन ढाँचे से जुड़ा सघन औद्योगिक क्षेत्र","नदी का उद्गम"],"औद्योगिक केंद्र महत्वपूर्ण परिवहन स्थानों के आसपास विनिर्माण, माल ढुलाई और सेवाओं को एकत्र करते हैं।"],"pa":["ਗਲਿਆਰੇ ਦੀ ਯੋਜਨਾ ਵਿੱਚ ਉਦਯੋਗਿਕ ਕੇਂਦਰ ਕੀ ਹੁੰਦਾ ਹੈ?",["ਖਣਿਜ ਦੀ ਇੱਕ ਕਿਸਮ","ਖੇਤੀ ਦਾ ਮੌਸਮ","ਪ੍ਰਮੁੱਖ ਆਵਾਜਾਈ ਢਾਂਚੇ ਨਾਲ ਜੁੜਿਆ ਸੰਘਣਾ ਉਦਯੋਗਿਕ ਖੇਤਰ","ਦਰਿਆ ਦਾ ਸਰੋਤ"],"ਉਦਯੋਗਿਕ ਕੇਂਦਰ ਅਹਿਮ ਆਵਾਜਾਈ ਥਾਵਾਂ ਕੋਲ ਨਿਰਮਾਣ, ਮਾਲ-ਢੁਆਈ ਅਤੇ ਸੇਵਾਵਾਂ ਨੂੰ ਇਕੱਠਾ ਕਰਦੇ ਹਨ।"]},
"GEO-IND-001-CP010-Q044":{"h":"60f51c9f","hi":["आधुनिक उद्योगों के लिए माल ढुलाई केंद्र क्यों महत्वपूर्ण हैं?",["वे लौह अयस्क बनाते हैं","वे कारखानों की जगह लेते हैं","वे वर्षा तय करते हैं","वे भंडारण, माल का स्थानांतरण और वितरण संभालते हैं"],"माल की कुशल आवाजाही से आपूर्तिकर्ताओं, संयंत्रों और बाज़ारों के बीच समय और लागत घटते हैं।"],"pa":["ਆਧੁਨਿਕ ਉਦਯੋਗਾਂ ਲਈ ਮਾਲ-ਢੁਆਈ ਕੇਂਦਰ ਕਿਉਂ ਅਹਿਮ ਹਨ?",["ਉਹ ਕੱਚਾ ਲੋਹਾ ਬਣਾਉਂਦੇ ਹਨ","ਉਹ ਕਾਰਖ਼ਾਨਿਆਂ ਦੀ ਥਾਂ ਲੈਂਦੇ ਹਨ","ਉਹ ਵਰਖਾ ਤੈਅ ਕਰਦੇ ਹਨ","ਉਹ ਭੰਡਾਰਨ, ਮਾਲ ਦੀ ਬਦਲੀ ਅਤੇ ਵੰਡ ਦਾ ਪ੍ਰਬੰਧ ਕਰਦੇ ਹਨ"],"ਸੁਚੱਜੀ ਮਾਲ-ਢੁਆਈ ਨਾਲ ਸਪਲਾਇਰਾਂ, ਪਲਾਂਟਾਂ ਅਤੇ ਬਾਜ਼ਾਰਾਂ ਵਿਚਕਾਰ ਸਮਾਂ ਤੇ ਖ਼ਰਚ ਘਟਦੇ ਹਨ।"]},
"GEO-IND-001-CP010-Q045":{"h":"14f99310","hi":["कथनों पर विचार कीजिए: I. औद्योगिक केंद्रों को परिवहन संपर्कों से लाभ होता है। II. माल ढुलाई केंद्र सड़क, रेल और पत्तनों को जोड़ सकते हैं। कौन-सा/से कथन सही है/हैं?",["I और II दोनों सही हैं","केवल I सही है","केवल II सही है","न तो I और न ही II सही है"],"परिवहन के कई साधनों से संपर्क आधुनिक औद्योगिक संकुलों के लिए महत्वपूर्ण है।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਉਦਯੋਗਿਕ ਕੇਂਦਰਾਂ ਨੂੰ ਆਵਾਜਾਈ ਸੰਪਰਕਾਂ ਤੋਂ ਲਾਭ ਹੁੰਦਾ ਹੈ। II. ਮਾਲ-ਢੁਆਈ ਕੇਂਦਰ ਸੜਕਾਂ, ਰੇਲਾਂ ਅਤੇ ਬੰਦਰਗਾਹਾਂ ਨੂੰ ਜੋੜ ਸਕਦੇ ਹਨ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਆਵਾਜਾਈ ਦੇ ਕਈ ਸਾਧਨਾਂ ਨਾਲ ਸੰਪਰਕ ਆਧੁਨਿਕ ਉਦਯੋਗਿਕ ਗੁੱਛਾਂ ਲਈ ਅਹਿਮ ਹੈ।"]},
"GEO-IND-001-CP010-Q046":{"h":"5466f798","hi":["आधुनिक औद्योगिक भूगोल में कौन-सा युग्म सही सुमेलित है?",["माल ढुलाई केंद्र — जूट की खेती","माल ढुलाई केंद्र — कई परिवहन साधनों से माल की आवाजाही","औद्योगिक केंद्र — खनिजों की उत्पत्ति","पत्तन — गन्ने की खेती"],"माल ढुलाई केंद्र परिवहन के कई साधनों के बीच समन्वय करते हैं।"],"pa":["ਆਧੁਨਿਕ ਉਦਯੋਗਿਕ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਮਾਲ-ਢੁਆਈ ਕੇਂਦਰ — ਜੂਟ ਦੀ ਖੇਤੀ","ਮਾਲ-ਢੁਆਈ ਕੇਂਦਰ — ਕਈ ਸਾਧਨਾਂ ਰਾਹੀਂ ਮਾਲ ਸੰਭਾਲਣਾ","ਉਦਯੋਗਿਕ ਕੇਂਦਰ — ਖਣਿਜਾਂ ਦਾ ਬਣਨਾ","ਬੰਦਰਗਾਹ — ਗੰਨੇ ਦੀ ਖੇਤੀ"],"ਮਾਲ-ਢੁਆਈ ਕੇਂਦਰ ਆਵਾਜਾਈ ਦੇ ਕਈ ਸਾਧਨਾਂ ਵਿਚਕਾਰ ਤਾਲਮੇਲ ਬਣਾਉਂਦੇ ਹਨ।"]},
"GEO-IND-001-CP010-Q047":{"h":"48ba88be","hi":["पत्तन से दूर होने पर भी किस कारण कोई आंतरिक औद्योगिक केंद्र प्रतिस्पर्धी बन सकता है?",["परिवहन का अभाव","केवल वर्षा","उच्च गुणवत्ता वाले रेल और सड़क संपर्क","केवल मिट्टी का रंग"],"आंतरिक इलाकों में कुशल माल ढुलाई, समुद्री पत्तनों से दूरी की कमी को दूर कर सकती है।"],"pa":["ਬੰਦਰਗਾਹ ਤੋਂ ਦੂਰ ਹੋਣ ਦੇ ਬਾਵਜੂਦ ਕਿਹੜਾ ਕਾਰਕ ਕਿਸੇ ਅੰਦਰੂਨੀ ਉਦਯੋਗਿਕ ਕੇਂਦਰ ਨੂੰ ਮੁਕਾਬਲੇਯੋਗ ਬਣਾ ਸਕਦਾ ਹੈ?",["ਆਵਾਜਾਈ ਦੀ ਅਣਹੋਂਦ","ਸਿਰਫ਼ ਵਰਖਾ","ਉੱਚ ਗੁਣਵੱਤਾ ਵਾਲੇ ਰੇਲ ਤੇ ਸੜਕ ਸੰਪਰਕ","ਸਿਰਫ਼ ਮਿੱਟੀ ਦਾ ਰੰਗ"],"ਅੰਦਰੂਨੀ ਇਲਾਕਿਆਂ ਵਿੱਚ ਸੁਚੱਜੀ ਮਾਲ-ਢੁਆਈ ਸਮੁੰਦਰੀ ਬੰਦਰਗਾਹਾਂ ਤੋਂ ਦੂਰੀ ਦੇ ਨੁਕਸਾਨ ਨੂੰ ਘਟਾ ਸਕਦੀ ਹੈ।"]},
"GEO-IND-001-CP010-Q048":{"h":"60629eef","hi":["एक विनिर्माण क्षेत्र मालवाहक टर्मिनल, द्रुतमार्ग और गोदामों के संकुल के पास है। इसका सबसे उपयुक्त वर्णन क्या है?",["केवल कृषि गाँव","खनिज की परत","जलविद्युत स्थल","औद्योगिक और माल ढुलाई केंद्र"],"विनिर्माण और कई साधनों से माल की आवाजाही का मेल एक औद्योगिक केंद्र की पहचान है।"],"pa":["ਇੱਕ ਨਿਰਮਾਣ ਖੇਤਰ ਮਾਲ ਟਰਮੀਨਲ, ਤੇਜ਼ ਰਫ਼ਤਾਰ ਮਾਰਗ ਅਤੇ ਗੋਦਾਮਾਂ ਦੇ ਗੁੱਛ ਕੋਲ ਹੈ। ਇਸ ਦਾ ਸਭ ਤੋਂ ਢੁੱਕਵਾਂ ਵਰਣਨ ਕੀ ਹੈ?",["ਸਿਰਫ਼ ਖੇਤੀ ਵਾਲਾ ਪਿੰਡ","ਖਣਿਜ ਦੀ ਪਰਤ","ਪਣ-ਬਿਜਲੀ ਵਾਲੀ ਥਾਂ","ਉਦਯੋਗਿਕ ਅਤੇ ਮਾਲ-ਢੁਆਈ ਕੇਂਦਰ"],"ਨਿਰਮਾਣ ਅਤੇ ਕਈ ਸਾਧਨਾਂ ਰਾਹੀਂ ਮਾਲ ਢੋਣ ਦਾ ਮੇਲ ਉਦਯੋਗਿਕ ਕੇਂਦਰ ਦੀ ਪਛਾਣ ਹੈ।"]},
"GEO-IND-001-CP010-Q049":{"h":"eb67ee5b","hi":["पत्तन के पास निर्यात-उन्मुख क्षेत्र की अवस्थिति का मुख्य औद्योगिक लाभ क्या है?",["अंतरराष्ट्रीय व्यापार मार्गों तक कुशल पहुँच","लौह अयस्क तक स्वतः पहुँच","श्रम की ज़रूरत नहीं","बाज़ारों की ज़रूरत नहीं"],"पत्तनों की निकटता से निर्यात-उन्मुख उद्योगों का माल ढुलाई समय और लागत घटते हैं।"],"pa":["ਬੰਦਰਗਾਹ ਨੇੜੇ ਨਿਰਯਾਤ ਲਈ ਬਣੇ ਉਦਯੋਗਿਕ ਖੇਤਰ ਨੂੰ ਥਾਂ ਦਾ ਮੁੱਖ ਲਾਭ ਕੀ ਹੈ?",["ਕੌਮਾਂਤਰੀ ਵਪਾਰ ਮਾਰਗਾਂ ਤੱਕ ਸੁਚੱਜੀ ਪਹੁੰਚ","ਕੱਚੇ ਲੋਹੇ ਤੱਕ ਆਪਣੇ ਆਪ ਪਹੁੰਚ","ਕਾਮਿਆਂ ਦੀ ਲੋੜ ਨਹੀਂ","ਬਾਜ਼ਾਰਾਂ ਦੀ ਲੋੜ ਨਹੀਂ"],"ਬੰਦਰਗਾਹ ਨੇੜੇ ਹੋਣ ਨਾਲ ਨਿਰਯਾਤ ਲਈ ਉਤਪਾਦ ਬਣਾਉਣ ਵਾਲੇ ਉਦਯੋਗਾਂ ਦਾ ਮਾਲ ਢੋਣ ਦਾ ਸਮਾਂ ਤੇ ਖ਼ਰਚ ਘਟਦਾ ਹੈ।"]},
"GEO-IND-001-CP010-Q050":{"h":"fc3191f9","hi":["निर्यात-उन्मुख औद्योगिक क्षेत्रों से खास तौर पर किन उद्योगों को लाभ हो सकता है?",["केवल निर्वाह कृषि","वैश्विक आपूर्ति शृंखलाओं से जुड़ा विनिर्माण","केवल स्थानीय खनन","केवल अंतर्देशीय मत्स्यन"],"निर्यात क्षेत्रों को अंतरराष्ट्रीय उत्पादन और व्यापार में भाग लेने वाली कंपनियों की मदद के लिए बनाया जाता है।"],"pa":["ਨਿਰਯਾਤ ਲਈ ਬਣੇ ਉਦਯੋਗਿਕ ਖੇਤਰਾਂ ਦਾ ਖ਼ਾਸ ਲਾਭ ਕਿਹੜੇ ਉਦਯੋਗਾਂ ਨੂੰ ਹੋ ਸਕਦਾ ਹੈ?",["ਸਿਰਫ਼ ਗੁਜ਼ਾਰੇ ਲਈ ਖੇਤੀ","ਆਲਮੀ ਸਪਲਾਈ ਲੜੀਆਂ ਨਾਲ ਜੁੜਿਆ ਨਿਰਮਾਣ","ਸਿਰਫ਼ ਸਥਾਨਕ ਖੁਦਾਈ","ਸਿਰਫ਼ ਅੰਦਰੂਨੀ ਪਾਣੀਆਂ ਵਿੱਚ ਮੱਛੀ ਫੜਨ ਦਾ ਕੰਮ"],"ਨਿਰਯਾਤ ਖੇਤਰ ਕੌਮਾਂਤਰੀ ਉਤਪਾਦਨ ਅਤੇ ਵਪਾਰ ਵਿੱਚ ਹਿੱਸਾ ਲੈਣ ਵਾਲੀਆਂ ਕੰਪਨੀਆਂ ਦੀ ਮਦਦ ਲਈ ਬਣਾਏ ਜਾਂਦੇ ਹਨ।"]},
"GEO-IND-001-CP010-Q051":{"h":"12b67ac4","hi":["कथनों पर विचार कीजिए: I. पत्तन तक पहुँच निर्यात-उन्मुख विनिर्माण के लिए लाभदायक हो सकती है। II. माल की आवाजाही की व्यवस्था की गुणवत्ता वैश्विक आपूर्ति शृंखलाओं को प्रभावित करती है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","I और II दोनों सही हैं","न तो I और न ही II सही है"],"दोनों कारक निर्यात की प्रतिस्पर्धात्मकता पर असर डालते हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਬੰਦਰਗਾਹ ਤੱਕ ਪਹੁੰਚ ਨਿਰਯਾਤ ਲਈ ਉਤਪਾਦ ਬਣਾਉਣ ਵਾਲੇ ਉਦਯੋਗਾਂ ਨੂੰ ਲਾਭ ਦੇ ਸਕਦੀ ਹੈ। II. ਮਾਲ ਢੋਣ ਦੇ ਪ੍ਰਬੰਧ ਦੀ ਗੁਣਵੱਤਾ ਆਲਮੀ ਸਪਲਾਈ ਲੜੀਆਂ 'ਤੇ ਅਸਰ ਪਾਉਂਦੀ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਦੋਵੇਂ ਕਾਰਕ ਨਿਰਯਾਤ ਦੀ ਮੁਕਾਬਲੇਬਾਜ਼ੀ ਦੀ ਸਮਰੱਥਾ 'ਤੇ ਅਸਰ ਪਾਉਂਦੇ ਹਨ।"]},
"GEO-IND-001-CP010-Q052":{"h":"fa7c5b5b","hi":["निर्यात-उन्मुख औद्योगिक भूगोल में कौन-सा युग्म सही सुमेलित है?",["पत्तन की निकटता — खनिजों की उत्पत्ति","विशेष आर्थिक क्षेत्र (SEZ) — गन्ने की खेती","गोदाम — अयस्क की श्रेणी","पत्तन की निकटता — समुद्री ढुलाई में कम बाधाएँ"],"पत्तन पास हो तो आयातित सामग्री और निर्यातित माल की आवाजाही में समय और लागत घट सकते हैं।"],"pa":["ਨਿਰਯਾਤ ਲਈ ਉਤਪਾਦ ਬਣਾਉਣ ਵਾਲੇ ਉਦਯੋਗਾਂ ਦੇ ਭੂਗੋਲ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਬੰਦਰਗਾਹ ਦੀ ਨੇੜਤਾ — ਖਣਿਜਾਂ ਦਾ ਬਣਨਾ","ਵਿਸ਼ੇਸ਼ ਆਰਥਿਕ ਖੇਤਰ (SEZ) — ਗੰਨੇ ਦੀ ਖੇਤੀ","ਗੋਦਾਮ — ਅਯਸਕ ਦਾ ਦਰਜਾ","ਬੰਦਰਗਾਹ ਦੀ ਨੇੜਤਾ — ਸਮੁੰਦਰੀ ਮਾਲ-ਢੁਆਈ ਵਿੱਚ ਘੱਟ ਰੁਕਾਵਟਾਂ"],"ਬੰਦਰਗਾਹ ਨੇੜੇ ਹੋਣ ਨਾਲ ਬਾਹਰੋਂ ਮੰਗਵਾਈ ਸਮੱਗਰੀ ਅਤੇ ਬਾਹਰ ਭੇਜੇ ਮਾਲ ਨੂੰ ਢੋਣ ਦਾ ਸਮਾਂ ਤੇ ਖ਼ਰਚ ਘਟ ਸਕਦੇ ਹਨ।"]},
"GEO-IND-001-CP010-Q053":{"h":"0d9ccf0b","hi":["तटीय औद्योगिक क्षेत्र इलेक्ट्रॉनिक्स और मोटर वाहनों के निर्यातकों को क्यों आकर्षित कर सकते हैं?",["पत्तन उन्हें पुर्ज़ों और उत्पादों की वैश्विक आवाजाही से कुशलतापूर्वक जोड़ते हैं","वे केवल कोयला खदानों पर निर्भर हैं","उन्हें जूट के खेत चाहिए","वे परिवहन से बचते हैं"],"आधुनिक विनिर्माण अक्सर अंतरराष्ट्रीय आपूर्ति शृंखलाओं पर निर्भर होता है।"],"pa":["ਤੱਟੀ ਉਦਯੋਗਿਕ ਖੇਤਰ ਇਲੈਕਟ੍ਰਾਨਿਕਸ ਅਤੇ ਮੋਟਰ ਵਾਹਨਾਂ ਦੇ ਨਿਰਯਾਤਕਾਂ ਨੂੰ ਕਿਉਂ ਖਿੱਚ ਸਕਦੇ ਹਨ?",["ਬੰਦਰਗਾਹਾਂ ਉਨ੍ਹਾਂ ਨੂੰ ਪੁਰਜ਼ਿਆਂ ਅਤੇ ਉਤਪਾਦਾਂ ਦੀ ਆਲਮੀ ਆਵਾਜਾਈ ਨਾਲ ਸੁਚੱਜੇ ਢੰਗ ਨਾਲ ਜੋੜਦੀਆਂ ਹਨ","ਉਹ ਸਿਰਫ਼ ਕੋਲੇ ਦੀਆਂ ਖਾਣਾਂ 'ਤੇ ਨਿਰਭਰ ਹਨ","ਉਨ੍ਹਾਂ ਨੂੰ ਜੂਟ ਦੇ ਖੇਤ ਚਾਹੀਦੇ ਹਨ","ਉਹ ਆਵਾਜਾਈ ਤੋਂ ਬਚਦੇ ਹਨ"],"ਆਧੁਨਿਕ ਨਿਰਮਾਣ ਅਕਸਰ ਕੌਮਾਂਤਰੀ ਸਪਲਾਈ ਲੜੀਆਂ 'ਤੇ ਨਿਰਭਰ ਹੁੰਦਾ ਹੈ।"]},
"GEO-IND-001-CP010-Q054":{"h":"134890e5","hi":["निर्यात-उन्मुख विनिर्माण के लिए अवस्थिति का सबसे महत्वपूर्ण कारक कौन-सा है?",["केवल मिट्टी की उर्वरता","वैश्विक परिवहन संपर्क","केवल वर्षा","केवल खनिज की श्रेणी"],"पत्तनों, हवाई अड्डों और माल ढुलाई के तंत्र तक भरोसेमंद पहुँच निर्यात-उन्मुख विनिर्माण के लिए महत्वपूर्ण है।"],"pa":["ਨਿਰਯਾਤ ਲਈ ਉਤਪਾਦ ਬਣਾਉਣ ਵਾਲੇ ਉਦਯੋਗਾਂ ਲਈ ਥਾਂ ਦਾ ਸਭ ਤੋਂ ਮੁੱਖ ਕਾਰਕ ਕਿਹੜਾ ਹੈ?",["ਸਿਰਫ਼ ਮਿੱਟੀ ਦੀ ਉਪਜਾਊ ਸ਼ਕਤੀ","ਆਲਮੀ ਆਵਾਜਾਈ ਸੰਪਰਕ","ਸਿਰਫ਼ ਵਰਖਾ","ਸਿਰਫ਼ ਖਣਿਜ ਦਾ ਦਰਜਾ"],"ਬੰਦਰਗਾਹਾਂ, ਹਵਾਈ ਅੱਡਿਆਂ ਅਤੇ ਮਾਲ-ਢੁਆਈ ਦੇ ਜਾਲਾਂ ਤੱਕ ਭਰੋਸੇਯੋਗ ਪਹੁੰਚ ਨਿਰਯਾਤ ਲਈ ਨਿਰਮਾਣ ਕਰਨ ਵਾਸਤੇ ਅਹਿਮ ਹੈ।"]},
"GEO-IND-001-CP011-Q001":{"h":"88c162ed","hi":["कौन-सी औद्योगिक गतिविधि कणीय वायु प्रदूषण का प्रमुख स्रोत है?",["शीत भंडारण","हथकरघा बुनाई","दूध का शीतलन","कारखानों में कोयला और अन्य ईंधन जलाना"],"उत्सर्जन पर उचित नियंत्रण न हो तो ईंधन जलने से धुआँ, राख और सूक्ष्म कण हवा में जा सकते हैं।"],"pa":["ਕਿਹੜੀ ਉਦਯੋਗਿਕ ਸਰਗਰਮੀ ਹਵਾ ਵਿੱਚ ਕਣਾਂ ਦੇ ਪ੍ਰਦੂਸ਼ਣ ਦਾ ਮੁੱਖ ਸਰੋਤ ਹੈ?",["ਠੰਢਾ ਭੰਡਾਰਨ","ਹੱਥ-ਖੱਡੀ ਨਾਲ ਬੁਣਾਈ","ਦੁੱਧ ਠੰਢਾ ਕਰਨਾ","ਕਾਰਖ਼ਾਨਿਆਂ ਵਿੱਚ ਕੋਲਾ ਅਤੇ ਹੋਰ ਬਾਲਣ ਸਾੜਨਾ"],"ਨਿਕਾਸ 'ਤੇ ਢੁੱਕਵਾਂ ਕਾਬੂ ਨਾ ਹੋਵੇ ਤਾਂ ਬਾਲਣ ਸਾੜਨ ਨਾਲ ਧੂੰਆਂ, ਸੁਆਹ ਅਤੇ ਬਰੀਕ ਕਣ ਹਵਾ ਵਿੱਚ ਜਾ ਸਕਦੇ ਹਨ।"]},
"GEO-IND-001-CP011-Q002":{"h":"1e3b6556","hi":["कोयला जलाने वाले औद्योगिक संयंत्रों से आम तौर पर कौन-सा प्रदूषक जुड़ा है?",["कणीय पदार्थ","कच्चा जूट","दुग्ध वसा","चूना पत्थर के खंड"],"कोयला जलने से गैसीय प्रदूषकों के साथ उड़न राख और सूक्ष्म कणीय पदार्थ निकल सकते हैं।"],"pa":["ਕੋਲਾ ਸਾੜਨ ਵਾਲੇ ਉਦਯੋਗਿਕ ਪਲਾਂਟਾਂ ਨਾਲ ਆਮ ਤੌਰ 'ਤੇ ਕਿਹੜਾ ਪ੍ਰਦੂਸ਼ਕ ਜੁੜਿਆ ਹੁੰਦਾ ਹੈ?",["ਕਣੀ ਪਦਾਰਥ","ਕੱਚਾ ਜੂਟ","ਦੁੱਧ ਦੀ ਚਰਬੀ","ਚੂਨਾ ਪੱਥਰ ਦੇ ਟੁਕੜੇ"],"ਕੋਲਾ ਸਾੜਨ ਨਾਲ ਪ੍ਰਦੂਸ਼ਕ ਗੈਸਾਂ ਦੇ ਨਾਲ ਉੱਡਣ ਵਾਲੀ ਸੁਆਹ ਅਤੇ ਬਰੀਕ ਕਣ ਨਿਕਲ ਸਕਦੇ ਹਨ।"]},
"GEO-IND-001-CP011-Q003":{"h":"84d07e08","hi":["कथनों पर विचार कीजिए: I. औद्योगिक दहन वायु को प्रदूषित कर सकता है। II. उत्सर्जन नियंत्रण उपकरण निकलने वाले कणों की मात्रा घटा सकते हैं। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","I और II दोनों सही हैं","केवल II सही है","न तो I और न ही II सही है"],"स्वच्छतर ईंधन और प्रदूषण नियंत्रण उपकरणों से औद्योगिक वायु प्रदूषण घटाया जा सकता है।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਉਦਯੋਗਾਂ ਵਿੱਚ ਬਾਲਣ ਸਾੜਨ ਨਾਲ ਹਵਾ ਪ੍ਰਦੂਸ਼ਿਤ ਹੋ ਸਕਦੀ ਹੈ। II. ਨਿਕਾਸ ਨੂੰ ਕਾਬੂ ਕਰਨ ਵਾਲੇ ਉਪਕਰਨ ਨਿਕਲਣ ਵਾਲੇ ਕਣ ਘਟਾ ਸਕਦੇ ਹਨ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਵਧੇਰੇ ਸਾਫ਼ ਬਾਲਣ ਅਤੇ ਪ੍ਰਦੂਸ਼ਣ ਨੂੰ ਕਾਬੂ ਕਰਨ ਵਾਲੇ ਉਪਕਰਨਾਂ ਨਾਲ ਉਦਯੋਗਿਕ ਹਵਾ ਪ੍ਰਦੂਸ਼ਣ ਘਟਾਇਆ ਜਾ ਸਕਦਾ ਹੈ।"]},
"GEO-IND-001-CP011-Q004":{"h":"eece0958","hi":["औद्योगिक निकास से कणों का उत्सर्जन घटाने का सबसे सीधा उपाय क्या है?",["बिना उपचार वाला निकास बढ़ाना","सभी चिमनियाँ हटाना","उपयुक्त उत्सर्जन नियंत्रण उपकरण लगाना","अधिक कच्चा माल इस्तेमाल करना"],"निकास छोड़ने से पहले कणों को पकड़ने के लिए फ़िल्टर, विद्युतस्थैतिक अवक्षेपक और संबंधित उपकरण इस्तेमाल होते हैं।"],"pa":["ਉਦਯੋਗਿਕ ਨਿਕਾਸ ਵਿੱਚ ਕਣਾਂ ਦੀ ਮਾਤਰਾ ਘਟਾਉਣ ਦਾ ਸਭ ਤੋਂ ਸਿੱਧਾ ਉਪਾਅ ਕੀ ਹੈ?",["ਬਿਨਾਂ ਸੋਧਿਆ ਨਿਕਾਸ ਵਧਾਉਣਾ","ਸਾਰੀਆਂ ਚਿਮਨੀਆਂ ਹਟਾਉਣੀਆਂ","ਨਿਕਾਸ ਕਾਬੂ ਕਰਨ ਲਈ ਢੁੱਕਵੇਂ ਉਪਕਰਨ ਲਾਉਣੇ","ਵੱਧ ਕੱਚਾ ਮਾਲ ਵਰਤਣਾ"],"ਨਿਕਾਸ ਛੱਡਣ ਤੋਂ ਪਹਿਲਾਂ ਕਣ ਫੜਨ ਲਈ ਫ਼ਿਲਟਰ, ਸਥਿਰ ਬਿਜਲਈ ਚਾਰਜ ਨਾਲ ਕਣ ਵੱਖ ਕਰਨ ਵਾਲੇ ਉਪਕਰਨ ਅਤੇ ਹੋਰ ਅਜਿਹੇ ਸਾਧਨ ਵਰਤੇ ਜਾਂਦੇ ਹਨ।"]},
"GEO-IND-001-CP011-Q005":{"h":"961d053d","hi":["औद्योगिक प्रदूषण नियंत्रण में कौन-सा युग्म सही सुमेलित है?",["कणीय पदार्थ — गन्ने की सिंचाई","धुआँ — जूट को पानी में सड़ाना","उड़न राख — परिधान की सिलाई","कणीय पदार्थ — उत्सर्जन नियंत्रण उपकरण"],"निकास गैसों से कण हटाने के लिए बने उपकरणों से औद्योगिक कणीय उत्सर्जन नियंत्रित किया जाता है।"],"pa":["ਉਦਯੋਗਿਕ ਪ੍ਰਦੂਸ਼ਣ ਨੂੰ ਕਾਬੂ ਕਰਨ ਬਾਰੇ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਕਣੀ ਪਦਾਰਥ — ਗੰਨੇ ਦੀ ਸਿੰਜਾਈ","ਧੂੰਆਂ — ਜੂਟ ਨੂੰ ਪਾਣੀ ਵਿੱਚ ਗਾਲਣਾ","ਉੱਡਣ ਵਾਲੀ ਸੁਆਹ — ਪਹਿਰਾਵਿਆਂ ਦੀ ਸਿਲਾਈ","ਕਣੀ ਪਦਾਰਥ — ਨਿਕਾਸ ਨੂੰ ਕਾਬੂ ਕਰਨ ਵਾਲਾ ਉਪਕਰਨ"],"ਨਿਕਾਸ ਵਾਲੀਆਂ ਗੈਸਾਂ ਵਿੱਚੋਂ ਕਣ ਕੱਢਣ ਲਈ ਬਣੇ ਉਪਕਰਨਾਂ ਨਾਲ ਉਦਯੋਗਿਕ ਕਣਾਂ ਦੇ ਨਿਕਾਸ ਨੂੰ ਕਾਬੂ ਕੀਤਾ ਜਾਂਦਾ ਹੈ।"]},
"GEO-IND-001-CP011-Q006":{"h":"68253541","hi":["एक कारखाने में ईंधन जलाने से धुआँ और महीन राख निकलते हैं। इसका सबसे सीधा संबंध किस प्रकार के प्रदूषण से है?",["वायु प्रदूषण","केवल ध्वनि प्रदूषण","मृदा निर्माण","भूजल पुनर्भरण"],"धुआँ और महीन राख हवा में फैलने वाले प्रदूषक हैं। इसलिए उनसे मुख्यतः वायु प्रदूषण होता है।"],"pa":["ਇੱਕ ਕਾਰਖ਼ਾਨੇ ਵਿੱਚ ਬਾਲਣ ਸਾੜਨ ਨਾਲ ਧੂੰਆਂ ਅਤੇ ਬਰੀਕ ਸੁਆਹ ਨਿਕਲਦੀ ਹੈ। ਇਸ ਦਾ ਸਭ ਤੋਂ ਸਿੱਧਾ ਸਬੰਧ ਕਿਹੜੇ ਪ੍ਰਦੂਸ਼ਣ ਨਾਲ ਹੈ?",["ਹਵਾ ਪ੍ਰਦੂਸ਼ਣ","ਸਿਰਫ਼ ਸ਼ੋਰ ਪ੍ਰਦੂਸ਼ਣ","ਮਿੱਟੀ ਦਾ ਬਣਨਾ","ਧਰਤੀ ਹੇਠਲੇ ਪਾਣੀ ਦੀ ਮੁੜ ਭਰਪਾਈ"],"ਧੂੰਆਂ ਅਤੇ ਬਰੀਕ ਸੁਆਹ ਹਵਾ ਵਿੱਚ ਫੈਲਣ ਵਾਲੇ ਪ੍ਰਦੂਸ਼ਕ ਹਨ। ਇਸ ਲਈ ਇਨ੍ਹਾਂ ਨਾਲ ਮੁੱਖ ਤੌਰ 'ਤੇ ਹਵਾ ਪ੍ਰਦੂਸ਼ਿਤ ਹੁੰਦੀ ਹੈ।"]},
"GEO-IND-001-CP011-Q007":{"h":"0f5251c0","hi":["बिना उपचार वाला औद्योगिक बहिःस्राव नदियों को कैसे प्रभावित कर सकता है?",["वह रसायनों और अपशिष्ट से पानी दूषित कर सकता है","वह हमेशा पानी की गुणवत्ता सुधारता है","वह वर्षा कराता है","वह हर बार घुलित ऑक्सीजन बढ़ाता है"],"बिना उपचार वाला बहिःस्राव जल निकायों में रसायन, निलंबित ठोस और विषैले पदार्थ पहुँचा सकता है।"],"pa":["ਬਿਨਾਂ ਸੋਧਿਆ ਉਦਯੋਗਿਕ ਗੰਦਾ ਪਾਣੀ ਦਰਿਆਵਾਂ 'ਤੇ ਕੀ ਅਸਰ ਪਾ ਸਕਦਾ ਹੈ?",["ਇਹ ਰਸਾਇਣਾਂ ਅਤੇ ਰਹਿੰਦ-ਖੂੰਹਦ ਨਾਲ ਪਾਣੀ ਦੂਸ਼ਿਤ ਕਰ ਸਕਦਾ ਹੈ","ਇਹ ਹਮੇਸ਼ਾ ਪਾਣੀ ਦੀ ਗੁਣਵੱਤਾ ਸੁਧਾਰਦਾ ਹੈ","ਇਹ ਵਰਖਾ ਕਰਵਾਉਂਦਾ ਹੈ","ਇਹ ਹਰ ਹਾਲਤ ਵਿੱਚ ਘੁਲੀ ਆਕਸੀਜਨ ਵਧਾਉਂਦਾ ਹੈ"],"ਬਿਨਾਂ ਸੋਧਿਆ ਗੰਦਾ ਪਾਣੀ ਰਸਾਇਣ, ਪਾਣੀ ਵਿੱਚ ਤੈਰਦੇ ਠੋਸ ਕਣ ਅਤੇ ਜ਼ਹਿਰੀਲੇ ਪਦਾਰਥ ਜਲ ਸਰੋਤਾਂ ਤੱਕ ਪਹੁੰਚਾ ਸਕਦਾ ਹੈ।"]},
"GEO-IND-001-CP011-Q008":{"h":"c686d5af","hi":["किस औद्योगिक पद्धति से जल प्रदूषण सबसे सीधे घटता है?",["बहिःस्राव सीधे नदियों में छोड़ना","छोड़ने से पहले अपशिष्ट जल का उपचार करना","बिना उपचार वाला अपशिष्ट बढ़ाना","जल निकासी तंत्र हटाना"],"बहिःस्राव के उपचार से अपशिष्ट जल छोड़ने या दोबारा उपयोग करने से पहले प्रदूषक हटते हैं या उनकी मात्रा घटती है।"],"pa":["ਕਿਹੜੇ ਉਦਯੋਗਿਕ ਤਰੀਕੇ ਨਾਲ ਜਲ ਪ੍ਰਦੂਸ਼ਣ ਸਭ ਤੋਂ ਸਿੱਧੇ ਤੌਰ 'ਤੇ ਘਟਦਾ ਹੈ?",["ਗੰਦਾ ਪਾਣੀ ਸਿੱਧਾ ਦਰਿਆਵਾਂ ਵਿੱਚ ਛੱਡਣਾ","ਗੰਦਾ ਪਾਣੀ ਛੱਡਣ ਤੋਂ ਪਹਿਲਾਂ ਸੋਧਣਾ","ਬਿਨਾਂ ਸੋਧੀ ਰਹਿੰਦ-ਖੂੰਹਦ ਵਧਾਉਣੀ","ਪਾਣੀ ਦੇ ਨਿਕਾਸ ਦੇ ਪ੍ਰਬੰਧ ਹਟਾਉਣੇ"],"ਗੰਦਾ ਪਾਣੀ ਸੋਧਣ ਨਾਲ ਉਸ ਨੂੰ ਛੱਡਣ ਜਾਂ ਦੁਬਾਰਾ ਵਰਤਣ ਤੋਂ ਪਹਿਲਾਂ ਪ੍ਰਦੂਸ਼ਕ ਕੱਢੇ ਜਾ ਸਕਦੇ ਹਨ ਜਾਂ ਉਨ੍ਹਾਂ ਦੀ ਮਾਤਰਾ ਘਟਾਈ ਜਾ ਸਕਦੀ ਹੈ।"]},
"GEO-IND-001-CP011-Q009":{"h":"3c9206d7","hi":["कथनों पर विचार कीजिए: I. औद्योगिक बहिःस्राव सतही जल को प्रदूषित कर सकता है। II. अपशिष्ट जल का उपचार इस प्रभाव को कम कर सकता है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","I और II दोनों सही हैं","न तो I और न ही II सही है"],"दोनों कथन प्रदूषण फैलने के रास्ते और उसके बुनियादी नियंत्रण का सही वर्णन करते हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਉਦਯੋਗਾਂ ਦਾ ਗੰਦਾ ਪਾਣੀ ਧਰਤੀ ਦੀ ਸਤ੍ਹਾ 'ਤੇ ਮੌਜੂਦ ਪਾਣੀ ਨੂੰ ਪ੍ਰਦੂਸ਼ਿਤ ਕਰ ਸਕਦਾ ਹੈ। II. ਗੰਦੇ ਪਾਣੀ ਦੀ ਸੋਧ ਨਾਲ ਇਹ ਅਸਰ ਘਟ ਸਕਦਾ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਦੋਵੇਂ ਕਥਨ ਸਹੀ ਦੱਸਦੇ ਹਨ ਕਿ ਪ੍ਰਦੂਸ਼ਣ ਕਿਵੇਂ ਫੈਲਦਾ ਹੈ ਅਤੇ ਉਸ ਨੂੰ ਕਾਬੂ ਕਰਨ ਦਾ ਬੁਨਿਆਦੀ ਤਰੀਕਾ ਕੀ ਹੈ।"]},
"GEO-IND-001-CP011-Q010":{"h":"f7c0a18a","hi":["कौन-सा युग्म बहिःस्राव के उपचार को सही दर्शाता है?",["बहिःस्राव उपचार — कोयला खनन","शीतलन मीनार — जूट का रेशा","अपशिष्ट जल निकास — जल शुद्धीकरण","बहिःस्राव उपचार — प्रदूषण में कमी"],"पानी को छोड़ने या पुनर्चक्रित करने से पहले बहिःस्राव उपचार प्रणालियाँ उसमें प्रदूषकों की मात्रा घटाती हैं।"],"pa":["ਕਿਹੜਾ ਜੋੜਾ ਗੰਦੇ ਪਾਣੀ ਦੀ ਸੋਧ ਨੂੰ ਸਹੀ ਦਰਸਾਉਂਦਾ ਹੈ?",["ਗੰਦੇ ਪਾਣੀ ਦੀ ਸੋਧ — ਕੋਲੇ ਦੀ ਖੁਦਾਈ","ਠੰਢਾ ਕਰਨ ਵਾਲਾ ਟਾਵਰ — ਜੂਟ ਦਾ ਰੇਸ਼ਾ","ਗੰਦੇ ਪਾਣੀ ਦਾ ਨਿਕਾਸ — ਪਾਣੀ ਦੀ ਸ਼ੁੱਧੀ","ਗੰਦੇ ਪਾਣੀ ਦੀ ਸੋਧ — ਪ੍ਰਦੂਸ਼ਣ ਵਿੱਚ ਕਮੀ"],"ਪਾਣੀ ਛੱਡਣ ਜਾਂ ਮੁੜ ਵਰਤਣ ਤੋਂ ਪਹਿਲਾਂ ਸੋਧ ਪ੍ਰਣਾਲੀਆਂ ਉਸ ਵਿੱਚ ਪ੍ਰਦੂਸ਼ਕਾਂ ਦੀ ਮਾਤਰਾ ਘਟਾਉਂਦੀਆਂ ਹਨ।"]},
"GEO-IND-001-CP011-Q011":{"h":"ec25949c","hi":["एक रसायन संयंत्र बिना उपचार वाला तरल अपशिष्ट पास की जलधारा में छोड़ता है। सबसे तत्काल पर्यावरणीय समस्या क्या है?",["जल प्रदूषण","पवन अपरदन","केवल हिमनदों का पिघलना","मृदा निर्माण"],"जलधारा में पहुँचा तरल औद्योगिक अपशिष्ट सीधे पानी को दूषित करता है।"],"pa":["ਇੱਕ ਰਸਾਇਣਕ ਪਲਾਂਟ ਬਿਨਾਂ ਸੋਧੀ ਤਰਲ ਰਹਿੰਦ-ਖੂੰਹਦ ਨੇੜਲੀ ਜਲਧਾਰਾ ਵਿੱਚ ਛੱਡਦਾ ਹੈ। ਸਭ ਤੋਂ ਫ਼ੌਰੀ ਵਾਤਾਵਰਨੀ ਸਮੱਸਿਆ ਕੀ ਹੈ?",["ਜਲ ਪ੍ਰਦੂਸ਼ਣ","ਹਵਾ ਨਾਲ ਕਟਾਅ","ਸਿਰਫ਼ ਹਿਮਨਦੀਆਂ ਦਾ ਪਿਘਲਣਾ","ਮਿੱਟੀ ਦਾ ਬਣਨਾ"],"ਜਲਧਾਰਾ ਵਿੱਚ ਪੈਣ ਵਾਲੀ ਤਰਲ ਉਦਯੋਗਿਕ ਰਹਿੰਦ-ਖੂੰਹਦ ਪਾਣੀ ਨੂੰ ਸਿੱਧਾ ਦੂਸ਼ਿਤ ਕਰਦੀ ਹੈ।"]},
"GEO-IND-001-CP011-Q012":{"h":"35694b7e","hi":["किस पद्धति से मीठे पानी की माँग और बहिःस्राव की मात्रा, दोनों घट सकती हैं?",["पानी का एकबारगी उपयोग बढ़ाना","प्रक्रिया जल का पुनर्चक्रण और पुनः उपयोग करना","पानी बिना उपचार छोड़ना","उपचार प्रणालियाँ हटाना"],"जल के पुनर्चक्रण से मीठे पानी की माँग घटती है और कम अपशिष्ट जल छोड़ना पड़ता है।"],"pa":["ਕਿਹੜਾ ਤਰੀਕਾ ਮਿੱਠੇ ਪਾਣੀ ਦੀ ਮੰਗ ਅਤੇ ਗੰਦੇ ਪਾਣੀ ਦਾ ਨਿਕਾਸ ਦੋਵੇਂ ਘਟਾ ਸਕਦਾ ਹੈ?",["ਪਾਣੀ ਦੀ ਇੱਕ ਵਾਰ ਦੀ ਵਰਤੋਂ ਵਧਾਉਣੀ","ਪ੍ਰਕਿਰਿਆ ਦਾ ਪਾਣੀ ਸੋਧ ਕੇ ਮੁੜ ਵਰਤਣਾ","ਪਾਣੀ ਬਿਨਾਂ ਸੋਧੇ ਛੱਡਣਾ","ਸੋਧ ਪ੍ਰਣਾਲੀਆਂ ਹਟਾਉਣੀਆਂ"],"ਪਾਣੀ ਨੂੰ ਮੁੜ ਵਰਤਣ ਨਾਲ ਮਿੱਠੇ ਪਾਣੀ ਦੀ ਮੰਗ ਘਟਦੀ ਹੈ ਅਤੇ ਘੱਟ ਗੰਦਾ ਪਾਣੀ ਬਾਹਰ ਛੱਡਣਾ ਪੈਂਦਾ ਹੈ।"]},
"GEO-IND-001-CP011-Q013":{"h":"1add5bde","hi":["तापीय प्रदूषण क्या है?",["गर्म पानी छोड़ने से जल के तापमान में हानिकारक बदलाव","ध्वनि स्तर में वृद्धि","केवल प्लास्टिक अपशिष्ट का जमाव","हवा में धूल छोड़ना"],"उद्योगों और बिजलीघरों में इस्तेमाल हुआ शीतलन जल, जिन जल निकायों में छोड़ा जाता है, उन्हें गर्म कर सकता है और जलीय पारितंत्रों को प्रभावित कर सकता है।"],"pa":["ਤਾਪੀ ਪ੍ਰਦੂਸ਼ਣ ਕੀ ਹੈ?",["ਗਰਮ ਪਾਣੀ ਛੱਡਣ ਨਾਲ ਪਾਣੀ ਦੇ ਤਾਪਮਾਨ ਵਿੱਚ ਨੁਕਸਾਨਦਾਇਕ ਬਦਲਾਅ","ਆਵਾਜ਼ ਦੇ ਪੱਧਰ ਵਿੱਚ ਵਾਧਾ","ਸਿਰਫ਼ ਪਲਾਸਟਿਕ ਦੀ ਰਹਿੰਦ-ਖੂੰਹਦ ਦਾ ਇਕੱਠਾ ਹੋਣਾ","ਹਵਾ ਵਿੱਚ ਧੂੜ ਛੱਡਣੀ"],"ਉਦਯੋਗਾਂ ਅਤੇ ਬਿਜਲੀ ਘਰਾਂ ਵਿੱਚ ਠੰਢਾ ਕਰਨ ਲਈ ਵਰਤਿਆ ਪਾਣੀ ਜਿੱਥੇ ਛੱਡਿਆ ਜਾਂਦਾ ਹੈ ਉੱਥੋਂ ਦੇ ਪਾਣੀ ਨੂੰ ਗਰਮ ਕਰ ਸਕਦਾ ਹੈ ਅਤੇ ਜਲ-ਪਰਿਸਥਿਤਕੀ ਤੰਤਰਾਂ ਵਿੱਚ ਵਿਘਨ ਪਾ ਸਕਦਾ ਹੈ।"]},
"GEO-IND-001-CP011-Q014":{"h":"c08217ee","hi":["कौन-सी औद्योगिक गतिविधि तापीय प्रदूषण पैदा कर सकती है?",["परिधान की सिलाई","गर्म शीतलन जल छोड़ना","जूट की बुनाई","शीत भंडारण"],"नदियों या झीलों में गर्म शीतलन जल छोड़ने से उनके पानी का तापमान बढ़ सकता है।"],"pa":["ਕਿਹੜੀ ਉਦਯੋਗਿਕ ਸਰਗਰਮੀ ਤਾਪੀ ਪ੍ਰਦੂਸ਼ਣ ਪੈਦਾ ਕਰ ਸਕਦੀ ਹੈ?",["ਪਹਿਰਾਵਿਆਂ ਦੀ ਸਿਲਾਈ","ਠੰਢਾ ਕਰਨ ਲਈ ਵਰਤਿਆ ਗਰਮ ਪਾਣੀ ਛੱਡਣਾ","ਜੂਟ ਦੀ ਬੁਣਾਈ","ਠੰਢਾ ਭੰਡਾਰਨ"],"ਦਰਿਆਵਾਂ ਜਾਂ ਝੀਲਾਂ ਵਿੱਚ ਠੰਢਾ ਕਰਨ ਲਈ ਵਰਤਿਆ ਗਰਮ ਪਾਣੀ ਛੱਡਣ ਨਾਲ ਉਨ੍ਹਾਂ ਦੇ ਪਾਣੀ ਦਾ ਤਾਪਮਾਨ ਵਧ ਸਕਦਾ ਹੈ।"]},
"GEO-IND-001-CP011-Q015":{"h":"4087ca0b","hi":["कथनों पर विचार कीजिए: I. तापीय प्रदूषण पानी का तापमान बदलता है। II. शीतलन प्रणालियाँ सीधे छोड़े जाने वाले गर्म पानी की मात्रा घटा सकती हैं। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","I और II दोनों सही हैं","न तो I और न ही II सही है"],"शीतलन मीनारें और जल की पुनः परिसंचरण प्रणालियाँ औद्योगिक बहिःस्राव के तापीय प्रभाव को घटा सकती हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਤਾਪੀ ਪ੍ਰਦੂਸ਼ਣ ਪਾਣੀ ਦਾ ਤਾਪਮਾਨ ਬਦਲਦਾ ਹੈ। II. ਠੰਢਾ ਕਰਨ ਵਾਲੀਆਂ ਪ੍ਰਣਾਲੀਆਂ ਸਿੱਧਾ ਛੱਡੇ ਜਾਂਦੇ ਗਰਮ ਪਾਣੀ ਦੀ ਮਾਤਰਾ ਘਟਾ ਸਕਦੀਆਂ ਹਨ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਪਾਣੀ ਠੰਢਾ ਕਰਨ ਵਾਲੇ ਟਾਵਰ ਅਤੇ ਪਾਣੀ ਨੂੰ ਮੁੜ ਘੁੰਮਾਉਣ ਵਾਲੀਆਂ ਪ੍ਰਣਾਲੀਆਂ ਉਦਯੋਗਿਕ ਨਿਕਾਸ ਦਾ ਤਾਪਮਾਨ 'ਤੇ ਅਸਰ ਘਟਾ ਸਕਦੀਆਂ ਹਨ।"]},
"GEO-IND-001-CP011-Q016":{"h":"5e5f1e57","hi":["कौन-सा युग्म तापीय प्रदूषण की सही पहचान करता है?",["धुआँ — जल पुनर्भरण","शोर — मिट्टी की उर्वरता","जूट की धूल — ज्वारीय ऊर्जा","गर्म शीतलन जल — तापीय प्रदूषण"],"तापीय प्रदूषण विशेष रूप से जल निकायों के तापमान में बदलाव को कहते हैं।"],"pa":["ਕਿਹੜਾ ਜੋੜਾ ਤਾਪੀ ਪ੍ਰਦੂਸ਼ਣ ਦੀ ਸਹੀ ਪਛਾਣ ਕਰਦਾ ਹੈ?",["ਧੂੰਆਂ — ਪਾਣੀ ਦੀ ਮੁੜ ਭਰਪਾਈ","ਸ਼ੋਰ — ਮਿੱਟੀ ਦੀ ਉਪਜਾਊ ਸ਼ਕਤੀ","ਜੂਟ ਦੀ ਧੂੜ — ਜਵਾਰ-ਭਾਟੇ ਦੀ ਊਰਜਾ","ਠੰਢਾ ਕਰਨ ਲਈ ਵਰਤਿਆ ਗਰਮ ਪਾਣੀ — ਤਾਪੀ ਪ੍ਰਦੂਸ਼ਣ"],"ਤਾਪੀ ਪ੍ਰਦੂਸ਼ਣ ਖ਼ਾਸ ਤੌਰ 'ਤੇ ਜਲ ਸਰੋਤਾਂ ਦੇ ਪਾਣੀ ਦੇ ਤਾਪਮਾਨ ਵਿੱਚ ਬਦਲਾਅ ਨੂੰ ਕਹਿੰਦੇ ਹਨ।"]},
"GEO-IND-001-CP011-Q017":{"h":"39114112","hi":["एक बिजलीघर बहुत गर्म शीतलन जल नदी में छोड़ता है। यह किस प्रकार का प्रदूषण है?",["तापीय प्रदूषण","केवल ध्वनि प्रदूषण","केवल ठोस अपशिष्ट प्रदूषण","केवल प्रकाश प्रदूषण"],"मुख्य पर्यावरणीय बदलाव पानी के तापमान में कृत्रिम बढ़ोतरी है।"],"pa":["ਇੱਕ ਬਿਜਲੀ ਘਰ ਠੰਢਾ ਕਰਨ ਲਈ ਵਰਤਿਆ ਬਹੁਤ ਗਰਮ ਪਾਣੀ ਦਰਿਆ ਵਿੱਚ ਛੱਡਦਾ ਹੈ। ਇਹ ਕਿਸ ਕਿਸਮ ਦਾ ਪ੍ਰਦੂਸ਼ਣ ਹੈ?",["ਤਾਪੀ ਪ੍ਰਦੂਸ਼ਣ","ਸਿਰਫ਼ ਸ਼ੋਰ ਪ੍ਰਦੂਸ਼ਣ","ਸਿਰਫ਼ ਠੋਸ ਰਹਿੰਦ-ਖੂੰਹਦ ਦਾ ਪ੍ਰਦੂਸ਼ਣ","ਸਿਰਫ਼ ਰੌਸ਼ਨੀ ਪ੍ਰਦੂਸ਼ਣ"],"ਮੁੱਖ ਵਾਤਾਵਰਨੀ ਬਦਲਾਅ ਪਾਣੀ ਦੇ ਤਾਪਮਾਨ ਵਿੱਚ ਗ਼ੈਰ-ਕੁਦਰਤੀ ਵਾਧਾ ਹੈ।"]},
"GEO-IND-001-CP011-Q018":{"h":"0d91dd8a","hi":["कौन-सा उपाय तापीय प्रदूषण नियंत्रित करने में मदद करता है?",["अधिक गर्म पानी छोड़ना","छोड़ने से पहले पानी ठंडा करना और फिर से परिसंचरित करना","सारा जल उपचार बंद करना","छोड़े जाने वाले पानी का तापमान बढ़ाना"],"शीतलन प्रणालियाँ पानी को पर्यावरण में वापस भेजने से पहले उसका तापमान घटाती हैं।"],"pa":["ਕਿਹੜਾ ਉਪਾਅ ਤਾਪੀ ਪ੍ਰਦੂਸ਼ਣ ਨੂੰ ਕਾਬੂ ਕਰਨ ਵਿੱਚ ਮਦਦ ਕਰਦਾ ਹੈ?",["ਵੱਧ ਗਰਮ ਪਾਣੀ ਛੱਡਣਾ","ਪਾਣੀ ਨੂੰ ਛੱਡਣ ਤੋਂ ਪਹਿਲਾਂ ਠੰਢਾ ਕਰਨਾ ਅਤੇ ਪ੍ਰਣਾਲੀ ਵਿੱਚ ਦੁਬਾਰਾ ਘੁੰਮਾਉਣਾ","ਪਾਣੀ ਦੀ ਸਾਰੀ ਸੋਧ ਬੰਦ ਕਰਨੀ","ਛੱਡੇ ਜਾਂਦੇ ਪਾਣੀ ਦਾ ਤਾਪਮਾਨ ਵਧਾਉਣਾ"],"ਠੰਢਾ ਕਰਨ ਵਾਲੀਆਂ ਪ੍ਰਣਾਲੀਆਂ ਪਾਣੀ ਨੂੰ ਵਾਤਾਵਰਨ ਵਿੱਚ ਵਾਪਸ ਛੱਡਣ ਤੋਂ ਪਹਿਲਾਂ ਉਸ ਦਾ ਤਾਪਮਾਨ ਘਟਾਉਂਦੀਆਂ ਹਨ।"]},
"GEO-IND-001-CP011-Q019":{"h":"9335b69d","hi":["कारखाने का कौन-सा स्रोत आम तौर पर ध्वनि प्रदूषण में योगदान देता है?",["शीत भंडार का ऊष्मारोधन","भंडारित चूना पत्थर","पैक किए हुए परिधान","भारी मशीनरी"],"बड़ी मशीनें, संपीडक और परिवहन उपकरण तेज़ आवाज़ पैदा कर सकते हैं।"],"pa":["ਕਾਰਖ਼ਾਨੇ ਦਾ ਕਿਹੜਾ ਸਰੋਤ ਆਮ ਤੌਰ 'ਤੇ ਸ਼ੋਰ ਪ੍ਰਦੂਸ਼ਣ ਪੈਦਾ ਕਰਦਾ ਹੈ?",["ਠੰਢੇ ਗੋਦਾਮ ਦੀ ਤਾਪ-ਰੋਕ ਪਰਤ","ਭੰਡਾਰ ਕੀਤਾ ਚੂਨਾ ਪੱਥਰ","ਪੈਕ ਕੀਤੇ ਪਹਿਰਾਵੇ","ਭਾਰੀ ਮਸ਼ੀਨਰੀ"],"ਵੱਡੀਆਂ ਮਸ਼ੀਨਾਂ, ਕੰਪ੍ਰੈਸਰ ਅਤੇ ਢੋਆ-ਢੁਆਈ ਦੇ ਸਾਧਨ ਉੱਚੀ ਆਵਾਜ਼ ਪੈਦਾ ਕਰ ਸਕਦੇ ਹਨ।"]},
"GEO-IND-001-CP011-Q020":{"h":"10eaf216","hi":["किन श्रमिकों को औद्योगिक शोर का विशेष रूप से सामना करना पड़ता है?",["लगातार चलती भारी मशीनों के पास काम करने वाले","केवल शांत भंडार कक्षों में काम करने वाले","उद्योगों से दूर किसान","केवल समुद्र में मछुआरे"],"लंबे समय तक शोर करती मशीनों के पास रहने से कार्यस्थल पर शोर संबंधी जोखिम पैदा हो सकते हैं।"],"pa":["ਕਿਹੜੇ ਕਾਮਿਆਂ ਨੂੰ ਉਦਯੋਗਿਕ ਸ਼ੋਰ ਦਾ ਖ਼ਾਸ ਤੌਰ 'ਤੇ ਸਾਹਮਣਾ ਕਰਨਾ ਪੈਂਦਾ ਹੈ?",["ਲਗਾਤਾਰ ਚੱਲਦੀਆਂ ਭਾਰੀਆਂ ਮਸ਼ੀਨਾਂ ਕੋਲ ਕੰਮ ਕਰਨ ਵਾਲੇ","ਸਿਰਫ਼ ਚੁੱਪ ਭੰਡਾਰ ਕਮਰਿਆਂ ਵਿੱਚ ਕੰਮ ਕਰਨ ਵਾਲੇ","ਉਦਯੋਗਾਂ ਤੋਂ ਦੂਰ ਕਿਸਾਨ","ਸਿਰਫ਼ ਸਮੁੰਦਰ ਵਿੱਚ ਮਛੇਰੇ"],"ਸ਼ੋਰ ਕਰਦੀਆਂ ਮਸ਼ੀਨਾਂ ਕੋਲ ਲੰਮਾ ਸਮਾਂ ਰਹਿਣ ਨਾਲ ਕੰਮ ਦੀ ਥਾਂ 'ਤੇ ਸ਼ੋਰ ਨਾਲ ਜੁੜੇ ਖ਼ਤਰੇ ਪੈਦਾ ਹੋ ਸਕਦੇ ਹਨ।"]},
"GEO-IND-001-CP011-Q021":{"h":"4282f1d8","hi":["कथनों पर विचार कीजिए: I. भारी मशीनरी ध्वनि प्रदूषण पैदा कर सकती है। II. ध्वनि अवरोधक और रखरखाव शोर घटा सकते हैं। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","I और II दोनों सही हैं","केवल II सही है","न तो I और न ही II सही है"],"अभियांत्रिकी उपाय और उचित रखरखाव औद्योगिक शोर का सामना कम कर सकते हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਭਾਰੀ ਮਸ਼ੀਨਰੀ ਸ਼ੋਰ ਪ੍ਰਦੂਸ਼ਣ ਪੈਦਾ ਕਰ ਸਕਦੀ ਹੈ। II. ਆਵਾਜ਼ ਰੋਕਣ ਵਾਲੀਆਂ ਰੁਕਾਵਟਾਂ ਅਤੇ ਸਾਂਭ-ਸੰਭਾਲ ਸ਼ੋਰ ਘਟਾ ਸਕਦੀਆਂ ਹਨ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਇੰਜੀਨੀਅਰਿੰਗ ਉਪਾਅ ਅਤੇ ਢੁੱਕਵੀਂ ਸਾਂਭ-ਸੰਭਾਲ ਨਾਲ ਕਾਮਿਆਂ ਦਾ ਉਦਯੋਗਿਕ ਸ਼ੋਰ ਨਾਲ ਸਾਹਮਣਾ ਘਟ ਸਕਦਾ ਹੈ।"]},
"GEO-IND-001-CP011-Q022":{"h":"e92d1998","hi":["कौन-सा उपाय औद्योगिक शोर घटाने में सहायक है?",["ध्वनि मंदक हटाना","मशीनों का कंपन बढ़ाना","शोर करने वाली मशीनों को घेरे में रखना","खराब उपकरण चलाना"],"मशीनों को घेरे में रखने, ध्वनिरोध और रखरखाव से शोर का प्रसार घटता है।"],"pa":["ਕਿਹੜਾ ਉਪਾਅ ਉਦਯੋਗਿਕ ਸ਼ੋਰ ਘਟਾਉਣ ਵਿੱਚ ਮਦਦ ਕਰ ਸਕਦਾ ਹੈ?",["ਸਾਈਲੈਂਸਰ ਹਟਾਉਣੇ","ਮਸ਼ੀਨਾਂ ਦੀ ਕੰਬਣੀ ਵਧਾਉਣੀ","ਸ਼ੋਰ ਕਰਦੀਆਂ ਮਸ਼ੀਨਾਂ ਨੂੰ ਘੇਰੇ ਵਿੱਚ ਰੱਖਣਾ","ਖ਼ਰਾਬ ਉਪਕਰਨ ਚਲਾਉਣੇ"],"ਮਸ਼ੀਨਾਂ ਨੂੰ ਘੇਰੇ ਵਿੱਚ ਰੱਖਣ, ਆਵਾਜ਼ ਰੋਕਣ ਵਾਲੀ ਪਰਤ ਲਾਉਣ ਅਤੇ ਸਾਂਭ-ਸੰਭਾਲ ਨਾਲ ਸ਼ੋਰ ਘੱਟ ਫੈਲਦਾ ਹੈ।"]},
"GEO-IND-001-CP011-Q023":{"h":"f13e50eb","hi":["कौन-सा युग्म औद्योगिक ध्वनि प्रदूषण को सही दर्शाता है?",["भारी मशीनरी — जूट की खेती","शीतलन जल — केवल शोर","बहिःस्राव — केवल ध्वनि प्रदूषण","भारी मशीनरी — ध्वनि प्रदूषण"],"यांत्रिक उपकरण औद्योगिक शोर का सीधा स्रोत हैं।"],"pa":["ਕਿਹੜਾ ਜੋੜਾ ਉਦਯੋਗਿਕ ਸ਼ੋਰ ਪ੍ਰਦੂਸ਼ਣ ਨੂੰ ਸਹੀ ਦਰਸਾਉਂਦਾ ਹੈ?",["ਭਾਰੀ ਮਸ਼ੀਨਰੀ — ਜੂਟ ਦੀ ਖੇਤੀ","ਠੰਢਾ ਕਰਨ ਲਈ ਵਰਤਿਆ ਪਾਣੀ — ਸਿਰਫ਼ ਸ਼ੋਰ","ਗੰਦਾ ਪਾਣੀ — ਸਿਰਫ਼ ਸ਼ੋਰ ਪ੍ਰਦੂਸ਼ਣ","ਭਾਰੀ ਮਸ਼ੀਨਰੀ — ਸ਼ੋਰ ਪ੍ਰਦੂਸ਼ਣ"],"ਮਸ਼ੀਨੀ ਉਪਕਰਨ ਉਦਯੋਗਿਕ ਸ਼ੋਰ ਦਾ ਸਿੱਧਾ ਸਰੋਤ ਹਨ।"]},
"GEO-IND-001-CP011-Q024":{"h":"c1875668","hi":["एक कारखाने के संपीडकों से लगातार ऊँचे डेसीबल की आवाज़ आने की शिकायत है। यह कौन-सा प्रदूषण है?",["ध्वनि प्रदूषण","जल प्रदूषण","तापीय प्रदूषण","मृदा अपरदन"],"ऊँचे डेसीबल वाली औद्योगिक आवाज़ ध्वनि प्रदूषण का एक रूप है।"],"pa":["ਇੱਕ ਕਾਰਖ਼ਾਨੇ ਦੇ ਕੰਪ੍ਰੈਸਰਾਂ ਤੋਂ ਲਗਾਤਾਰ ਉੱਚੇ ਡੈਸੀਬਲ ਦੀ ਆਵਾਜ਼ ਆਉਣ ਦੀ ਸ਼ਿਕਾਇਤ ਹੈ। ਇਹ ਕਿਹੜਾ ਪ੍ਰਦੂਸ਼ਣ ਹੈ?",["ਸ਼ੋਰ ਪ੍ਰਦੂਸ਼ਣ","ਜਲ ਪ੍ਰਦੂਸ਼ਣ","ਤਾਪੀ ਪ੍ਰਦੂਸ਼ਣ","ਮਿੱਟੀ ਦਾ ਕਟਾਅ"],"ਉੱਚੇ ਡੈਸੀਬਲ ਵਾਲੀ ਉਦਯੋਗਿਕ ਆਵਾਜ਼ ਸ਼ੋਰ ਪ੍ਰਦੂਸ਼ਣ ਦੀ ਇੱਕ ਕਿਸਮ ਹੈ।"]},
"GEO-IND-001-CP011-Q025":{"h":"5d98367a","hi":["कौन-सी औद्योगिक पद्धति ठोस अपशिष्ट का बेहतर प्रबंधन करती है?",["छँटाई, उपयोगी सामग्री की प्राप्ति और सुरक्षित निपटान","सारा अपशिष्ट पानी में मिलाना","अपशिष्ट कहीं भी फेंकना","सारा अपशिष्ट बिना नियंत्रण जलाना"],"अपशिष्ट की छँटाई से पुनर्चक्रण योग्य सामग्री निकाली जा सकती है और खतरनाक अपशिष्ट को सुरक्षित ढंग से सँभाला जा सकता है।"],"pa":["ਕਿਹੜਾ ਉਦਯੋਗਿਕ ਤਰੀਕਾ ਠੋਸ ਰਹਿੰਦ-ਖੂੰਹਦ ਦੇ ਬਿਹਤਰ ਪ੍ਰਬੰਧ ਵਿੱਚ ਮਦਦ ਕਰਦਾ ਹੈ?",["ਛਾਂਟੀ, ਲਾਹੇਵੰਦ ਸਮੱਗਰੀ ਕੱਢਣੀ ਅਤੇ ਸੁਰੱਖਿਅਤ ਨਿਪਟਾਰਾ","ਸਾਰੀ ਰਹਿੰਦ-ਖੂੰਹਦ ਪਾਣੀ ਵਿੱਚ ਮਿਲਾਉਣੀ","ਰਹਿੰਦ-ਖੂੰਹਦ ਕਿਤੇ ਵੀ ਸੁੱਟਣੀ","ਸਾਰੀ ਰਹਿੰਦ-ਖੂੰਹਦ ਬਿਨਾਂ ਕਾਬੂ ਸਾੜਨੀ"],"ਰਹਿੰਦ-ਖੂੰਹਦ ਦੀ ਛਾਂਟੀ ਨਾਲ ਮੁੜ ਵਰਤਣਯੋਗ ਸਮੱਗਰੀ ਕੱਢੀ ਜਾ ਸਕਦੀ ਹੈ ਅਤੇ ਖ਼ਤਰਨਾਕ ਰਹਿੰਦ-ਖੂੰਹਦ ਨੂੰ ਸੁਰੱਖਿਅਤ ਢੰਗ ਨਾਲ ਸੰਭਾਲਿਆ ਜਾ ਸਕਦਾ ਹੈ।"]},
"GEO-IND-001-CP011-Q026":{"h":"31ddcf5f","hi":["कौन-सा औद्योगिक उपोत्पाद सीमेंट विनिर्माण में दोबारा इस्तेमाल हो सकता है?",["केवल कच्चा जूट","उड़न राख","केवल बिनौले","चाय की पत्तियाँ"],"ताप विद्युत संयंत्रों की उड़न राख मिश्रित सीमेंट और उससे जुड़े उत्पादों में इस्तेमाल हो सकती है।"],"pa":["ਕਿਹੜਾ ਉਦਯੋਗਿਕ ਉਪ-ਉਤਪਾਦ ਸੀਮਿੰਟ ਬਣਾਉਣ ਵਿੱਚ ਦੁਬਾਰਾ ਵਰਤਿਆ ਜਾ ਸਕਦਾ ਹੈ?",["ਸਿਰਫ਼ ਕੱਚਾ ਜੂਟ","ਉੱਡਣ ਵਾਲੀ ਸੁਆਹ","ਸਿਰਫ਼ ਵੜੇਵੇਂ","ਚਾਹ ਦੀਆਂ ਪੱਤੀਆਂ"],"ਤਾਪ ਬਿਜਲੀ ਪਲਾਂਟਾਂ ਦੀ ਉੱਡਣ ਵਾਲੀ ਸੁਆਹ ਮਿਸ਼ਰਤ ਸੀਮਿੰਟ ਅਤੇ ਇਸ ਨਾਲ ਜੁੜੇ ਉਤਪਾਦਾਂ ਵਿੱਚ ਵਰਤੀ ਜਾ ਸਕਦੀ ਹੈ।"]},
"GEO-IND-001-CP011-Q027":{"h":"04b24469","hi":["कथनों पर विचार कीजिए: I. कुछ औद्योगिक अपशिष्ट फिर से उत्पादन सामग्री के रूप में काम आ सकते हैं। II. जिनसे उपयोगी सामग्री नहीं निकाली जा सकती, उनका सुरक्षित निपटान ज़रूरी है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","I और II दोनों सही हैं","न तो I और न ही II सही है"],"उपयोगी सामग्री निकालने से अपशिष्ट कम होता है। बचे हुए अवशेष को पर्यावरण के लिए सुरक्षित ढंग से सँभालना पड़ता है।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਕੁਝ ਉਦਯੋਗਿਕ ਰਹਿੰਦ-ਖੂੰਹਦ ਮੁੜ ਉਤਪਾਦਨ ਦੀ ਸਮੱਗਰੀ ਵਜੋਂ ਵਰਤੀ ਜਾ ਸਕਦੀ ਹੈ। II. ਜਿਸ ਤੋਂ ਲਾਹੇਵੰਦ ਸਮੱਗਰੀ ਨਹੀਂ ਕੱਢੀ ਜਾ ਸਕਦੀ, ਉਸ ਦਾ ਸੁਰੱਖਿਅਤ ਨਿਪਟਾਰਾ ਜ਼ਰੂਰੀ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਲਾਹੇਵੰਦ ਸਮੱਗਰੀ ਕੱਢਣ ਨਾਲ ਰਹਿੰਦ-ਖੂੰਹਦ ਘਟਦੀ ਹੈ। ਜੋ ਬਚਦਾ ਹੈ ਉਸ ਨੂੰ ਵਾਤਾਵਰਨ ਲਈ ਸੁਰੱਖਿਅਤ ਢੰਗ ਨਾਲ ਸੰਭਾਲਣਾ ਪੈਂਦਾ ਹੈ।"]},
"GEO-IND-001-CP011-Q028":{"h":"13d30be6","hi":["औद्योगिक अपशिष्ट से उपयोगी सामग्री प्राप्त करने के संबंध में कौन-सा युग्म सही सुमेलित है?",["उड़न राख — जूट का रेशा","इस्पात का धातुमल — चीनी","गन्ने की खोई — ऐलुमिनियम का अयस्क","उड़न राख — मिश्रित सीमेंट"],"सीमेंट विनिर्माण में उड़न राख एक प्रचलित पूरक सामग्री है।"],"pa":["ਉਦਯੋਗਿਕ ਰਹਿੰਦ-ਖੂੰਹਦ ਤੋਂ ਲਾਹੇਵੰਦ ਸਮੱਗਰੀ ਕੱਢਣ ਬਾਰੇ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਉੱਡਣ ਵਾਲੀ ਸੁਆਹ — ਜੂਟ ਦਾ ਰੇਸ਼ਾ","ਸਟੀਲ ਦੀ ਸਲੈਗ — ਖੰਡ","ਗੰਨੇ ਦੀ ਖੋਈ — ਐਲੂਮੀਨੀਅਮ ਦਾ ਅਯਸਕ","ਉੱਡਣ ਵਾਲੀ ਸੁਆਹ — ਮਿਸ਼ਰਤ ਸੀਮਿੰਟ"],"ਉੱਡਣ ਵਾਲੀ ਸੁਆਹ ਸੀਮਿੰਟ ਬਣਾਉਣ ਲਈ ਜਾਣੀ-ਪਛਾਣੀ ਪੂਰਕ ਸਮੱਗਰੀ ਹੈ।"]},
"GEO-IND-001-CP011-Q029":{"h":"09ff0607","hi":["औद्योगिक अपशिष्ट की छँटाई क्यों उपयोगी है?",["इससे पुनर्चक्रण योग्य, खतरनाक और सामान्य अपशिष्ट अलग होते हैं","इससे अपशिष्ट अधिक मिल जाता है","इससे पुनर्चक्रण रुकता है","इससे सभी उपचारों की ज़रूरत खत्म होती है"],"छँटाई से उपयोगी सामग्री निकालना आसान होता है और खतरनाक पदार्थों को उचित ढंग से सँभाला जा सकता है।"],"pa":["ਉਦਯੋਗਿਕ ਰਹਿੰਦ-ਖੂੰਹਦ ਦੀ ਛਾਂਟੀ ਕਿਉਂ ਲਾਹੇਵੰਦ ਹੈ?",["ਇਸ ਨਾਲ ਮੁੜ ਵਰਤਣਯੋਗ, ਖ਼ਤਰਨਾਕ ਅਤੇ ਆਮ ਰਹਿੰਦ-ਖੂੰਹਦ ਵੱਖ ਹੁੰਦੀ ਹੈ","ਇਸ ਨਾਲ ਰਹਿੰਦ-ਖੂੰਹਦ ਵੱਧ ਰਲ ਜਾਂਦੀ ਹੈ","ਇਹ ਮੁੜ ਵਰਤੋਂ ਰੋਕਦੀ ਹੈ","ਇਹ ਸੋਧ ਦੀ ਸਾਰੀ ਲੋੜ ਖ਼ਤਮ ਕਰਦੀ ਹੈ"],"ਛਾਂਟੀ ਨਾਲ ਲਾਹੇਵੰਦ ਸਮੱਗਰੀ ਕੱਢਣੀ ਸੌਖੀ ਹੁੰਦੀ ਹੈ ਅਤੇ ਖ਼ਤਰਨਾਕ ਪਦਾਰਥ ਢੁੱਕਵੇਂ ਢੰਗ ਨਾਲ ਸੰਭਾਲੇ ਜਾ ਸਕਦੇ ਹਨ।"]},
"GEO-IND-001-CP011-Q030":{"h":"6fdd1b5c","hi":["एक संयंत्र दोबारा इस्तेमाल हो सकने वाला उपोत्पाद फेंकने के बजाय दूसरे उद्योग को भेजता है। यह किस सिद्धांत का उदाहरण है?",["अपशिष्ट को अधिकतम करना","औद्योगिक अपशिष्ट से उपयोगी संसाधन प्राप्त करना","औद्योगिक अलगाव","कच्चे माल का क्षय"],"एक उद्योग के उपोत्पाद को दूसरे की उत्पादन सामग्री बनाने से अपशिष्ट और संसाधनों की माँग घटती है।"],"pa":["ਇੱਕ ਪਲਾਂਟ ਮੁੜ ਵਰਤਣਯੋਗ ਉਪ-ਉਤਪਾਦ ਨੂੰ ਸੁੱਟਣ ਦੀ ਥਾਂ ਕਿਸੇ ਹੋਰ ਉਦਯੋਗ ਨੂੰ ਭੇਜਦਾ ਹੈ। ਇਹ ਕਿਸ ਅਸੂਲ ਦੀ ਉਦਾਹਰਨ ਹੈ?",["ਰਹਿੰਦ-ਖੂੰਹਦ ਵੱਧ ਤੋਂ ਵੱਧ ਕਰਨੀ","ਉਦਯੋਗਿਕ ਰਹਿੰਦ-ਖੂੰਹਦ ਤੋਂ ਲਾਹੇਵੰਦ ਸਰੋਤ ਹਾਸਲ ਕਰਨੇ","ਉਦਯੋਗਿਕ ਅਲੱਗ-ਥਲੱਗਤਾ","ਕੱਚੇ ਮਾਲ ਦੀ ਘਾਟ"],"ਇੱਕ ਉਦਯੋਗ ਦੇ ਉਪ-ਉਤਪਾਦ ਨੂੰ ਦੂਜੇ ਦੀ ਸਮੱਗਰੀ ਵਜੋਂ ਵਰਤਣ ਨਾਲ ਰਹਿੰਦ-ਖੂੰਹਦ ਅਤੇ ਸਰੋਤਾਂ ਦੀ ਮੰਗ ਘਟਦੀ ਹੈ।"]},
"GEO-IND-001-CP011-Q031":{"h":"c8aeff05","hi":["स्वच्छतर उत्पादन का मुख्य उद्देश्य क्या है?",["बिना उपचार वाला निकास बढ़ाना","स्रोत पर ही अपशिष्ट और प्रदूषण घटाना","उतना ही उत्पादन करने के लिए अधिक कच्चा माल इस्तेमाल करना","प्रदूषण को जल से वायु में पहुँचा देना"],"स्वच्छतर उत्पादन का ज़ोर अपशिष्ट बनने से रोकने पर है, ताकि केवल बनने के बाद उसके उपचार पर निर्भर न रहना पड़े।"],"pa":["ਵਧੇਰੇ ਸਾਫ਼ ਉਤਪਾਦਨ ਦਾ ਮੁੱਖ ਉਦੇਸ਼ ਕੀ ਹੈ?",["ਬਿਨਾਂ ਸੋਧਿਆ ਨਿਕਾਸ ਵਧਾਉਣਾ","ਸਰੋਤ 'ਤੇ ਹੀ ਰਹਿੰਦ-ਖੂੰਹਦ ਅਤੇ ਪ੍ਰਦੂਸ਼ਣ ਘਟਾਉਣਾ","ਉਸੇ ਉਤਪਾਦਨ ਲਈ ਵੱਧ ਕੱਚਾ ਮਾਲ ਵਰਤਣਾ","ਪ੍ਰਦੂਸ਼ਣ ਪਾਣੀ ਤੋਂ ਹਵਾ ਵਿੱਚ ਭੇਜ ਦੇਣਾ"],"ਵਧੇਰੇ ਸਾਫ਼ ਉਤਪਾਦਨ ਵਿੱਚ ਜ਼ੋਰ ਰਹਿੰਦ-ਖੂੰਹਦ ਬਣਨ ਤੋਂ ਰੋਕਣ 'ਤੇ ਹੈ, ਤਾਂ ਜੋ ਸਿਰਫ਼ ਬਣਨ ਤੋਂ ਬਾਅਦ ਉਸ ਦੀ ਸੋਧ 'ਤੇ ਨਿਰਭਰ ਨਾ ਰਹਿਣਾ ਪਵੇ।"]},
"GEO-IND-001-CP011-Q032":{"h":"34f75c74","hi":["कौन-सी पद्धति औद्योगिक संसाधन दक्षता बढ़ाती है?",["टाली जा सकने वाली हानियाँ बढ़ाना","पुनर्चक्रण न करना","प्रति इकाई उत्पादन कम सामग्री और ऊर्जा इस्तेमाल करना","बिना ज़रूरत अधिक ईंधन इस्तेमाल करना"],"संसाधन दक्षता का अर्थ कम सामग्री और ऊर्जा से अधिक मूल्य का उत्पादन करना है।"],"pa":["ਕਿਹੜਾ ਤਰੀਕਾ ਉਦਯੋਗਿਕ ਸਰੋਤਾਂ ਦੀ ਸੁਚੱਜੀ ਵਰਤੋਂ ਵਧਾਉਂਦਾ ਹੈ?",["ਟਾਲੇ ਜਾ ਸਕਣ ਵਾਲੇ ਨੁਕਸਾਨ ਵਧਾਉਣੇ","ਮੁੜ ਵਰਤੋਂ ਰੱਦ ਕਰਨੀ","ਉਤਪਾਦਨ ਦੀ ਹਰ ਇਕਾਈ ਲਈ ਘੱਟ ਸਮੱਗਰੀ ਅਤੇ ਊਰਜਾ ਵਰਤਣੀ","ਬਿਨਾਂ ਲੋੜ ਵੱਧ ਬਾਲਣ ਵਰਤਣਾ"],"ਸਰੋਤਾਂ ਦੀ ਸੁਚੱਜੀ ਵਰਤੋਂ ਦਾ ਭਾਵ ਘੱਟ ਸਮੱਗਰੀ ਅਤੇ ਊਰਜਾ ਨਾਲ ਵੱਧ ਮੁੱਲ ਪੈਦਾ ਕਰਨਾ ਹੈ।"]},
"GEO-IND-001-CP011-Q033":{"h":"230fe2fc","hi":["कथनों पर विचार कीजिए: I. स्वच्छतर उत्पादन का लक्ष्य प्रदूषण रोकना है। II. संसाधन दक्षता से उत्पादन सामग्री की अनावश्यक खपत घटती है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","न तो I और न ही II सही है","I और II दोनों सही हैं"],"दोनों उपाय उत्पादन की दक्षता बढ़ाते हुए पर्यावरण पर दबाव घटाते हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਵਧੇਰੇ ਸਾਫ਼ ਉਤਪਾਦਨ ਦਾ ਉਦੇਸ਼ ਪ੍ਰਦੂਸ਼ਣ ਰੋਕਣਾ ਹੈ। II. ਸਰੋਤਾਂ ਦੀ ਸੁਚੱਜੀ ਵਰਤੋਂ ਨਾਲ ਸਮੱਗਰੀ ਦੀ ਬੇਲੋੜੀ ਖਪਤ ਘਟਦੀ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ"],"ਦੋਵੇਂ ਤਰੀਕੇ ਉਤਪਾਦਨ ਦੀ ਕਾਰਗੁਜ਼ਾਰੀ ਸੁਧਾਰਦੇ ਹੋਏ ਵਾਤਾਵਰਨ 'ਤੇ ਦਬਾਅ ਘਟਾਉਂਦੇ ਹਨ।"]},
"GEO-IND-001-CP011-Q034":{"h":"955b5375","hi":["सतत विनिर्माण में कौन-सा युग्म सही सुमेलित है?",["संसाधन दक्षता — सामग्री और ऊर्जा की कम बर्बादी","संसाधन दक्षता — अधिक अपशिष्ट","स्वच्छतर उत्पादन — बिना उपचार वाला निकास","पुनर्चक्रण — केवल अधिक खनन"],"दक्ष उत्पादन से अपशिष्ट और नए संसाधनों की माँग घटती है।"],"pa":["ਟਿਕਾਊ ਨਿਰਮਾਣ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਸਰੋਤਾਂ ਦੀ ਸੁਚੱਜੀ ਵਰਤੋਂ — ਸਮੱਗਰੀ ਤੇ ਊਰਜਾ ਦੀ ਘੱਟ ਬਰਬਾਦੀ","ਸਰੋਤਾਂ ਦੀ ਸੁਚੱਜੀ ਵਰਤੋਂ — ਵੱਧ ਰਹਿੰਦ-ਖੂੰਹਦ","ਵਧੇਰੇ ਸਾਫ਼ ਉਤਪਾਦਨ — ਬਿਨਾਂ ਸੋਧਿਆ ਨਿਕਾਸ","ਮੁੜ ਵਰਤੋਂ — ਸਿਰਫ਼ ਵੱਧ ਖੁਦਾਈ"],"ਸੁਚੱਜੇ ਉਤਪਾਦਨ ਨਾਲ ਰਹਿੰਦ-ਖੂੰਹਦ ਅਤੇ ਨਵੇਂ ਸਰੋਤਾਂ ਦੀ ਮੰਗ ਘਟਦੀ ਹੈ।"]},
"GEO-IND-001-CP011-Q035":{"h":"14c6aa7c","hi":["कारखाने में कौन-सा बदलाव स्वच्छतर उत्पादन का सबसे अच्छा उदाहरण है?",["अधिक अपशिष्ट जल छोड़ना","कम पानी और कम अपशिष्ट के लिए प्रक्रिया में बदलाव करना","उतने ही उत्पादन के लिए अधिक ईंधन लगाना","रिसाव की अनदेखी करना"],"प्रक्रिया को इस तरह बदलना कि अपशिष्ट न बने, स्वच्छतर उत्पादन की एक प्रमुख पद्धति है।"],"pa":["ਕਾਰਖ਼ਾਨੇ ਵਿੱਚ ਕਿਹੜਾ ਬਦਲਾਅ ਵਧੇਰੇ ਸਾਫ਼ ਉਤਪਾਦਨ ਦੀ ਸਭ ਤੋਂ ਚੰਗੀ ਉਦਾਹਰਨ ਹੈ?",["ਵੱਧ ਗੰਦਾ ਪਾਣੀ ਛੱਡਣਾ","ਘੱਟ ਪਾਣੀ ਵਰਤਣ ਅਤੇ ਘੱਟ ਰਹਿੰਦ-ਖੂੰਹਦ ਬਣਾਉਣ ਲਈ ਪ੍ਰਕਿਰਿਆ ਬਦਲਣੀ","ਉਸੇ ਉਤਪਾਦਨ ਲਈ ਵੱਧ ਬਾਲਣ ਵਰਤਣਾ","ਰਿਸਾਅ ਨੂੰ ਅਣਗੌਲਿਆ ਕਰਨਾ"],"ਪ੍ਰਕਿਰਿਆ ਨੂੰ ਇਸ ਤਰ੍ਹਾਂ ਬਦਲਣਾ ਕਿ ਰਹਿੰਦ-ਖੂੰਹਦ ਨਾ ਬਣੇ, ਵਧੇਰੇ ਸਾਫ਼ ਉਤਪਾਦਨ ਦਾ ਮੁੱਖ ਤਰੀਕਾ ਹੈ।"]},
"GEO-IND-001-CP011-Q036":{"h":"96a25003","hi":["संसाधन दक्षता औद्योगिक लागत क्यों घटा सकती है?",["यह निपटान के लिए अपशिष्ट बढ़ाती है","यह बाज़ारों को खत्म करती है","यह सामग्री और ऊर्जा की अनावश्यक खपत घटाती है","यह जानबूझकर माल-भाड़ा बढ़ाती है"],"कम सामग्री इस्तेमाल करने और कम अपशिष्ट बनाने से खरीद और निपटान, दोनों का ख़र्च घट सकता है।"],"pa":["ਸਰੋਤਾਂ ਦੀ ਸੁਚੱਜੀ ਵਰਤੋਂ ਨਾਲ ਉਦਯੋਗਿਕ ਖ਼ਰਚ ਕਿਉਂ ਘਟ ਸਕਦੇ ਹਨ?",["ਇਹ ਨਿਪਟਾਰੇ ਲਈ ਰਹਿੰਦ-ਖੂੰਹਦ ਵਧਾਉਂਦੀ ਹੈ","ਇਹ ਬਾਜ਼ਾਰ ਖ਼ਤਮ ਕਰਦੀ ਹੈ","ਇਹ ਸਮੱਗਰੀ ਅਤੇ ਊਰਜਾ ਦੀ ਬੇਲੋੜੀ ਖਪਤ ਘਟਾਉਂਦੀ ਹੈ","ਇਹ ਜਾਣ-ਬੁੱਝ ਕੇ ਮਾਲ-ਭਾੜਾ ਵਧਾਉਂਦੀ ਹੈ"],"ਘੱਟ ਸਮੱਗਰੀ ਵਰਤਣ ਅਤੇ ਘੱਟ ਰਹਿੰਦ-ਖੂੰਹਦ ਬਣਨ ਨਾਲ ਖ਼ਰੀਦ ਅਤੇ ਨਿਪਟਾਰੇ, ਦੋਵਾਂ ਦਾ ਖ਼ਰਚ ਘਟ ਸਕਦਾ ਹੈ।"]},
"GEO-IND-001-CP011-Q037":{"h":"78e8e0c8","hi":["औद्योगिक जल पुनर्चक्रण क्या है?",["सारा पानी बिना उपचार छोड़ना","बोतलबंद पानी आयात करना","इस्तेमाल हुए प्रक्रिया जल का उपचार करके उसे फिर उपयोग योग्य बनाना","केवल नदी का पानी गर्म करना"],"जल पुनर्चक्रण में प्रक्रिया जल का उपचार किया जाता है ताकि उसी औद्योगिक तंत्र में या उसके बाहर पानी फिर इस्तेमाल हो सके।"],"pa":["ਉਦਯੋਗਾਂ ਵਿੱਚ ਪਾਣੀ ਨੂੰ ਮੁੜ ਵਰਤਣ ਲਈ ਸੋਧਣ ਦਾ ਕੀ ਮਤਲਬ ਹੈ?",["ਸਾਰਾ ਪਾਣੀ ਬਿਨਾਂ ਸੋਧੇ ਛੱਡਣਾ","ਬੋਤਲਬੰਦ ਪਾਣੀ ਆਯਾਤ ਕਰਨਾ","ਪ੍ਰਕਿਰਿਆ ਵਿੱਚ ਵਰਤਿਆ ਪਾਣੀ ਸੋਧ ਕੇ ਦੁਬਾਰਾ ਵਰਤਣਯੋਗ ਬਣਾਉਣਾ","ਸਿਰਫ਼ ਦਰਿਆ ਦਾ ਪਾਣੀ ਗਰਮ ਕਰਨਾ"],"ਪਾਣੀ ਨੂੰ ਸੋਧਿਆ ਜਾਂਦਾ ਹੈ ਤਾਂ ਜੋ ਉਹ ਉਸੇ ਉਦਯੋਗਿਕ ਪ੍ਰਣਾਲੀ ਦੇ ਅੰਦਰ ਜਾਂ ਬਾਹਰ ਦੁਬਾਰਾ ਵਰਤਿਆ ਜਾ ਸਕੇ।"]},
"GEO-IND-001-CP011-Q038":{"h":"2c939617","hi":["जल की कमी वाले औद्योगिक क्षेत्रों में जल पुनर्चक्रण क्यों महत्वपूर्ण है?",["यह पानी की हानि बढ़ाता है","यह उपचार रोकता है","यह खनिज बनाता है","यह मीठे पानी की माँग घटाता है"],"उपचारित जल का दोबारा इस्तेमाल करने से मीठे पानी की सीमित आपूर्ति पर दबाव कम होता है।"],"pa":["ਪਾਣੀ ਦੀ ਘਾਟ ਵਾਲੇ ਉਦਯੋਗਿਕ ਖੇਤਰਾਂ ਵਿੱਚ ਪਾਣੀ ਦੀ ਮੁੜ ਵਰਤੋਂ ਕਿਉਂ ਲਾਹੇਵੰਦ ਹੈ?",["ਇਹ ਪਾਣੀ ਦੀ ਹਾਨੀ ਵਧਾਉਂਦੀ ਹੈ","ਇਹ ਸੋਧ ਰੋਕਦੀ ਹੈ","ਇਹ ਖਣਿਜ ਬਣਾਉਂਦੀ ਹੈ","ਇਹ ਮਿੱਠੇ ਪਾਣੀ ਦੀ ਮੰਗ ਘਟਾਉਂਦੀ ਹੈ"],"ਸੋਧਿਆ ਪਾਣੀ ਮੁੜ ਵਰਤਣ ਨਾਲ ਮਿੱਠੇ ਪਾਣੀ ਦੀ ਸੀਮਤ ਸਪਲਾਈ 'ਤੇ ਦਬਾਅ ਘਟਦਾ ਹੈ।"]},
"GEO-IND-001-CP011-Q039":{"h":"6785cd38","hi":["कथनों पर विचार कीजिए: I. जल पुनर्चक्रण मीठे पानी की माँग कम कर सकता है। II. इससे छोड़े जाने वाले अपशिष्ट जल की मात्रा भी कम हो सकती है। कौन-सा/से कथन सही है/हैं?",["I और II दोनों सही हैं","केवल I सही है","केवल II सही है","न तो I और न ही II सही है"],"पुनर्चक्रण से लिया और छोड़ा जाने वाला पानी, दोनों कम होते हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਪਾਣੀ ਸੋਧ ਕੇ ਮੁੜ ਵਰਤਣ ਨਾਲ ਮਿੱਠੇ ਪਾਣੀ ਦੀ ਮੰਗ ਘਟ ਸਕਦੀ ਹੈ। II. ਇਸ ਨਾਲ ਗੰਦੇ ਪਾਣੀ ਦਾ ਨਿਕਾਸ ਵੀ ਘਟ ਸਕਦਾ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਮੁੜ ਵਰਤੋਂ ਨਾਲ ਲਿਆ ਅਤੇ ਛੱਡਿਆ ਜਾਣ ਵਾਲਾ ਪਾਣੀ, ਦੋਵੇਂ ਘਟਦੇ ਹਨ।"]},
"GEO-IND-001-CP011-Q040":{"h":"22bab816","hi":["कौन-सा युग्म औद्योगिक जल के पुनः उपयोग को सही दर्शाता है?",["बिना उपचार वाला बहिःस्राव — पीने का पानी","उपचारित प्रक्रिया जल — पुनः उपयोग","शीतलन जल — जूट का रेशा","अपशिष्ट जल — खनिज अयस्क"],"उपचारित जल अक्सर शीतलन, सफ़ाई या उत्पादन प्रक्रिया की ज़रूरतों के लिए दोबारा इस्तेमाल किया जा सकता है।"],"pa":["ਕਿਹੜਾ ਜੋੜਾ ਉਦਯੋਗਿਕ ਪਾਣੀ ਦੀ ਮੁੜ ਵਰਤੋਂ ਨੂੰ ਸਹੀ ਦਰਸਾਉਂਦਾ ਹੈ?",["ਬਿਨਾਂ ਸੋਧਿਆ ਗੰਦਾ ਪਾਣੀ — ਪੀਣ ਦਾ ਪਾਣੀ","ਸੋਧਿਆ ਪ੍ਰਕਿਰਿਆ ਜਲ — ਮੁੜ ਵਰਤੋਂ","ਠੰਢਾ ਕਰਨ ਲਈ ਪਾਣੀ — ਜੂਟ ਦਾ ਰੇਸ਼ਾ","ਗੰਦਾ ਪਾਣੀ — ਖਣਿਜ ਅਯਸਕ"],"ਸੋਧਿਆ ਪਾਣੀ ਅਕਸਰ ਠੰਢਾ ਕਰਨ, ਸਫ਼ਾਈ ਜਾਂ ਉਤਪਾਦਨ ਦੀਆਂ ਲੋੜਾਂ ਲਈ ਮੁੜ ਵਰਤਿਆ ਜਾ ਸਕਦਾ ਹੈ।"]},
"GEO-IND-001-CP011-Q041":{"h":"4f021f3b","hi":["एक संयंत्र अपने अपशिष्ट जल का उपचार करके उसे शीतलन में फिर इस्तेमाल करता है। यह कौन-सी पद्धति है?",["खुले में अपशिष्ट फेंकना","कच्चे माल का खनन","जल पुनर्चक्रण","गर्म जल छोड़ना"],"उसी पानी को बाहर छोड़ने के बजाय उसका उपचार करके फिर इस्तेमाल किया जाता है।"],"pa":["ਇੱਕ ਪਲਾਂਟ ਆਪਣਾ ਗੰਦਾ ਪਾਣੀ ਸੋਧ ਕੇ ਮੁੜ ਠੰਢਾ ਕਰਨ ਦੇ ਕੰਮ ਲਾਉਂਦਾ ਹੈ। ਇਹ ਕਿਹੜਾ ਤਰੀਕਾ ਹੈ?",["ਖੁੱਲ੍ਹੇ ਵਿੱਚ ਰਹਿੰਦ-ਖੂੰਹਦ ਸੁੱਟਣੀ","ਕੱਚੇ ਮਾਲ ਦੀ ਖੁਦਾਈ","ਪਾਣੀ ਸੋਧ ਕੇ ਮੁੜ ਵਰਤਣਾ","ਗਰਮ ਪਾਣੀ ਛੱਡਣਾ"],"ਉਸੇ ਪਾਣੀ ਨੂੰ ਬਾਹਰ ਛੱਡਣ ਦੀ ਥਾਂ ਸੋਧ ਕੇ ਦੁਬਾਰਾ ਵਰਤਿਆ ਜਾਂਦਾ ਹੈ।"]},
"GEO-IND-001-CP011-Q042":{"h":"641124ab","hi":["जल पुनर्चक्रण से कौन-सा औद्योगिक उद्देश्य पूरा करने में मदद मिलती है?",["बिना उपचार वाला अधिक निकास","पानी की अधिक बर्बादी","मीठे पानी का अधिक दोहन","संसाधनों का कम उपयोग और कम बहिःस्राव"],"पुनर्चक्रण से संसाधन दक्षता बढ़ती है और प्रदूषण का दबाव कम होता है।"],"pa":["ਪਾਣੀ ਸੋਧ ਕੇ ਮੁੜ ਵਰਤਣ ਨਾਲ ਕਿਹੜਾ ਉਦਯੋਗਿਕ ਉਦੇਸ਼ ਪੂਰਾ ਕਰਨ ਵਿੱਚ ਮਦਦ ਮਿਲਦੀ ਹੈ?",["ਵੱਧ ਬਿਨਾਂ ਸੋਧਿਆ ਨਿਕਾਸ","ਪਾਣੀ ਦੀ ਵੱਧ ਬਰਬਾਦੀ","ਵੱਧ ਮਿੱਠਾ ਪਾਣੀ ਕੱਢਣਾ","ਸਰੋਤਾਂ ਦੀ ਘੱਟ ਵਰਤੋਂ ਅਤੇ ਘੱਟ ਗੰਦਾ ਪਾਣੀ"],"ਮੁੜ ਵਰਤੋਂ ਨਾਲ ਸਰੋਤਾਂ ਦੀ ਵਰਤੋਂ ਵਧੇਰੇ ਸੁਚੱਜੀ ਹੁੰਦੀ ਹੈ ਅਤੇ ਪ੍ਰਦੂਸ਼ਣ ਦਾ ਦਬਾਅ ਘਟਦਾ ਹੈ।"]},
"GEO-IND-001-CP011-Q043":{"h":"cd8223b0","hi":["औद्योगिक सहजीविता क्या है?",["एक उद्योग का उपोत्पाद दूसरे उद्योग की उत्पादन सामग्री बनता है","उद्योग बिना किसी आदान-प्रदान के चलते हैं","सारा अपशिष्ट फेंक दिया जाता है","कारखाने कोई आधारभूत संरचना साझा नहीं करते"],"औद्योगिक सहजीविता कंपनियों के बीच सामग्री के उपयोगी आदान-प्रदान से अपशिष्ट घटाती है।"],"pa":["ਉਦਯੋਗਿਕ ਸਹਿਜੀਵਤਾ ਕੀ ਹੈ?",["ਇੱਕ ਉਦਯੋਗ ਦਾ ਉਪ-ਉਤਪਾਦ ਦੂਜੇ ਉਦਯੋਗ ਦੀ ਸਮੱਗਰੀ ਵਜੋਂ ਵਰਤਿਆ ਜਾਂਦਾ ਹੈ","ਉਦਯੋਗ ਬਿਨਾਂ ਕਿਸੇ ਆਦਾਨ-ਪ੍ਰਦਾਨ ਦੇ ਚੱਲਦੇ ਹਨ","ਸਾਰੀ ਰਹਿੰਦ-ਖੂੰਹਦ ਸੁੱਟ ਦਿੱਤੀ ਜਾਂਦੀ ਹੈ","ਕਾਰਖ਼ਾਨੇ ਕੋਈ ਬੁਨਿਆਦੀ ਢਾਂਚਾ ਸਾਂਝਾ ਨਹੀਂ ਕਰਦੇ"],"ਉਦਯੋਗਿਕ ਸਹਿਜੀਵਤਾ ਨਾਲ ਕੰਪਨੀਆਂ ਵਿਚਕਾਰ ਸਮੱਗਰੀ ਦਾ ਲਾਹੇਵੰਦ ਆਦਾਨ-ਪ੍ਰਦਾਨ ਹੁੰਦਾ ਹੈ ਅਤੇ ਰਹਿੰਦ-ਖੂੰਹਦ ਘਟਦੀ ਹੈ।"]},
"GEO-IND-001-CP011-Q044":{"h":"e8c71287","hi":["कौन-सा उदाहरण औद्योगिक सहजीविता को दर्शाता है?",["बिना उपचार वाला बहिःस्राव नदी में छोड़ना","बिजलीघर की उड़न राख सीमेंट में इस्तेमाल करना","कोयले की राख खेत में फेंकना","शोर दूसरे कारखाने में भेजना"],"उपोत्पाद अपशिष्ट बनने के बजाय उपयोगी उत्पादन सामग्री बन जाता है।"],"pa":["ਕਿਹੜੀ ਉਦਾਹਰਨ ਉਦਯੋਗਿਕ ਸਹਿਜੀਵਤਾ ਦਰਸਾਉਂਦੀ ਹੈ?",["ਬਿਨਾਂ ਸੋਧਿਆ ਗੰਦਾ ਪਾਣੀ ਦਰਿਆ ਵਿੱਚ ਛੱਡਣਾ","ਬਿਜਲੀ ਘਰ ਦੀ ਉੱਡਣ ਵਾਲੀ ਸੁਆਹ ਸੀਮਿੰਟ ਵਿੱਚ ਵਰਤਣੀ","ਕੋਲੇ ਦੀ ਸੁਆਹ ਖੇਤ ਵਿੱਚ ਸੁੱਟਣੀ","ਸ਼ੋਰ ਦੂਜੇ ਕਾਰਖ਼ਾਨੇ ਵਿੱਚ ਭੇਜਣਾ"],"ਉਪ-ਉਤਪਾਦ ਰਹਿੰਦ-ਖੂੰਹਦ ਬਣਨ ਦੀ ਥਾਂ ਉਤਪਾਦਨ ਲਈ ਲਾਹੇਵੰਦ ਸਮੱਗਰੀ ਬਣ ਜਾਂਦਾ ਹੈ।"]},
"GEO-IND-001-CP011-Q045":{"h":"69aa727f","hi":["कथनों पर विचार कीजिए: I. औद्योगिक सहजीविता अपशिष्ट घटा सकती है। II. यह पहली बार निकाले गए कच्चे माल की माँग भी घटा सकती है। कौन-सा/से कथन सही है/हैं?",["केवल I सही है","केवल II सही है","I और II दोनों सही हैं","न तो I और न ही II सही है"],"उपोत्पादों के आदान-प्रदान से कम अपशिष्ट का निपटान करना पड़ता है और वे नए कच्चे माल की जगह ले सकते हैं।"],"pa":["ਕਥਨਾਂ 'ਤੇ ਵਿਚਾਰ ਕਰੋ: I. ਉਦਯੋਗਿਕ ਸਹਿਜੀਵਤਾ ਰਹਿੰਦ-ਖੂੰਹਦ ਘਟਾ ਸਕਦੀ ਹੈ। II. ਇਹ ਪਹਿਲੀ ਵਾਰ ਕੱਢੇ ਕੱਚੇ ਮਾਲ ਦੀ ਮੰਗ ਵੀ ਘਟਾ ਸਕਦੀ ਹੈ। ਕਿਹੜਾ/ਕਿਹੜੇ ਕਥਨ ਸਹੀ ਹੈ/ਹਨ?",["ਸਿਰਫ਼ I ਸਹੀ ਹੈ","ਸਿਰਫ਼ II ਸਹੀ ਹੈ","I ਅਤੇ II ਦੋਵੇਂ ਸਹੀ ਹਨ","ਨਾ I ਅਤੇ ਨਾ ਹੀ II ਸਹੀ ਹੈ"],"ਉਪ-ਉਤਪਾਦਾਂ ਦੇ ਆਦਾਨ-ਪ੍ਰਦਾਨ ਨਾਲ ਘੱਟ ਰਹਿੰਦ-ਖੂੰਹਦ ਦਾ ਨਿਪਟਾਰਾ ਕਰਨਾ ਪੈਂਦਾ ਹੈ ਅਤੇ ਉਹ ਨਵੀਂ ਸਮੱਗਰੀ ਦੀ ਥਾਂ ਲੈ ਸਕਦੇ ਹਨ।"]},
"GEO-IND-001-CP011-Q046":{"h":"36514afc","hi":["औद्योगिक सहजीविता में कौन-सा युग्म सही सुमेलित है?",["वात्या भट्टी का धातुमल — कपास का रेशा","शीरा — इस्पात का अयस्क","जूट का अपशिष्ट — ऐलुमिनियम का अयस्क","वात्या भट्टी का धातुमल — सीमेंट की उत्पादन सामग्री"],"इस्पात संयंत्रों की वात्या भट्टियों का धातुमल सीमेंट विनिर्माण में पूरक सामग्री बन सकता है। इससे अपशिष्ट और पहली बार निकाले जाने वाले कच्चे माल की माँग घटती है।"],"pa":["ਉਦਯੋਗਿਕ ਸਹਿਜੀਵਤਾ ਵਿੱਚ ਕਿਹੜਾ ਜੋੜਾ ਸਹੀ ਮੇਲ ਖਾਂਦਾ ਹੈ?",["ਬਲਾਸਟ ਫਰਨੇਸ ਦੀ ਸਲੈਗ — ਕਪਾਹ ਦਾ ਰੇਸ਼ਾ","ਸ਼ੀਰਾ — ਸਟੀਲ ਦਾ ਅਯਸਕ","ਜੂਟ ਦੀ ਰਹਿੰਦ-ਖੂੰਹਦ — ਐਲੂਮੀਨੀਅਮ ਦਾ ਅਯਸਕ","ਬਲਾਸਟ ਫਰਨੇਸ ਦੀ ਸਲੈਗ — ਸੀਮਿੰਟ ਦੀ ਸਮੱਗਰੀ"],"ਸਟੀਲ ਪਲਾਂਟ ਦੀ ਬਲਾਸਟ ਫਰਨੇਸ ਦੀ ਸਲੈਗ ਸੀਮਿੰਟ ਬਣਾਉਣ ਵਿੱਚ ਪੂਰਕ ਸਮੱਗਰੀ ਵਜੋਂ ਵਰਤੀ ਜਾ ਸਕਦੀ ਹੈ। ਇਸ ਨਾਲ ਰਹਿੰਦ-ਖੂੰਹਦ ਅਤੇ ਪਹਿਲੀ ਵਾਰ ਕੱਢੇ ਕੱਚੇ ਮਾਲ ਦੀ ਮੰਗ ਘਟਦੀ ਹੈ।"]},
"GEO-IND-001-CP011-Q047":{"h":"707dde97","hi":["औद्योगिक संकुल सहजीविता को आसान क्यों बना सकते हैं?",["कंपनियाँ पास होने से सामग्री और सेवाओं का कुशल आदान-प्रदान कर सकती हैं","दूरी हमेशा दक्षता बढ़ाती है","संकुल सामग्री के आदान-प्रदान को रोकते हैं","परिवहन का कोई महत्व नहीं है"],"कम दूरी से जुड़े उद्योगों के बीच उपोत्पाद पहुँचाने का ख़र्च घटता है।"],"pa":["ਉਦਯੋਗਾਂ ਦੇ ਗੁੱਛ ਸਹਿਜੀਵਤਾ ਨੂੰ ਕਿਉਂ ਸੌਖਾ ਬਣਾ ਸਕਦੇ ਹਨ?",["ਕੰਪਨੀਆਂ ਨੇੜੇ ਹੋਣ ਕਰਕੇ ਸਮੱਗਰੀ ਅਤੇ ਸਹੂਲਤਾਂ ਦਾ ਸੁਚੱਜਾ ਆਦਾਨ-ਪ੍ਰਦਾਨ ਕਰ ਸਕਦੀਆਂ ਹਨ","ਦੂਰੀ ਹਮੇਸ਼ਾ ਕਾਰਗੁਜ਼ਾਰੀ ਵਧਾਉਂਦੀ ਹੈ","ਗੁੱਛ ਸਮੱਗਰੀ ਦਾ ਆਦਾਨ-ਪ੍ਰਦਾਨ ਰੋਕਦੇ ਹਨ","ਆਵਾਜਾਈ ਦਾ ਕੋਈ ਮਹੱਤਵ ਨਹੀਂ ਹੈ"],"ਦੂਰੀ ਘੱਟ ਹੋਣ ਨਾਲ ਜੁੜੇ ਉਦਯੋਗਾਂ ਵਿਚਕਾਰ ਉਪ-ਉਤਪਾਦਾਂ ਨੂੰ ਢੋਣ ਦਾ ਖ਼ਰਚ ਘਟਦਾ ਹੈ।"]},
"GEO-IND-001-CP011-Q048":{"h":"d56b1b76","hi":["एक इस्पात संयंत्र पास के सीमेंट संयंत्र को धातुमल भेजता है। इसका सबसे स्पष्ट अर्थ क्या है?",["औद्योगिक अलगाव","औद्योगिक सहजीविता","प्राथमिक कृषि","केवल संसाधन क्षय"],"एक संयंत्र का अपशिष्ट/उपोत्पाद दूसरे की उत्पादन सामग्री बन रहा है।"],"pa":["ਇੱਕ ਸਟੀਲ ਪਲਾਂਟ ਨੇੜਲੇ ਸੀਮਿੰਟ ਪਲਾਂਟ ਨੂੰ ਸਲੈਗ ਭੇਜਦਾ ਹੈ। ਇਸ ਦਾ ਸਭ ਤੋਂ ਸਪਸ਼ਟ ਅਰਥ ਕੀ ਹੈ?",["ਉਦਯੋਗਿਕ ਅਲੱਗ-ਥਲੱਗਤਾ","ਉਦਯੋਗਿਕ ਸਹਿਜੀਵਤਾ","ਮੁੱਢਲੀ ਖੇਤੀ","ਸਿਰਫ਼ ਸਰੋਤਾਂ ਦੀ ਘਾਟ"],"ਇੱਕ ਪਲਾਂਟ ਦੀ ਰਹਿੰਦ-ਖੂੰਹਦ/ਉਪ-ਉਤਪਾਦ ਦੂਜੇ ਪਲਾਂਟ ਲਈ ਸਮੱਗਰੀ ਵਜੋਂ ਵਰਤਿਆ ਜਾ ਰਿਹਾ ਹੈ।"]}};
